INSERT INTO `alembic_version` VALUES ('d2e3f4a5b6c7');
INSERT INTO `chunk` VALUES ('005891c2-b32a-4480-8393-00a52095eb75', 'b25ce095-dfba-4403-acf8-c58eb456ca4c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 39, '建设用地使用权自登记时设立。登记机构应当向建设用地使用权人发放权属证书。\n第三百五十条　建设用地使用权人应当合理利用土地，不得改变土地用途；需要改变土地用途的，应当依法经有关行政主管部门批准。\n第三百五十一条　建设用地使用权人应当依照法律规定以及合同约定支付出让金等费用。\n第三百五十二条　建设用地使用权人建造的建筑物、构筑物及其附属设施的所有权属于建设用地使用权人，但是有相反证据证明的除外。\n第三百五十三条　建设用地使用权人有权将建设用地使用权转让、互换、出资、赠与或者抵押，但是法律另有规定的除外。\n第三百五十四条　建设用地使用权转让、互换、出资、赠与或者抵押的，当事人应当采用书面形式订立相应的合同。使用期限由当事人约定，但是不得超过建设用地使用权的剩余期限。\n第三百五十五条　建设用地使用权转让、互换、出资或者赠与的，应当向登记机构申请变更登记。\n第三百五十六条　建设用地使用权转让、互换、出资或者赠与的，附着于该土地上的建筑物、构筑物及其附属设施一并处分。\n第三百五十七条　建筑物、构筑物及其附属设施转让、互换、出资或者赠与的，该建筑物、构筑物及其附属设施占用范围内的建设用地使用权一并处分。\n第三百五十八条　建设用地使用权期限届满前，因公共利益需要提前收回该土地的，应当依据本法第二百四十三条的规定对该土地上的房屋以及其他不动产给予补偿，并退还相应的出让金。\n第三百五十九条　住宅建设用地使用权期限届满的，自动续期。续期费用的缴纳或者减免，依照法律、行政法规的规定办理。\n非住宅建设用地使用权期限届满后的续期，依照法律规定办理。该土地上的房屋以及其他不动产的归属，有约定的，按照约定；没有约定或者约定不明确的，依照法律、行政法规的规定办理。\n第三百六十条　建设用地使用权消灭的，出让人应当及时办理注销登记。登记机构应当收回权属证书', 772, '{\"level\": null, \"title\": null, \"chunk_index\": 39}', 'bge-large-zh-v1.5', '2026-09-25 17:05:01');
INSERT INTO `chunk` VALUES ('01706323-d9bd-457c-b354-9e78c205d239', 'b25ce095-dfba-4403-acf8-c58eb456ca4c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 58, '逾期交付标的物的，遇价格上涨时，按照原价格执行；价格下降时，按照新价格执行。逾期提取标的物或者逾期付款的，遇价格上涨时，按照新价格执行；价格下降时，按照原价格执行。\n第五百一十四条　以支付金钱为内容的债，除法律另有规定或者当事人另有约定外，债权人可以请求债务人以实际履行地的法定货币履行。\n第五百一十五条　标的有多项而债务人只需履行其中一项的，债务人享有选择权；但是，法律另有规定、当事人另有约定或者另有交易习惯的除外。\n享有选择权的当事人在约定期限内或者履行期限届满未作选择，经催告后在合理期限内仍未选择的，选择权转移至对方。\n第五百一十六条　当事人行使选择权应当及时通知对方，通知到达对方时，标的确定。标的确定后不得变更，但是经对方同意的除外。\n可选择的标的发生不能履行情形的，享有选择权的当事人不得选择不能履行的标的，但是该不能履行的情形是由对方造成的除外。\n第五百一十七条　债权人为二人以上，标的可分，按照份额各自享有债权的，为按份债权；债务人为二人以上，标的可分，按照份额各自负担债务的，为按份债务。\n按份债权人或者按份债务人的份额难以确定的，视为份额相同。\n第五百一十八条　债权人为二人以上，部分或者全部债权人均可以请求债务人履行债务的，为连带债权；债务人为二人以上，债权人可以请求部分或者全部债务人履行全部债务的，为连带债务。\n连带债权或者连带债务，由法律规定或者当事人约定。\n第五百一十九条　连带债务人之间的份额难以确定的，视为份额相同。\n实际承担债务超过自己份额的连带债务人，有权就超出部分在其他连带债务人未履行的份额范围内向其追偿，并相应地享有债权人的权利，但是不得损害债权人的利益。其他连带债务人对债权人的抗辩，可以向该债务人主张。\n被追偿的连带债务人不能履行其应分担份额的，其他连带债务人应当在相应范围内按比例分担', 769, '{\"level\": null, \"title\": null, \"chunk_index\": 58}', 'bge-large-zh-v1.5', '2026-09-25 17:05:01');
INSERT INTO `chunk` VALUES ('04013cc1-ce67-4af7-9945-ab66cd2befc5', '821ce1fd-178d-4a7e-ab92-3deff1488ce2', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 52, '第四章　侵犯公民人身权利、民主权利罪\n第二百三十二条　故意杀人的，处死刑、无期徒刑或者十年以上有期徒刑；情节较轻的，处三年以上十年以下有期徒刑。\n第二百三十三条　过失致人死亡的，处三年以上七年以下有期徒刑；情节较轻的，处三年以下有期徒刑。本法另有规定的，依照规定。\n第二百三十四条　故意伤害他人身体的，处三年以下有期徒刑、拘役或者管制。\n犯前款罪，致人重伤的，处三年以上十年以下有期徒刑；致人死亡或者以特别残忍手段致人重伤造成严重残疾的，处十年以上有期徒刑、无期徒刑或者死刑。本法另有规定的，依照规定。\n第二百三十四条之一　组织他人出卖人体器官的，处五年以下有期徒刑，并处罚金；情节严重的，处五年以上有期徒刑，并处罚金或者没收财产。\n未经本人同意摘取其器官，或者摘取不满十八周岁的人的器官，或者强迫、欺骗他人捐献器官的，依照本法第二百三十四条、第二百三十二条的规定定罪处罚。\n违背本人生前意愿摘取其尸体器官，或者本人生前未表示同意，违反国家规定，违背其近亲属意愿摘取其尸体器官的，依照本法第三百零二条的规定定罪处罚。\n第二百三十五条　过失伤害他人致人重伤的，处三年以下有期徒刑或者拘役。本法另有规定的，依照规定。\n第二百三十六条　以暴力、胁迫或者其他手段强奸妇女的，处三年以上十年以下有期徒刑。\n奸淫不满十四周岁的幼女的，以强奸论，从重处罚。\n强奸妇女、奸淫幼女，有下列情形之一的，处十年以上有期徒刑、无期徒刑或者死刑：\n（一）强奸妇女、奸淫幼女情节恶劣的；\n（二）强奸妇女、奸淫幼女多人的；\n（三）在公共场所当众强奸妇女、奸淫幼女的；\n（四）二人以上轮奸的；\n（五）奸淫不满十周岁的幼女或者造成幼女伤害的；\n（六）致使被害人重伤、死亡或者造成其他严重后果的', 729, '{\"level\": null, \"title\": null, \"chunk_index\": 52}', 'bge-large-zh-v1.5', '2026-09-25 17:04:56');
INSERT INTO `chunk` VALUES ('04411925-1ccd-469e-8368-b8066a48736c', 'd9d7dc15-8041-43b8-9f75-f112fe3ae003', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 34, '\n第一百零九条　有下列情形之一的，由交通运输主管部门责令限期改正，处五万元以上五十万元以下的罚款；逾期不改正的，责令停产停业整顿，对其直接负责的主管人员和其他直接责任人员处一万元以上五万元以下的罚款：\n（一）危险化学品道路运输企业、水路运输企业的驾驶人员、船员、装卸管理人员、押运人员、申报人员、集装箱装箱现场检查员未取得从业资格上岗作业；\n（二）危险化学品的装卸作业未遵守安全作业标准、规程和制度，或者未在装卸管理人员的现场指挥或者监控下进行；\n（三）水路运输危险化学品的集装箱装箱作业未在集装箱装箱现场检查员的指挥或者监控下进行，或者不符合积载、隔离的规范和要求；\n（四）运输危险化学品，未根据危险化学品的危险特性采取相应的安全防护措施，或者未配备必要的防护用品和应急救援器材、装备、设备和物资；\n（五）危险化学品道路运输企业未对运输车辆、驾驶人员的作业状态进行实时监控、管理；\n（六）使用未依法取得危险货物适装证书的船舶，通过内河运输危险化学品；\n（七）通过内河运输危险化学品的承运人违反国务院交通运输主管部门对单船运输的危险化学品数量的限制性规定运输危险化学品；\n（八）用于危险化学品运输作业的内河码头、泊位不符合国家有关安全规范，未与饮用水取水口保持国家规定的安全距离，或者未按照国家有关规定验收合格投入使用；\n（九）托运人未向承运人提交电子或者纸质的危险货物托运清单说明所托运的危险化学品相关情况，未提供化学品安全技术说明书，或者未按照国家有关规定对所托运的危险化学品妥善包装并在危险化学品包装上粘贴、印刷、拴挂与包装内危险化学品相符的化学品安全标签；\n（十）运输危险化学品需要添加抑制剂或者稳定剂，托运人未按照规定添加或者未将有关情况告知承运人', 729, '{\"level\": null, \"title\": null, \"chunk_index\": 34}', 'bge-large-zh-v1.5', '2026-09-25 17:04:46');
INSERT INTO `chunk` VALUES ('053e776f-f91c-457a-8c63-f6ee93ddec71', '16cbea7e-7e36-4f31-afb5-63892345d29c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 50, '承办部门补充调查结束后，应当经审批将补证情况报告及相关证据材料，连同案卷材料一并移送案件审理部门；对确实无法查明的事项或者无法补充的证据，应当作出书面说明。重新调查终结后，应当重新形成调查报告，依法移送审理。\n重新调查完毕移送审理的，审理期限重新计算。补充调查期间不计入审理期限。\n第二百二十七条　审理工作结束后应当形成审理报告，载明被调查人基本情况、调查简况、涉嫌违法或者犯罪事实、被调查人态度和认识、涉案财物处置、承办部门意见、审理意见等内容，提请监察机关集体审议。\n对被调查人涉嫌职务犯罪需要追究刑事责任的，应当形成《起诉意见书》，作为审理报告附件。《起诉意见书》应当忠实于事实真象，载明被调查人基本情况，调查简况，采取监察强制措施的时间，依法查明的犯罪事实和证据，从重、从轻、减轻或者免除处罚等情节，涉案财物情况，涉嫌罪名和法律依据，采取刑事强制措施的建议，以及其他需要说明的情况。\n案件审理部门经审理认为现有证据不足以证明被调查人存在违法犯罪行为，且通过退回补充调查仍无法达到证明标准的，应当提出撤销案件的建议。\n第二百二十八条　上级监察机关办理下级监察机关管辖案件的，可以经审理后按程序直接进行处置，也可以经审理形成处置意见后，交由下级监察机关办理。\n第二百二十九条　被指定管辖的监察机关在调查结束后应当将案件移送审理，提请监察机关集体审议。\n上级监察机关将其所管辖的案件指定管辖的，被指定管辖的下级监察机关应当按照前款规定办理后，将案件报上级监察机关依法作出政务处分决定。上级监察机关在作出决定前，应当进行审理。\n上级监察机关将下级监察机关管辖的案件指定其他下级监察机关管辖的，被指定管辖的监察机关应当按照第一款规定办理后，将案件送交有管理权限的监察机关依法作出政务处分决定', 744, '{\"level\": null, \"title\": null, \"chunk_index\": 50}', 'bge-large-zh-v1.5', '2026-09-25 17:04:49');
INSERT INTO `chunk` VALUES ('053f4301-e646-43e0-bc09-ad59e5253720', '16cbea7e-7e36-4f31-afb5-63892345d29c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 42, '第一百九十条　监察机关接到公安机关抓获被通缉人员的通知后，应当立即核实被抓获人员身份，并在接到通知后二十四小时以内派员办理交接手续。边远或者交通不便地区，至迟不得超过三日。\n公安机关在移交前，将被抓获人员送往当地监察机关留置场所临时看管的，当地监察机关应当接收，并保障临时看管期间的安全，对工作信息严格保密。\n监察机关需要提请公安机关协助将被抓获人员带回的，应当按规定报批，请本地同级公安机关依法予以协助。提请协助时，应当出具《提请协助采取留置措施函》，附《留置决定书》复印件及相关材料。\n第一百九十一条　监察机关对于被通缉人员已经归案、死亡，或者依法撤销留置决定以及发现有其他不需要继续采取通缉措施情形的，应当经审批出具《撤销通缉通知书》，送交协助采取原措施的公安机关执行。需要撤销网上追逃措施的，监察机关应当出具《撤销网上追逃通知书》，送交协助采取原措施的公安机关执行。\n第十八节　限制出境\n第一百九十二条　监察机关为防止被调查人及相关人员逃匿境外，按规定报批后，可以依法决定采取限制出境措施，交由移民管理机构依法执行。\n第一百九十三条　监察机关采取限制出境措施应当出具有关函件，与采取限制出境措施决定书等文书材料一并送交移民管理机构执行。其中，采取边控措施的，应当附《边控对象通知书》；采取法定不批准出境措施的，应当附《法定不准出境人员报备表》。\n第一百九十四条　限制出境措施有效期不超过三个月，到期自动解除。\n到期后仍有必要继续采取边控措施的，应当按原程序报批。承办部门应当出具有关函件，在到期前与《延长限制出境措施期限决定书》一并送交移民管理机构执行。延长期限每次不得超过三个月。\n到期后仍有必要继续采取法定不批准出境措施的，应当在报备期满三日前按规定再次办理法定不批准出境人员报备手续', 748, '{\"level\": null, \"title\": null, \"chunk_index\": 42}', 'bge-large-zh-v1.5', '2026-09-25 17:04:49');
INSERT INTO `chunk` VALUES ('0562b72e-b6c5-4cda-bb66-1af7dfa61acf', '22a2c356-7a68-4455-b657-333e3dba1e1a', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 18, '第八十九条　国务院行使下列职权：\n（一）根据宪法和法律，规定行政措施，制定行政法规，发布决定和命令；\n（二）向全国人民代表大会或者全国人民代表大会常务委员会提出议案；\n（三）规定各部和各委员会的任务和职责，统一领导各部和各委员会的工作，并且领导不属于各部和各委员会的全国性的行政工作；\n（四）统一领导全国地方各级国家行政机关的工作，规定中央和省、自治区、直辖市的国家行政机关的职权的具体划分；\n（五）编制和执行国民经济和社会发展计划和国家预算；\n（六）领导和管理经济工作和城乡建设、生态文明建设；\n（七）领导和管理教育、科学、文化、卫生、体育和计划生育工作；\n（八）领导和管理民政、公安、司法行政等工作；\n（九）管理对外事务，同外国缔结条约和协定；\n（十）领导和管理国防建设事业；\n（十一）领导和管理民族事务，保障少数民族的平等权利和民族自治地方的自治权利；\n（十二）保护华侨的正当的权利和利益，保护归侨和侨眷的合法的权利和利益；\n（十三）改变或者撤销各部、各委员会发布的不适当的命令、指示和规章；\n（十四）改变或者撤销地方各级国家行政机关的不适当的决定和命令；\n（十五）批准省、自治区、直辖市的区域划分，批准自治州、县、自治县、市的建置和区域划分；\n（十六）依照法律规定决定省、自治区、直辖市的范围内部分地区进入紧急状态；\n（十七）审定行政机构的编制，依照法律规定任免、培训、考核和奖惩行政人员；\n（十八）全国人民代表大会和全国人民代表大会常务委员会授予的其他职权。\n第九十条　国务院各部部长、各委员会主任负责本部门的工作；召集和主持部务会议或者委员会会议、委务会议，讨论决定本部门工作的重大问题。\n各部、各委员会根据法律和国务院的行政法规、决定、命令，在本部门的权限内，发布命令、指示和规章', 747, '{\"level\": null, \"title\": null, \"chunk_index\": 18}', 'bge-large-zh-v1.5', '2026-09-25 17:04:29');
INSERT INTO `chunk` VALUES ('057d0009-efbf-4fa1-a7a5-cebead40c60c', 'b25ce095-dfba-4403-acf8-c58eb456ca4c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 99, '第八百七十一条　技术转让合同的受让人和技术许可合同的被许可人应当按照约定的范围和期限，对让与人、许可人提供的技术中尚未公开的秘密部分，承担保密义务。\n第八百七十二条　许可人未按照约定许可技术的，应当返还部分或者全部使用费，并应当承担违约责任；实施专利或者使用技术秘密超越约定的范围的，违反约定擅自许可第三人实施该项专利或者使用该项技术秘密的，应当停止违约行为，承担违约责任；违反约定的保密义务的，应当承担违约责任。\n让与人承担违约责任，参照适用前款规定。\n第八百七十三条　被许可人未按照约定支付使用费的，应当补交使用费并按照约定支付违约金；不补交使用费或者支付违约金的，应当停止实施专利或者使用技术秘密，交还技术资料，承担违约责任；实施专利或者使用技术秘密超越约定的范围的，未经许可人同意擅自许可第三人实施该专利或者使用该技术秘密的，应当停止违约行为，承担违约责任；违反约定的保密义务的，应当承担违约责任。\n受让人承担违约责任，参照适用前款规定。\n第八百七十四条　受让人或者被许可人按照约定实施专利、使用技术秘密侵害他人合法权益的，由让与人或者许可人承担责任，但是当事人另有约定的除外。\n第八百七十五条　当事人可以按照互利的原则，在合同中约定实施专利、使用技术秘密后续改进的技术成果的分享办法；没有约定或者约定不明确，依据本法第五百一十条的规定仍不能确定的，一方后续改进的技术成果，其他各方无权分享。\n第八百七十六条　集成电路布图设计专有权、植物新品种权、计算机软件著作权等其他知识产权的转让和许可，参照适用本节的有关规定。\n第八百七十七条　法律、行政法规对技术进出口合同或者专利、专利申请合同另有规定的，依照其规定。\n第四节　技术咨询合同和技术服务合同\n第八百七十八条　技术咨询合同是当事人一方以技术知识为对方就特定技术项目提供可行性论证、技术预测、专题技术调查、分析评价报告等所订立的合同', 796, '{\"level\": null, \"title\": null, \"chunk_index\": 99}', 'bge-large-zh-v1.5', '2026-09-25 17:05:01');
INSERT INTO `chunk` VALUES ('05c0454e-d852-4ae2-8eb8-5b7ee02546c8', 'b25ce095-dfba-4403-acf8-c58eb456ca4c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 80, '第七百零二条　债务人对债权人享有抵销权或者撤销权的，保证人可以在相应范围内拒绝承担保证责任。\n第十四章　租赁合同\n第七百零三条　租赁合同是出租人将租赁物交付承租人使用、收益，承租人支付租金的合同。\n第七百零四条　租赁合同的内容一般包括租赁物的名称、数量、用途、租赁期限、租金及其支付期限和方式、租赁物维修等条款。\n第七百零五条　租赁期限不得超过二十年。超过二十年的，超过部分无效。\n租赁期限届满，当事人可以续订租赁合同；但是，约定的租赁期限自续订之日起不得超过二十年。\n第七百零六条　当事人未依照法律、行政法规规定办理租赁合同登记备案手续的，不影响合同的效力。\n第七百零七条　租赁期限六个月以上的，应当采用书面形式。当事人未采用书面形式，无法确定租赁期限的，视为不定期租赁。\n第七百零八条　出租人应当按照约定将租赁物交付承租人，并在租赁期限内保持租赁物符合约定的用途。\n第七百零九条　承租人应当按照约定的方法使用租赁物。对租赁物的使用方法没有约定或者约定不明确，依据本法第五百一十条的规定仍不能确定的，应当根据租赁物的性质使用。\n第七百一十条　承租人按照约定的方法或者根据租赁物的性质使用租赁物，致使租赁物受到损耗的，不承担赔偿责任。\n第七百一十一条　承租人未按照约定的方法或者未根据租赁物的性质使用租赁物，致使租赁物受到损失的，出租人可以解除合同并请求赔偿损失。\n第七百一十二条　出租人应当履行租赁物的维修义务，但是当事人另有约定的除外。\n第七百一十三条　承租人在租赁物需要维修时可以请求出租人在合理期限内维修。出租人未履行维修义务的，承租人可以自行维修，维修费用由出租人负担。因维修租赁物影响承租人使用的，应当相应减少租金或者延长租期。\n因承租人的过错致使租赁物需要维修的，出租人不承担前款规定的维修义务', 754, '{\"level\": null, \"title\": null, \"chunk_index\": 80}', 'bge-large-zh-v1.5', '2026-09-25 17:05:01');
INSERT INTO `chunk` VALUES ('06b642f0-d899-4050-99c3-1422377f3f8d', 'd9d7dc15-8041-43b8-9f75-f112fe3ae003', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 24, '第九十四条　危险化学品单位发生直接危及人身安全的紧急情况时，在确保安全的前提下，作业现场带班人员、班组长、调度人员有权立即下达停产撤人命令，指挥有关遇险人员撤离。\n第九十五条　发生危险化学品事故，有关地方人民政府应当立即组织应急管理、生态环境、公安、卫生健康、交通运输等有关部门，按照本地区危险化学品事故应急预案组织实施救援，不得拖延、推诿。\n有关地方人民政府及其有关部门应当按照下列规定，采取必要的应急处置措施，减少事故损失，防止事故蔓延、扩大：\n（一）立即组织营救和救治受害人员，转移、疏散、撤离并妥善安置受到威胁的其他人员或者采取其他保护措施；\n（二）迅速控制危害源，测定危险化学品的性质，评估事故的危害区域及危害程度；\n（三）针对事故对人体、动植物、土壤、水源、水体、大气造成的现实危害和可能产生的危害，迅速采取封闭、隔离、洗消等措施；\n（四）对危险化学品事故造成的环境污染和生态破坏状况进行监测、评估，并采取相应的环境污染治理和生态修复措施。\n第九十六条　有关危险化学品单位应当为危险化学品事故应急救援提供技术指导和必要的协助。\n第九十七条　危险化学品事故造成环境污染和生态破坏的，由履行统一领导职责的人民政府统一发布有关信息。\n第九章　法律责任\n第九十八条　生产、使用、经营国家禁止生产、使用、经营的危险化学品的，由应急管理部门责令停止生产、使用、经营活动，有违法所得的，没收违法所得，并没收违法生产、使用、经营的危险化学品以及用于违法生产、使用、经营的工具、设备、原料等；违法生产、使用、经营的危险化学品货值金额不足十万元的，并处三十万元以上五十万元以下的罚款；货值金额十万元以上的，并处货值金额五倍以上十倍以下的罚款。\n有前款规定行为的，应急管理部门还应当责令其对所生产、使用、经营的危险化学品进行无害化处理', 762, '{\"level\": null, \"title\": null, \"chunk_index\": 24}', 'bge-large-zh-v1.5', '2026-09-25 17:04:46');
INSERT INTO `chunk` VALUES ('072d0d6b-c2f7-4294-8a77-a95fbed52f4a', '821ce1fd-178d-4a7e-ab92-3deff1488ce2', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 58, '第二百六十一条　对于年老、年幼、患病或者其他没有独立生活能力的人，负有扶养义务而拒绝扶养，情节恶劣的，处五年以下有期徒刑、拘役或者管制。\n第二百六十二条　拐骗不满十四周岁的未成年人，脱离家庭或者监护人的，处五年以下有期徒刑或者拘役。\n第二百六十二条之一　以暴力、胁迫手段组织残疾人或者不满十四周岁的未成年人乞讨的，处三年以下有期徒刑或者拘役，并处罚金；情节严重的，处三年以上七年以下有期徒刑，并处罚金。\n第二百六十二条之二　组织未成年人进行盗窃、诈骗、抢夺、敲诈勒索等违反治安管理活动的，处三年以下有期徒刑或者拘役，并处罚金；情节严重的，处三年以上七年以下有期徒刑，并处罚金。\n第五章　侵犯财产罪\n第二百六十三条　以暴力、胁迫或者其他方法抢劫公私财物的，处三年以上十年以下有期徒刑，并处罚金；有下列情形之一的，处十年以上有期徒刑、无期徒刑或者死刑，并处罚金或者没收财产：\n（一）入户抢劫的；\n（二）在公共交通工具上抢劫的；\n（三）抢劫银行或者其他金融机构的；\n（四）多次抢劫或者抢劫数额巨大的；\n（五）抢劫致人重伤、死亡的；\n（六）冒充军警人员抢劫的；\n（七）持枪抢劫的；\n（八）抢劫军用物资或者抢险、救灾、救济物资的。\n第二百六十四条　盗窃公私财物，数额较大的，或者多次盗窃、入户盗窃、携带凶器盗窃、扒窃的，处三年以下有期徒刑、拘役或者管制，并处或者单处罚金；数额巨大或者有其他严重情节的，处三年以上十年以下有期徒刑，并处罚金；数额特别巨大或者有其他特别严重情节的，处十年以上有期徒刑或者无期徒刑，并处罚金或者没收财产。\n第二百六十五条　以牟利为目的，盗接他人通信线路、复制他人电信码号或者明知是盗接、复制的电信设备、设施而使用的，依照本法第二百六十四条的规定定罪处罚', 735, '{\"level\": null, \"title\": null, \"chunk_index\": 58}', 'bge-large-zh-v1.5', '2026-09-25 17:04:56');
INSERT INTO `chunk` VALUES ('07bf974a-3949-4a50-8b3d-2e28b3cb6f58', 'b25ce095-dfba-4403-acf8-c58eb456ca4c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 1, '同\n第十章　供用电、水、气、热力合同\n第十一章　赠与合同\n第十二章　借款合同\n第十三章　保证合同\n第一节　一般规定\n第二节　保证责任\n第十四章　租赁合同\n第十五章　融资租赁合同\n第十六章　保理合同\n第十七章　承揽合同\n第十八章　建设工程合同\n第十九章　运输合同\n第一节　一般规定\n第二节　客运合同\n第三节　货运合同\n第四节　多式联运合同\n第二十章　技术合同\n第一节　一般规定\n第二节　技术开发合同\n第三节　技术转让合同和技术许可合同\n第四节　技术咨询合同和技术服务合同\n第二十一章　保管合同\n第二十二章　仓储合同\n第二十三章　委托合同\n第二十四章　物业服务合同\n第二十五章　行纪合同\n第二十六章　中介合同\n第二十七章　合伙合同\n第三分编　准合同\n第二十八章　无因管理\n第二十九章　不当得利\n第四编　人格权\n第一章　一般规定\n第二章　生命权、身体权和健康权\n第三章　姓名权和名称权\n第四章　肖像权\n第五章　名誉权和荣誉权\n第六章　隐私权和个人信息保护\n第五编　婚姻家庭\n第一章　一般规定\n第二章　结　　婚\n第三章　家庭关系\n第一节　夫妻关系\n第二节　父母子女关系和其他近亲属关系\n第四章　离　　婚\n第五章　收　　养\n第一节　收养关系的成立\n第二节　收养的效力\n第三节　收养关系的解除\n第六编　继　　承\n第一章　一般规定\n第二章　法定继承\n第三章　遗嘱继承和遗赠\n第四章　遗产的处理\n第七编　侵权责任\n第一章　一般规定\n第二章　损害赔偿\n第三章　责任主体的特殊规定\n第四章　产品责任\n第五章　机动车交通事故责任\n第六章　医疗损害责任\n第七章　环境污染和生态破坏责任\n第八章　高度危险责任\n第九章　饲养动物损害责任\n第十章　建筑物和物件损害责任\n附　　则\n第一编　总　　则\n第一章　基本规定\n第一条　为了保护民事主体的合法权益，调整民事关系，维护社会和经济秩序，适应中国特色社会主义发展要求，弘扬社会主义核', 800, '{\"level\": null, \"title\": null, \"chunk_index\": 1}', 'bge-large-zh-v1.5', '2026-09-25 17:05:01');
INSERT INTO `chunk` VALUES ('0848c96d-50b6-433e-827e-705d39b445d6', '16cbea7e-7e36-4f31-afb5-63892345d29c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 14, '第六十五条　县级以上监察机关需要提请公安机关协助采取强制到案、责令候查、管护、留置、搜查措施的，应当按规定报批，请同级公安机关依法予以协助。提请协助时，应当出具提请协助函，列明提请协助的具体事项和建议，协助采取措施的时间、地点等内容，附采取监察措施决定书复印件。\n因保密需要，不宜在采取监察措施前向公安机关告知采取措施对象姓名的，可以作出说明，进行保密处理。\n需要提请异地公安机关协助采取监察措施的，应当按规定报批，向协作地同级监察机关出具协作函件和相关文书，由协作地监察机关提请当地公安机关依法予以协助。\n第二节　证　　据\n第六十六条　可以用于证明案件事实的材料都是证据，包括：\n（一）物证；\n（二）书证；\n（三）证人证言；\n（四）被害人陈述；\n（五）被调查人陈述、供述和辩解；\n（六）鉴定意见；\n（七）勘验检查、辨认、调查实验等笔录；\n（八）视听资料、电子数据。\n监察机关向有关单位和个人收集、调取证据时，应当告知其必须依法如实提供证据。对于不按要求提供有关材料，泄露相关信息，伪造、隐匿、毁灭证据，提供虚假情况或者阻止他人提供证据的，依法追究法律责任。\n监察机关依照监察法和本条例规定收集的证据材料，经审查符合法定要求的，在刑事诉讼中可以作为证据使用。\n第六十七条　监察机关认定案件事实应当以证据为根据，全面、客观地收集、固定被调查人有无违法犯罪以及情节轻重的各种证据，形成相互印证、完整稳定的证据链。\n只有被调查人陈述或者供述，没有其他证据的，不能认定案件事实；没有被调查人陈述或者供述，证据符合法定标准的，可以认定案件事实。\n第六十八条　证据必须经过查证属实，才能作为定案的根据。审查认定证据，应当结合案件的具体情况，从证据与待证事实的关联程度、各证据之间的联系、是否依照法定程序收集等方面进行综合判断。\n第六十九条　监察机关调查终结的职务违法案件，应当事实清楚、证据确凿', 791, '{\"level\": null, \"title\": null, \"chunk_index\": 14}', 'bge-large-zh-v1.5', '2026-09-25 17:04:49');
INSERT INTO `chunk` VALUES ('094a50d4-9a99-4142-b652-517d28325da0', '821ce1fd-178d-4a7e-ab92-3deff1488ce2', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 66, '第二百九十一条　聚众扰乱车站、码头、民用航空站、商场、公园、影剧院、展览会、运动场或者其他公共场所秩序，聚众堵塞交通或者破坏交通秩序，抗拒、阻碍国家治安管理工作人员依法执行职务，情节严重的，对首要分子，处五年以下有期徒刑、拘役或者管制。\n第二百九十一条之一　投放虚假的爆炸性、毒害性、放射性、传染病病原体等物质，或者编造爆炸威胁、生化威胁、放射威胁等恐怖信息，或者明知是编造的恐怖信息而故意传播，严重扰乱社会秩序的，处五年以下有期徒刑、拘役或者管制；造成严重后果的，处五年以上有期徒刑。\n编造虚假的险情、疫情、灾情、警情，在信息网络或者其他媒体上传播，或者明知是上述虚假信息，故意在信息网络或者其他媒体上传播，严重扰乱社会秩序的，处三年以下有期徒刑、拘役或者管制；造成严重后果的，处三年以上七年以下有期徒刑。\n第二百九十一条之二　从建筑物或者其他高空抛掷物品，情节严重的，处一年以下有期徒刑、拘役或者管制，并处或者单处罚金。\n有前款行为，同时构成其他犯罪的，依照处罚较重的规定定罪处罚。\n第二百九十二条　聚众斗殴的，对首要分子和其他积极参加的，处三年以下有期徒刑、拘役或者管制；有下列情形之一的，对首要分子和其他积极参加的，处三年以上十年以下有期徒刑：\n（一）多次聚众斗殴的；\n（二）聚众斗殴人数多，规模大，社会影响恶劣的；\n（三）在公共场所或者交通要道聚众斗殴，造成社会秩序严重混乱的；\n（四）持械聚众斗殴的。\n聚众斗殴，致人重伤、死亡的，依照本法第二百三十四条、第二百三十二条的规定定罪处罚。\n第二百九十三条　有下列寻衅滋事行为之一，破坏社会秩序的，处五年以下有期徒刑、拘役或者管制：\n（一）随意殴打他人，情节恶劣的；\n（二）追逐、拦截、辱骂、恐吓他人，情节恶劣的；\n（三）强拿硬要或者任意损毁、占用公私财物，情节严重的；\n（四）在公共场所起哄闹事，造成公共场所秩序严重混乱的', 790, '{\"level\": null, \"title\": null, \"chunk_index\": 66}', 'bge-large-zh-v1.5', '2026-09-25 17:04:56');
INSERT INTO `chunk` VALUES ('09db71a2-7cb7-4096-be0e-ce5905d566e3', 'b25ce095-dfba-4403-acf8-c58eb456ca4c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 112, '管理人管理事务取得的财产，应当及时转交给受益人。\n第九百八十四条　管理人管理事务经受益人事后追认的，从管理事务开始时起，适用委托合同的有关规定，但是管理人另有意思表示的除外。\n第二十九章　不当得利\n第九百八十五条　得利人没有法律根据取得不当利益的，受损失的人可以请求得利人返还取得的利益，但是有下列情形之一的除外：\n（一）为履行道德义务进行的给付；\n（二）债务到期之前的清偿；\n（三）明知无给付义务而进行的债务清偿。\n第九百八十六条　得利人不知道且不应当知道取得的利益没有法律根据，取得的利益已经不存在的，不承担返还该利益的义务。\n第九百八十七条　得利人知道或者应当知道取得的利益没有法律根据的，受损失的人可以请求得利人返还其取得的利益并依法赔偿损失。\n第九百八十八条　得利人已经将取得的利益无偿转让给第三人的，受损失的人可以请求第三人在相应范围内承担返还义务。\n第四编　人格权\n第一章　一般规定\n第九百八十九条　本编调整因人格权的享有和保护产生的民事关系。\n第九百九十条　人格权是民事主体享有的生命权、身体权、健康权、姓名权、名称权、肖像权、名誉权、荣誉权、隐私权等权利。\n除前款规定的人格权外，自然人享有基于人身自由、人格尊严产生的其他人格权益。\n第九百九十一条　民事主体的人格权受法律保护，任何组织或者个人不得侵害。\n第九百九十二条　人格权不得放弃、转让或者继承。\n第九百九十三条　民事主体可以将自己的姓名、名称、肖像等许可他人使用，但是依照法律规定或者根据其性质不得许可的除外。\n第九百九十四条　死者的姓名、肖像、名誉、荣誉、隐私、遗体等受到侵害的，其配偶、子女、父母有权依法请求行为人承担民事责任；死者没有配偶、子女且父母已经死亡的，其他近亲属有权依法请求行为人承担民事责任。\n第九百九十五条　人格权受到侵害的，受害人有权依照本法和其他法律的规定请求行为人承担民事责任', 789, '{\"level\": null, \"title\": null, \"chunk_index\": 112}', 'bge-large-zh-v1.5', '2026-09-25 17:05:01');
INSERT INTO `chunk` VALUES ('0a7d15e8-a42e-4aa8-a3d2-3d28778fd551', 'b25ce095-dfba-4403-acf8-c58eb456ca4c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 110, '因中介人提供订立合同的媒介服务而促成合同成立的，由该合同的当事人平均负担中介人的报酬。\n中介人促成合同成立的，中介活动的费用，由中介人负担。\n第九百六十四条　中介人未促成合同成立的，不得请求支付报酬；但是，可以按照约定请求委托人支付从事中介活动支出的必要费用。\n第九百六十五条　委托人在接受中介人的服务后，利用中介人提供的交易机会或者媒介服务，绕开中介人直接订立合同的，应当向中介人支付报酬。\n第九百六十六条　本章没有规定的，参照适用委托合同的有关规定。\n第二十七章　合伙合同\n第九百六十七条　合伙合同是两个以上合伙人为了共同的事业目的，订立的共享利益、共担风险的协议。\n第九百六十八条　合伙人应当按照约定的出资方式、数额和缴付期限，履行出资义务。\n第九百六十九条　合伙人的出资、因合伙事务依法取得的收益和其他财产，属于合伙财产。\n合伙合同终止前，合伙人不得请求分割合伙财产。\n第九百七十条　合伙人就合伙事务作出决定的，除合伙合同另有约定外，应当经全体合伙人一致同意。\n合伙事务由全体合伙人共同执行。按照合伙合同的约定或者全体合伙人的决定，可以委托一个或者数个合伙人执行合伙事务；其他合伙人不再执行合伙事务，但是有权监督执行情况。\n合伙人分别执行合伙事务的，执行事务合伙人可以对其他合伙人执行的事务提出异议；提出异议后，其他合伙人应当暂停该项事务的执行。\n第九百七十一条　合伙人不得因执行合伙事务而请求支付报酬，但是合伙合同另有约定的除外。\n第九百七十二条　合伙的利润分配和亏损分担，按照合伙合同的约定办理；合伙合同没有约定或者约定不明确的，由合伙人协商决定；协商不成的，由合伙人按照实缴出资比例分配、分担；无法确定出资比例的，由合伙人平均分配、分担。\n第九百七十三条　合伙人对合伙债务承担连带责任。清偿合伙债务超过自己应当承担份额的合伙人，有权向其他合伙人追偿', 781, '{\"level\": null, \"title\": null, \"chunk_index\": 110}', 'bge-large-zh-v1.5', '2026-09-25 17:05:01');
INSERT INTO `chunk` VALUES ('0a92ee1d-783b-4b8c-88bc-4ec6847f6834', 'b25ce095-dfba-4403-acf8-c58eb456ca4c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 106, '第九百三十五条　因委托人死亡或者被宣告破产、解散，致使委托合同终止将损害委托人利益的，在委托人的继承人、遗产管理人或者清算人承受委托事务之前，受托人应当继续处理委托事务。\n第九百三十六条　因受托人死亡、丧失民事行为能力或者被宣告破产、解散，致使委托合同终止的，受托人的继承人、遗产管理人、法定代理人或者清算人应当及时通知委托人。因委托合同终止将损害委托人利益的，在委托人作出善后处理之前，受托人的继承人、遗产管理人、法定代理人或者清算人应当采取必要措施。\n第二十四章　物业服务合同\n第九百三十七条　物业服务合同是物业服务人在物业服务区域内，为业主提供建筑物及其附属设施的维修养护、环境卫生和相关秩序的管理维护等物业服务，业主支付物业费的合同。\n物业服务人包括物业服务企业和其他管理人。\n第九百三十八条　物业服务合同的内容一般包括服务事项、服务质量、服务费用的标准和收取办法、维修资金的使用、服务用房的管理和使用、服务期限、服务交接等条款。\n物业服务人公开作出的有利于业主的服务承诺，为物业服务合同的组成部分。\n物业服务合同应当采用书面形式。\n第九百三十九条　建设单位依法与物业服务人订立的前期物业服务合同，以及业主委员会与业主大会依法选聘的物业服务人订立的物业服务合同，对业主具有法律约束力。\n第九百四十条　建设单位依法与物业服务人订立的前期物业服务合同约定的服务期限届满前，业主委员会或者业主与新物业服务人订立的物业服务合同生效的，前期物业服务合同终止。\n第九百四十一条　物业服务人将物业服务区域内的部分专项服务事项委托给专业性服务组织或者其他第三人的，应当就该部分专项服务事项向业主负责。\n物业服务人不得将其应当提供的全部物业服务转委托给第三人，或者将全部物业服务支解后分别转委托给第三人', 746, '{\"level\": null, \"title\": null, \"chunk_index\": 106}', 'bge-large-zh-v1.5', '2026-09-25 17:05:01');
INSERT INTO `chunk` VALUES ('0ae72884-29d2-4201-8e1e-6f489d059c56', '16cbea7e-7e36-4f31-afb5-63892345d29c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 9, '第四十六条　下列人员属于监察法第十五条第六项所称其他依法履行公职的人员：\n（一）履行人民代表大会职责的各级人民代表大会代表，履行公职的中国人民政治协商会议各级委员会委员、人民陪审员、人民监督员；\n（二）虽未列入党政机关人员编制，但在党政机关中从事公务的人员；\n（三）在集体经济组织等单位、组织中，由党组织或者国家机关，国有独资、全资公司、企业，国家出资企业中负有管理监督国有和集体资产职责的组织，事业单位提名、推荐、任命、批准等，从事组织、领导、管理、监督等工作的人员；\n（四）在依法组建的评标、谈判、询价等组织中代表国家机关，国有独资、全资公司、企业，事业单位，人民团体临时履行公共事务组织、领导、管理、监督等职责的人员；\n（五）其他依法行使公权力的人员。\n第四十七条　有关机关、单位、组织集体作出的决定违法或者实施违法行为的，监察机关应当对负有责任的领导人员和直接责任人员中的公职人员依法追究法律责任。\n第二节　管　　辖\n第四十八条　监察机关开展监督、调查、处置，按照管理权限与属地管辖相结合的原则，实行分级负责制。\n第四十九条　设区的市级以上监察委员会按照管理权限，依法管辖同级党委管理的公职人员涉嫌职务违法和职务犯罪案件。\n县级监察委员会和直辖市所辖区（县）监察委员会按照管理权限，依法管辖本辖区内公职人员涉嫌职务违法和职务犯罪案件。\n地方各级监察委员会按照本条例第十三条、第五十二条规定，可以依法管辖工作单位在本辖区内的有关公职人员涉嫌职务违法和职务犯罪案件。\n监察机关调查公职人员涉嫌职务犯罪案件，可以依法对涉嫌行贿犯罪、介绍贿赂犯罪或者共同职务犯罪的涉案人员中的非公职人员一并管辖并进行调查处置。非公职人员涉嫌利用影响力受贿罪的，监察机关按照其所利用的公职人员的管理权限确定管辖并进行调查处置', 753, '{\"level\": null, \"title\": null, \"chunk_index\": 9}', 'bge-large-zh-v1.5', '2026-09-25 17:04:49');
INSERT INTO `chunk` VALUES ('0b505473-3952-4888-9d5f-ee80ce6082fb', '821ce1fd-178d-4a7e-ab92-3deff1488ce2', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 63, '第二百八十三条　非法生产、销售专用间谍器材或者窃听、窃照专用器材的，处三年以下有期徒刑、拘役或者管制，并处或者单处罚金；情节严重的，处三年以上七年以下有期徒刑，并处罚金。\n单位犯前款罪的，对单位判处罚金，并对其直接负责的主管人员和其他直接责任人员，依照前款的规定处罚。\n第二百八十四条　非法使用窃听、窃照专用器材，造成严重后果的，处二年以下有期徒刑、拘役或者管制。\n第二百八十四条之一　在法律规定的国家考试中，组织作弊的，处三年以下有期徒刑或者拘役，并处或者单处罚金；情节严重的，处三年以上七年以下有期徒刑，并处罚金。\n为他人实施前款犯罪提供作弊器材或者其他帮助的，依照前款的规定处罚。\n为实施考试作弊行为，向他人非法出售或者提供第一款规定的考试的试题、答案的，依照第一款的规定处罚。\n代替他人或者让他人代替自己参加第一款规定的考试的，处拘役或者管制，并处或者单处罚金。\n第二百八十五条　违反国家规定，侵入国家事务、国防建设、尖端科学技术领域的计算机信息系统的，处三年以下有期徒刑或者拘役。\n违反国家规定，侵入前款规定以外的计算机信息系统或者采用其他技术手段，获取该计算机信息系统中存储、处理或者传输的数据，或者对该计算机信息系统实施非法控制，情节严重的，处三年以下有期徒刑或者拘役，并处或者单处罚金；情节特别严重的，处三年以上七年以下有期徒刑，并处罚金。\n提供专门用于侵入、非法控制计算机信息系统的程序、工具，或者明知他人实施侵入、非法控制计算机信息系统的违法犯罪行为而为其提供程序、工具，情节严重的，依照前款的规定处罚。\n单位犯前三款罪的，对单位判处罚金，并对其直接负责的主管人员和其他直接责任人员，依照各该款的规定处罚', 712, '{\"level\": null, \"title\": null, \"chunk_index\": 63}', 'bge-large-zh-v1.5', '2026-09-25 17:04:56');
INSERT INTO `chunk` VALUES ('0b65c2db-3302-486e-905c-2377b086cc68', '16cbea7e-7e36-4f31-afb5-63892345d29c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 48, '第二百一十九条　调查组对被调查人涉嫌职务犯罪拟依法移送人民检察院审查起诉的，应当起草《起诉建议书》。《起诉建议书》应当载明被调查人基本情况，调查简况，认罪认罚情况，采取监察强制措施的时间，涉嫌职务犯罪事实以及证据，对被调查人从重、从轻、减轻或者免除处罚等情节，提出对被调查人移送起诉的理由和法律依据，采取刑事强制措施的建议，并注明移送案卷数及涉案财物等内容。\n调查组应当形成被调查人到案经过及量刑情节方面的材料，包括案件来源、到案经过，自动投案、如实供述、立功等量刑情节，认罪悔罪态度、退赃、避免和减少损害结果发生等方面的情况说明及相关材料。被检举揭发的问题已被立案、查破，被检举揭发人已被采取调查措施或者刑事强制措施、起诉或者审判的，还应当附有关法律文书。\n第二百二十条　经调查认为被调查人构成职务违法或者职务犯罪的，应当区分不同情况提出相应处理意见，经审批将调查报告、职务违法或者职务犯罪事实材料、涉案财物报告、涉案人员处理意见等材料，连同全部证据和文书手续移送审理。\n对涉嫌职务犯罪的案件材料应当按照刑事诉讼要求单独立卷，与《起诉建议书》、涉案财物报告、同步录音录像资料及其自查报告等材料一并移送审理。\n调查全过程形成的材料应当案结卷成、事毕归档。\n第四节　审　　理\n第二百二十一条　案件审理部门收到移送审理的案件后，应当审核材料是否齐全、手续是否完备。对被调查人涉嫌职务犯罪的，还应当审核相关案卷材料是否符合职务犯罪案件立卷要求，是否在调查报告中单独表述已查明的涉嫌犯罪问题，是否形成《起诉建议书》。\n经审核符合移送条件的，应当予以受理；不符合移送条件的，经审批可以暂缓受理或者不予受理，并要求承办部门补充完善材料。\n第二百二十二条　案件审理部门受理案件后，应当成立由二人以上组成的审理组，全面审理案卷材料', 757, '{\"level\": null, \"title\": null, \"chunk_index\": 48}', 'bge-large-zh-v1.5', '2026-09-25 17:04:49');
INSERT INTO `chunk` VALUES ('0bb433d6-0ee3-42c5-b0b1-c17fae67057f', 'b25ce095-dfba-4403-acf8-c58eb456ca4c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 121, '第一千零五十七条　夫妻双方都有参加生产、工作、学习和社会活动的自由，一方不得对另一方加以限制或者干涉。\n第一千零五十八条　夫妻双方平等享有对未成年子女抚养、教育和保护的权利，共同承担对未成年子女抚养、教育和保护的义务。\n第一千零五十九条　夫妻有相互扶养的义务。\n需要扶养的一方，在另一方不履行扶养义务时，有要求其给付扶养费的权利。\n第一千零六十条　夫妻一方因家庭日常生活需要而实施的民事法律行为，对夫妻双方发生效力，但是夫妻一方与相对人另有约定的除外。\n夫妻之间对一方可以实施的民事法律行为范围的限制，不得对抗善意相对人。\n第一千零六十一条　夫妻有相互继承遗产的权利。\n第一千零六十二条　夫妻在婚姻关系存续期间所得的下列财产，为夫妻的共同财产，归夫妻共同所有：\n（一）工资、奖金、劳务报酬；\n（二）生产、经营、投资的收益；\n（三）知识产权的收益；\n（四）继承或者受赠的财产，但是本法第一千零六十三条第三项规定的除外；\n（五）其他应当归共同所有的财产。\n夫妻对共同财产，有平等的处理权。\n第一千零六十三条　下列财产为夫妻一方的个人财产：\n（一）一方的婚前财产；\n（二）一方因受到人身损害获得的赔偿或者补偿；\n（三）遗嘱或者赠与合同中确定只归一方的财产；\n（四）一方专用的生活用品；\n（五）其他应当归一方的财产。\n第一千零六十四条　夫妻双方共同签名或者夫妻一方事后追认等共同意思表示所负的债务，以及夫妻一方在婚姻关系存续期间以个人名义为家庭日常生活需要所负的债务，属于夫妻共同债务。\n夫妻一方在婚姻关系存续期间以个人名义超出家庭日常生活需要所负的债务，不属于夫妻共同债务；但是，债权人能够证明该债务用于夫妻共同生活、共同生产经营或者基于夫妻双方共同意思表示的除外。\n第一千零六十五条　男女双方可以约定婚姻关系存续期间所得的财产以及婚前财产归各自所有、共同所有或者部分各自所有、部分共同所有', 792, '{\"level\": null, \"title\": null, \"chunk_index\": 121}', 'bge-large-zh-v1.5', '2026-09-25 17:05:01');
INSERT INTO `chunk` VALUES ('0c700f94-91e1-4e0a-a3e1-03d2d57cd9d7', 'd9d7dc15-8041-43b8-9f75-f112fe3ae003', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 39, '化学品的危险特性尚未确定的，任何单位和个人不得擅自从事该化学品的生产、储存、使用、经营、运输等活动。\n第一百二十五条　港区内危险化学品生产和使用危险化学品的生产装置及相连储罐部分，由应急管理部门负责安全监督管理；仅与危险化学品码头相连的储罐部分，由港口行政管理部门负责安全监督管理。\n第一百二十六条　中国人民解放军、中国人民武装警察部队的危险化学品安全管理，依照本法有关规定和中央军事委员会的规定执行。\n第一百二十七条　本法自2026年5月1日起施行。', 226, '{\"level\": null, \"title\": null, \"chunk_index\": 39}', 'bge-large-zh-v1.5', '2026-09-25 17:04:46');
INSERT INTO `chunk` VALUES ('0f05b088-215f-4d2f-89ef-efd6f84a8b13', '821ce1fd-178d-4a7e-ab92-3deff1488ce2', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 28, '第三节　妨害对公司、企业的管理秩序罪\n第一百五十八条　申请公司登记使用虚假证明文件或者采取其他欺诈手段虚报注册资本，欺骗公司登记主管部门，取得公司登记，虚报注册资本数额巨大、后果严重或者有其他严重情节的，处三年以下有期徒刑或者拘役，并处或者单处虚报注册资本金额百分之一以上百分之五以下罚金。\n单位犯前款罪的，对单位判处罚金，并对其直接负责的主管人员和其他直接责任人员，处三年以下有期徒刑或者拘役。\n第一百五十九条　公司发起人、股东违反公司法的规定未交付货币、实物或者未转移财产权，虚假出资，或者在公司成立后又抽逃其出资，数额巨大、后果严重或者有其他严重情节的，处五年以下有期徒刑或者拘役，并处或者单处虚假出资金额或者抽逃出资金额百分之二以上百分之十以下罚金。\n单位犯前款罪的，对单位判处罚金，并对其直接负责的主管人员和其他直接责任人员，处五年以下有期徒刑或者拘役。\n第一百六十条　在招股说明书、认股书、公司、企业债券募集办法等发行文件中隐瞒重要事实或者编造重大虚假内容，发行股票或者公司、企业债券、存托凭证或者国务院依法认定的其他证券，数额巨大、后果严重或者有其他严重情节的，处五年以下有期徒刑或者拘役，并处或者单处罚金；数额特别巨大、后果特别严重或者有其他特别严重情节的，处五年以上有期徒刑，并处罚金。\n控股股东、实际控制人组织、指使实施前款行为的，处五年以下有期徒刑或者拘役，并处或者单处非法募集资金金额百分之二十以上一倍以下罚金；数额特别巨大、后果特别严重或者有其他特别严重情节的，处五年以上有期徒刑，并处非法募集资金金额百分之二十以上一倍以下罚金。\n单位犯前两款罪的，对单位判处非法募集资金金额百分之二十以上一倍以下罚金，并对其直接负责的主管人员和其他直接责任人员，依照第一款的规定处罚', 747, '{\"level\": null, \"title\": null, \"chunk_index\": 28}', 'bge-large-zh-v1.5', '2026-09-25 17:04:56');
INSERT INTO `chunk` VALUES ('0f4a35b9-67a6-445a-8b5b-690ab2c60e75', 'd9d7dc15-8041-43b8-9f75-f112fe3ae003', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 25, '违反国家关于危险化学品使用的限制性规定使用危险化学品的，依照本条第一款的规定处理、处罚。\n第九十九条　有下列情形之一的，由负有危险化学品安全监督管理职责的部门按照职责分工责令停止建设或者停产停业整顿，限期改正，并处十万元以上五十万元以下的罚款，对其直接负责的主管人员和其他直接责任人员处二万元以上五万元以下的罚款；逾期未改正的，处五十万元以上一百万元以下的罚款，对其直接负责的主管人员和其他直接责任人员处五万元以上十万元以下的罚款：\n（一）危险化学品建设项目未经安全条件审查；\n（二）危险化学品建设项目没有安全设施设计或者安全设施设计未报有关应急管理部门审查同意；\n（三）施工单位未按照批准的安全设施设计施工；\n（四）实行工程监理的危险化学品建设项目，建设单位未对安全设施施工一并委托监理；\n（五）危险化学品建设项目竣工投入生产或者使用前，安全设施未经验收合格。\n危险化学品港口建设项目有前款规定情形的，由港口行政管理部门依照前款规定予以处理、处罚。\n第一百条　未依法取得危险化学品安全生产许可证从事危险化学品生产，或者未依法取得工业产品生产许可证从事危险化学品及其包装物、容器生产的，分别依照有关安全生产许可、工业产品生产许可法律、行政法规的规定处理、处罚。\n违反本法规定，化工企业未取得危险化学品安全使用许可证，使用危险化学品从事生产的，由应急管理部门责令限期改正，处十万元以上五十万元以下的罚款；逾期不改正的，责令停产整顿。\n违反本法规定，未取得危险化学品经营许可证从事危险化学品经营的，由应急管理部门责令停止经营活动，没收违法经营的危险化学品以及违法所得，并处十万元以上五十万元以下的罚款', 698, '{\"level\": null, \"title\": null, \"chunk_index\": 25}', 'bge-large-zh-v1.5', '2026-09-25 17:04:46');
INSERT INTO `chunk` VALUES ('0f77cdce-3468-452f-9001-8ad62a2007be', '0497a5e7-7044-4b18-8fed-af3fb7bc7890', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 3, '增值税法第二十二条第三项所称非正常损失项目，包括：\n（一）非正常损失的购进货物，以及与之相关的加工修理修配服务和交通运输服务；\n（二）非正常损失的在产品、产成品所耗用的购进货物（不包括固定资产）、加工修理修配服务和交通运输服务；\n（三）非正常损失的不动产，以及该不动产所耗用的购进货物和建筑服务；\n（四）非正常损失的不动产在建工程所耗用的购进货物和建筑服务。不动产在建工程包括纳税人新建、改建、扩建、修缮、装饰不动产。\n本条第二款第三项、第四项所称货物，是指构成不动产实体的材料和设备，包括建筑装饰材料和给排水、采暖、卫生、通风、照明、通讯、燃气、消防、中央空调、电梯、电气、光伏发电、智能化楼宇设备及配套设施等。\n本条例所称固定资产，是指使用期限超过12个月的机器、机械、运输工具以及其他与生产经营相关的设备、工具、器具等。\n第二十条　纳税人的交际应酬消费属于增值税法所称个人消费。\n第二十一条　纳税人购进贷款服务的利息支出，及其向贷款方支付的与该贷款服务直接相关的投融资顾问费、手续费、咨询费等费用支出，对应的进项税额暂不得从销项税额中抵扣。\n国务院财政、税务主管部门应当适时研究和评估购进贷款服务利息及相关费用支出对应的进项税额不得从销项税额中抵扣政策执行效果。\n第二十二条　纳税人购进货物、服务、无形资产、不动产，用于同时符合下列情形的非应税交易（以下统称不得抵扣非应税交易），对应的进项税额不得从销项税额中抵扣：\n（一）发生增值税法第三条至第五条以外的经营活动，并取得与之相关的货币或者非货币形式的经济利益；\n（二）不属于增值税法第六条规定的情形', 678, '{\"level\": null, \"title\": null, \"chunk_index\": 3}', 'bge-large-zh-v1.5', '2026-09-25 17:04:28');
INSERT INTO `chunk` VALUES ('0ff27d30-c184-43b3-b1e4-9c6d79183de0', 'b25ce095-dfba-4403-acf8-c58eb456ca4c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 9, '农村承包经营户的债务，以从事农村土地承包经营的农户财产承担；事实上由农户部分成员经营的，以该部分成员的财产承担。\n第三章　法　　人\n第一节　一般规定\n第五十七条　法人是具有民事权利能力和民事行为能力，依法独立享有民事权利和承担民事义务的组织。\n第五十八条　法人应当依法成立。\n法人应当有自己的名称、组织机构、住所、财产或者经费。法人成立的具体条件和程序，依照法律、行政法规的规定。\n设立法人，法律、行政法规规定须经有关机关批准的，依照其规定。\n第五十九条　法人的民事权利能力和民事行为能力，从法人成立时产生，到法人终止时消灭。\n第六十条　法人以其全部财产独立承担民事责任。\n第六十一条　依照法律或者法人章程的规定，代表法人从事民事活动的负责人，为法人的法定代表人。\n法定代表人以法人名义从事的民事活动，其法律后果由法人承受。\n法人章程或者法人权力机构对法定代表人代表权的限制，不得对抗善意相对人。\n第六十二条　法定代表人因执行职务造成他人损害的，由法人承担民事责任。\n法人承担民事责任后，依照法律或者法人章程的规定，可以向有过错的法定代表人追偿。\n第六十三条　法人以其主要办事机构所在地为住所。依法需要办理法人登记的，应当将主要办事机构所在地登记为住所。\n第六十四条　法人存续期间登记事项发生变化的，应当依法向登记机关申请变更登记。\n第六十五条　法人的实际情况与登记的事项不一致的，不得对抗善意相对人。\n第六十六条　登记机关应当依法及时公示法人登记的有关信息。\n第六十七条　法人合并的，其权利和义务由合并后的法人享有和承担。\n法人分立的，其权利和义务由分立后的法人享有连带债权，承担连带债务，但是债权人和债务人另有约定的除外。\n第六十八条　有下列原因之一并依法完成清算、注销登记的，法人终止：\n（一）法人解散；\n（二）法人被宣告破产；\n（三）法律规定的其他原因', 780, '{\"level\": null, \"title\": null, \"chunk_index\": 9}', 'bge-large-zh-v1.5', '2026-09-25 17:05:01');
INSERT INTO `chunk` VALUES ('11437d3a-5ad2-4969-823a-d748fd63fd1d', '821ce1fd-178d-4a7e-ab92-3deff1488ce2', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 70, '有第一款行为，非法占有他人财产或者逃避合法债务，又构成其他犯罪的，依照处罚较重的规定定罪从重处罚。\n司法工作人员利用职权，与他人共同实施前三款行为的，从重处罚；同时构成其他犯罪的，依照处罚较重的规定定罪从重处罚。\n第三百零八条　对证人进行打击报复的，处三年以下有期徒刑或者拘役；情节严重的，处三年以上七年以下有期徒刑。\n第三百零八条之一　司法工作人员、辩护人、诉讼代理人或者其他诉讼参与人，泄露依法不公开审理的案件中不应当公开的信息，造成信息公开传播或者其他严重后果的，处三年以下有期徒刑、拘役或者管制，并处或者单处罚金。\n有前款行为，泄露国家秘密的，依照本法第三百九十八条的规定定罪处罚。\n公开披露、报道第一款规定的案件信息，情节严重的，依照第一款的规定处罚。\n单位犯前款罪的，对单位判处罚金，并对其直接负责的主管人员和其他直接责任人员，依照第一款的规定处罚。\n第三百零九条　有下列扰乱法庭秩序情形之一的，处三年以下有期徒刑、拘役、管制或者罚金：\n（一）聚众哄闹、冲击法庭的；\n（二）殴打司法工作人员或者诉讼参与人的；\n（三）侮辱、诽谤、威胁司法工作人员或者诉讼参与人，不听法庭制止，严重扰乱法庭秩序的；\n（四）有毁坏法庭设施，抢夺、损毁诉讼文书、证据等扰乱法庭秩序行为，情节严重的。\n第三百一十条　明知是犯罪的人而为其提供隐藏处所、财物，帮助其逃匿或者作假证明包庇的，处三年以下有期徒刑、拘役或者管制；情节严重的，处三年以上十年以下有期徒刑。\n犯前款罪，事前通谋的，以共同犯罪论处。\n第三百一十一条　明知他人有间谍犯罪或者恐怖主义、极端主义犯罪行为，在司法机关向其调查有关情况、收集有关证据时，拒绝提供，情节严重的，处三年以下有期徒刑、拘役或者管制', 726, '{\"level\": null, \"title\": null, \"chunk_index\": 70}', 'bge-large-zh-v1.5', '2026-09-25 17:04:56');
INSERT INTO `chunk` VALUES ('1287ebe0-07ac-44ea-8d80-a595e348d9cf', '16cbea7e-7e36-4f31-afb5-63892345d29c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 22, '第一百零二条　监察机关在强制到案期限内未作出采取其他监察强制措施决定的，强制到案期满，应当立即结束强制到案。\n第七节　责令候查\n第一百零三条　监察机关调查严重职务违法或者职务犯罪，对于符合监察法第二十三条第一款规定的，经依法审批，可以对被调查人采取责令候查措施。\n第一百零四条　采取责令候查措施时，调查人员不得少于二人，应当向被责令候查人员宣布《责令候查决定书》，出示《被责令候查人员权利义务告知书》，由被责令候查人员签名、捺指印，要求其遵守监察法第二十三条第二款的规定，告知其违反规定应负的法律责任。被责令候查人员拒绝签名、捺指印的，调查人员应当在文书上记明。\n监察机关将其他监察强制措施变更为责令候查措施的，应当按照前款规定履行权利义务告知程序。\n责令候查最长不得超过十二个月，自向被责令候查人员宣布之日起算。\n第一百零五条　除无法通知的以外，监察机关应当在采取责令候查措施后二十四小时以内，通知被责令候查人员所在单位和家属。当面通知的，由有关人员在《责令候查通知书》上签名。无法当面通知的，可以先以电话等方式通知，并通过邮寄、转交等方式送达《责令候查通知书》，要求有关人员在《责令候查通知书》上签名。有关人员拒绝签名的，调查人员应当在文书上记明。\n第一百零六条　责令候查应当由决定采取责令候查措施的监察机关执行。\n执行责令候查的监察机关应当履行下列职责：\n（一）监督、考察被责令候查人员遵守有关规定，及时掌握其活动、住址、工作单位、联系方式及变动情况；\n（二）审批被责令候查人员离开所居住的直辖市、设区的市的城市市区或者不设区的市、县的辖区（以下统称所居住的市、县）的申请；\n（三）被责令候查人员违反应当遵守的规定的，及时制止或者纠正；\n（四）会同被责令候查人员所在单位、家属等对被责令候查人员开展思想教育、心理疏导工作。\n第一百零七条　被责令候查人员未经批准不得离开所居住的市、县', 794, '{\"level\": null, \"title\": null, \"chunk_index\": 22}', 'bge-large-zh-v1.5', '2026-09-25 17:04:49');
INSERT INTO `chunk` VALUES ('13a20795-cd55-42f4-8005-882fb8ebd776', 'd9d7dc15-8041-43b8-9f75-f112fe3ae003', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 18, '运输危险化学品，驾驶人员、船员、装卸管理人员、押运人员、申报人员、集装箱装箱现场检查员应当熟悉所运输的危险化学品的危险特性及其包装物、容器的使用要求，掌握出现危险情况时的应急处置方法。\n第六十八条　通过道路运输危险化学品，应当按照运输车辆的核定载质量装载危险化学品，不得超载。\n危险化学品运输车辆应当符合国家标准要求的安全技术条件，并按照国家有关规定定期进行安全技术检验。\n危险化学品运输车辆应当悬挂或者喷涂符合国家标准要求的警示标志，不得遮挡、拆除。\n危险化学品运输车辆应当安装符合国家标准、行业标准要求的卫星定位监控装置并确保处于良好运行状态，不得拆除、关闭或者采取屏蔽信号等方式影响其正常运行，不得删除、篡改监控数据。\n第六十九条　通过道路运输危险化学品，应当按照要求配备押运人员，并保证所运输的危险化学品处于押运人员的监控之下。具体办法由国务院交通运输主管部门会同有关部门制定。\n危险化学品道路运输企业应当对运输车辆、驾驶人员的作业状态进行实时监控、管理，及时纠正超速行驶、疲劳驾驶、不按规定线路行驶等违法违规驾驶行为，实现安全监测、监控和预警。运输危险化学品车辆的驾驶人员应当严格遵守道路交通安全法律法规，日间连续驾驶时间不得超过四小时，夜间连续驾驶时间不得超过二小时，每次停车休息时间不少于二十分钟。\n运输危险化学品途中需要停车的，驾驶人员、押运人员应当采取相应的安全防范措施；运输剧毒化学品或者易制爆危险化学品因住宿或者发生影响正常运输的情况，需要较长时间停车的，还应当向当地公安机关报告。\n第七十条　未经公安机关批准，运输危险化学品的车辆不得进入危险化学品运输车辆限制通行的区域。危险化学品运输车辆限制通行的区域由县级人民政府公安机关划定或者会同有关部门划定，并设置明显的标志。\n运输危险化学品的车辆进入危险化学品运输车辆限制通行区域许可管理按照国务院公安部门的规定执行', 793, '{\"level\": null, \"title\": null, \"chunk_index\": 18}', 'bge-large-zh-v1.5', '2026-09-25 17:04:46');
INSERT INTO `chunk` VALUES ('13d1a4e6-2632-4405-b6f7-b487cbe44712', '821ce1fd-178d-4a7e-ab92-3deff1488ce2', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 97, '第四百三十九条　非法出卖、转让军队武器装备的，处三年以上十年以下有期徒刑；出卖、转让大量武器装备或者有其他特别严重情节的，处十年以上有期徒刑、无期徒刑或者死刑。\n第四百四十条　违抗命令，遗弃武器装备的，处五年以下有期徒刑或者拘役；遗弃重要或者大量武器装备的，或者有其他严重情节的，处五年以上有期徒刑。\n第四百四十一条　遗失武器装备，不及时报告或者有其他严重情节的，处三年以下有期徒刑或者拘役。\n第四百四十二条　违反规定，擅自出卖、转让军队房地产，情节严重的，对直接责任人员，处三年以下有期徒刑或者拘役；情节特别严重的，处三年以上十年以下有期徒刑。\n第四百四十三条　滥用职权，虐待部属，情节恶劣，致人重伤或者造成其他严重后果的，处五年以下有期徒刑或者拘役；致人死亡的，处五年以上有期徒刑。\n第四百四十四条　在战场上故意遗弃伤病军人，情节恶劣的，对直接责任人员，处五年以下有期徒刑。\n第四百四十五条　战时在救护治疗职位上，有条件救治而拒不救治危重伤病军人的，处五年以下有期徒刑或者拘役；造成伤病军人重残、死亡或者有其他严重情节的，处五年以上十年以下有期徒刑。\n第四百四十六条　战时在军事行动地区，残害无辜居民或者掠夺无辜居民财物的，处五年以下有期徒刑；情节严重的，处五年以上十年以下有期徒刑；情节特别严重的，处十年以上有期徒刑、无期徒刑或者死刑。\n第四百四十七条　私放俘虏的，处五年以下有期徒刑；私放重要俘虏、私放俘虏多人或者有其他严重情节的，处五年以上有期徒刑。\n第四百四十八条　虐待俘虏，情节恶劣的，处三年以下有期徒刑。\n第四百四十九条　在战时，对被判处三年以下有期徒刑没有现实危险宣告缓刑的犯罪军人，允许其戴罪立功，确有立功表现时，可以撤销原判刑罚，不以犯罪论处', 732, '{\"level\": null, \"title\": null, \"chunk_index\": 97}', 'bge-large-zh-v1.5', '2026-09-25 17:04:56');
INSERT INTO `chunk` VALUES ('1475e2b3-3e3d-4d36-aac7-19c2be6c464b', '16cbea7e-7e36-4f31-afb5-63892345d29c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 0, '中华人民共和国监察法实施条例\n（2021年7月20日国家监察委员会全体会议决定　2021年9月20日国家监察委员会公告第1号公布　2025年4月27日国家监察委员会全体会议修订　2025年6月1日国家监察委员会公告第2号公布）\n目　　录\n第一章　总　　则\n第二章　监察机关及其职责\n第三章　监察范围和管辖\n第四章　监察权限\n第五章　监察程序\n第六章　反腐败国际合作\n第七章　对监察机关和监察人员的监督\n第八章　法律责任\n第九章　附　　则\n第一章　总　　则\n第一条　为了推动监察工作法治化、规范化，保障依法公正行使监察权，根据《中华人民共和国监察法》（以下简称监察法），结合工作实际，制定本条例。\n第二条　坚持中国共产党对监察工作的全面领导，增强政治意识、大局意识、核心意识、看齐意识，坚定中国特色社会主义道路自信、理论自信、制度自信、文化自信，坚决维护习近平总书记党中央的核心、全党的核心地位，坚决维护以习近平同志为核心的党中央权威和集中统一领导，把党的领导贯彻到监察工作各方面和全过程。\n第三条　监察机关与党的纪律检查机关合署办公，坚持法治思维和法治方式，促进执纪执法贯通、有效衔接司法，实现依纪监督和依法监察、适用纪律和适用法律有机融合。\n第四条　监察机关应当依法履行监督、调查、处置职责，坚持实事求是，坚持惩前毖后、治病救人，坚持惩戒与教育相结合，实现政治效果、法律效果和社会效果相统一。\n第五条　监察机关应当坚定不移惩治腐败，推动深化改革、完善制度，规范权力运行，加强新时代廉洁文化建设，引导公职人员提高觉悟、担当作为、依法履职，一体推进不敢腐、不能腐、不想腐，着力铲除腐败滋生的土壤和条件。\n第六条　监察机关坚持民主集中制，对于线索处置、立案调查、案件审理、处置执行、复审复核中的重要事项应当集体研究，严格按照权限履行请示报告程序', 770, '{\"level\": null, \"title\": null, \"chunk_index\": 0}', 'bge-large-zh-v1.5', '2026-09-25 17:04:49');
INSERT INTO `chunk` VALUES ('15513d97-9c5f-4194-8737-720572d5ec6d', '16cbea7e-7e36-4f31-afb5-63892345d29c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 7, '第三十七条　监察机关在追究违法的公职人员直接责任的同时，依法对履行职责不力、失职失责，造成严重后果或者恶劣影响的领导人员予以问责。\n监察机关应当组成调查组依法开展问责调查。调查结束后经集体讨论形成调查报告，需要进行问责的按照管理权限作出问责决定，或者向有权作出问责决定的机关、单位书面提出问责建议。\n第三十八条　监察机关对涉嫌职务犯罪的人员，经调查认为犯罪事实清楚，证据确实、充分，需要追究刑事责任的，依法移送人民检察院审查起诉。\n第三十九条　监察机关根据监督、调查结果，发现监察对象所在单位具有下列情形之一，需要整改纠正的，依法提出监察建议，推动以案促改工作：\n（一）廉政建设方面存在突出问题的；\n（二）权力运行制约监督方面存在较大风险的；\n（三）监察对象教育管理监督方面存在突出问题的；\n（四）执行法律法规制度不到位的；\n（五）不履行或者不正确履行法定职责的；\n（六）其他需要提出监察建议的情形。\n监察机关应当跟踪了解监察建议的采纳情况，指导、督促有关单位限期整改，对未达到整改要求的提出进一步整改意见，推动监察建议落实到位。\n第三章　监察范围和管辖\n第一节　监察对象\n第四十条　监察机关依法对所有行使公权力的公职人员进行监察，实现国家监察全面覆盖。\n第四十一条　监察法第十五条第一项所称公务员范围，依据《中华人民共和国公务员法》（以下简称公务员法）确定。\n监察法第十五条第一项所称参照公务员法管理的人员，是指有关单位中经批准参照公务员法进行管理的工作人员。\n第四十二条　监察法第十五条第二项所称法律、法规授权或者受国家机关依法委托管理公共事务的组织中从事公务的人员，是指在上述组织中，除参照公务员法管理的人员外，对公共事务履行组织、领导、管理、监督等职责的人员，包括具有公共事务管理职能的行业协会等组织中从事公务的人员，以及法定检验检测、检疫等机构中从事公务的人员', 785, '{\"level\": null, \"title\": null, \"chunk_index\": 7}', 'bge-large-zh-v1.5', '2026-09-25 17:04:49');
INSERT INTO `chunk` VALUES ('15959824-e7b5-43a4-aadb-16df1656a5cb', 'b25ce095-dfba-4403-acf8-c58eb456ca4c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 133, '继承人放弃继承的，对被继承人依法应当缴纳的税款和债务可以不负清偿责任。\n第一千一百六十二条　执行遗赠不得妨碍清偿遗赠人依法应当缴纳的税款和债务。\n第一千一百六十三条　既有法定继承又有遗嘱继承、遗赠的，由法定继承人清偿被继承人依法应当缴纳的税款和债务；超过法定继承遗产实际价值部分，由遗嘱继承人和受遗赠人按比例以所得遗产清偿。\n第七编　侵权责任\n第一章　一般规定\n第一千一百六十四条　本编调整因侵害民事权益产生的民事关系。\n第一千一百六十五条　行为人因过错侵害他人民事权益造成损害的，应当承担侵权责任。\n依照法律规定推定行为人有过错，其不能证明自己没有过错的，应当承担侵权责任。\n第一千一百六十六条　行为人造成他人民事权益损害，不论行为人有无过错，法律规定应当承担侵权责任的，依照其规定。\n第一千一百六十七条　侵权行为危及他人人身、财产安全的，被侵权人有权请求侵权人承担停止侵害、排除妨碍、消除危险等侵权责任。\n第一千一百六十八条　二人以上共同实施侵权行为，造成他人损害的，应当承担连带责任。\n第一千一百六十九条　教唆、帮助他人实施侵权行为的，应当与行为人承担连带责任。\n教唆、帮助无民事行为能力人、限制民事行为能力人实施侵权行为的，应当承担侵权责任；该无民事行为能力人、限制民事行为能力人的监护人未尽到监护职责的，应当承担相应的责任。\n第一千一百七十条　二人以上实施危及他人人身、财产安全的行为，其中一人或者数人的行为造成他人损害，能够确定具体侵权人的，由侵权人承担责任；不能确定具体侵权人的，行为人承担连带责任。\n第一千一百七十一条　二人以上分别实施侵权行为造成同一损害，每个人的侵权行为都足以造成全部损害的，行为人承担连带责任。\n第一千一百七十二条　二人以上分别实施侵权行为造成同一损害，能够确定责任大小的，各自承担相应的责任；难以确定责任大小的，平均承担责任', 782, '{\"level\": null, \"title\": null, \"chunk_index\": 133}', 'bge-large-zh-v1.5', '2026-09-25 17:05:01');
INSERT INTO `chunk` VALUES ('1783c45d-786f-41da-85fa-aa64da5e7285', '0497a5e7-7044-4b18-8fed-af3fb7bc7890', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 6, '小规模纳税人符合增值税法第九条第二款规定的，可以向主管税务机关办理一般纳税人登记，并自办理登记的当期起按照一般计税方法计算缴纳增值税。\n纳税人登记为一般纳税人后，不得转为小规模纳税人。\n第三十七条　纳税人发生应税交易，应当向购买方开具发票。有下列情形之一的，不得开具增值税专用发票：\n（一）应税交易的购买方为自然人；\n（二）应税交易免征增值税；\n（三）国务院财政、税务主管部门规定的其他情形。\n第三十八条　纳税人发生应税交易，开具增值税专用发票后，发生开票有误或者销售折让、中止、退回等情形的，应当按照国务院税务主管部门的规定进行作废处理或者开具红字增值税专用发票；未按规定进行作废处理或者开具红字增值税专用发票的，不得依照本条例第十三条和第十四条的规定扣减销项税额或者销售额。\n第三十九条　增值税法第二十八条第一款第一项所称收讫销售款项，是指纳税人发生应税交易过程中或者完成后收到款项；取得销售款项索取凭据的当日，是指书面合同确定的付款日期，未签订书面合同或者书面合同未确定付款日期的，是指应税交易完成的当日，即货物发出、服务完成、金融商品所有权转移、无形资产转让完成或者不动产转让完成的当日。\n第四十条　增值税法第二十八条第一款第二项所称完成视同应税交易的当日，是指货物发出、金融商品所有权转移、无形资产转让完成或者不动产转让完成的当日。\n第四十一条　纳税人出口货物，报关出口日期早于增值税法第二十八条第一款第一项、第二项规定的纳税义务发生时间的，纳税义务发生时间为货物报关出口的当日', 644, '{\"level\": null, \"title\": null, \"chunk_index\": 6}', 'bge-large-zh-v1.5', '2026-09-25 17:04:28');
INSERT INTO `chunk` VALUES ('17bb644d-eed2-46ad-b6a0-60fd9fbfcdcd', 'b25ce095-dfba-4403-acf8-c58eb456ca4c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 136, '完全民事行为能力人因醉酒、滥用麻醉药品或者精神药品对自己的行为暂时没有意识或者失去控制造成他人损害的，应当承担侵权责任。\n第一千一百九十一条　用人单位的工作人员因执行工作任务造成他人损害的，由用人单位承担侵权责任。用人单位承担侵权责任后，可以向有故意或者重大过失的工作人员追偿。\n劳务派遣期间，被派遣的工作人员因执行工作任务造成他人损害的，由接受劳务派遣的用工单位承担侵权责任；劳务派遣单位有过错的，承担相应的责任。\n第一千一百九十二条　个人之间形成劳务关系，提供劳务一方因劳务造成他人损害的，由接受劳务一方承担侵权责任。接受劳务一方承担侵权责任后，可以向有故意或者重大过失的提供劳务一方追偿。提供劳务一方因劳务受到损害的，根据双方各自的过错承担相应的责任。\n提供劳务期间，因第三人的行为造成提供劳务一方损害的，提供劳务一方有权请求第三人承担侵权责任，也有权请求接受劳务一方给予补偿。接受劳务一方补偿后，可以向第三人追偿。\n第一千一百九十三条　承揽人在完成工作过程中造成第三人损害或者自己损害的，定作人不承担侵权责任。但是，定作人对定作、指示或者选任有过错的，应当承担相应的责任。\n第一千一百九十四条　网络用户、网络服务提供者利用网络侵害他人民事权益的，应当承担侵权责任。法律另有规定的，依照其规定。\n第一千一百九十五条　网络用户利用网络服务实施侵权行为的，权利人有权通知网络服务提供者采取删除、屏蔽、断开链接等必要措施。通知应当包括构成侵权的初步证据及权利人的真实身份信息。\n网络服务提供者接到通知后，应当及时将该通知转送相关网络用户，并根据构成侵权的初步证据和服务类型采取必要措施；未及时采取必要措施的，对损害的扩大部分与该网络用户承担连带责任。\n权利人因错误通知造成网络用户或者网络服务提供者损害的，应当承担侵权责任。法律另有规定的，依照其规定', 775, '{\"level\": null, \"title\": null, \"chunk_index\": 136}', 'bge-large-zh-v1.5', '2026-09-25 17:05:01');
INSERT INTO `chunk` VALUES ('19254aff-8a5d-48a8-99bb-909e90e58991', 'b25ce095-dfba-4403-acf8-c58eb456ca4c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 109, '行纪人高于委托人指定的价格卖出或者低于委托人指定的价格买入的，可以按照约定增加报酬；没有约定或者约定不明确，依据本法第五百一十条的规定仍不能确定的，该利益属于委托人。\n委托人对价格有特别指示的，行纪人不得违背该指示卖出或者买入。\n第九百五十六条　行纪人卖出或者买入具有市场定价的商品，除委托人有相反的意思表示外，行纪人自己可以作为买受人或者出卖人。\n行纪人有前款规定情形的，仍然可以请求委托人支付报酬。\n第九百五十七条　行纪人按照约定买入委托物，委托人应当及时受领。经行纪人催告，委托人无正当理由拒绝受领的，行纪人依法可以提存委托物。\n委托物不能卖出或者委托人撤回出卖，经行纪人催告，委托人不取回或者不处分该物的，行纪人依法可以提存委托物。\n第九百五十八条　行纪人与第三人订立合同的，行纪人对该合同直接享有权利、承担义务。\n第三人不履行义务致使委托人受到损害的，行纪人应当承担赔偿责任，但是行纪人与委托人另有约定的除外。\n第九百五十九条　行纪人完成或者部分完成委托事务的，委托人应当向其支付相应的报酬。委托人逾期不支付报酬的，行纪人对委托物享有留置权，但是当事人另有约定的除外。\n第九百六十条　本章没有规定的，参照适用委托合同的有关规定。\n第二十六章　中介合同\n第九百六十一条　中介合同是中介人向委托人报告订立合同的机会或者提供订立合同的媒介服务，委托人支付报酬的合同。\n第九百六十二条　中介人应当就有关订立合同的事项向委托人如实报告。\n中介人故意隐瞒与订立合同有关的重要事实或者提供虚假情况，损害委托人利益的，不得请求支付报酬并应当承担赔偿责任。\n第九百六十三条　中介人促成合同成立的，委托人应当按照约定支付报酬。对中介人的报酬没有约定或者约定不明确，依据本法第五百一十条的规定仍不能确定的，根据中介人的劳务合理确定', 759, '{\"level\": null, \"title\": null, \"chunk_index\": 109}', 'bge-large-zh-v1.5', '2026-09-25 17:05:01');
INSERT INTO `chunk` VALUES ('1a4594d7-f614-4928-9f64-180dddcbea77', '16cbea7e-7e36-4f31-afb5-63892345d29c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 30, '案件依法移送人民检察院审查起诉的，留置措施自犯罪嫌疑人被执行拘留时自动解除，不再办理解除法律手续。\n第十节　查询、冻结\n第一百三十五条　监察机关调查严重职务违法或者职务犯罪，根据工作需要，按规定报批后，可以依法查询、冻结涉案单位和个人的存款、汇款、债券、股票、基金份额等财产。\n第一百三十六条　查询、冻结财产时，调查人员不得少于二人。调查人员应当出具《协助查询财产通知书》或者《协助冻结财产通知书》，送交银行或者其他金融机构、邮政部门等单位执行。有关单位和个人应当予以配合，并严格保密。\n查询财产应当在《协助查询财产通知书》中填写查询账号、查询内容等信息。没有具体账号的，应当填写足以确定账户或者权利人的自然人姓名、身份证件号码或者市场主体名称、统一社会信用代码等信息。\n冻结财产应当在《协助冻结财产通知书》中填写冻结账户名称、冻结账号、冻结数额、冻结期限起止时间等信息。冻结数额应当具体、明确，暂时无法确定具体数额的，应当在《协助冻结财产通知书》上明确写明“只收不付”。冻结证券和交易结算资金时，应当明确冻结的范围是否及于孳息。\n冻结财产，应当为被调查人及其所扶养的亲属保留必需的生活费用。\n第一百三十七条　调查人员可以根据需要对查询结果进行打印、抄录、复制、拍照，要求相关单位在有关材料上加盖证明印章。对查询结果有疑问的，可以要求相关单位进行书面解释并加盖印章。\n第一百三十八条　监察机关对查询信息应当加强管理，规范信息交接、调阅、使用程序和手续，防止滥用和泄露。\n调查人员不得查询与案件调查工作无关的信息。\n第一百三十九条　冻结财产的期限不得超过六个月。冻结期限到期未办理续冻手续的，冻结自动解除。\n有特殊原因需要延长冻结期限的，应当在到期前按原程序报批，办理续冻手续。每次续冻期限不得超过六个月。\n第一百四十条　已被冻结的财产可以轮候冻结，不得重复冻结', 780, '{\"level\": null, \"title\": null, \"chunk_index\": 30}', 'bge-large-zh-v1.5', '2026-09-25 17:04:49');
INSERT INTO `chunk` VALUES ('1b54514e-125d-49e6-a536-06d29624bcda', 'b25ce095-dfba-4403-acf8-c58eb456ca4c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 35, '偿还债务超过自己应当承担份额的按份共有人，有权向其他共有人追偿。\n第三百零八条　共有人对共有的不动产或者动产没有约定为按份共有或者共同共有，或者约定不明确的，除共有人具有家庭关系等外，视为按份共有。\n第三百零九条　按份共有人对共有的不动产或者动产享有的份额，没有约定或者约定不明确的，按照出资额确定；不能确定出资额的，视为等额享有。\n第三百一十条　两个以上组织、个人共同享有用益物权、担保物权的，参照适用本章的有关规定。\n第九章　所有权取得的特别规定\n第三百一十一条　无处分权人将不动产或者动产转让给受让人的，所有权人有权追回；除法律另有规定外，符合下列情形的，受让人取得该不动产或者动产的所有权：\n（一）受让人受让该不动产或者动产时是善意；\n（二）以合理的价格转让；\n（三）转让的不动产或者动产依照法律规定应当登记的已经登记，不需要登记的已经交付给受让人。\n受让人依据前款规定取得不动产或者动产的所有权的，原所有权人有权向无处分权人请求损害赔偿。\n当事人善意取得其他物权的，参照适用前两款规定。\n第三百一十二条　所有权人或者其他权利人有权追回遗失物。该遗失物通过转让被他人占有的，权利人有权向无处分权人请求损害赔偿，或者自知道或者应当知道受让人之日起二年内向受让人请求返还原物；但是，受让人通过拍卖或者向具有经营资格的经营者购得该遗失物的，权利人请求返还原物时应当支付受让人所付的费用。权利人向受让人支付所付费用后，有权向无处分权人追偿。\n第三百一十三条　善意受让人取得动产后，该动产上的原有权利消灭。但是，善意受让人在受让时知道或者应当知道该权利的除外。\n第三百一十四条　拾得遗失物，应当返还权利人。拾得人应当及时通知权利人领取，或者送交公安等有关部门。\n第三百一十五条　有关部门收到遗失物，知道权利人的，应当及时通知其领取；不知道的，应当及时发布招领公告', 780, '{\"level\": null, \"title\": null, \"chunk_index\": 35}', 'bge-large-zh-v1.5', '2026-09-25 17:05:01');
INSERT INTO `chunk` VALUES ('1b7aec85-cea5-4eb0-aef6-f04dbd93695a', '821ce1fd-178d-4a7e-ab92-3deff1488ce2', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 72, '第三节　妨害国（边）境管理罪\n第三百一十八条　组织他人偷越国（边）境的，处二年以上七年以下有期徒刑，并处罚金；有下列情形之一的，处七年以上有期徒刑或者无期徒刑，并处罚金或者没收财产：\n（一）组织他人偷越国（边）境集团的首要分子；\n（二）多次组织他人偷越国（边）境或者组织他人偷越国（边）境人数众多的；\n（三）造成被组织人重伤、死亡的；\n（四）剥夺或者限制被组织人人身自由的；\n（五）以暴力、威胁方法抗拒检查的；\n（六）违法所得数额巨大的；\n（七）有其他特别严重情节的。\n犯前款罪，对被组织人有杀害、伤害、强奸、拐卖等犯罪行为，或者对检查人员有杀害、伤害等犯罪行为的，依照数罪并罚的规定处罚。\n第三百一十九条　以劳务输出、经贸往来或者其他名义，弄虚作假，骗取护照、签证等出境证件，为组织他人偷越国（边）境使用的，处三年以下有期徒刑，并处罚金；情节严重的，处三年以上十年以下有期徒刑，并处罚金。\n单位犯前款罪的，对单位判处罚金，并对其直接负责的主管人员和其他直接责任人员，依照前款的规定处罚。\n第三百二十条　为他人提供伪造、变造的护照、签证等出入境证件，或者出售护照、签证等出入境证件的，处五年以下有期徒刑，并处罚金；情节严重的，处五年以上有期徒刑，并处罚金。\n第三百二十一条　运送他人偷越国（边）境的，处五年以下有期徒刑、拘役或者管制，并处罚金；有下列情形之一的，处五年以上十年以下有期徒刑，并处罚金：\n（一）多次实施运送行为或者运送人数众多的；\n（二）所使用的船只、车辆等交通工具不具备必要的安全条件，足以造成严重后果的；\n（三）违法所得数额巨大的；\n（四）有其他特别严重情节的。\n在运送他人偷越国（边）境中造成被运送人重伤、死亡，或者以暴力、威胁方法抗拒检查的，处七年以上有期徒刑，并处罚金', 746, '{\"level\": null, \"title\": null, \"chunk_index\": 72}', 'bge-large-zh-v1.5', '2026-09-25 17:04:56');
INSERT INTO `chunk` VALUES ('1d3cd7e5-aab6-4c27-8422-a0a2785733b5', 'b25ce095-dfba-4403-acf8-c58eb456ca4c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 44, '以乡镇、村企业的厂房等建筑物抵押的，其占用范围内的建设用地使用权一并抵押。\n第三百九十九条　下列财产不得抵押：\n（一）土地所有权；\n（二）宅基地、自留地、自留山等集体所有土地的使用权，但是法律规定可以抵押的除外；\n（三）学校、幼儿园、医疗机构等为公益目的成立的非营利法人的教育设施、医疗卫生设施和其他公益设施；\n（四）所有权、使用权不明或者有争议的财产；\n（五）依法被查封、扣押、监管的财产；\n（六）法律、行政法规规定不得抵押的其他财产。\n第四百条　设立抵押权，当事人应当采用书面形式订立抵押合同。\n抵押合同一般包括下列条款：\n（一）被担保债权的种类和数额；\n（二）债务人履行债务的期限；\n（三）抵押财产的名称、数量等情况；\n（四）担保的范围。\n第四百零一条　抵押权人在债务履行期限届满前，与抵押人约定债务人不履行到期债务时抵押财产归债权人所有的，只能依法就抵押财产优先受偿。\n第四百零二条　以本法第三百九十五条第一款第一项至第三项规定的财产或者第五项规定的正在建造的建筑物抵押的，应当办理抵押登记。抵押权自登记时设立。\n第四百零三条　以动产抵押的，抵押权自抵押合同生效时设立；未经登记，不得对抗善意第三人。\n第四百零四条　以动产抵押的，不得对抗正常经营活动中已经支付合理价款并取得抵押财产的买受人。\n第四百零五条　抵押权设立前，抵押财产已经出租并转移占有的，原租赁关系不受该抵押权的影响。\n第四百零六条　抵押期间，抵押人可以转让抵押财产。当事人另有约定的，按照其约定。抵押财产转让的，抵押权不受影响。\n抵押人转让抵押财产的，应当及时通知抵押权人。抵押权人能够证明抵押财产转让可能损害抵押权的，可以请求抵押人将转让所得的价款向抵押权人提前清偿债务或者提存。转让的价款超过债权数额的部分归抵押人所有，不足部分由债务人清偿。\n第四百零七条　抵押权不得与债权分离而单独转让或者作为其他债权的担保', 794, '{\"level\": null, \"title\": null, \"chunk_index\": 44}', 'bge-large-zh-v1.5', '2026-09-25 17:05:01');
INSERT INTO `chunk` VALUES ('1d49682d-94b5-4268-addb-81ca700f0ee7', '821ce1fd-178d-4a7e-ab92-3deff1488ce2', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 61, '第二百七十六条　由于泄愤报复或者其他个人目的，毁坏机器设备、残害耕畜或者以其他方法破坏生产经营的，处三年以下有期徒刑、拘役或者管制；情节严重的，处三年以上七年以下有期徒刑。\n第二百七十六条之一　以转移财产、逃匿等方法逃避支付劳动者的劳动报酬或者有能力支付而不支付劳动者的劳动报酬，数额较大，经政府有关部门责令支付仍不支付的，处三年以下有期徒刑或者拘役，并处或者单处罚金；造成严重后果的，处三年以上七年以下有期徒刑，并处罚金。\n单位犯前款罪的，对单位判处罚金，并对其直接负责的主管人员和其他直接责任人员，依照前款的规定处罚。\n有前两款行为，尚未造成严重后果，在提起公诉前支付劳动者的劳动报酬，并依法承担相应赔偿责任的，可以减轻或者免除处罚。\n第六章　妨害社会管理秩序罪\n第一节　扰乱公共秩序罪\n第二百七十七条　以暴力、威胁方法阻碍国家机关工作人员依法执行职务的，处三年以下有期徒刑、拘役、管制或者罚金。\n以暴力、威胁方法阻碍全国人民代表大会和地方各级人民代表大会代表依法执行代表职务的，依照前款的规定处罚。\n在自然灾害和突发事件中，以暴力、威胁方法阻碍红十字会工作人员依法履行职责的，依照第一款的规定处罚。\n故意阻碍国家安全机关、公安机关依法执行国家安全工作任务，未使用暴力、威胁方法，造成严重后果的，依照第一款的规定处罚。\n暴力袭击正在依法执行职务的人民警察的，处三年以下有期徒刑、拘役或者管制；使用枪支、管制刀具，或者以驾驶机动车撞击等手段，严重危及其人身安全的，处三年以上七年以下有期徒刑。\n第二百七十八条　煽动群众暴力抗拒国家法律、行政法规实施的，处三年以下有期徒刑、拘役、管制或者剥夺政治权利；造成严重后果的，处三年以上七年以下有期徒刑。\n第二百七十九条　冒充国家机关工作人员招摇撞骗的，处三年以下有期徒刑、拘役、管制或者剥夺政治权利；情节严重的，处三年以上十年以下有期徒刑', 791, '{\"level\": null, \"title\": null, \"chunk_index\": 61}', 'bge-large-zh-v1.5', '2026-09-25 17:04:56');
INSERT INTO `chunk` VALUES ('1d675671-9b03-4528-81f0-c93e43b6f7e2', 'b25ce095-dfba-4403-acf8-c58eb456ca4c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 119, '自然人发现信息处理者违反法律、行政法规的规定或者双方的约定处理其个人信息的，有权请求信息处理者及时删除。\n第一千零三十八条　信息处理者不得泄露或者篡改其收集、存储的个人信息；未经自然人同意，不得向他人非法提供其个人信息，但是经过加工无法识别特定个人且不能复原的除外。\n信息处理者应当采取技术措施和其他必要措施，确保其收集、存储的个人信息安全，防止信息泄露、篡改、丢失；发生或者可能发生个人信息泄露、篡改、丢失的，应当及时采取补救措施，按照规定告知自然人并向有关主管部门报告。\n第一千零三十九条　国家机关、承担行政职能的法定机构及其工作人员对于履行职责过程中知悉的自然人的隐私和个人信息，应当予以保密，不得泄露或者向他人非法提供。\n第五编　婚姻家庭\n第一章　一般规定\n第一千零四十条　本编调整因婚姻家庭产生的民事关系。\n第一千零四十一条　婚姻家庭受国家保护。\n实行婚姻自由、一夫一妻、男女平等的婚姻制度。\n保护妇女、未成年人、老年人、残疾人的合法权益。\n第一千零四十二条　禁止包办、买卖婚姻和其他干涉婚姻自由的行为。禁止借婚姻索取财物。\n禁止重婚。禁止有配偶者与他人同居。\n禁止家庭暴力。禁止家庭成员间的虐待和遗弃。\n第一千零四十三条　家庭应当树立优良家风，弘扬家庭美德，重视家庭文明建设。\n夫妻应当互相忠实，互相尊重，互相关爱；家庭成员应当敬老爱幼，互相帮助，维护平等、和睦、文明的婚姻家庭关系。\n第一千零四十四条　收养应当遵循最有利于被收养人的原则，保障被收养人和收养人的合法权益。\n禁止借收养名义买卖未成年人。\n第一千零四十五条　亲属包括配偶、血亲和姻亲。\n配偶、父母、子女、兄弟姐妹、祖父母、外祖父母、孙子女、外孙子女为近亲属。\n配偶、父母、子女和其他共同生活的近亲属为家庭成员', 742, '{\"level\": null, \"title\": null, \"chunk_index\": 119}', 'bge-large-zh-v1.5', '2026-09-25 17:05:01');
INSERT INTO `chunk` VALUES ('1f016837-15e1-4d2d-a41f-7ee979e0b208', '16cbea7e-7e36-4f31-afb5-63892345d29c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 34, '对于被调查人到案时随身携带的物品，以及被调查人或者其他相关人员主动上交的财物和文件，依法需要扣押的，依照前款规定办理。对于被调查人随身携带的与案件无关的个人用品，应当逐件登记，随案移交或者退还。\n第一百五十六条　对查封、扣押工作，应当全程同步录音录像。\n查封、扣押时，应当出具《查封/扣押通知书》，调查人员不得少于二人。持有人拒绝交出应当查封、扣押的财物和文件的，可以依法强制查封、扣押。\n调查人员对于查封、扣押的财物和文件，应当会同在场见证人和被查封、扣押财物持有人进行清点核对，开列《查封/扣押财物、文件清单》，由调查人员、见证人和持有人签名或者盖章。持有人不在场或者拒绝签名、盖章的，调查人员应当在清单上记明。\n查封、扣押财物，应当为被调查人及其所扶养的亲属保留必需的生活费用和物品。\n第一百五十七条　查封、扣押不动产和置于该不动产上不宜移动的设施、家具和其他相关财物，以及车辆、船舶、航空器和大型机械、设备等财物，必要时可以依法扣押其权利证书，经拍照或者录像后原地封存。调查人员应当在查封清单上记明相关财物的所在地址和特征，已经拍照或者录像及其权利证书被扣押的情况，由调查人员、见证人和持有人签名或者盖章。持有人不在场或者拒绝签名、盖章的，调查人员应当在清单上记明。\n查封、扣押前款规定财物的，必要时可以将被查封财物交给持有人或者其近亲属保管。调查人员应当告知保管人妥善保管，不得对被查封财物进行转移、变卖、毁损、抵押、赠予等处理。\n调查人员应当将《查封/扣押通知书》送达不动产、生产设备或者车辆、船舶、航空器等财物的登记、管理部门，告知其在查封期间禁止办理抵押、转让、出售等权属关系变更、转移登记手续。相关情况应当在查封清单上记明。被查封、扣押的财物已经办理抵押登记的，监察机关在执行没收、追缴、责令退赔等决定时应当及时通知抵押权人', 771, '{\"level\": null, \"title\": null, \"chunk_index\": 34}', 'bge-large-zh-v1.5', '2026-09-25 17:04:49');
INSERT INTO `chunk` VALUES ('20488554-e2d5-49d7-967a-6f6d3670fdfb', '0497a5e7-7044-4b18-8fed-af3fb7bc7890', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 0, '中华人民共和国增值税法实施条例\n第一章　总　　则\n第一条　根据《中华人民共和国增值税法》（以下简称增值税法），制定本条例。\n第二条　增值税法第三条所称货物，包括有形动产、电力、热力、气体等。\n增值税法第三条所称服务，包括交通运输服务、邮政服务、电信服务、建筑服务、金融服务，以及信息技术服务、文化体育服务、鉴证咨询服务等生产生活服务。\n增值税法第三条所称无形资产，是指不具实物形态，但能带来经济利益的资产，包括技术、商标、著作权、商誉、自然资源使用权和其他无形资产。\n增值税法第三条所称不动产，是指不能移动或者移动后会引起性质、形状改变的资产，包括建筑物、构筑物等。\n国务院财政、税务主管部门提出货物、服务、无形资产、不动产的具体范围，报国务院批准后公布施行。\n第三条　增值税法第三条所称单位，包括企业、行政机关、事业单位、军事单位、社会组织及其他单位。\n增值税法第三条所称个人，包括个体工商户和自然人。\n第四条　增值税法第四条第四项所称服务、无形资产在境内消费，是指下列情形：\n（一）境外单位或者个人向境内单位或者个人销售服务、无形资产，在境外现场消费的服务除外；\n（二）境外单位或者个人销售的服务、无形资产与境内的货物、不动产、自然资源直接相关；\n（三）国务院财政、税务主管部门规定的其他情形。\n第五条　纳税人开具增值税专用发票，应当分别列明销售额和增值税税额。\n第六条　适用一般计税方法的纳税人为一般纳税人。\n一般纳税人实行登记制度，具体登记办法由国务院税务主管部门制定。\n第七条　自然人属于小规模纳税人。不经常发生应税交易且主要业务不属于应税交易范围的非企业单位，可以选择按照小规模纳税人纳税。\n第二章　税　　率\n第八条　增值税法第十条第四项所称出口货物，是指向海关报关实际离境并销售给境外单位或者个人的货物，以及国务院规定的视同出口的货物', 774, '{\"level\": null, \"title\": null, \"chunk_index\": 0}', 'bge-large-zh-v1.5', '2026-09-25 17:04:28');
INSERT INTO `chunk` VALUES ('20ef7f68-3c81-4d71-b3e3-22909ae13eb9', 'b25ce095-dfba-4403-acf8-c58eb456ca4c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 124, '第一千零八十条　完成离婚登记，或者离婚判决书、调解书生效，即解除婚姻关系。\n第一千零八十一条　现役军人的配偶要求离婚，应当征得军人同意，但是军人一方有重大过错的除外。\n第一千零八十二条　女方在怀孕期间、分娩后一年内或者终止妊娠后六个月内，男方不得提出离婚；但是，女方提出离婚或者人民法院认为确有必要受理男方离婚请求的除外。\n第一千零八十三条　离婚后，男女双方自愿恢复婚姻关系的，应当到婚姻登记机关重新进行结婚登记。\n第一千零八十四条　父母与子女间的关系，不因父母离婚而消除。离婚后，子女无论由父或者母直接抚养，仍是父母双方的子女。\n离婚后，父母对于子女仍有抚养、教育、保护的权利和义务。\n离婚后，不满两周岁的子女，以由母亲直接抚养为原则。已满两周岁的子女，父母双方对抚养问题协议不成的，由人民法院根据双方的具体情况，按照最有利于未成年子女的原则判决。子女已满八周岁的，应当尊重其真实意愿。\n第一千零八十五条　离婚后，子女由一方直接抚养的，另一方应当负担部分或者全部抚养费。负担费用的多少和期限的长短，由双方协议；协议不成的，由人民法院判决。\n前款规定的协议或者判决，不妨碍子女在必要时向父母任何一方提出超过协议或者判决原定数额的合理要求。\n第一千零八十六条　离婚后，不直接抚养子女的父或者母，有探望子女的权利，另一方有协助的义务。\n行使探望权利的方式、时间由当事人协议；协议不成的，由人民法院判决。\n父或者母探望子女，不利于子女身心健康的，由人民法院依法中止探望；中止的事由消失后，应当恢复探望。\n第一千零八十七条　离婚时，夫妻的共同财产由双方协议处理；协议不成的，由人民法院根据财产的具体情况，按照照顾子女、女方和无过错方权益的原则判决。\n对夫或者妻在家庭土地承包经营中享有的权益等，应当依法予以保护', 751, '{\"level\": null, \"title\": null, \"chunk_index\": 124}', 'bge-large-zh-v1.5', '2026-09-25 17:05:01');
INSERT INTO `chunk` VALUES ('2103fdb7-7aef-43a4-b603-fee923544684', 'b25ce095-dfba-4403-acf8-c58eb456ca4c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 83, '返还的租赁物应当符合按照约定或者根据租赁物的性质使用后的状态。\n第七百三十四条　租赁期限届满，承租人继续使用租赁物，出租人没有提出异议的，原租赁合同继续有效，但是租赁期限为不定期。\n租赁期限届满，房屋承租人享有以同等条件优先承租的权利。\n第十五章　融资租赁合同\n第七百三十五条　融资租赁合同是出租人根据承租人对出卖人、租赁物的选择，向出卖人购买租赁物，提供给承租人使用，承租人支付租金的合同。\n第七百三十六条　融资租赁合同的内容一般包括租赁物的名称、数量、规格、技术性能、检验方法，租赁期限，租金构成及其支付期限和方式、币种，租赁期限届满租赁物的归属等条款。\n融资租赁合同应当采用书面形式。\n第七百三十七条　当事人以虚构租赁物方式订立的融资租赁合同无效。\n第七百三十八条　依照法律、行政法规的规定，对于租赁物的经营使用应当取得行政许可的，出租人未取得行政许可不影响融资租赁合同的效力。\n第七百三十九条　出租人根据承租人对出卖人、租赁物的选择订立的买卖合同，出卖人应当按照约定向承租人交付标的物，承租人享有与受领标的物有关的买受人的权利。\n第七百四十条　出卖人违反向承租人交付标的物的义务，有下列情形之一的，承租人可以拒绝受领出卖人向其交付的标的物：\n（一）标的物严重不符合约定；\n（二）未按照约定交付标的物，经承租人或者出租人催告后在合理期限内仍未交付。\n承租人拒绝受领标的物的，应当及时通知出租人。\n第七百四十一条　出租人、出卖人、承租人可以约定，出卖人不履行买卖合同义务的，由承租人行使索赔的权利。承租人行使索赔权利的，出租人应当协助。\n第七百四十二条　承租人对出卖人行使索赔权利，不影响其履行支付租金的义务。但是，承租人依赖出租人的技能确定租赁物或者出租人干预选择租赁物的，承租人可以请求减免相应租金', 753, '{\"level\": null, \"title\": null, \"chunk_index\": 83}', 'bge-large-zh-v1.5', '2026-09-25 17:05:01');
INSERT INTO `chunk` VALUES ('2109f36e-6863-4aac-97b4-eda5234ea3ba', '22a2c356-7a68-4455-b657-333e3dba1e1a', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 0, '中华人民共和国宪法\n（1982年12月4日第五届全国人民代表大会第五次会议通过　1982年12月4日全国人民代表大会公告公布施行\n根据1988年4月12日第七届全国人民代表大会第一次会议通过的《中华人民共和国宪法修正案》、1993年3月29日第八届全国人民代表大会第一次会议通过的《中华人民共和国宪法修正案》、1999年3月15日第九届全国人民代表大会第二次会议通过的《中华人民共和国宪法修正案》、2004年3月14日第十届全国人民代表大会第二次会议通过的《中华人民共和国宪法修正案》和2018年3月11日第十三届全国人民代表大会第一次会议通过的《中华人民共和国宪法修正案》修正）\n目　　录\n序　　言\n第一章　总　　纲\n第二章　公民的基本权利和义务\n第三章　国家机构\n第一节　全国人民代表大会\n第二节　中华人民共和国主席\n第三节　国务院\n第四节　中央军事委员会\n第五节　地方各级人民代表大会和地方各级人民政府\n第六节　民族自治地方的自治机关\n第七节　监察委员会\n第八节　人民法院和人民检察院\n第四章　国旗、国歌、国徽、首都\n序　　言\n中国是世界上历史最悠久的国家之一。中国各族人民共同创造了光辉灿烂的文化，具有光荣的革命传统。\n一八四〇年以后，封建的中国逐渐变成半殖民地、半封建的国家。中国人民为国家独立、民族解放和民主自由进行了前仆后继的英勇奋斗。\n二十世纪，中国发生了翻天覆地的伟大历史变革。\n一九一一年孙中山先生领导的辛亥革命，废除了封建帝制，创立了中华民国。但是，中国人民反对帝国主义和封建主义的历史任务还没有完成。\n一九四九年，以毛泽东主席为领袖的中国共产党领导中国各族人民，在经历了长期的艰难曲折的武装斗争和其他形式的斗争以后，终于推翻了帝国主义、封建主义和官僚资本主义的统治，取得了新民主主义革命的伟大胜利，建立了中华人民共和国。从此，中国人民掌握了国家的权力，成为国家的主人', 795, '{\"level\": null, \"title\": null, \"chunk_index\": 0}', 'bge-large-zh-v1.5', '2026-09-25 17:04:28');
INSERT INTO `chunk` VALUES ('210b36ad-098e-4022-bbc5-ab9bdc0197bc', 'd9d7dc15-8041-43b8-9f75-f112fe3ae003', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 22, '任何单位和个人不得交寄危险化学品或者在邮件、快件内夹带危险化学品，不得将危险化学品匿报或者谎报为普通物品交寄。邮政企业、快递企业不得收寄危险化学品。\n对涉嫌违反本条第一款、第二款规定的，交通运输主管部门、邮政管理部门可以依法开拆，并通过取样检验等多种方式开展查验。\n第八十四条　通过铁路、航空运输危险化学品的安全管理，依照有关铁路、航空运输的法律、行政法规、规章的规定执行。\n第七章　危险化学品登记\n第八十五条　国家实行危险化学品登记制度，为危险化学品安全管理以及危险化学品事故预防和应急救援提供技术、信息支持。\n第八十六条　危险化学品生产企业、进口企业应当向国务院应急管理部门负责危险化学品登记的机构（以下简称危险化学品登记机构）办理危险化学品登记。\n危险化学品登记包括下列内容：\n（一）分类和标签信息；\n（二）物理、化学性质；\n（三）主要用途；\n（四）危险特性；\n（五）储存、使用、运输的安全要求；\n（六）出现危险情况的应急处置措施。\n对同一企业生产、进口的同一品种的危险化学品，不进行重复登记。危险化学品生产企业、进口企业发现其生产、进口的危险化学品有新的危险特性或者其他登记内容发生变更的，应当及时向危险化学品登记机构办理登记内容变更手续。\n危险化学品登记的具体办法由国务院应急管理部门制定。\n第八十七条　国家对研究开发、试产试销过程中的低量低释放、低暴露的危险化学品等免予登记。免予登记的具体办法由国务院应急管理部门会同工业和信息化、公安、生态环境、农业农村、卫生健康、海关等部门制定。\n第八十八条　危险化学品登记机构应当将危险化学品登记信息数据与工业和信息化、公安、自然资源、生态环境、交通运输、农业农村、卫生健康、海关、市场监督管理、能源、军事机关等单位共享。\n第八十九条　新化学物质环境管理登记，依照有关生态环境保护的法律、行政法规、规章的规定执行', 782, '{\"level\": null, \"title\": null, \"chunk_index\": 22}', 'bge-large-zh-v1.5', '2026-09-25 17:04:46');
INSERT INTO `chunk` VALUES ('21ba126c-c124-4eed-9823-b7de036981e2', 'b25ce095-dfba-4403-acf8-c58eb456ca4c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 16, '第一百三十四条　民事法律行为可以基于双方或者多方的意思表示一致成立，也可以基于单方的意思表示成立。\n法人、非法人组织依照法律或者章程规定的议事方式和表决程序作出决议的，该决议行为成立。\n第一百三十五条　民事法律行为可以采用书面形式、口头形式或者其他形式；法律、行政法规规定或者当事人约定采用特定形式的，应当采用特定形式。\n第一百三十六条　民事法律行为自成立时生效，但是法律另有规定或者当事人另有约定的除外。\n行为人非依法律规定或者未经对方同意，不得擅自变更或者解除民事法律行为。\n第二节　意思表示\n第一百三十七条　以对话方式作出的意思表示，相对人知道其内容时生效。\n以非对话方式作出的意思表示，到达相对人时生效。以非对话方式作出的采用数据电文形式的意思表示，相对人指定特定系统接收数据电文的，该数据电文进入该特定系统时生效；未指定特定系统的，相对人知道或者应当知道该数据电文进入其系统时生效。当事人对采用数据电文形式的意思表示的生效时间另有约定的，按照其约定。\n第一百三十八条　无相对人的意思表示，表示完成时生效。法律另有规定的，依照其规定。\n第一百三十九条　以公告方式作出的意思表示，公告发布时生效。\n第一百四十条　行为人可以明示或者默示作出意思表示。\n沉默只有在有法律规定、当事人约定或者符合当事人之间的交易习惯时，才可以视为意思表示。\n第一百四十一条　行为人可以撤回意思表示。撤回意思表示的通知应当在意思表示到达相对人前或者与意思表示同时到达相对人。\n第一百四十二条　有相对人的意思表示的解释，应当按照所使用的词句，结合相关条款、行为的性质和目的、习惯以及诚信原则，确定意思表示的含义。\n无相对人的意思表示的解释，不能完全拘泥于所使用的词句，而应当结合相关条款、行为的性质和目的、习惯以及诚信原则，确定行为人的真实意思', 762, '{\"level\": null, \"title\": null, \"chunk_index\": 16}', 'bge-large-zh-v1.5', '2026-09-25 17:05:01');
INSERT INTO `chunk` VALUES ('23cf0bd4-1191-472c-8c84-d67116918355', 'b25ce095-dfba-4403-acf8-c58eb456ca4c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 63, '第五百五十三条　债务人转移债务的，新债务人可以主张原债务人对债权人的抗辩；原债务人对债权人享有债权的，新债务人不得向债权人主张抵销。\n第五百五十四条　债务人转移债务的，新债务人应当承担与主债务有关的从债务，但是该从债务专属于原债务人自身的除外。\n第五百五十五条　当事人一方经对方同意，可以将自己在合同中的权利和义务一并转让给第三人。\n第五百五十六条　合同的权利和义务一并转让的，适用债权转让、债务转移的有关规定。\n第七章　合同的权利义务终止\n第五百五十七条　有下列情形之一的，债权债务终止：\n（一）债务已经履行；\n（二）债务相互抵销；\n（三）债务人依法将标的物提存；\n（四）债权人免除债务；\n（五）债权债务同归于一人；\n（六）法律规定或者当事人约定终止的其他情形。\n合同解除的，该合同的权利义务关系终止。\n第五百五十八条　债权债务终止后，当事人应当遵循诚信等原则，根据交易习惯履行通知、协助、保密、旧物回收等义务。\n第五百五十九条　债权债务终止时，债权的从权利同时消灭，但是法律另有规定或者当事人另有约定的除外。\n第五百六十条　债务人对同一债权人负担的数项债务种类相同，债务人的给付不足以清偿全部债务的，除当事人另有约定外，由债务人在清偿时指定其履行的债务。\n债务人未作指定的，应当优先履行已经到期的债务；数项债务均到期的，优先履行对债权人缺乏担保或者担保最少的债务；均无担保或者担保相等的，优先履行债务人负担较重的债务；负担相同的，按照债务到期的先后顺序履行；到期时间相同的，按照债务比例履行。\n第五百六十一条　债务人在履行主债务外还应当支付利息和实现债权的有关费用，其给付不足以清偿全部债务的，除当事人另有约定外，应当按照下列顺序履行：\n（一）实现债权的有关费用；\n（二）利息；\n（三）主债务。\n第五百六十二条　当事人协商一致，可以解除合同。\n当事人可以约定一方解除合同的事由', 790, '{\"level\": null, \"title\": null, \"chunk_index\": 63}', 'bge-large-zh-v1.5', '2026-09-25 17:05:01');
INSERT INTO `chunk` VALUES ('25377fdf-a783-40a4-91c6-0862ada09496', 'd9d7dc15-8041-43b8-9f75-f112fe3ae003', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 14, '依法设立的危险化学品生产企业在其厂区范围内销售本企业生产的危险化学品，不需要取得危险化学品经营许可。\n依照《中华人民共和国港口法》的规定取得港口经营许可证的港口经营人，在港区内从事危险化学品仓储经营，不需要取得危险化学品经营许可。\n第五十四条　从事危险化学品经营的企业应当具备下列条件：\n（一）有符合国家标准、行业标准的经营场所，储存危险化学品的，还应当有符合国家标准、行业标准的储存设施；\n（二）从业人员经过专业技术培训并经考核合格；\n（三）有健全的安全管理规章制度；\n（四）有专职安全生产管理人员，主要负责人和安全生产管理人员具备与本企业危险化学品经营活动相适应的安全生产知识和管理能力，经应急管理部门考核合格；\n（五）有符合国家规定的危险化学品事故应急预案和必要的应急救援器材、装备、设备和物资；\n（六）法律、法规规定的其他条件。\n第五十五条　从事剧毒化学品、易制爆危险化学品经营的企业，应当向所在地设区的市级人民政府应急管理部门提出申请。从事其他危险化学品经营的企业，应当向所在地县级人民政府应急管理部门提出申请；有储存设施且储存数量构成重大危险源的，应当向所在地设区的市级人民政府应急管理部门提出申请。申请人应当提交其符合本法第五十四条规定条件的证明材料。设区的市级人民政府应急管理部门或者县级人民政府应急管理部门应当依法进行审查，并按照规定对申请人的经营场所、储存设施进行现场核查。自收到证明材料之日起二十个工作日内作出批准或者不予批准的决定。予以批准的，颁发危险化学品经营许可证；不予批准的，书面通知申请人并说明理由。\n设区的市级人民政府应急管理部门和县级人民政府应急管理部门应当将其颁发危险化学品经营许可证的情况依照有关法律、行政法规的规定及时向社会公开。\n申请人持危险化学品经营许可证向市场监督管理部门办理登记手续后，方可从事危险化学品经营活动', 781, '{\"level\": null, \"title\": null, \"chunk_index\": 14}', 'bge-large-zh-v1.5', '2026-09-25 17:04:46');
INSERT INTO `chunk` VALUES ('25445c87-c6b5-4682-a504-3ffa9ad04c90', 'b25ce095-dfba-4403-acf8-c58eb456ca4c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 3, '第二条　民法调整平等主体的自然人、法人和非法人组织之间的人身关系和财产关系。\n第三条　民事主体的人身权利、财产权利以及其他合法权益受法律保护，任何组织或者个人不得侵犯。\n第四条　民事主体在民事活动中的法律地位一律平等。\n第五条　民事主体从事民事活动，应当遵循自愿原则，按照自己的意思设立、变更、终止民事法律关系。\n第六条　民事主体从事民事活动，应当遵循公平原则，合理确定各方的权利和义务。\n第七条　民事主体从事民事活动，应当遵循诚信原则，秉持诚实，恪守承诺。\n第八条　民事主体从事民事活动，不得违反法律，不得违背公序良俗。\n第九条　民事主体从事民事活动，应当有利于节约资源、保护生态环境。\n第十条　处理民事纠纷，应当依照法律；法律没有规定的，可以适用习惯，但是不得违背公序良俗。\n第十一条　其他法律对民事关系有特别规定的，依照其规定。\n第十二条　中华人民共和国领域内的民事活动，适用中华人民共和国法律。法律另有规定的，依照其规定。\n第二章　自然人\n第一节　民事权利能力和民事行为能力\n第十三条　自然人从出生时起到死亡时止，具有民事权利能力，依法享有民事权利，承担民事义务。\n第十四条　自然人的民事权利能力一律平等。\n第十五条　自然人的出生时间和死亡时间，以出生证明、死亡证明记载的时间为准；没有出生证明、死亡证明的，以户籍登记或者其他有效身份登记记载的时间为准。有其他证据足以推翻以上记载时间的，以该证据证明的时间为准。\n第十六条　涉及遗产继承、接受赠与等胎儿利益保护的，胎儿视为具有民事权利能力。但是，胎儿娩出时为死体的，其民事权利能力自始不存在。\n第十七条　十八周岁以上的自然人为成年人。不满十八周岁的自然人为未成年人。\n第十八条　成年人为完全民事行为能力人，可以独立实施民事法律行为。\n十六周岁以上的未成年人，以自己的劳动收入为主要生活来源的，视为完全民事行为能力人', 786, '{\"level\": null, \"title\": null, \"chunk_index\": 3}', 'bge-large-zh-v1.5', '2026-09-25 17:05:01');
INSERT INTO `chunk` VALUES ('2813fafa-ae88-4ce2-a578-be8245959db2', 'b25ce095-dfba-4403-acf8-c58eb456ca4c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 68, '当事人因防止损失扩大而支出的合理费用，由违约方负担。\n第五百九十二条　当事人都违反合同的，应当各自承担相应的责任。\n当事人一方违约造成对方损失，对方对损失的发生有过错的，可以减少相应的损失赔偿额。\n第五百九十三条　当事人一方因第三人的原因造成违约的，应当依法向对方承担违约责任。当事人一方和第三人之间的纠纷，依照法律规定或者按照约定处理。\n第五百九十四条　因国际货物买卖合同和技术进出口合同争议提起诉讼或者申请仲裁的时效期间为四年。\n第二分编　典型合同\n第九章　买卖合同\n第五百九十五条　买卖合同是出卖人转移标的物的所有权于买受人，买受人支付价款的合同。\n第五百九十六条　买卖合同的内容一般包括标的物的名称、数量、质量、价款、履行期限、履行地点和方式、包装方式、检验标准和方法、结算方式、合同使用的文字及其效力等条款。\n第五百九十七条　因出卖人未取得处分权致使标的物所有权不能转移的，买受人可以解除合同并请求出卖人承担违约责任。\n法律、行政法规禁止或者限制转让的标的物，依照其规定。\n第五百九十八条　出卖人应当履行向买受人交付标的物或者交付提取标的物的单证，并转移标的物所有权的义务。\n第五百九十九条　出卖人应当按照约定或者交易习惯向买受人交付提取标的物单证以外的有关单证和资料。\n第六百条　出卖具有知识产权的标的物的，除法律另有规定或者当事人另有约定外，该标的物的知识产权不属于买受人。\n第六百零一条　出卖人应当按照约定的时间交付标的物。约定交付期限的，出卖人可以在该交付期限内的任何时间交付。\n第六百零二条　当事人没有约定标的物的交付期限或者约定不明确的，适用本法第五百一十条、第五百一十一条第四项的规定。\n第六百零三条　出卖人应当按照约定的地点交付标的物', 730, '{\"level\": null, \"title\": null, \"chunk_index\": 68}', 'bge-large-zh-v1.5', '2026-09-25 17:05:01');
INSERT INTO `chunk` VALUES ('284b1d85-0def-4792-ad1b-1b36762503e0', 'd9d7dc15-8041-43b8-9f75-f112fe3ae003', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 17, '第六章　运输安全\n第六十四条　通过道路、水路运输按照危险货物管理的危险化学品，应当遵守本法和有关法律、行政法规、国务院交通运输主管部门关于危险货物道路、水路运输安全的规定。\n第六十五条　从事危险化学品道路运输、水路运输的，应当向市场监督管理部门办理登记手续，并分别依照有关道路运输、水路运输的法律、行政法规的规定，取得危险货物道路运输许可、相应危险货物水路运输许可或者办理备案手续。\n通过道路、水路运输危险化学品，应当由依法取得相应许可或者办理备案手续的运输企业承运，其他单位和个人不得承运。托运人应当委托依法取得相应许可或者办理备案手续的运输企业承运，不得委托其他单位和个人承运。其他单位和个人的危险化学品运输车辆不得挂靠经营。\n危险化学品道路运输企业、水路运输企业应当配备专职安全生产管理人员。\n经妥善处理后可以按照普通货物管理的危险化学品按照普通货物运输，具体办法由国务院交通运输主管部门制定。\n第六十六条　危险化学品道路运输企业、水路运输企业的驾驶人员、船员、装卸管理人员、押运人员、申报人员、集装箱装箱现场检查员应当经交通运输主管部门考核合格，取得从业资格。具体办法由国务院交通运输主管部门制定。\n危险化学品的装卸作业应当遵守安全作业标准、规程和制度，并在装卸管理人员的现场指挥或者监控下进行。水路运输危险化学品的集装箱装箱作业应当在集装箱装箱现场检查员的指挥或者监控下进行，并符合积载、隔离的规范和要求；装箱作业完毕后，集装箱装箱现场检查员应当签署装箱证明书。\n第六十七条　运输危险化学品，应当根据危险化学品的危险特性采取相应的安全防护措施，并配备必要的防护用品和应急救援器材、装备、设备和物资。\n用于运输危险化学品的槽罐以及其他容器应当封口严密，能够防止危险化学品在运输过程中因温度、湿度或者压力的变化发生渗漏、洒漏；槽罐以及其他容器的溢流和泄压装置应当设置准确、启闭灵活', 793, '{\"level\": null, \"title\": null, \"chunk_index\": 17}', 'bge-large-zh-v1.5', '2026-09-25 17:04:46');
INSERT INTO `chunk` VALUES ('28893906-b73b-410f-ac5c-1eb88ac92514', '821ce1fd-178d-4a7e-ab92-3deff1488ce2', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 9, '被剥夺政治权利的犯罪分子，在执行期间，应当遵守法律、行政法规和国务院公安部门有关监督管理的规定，服从监督；不得行使本法第五十四条规定的各项权利。\n第八节　没收财产\n第五十九条　没收财产是没收犯罪分子个人所有财产的一部或者全部。没收全部财产的，应当对犯罪分子个人及其扶养的家属保留必需的生活费用。\n在判处没收财产的时候，不得没收属于犯罪分子家属所有或者应有的财产。\n第六十条　没收财产以前犯罪分子所负的正当债务，需要以没收的财产偿还的，经债权人请求，应当偿还。\n第四章　刑罚的具体运用\n第一节　量　　刑\n第六十一条　对于犯罪分子决定刑罚的时候，应当根据犯罪的事实、犯罪的性质、情节和对于社会的危害程度，依照本法的有关规定判处。\n第六十二条　犯罪分子具有本法规定的从重处罚、从轻处罚情节的，应当在法定刑的限度以内判处刑罚。\n第六十三条　犯罪分子具有本法规定的减轻处罚情节的，应当在法定刑以下判处刑罚；本法规定有数个量刑幅度的，应当在法定量刑幅度的下一个量刑幅度内判处刑罚。\n犯罪分子虽然不具有本法规定的减轻处罚情节，但是根据案件的特殊情况，经最高人民法院核准，也可以在法定刑以下判处刑罚。\n第六十四条　犯罪分子违法所得的一切财物，应当予以追缴或者责令退赔；对被害人的合法财产，应当及时返还；违禁品和供犯罪所用的本人财物，应当予以没收。没收的财物和罚金，一律上缴国库，不得挪用和自行处理。\n第二节　累　　犯\n第六十五条　被判处有期徒刑以上刑罚的犯罪分子，刑罚执行完毕或者赦免以后，在五年以内再犯应当判处有期徒刑以上刑罚之罪的，是累犯，应当从重处罚，但是过失犯罪和不满十八周岁的人犯罪的除外。\n前款规定的期限，对于被假释的犯罪分子，从假释期满之日起计算。\n第六十六条　危害国家安全犯罪、恐怖活动犯罪、黑社会性质的组织犯罪的犯罪分子，在刑罚执行完毕或者赦免以后，在任何时候再犯上述任一类罪的，都以累犯论处', 797, '{\"level\": null, \"title\": null, \"chunk_index\": 9}', 'bge-large-zh-v1.5', '2026-09-25 17:04:56');
INSERT INTO `chunk` VALUES ('28b99e78-96bc-4b12-93ea-cc5fd320754d', '16cbea7e-7e36-4f31-afb5-63892345d29c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 59, '派驻或者派出的监察机构、监察专员调查的职务犯罪案件需要指定起诉、审判管辖的，应当报派出机关办理指定管辖手续。\n第二百五十三条　上级监察机关指定下级监察机关进行调查，移送起诉时需要人民检察院依法指定管辖的，应当按规定办理有关程序事宜。\n第二百五十四条　监察机关对已经移送起诉的职务犯罪案件，发现遗漏被调查人罪行需要补充移送起诉的，应当经审批出具《补充起诉意见书》，连同相关案卷材料、证据等一并移送同级人民检察院。\n对于经人民检察院指定管辖的案件需要补充移送起诉的，可以直接移送原受理移送起诉的人民检察院；需要追加犯罪嫌疑人、被告人的，应当再次商请人民检察院办理指定管辖手续。\n第二百五十五条　对于涉嫌行贿犯罪、介绍贿赂犯罪或者共同职务犯罪等关联案件的涉案人员，移送起诉时一般应当随主案确定管辖。\n主案与关联案件由不同监察机关立案调查的，调查关联案件的监察机关在移送起诉前，应当报告或者通报调查主案的监察机关，由其统一协调案件管辖事宜。因特殊原因，关联案件不宜随主案确定管辖的，调查主案的监察机关应当及时通报和协调有关事项。\n第二百五十六条　监察机关对于人民检察院在审查起诉中书面提出的下列要求应当予以配合：\n（一）认为可能存在以非法方法收集证据情形，要求监察机关对证据收集的合法性作出说明或者提供相关证明材料的；\n（二）排除非法证据后，要求监察机关另行指派调查人员重新取证的；\n（三）对物证、书证、视听资料、电子数据及勘验检查、辨认、调查实验等笔录存在疑问，要求调查人员提供获取、制作的有关情况的；\n（四）要求监察机关对案件中某些专门性问题进行鉴定，或者对勘验检查进行复验、复查的；\n（五）认为主要犯罪事实已经查清，仍有部分证据需要补充完善，要求监察机关补充提供证据的；\n（六）人民检察院依法提出的其他工作要求', 754, '{\"level\": null, \"title\": null, \"chunk_index\": 59}', 'bge-large-zh-v1.5', '2026-09-25 17:04:49');
INSERT INTO `chunk` VALUES ('2941c495-054d-48c7-bc6c-1864d889a294', 'b25ce095-dfba-4403-acf8-c58eb456ca4c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 54, '第四百八十七条　受要约人在承诺期限内发出承诺，按照通常情形能够及时到达要约人，但是因其他原因致使承诺到达要约人时超过承诺期限的，除要约人及时通知受要约人因承诺超过期限不接受该承诺外，该承诺有效。\n第四百八十八条　承诺的内容应当与要约的内容一致。受要约人对要约的内容作出实质性变更的，为新要约。有关合同标的、数量、质量、价款或者报酬、履行期限、履行地点和方式、违约责任和解决争议方法等的变更，是对要约内容的实质性变更。\n第四百八十九条　承诺对要约的内容作出非实质性变更的，除要约人及时表示反对或者要约表明承诺不得对要约的内容作出任何变更外，该承诺有效，合同的内容以承诺的内容为准。\n第四百九十条　当事人采用合同书形式订立合同的，自当事人均签名、盖章或者按指印时合同成立。在签名、盖章或者按指印之前，当事人一方已经履行主要义务，对方接受时，该合同成立。\n法律、行政法规规定或者当事人约定合同应当采用书面形式订立，当事人未采用书面形式但是一方已经履行主要义务，对方接受时，该合同成立。\n第四百九十一条　当事人采用信件、数据电文等形式订立合同要求签订确认书的，签订确认书时合同成立。\n当事人一方通过互联网等信息网络发布的商品或者服务信息符合要约条件的，对方选择该商品或者服务并提交订单成功时合同成立，但是当事人另有约定的除外。\n第四百九十二条　承诺生效的地点为合同成立的地点。\n采用数据电文形式订立合同的，收件人的主营业地为合同成立的地点；没有主营业地的，其住所地为合同成立的地点。当事人另有约定的，按照其约定。\n第四百九十三条　当事人采用合同书形式订立合同的，最后签名、盖章或者按指印的地点为合同成立的地点，但是当事人另有约定的除外。\n第四百九十四条　国家根据抢险救灾、疫情防控或者其他需要下达国家订货任务、指令性任务的，有关民事主体之间应当依照有关法律、行政法规规定的权利和义务订立合同', 791, '{\"level\": null, \"title\": null, \"chunk_index\": 54}', 'bge-large-zh-v1.5', '2026-09-25 17:05:01');
INSERT INTO `chunk` VALUES ('2aee277e-57d0-4fda-9ed4-2ad25896d3c9', 'd9d7dc15-8041-43b8-9f75-f112fe3ae003', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 9, '第三十二条　危险化学品的包装应当符合法律、行政法规、规章的规定和国家标准、行业标准的要求。\n危险化学品包装物、容器的材质以及危险化学品包装的型式、规格、方法和单件质量，应当与所包装的危险化学品的性质和用途相适应。\n第三十三条　生产列入国家实行生产许可证制度的工业产品目录的危险化学品包装物、容器的企业，应当依照有关工业产品生产许可法律、行政法规的规定，取得工业产品生产许可证；其生产的危险化学品包装物、容器经具有相应资质的检验机构检验合格，方可出厂销售。\n运输危险化学品的船舶及其配载的容器，应当符合有关法律、行政法规、规章以及强制性标准和技术规范的要求，并经国家海事管理机构认定的船舶检验机构检验合格，方可投入使用。\n对重复使用的危险化学品包装物、容器，使用单位在重复使用前应当进行检查；发现存在安全隐患的，应当及时维修或者更换。使用单位应当对检查情况作出记录，记录的保存期限不得少于三年。\n第三十四条　生产、储存危险化学品的企业应当建立安全风险分级管控制度，开展安全风险辨识评估，按照安全风险分级采取相应的管控措施。\n生产、储存危险化学品的企业的工艺、设施、设备、原料等发生变更时应当重新进行安全风险辨识评估。\n生产、储存危险化学品的企业不得使用国家明令淘汰或者禁止使用的危及生产安全的工艺、技术、设施、设备，具体目录由国务院应急管理部门会同有关部门制定并公布。\n第三十五条　生产、储存危险化学品的企业应当建立包括工艺操作、特殊作业、设备管理、储存条件、开停车和检维修、变更等全部生产作业环节在内的过程安全管理制度，明确责任人、岗位职责和操作规程，并组织有效实施。\n第三十六条　生产、储存危险化学品的企业应当按照国家标准或者行业标准装备自动控制系统和安全仪表系统，建立安全风险监测预警系统，并与政府有关部门实现互联互通', 761, '{\"level\": null, \"title\": null, \"chunk_index\": 9}', 'bge-large-zh-v1.5', '2026-09-25 17:04:46');
INSERT INTO `chunk` VALUES ('2b7c6921-3222-4561-95e9-a37cceee79a7', '821ce1fd-178d-4a7e-ab92-3deff1488ce2', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 19, '第一百二十条之六　明知是宣扬恐怖主义、极端主义的图书、音频视频资料或者其他物品而非法持有，情节严重的，处三年以下有期徒刑、拘役或者管制，并处或者单处罚金。\n第一百二十一条　以暴力、胁迫或者其他方法劫持航空器的，处十年以上有期徒刑或者无期徒刑；致人重伤、死亡或者使航空器遭受严重破坏的，处死刑。\n第一百二十二条　以暴力、胁迫或者其他方法劫持船只、汽车的，处五年以上十年以下有期徒刑；造成严重后果的，处十年以上有期徒刑或者无期徒刑。\n第一百二十三条　对飞行中的航空器上的人员使用暴力，危及飞行安全，尚未造成严重后果的，处五年以下有期徒刑或者拘役；造成严重后果的，处五年以上有期徒刑。\n第一百二十四条　破坏广播电视设施、公用电信设施，危害公共安全的，处三年以上七年以下有期徒刑；造成严重后果的，处七年以上有期徒刑。\n过失犯前款罪的，处三年以上七年以下有期徒刑；情节较轻的，处三年以下有期徒刑或者拘役。\n第一百二十五条　非法制造、买卖、运输、邮寄、储存枪支、弹药、爆炸物的，处三年以上十年以下有期徒刑；情节严重的，处十年以上有期徒刑、无期徒刑或者死刑。\n非法制造、买卖、运输、储存毒害性、放射性、传染病病原体等物质，危害公共安全的，依照前款的规定处罚。\n单位犯前两款罪的，对单位判处罚金，并对其直接负责的主管人员和其他直接责任人员，依照第一款的规定处罚。\n第一百二十六条　依法被指定、确定的枪支制造企业、销售企业，违反枪支管理规定，有下列行为之一的，对单位判处罚金，并对其直接负责的主管人员和其他直接责任人员，处五年以下有期徒刑；情节严重的，处五年以上十年以下有期徒刑；情节特别严重的，处十年以上有期徒刑或者无期徒刑：\n（一）以非法销售为目的，超过限额或者不按照规定的品种制造、配售枪支的；\n（二）以非法销售为目的，制造无号、重号、假号的枪支的；\n（三）非法销售枪支或者在境内销售为出口制造的枪支的', 795, '{\"level\": null, \"title\": null, \"chunk_index\": 19}', 'bge-large-zh-v1.5', '2026-09-25 17:04:56');
INSERT INTO `chunk` VALUES ('2bd59ab7-34c2-4ff4-af38-5d07f56cedb8', '821ce1fd-178d-4a7e-ab92-3deff1488ce2', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 56, '致人伤残、死亡的，依照本法第二百三十四条、第二百三十二条的规定定罪从重处罚。\n第二百四十八条　监狱、拘留所、看守所等监管机构的监管人员对被监管人进行殴打或者体罚虐待，情节严重的，处三年以下有期徒刑或者拘役；情节特别严重的，处三年以上十年以下有期徒刑。致人伤残、死亡的，依照本法第二百三十四条、第二百三十二条的规定定罪从重处罚。\n监管人员指使被监管人殴打或者体罚虐待其他被监管人的，依照前款的规定处罚。\n第二百四十九条　煽动民族仇恨、民族歧视，情节严重的，处三年以下有期徒刑、拘役、管制或者剥夺政治权利；情节特别严重的，处三年以上十年以下有期徒刑。\n第二百五十条　在出版物中刊载歧视、侮辱少数民族的内容，情节恶劣，造成严重后果的，对直接责任人员，处三年以下有期徒刑、拘役或者管制。\n第二百五十一条　国家机关工作人员非法剥夺公民的宗教信仰自由和侵犯少数民族风俗习惯，情节严重的，处二年以下有期徒刑或者拘役。\n第二百五十二条　隐匿、毁弃或者非法开拆他人信件，侵犯公民通信自由权利，情节严重的，处一年以下有期徒刑或者拘役。\n第二百五十三条　邮政工作人员私自开拆或者隐匿、毁弃邮件、电报的，处二年以下有期徒刑或者拘役。\n犯前款罪而窃取财物的，依照本法第二百六十四条的规定定罪从重处罚。\n第二百五十三条之一　违反国家有关规定，向他人出售或者提供公民个人信息，情节严重的，处三年以下有期徒刑或者拘役，并处或者单处罚金；情节特别严重的，处三年以上七年以下有期徒刑，并处罚金。\n违反国家有关规定，将在履行职责或者提供服务过程中获得的公民个人信息，出售或者提供给他人的，依照前款的规定从重处罚。\n窃取或者以其他方法非法获取公民个人信息的，依照第一款的规定处罚。\n单位犯前三款罪的，对单位判处罚金，并对其直接负责的主管人员和其他直接责任人员，依照各该款的规定处罚', 770, '{\"level\": null, \"title\": null, \"chunk_index\": 56}', 'bge-large-zh-v1.5', '2026-09-25 17:04:56');
INSERT INTO `chunk` VALUES ('2c525d3b-8ef5-426a-9ea7-39fb07ed706a', '821ce1fd-178d-4a7e-ab92-3deff1488ce2', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 48, '第二百一十七条　以营利为目的，有下列侵犯著作权或者与著作权有关的权利的情形之一，违法所得数额较大或者有其他严重情节的，处三年以下有期徒刑，并处或者单处罚金；违法所得数额巨大或者有其他特别严重情节的，处三年以上十年以下有期徒刑，并处罚金：\n（一）未经著作权人许可，复制发行、通过信息网络向公众传播其文字作品、音乐、美术、视听作品、计算机软件及法律、行政法规规定的其他作品的；\n（二）出版他人享有专有出版权的图书的；\n（三）未经录音录像制作者许可，复制发行、通过信息网络向公众传播其制作的录音录像的；\n（四）未经表演者许可，复制发行录有其表演的录音录像制品，或者通过信息网络向公众传播其表演的；\n（五）制作、出售假冒他人署名的美术作品的；\n（六）未经著作权人或者与著作权有关的权利人许可，故意避开或者破坏权利人为其作品、录音录像制品等采取的保护著作权或者与著作权有关的权利的技术措施的。\n第二百一十八条　以营利为目的，销售明知是本法第二百一十七条规定的侵权复制品，违法所得数额巨大或者有其他严重情节的，处五年以下有期徒刑，并处或者单处罚金。\n第二百一十九条　有下列侵犯商业秘密行为之一，情节严重的，处三年以下有期徒刑，并处或者单处罚金；情节特别严重的，处三年以上十年以下有期徒刑，并处罚金：\n（一）以盗窃、贿赂、欺诈、胁迫、电子侵入或者其他不正当手段获取权利人的商业秘密的；\n（二）披露、使用或者允许他人使用以前项手段获取的权利人的商业秘密的；\n（三）违反保密义务或者违反权利人有关保守商业秘密的要求，披露、使用或者允许他人使用其所掌握的商业秘密的。\n明知前款所列行为，获取、披露、使用或者允许他人使用该商业秘密的，以侵犯商业秘密论。\n本条所称权利人，是指商业秘密的所有人和经商业秘密所有人许可的商业秘密使用人', 753, '{\"level\": null, \"title\": null, \"chunk_index\": 48}', 'bge-large-zh-v1.5', '2026-09-25 17:04:56');
INSERT INTO `chunk` VALUES ('2c8ae798-1808-4625-a296-a4f260a4b9da', 'b25ce095-dfba-4403-acf8-c58eb456ca4c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 117, '第一千零二十六条　认定行为人是否尽到前条第二项规定的合理核实义务，应当考虑下列因素：\n（一）内容来源的可信度；\n（二）对明显可能引发争议的内容是否进行了必要的调查；\n（三）内容的时限性；\n（四）内容与公序良俗的关联性；\n（五）受害人名誉受贬损的可能性；\n（六）核实能力和核实成本。\n第一千零二十七条　行为人发表的文学、艺术作品以真人真事或者特定人为描述对象，含有侮辱、诽谤内容，侵害他人名誉权的，受害人有权依法请求该行为人承担民事责任。\n行为人发表的文学、艺术作品不以特定人为描述对象，仅其中的情节与该特定人的情况相似的，不承担民事责任。\n第一千零二十八条　民事主体有证据证明报刊、网络等媒体报道的内容失实，侵害其名誉权的，有权请求该媒体及时采取更正或者删除等必要措施。\n第一千零二十九条　民事主体可以依法查询自己的信用评价；发现信用评价不当的，有权提出异议并请求采取更正、删除等必要措施。信用评价人应当及时核查，经核查属实的，应当及时采取必要措施。\n第一千零三十条　民事主体与征信机构等信用信息处理者之间的关系，适用本编有关个人信息保护的规定和其他法律、行政法规的有关规定。\n第一千零三十一条　民事主体享有荣誉权。任何组织或者个人不得非法剥夺他人的荣誉称号，不得诋毁、贬损他人的荣誉。\n获得的荣誉称号应当记载而没有记载的，民事主体可以请求记载；获得的荣誉称号记载错误的，民事主体可以请求更正。\n第六章　隐私权和个人信息保护\n第一千零三十二条　自然人享有隐私权。任何组织或者个人不得以刺探、侵扰、泄露、公开等方式侵害他人的隐私权。\n隐私是自然人的私人生活安宁和不愿为他人知晓的私密空间、私密活动、私密信息', 702, '{\"level\": null, \"title\": null, \"chunk_index\": 117}', 'bge-large-zh-v1.5', '2026-09-25 17:05:01');
INSERT INTO `chunk` VALUES ('2cdef5c7-1d7c-42ef-9f47-3144718f3637', '16cbea7e-7e36-4f31-afb5-63892345d29c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 72, '第三百一十二条　监察机关应当加强留置场所管理和监督工作，依法规范管理、使用留置场所。\n留置场所应当建立健全保密、消防、医疗、防疫、餐饮及安保等方面安全制度，制定突发事件处置预案，采取安全防范措施，严格落实安全工作责任制。\n发生被强制到案人员、被管护人员、被留置人员或者被禁闭人员死亡、伤残、脱逃等办案安全事故、事件的，应当及时做好处置、处理工作。相关情况应当立即报告监察机关主要负责人，并在二十四小时以内逐级上报至国家监察委员会。\n第三百一十三条　监察机关在维护监督执法调查工作纪律方面失职失责的，依法追究责任。监察人员涉嫌严重职务违法、职务犯罪或者对案件处置出现重大失误的，既应当追究直接责任，还应当严肃追究负有责任的领导人员责任。\n监察机关应当建立办案质量责任制，对滥用职权、失职失责造成严重后果的，实行终身责任追究。\n第八章　法律责任\n第三百一十四条　有关单位拒不执行监察机关依法作出的下列处理决定的，应当由其主管部门、上级机关责令改正，对单位给予通报批评，对负有责任的领导人员和直接责任人员依法给予处理：\n（一）政务处分决定；\n（二）问责决定；\n（三）谈话提醒、批评教育、责令检查，或者予以诫勉的决定；\n（四）采取调查措施的决定；\n（五）复审、复核决定；\n（六）监察机关依法作出的其他处理决定。\n第三百一十五条　监察对象对控告人、申诉人、批评人、检举人、证人、监察人员进行打击、压制等报复陷害的，监察机关应当依法给予政务处分。构成犯罪的，依法追究刑事责任。\n第三百一十六条　控告人、检举人、证人采取捏造事实、伪造材料等方式诬告陷害的，监察机关应当依法给予政务处分，或者移送有关机关处理。构成犯罪的，依法追究刑事责任。\n监察人员因依法履行职责遭受不实举报、诬告陷害、侮辱诽谤，致使名誉受到损害的，监察机关应当会同有关部门及时澄清事实，消除不良影响，并依法追究相关单位或者个人的责任', 793, '{\"level\": null, \"title\": null, \"chunk_index\": 72}', 'bge-large-zh-v1.5', '2026-09-25 17:04:49');
INSERT INTO `chunk` VALUES ('2f2edcf1-8bed-45a7-9f74-2619249b9558', 'd9d7dc15-8041-43b8-9f75-f112fe3ae003', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 0, '中华人民共和国危险化学品安全法\n（2025年12月27日第十四届全国人民代表大会常务委员会第十九次会议通过）\n目　　录\n第一章　总　　则\n第二章　规划布局\n第三章　生产和储存安全\n第四章　使用安全\n第五章　经营安全\n第六章　运输安全\n第七章　危险化学品登记\n第八章　事故应急救援\n第九章　法律责任\n第十章　附　　则\n第一章　总　　则\n第一条　为了加强危险化学品的安全管理，预防和减少危险化学品事故，保障人民群众身体健康、生命安全和财产安全，保护生态环境，制定本法。\n第二条　危险化学品生产、储存、使用、经营和运输的安全管理，适用本法。\n废弃危险化学品的处置，依照有关生态环境保护的法律、行政法规和国家有关规定执行。\n第三条　本法所称危险化学品，是指具有毒害、腐蚀、爆炸、燃烧、助燃等性质，对人体、设施、生态环境具有危害的剧毒化学品和其他化学品。\n国家建立健全危险化学品目录管理制度。危险化学品目录，由国务院应急管理部门会同工业和信息化、公安、生态环境、交通运输、农业农村、卫生健康、海关、市场监督管理、铁路、民用航空等部门，根据化学品危险特性的鉴定和分类标准确定、公布，并适时调整。\n第四条　危险化学品安全管理工作坚持中国共产党的领导。\n危险化学品安全管理工作应当坚持人民至上、生命至上，贯彻总体国家安全观，统筹发展和安全，坚持安全第一、预防为主、综合治理的方针，从源头上防范化解重大安全风险。\n危险化学品安全管理工作实行管行业必须管安全、管业务必须管安全、管生产经营必须管安全，强化和落实单位主体责任与政府监管责任，建立单位负责、职工参与、政府监管、行业自律、社会监督的机制', 688, '{\"level\": null, \"title\": null, \"chunk_index\": 0}', 'bge-large-zh-v1.5', '2026-09-25 17:04:46');
INSERT INTO `chunk` VALUES ('30760453-8722-4b5a-bdc4-cfefdc0dc7f6', '821ce1fd-178d-4a7e-ab92-3deff1488ce2', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 83, '第三百五十九条　引诱、容留、介绍他人卖淫的，处五年以下有期徒刑、拘役或者管制，并处罚金；情节严重的，处五年以上有期徒刑，并处罚金。\n引诱不满十四周岁的幼女卖淫的，处五年以上有期徒刑，并处罚金。\n第三百六十条　明知自己患有梅毒、淋病等严重性病卖淫、嫖娼的，处五年以下有期徒刑、拘役或者管制，并处罚金。\n第三百六十一条　旅馆业、饮食服务业、文化娱乐业、出租汽车业等单位的人员，利用本单位的条件，组织、强迫、引诱、容留、介绍他人卖淫的，依照本法第三百五十八条、第三百五十九条的规定定罪处罚。\n前款所列单位的主要负责人，犯前款罪的，从重处罚。\n第三百六十二条　旅馆业、饮食服务业、文化娱乐业、出租汽车业等单位的人员，在公安机关查处卖淫、嫖娼活动时，为违法犯罪分子通风报信，情节严重的，依照本法第三百一十条的规定定罪处罚。\n第九节　制作、贩卖、传播淫秽物品罪\n第三百六十三条　以牟利为目的，制作、复制、出版、贩卖、传播淫秽物品的，处三年以下有期徒刑、拘役或者管制，并处罚金；情节严重的，处三年以上十年以下有期徒刑，并处罚金；情节特别严重的，处十年以上有期徒刑或者无期徒刑，并处罚金或者没收财产。\n为他人提供书号，出版淫秽书刊的，处三年以下有期徒刑、拘役或者管制，并处或者单处罚金；明知他人用于出版淫秽书刊而提供书号的，依照前款的规定处罚。\n第三百六十四条　传播淫秽的书刊、影片、音像、图片或者其他淫秽物品，情节严重的，处二年以下有期徒刑、拘役或者管制。\n组织播放淫秽的电影、录像等音像制品的，处三年以下有期徒刑、拘役或者管制，并处罚金；情节严重的，处三年以上十年以下有期徒刑，并处罚金。\n制作、复制淫秽的电影、录像等音像制品组织播放的，依照第二款的规定从重处罚。\n向不满十八周岁的未成年人传播淫秽物品的，从重处罚', 751, '{\"level\": null, \"title\": null, \"chunk_index\": 83}', 'bge-large-zh-v1.5', '2026-09-25 17:04:56');
INSERT INTO `chunk` VALUES ('308d6d79-e92f-4d56-bf7c-7fcd4c105638', 'b25ce095-dfba-4403-acf8-c58eb456ca4c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 86, '第七百六十条　融资租赁合同无效，当事人就该情形下租赁物的归属有约定的，按照其约定；没有约定或者约定不明确的，租赁物应当返还出租人。但是，因承租人原因致使合同无效，出租人不请求返还或者返还后会显著降低租赁物效用的，租赁物的所有权归承租人，由承租人给予出租人合理补偿。\n第十六章　保理合同\n第七百六十一条　保理合同是应收账款债权人将现有的或者将有的应收账款转让给保理人，保理人提供资金融通、应收账款管理或者催收、应收账款债务人付款担保等服务的合同。\n第七百六十二条　保理合同的内容一般包括业务类型、服务范围、服务期限、基础交易合同情况、应收账款信息、保理融资款或者服务报酬及其支付方式等条款。\n保理合同应当采用书面形式。\n第七百六十三条　应收账款债权人与债务人虚构应收账款作为转让标的，与保理人订立保理合同的，应收账款债务人不得以应收账款不存在为由对抗保理人，但是保理人明知虚构的除外。\n第七百六十四条　保理人向应收账款债务人发出应收账款转让通知的，应当表明保理人身份并附有必要凭证。\n第七百六十五条　应收账款债务人接到应收账款转让通知后，应收账款债权人与债务人无正当理由协商变更或者终止基础交易合同，对保理人产生不利影响的，对保理人不发生效力。\n第七百六十六条　当事人约定有追索权保理的，保理人可以向应收账款债权人主张返还保理融资款本息或者回购应收账款债权，也可以向应收账款债务人主张应收账款债权。保理人向应收账款债务人主张应收账款债权，在扣除保理融资款本息和相关费用后有剩余的，剩余部分应当返还给应收账款债权人。\n第七百六十七条　当事人约定无追索权保理的，保理人应当向应收账款债务人主张应收账款债权，保理人取得超过保理融资款本息和相关费用的部分，无需向应收账款债权人返还', 735, '{\"level\": null, \"title\": null, \"chunk_index\": 86}', 'bge-large-zh-v1.5', '2026-09-25 17:05:01');
INSERT INTO `chunk` VALUES ('31831dbb-7cfa-4d3b-89f9-e9631c8f798a', '22a2c356-7a68-4455-b657-333e3dba1e1a', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 6, '国家举办各种学校，普及初等义务教育，发展中等教育、职业教育和高等教育，并且发展学前教育。\n国家发展各种教育设施，扫除文盲，对工人、农民、国家工作人员和其他劳动者进行政治、文化、科学、技术、业务的教育，鼓励自学成才。\n国家鼓励集体经济组织、国家企业事业组织和其他社会力量依照法律规定举办各种教育事业。\n国家推广全国通用的普通话。\n第二十条　国家发展自然科学和社会科学事业，普及科学和技术知识，奖励科学研究成果和技术发明创造。\n第二十一条　国家发展医疗卫生事业，发展现代医药和我国传统医药，鼓励和支持农村集体经济组织、国家企业事业组织和街道组织举办各种医疗卫生设施，开展群众性的卫生活动，保护人民健康。\n国家发展体育事业，开展群众性的体育活动，增强人民体质。\n第二十二条　国家发展为人民服务、为社会主义服务的文学艺术事业、新闻广播电视事业、出版发行事业、图书馆博物馆文化馆和其他文化事业，开展群众性的文化活动。\n国家保护名胜古迹、珍贵文物和其他重要历史文化遗产。\n第二十三条　国家培养为社会主义服务的各种专业人才，扩大知识分子的队伍，创造条件，充分发挥他们在社会主义现代化建设中的作用。\n第二十四条　国家通过普及理想教育、道德教育、文化教育、纪律和法制教育，通过在城乡不同范围的群众中制定和执行各种守则、公约，加强社会主义精神文明的建设。\n国家倡导社会主义核心价值观，提倡爱祖国、爱人民、爱劳动、爱科学、爱社会主义的公德，在人民中进行爱国主义、集体主义和国际主义、共产主义的教育，进行辩证唯物主义和历史唯物主义的教育，反对资本主义的、封建主义的和其他的腐朽思想。\n第二十五条　国家推行计划生育，使人口的增长同经济和社会发展计划相适应。\n第二十六条　国家保护和改善生活环境和生态环境，防治污染和其他公害。\n国家组织和鼓励植树造林，保护林木', 766, '{\"level\": null, \"title\": null, \"chunk_index\": 6}', 'bge-large-zh-v1.5', '2026-09-25 17:04:28');
INSERT INTO `chunk` VALUES ('335cad7b-4a04-4a26-8a82-e49da4b696f8', 'b25ce095-dfba-4403-acf8-c58eb456ca4c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 142, '第一千二百三十五条　违反国家规定造成生态环境损害的，国家规定的机关或者法律规定的组织有权请求侵权人赔偿下列损失和费用：\n（一）生态环境受到损害至修复完成期间服务功能丧失导致的损失；\n（二）生态环境功能永久性损害造成的损失；\n（三）生态环境损害调查、鉴定评估等费用；\n（四）清除污染、修复生态环境费用；\n（五）防止损害的发生和扩大所支出的合理费用。\n第八章　高度危险责任\n第一千二百三十六条　从事高度危险作业造成他人损害的，应当承担侵权责任。\n第一千二百三十七条　民用核设施或者运入运出核设施的核材料发生核事故造成他人损害的，民用核设施的营运单位应当承担侵权责任；但是，能够证明损害是因战争、武装冲突、暴乱等情形或者受害人故意造成的，不承担责任。\n第一千二百三十八条　民用航空器造成他人损害的，民用航空器的经营者应当承担侵权责任；但是，能够证明损害是因受害人故意造成的，不承担责任。\n第一千二百三十九条　占有或者使用易燃、易爆、剧毒、高放射性、强腐蚀性、高致病性等高度危险物造成他人损害的，占有人或者使用人应当承担侵权责任；但是，能够证明损害是因受害人故意或者不可抗力造成的，不承担责任。被侵权人对损害的发生有重大过失的，可以减轻占有人或者使用人的责任。\n第一千二百四十条　从事高空、高压、地下挖掘活动或者使用高速轨道运输工具造成他人损害的，经营者应当承担侵权责任；但是，能够证明损害是因受害人故意或者不可抗力造成的，不承担责任。被侵权人对损害的发生有重大过失的，可以减轻经营者的责任。\n第一千二百四十一条　遗失、抛弃高度危险物造成他人损害的，由所有人承担侵权责任。所有人将高度危险物交由他人管理的，由管理人承担侵权责任；所有人有过错的，与管理人承担连带责任。\n第一千二百四十二条　非法占有高度危险物造成他人损害的，由非法占有人承担侵权责任', 769, '{\"level\": null, \"title\": null, \"chunk_index\": 142}', 'bge-large-zh-v1.5', '2026-09-25 17:05:01');
INSERT INTO `chunk` VALUES ('34738845-5b7f-4b8f-ab1c-b19e02f50d75', 'd9d7dc15-8041-43b8-9f75-f112fe3ae003', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 26, '第一百零一条　有下列情形之一的，由负有危险化学品安全监督管理职责的部门按照职责分工责令限期改正，可以处十万元以下的罚款；逾期未改正的，处十万元以上二十万元以下的罚款，对其直接负责的主管人员和其他直接责任人员处二万元以上五万元以下的罚款；情节严重的，责令停产停业整顿：\n（一）危险化学品生产企业、进口企业未提供中文化学品安全技术说明书，或者未在危险化学品包装上粘贴、印刷、拴挂中文化学品安全标签；\n（二）危险化学品生产企业、进口企业提供的中文化学品安全技术说明书与其生产、进口的危险化学品不相符，在危险化学品包装上粘贴、印刷、拴挂的中文化学品安全标签与包装内危险化学品不相符，或者化学品安全技术说明书、化学品安全标签不符合国家标准要求；\n（三）危险化学品生产企业、进口企业发现其生产或者进口的危险化学品有新的危险特性不立即公告，或者不及时修订其化学品安全技术说明书、化学品安全标签；\n（四）生产、储存危险化学品的单位未对其敷设的危险化学品管道设置明显标志，或者未对危险化学品管道定期检查、检测、巡护；\n（五）进行可能危及危险化学品管道安全的施工作业，施工单位未按照规定将施工方案书面通知管道所属单位，未与管道所属单位共同制定应急预案、采取相应的安全防护措施，或者管道所属单位未指派专门人员到现场进行管道安全保护指导；\n（六）危险化学品生产企业从业人员未满足国家规定的学历要求，未接受安全生产教育和培训，或者未经考核合格上岗作业；\n（七）危险化学品包装物、容器的材质以及包装的型式、规格、方法和单件质量与所包装的危险化学品的性质和用途不相适应；\n（八）生产、储存危险化学品的企业以及使用危险化学品从事生产的企业未明确责任人、岗位职责和操作规程', 719, '{\"level\": null, \"title\": null, \"chunk_index\": 26}', 'bge-large-zh-v1.5', '2026-09-25 17:04:46');
INSERT INTO `chunk` VALUES ('35f9c9e3-0d35-4b67-a867-98ac9e6921d9', 'b25ce095-dfba-4403-acf8-c58eb456ca4c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 118, '第一千零三十三条　除法律另有规定或者权利人明确同意外，任何组织或者个人不得实施下列行为：\n（一）以电话、短信、即时通讯工具、电子邮件、传单等方式侵扰他人的私人生活安宁；\n（二）进入、拍摄、窥视他人的住宅、宾馆房间等私密空间；\n（三）拍摄、窥视、窃听、公开他人的私密活动；\n（四）拍摄、窥视他人身体的私密部位；\n（五）处理他人的私密信息；\n（六）以其他方式侵害他人的隐私权。\n第一千零三十四条　自然人的个人信息受法律保护。\n个人信息是以电子或者其他方式记录的能够单独或者与其他信息结合识别特定自然人的各种信息，包括自然人的姓名、出生日期、身份证件号码、生物识别信息、住址、电话号码、电子邮箱、健康信息、行踪信息等。\n个人信息中的私密信息，适用有关隐私权的规定；没有规定的，适用有关个人信息保护的规定。\n第一千零三十五条　处理个人信息的，应当遵循合法、正当、必要原则，不得过度处理，并符合下列条件：\n（一）征得该自然人或者其监护人同意，但是法律、行政法规另有规定的除外；\n（二）公开处理信息的规则；\n（三）明示处理信息的目的、方式和范围；\n（四）不违反法律、行政法规的规定和双方的约定。\n个人信息的处理包括个人信息的收集、存储、使用、加工、传输、提供、公开等。\n第一千零三十六条　处理个人信息，有下列情形之一的，行为人不承担民事责任：\n（一）在该自然人或者其监护人同意的范围内合理实施的行为；\n（二）合理处理该自然人自行公开的或者其他已经合法公开的信息，但是该自然人明确拒绝或者处理该信息侵害其重大利益的除外；\n（三）为维护公共利益或者该自然人合法权益，合理实施的其他行为。\n第一千零三十七条　自然人可以依法向信息处理者查阅或者复制其个人信息；发现信息有错误的，有权提出异议并请求及时采取更正等必要措施', 749, '{\"level\": null, \"title\": null, \"chunk_index\": 118}', 'bge-large-zh-v1.5', '2026-09-25 17:05:01');
INSERT INTO `chunk` VALUES ('36eefe27-3a3b-43ec-894b-745a8649385b', '22a2c356-7a68-4455-b657-333e3dba1e1a', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 16, '第七十六条　全国人民代表大会代表必须模范地遵守宪法和法律，保守国家秘密，并且在自己参加的生产、工作和社会活动中，协助宪法和法律的实施。\n全国人民代表大会代表应当同原选举单位和人民保持密切的联系，听取和反映人民的意见和要求，努力为人民服务。\n第七十七条　全国人民代表大会代表受原选举单位的监督。原选举单位有权依照法律规定的程序罢免本单位选出的代表。\n第七十八条　全国人民代表大会和全国人民代表大会常务委员会的组织和工作程序由法律规定。\n第二节　中华人民共和国主席\n第七十九条　中华人民共和国主席、副主席由全国人民代表大会选举。\n有选举权和被选举权的年满四十五周岁的中华人民共和国公民可以被选为中华人民共和国主席、副主席。\n中华人民共和国主席、副主席每届任期同全国人民代表大会每届任期相同。\n第八十条　中华人民共和国主席根据全国人民代表大会的决定和全国人民代表大会常务委员会的决定，公布法律，任免国务院总理、副总理、国务委员、各部部长、各委员会主任、审计长、秘书长，授予国家的勋章和荣誉称号，发布特赦令，宣布进入紧急状态，宣布战争状态，发布动员令。\n第八十一条　中华人民共和国主席代表中华人民共和国，进行国事活动，接受外国使节；根据全国人民代表大会常务委员会的决定，派遣和召回驻外全权代表，批准和废除同外国缔结的条约和重要协定。\n第八十二条　中华人民共和国副主席协助主席工作。\n中华人民共和国副主席受主席的委托，可以代行主席的部分职权。\n第八十三条　中华人民共和国主席、副主席行使职权到下届全国人民代表大会选出的主席、副主席就职为止。\n第八十四条　中华人民共和国主席缺位的时候，由副主席继任主席的职位。\n中华人民共和国副主席缺位的时候，由全国人民代表大会补选。\n中华人民共和国主席、副主席都缺位的时候，由全国人民代表大会补选；在补选以前，由全国人民代表大会常务委员会委员长暂时代理主席职位', 792, '{\"level\": null, \"title\": null, \"chunk_index\": 16}', 'bge-large-zh-v1.5', '2026-09-25 17:04:29');
INSERT INTO `chunk` VALUES ('372b9233-a1d6-4258-8be4-0e8ebd965036', 'b25ce095-dfba-4403-acf8-c58eb456ca4c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 38, '第三百三十九条　土地承包经营权人可以自主决定依法采取出租、入股或者其他方式向他人流转土地经营权。\n第三百四十条　土地经营权人有权在合同约定的期限内占有农村土地，自主开展农业生产经营并取得收益。\n第三百四十一条　流转期限为五年以上的土地经营权，自流转合同生效时设立。当事人可以向登记机构申请土地经营权登记；未经登记，不得对抗善意第三人。\n第三百四十二条　通过招标、拍卖、公开协商等方式承包农村土地，经依法登记取得权属证书的，可以依法采取出租、入股、抵押或者其他方式流转土地经营权。\n第三百四十三条　国家所有的农用地实行承包经营的，参照适用本编的有关规定。\n第十二章　建设用地使用权\n第三百四十四条　建设用地使用权人依法对国家所有的土地享有占有、使用和收益的权利，有权利用该土地建造建筑物、构筑物及其附属设施。\n第三百四十五条　建设用地使用权可以在土地的地表、地上或者地下分别设立。\n第三百四十六条　设立建设用地使用权，应当符合节约资源、保护生态环境的要求，遵守法律、行政法规关于土地用途的规定，不得损害已经设立的用益物权。\n第三百四十七条　设立建设用地使用权，可以采取出让或者划拨等方式。\n工业、商业、旅游、娱乐和商品住宅等经营性用地以及同一土地有两个以上意向用地者的，应当采取招标、拍卖等公开竞价的方式出让。\n严格限制以划拨方式设立建设用地使用权。\n第三百四十八条　通过招标、拍卖、协议等出让方式设立建设用地使用权的，当事人应当采用书面形式订立建设用地使用权出让合同。\n建设用地使用权出让合同一般包括下列条款：\n（一）当事人的名称和住所；\n（二）土地界址、面积等；\n（三）建筑物、构筑物及其附属设施占用的空间；\n（四）土地用途、规划条件；\n（五）建设用地使用权期限；\n（六）出让金等费用及其支付方式；\n（七）解决争议的方法。\n第三百四十九条　设立建设用地使用权的，应当向登记机构申请建设用地使用权登记', 800, '{\"level\": null, \"title\": null, \"chunk_index\": 38}', 'bge-large-zh-v1.5', '2026-09-25 17:05:01');
INSERT INTO `chunk` VALUES ('374af704-19e2-44fa-9b02-0c0368d9d763', '22a2c356-7a68-4455-b657-333e3dba1e1a', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 7, '第二十七条　一切国家机关实行精简的原则，实行工作责任制，实行工作人员的培训和考核制度，不断提高工作质量和工作效率，反对官僚主义。\n一切国家机关和国家工作人员必须依靠人民的支持，经常保持同人民的密切联系，倾听人民的意见和建议，接受人民的监督，努力为人民服务。\n国家工作人员就职时应当依照法律规定公开进行宪法宣誓。\n第二十八条　国家维护社会秩序，镇压叛国和其他危害国家安全的犯罪活动，制裁危害社会治安、破坏社会主义经济和其他犯罪的活动，惩办和改造犯罪分子。\n第二十九条　中华人民共和国的武装力量属于人民。它的任务是巩固国防，抵抗侵略，保卫祖国，保卫人民的和平劳动，参加国家建设事业，努力为人民服务。\n国家加强武装力量的革命化、现代化、正规化的建设，增强国防力量。\n第三十条　中华人民共和国的行政区域划分如下：\n（一）全国分为省、自治区、直辖市；\n（二）省、自治区分为自治州、县、自治县、市；\n（三）县、自治县分为乡、民族乡、镇。\n直辖市和较大的市分为区、县。自治州分为县、自治县、市。\n自治区、自治州、自治县都是民族自治地方。\n第三十一条　国家在必要时得设立特别行政区。在特别行政区内实行的制度按照具体情况由全国人民代表大会以法律规定。\n第三十二条　中华人民共和国保护在中国境内的外国人的合法权利和利益，在中国境内的外国人必须遵守中华人民共和国的法律。\n中华人民共和国对于因为政治原因要求避难的外国人，可以给予受庇护的权利。\n第二章　公民的基本权利和义务\n第三十三条　凡具有中华人民共和国国籍的人都是中华人民共和国公民。\n中华人民共和国公民在法律面前一律平等。\n国家尊重和保障人权。\n任何公民享有宪法和法律规定的权利，同时必须履行宪法和法律规定的义务', 723, '{\"level\": null, \"title\": null, \"chunk_index\": 7}', 'bge-large-zh-v1.5', '2026-09-25 17:04:28');
INSERT INTO `chunk` VALUES ('381ae323-e13f-4dd2-a564-5d50675769b9', 'b25ce095-dfba-4403-acf8-c58eb456ca4c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 40, '第三百六十一条　集体所有的土地作为建设用地的，应当依照土地管理的法律规定办理。\n第十三章　宅基地使用权\n第三百六十二条　宅基地使用权人依法对集体所有的土地享有占有和使用的权利，有权依法利用该土地建造住宅及其附属设施。\n第三百六十三条　宅基地使用权的取得、行使和转让，适用土地管理的法律和国家有关规定。\n第三百六十四条　宅基地因自然灾害等原因灭失的，宅基地使用权消灭。对失去宅基地的村民，应当依法重新分配宅基地。\n第三百六十五条　已经登记的宅基地使用权转让或者消灭的，应当及时办理变更登记或者注销登记。\n第十四章　居住权\n第三百六十六条　居住权人有权按照合同约定，对他人的住宅享有占有、使用的用益物权，以满足生活居住的需要。\n第三百六十七条　设立居住权，当事人应当采用书面形式订立居住权合同。\n居住权合同一般包括下列条款：\n（一）当事人的姓名或者名称和住所；\n（二）住宅的位置；\n（三）居住的条件和要求；\n（四）居住权期限；\n（五）解决争议的方法。\n第三百六十八条　居住权无偿设立，但是当事人另有约定的除外。设立居住权的，应当向登记机构申请居住权登记。居住权自登记时设立。\n第三百六十九条　居住权不得转让、继承。设立居住权的住宅不得出租，但是当事人另有约定的除外。\n第三百七十条　居住权期限届满或者居住权人死亡的，居住权消灭。居住权消灭的，应当及时办理注销登记。\n第三百七十一条　以遗嘱方式设立居住权的，参照适用本章的有关规定。\n第十五章　地役权\n第三百七十二条　地役权人有权按照合同约定，利用他人的不动产，以提高自己的不动产的效益。\n前款所称他人的不动产为供役地，自己的不动产为需役地。\n第三百七十三条　设立地役权，当事人应当采用书面形式订立地役权合同', 726, '{\"level\": null, \"title\": null, \"chunk_index\": 40}', 'bge-large-zh-v1.5', '2026-09-25 17:05:01');
INSERT INTO `chunk` VALUES ('3969f32a-3432-4ed2-b6d8-c7ba4e68b81e', '821ce1fd-178d-4a7e-ab92-3deff1488ce2', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 45, '第二百零五条　虚开增值税专用发票或者虚开用于骗取出口退税、抵扣税款的其他发票的，处三年以下有期徒刑或者拘役，并处二万元以上二十万元以下罚金；虚开的税款数额较大或者有其他严重情节的，处三年以上十年以下有期徒刑，并处五万元以上五十万元以下罚金；虚开的税款数额巨大或者有其他特别严重情节的，处十年以上有期徒刑或者无期徒刑，并处五万元以上五十万元以下罚金或者没收财产。\n单位犯本条规定之罪的，对单位判处罚金，并对其直接负责的主管人员和其他直接责任人员，处三年以下有期徒刑或者拘役；虚开的税款数额较大或者有其他严重情节的，处三年以上十年以下有期徒刑；虚开的税款数额巨大或者有其他特别严重情节的，处十年以上有期徒刑或者无期徒刑。\n虚开增值税专用发票或者虚开用于骗取出口退税、抵扣税款的其他发票，是指有为他人虚开、为自己虚开、让他人为自己虚开、介绍他人虚开行为之一的。\n第二百零五条之一　虚开本法第二百零五条规定以外的其他发票，情节严重的，处二年以下有期徒刑、拘役或者管制，并处罚金；情节特别严重的，处二年以上七年以下有期徒刑，并处罚金。\n单位犯前款罪的，对单位判处罚金，并对其直接负责的主管人员和其他直接责任人员，依照前款的规定处罚。\n第二百零六条　伪造或者出售伪造的增值税专用发票的，处三年以下有期徒刑、拘役或者管制，并处二万元以上二十万元以下罚金；数量较大或者有其他严重情节的，处三年以上十年以下有期徒刑，并处五万元以上五十万元以下罚金；数量巨大或者有其他特别严重情节的，处十年以上有期徒刑或者无期徒刑，并处五万元以上五十万元以下罚金或者没收财产。\n单位犯本条规定之罪的，对单位判处罚金，并对其直接负责的主管人员和其他直接责任人员，处三年以下有期徒刑、拘役或者管制；数量较大或者有其他严重情节的，处三年以上十年以下有期徒刑；数量巨大或者有其他特别严重情节的，处十年以上有期徒刑或者无期徒刑', 790, '{\"level\": null, \"title\": null, \"chunk_index\": 45}', 'bge-large-zh-v1.5', '2026-09-25 17:04:56');
INSERT INTO `chunk` VALUES ('39a21976-ff83-4e83-b97a-b7aa75cc9b17', 'b25ce095-dfba-4403-acf8-c58eb456ca4c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 55, '依照法律、行政法规的规定负有发出要约义务的当事人，应当及时发出合理的要约。\n依照法律、行政法规的规定负有作出承诺义务的当事人，不得拒绝对方合理的订立合同要求。\n第四百九十五条　当事人约定在将来一定期限内订立合同的认购书、订购书、预订书等，构成预约合同。\n当事人一方不履行预约合同约定的订立合同义务的，对方可以请求其承担预约合同的违约责任。\n第四百九十六条　格式条款是当事人为了重复使用而预先拟定，并在订立合同时未与对方协商的条款。\n采用格式条款订立合同的，提供格式条款的一方应当遵循公平原则确定当事人之间的权利和义务，并采取合理的方式提示对方注意免除或者减轻其责任等与对方有重大利害关系的条款，按照对方的要求，对该条款予以说明。提供格式条款的一方未履行提示或者说明义务，致使对方没有注意或者理解与其有重大利害关系的条款的，对方可以主张该条款不成为合同的内容。\n第四百九十七条　有下列情形之一的，该格式条款无效：\n（一）具有本法第一编第六章第三节和本法第五百零六条规定的无效情形；\n（二）提供格式条款一方不合理地免除或者减轻其责任、加重对方责任、限制对方主要权利；\n（三）提供格式条款一方排除对方主要权利。\n第四百九十八条　对格式条款的理解发生争议的，应当按照通常理解予以解释。对格式条款有两种以上解释的，应当作出不利于提供格式条款一方的解释。格式条款和非格式条款不一致的，应当采用非格式条款。\n第四百九十九条　悬赏人以公开方式声明对完成特定行为的人支付报酬的，完成该行为的人可以请求其支付。\n第五百条　当事人在订立合同过程中有下列情形之一，造成对方损失的，应当承担赔偿责任：\n（一）假借订立合同，恶意进行磋商；\n（二）故意隐瞒与订立合同有关的重要事实或者提供虚假情况；\n（三）有其他违背诚信原则的行为', 750, '{\"level\": null, \"title\": null, \"chunk_index\": 55}', 'bge-large-zh-v1.5', '2026-09-25 17:05:01');
INSERT INTO `chunk` VALUES ('39a88816-d205-4be7-b04f-5e574c252232', '821ce1fd-178d-4a7e-ab92-3deff1488ce2', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 32, '第一百六十九条之一　上市公司的董事、监事、高级管理人员违背对公司的忠实义务，利用职务便利，操纵上市公司从事下列行为之一，致使上市公司利益遭受重大损失的，处三年以下有期徒刑或者拘役，并处或者单处罚金；致使上市公司利益遭受特别重大损失的，处三年以上七年以下有期徒刑，并处罚金：\n（一）无偿向其他单位或者个人提供资金、商品、服务或者其他资产的；\n（二）以明显不公平的条件，提供或者接受资金、商品、服务或者其他资产的；\n（三）向明显不具有清偿能力的单位或者个人提供资金、商品、服务或者其他资产的；\n（四）为明显不具有清偿能力的单位或者个人提供担保，或者无正当理由为其他单位或者个人提供担保的；\n（五）无正当理由放弃债权、承担债务的；\n（六）采用其他方式损害上市公司利益的。\n上市公司的控股股东或者实际控制人，指使上市公司董事、监事、高级管理人员实施前款行为的，依照前款的规定处罚。\n犯前款罪的上市公司的控股股东或者实际控制人是单位的，对单位判处罚金，并对其直接负责的主管人员和其他直接责任人员，依照第一款的规定处罚。\n第四节　破坏金融管理秩序罪\n第一百七十条　伪造货币的，处三年以上十年以下有期徒刑，并处罚金；有下列情形之一的，处十年以上有期徒刑或者无期徒刑，并处罚金或者没收财产：\n（一）伪造货币集团的首要分子；\n（二）伪造货币数额特别巨大的；\n（三）有其他特别严重情节的。\n第一百七十一条　出售、购买伪造的货币或者明知是伪造的货币而运输，数额较大的，处三年以下有期徒刑或者拘役，并处二万元以上二十万元以下罚金；数额巨大的，处三年以上十年以下有期徒刑，并处五万元以上五十万元以下罚金；数额特别巨大的，处十年以上有期徒刑或者无期徒刑，并处五万元以上五十万元以下罚金或者没收财产', 734, '{\"level\": null, \"title\": null, \"chunk_index\": 32}', 'bge-large-zh-v1.5', '2026-09-25 17:04:56');
INSERT INTO `chunk` VALUES ('3c1dbb7c-ad55-45ca-bbf9-82b723b93036', '0497a5e7-7044-4b18-8fed-af3fb7bc7890', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 8, '免抵退税办法，是指出口环节免征增值税，对应的进项税额抵减应纳增值税税额，未抵减完的部分予以退还；免退税办法，是指出口环节免征增值税，对应的进项税额予以退还。\n第四十八条　纳税人适用退（免）税、免征增值税的出口业务，应当按照规定期限申报；逾期未申报的，按照视同向境内销售的规定缴纳增值税。\n纳税人以委托方式出口货物的，应当按照国务院税务主管部门的规定办理委托代理出口手续，由委托方按规定申报办理出口退（免）税、免征增值税或者缴纳增值税；未办理委托代理出口手续的，由出口货物的发货人按规定申报缴纳增值税。\n第四十九条　纳税人适用退（免）税的出口业务，可以放弃退（免）税，选择免征增值税或者缴纳增值税，自放弃退（免）税之日次月起，适用退（免）税的出口业务免征增值税或者按规定缴纳增值税。\n纳税人适用免征增值税的出口业务，可以放弃免征增值税，选择缴纳增值税，自放弃免征增值税之日次月起，适用免征增值税的出口业务按规定缴纳增值税。\n纳税人放弃退（免）税或者免征增值税的出口业务，在36个月内不得再次适用退（免）税或者免征增值税。\n第五十条　办理退（免）税的出口业务发生销售折让、中止或者退回等情形的，纳税人应当缴回已退（免）税款。\n第五十一条　增值税出口退（免）税的具体操作办法，由国务院财政、税务主管部门制定。\n第五十二条　税务机关可以依法向有关单位和个人获取与出口税收征收管理相关的物流、报关、货物运输代理、资金结算等信息，有关单位和个人应当予以提供。税务机关及其工作人员应当对相关信息予以保密，不得用于税收征收管理以外的用途。法律、行政法规另有规定的，从其规定。\n第五十三条　纳税人实施不具有合理商业目的的安排而减少、免除、推迟缴纳增值税税款，或者提前退税、多退税款的，税务机关可以依照《中华人民共和国税收征收管理法》和有关行政法规的规定予以调整', 771, '{\"level\": null, \"title\": null, \"chunk_index\": 8}', 'bge-large-zh-v1.5', '2026-09-25 17:04:28');
INSERT INTO `chunk` VALUES ('3ce5c79a-a997-41ad-85f7-7d009d652b62', 'b25ce095-dfba-4403-acf8-c58eb456ca4c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 72, '对支付时间没有约定或者约定不明确，依据本法第五百一十条的规定仍不能确定的，买受人应当在收到标的物或者提取标的物单证的同时支付。\n第六百二十九条　出卖人多交标的物的，买受人可以接收或者拒绝接收多交的部分。买受人接收多交部分的，按照约定的价格支付价款；买受人拒绝接收多交部分的，应当及时通知出卖人。\n第六百三十条　标的物在交付之前产生的孳息，归出卖人所有；交付之后产生的孳息，归买受人所有。但是，当事人另有约定的除外。\n第六百三十一条　因标的物的主物不符合约定而解除合同的，解除合同的效力及于从物。因标的物的从物不符合约定被解除的，解除的效力不及于主物。\n第六百三十二条　标的物为数物，其中一物不符合约定的，买受人可以就该物解除。但是，该物与他物分离使标的物的价值显受损害的，买受人可以就数物解除合同。\n第六百三十三条　出卖人分批交付标的物的，出卖人对其中一批标的物不交付或者交付不符合约定，致使该批标的物不能实现合同目的的，买受人可以就该批标的物解除。\n出卖人不交付其中一批标的物或者交付不符合约定，致使之后其他各批标的物的交付不能实现合同目的的，买受人可以就该批以及之后其他各批标的物解除。\n买受人如果就其中一批标的物解除，该批标的物与其他各批标的物相互依存的，可以就已经交付和未交付的各批标的物解除。\n第六百三十四条　分期付款的买受人未支付到期价款的数额达到全部价款的五分之一，经催告后在合理期限内仍未支付到期价款的，出卖人可以请求买受人支付全部价款或者解除合同。\n出卖人解除合同的，可以向买受人请求支付该标的物的使用费。\n第六百三十五条　凭样品买卖的当事人应当封存样品，并可以对样品质量予以说明。出卖人交付的标的物应当与样品及其说明的质量相同。\n第六百三十六条　凭样品买卖的买受人不知道样品有隐蔽瑕疵的，即使交付的标的物与样品相同，出卖人交付的标的物的质量仍然应当符合同种物的通常标准', 794, '{\"level\": null, \"title\": null, \"chunk_index\": 72}', 'bge-large-zh-v1.5', '2026-09-25 17:05:01');
INSERT INTO `chunk` VALUES ('3f3d8671-062f-428d-ab05-3baa58e40866', '821ce1fd-178d-4a7e-ab92-3deff1488ce2', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 12, '第六节　减　　刑\n第七十八条　被判处管制、拘役、有期徒刑、无期徒刑的犯罪分子，在执行期间，如果认真遵守监规，接受教育改造，确有悔改表现的，或者有立功表现的，可以减刑；有下列重大立功表现之一的，应当减刑：\n（一）阻止他人重大犯罪活动的；\n（二）检举监狱内外重大犯罪活动，经查证属实的；\n（三）有发明创造或者重大技术革新的；\n（四）在日常生产、生活中舍己救人的；\n（五）在抗御自然灾害或者排除重大事故中，有突出表现的；\n（六）对国家和社会有其他重大贡献的。\n减刑以后实际执行的刑期不能少于下列期限：\n（一）判处管制、拘役、有期徒刑的，不能少于原判刑期的二分之一；\n（二）判处无期徒刑的，不能少于十三年；\n（三）人民法院依照本法第五十条第二款规定限制减刑的死刑缓期执行的犯罪分子，缓期执行期满后依法减为无期徒刑的，不能少于二十五年，缓期执行期满后依法减为二十五年有期徒刑的，不能少于二十年。\n第七十九条　对于犯罪分子的减刑，由执行机关向中级以上人民法院提出减刑建议书。人民法院应当组成合议庭进行审理，对确有悔改或者立功事实的，裁定予以减刑。非经法定程序不得减刑。\n第八十条　无期徒刑减为有期徒刑的刑期，从裁定减刑之日起计算。\n第七节　假　　释\n第八十一条　被判处有期徒刑的犯罪分子，执行原判刑期二分之一以上，被判处无期徒刑的犯罪分子，实际执行十三年以上，如果认真遵守监规，接受教育改造，确有悔改表现，没有再犯罪的危险的，可以假释。如果有特殊情况，经最高人民法院核准，可以不受上述执行刑期的限制。\n对累犯以及因故意杀人、强奸、抢劫、绑架、放火、爆炸、投放危险物质或者有组织的暴力性犯罪被判处十年以上有期徒刑、无期徒刑的犯罪分子，不得假释。\n对犯罪分子决定假释时，应当考虑其假释后对所居住社区的影响。\n第八十二条　对于犯罪分子的假释，依照本法第七十九条规定的程序进行。非经法定程序不得假释', 789, '{\"level\": null, \"title\": null, \"chunk_index\": 12}', 'bge-large-zh-v1.5', '2026-09-25 17:04:56');
INSERT INTO `chunk` VALUES ('3f437cb5-351c-4c46-adab-579efba34e06', 'b25ce095-dfba-4403-acf8-c58eb456ca4c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 102, '但是，无偿保管人证明自己没有故意或者重大过失的，不承担赔偿责任。\n第八百九十八条　寄存人寄存货币、有价证券或者其他贵重物品的，应当向保管人声明，由保管人验收或者封存；寄存人未声明的，该物品毁损、灭失后，保管人可以按照一般物品予以赔偿。\n第八百九十九条　寄存人可以随时领取保管物。\n当事人对保管期限没有约定或者约定不明确的，保管人可以随时请求寄存人领取保管物；约定保管期限的，保管人无特别事由，不得请求寄存人提前领取保管物。\n第九百条　保管期限届满或者寄存人提前领取保管物的，保管人应当将原物及其孳息归还寄存人。\n第九百零一条　保管人保管货币的，可以返还相同种类、数量的货币；保管其他可替代物的，可以按照约定返还相同种类、品质、数量的物品。\n第九百零二条　有偿的保管合同，寄存人应当按照约定的期限向保管人支付保管费。\n当事人对支付期限没有约定或者约定不明确，依据本法第五百一十条的规定仍不能确定的，应当在领取保管物的同时支付。\n第九百零三条　寄存人未按照约定支付保管费或者其他费用的，保管人对保管物享有留置权，但是当事人另有约定的除外。\n第二十二章　仓储合同\n第九百零四条　仓储合同是保管人储存存货人交付的仓储物，存货人支付仓储费的合同。\n第九百零五条　仓储合同自保管人和存货人意思表示一致时成立。\n第九百零六条　储存易燃、易爆、有毒、有腐蚀性、有放射性等危险物品或者易变质物品的，存货人应当说明该物品的性质，提供有关资料。\n存货人违反前款规定的，保管人可以拒收仓储物，也可以采取相应措施以避免损失的发生，因此产生的费用由存货人负担。\n保管人储存易燃、易爆、有毒、有腐蚀性、有放射性等危险物品的，应当具备相应的保管条件。\n第九百零七条　保管人应当按照约定对入库仓储物进行验收。保管人验收时发现入库仓储物与约定不符合的，应当及时通知存货人', 767, '{\"level\": null, \"title\": null, \"chunk_index\": 102}', 'bge-large-zh-v1.5', '2026-09-25 17:05:01');
INSERT INTO `chunk` VALUES ('3f81f8f1-01d8-4188-958b-0d2fec95f7af', '22a2c356-7a68-4455-b657-333e3dba1e1a', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 1, '中华人民共和国成立以后，我国社会逐步实现了由新民主主义到社会主义的过渡。生产资料私有制的社会主义改造已经完成，人剥削人的制度已经消灭，社会主义制度已经确立。工人阶级领导的、以工农联盟为基础的人民民主专政，实质上即无产阶级专政，得到巩固和发展。中国人民和中国人民解放军战胜了帝国主义、霸权主义的侵略、破坏和武装挑衅，维护了国家的独立和安全，增强了国防。经济建设取得了重大的成就，独立的、比较完整的社会主义工业体系已经基本形成，农业生产显著提高。教育、科学、文化等事业有了很大的发展，社会主义思想教育取得了明显的成效。广大人民的生活有了较大的改善。\n中国新民主主义革命的胜利和社会主义事业的成就，是中国共产党领导中国各族人民，在马克思列宁主义、毛泽东思想的指引下，坚持真理，修正错误，战胜许多艰难险阻而取得的。我国将长期处于社会主义初级阶段。国家的根本任务是，沿着中国特色社会主义道路，集中力量进行社会主义现代化建设。中国各族人民将继续在中国共产党领导下，在马克思列宁主义、毛泽东思想、邓小平理论、“三个代表”重要思想、科学发展观、习近平新时代中国特色社会主义思想指引下，坚持人民民主专政，坚持社会主义道路，坚持改革开放，不断完善社会主义的各项制度，发展社会主义市场经济，发展社会主义民主，健全社会主义法治，贯彻新发展理念，自力更生，艰苦奋斗，逐步实现工业、农业、国防和科学技术的现代化，推动物质文明、政治文明、精神文明、社会文明、生态文明协调发展，把我国建设成为富强民主文明和谐美丽的社会主义现代化强国，实现中华民族伟大复兴。\n在我国，剥削阶级作为阶级已经消灭，但是阶级斗争还将在一定范围内长期存在。中国人民对敌视和破坏我国社会主义制度的国内外的敌对势力和敌对分子，必须进行斗争。\n台湾是中华人民共和国的神圣领土的一部分。完成统一祖国的大业是包括台湾同胞在内的全中国人民的神圣职责', 789, '{\"level\": null, \"title\": null, \"chunk_index\": 1}', 'bge-large-zh-v1.5', '2026-09-25 17:04:28');
INSERT INTO `chunk` VALUES ('3fe8d9f3-bab1-45fb-9dfe-af36b75528ea', 'b25ce095-dfba-4403-acf8-c58eb456ca4c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 53, '第四百七十七条　撤销要约的意思表示以对话方式作出的，该意思表示的内容应当在受要约人作出承诺之前为受要约人所知道；撤销要约的意思表示以非对话方式作出的，应当在受要约人作出承诺之前到达受要约人。\n第四百七十八条　有下列情形之一的，要约失效：\n（一）要约被拒绝；\n（二）要约被依法撤销；\n（三）承诺期限届满，受要约人未作出承诺；\n（四）受要约人对要约的内容作出实质性变更。\n第四百七十九条　承诺是受要约人同意要约的意思表示。\n第四百八十条　承诺应当以通知的方式作出；但是，根据交易习惯或者要约表明可以通过行为作出承诺的除外。\n第四百八十一条　承诺应当在要约确定的期限内到达要约人。\n要约没有确定承诺期限的，承诺应当依照下列规定到达：\n（一）要约以对话方式作出的，应当即时作出承诺；\n（二）要约以非对话方式作出的，承诺应当在合理期限内到达。\n第四百八十二条　要约以信件或者电报作出的，承诺期限自信件载明的日期或者电报交发之日开始计算。信件未载明日期的，自投寄该信件的邮戳日期开始计算。要约以电话、传真、电子邮件等快速通讯方式作出的，承诺期限自要约到达受要约人时开始计算。\n第四百八十三条　承诺生效时合同成立，但是法律另有规定或者当事人另有约定的除外。\n第四百八十四条　以通知方式作出的承诺，生效的时间适用本法第一百三十七条的规定。\n承诺不需要通知的，根据交易习惯或者要约的要求作出承诺的行为时生效。\n第四百八十五条　承诺可以撤回。承诺的撤回适用本法第一百四十一条的规定。\n第四百八十六条　受要约人超过承诺期限发出承诺，或者在承诺期限内发出承诺，按照通常情形不能及时到达要约人的，为新要约；但是，要约人及时通知受要约人该承诺有效的除外', 712, '{\"level\": null, \"title\": null, \"chunk_index\": 53}', 'bge-large-zh-v1.5', '2026-09-25 17:05:01');
INSERT INTO `chunk` VALUES ('4010f9e7-2b11-4ed5-b6bf-0e9ece10cf7c', 'b25ce095-dfba-4403-acf8-c58eb456ca4c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 25, '第二百一十二条　登记机构应当履行下列职责：\n（一）查验申请人提供的权属证明和其他必要材料；\n（二）就有关登记事项询问申请人；\n（三）如实、及时登记有关事项；\n（四）法律、行政法规规定的其他职责。\n申请登记的不动产的有关情况需要进一步证明的，登记机构可以要求申请人补充材料，必要时可以实地查看。\n第二百一十三条　登记机构不得有下列行为：\n（一）要求对不动产进行评估；\n（二）以年检等名义进行重复登记；\n（三）超出登记职责范围的其他行为。\n第二百一十四条　不动产物权的设立、变更、转让和消灭，依照法律规定应当登记的，自记载于不动产登记簿时发生效力。\n第二百一十五条　当事人之间订立有关设立、变更、转让和消灭不动产物权的合同，除法律另有规定或者当事人另有约定外，自合同成立时生效；未办理物权登记的，不影响合同效力。\n第二百一十六条　不动产登记簿是物权归属和内容的根据。\n不动产登记簿由登记机构管理。\n第二百一十七条　不动产权属证书是权利人享有该不动产物权的证明。不动产权属证书记载的事项，应当与不动产登记簿一致；记载不一致的，除有证据证明不动产登记簿确有错误外，以不动产登记簿为准。\n第二百一十八条　权利人、利害关系人可以申请查询、复制不动产登记资料，登记机构应当提供。\n第二百一十九条　利害关系人不得公开、非法使用权利人的不动产登记资料。\n第二百二十条　权利人、利害关系人认为不动产登记簿记载的事项错误的，可以申请更正登记。不动产登记簿记载的权利人书面同意更正或者有证据证明登记确有错误的，登记机构应当予以更正。\n不动产登记簿记载的权利人不同意更正的，利害关系人可以申请异议登记。登记机构予以异议登记，申请人自异议登记之日起十五日内不提起诉讼的，异议登记失效。异议登记不当，造成权利人损害的，权利人可以向申请人请求损害赔偿', 759, '{\"level\": null, \"title\": null, \"chunk_index\": 25}', 'bge-large-zh-v1.5', '2026-09-25 17:05:01');
INSERT INTO `chunk` VALUES ('40a6d638-24e8-4630-97ec-6bd88e69bf53', '22a2c356-7a68-4455-b657-333e3dba1e1a', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 8, '第三十四条　中华人民共和国年满十八周岁的公民，不分民族、种族、性别、职业、家庭出身、宗教信仰、教育程度、财产状况、居住期限，都有选举权和被选举权；但是依照法律被剥夺政治权利的人除外。\n第三十五条　中华人民共和国公民有言论、出版、集会、结社、游行、示威的自由。\n第三十六条　中华人民共和国公民有宗教信仰自由。\n任何国家机关、社会团体和个人不得强制公民信仰宗教或者不信仰宗教，不得歧视信仰宗教的公民和不信仰宗教的公民。\n国家保护正常的宗教活动。任何人不得利用宗教进行破坏社会秩序、损害公民身体健康、妨碍国家教育制度的活动。\n宗教团体和宗教事务不受外国势力的支配。\n第三十七条　中华人民共和国公民的人身自由不受侵犯。\n任何公民，非经人民检察院批准或者决定或者人民法院决定，并由公安机关执行，不受逮捕。\n禁止非法拘禁和以其他方法非法剥夺或者限制公民的人身自由，禁止非法搜查公民的身体。\n第三十八条　中华人民共和国公民的人格尊严不受侵犯。禁止用任何方法对公民进行侮辱、诽谤和诬告陷害。\n第三十九条　中华人民共和国公民的住宅不受侵犯。禁止非法搜查或者非法侵入公民的住宅。\n第四十条　中华人民共和国公民的通信自由和通信秘密受法律的保护。除因国家安全或者追查刑事犯罪的需要，由公安机关或者检察机关依照法律规定的程序对通信进行检查外，任何组织或者个人不得以任何理由侵犯公民的通信自由和通信秘密。\n第四十一条　中华人民共和国公民对于任何国家机关和国家工作人员，有提出批评和建议的权利；对于任何国家机关和国家工作人员的违法失职行为，有向有关国家机关提出申诉、控告或者检举的权利，但是不得捏造或者歪曲事实进行诬告陷害。\n对于公民的申诉、控告或者检举，有关国家机关必须查清事实，负责处理。任何人不得压制和打击报复。\n由于国家机关和国家工作人员侵犯公民权利而受到损失的人，有依照法律规定取得赔偿的权利', 786, '{\"level\": null, \"title\": null, \"chunk_index\": 8}', 'bge-large-zh-v1.5', '2026-09-25 17:04:28');
INSERT INTO `chunk` VALUES ('40a95394-1ac3-4dd5-9f4d-82ea3adde97d', 'b25ce095-dfba-4403-acf8-c58eb456ca4c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 41, '地役权合同一般包括下列条款：\n（一）当事人的姓名或者名称和住所；\n（二）供役地和需役地的位置；\n（三）利用目的和方法；\n（四）地役权期限；\n（五）费用及其支付方式；\n（六）解决争议的方法。\n第三百七十四条　地役权自地役权合同生效时设立。当事人要求登记的，可以向登记机构申请地役权登记；未经登记，不得对抗善意第三人。\n第三百七十五条　供役地权利人应当按照合同约定，允许地役权人利用其不动产，不得妨害地役权人行使权利。\n第三百七十六条　地役权人应当按照合同约定的利用目的和方法利用供役地，尽量减少对供役地权利人物权的限制。\n第三百七十七条　地役权期限由当事人约定；但是，不得超过土地承包经营权、建设用地使用权等用益物权的剩余期限。\n第三百七十八条　土地所有权人享有地役权或者负担地役权的，设立土地承包经营权、宅基地使用权等用益物权时，该用益物权人继续享有或者负担已经设立的地役权。\n第三百七十九条　土地上已经设立土地承包经营权、建设用地使用权、宅基地使用权等用益物权的，未经用益物权人同意，土地所有权人不得设立地役权。\n第三百八十条　地役权不得单独转让。土地承包经营权、建设用地使用权等转让的，地役权一并转让，但是合同另有约定的除外。\n第三百八十一条　地役权不得单独抵押。土地经营权、建设用地使用权等抵押的，在实现抵押权时，地役权一并转让。\n第三百八十二条　需役地以及需役地上的土地承包经营权、建设用地使用权等部分转让时，转让部分涉及地役权的，受让人同时享有地役权。\n第三百八十三条　供役地以及供役地上的土地承包经营权、建设用地使用权等部分转让时，转让部分涉及地役权的，地役权对受让人具有法律约束力', 697, '{\"level\": null, \"title\": null, \"chunk_index\": 41}', 'bge-large-zh-v1.5', '2026-09-25 17:05:01');
INSERT INTO `chunk` VALUES ('41282ce3-112e-404b-bd30-d62fb0506072', 'd9d7dc15-8041-43b8-9f75-f112fe3ae003', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 23, '第八章　事故应急救援\n第九十条　县级以上地方人民政府应急管理部门应当会同工业和信息化、公安、生态环境、交通运输、卫生健康、市场监督管理等部门，根据本地区实际情况，制定危险化学品事故应急预案，报本级人民政府批准，并依法向社会公布。\n负有危险化学品安全监督管理职责的部门在制定本部门应急预案时应当包含危险化学品事故应急处置的内容。\n中国人民解放军、中国人民武装警察部队按照中央军事委员会的命令，依法参加危险化学品事故应急救援工作。\n第九十一条　危险化学品单位应当做好应急准备工作，健全应急管理制度，制定本单位危险化学品事故应急预案，依法建立专职或者兼职应急救援队伍，配备必要的应急救援器材、装备、设备和物资，并定期组织应急救援演练，提高从业人员的应急处置能力。生产经营规模较小的，可以不建立应急救援队伍，但应当指定兼职的应急救援人员，并可以与邻近的应急救援队伍签订应急救援协议。\n危险化学品单位应当将其危险化学品事故应急预案按照国家有关规定报送县级以上人民政府应急管理部门备案，并依法向社会公布。\n第九十二条　县级以上地方人民政府根据生产安全事故应急工作的实际需要，加强化工园区危险化学品专业应急救援力量建设，可以依托有条件的生产经营单位、社会组织共同建立危险化学品专业应急救援队伍，配备必要的应急救援器材、装备、设备和物资，并定期组织训练。\n化工园区内的危险化学品单位，可以联合建立应急救援队伍。\n第九十三条　发生危险化学品事故，事故单位主要负责人应当立即按照本单位危险化学品事故应急预案组织救援，并向当地应急管理、生态环境、公安、卫生健康、市场监督管理部门报告，及时通知可能受影响的单位和人员；道路运输、水路运输过程中发生危险化学品事故的，驾驶人员、船员或者押运人员还应当向事故发生地交通运输主管部门报告', 752, '{\"level\": null, \"title\": null, \"chunk_index\": 23}', 'bge-large-zh-v1.5', '2026-09-25 17:04:46');
INSERT INTO `chunk` VALUES ('415e2674-747b-4e98-9b63-ccc37b6764cc', 'b25ce095-dfba-4403-acf8-c58eb456ca4c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 79, '第六百九十四条　一般保证的债权人在保证期间届满前对债务人提起诉讼或者申请仲裁的，从保证人拒绝承担保证责任的权利消灭之日起，开始计算保证债务的诉讼时效。\n连带责任保证的债权人在保证期间届满前请求保证人承担保证责任的，从债权人请求保证人承担保证责任之日起，开始计算保证债务的诉讼时效。\n第六百九十五条　债权人和债务人未经保证人书面同意，协商变更主债权债务合同内容，减轻债务的，保证人仍对变更后的债务承担保证责任；加重债务的，保证人对加重的部分不承担保证责任。\n债权人和债务人变更主债权债务合同的履行期限，未经保证人书面同意的，保证期间不受影响。\n第六百九十六条　债权人转让全部或者部分债权，未通知保证人的，该转让对保证人不发生效力。\n保证人与债权人约定禁止债权转让，债权人未经保证人书面同意转让债权的，保证人对受让人不再承担保证责任。\n第六百九十七条　债权人未经保证人书面同意，允许债务人转移全部或者部分债务，保证人对未经其同意转移的债务不再承担保证责任，但是债权人和保证人另有约定的除外。\n第三人加入债务的，保证人的保证责任不受影响。\n第六百九十八条　一般保证的保证人在主债务履行期限届满后，向债权人提供债务人可供执行财产的真实情况，债权人放弃或者怠于行使权利致使该财产不能被执行的，保证人在其提供可供执行财产的价值范围内不再承担保证责任。\n第六百九十九条　同一债务有两个以上保证人的，保证人应当按照保证合同约定的保证份额，承担保证责任；没有约定保证份额的，债权人可以请求任何一个保证人在其保证范围内承担保证责任。\n第七百条　保证人承担保证责任后，除当事人另有约定外，有权在其承担保证责任的范围内向债务人追偿，享有债权人对债务人的权利，但是不得损害债权人的利益。\n第七百零一条　保证人可以主张债务人对债权人的抗辩。债务人放弃抗辩的，保证人仍有权向债权人主张抗辩', 779, '{\"level\": null, \"title\": null, \"chunk_index\": 79}', 'bge-large-zh-v1.5', '2026-09-25 17:05:01');
INSERT INTO `chunk` VALUES ('41894e5c-3f7a-41ac-abf6-2d09c108e50f', 'd9d7dc15-8041-43b8-9f75-f112fe3ae003', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 21, '在内河港口内进行危险化学品的装卸、过驳作业，应当将危险化学品的名称、危险特性、包装和作业的时间、地点等事项报告港口行政管理部门。港口行政管理部门接到报告后，应当在国务院交通运输主管部门规定的时间内作出是否同意的决定，通知报告人，同时通报海事管理机构。\n载运危险化学品的船舶在内河航行，通过通航建筑物的，应当符合通航建筑物安全管理有关要求，并提前向通航建筑物运行单位报告。运行单位应当及时转报交通运输主管部门。载运危险化学品的船舶通过通航建筑物时，应当接受交通运输主管部门的管理。\n第八十条　载运危险化学品的船舶在内河航行、装卸或者停泊，应当悬挂专用的警示标志，按照规定显示专用信号。\n载运危险化学品的船舶在内河航行，依照法律、行政法规以及国务院交通运输主管部门的规定需要引航的，应当申请引航。\n第八十一条　载运危险化学品的船舶在内河航行，应当遵守法律、行政法规和国家其他有关饮用水水源和自然保护地保护的规定。内河航道发展规划应当与依法经批准的饮用水水源保护区划定方案和自然保护地总体规划相协调。\n第八十二条　托运危险化学品，托运人应当向承运人提交电子或者纸质的危险货物托运清单，说明所托运的危险化学品的种类、数量、危险特性以及发生危险情况的应急处置措施，提供化学品安全技术说明书，并按照国家有关规定对所托运的危险化学品妥善包装，在危险化学品包装上粘贴、印刷或者拴挂与包装内危险化学品相符的化学品安全标签，并保证随时可查。\n运输危险化学品需要添加抑制剂或者稳定剂的，托运人应当按照规定添加，并将有关情况告知承运人。\n装货人应当在充装或者装载危险化学品前履行查验责任，并按照标准要求进行充装、装载作业。\n第八十三条　托运人不得在托运的普通货物中夹带危险化学品，不得将危险化学品匿报或者谎报为普通货物托运', 749, '{\"level\": null, \"title\": null, \"chunk_index\": 21}', 'bge-large-zh-v1.5', '2026-09-25 17:04:46');
INSERT INTO `chunk` VALUES ('42d646c5-ea26-487c-ba5d-7fdd929de83b', 'b25ce095-dfba-4403-acf8-c58eb456ca4c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 97, '第八百五十六条　合作开发合同的当事人违反约定造成研究开发工作停滞、延误或者失败的，应当承担违约责任。\n第八百五十七条　作为技术开发合同标的的技术已经由他人公开，致使技术开发合同的履行没有意义的，当事人可以解除合同。\n第八百五十八条　技术开发合同履行过程中，因出现无法克服的技术困难，致使研究开发失败或者部分失败的，该风险由当事人约定；没有约定或者约定不明确，依据本法第五百一十条的规定仍不能确定的，风险由当事人合理分担。\n当事人一方发现前款规定的可能致使研究开发失败或者部分失败的情形时，应当及时通知另一方并采取适当措施减少损失；没有及时通知并采取适当措施，致使损失扩大的，应当就扩大的损失承担责任。\n第八百五十九条　委托开发完成的发明创造，除法律另有规定或者当事人另有约定外，申请专利的权利属于研究开发人。研究开发人取得专利权的，委托人可以依法实施该专利。\n研究开发人转让专利申请权的，委托人享有以同等条件优先受让的权利。\n第八百六十条　合作开发完成的发明创造，申请专利的权利属于合作开发的当事人共有；当事人一方转让其共有的专利申请权的，其他各方享有以同等条件优先受让的权利。但是，当事人另有约定的除外。\n合作开发的当事人一方声明放弃其共有的专利申请权的，除当事人另有约定外，可以由另一方单独申请或者由其他各方共同申请。申请人取得专利权的，放弃专利申请权的一方可以免费实施该专利。\n合作开发的当事人一方不同意申请专利的，另一方或者其他各方不得申请专利。\n第八百六十一条　委托开发或者合作开发完成的技术秘密成果的使用权、转让权以及收益的分配办法，由当事人约定；没有约定或者约定不明确，依据本法第五百一十条的规定仍不能确定的，在没有相同技术方案被授予专利权前，当事人均有使用和转让的权利。但是，委托开发的研究开发人不得在向委托人交付研究开发成果之前，将研究开发成果转让给第三人', 787, '{\"level\": null, \"title\": null, \"chunk_index\": 97}', 'bge-large-zh-v1.5', '2026-09-25 17:05:01');
INSERT INTO `chunk` VALUES ('4391cc09-56c1-495d-98e4-5eb53f1ba91c', '16cbea7e-7e36-4f31-afb5-63892345d29c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 47, '第三节　调　　查\n第二百一十五条　监察机关对已经立案的职务违法或者职务犯罪案件应当依法进行调查，收集证据查明违法犯罪事实。\n调查职务违法或者职务犯罪案件，对被调查人没有采取留置措施的，应当在立案后一年以内作出处理决定；对被调查人解除留置措施的，应当在解除留置措施后一年以内作出处理决定。案情重大、复杂的案件，经上一级监察机关批准，可以适当延长，但延长期限不得超过六个月。\n被调查人在监察机关立案调查以后逃匿的，调查期限自被调查人到案之日起重新计算。\n第二百一十六条　案件立案后，监察机关主要负责人应当依照法定程序批准确定调查方案。\n监察机关应当组成调查组依法开展调查。调查工作应当严格按照批准的方案执行，不得随意扩大调查范围、变更调查对象和事项，对重要事项应当及时请示报告。调查人员在调查工作期间，未经批准不得单独接触任何涉案人员及其特定关系人，不得擅自采取调查措施。\n第二百一十七条　调查组应当将调查认定的涉嫌违法犯罪事实形成书面材料，交给被调查人核对，听取其意见。被调查人应当在书面材料上签署意见。对被调查人签署不同意见或者拒不签署意见的，调查组应当作出说明或者注明情况。对被调查人提出申辩的事实、理由和证据应当进行核实，成立的予以采纳。\n调查组对于立案调查的涉嫌行贿犯罪、介绍贿赂犯罪或者共同职务犯罪的涉案人员，在查明其涉嫌犯罪问题后，依照前款规定办理。\n对于按照本条例规定，对立案和移送审理一并报批的案件，应当在报批前履行本条第一款规定的程序。\n第二百一十八条　调查组在调查工作结束后应当集体讨论，形成调查报告。调查报告应当列明被调查人基本情况、问题线索来源及调查依据、调查过程，涉嫌的主要职务违法或者职务犯罪事实，被调查人的态度和认识，处置建议及法律依据，并由调查组组长以及有关人员签名。\n对调查过程中发现的重要问题和形成的意见建议，应当形成专题报告', 780, '{\"level\": null, \"title\": null, \"chunk_index\": 47}', 'bge-large-zh-v1.5', '2026-09-25 17:04:49');
INSERT INTO `chunk` VALUES ('43a189db-76ec-49f3-82d6-68bd6c628bae', 'b25ce095-dfba-4403-acf8-c58eb456ca4c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 15, '债权是因合同、侵权行为、无因管理、不当得利以及法律的其他规定，权利人请求特定义务人为或者不为一定行为的权利。\n第一百一十九条　依法成立的合同，对当事人具有法律约束力。\n第一百二十条　民事权益受到侵害的，被侵权人有权请求侵权人承担侵权责任。\n第一百二十一条　没有法定的或者约定的义务，为避免他人利益受损失而进行管理的人，有权请求受益人偿还由此支出的必要费用。\n第一百二十二条　因他人没有法律根据，取得不当利益，受损失的人有权请求其返还不当利益。\n第一百二十三条　民事主体依法享有知识产权。\n知识产权是权利人依法就下列客体享有的专有的权利：\n（一）作品；\n（二）发明、实用新型、外观设计；\n（三）商标；\n（四）地理标志；\n（五）商业秘密；\n（六）集成电路布图设计；\n（七）植物新品种；\n（八）法律规定的其他客体。\n第一百二十四条　自然人依法享有继承权。\n自然人合法的私有财产，可以依法继承。\n第一百二十五条　民事主体依法享有股权和其他投资性权利。\n第一百二十六条　民事主体享有法律规定的其他民事权利和利益。\n第一百二十七条　法律对数据、网络虚拟财产的保护有规定的，依照其规定。\n第一百二十八条　法律对未成年人、老年人、残疾人、妇女、消费者等的民事权利保护有特别规定的，依照其规定。\n第一百二十九条　民事权利可以依据民事法律行为、事实行为、法律规定的事件或者法律规定的其他方式取得。\n第一百三十条　民事主体按照自己的意愿依法行使民事权利，不受干涉。\n第一百三十一条　民事主体行使权利时，应当履行法律规定的和当事人约定的义务。\n第一百三十二条　民事主体不得滥用民事权利损害国家利益、社会公共利益或者他人合法权益。\n第六章　民事法律行为\n第一节　一般规定\n第一百三十三条　民事法律行为是民事主体通过意思表示设立、变更、终止民事法律关系的行为', 765, '{\"level\": null, \"title\": null, \"chunk_index\": 15}', 'bge-large-zh-v1.5', '2026-09-25 17:05:01');
INSERT INTO `chunk` VALUES ('43a85e15-fe8c-4cd3-9637-c34f47f2401d', '821ce1fd-178d-4a7e-ab92-3deff1488ce2', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 43, '第一百九十八条　有下列情形之一，进行保险诈骗活动，数额较大的，处五年以下有期徒刑或者拘役，并处一万元以上十万元以下罚金；数额巨大或者有其他严重情节的，处五年以上十年以下有期徒刑，并处二万元以上二十万元以下罚金；数额特别巨大或者有其他特别严重情节的，处十年以上有期徒刑，并处二万元以上二十万元以下罚金或者没收财产：\n（一）投保人故意虚构保险标的，骗取保险金的；\n（二）投保人、被保险人或者受益人对发生的保险事故编造虚假的原因或者夸大损失的程度，骗取保险金的；\n（三）投保人、被保险人或者受益人编造未曾发生的保险事故，骗取保险金的；\n（四）投保人、被保险人故意造成财产损失的保险事故，骗取保险金的；\n（五）投保人、受益人故意造成被保险人死亡、伤残或者疾病，骗取保险金的。\n有前款第四项、第五项所列行为，同时构成其他犯罪的，依照数罪并罚的规定处罚。\n单位犯第一款罪的，对单位判处罚金，并对其直接负责的主管人员和其他直接责任人员，处五年以下有期徒刑或者拘役；数额巨大或者有其他严重情节的，处五年以上十年以下有期徒刑；数额特别巨大或者有其他特别严重情节的，处十年以上有期徒刑。\n保险事故的鉴定人、证明人、财产评估人故意提供虚假的证明文件，为他人诈骗提供条件的，以保险诈骗的共犯论处。\n第一百九十九条　（删去）\n第二百条　单位犯本节第一百九十四条、第一百九十五条规定之罪的，对单位判处罚金，并对其直接负责的主管人员和其他直接责任人员，处五年以下有期徒刑或者拘役，可以并处罚金；数额巨大或者有其他严重情节的，处五年以上十年以下有期徒刑，并处罚金；数额特别巨大或者有其他特别严重情节的，处十年以上有期徒刑或者无期徒刑，并处罚金', 705, '{\"level\": null, \"title\": null, \"chunk_index\": 43}', 'bge-large-zh-v1.5', '2026-09-25 17:04:56');
INSERT INTO `chunk` VALUES ('43d09e34-01e7-47d7-a677-7fcb7f705176', '0497a5e7-7044-4b18-8fed-af3fb7bc7890', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 7, '第四十二条　增值税法第二十九条第一项所称经省级以上财政、税务主管部门批准可以由总机构汇总申报纳税，是指有固定生产经营场所的纳税人，总机构和分支机构不在同一省（自治区、直辖市）内的，经国务院财政、税务主管部门批准，可以由总机构汇总向总机构所在地的主管税务机关申报纳税；总机构和分支机构在同一省（自治区、直辖市）内但不在同一县（市、区、旗）内的，经省（自治区、直辖市）财政、税务主管部门批准，可以由总机构汇总向总机构所在地的主管税务机关申报纳税。\n第四十三条　下列纳税人可以适用增值税法第三十条规定的以一个季度为一个计税期间：\n（一）小规模纳税人；\n（二）一般纳税人中的银行、财务公司、信托公司、信用社；\n（三）国务院税务、财政主管部门确定的其他纳税人。\n第四十四条　按次纳税的纳税人，销售额达到起征点的，应当自纳税义务发生之日起至次年6月30日前申报纳税。\n第四十五条　下列情形应当按规定预缴税款：\n（一）跨地级行政区（直辖市下辖县区）提供建筑服务；\n（二）采取预收款方式提供建筑服务；\n（三）采取预售方式销售房地产项目；\n（四）转让或者出租与纳税人机构所在地不在同一县（市、区、旗）内的不动产；\n（五）油气田企业跨省、自治区、直辖市销售与生产原油、天然气相关的服务。\n本条第一款规定的预缴税款的具体操作办法，由国务院财政、税务主管部门制定。\n第四十六条　经省级以上财政、税务主管部门批准由总机构汇总申报纳税的，批准部门可以规定由分支机构预缴税款。\n第四十七条　纳税人出口货物或者跨境销售服务、无形资产（以下统称出口业务），依照增值税法第三十三条的规定申报办理退（免）税的，按照国务院规定的出口退税率，通过免抵退税办法或者免退税办法计算退（免）税额，经税务机关审核通过后，办理退（免）税', 742, '{\"level\": null, \"title\": null, \"chunk_index\": 7}', 'bge-large-zh-v1.5', '2026-09-25 17:04:28');
INSERT INTO `chunk` VALUES ('44d565ab-fe2e-4eb1-b8c1-4785c3e64e67', '821ce1fd-178d-4a7e-ab92-3deff1488ce2', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 91, '第三百九十九条　司法工作人员徇私枉法、徇情枉法，对明知是无罪的人而使他受追诉、对明知是有罪的人而故意包庇不使他受追诉，或者在刑事审判活动中故意违背事实和法律作枉法裁判的，处五年以下有期徒刑或者拘役；情节严重的，处五年以上十年以下有期徒刑；情节特别严重的，处十年以上有期徒刑。\n在民事、行政审判活动中故意违背事实和法律作枉法裁判，情节严重的，处五年以下有期徒刑或者拘役；情节特别严重的，处五年以上十年以下有期徒刑。\n在执行判决、裁定活动中，严重不负责任或者滥用职权，不依法采取诉讼保全措施、不履行法定执行职责，或者违法采取诉讼保全措施、强制执行措施，致使当事人或者其他人的利益遭受重大损失的，处五年以下有期徒刑或者拘役；致使当事人或者其他人的利益遭受特别重大损失的，处五年以上十年以下有期徒刑。\n司法工作人员收受贿赂，有前三款行为的，同时又构成本法第三百八十五条规定之罪的，依照处罚较重的规定定罪处罚。\n第三百九十九条之一　依法承担仲裁职责的人员，在仲裁活动中故意违背事实和法律作枉法裁决，情节严重的，处三年以下有期徒刑或者拘役；情节特别严重的，处三年以上七年以下有期徒刑。\n第四百条　司法工作人员私放在押的犯罪嫌疑人、被告人或者罪犯的，处五年以下有期徒刑或者拘役；情节严重的，处五年以上十年以下有期徒刑；情节特别严重的，处十年以上有期徒刑。\n司法工作人员由于严重不负责任，致使在押的犯罪嫌疑人、被告人或者罪犯脱逃，造成严重后果的，处三年以下有期徒刑或者拘役；造成特别严重后果的，处三年以上十年以下有期徒刑。\n第四百零一条　司法工作人员徇私舞弊，对不符合减刑、假释、暂予监外执行条件的罪犯，予以减刑、假释或者暂予监外执行的，处三年以下有期徒刑或者拘役；情节严重的，处三年以上七年以下有期徒刑', 744, '{\"level\": null, \"title\": null, \"chunk_index\": 91}', 'bge-large-zh-v1.5', '2026-09-25 17:04:56');
INSERT INTO `chunk` VALUES ('44f2677a-6636-47f2-b3bd-6fae0549380a', 'd9d7dc15-8041-43b8-9f75-f112fe3ae003', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 27, '（九）生产、储存危险化学品的企业以及使用危险化学品从事生产的企业未按照规定装备自动控制系统和安全仪表系统，未建立安全风险监测预警系统，或者安全风险监测预警系统未与政府有关部门实现互联互通；\n（十）生产、储存、使用危险化学品的单位未在作业场所和安全设施、设备上设置明显的安全警示标志，或者未在作业场所设置通信、报警装置并处于适用状态；\n（十一）危险化学品专用储存场所未设专人负责管理，对储存的剧毒化学品以及储存数量构成重大危险源的其他危险化学品未实行双人收发、双人保管制度，或者收发记录的保存期限少于三年；\n（十二）储存危险化学品的单位未建立危险化学品出入库核查、登记制度；\n（十三）危险化学品专用储存场所未设置明显标志；\n（十四）研制开发单位将未经小试、中试、工业化试验的新工艺、新技术直接用于工业化生产，或者转让危险化学品新工艺、新技术时，未提供新工艺、新技术的安全论证报告及相关资料；\n（十五）使用危险化学品的单位未将其作业场所使用的化学品安全技术说明书、化学品安全标签提供给从业人员，或者未告知从业人员正确使用的方法、在紧急情况下应当采取的措施；\n（十六）危险化学品生产企业、经营企业经营没有化学品安全技术说明书、化学品安全标签的危险化学品，或者擅自更改化学品安全技术说明书、化学品安全标签；\n（十七）危险化学品生产企业、进口企业不办理危险化学品登记，或者发现其生产、进口的危险化学品有新的危险特性、其他登记内容发生变更，不办理危险化学品登记内容变更手续', 630, '{\"level\": null, \"title\": null, \"chunk_index\": 27}', 'bge-large-zh-v1.5', '2026-09-25 17:04:46');
INSERT INTO `chunk` VALUES ('45514e61-8760-4949-9053-2e9087f2beb9', '16cbea7e-7e36-4f31-afb5-63892345d29c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 69, '监察机关主要负责人的回避，由上级监察机关主要负责人决定；其他监察人员的回避，由本级监察机关主要负责人决定。\n第二百九十七条　上级监察机关应当通过专项检查、业务考评、开展复查等方式，强化对下级监察机关及监察人员执行职务和遵纪守法情况的监督。\n第二百九十八条　监察机关应当对监察人员有计划地进行政治、理论和业务培训。培训应当坚持理论联系实际、按需施教、讲求实效，突出政治机关特色，建设忠诚干净担当、敢于善于斗争的高素质专业化监察队伍，全面提高监察工作规范化法治化正规化水平。\n第二百九十九条　监察机关应当严格执行保密制度，控制监察事项知悉范围和时间。监察人员不准私自留存、隐匿、查阅、摘抄、复制、携带问题线索和涉案资料，严禁泄露监察工作秘密。\n监察机关应当建立健全检举控告保密制度，对检举控告人的姓名（单位名称）、工作单位、住址、电话和邮箱等有关情况以及检举控告内容必须严格保密。\n第三百条　监察机关涉密人员离岗离职后，应当遵守脱密期管理规定，严格履行保密义务，不得泄露相关秘密。\n第三百零一条　监察人员离任三年以内，不得从事与监察和司法工作相关联且可能发生利益冲突的职业。\n监察人员离任后，不得担任原任职监察机关办理案件的诉讼代理人或者辩护人，但是作为当事人的监护人或者近亲属代理诉讼或者进行辩护的除外。\n第三百零二条　监察人员应当严格遵守有关规范领导干部配偶、子女及其配偶经商办企业行为的规定。\n第三百零三条　监察机关及其工作人员在履行职责过程中应当依法保护企业产权和自主经营权，严禁利用职权非法干扰企业生产经营。需要企业经营者协助调查的，应当依法保障其人身权利、财产权利和其他合法权益，避免或者尽量减少对涉案企业正常生产经营活动的影响。\n监察机关查封、扣押、冻结以及追缴涉案财物，应当严格区分企业财产与经营者个人财产，被调查人个人财产与家庭成员财产，违法所得、其他涉案财产与合法财产', 792, '{\"level\": null, \"title\": null, \"chunk_index\": 69}', 'bge-large-zh-v1.5', '2026-09-25 17:04:49');
INSERT INTO `chunk` VALUES ('4567d6b0-5425-49ff-af71-e4d8e0f47edb', '16cbea7e-7e36-4f31-afb5-63892345d29c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 37, '对于主动上交的财物，应当根据立案及调查情况及时决定是否依法查封、扣押。\n第十四节　勘验检查、调查实验\n第一百六十六条　监察机关按规定报批后，可以依法对与违法犯罪有关的场所、物品、人身、尸体、电子数据等进行勘验检查。\n第一百六十七条　依法需要勘验检查的，应当制作《勘验检查证》；需要委托勘验检查的，应当出具《委托勘验检查书》，送具有专门知识的人办理。\n第一百六十八条　勘验检查应当由二名以上调查人员主持，邀请与案件无关的见证人在场。勘验检查情况应当制作笔录，并由参加勘验检查人员和见证人签名或者盖章。\n勘验检查现场、拆封电子数据存储介质应当全程同步录音录像。对现场情况应当拍摄现场照片、制作现场图，并由勘验检查人员签名或者盖章。\n第一百六十九条　为了确定被调查人或者相关人员的某些特征、伤害情况或者生理状态，可以依法对其人身进行检查。必要时可以聘请法医或者医师进行人身检查。检查女性身体，应当由女性工作人员或者医师进行。被调查人拒绝检查的，可以依法强制检查。\n人身检查不得采用损害被检查人生命、健康或者贬低其名誉、人格的方法。对人身检查过程中知悉的个人隐私，应当严格保密。\n对人身检查的情况应当制作笔录，由参加检查的调查人员、检查人员、被检查人员和见证人签名或者盖章。被检查人员拒绝签名、盖章的，调查人员应当在笔录中记明。\n第一百七十条　为查明案情，在必要的时候，经审批可以依法进行调查实验。调查实验，可以聘请有关专业人员参加，也可以要求被调查人、被害人、证人参加。\n进行调查实验，应当全程同步录音录像，制作调查实验笔录，由参加实验的人签名或者盖章。进行调查实验，禁止一切足以造成危险、侮辱人格的行为。\n调查实验的条件与事件发生时的条件有明显差异，或者存在影响实验结论科学性的其他情形的，调查实验笔录不得作为认定案件的依据', 760, '{\"level\": null, \"title\": null, \"chunk_index\": 37}', 'bge-large-zh-v1.5', '2026-09-25 17:04:49');
INSERT INTO `chunk` VALUES ('458ab6e9-0927-4c7b-bd93-b40895492597', 'b25ce095-dfba-4403-acf8-c58eb456ca4c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 78, '一般保证的保证人在主合同纠纷未经审判或者仲裁，并就债务人财产依法强制执行仍不能履行债务前，有权拒绝向债权人承担保证责任，但是有下列情形之一的除外：\n（一）债务人下落不明，且无财产可供执行；\n（二）人民法院已经受理债务人破产案件；\n（三）债权人有证据证明债务人的财产不足以履行全部债务或者丧失履行债务能力；\n（四）保证人书面表示放弃本款规定的权利。\n第六百八十八条　当事人在保证合同中约定保证人和债务人对债务承担连带责任的，为连带责任保证。\n连带责任保证的债务人不履行到期债务或者发生当事人约定的情形时，债权人可以请求债务人履行债务，也可以请求保证人在其保证范围内承担保证责任。\n第六百八十九条　保证人可以要求债务人提供反担保。\n第六百九十条　保证人与债权人可以协商订立最高额保证的合同，约定在最高债权额限度内就一定期间连续发生的债权提供保证。\n最高额保证除适用本章规定外，参照适用本法第二编最高额抵押权的有关规定。\n第二节　保证责任\n第六百九十一条　保证的范围包括主债权及其利息、违约金、损害赔偿金和实现债权的费用。当事人另有约定的，按照其约定。\n第六百九十二条　保证期间是确定保证人承担保证责任的期间，不发生中止、中断和延长。\n债权人与保证人可以约定保证期间，但是约定的保证期间早于主债务履行期限或者与主债务履行期限同时届满的，视为没有约定；没有约定或者约定不明确的，保证期间为主债务履行期限届满之日起六个月。\n债权人与债务人对主债务履行期限没有约定或者约定不明确的，保证期间自债权人请求债务人履行债务的宽限期届满之日起计算。\n第六百九十三条　一般保证的债权人未在保证期间对债务人提起诉讼或者申请仲裁的，保证人不再承担保证责任。\n连带责任保证的债权人未在保证期间请求保证人承担保证责任的，保证人不再承担保证责任', 756, '{\"level\": null, \"title\": null, \"chunk_index\": 78}', 'bge-large-zh-v1.5', '2026-09-25 17:05:01');
INSERT INTO `chunk` VALUES ('481a499e-0f6b-4197-8eb9-759d093cecfd', 'd9d7dc15-8041-43b8-9f75-f112fe3ae003', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 33, '违反本法规定，在互联网上销售剧毒化学品、易制爆危险化学品的，由负有危险化学品安全监督管理职责的部门按照职责分工依照本条第一款的规定予以处理、处罚。\n第一百零八条　未依法取得危险货物道路运输许可、相应危险货物水路运输许可或者未办理备案手续，从事危险化学品道路运输、水路运输的，分别依照有关道路运输、水路运输的法律、行政法规的规定处理、处罚', 168, '{\"level\": null, \"title\": null, \"chunk_index\": 33}', 'bge-large-zh-v1.5', '2026-09-25 17:04:46');
INSERT INTO `chunk` VALUES ('485b37e7-26ed-4baa-9886-e4e97c9a4964', '16cbea7e-7e36-4f31-afb5-63892345d29c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 32, '搜查时，应当有被搜查人或者其家属、其所在单位工作人员或者其他见证人在场。调查人员应当向被搜查人或者其家属、见证人出示《搜查证》，要求其签名或者盖章。被搜查人或者其家属不在场，或者拒绝签名、盖章的，调查人员应当在文书上记明。\n第一百四十五条　搜查时，应当要求在场人员予以配合，不得进行阻碍。对以暴力、威胁等方法阻碍搜查的，应当依法制止。对阻碍搜查构成违法犯罪的，依法追究法律责任。\n第一百四十六条　对搜查取证工作，应当全程同步录音录像。\n对搜查情况应当制作《搜查笔录》，由调查人员和被搜查人或者其家属、见证人签名或者盖章。被搜查人或者其家属不在场，或者拒绝签名、盖章的，调查人员应当在笔录中记明。\n对于查获的重要物证、书证、视听资料、电子数据及其放置、存储位置应当拍照，并在《搜查笔录》中作出文字说明。\n第一百四十七条　搜查时，应当避免未成年人或者其他不适宜在搜查现场的人在场。\n搜查人员应当服从指挥、文明执法，不得擅自变更搜查对象和扩大搜查范围，严禁单独进入搜查区域。搜查的具体时间、方法，在实施前应当严格保密。\n第一百四十八条　在搜查过程中查封、扣押财物和文件的，按照查封、扣押的有关规定办理。\n第十二节　调　　取\n第一百四十九条　监察机关按规定报批后，可以依法向有关单位和个人调取用以证明案件事实的证据材料。\n第一百五十条　调取证据材料时，调查人员不得少于二人。调查人员应当依法出具《调取证据通知书》，必要时附《调取证据清单》。\n有关单位和个人配合监察机关调取证据，应当严格保密。\n第一百五十一条　调取物证应当调取原物。原物不便搬运、保存，或者依法应当返还，或者因保密工作需要不能调取原物的，可以将原物封存，并拍照、录像。对原物拍照或者录像时，应当足以反映原物的外形、内容。\n调取书证、视听资料应当调取原件。取得原件确有困难或者因保密工作需要不能调取原件的，可以调取副本或者复制件', 792, '{\"level\": null, \"title\": null, \"chunk_index\": 32}', 'bge-large-zh-v1.5', '2026-09-25 17:04:49');
INSERT INTO `chunk` VALUES ('4aacacda-26f7-4f90-bae1-df4d350d9944', '821ce1fd-178d-4a7e-ab92-3deff1488ce2', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 50, '第二百二十四条之一　组织、领导以推销商品、提供服务等经营活动为名，要求参加者以缴纳费用或者购买商品、服务等方式获得加入资格，并按照一定顺序组成层级，直接或者间接以发展人员的数量作为计酬或者返利依据，引诱、胁迫参加者继续发展他人参加，骗取财物，扰乱经济社会秩序的传销活动的，处五年以下有期徒刑或者拘役，并处罚金；情节严重的，处五年以上有期徒刑，并处罚金。\n第二百二十五条　违反国家规定，有下列非法经营行为之一，扰乱市场秩序，情节严重的，处五年以下有期徒刑或者拘役，并处或者单处违法所得一倍以上五倍以下罚金；情节特别严重的，处五年以上有期徒刑，并处违法所得一倍以上五倍以下罚金或者没收财产：\n（一）未经许可经营法律、行政法规规定的专营、专卖物品或者其他限制买卖的物品的；\n（二）买卖进出口许可证、进出口原产地证明以及其他法律、行政法规规定的经营许可证或者批准文件的；\n（三）未经国家有关主管部门批准非法经营证券、期货、保险业务的，或者非法从事资金支付结算业务的；\n（四）其他严重扰乱市场秩序的非法经营行为。\n第二百二十六条　以暴力、威胁手段，实施下列行为之一，情节严重的，处三年以下有期徒刑或者拘役，并处或者单处罚金；情节特别严重的，处三年以上七年以下有期徒刑，并处罚金：\n（一）强买强卖商品的；\n（二）强迫他人提供或者接受服务的；\n（三）强迫他人参与或者退出投标、拍卖的；\n（四）强迫他人转让或者收购公司、企业的股份、债券或者其他资产的；\n（五）强迫他人参与或者退出特定的经营活动的。\n第二百二十七条　伪造或者倒卖伪造的车票、船票、邮票或者其他有价票证，数额较大的，处二年以下有期徒刑、拘役或者管制，并处或者单处票证价额一倍以上五倍以下罚金；数额巨大的，处二年以上七年以下有期徒刑，并处票证价额一倍以上五倍以下罚金', 756, '{\"level\": null, \"title\": null, \"chunk_index\": 50}', 'bge-large-zh-v1.5', '2026-09-25 17:04:56');
INSERT INTO `chunk` VALUES ('4aaf2f83-cab2-4fec-98c6-818239ced000', '821ce1fd-178d-4a7e-ab92-3deff1488ce2', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 69, '第三百零二条　盗窃、侮辱、故意毁坏尸体、尸骨、骨灰的，处三年以下有期徒刑、拘役或者管制。\n第三百零三条　以营利为目的，聚众赌博或者以赌博为业的，处三年以下有期徒刑、拘役或者管制，并处罚金。\n开设赌场的，处五年以下有期徒刑、拘役或者管制，并处罚金；情节严重的，处五年以上十年以下有期徒刑，并处罚金。\n组织中华人民共和国公民参与国（境）外赌博，数额巨大或者有其他严重情节的，依照前款的规定处罚。\n第三百零四条　邮政工作人员严重不负责任，故意延误投递邮件，致使公共财产、国家和人民利益遭受重大损失的，处二年以下有期徒刑或者拘役。\n第二节　妨害司法罪\n第三百零五条　在刑事诉讼中，证人、鉴定人、记录人、翻译人对与案件有重要关系的情节，故意作虚假证明、鉴定、记录、翻译，意图陷害他人或者隐匿罪证的，处三年以下有期徒刑或者拘役；情节严重的，处三年以上七年以下有期徒刑。\n第三百零六条　在刑事诉讼中，辩护人、诉讼代理人毁灭、伪造证据，帮助当事人毁灭、伪造证据，威胁、引诱证人违背事实改变证言或者作伪证的，处三年以下有期徒刑或者拘役；情节严重的，处三年以上七年以下有期徒刑。\n辩护人、诉讼代理人提供、出示、引用的证人证言或者其他证据失实，不是有意伪造的，不属于伪造证据。\n第三百零七条　以暴力、威胁、贿买等方法阻止证人作证或者指使他人作伪证的，处三年以下有期徒刑或者拘役；情节严重的，处三年以上七年以下有期徒刑。\n帮助当事人毁灭、伪造证据，情节严重的，处三年以下有期徒刑或者拘役。\n司法工作人员犯前两款罪的，从重处罚。\n第三百零七条之一　以捏造的事实提起民事诉讼，妨害司法秩序或者严重侵害他人合法权益的，处三年以下有期徒刑、拘役或者管制，并处或者单处罚金；情节严重的，处三年以上七年以下有期徒刑，并处罚金。\n单位犯前款罪的，对单位判处罚金，并对其直接负责的主管人员和其他直接责任人员，依照前款的规定处罚', 793, '{\"level\": null, \"title\": null, \"chunk_index\": 69}', 'bge-large-zh-v1.5', '2026-09-25 17:04:56');
INSERT INTO `chunk` VALUES ('4bcf6df4-e5b1-4b59-90f5-aaa0edddbfdf', '16cbea7e-7e36-4f31-afb5-63892345d29c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 46, '第二节　立　　案\n第二百一十条　监察机关已经掌握监察对象涉嫌职务违法或者职务犯罪的部分事实和证据，认为需要追究其法律责任的，应当按规定报批后，依法立案调查。\n第二百一十一条　监察机关立案调查职务违法或者职务犯罪案件，需要对涉嫌行贿犯罪、介绍贿赂犯罪或者共同职务犯罪的涉案人员立案调查的，应当一并办理立案手续。需要交由下级监察机关立案的，经审批交由下级监察机关办理立案手续。\n对单位涉嫌受贿、行贿等职务犯罪，需要追究法律责任的，依法对该单位办理立案调查手续。对事故（事件）中存在职务违法或者职务犯罪问题，需要追究法律责任，但相关责任人员尚不明确的，可以以事立案。对单位立案或者以事立案后，经调查确定相关责任人员的，按照管理权限报批确定被调查人。\n监察机关根据人民法院生效刑事判决、裁定和人民检察院不起诉决定认定的事实，需要对监察对象给予政务处分的，可以由相关监督检查部门依据司法机关的生效判决、裁定、决定及其认定的事实、性质和情节，提出给予政务处分的意见，按程序移送审理。对依法被追究行政法律责任的监察对象，需要给予政务处分的，应当依法办理立案手续。\n第二百一十二条　对案情简单、经过初步核实已查清主要职务违法事实，应当追究监察对象法律责任，不再需要开展调查的，立案和移送审理可以一并报批，履行立案程序后再移送审理。\n第二百一十三条　上级监察机关需要指定下级监察机关立案调查的，应当按规定报批，向被指定管辖的监察机关出具《指定管辖决定书》，由其办理立案手续。\n第二百一十四条　批准立案后，应当由二名以上调查人员出示证件，向被调查人宣布立案决定。宣布立案决定后，应当及时向被调查人所在单位等相关组织送达《立案通知书》，并向被调查人所在单位主要负责人通报。\n对涉嫌严重职务违法或者职务犯罪的公职人员立案调查并采取留置措施的，应当按规定通知被调查人所在单位和家属，并向社会公开发布', 786, '{\"level\": null, \"title\": null, \"chunk_index\": 46}', 'bge-large-zh-v1.5', '2026-09-25 17:04:49');
INSERT INTO `chunk` VALUES ('4bdf4d21-22b5-4af2-b40e-a5025b1bd70a', '821ce1fd-178d-4a7e-ab92-3deff1488ce2', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 4, '因不满十六周岁不予刑事处罚的，责令其父母或者其他监护人加以管教；在必要的时候，依法进行专门矫治教育。\n第十七条之一　已满七十五周岁的人故意犯罪的，可以从轻或者减轻处罚；过失犯罪的，应当从轻或者减轻处罚。\n第十八条　精神病人在不能辨认或者不能控制自己行为的时候造成危害结果，经法定程序鉴定确认的，不负刑事责任，但是应当责令他的家属或者监护人严加看管和医疗；在必要的时候，由政府强制医疗。\n间歇性的精神病人在精神正常的时候犯罪，应当负刑事责任。\n尚未完全丧失辨认或者控制自己行为能力的精神病人犯罪的，应当负刑事责任，但是可以从轻或者减轻处罚。\n醉酒的人犯罪，应当负刑事责任。\n第十九条　又聋又哑的人或者盲人犯罪，可以从轻、减轻或者免除处罚。\n第二十条　为了使国家、公共利益、本人或者他人的人身、财产和其他权利免受正在进行的不法侵害，而采取的制止不法侵害的行为，对不法侵害人造成损害的，属于正当防卫，不负刑事责任。\n正当防卫明显超过必要限度造成重大损害的，应当负刑事责任，但是应当减轻或者免除处罚。\n对正在进行行凶、杀人、抢劫、强奸、绑架以及其他严重危及人身安全的暴力犯罪，采取防卫行为，造成不法侵害人伤亡的，不属于防卫过当，不负刑事责任。\n第二十一条　为了使国家、公共利益、本人或者他人的人身、财产和其他权利免受正在发生的危险，不得已采取的紧急避险行为，造成损害的，不负刑事责任。\n紧急避险超过必要限度造成不应有的损害的，应当负刑事责任，但是应当减轻或者免除处罚。\n第一款中关于避免本人危险的规定，不适用于职务上、业务上负有特定责任的人。\n第二节　犯罪的预备、未遂和中止\n第二十二条　为了犯罪，准备工具、制造条件的，是犯罪预备。\n对于预备犯，可以比照既遂犯从轻、减轻处罚或者免除处罚。\n第二十三条　已经着手实行犯罪，由于犯罪分子意志以外的原因而未得逞的，是犯罪未遂', 780, '{\"level\": null, \"title\": null, \"chunk_index\": 4}', 'bge-large-zh-v1.5', '2026-09-25 17:04:56');
INSERT INTO `chunk` VALUES ('4be2e036-864a-4584-b130-1c4df79af90d', '0497a5e7-7044-4b18-8fed-af3fb7bc7890', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 1, '第九条　境内单位或者个人跨境销售下列服务、无形资产，税率为零：\n（一）向境外单位销售的完全在境外消费的研发服务、合同能源管理服务、设计服务、广播影视制作和发行服务、软件服务、电路设计和测试服务、信息系统服务、业务流程管理服务、离岸服务外包业务；\n（二）向境外单位转让的完全在境外使用的技术；\n（三）国际运输服务、航天运输服务、对外修理修配服务。\n第十条　增值税法第十三条所称应税交易，应当同时符合下列条件：\n（一）包含两个以上涉及不同税率、征收率的业务；\n（二）业务之间具有明显的主附关系。主要业务居于主体地位，体现交易的实质和目的；附属业务是主要业务的必要补充，并以主要业务的发生为前提。\n第三章　应纳税额\n第十一条　增值税法第十六条所称增值税扣税凭证，应当符合国务院税务主管部门的有关规定，具体包括增值税专用发票、海关进口增值税专用缴款书、完税凭证、农产品收购发票、农产品销售发票以及其他具有进项税额抵扣功能的扣税凭证。\n第十二条　纳税人凭增值税扣税凭证从销项税额中抵扣的进项税额，包括：\n（一）从销售方取得的增值税专用发票上列明的增值税税额；\n（二）从海关取得的海关进口增值税专用缴款书上列明的增值税税额；\n（三）自境外单位或者个人购进服务、无形资产或者境内不动产取得的完税凭证上列明的增值税税额；\n（四）购进农产品时，除取得增值税专用发票或者海关进口增值税专用缴款书外，按照农产品收购发票或者农产品销售发票计算的进项税额，国务院另有规定的除外；\n（五）从销售方取得的其他增值税扣税凭证上列明或者包含的增值税税额。\n第十三条　纳税人按照一般计税方法计算缴纳增值税的，因销售折让、中止或者退回而退还给购买方的增值税税额，应当从当期的销项税额中扣减；因销售折让、中止或者退回而收回的增值税税额，应当从当期的进项税额中扣减', 761, '{\"level\": null, \"title\": null, \"chunk_index\": 1}', 'bge-large-zh-v1.5', '2026-09-25 17:04:28');
INSERT INTO `chunk` VALUES ('4d0fc21e-17fe-4f05-9fcf-deda01fc9012', '821ce1fd-178d-4a7e-ab92-3deff1488ce2', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 84, '第三百六十五条　组织进行淫秽表演的，处三年以下有期徒刑、拘役或者管制，并处罚金；情节严重的，处三年以上十年以下有期徒刑，并处罚金。\n第三百六十六条　单位犯本节第三百六十三条、第三百六十四条、第三百六十五条规定之罪的，对单位判处罚金，并对其直接负责的主管人员和其他直接责任人员，依照各该条的规定处罚。\n第三百六十七条　本法所称淫秽物品，是指具体描绘性行为或者露骨宣扬色情的诲淫性的书刊、影片、录像带、录音带、图片及其他淫秽物品。\n有关人体生理、医学知识的科学著作不是淫秽物品。\n包含有色情内容的有艺术价值的文学、艺术作品不视为淫秽物品。\n第七章　危害国防利益罪\n第三百六十八条　以暴力、威胁方法阻碍军人依法执行职务的，处三年以下有期徒刑、拘役、管制或者罚金。\n故意阻碍武装部队军事行动，造成严重后果的，处五年以下有期徒刑或者拘役。\n第三百六十九条　破坏武器装备、军事设施、军事通信的，处三年以下有期徒刑、拘役或者管制；破坏重要武器装备、军事设施、军事通信的，处三年以上十年以下有期徒刑；情节特别严重的，处十年以上有期徒刑、无期徒刑或者死刑。\n过失犯前款罪，造成严重后果的，处三年以下有期徒刑或者拘役；造成特别严重后果的，处三年以上七年以下有期徒刑。\n战时犯前两款罪的，从重处罚。\n第三百七十条　明知是不合格的武器装备、军事设施而提供给武装部队的，处五年以下有期徒刑或者拘役；情节严重的，处五年以上十年以下有期徒刑；情节特别严重的，处十年以上有期徒刑、无期徒刑或者死刑。\n过失犯前款罪，造成严重后果的，处三年以下有期徒刑或者拘役；造成特别严重后果的，处三年以上七年以下有期徒刑。\n单位犯第一款罪的，对单位判处罚金，并对其直接负责的主管人员和其他直接责任人员，依照第一款的规定处罚', 737, '{\"level\": null, \"title\": null, \"chunk_index\": 84}', 'bge-large-zh-v1.5', '2026-09-25 17:04:56');
INSERT INTO `chunk` VALUES ('4dde91b3-7b62-4ea5-9a1f-e7880dd63c0d', '821ce1fd-178d-4a7e-ab92-3deff1488ce2', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 10, '第三节　自首和立功\n第六十七条　犯罪以后自动投案，如实供述自己的罪行的，是自首。对于自首的犯罪分子，可以从轻或者减轻处罚。其中，犯罪较轻的，可以免除处罚。\n被采取强制措施的犯罪嫌疑人、被告人和正在服刑的罪犯，如实供述司法机关还未掌握的本人其他罪行的，以自首论。\n犯罪嫌疑人虽不具有前两款规定的自首情节，但是如实供述自己罪行的，可以从轻处罚；因其如实供述自己罪行，避免特别严重后果发生的，可以减轻处罚。\n第六十八条　犯罪分子有揭发他人犯罪行为，查证属实的，或者提供重要线索，从而得以侦破其他案件等立功表现的，可以从轻或者减轻处罚；有重大立功表现的，可以减轻或者免除处罚。\n第四节　数罪并罚\n第六十九条　判决宣告以前一人犯数罪的，除判处死刑和无期徒刑的以外，应当在总和刑期以下、数刑中最高刑期以上，酌情决定执行的刑期，但是管制最高不能超过三年，拘役最高不能超过一年，有期徒刑总和刑期不满三十五年的，最高不能超过二十年，总和刑期在三十五年以上的，最高不能超过二十五年。\n数罪中有判处有期徒刑和拘役的，执行有期徒刑。数罪中有判处有期徒刑和管制，或者拘役和管制的，有期徒刑、拘役执行完毕后，管制仍须执行。\n数罪中有判处附加刑的，附加刑仍须执行，其中附加刑种类相同的，合并执行，种类不同的，分别执行。\n第七十条　判决宣告以后，刑罚执行完毕以前，发现被判刑的犯罪分子在判决宣告以前还有其他罪没有判决的，应当对新发现的罪作出判决，把前后两个判决所判处的刑罚，依照本法第六十九条的规定，决定执行的刑罚。已经执行的刑期，应当计算在新判决决定的刑期以内。\n第七十一条　判决宣告以后，刑罚执行完毕以前，被判刑的犯罪分子又犯罪的，应当对新犯的罪作出判决，把前罪没有执行的刑罚和后罪所判处的刑罚，依照本法第六十九条的规定，决定执行的刑罚', 754, '{\"level\": null, \"title\": null, \"chunk_index\": 10}', 'bge-large-zh-v1.5', '2026-09-25 17:04:56');
INSERT INTO `chunk` VALUES ('4e33e74e-4224-4755-93f3-4346c2f20c2e', '16cbea7e-7e36-4f31-afb5-63892345d29c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 62, '国家监察委员会组织协调有关单位建立集中统一、高效顺畅的反腐败国际追逃追赃和防逃协调机制，统筹协调、督促指导各级监察机关反腐败国际追逃追赃等涉外案件办理工作，具体履行下列职责：\n（一）制定反腐败国际追逃追赃和防逃工作计划，研究工作中的重要问题；\n（二）会同有关单位开展反腐败国际追逃追赃等重大涉外案件办理工作；\n（三）办理由国家监察委员会管辖的涉外案件；\n（四）指导地方各级监察机关依法开展涉外案件办理工作；\n（五）汇总和通报全国职务犯罪外逃案件信息和追逃追赃工作信息；\n（六）建立健全反腐败国际追逃追赃和防逃合作网络；\n（七）承担监察机关开展国际刑事司法协助的主管机关职责；\n（八）承担其他与反腐败国际追逃追赃等涉外案件办理工作相关的职责。\n第二百六十六条　地方各级监察机关在国家监察委员会领导下，统筹协调、督促指导本地区反腐败国际追逃追赃等涉外案件办理工作，具体履行下列职责：\n（一）落实上级监察机关关于反腐败国际追逃追赃和防逃工作部署，制定工作计划；\n（二）按照管辖权限或者上级监察机关指定管辖，办理涉外案件；\n（三）按照上级监察机关要求，协助配合其他监察机关开展涉外案件办理工作；\n（四）汇总和通报本地区职务犯罪外逃案件信息和追逃追赃工作信息；\n（五）承担本地区其他与反腐败国际追逃追赃等涉外案件办理工作相关的职责。\n省级监察委员会应当会同有关单位，建立健全本地区反腐败国际追逃追赃和防逃协调机制。\n国家监察委员会派驻或者派出的监察机构、监察专员统筹协调、督促指导驻在单位反腐败国际追逃追赃等涉外案件办理工作，参照第一款规定执行。\n第二百六十七条　国家监察委员会国际合作局归口管理监察机关反腐败国际追逃追赃等涉外案件办理工作。地方各级监察委员会应当明确专责部门，归口管理本地区涉外案件办理工作', 749, '{\"level\": null, \"title\": null, \"chunk_index\": 62}', 'bge-large-zh-v1.5', '2026-09-25 17:04:49');
INSERT INTO `chunk` VALUES ('4f6b514b-8899-4814-9de3-1a22762473c3', '821ce1fd-178d-4a7e-ab92-3deff1488ce2', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 38, '第一百八十三条　保险公司的工作人员利用职务上的便利，故意编造未曾发生的保险事故进行虚假理赔，骗取保险金归自己所有的，依照本法第二百七十一条的规定定罪处罚。\n国有保险公司工作人员和国有保险公司委派到非国有保险公司从事公务的人员有前款行为的，依照本法第三百八十二条、第三百八十三条的规定定罪处罚。\n第一百八十四条　银行或者其他金融机构的工作人员在金融业务活动中索取他人财物或者非法收受他人财物，为他人谋取利益的，或者违反国家规定，收受各种名义的回扣、手续费，归个人所有的，依照本法第一百六十三条的规定定罪处罚。\n国有金融机构工作人员和国有金融机构委派到非国有金融机构从事公务的人员有前款行为的，依照本法第三百八十五条、第三百八十六条的规定定罪处罚。\n第一百八十五条　商业银行、证券交易所、期货交易所、证券公司、期货经纪公司、保险公司或者其他金融机构的工作人员利用职务上的便利，挪用本单位或者客户资金的，依照本法第二百七十二条的规定定罪处罚。\n国有商业银行、证券交易所、期货交易所、证券公司、期货经纪公司、保险公司或者其他国有金融机构的工作人员和国有商业银行、证券交易所、期货交易所、证券公司、期货经纪公司、保险公司或者其他国有金融机构委派到前款规定中的非国有机构从事公务的人员有前款行为的，依照本法第三百八十四条的规定定罪处罚。\n第一百八十五条之一　商业银行、证券交易所、期货交易所、证券公司、期货经纪公司、保险公司或者其他金融机构，违背受托义务，擅自运用客户资金或者其他委托、信托的财产，情节严重的，对单位判处罚金，并对其直接负责的主管人员和其他直接责任人员，处三年以下有期徒刑或者拘役，并处三万元以上三十万元以下罚金；情节特别严重的，处三年以上十年以下有期徒刑，并处五万元以上五十万元以下罚金', 746, '{\"level\": null, \"title\": null, \"chunk_index\": 38}', 'bge-large-zh-v1.5', '2026-09-25 17:04:56');
INSERT INTO `chunk` VALUES ('5012ad26-997e-40d8-8e67-6c6b16f61183', 'b25ce095-dfba-4403-acf8-c58eb456ca4c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 135, '第一千一百八十二条　侵害他人人身权益造成财产损失的，按照被侵权人因此受到的损失或者侵权人因此获得的利益赔偿；被侵权人因此受到的损失以及侵权人因此获得的利益难以确定，被侵权人和侵权人就赔偿数额协商不一致，向人民法院提起诉讼的，由人民法院根据实际情况确定赔偿数额。\n第一千一百八十三条　侵害自然人人身权益造成严重精神损害的，被侵权人有权请求精神损害赔偿。\n因故意或者重大过失侵害自然人具有人身意义的特定物造成严重精神损害的，被侵权人有权请求精神损害赔偿。\n第一千一百八十四条　侵害他人财产的，财产损失按照损失发生时的市场价格或者其他合理方式计算。\n第一千一百八十五条　故意侵害他人知识产权，情节严重的，被侵权人有权请求相应的惩罚性赔偿。\n第一千一百八十六条　受害人和行为人对损害的发生都没有过错的，依照法律的规定由双方分担损失。\n第一千一百八十七条　损害发生后，当事人可以协商赔偿费用的支付方式。协商不一致的，赔偿费用应当一次性支付；一次性支付确有困难的，可以分期支付，但是被侵权人有权请求提供相应的担保。\n第三章　责任主体的特殊规定\n第一千一百八十八条　无民事行为能力人、限制民事行为能力人造成他人损害的，由监护人承担侵权责任。监护人尽到监护职责的，可以减轻其侵权责任。\n有财产的无民事行为能力人、限制民事行为能力人造成他人损害的，从本人财产中支付赔偿费用；不足部分，由监护人赔偿。\n第一千一百八十九条　无民事行为能力人、限制民事行为能力人造成他人损害，监护人将监护职责委托给他人的，监护人应当承担侵权责任；受托人有过错的，承担相应的责任。\n第一千一百九十条　完全民事行为能力人对自己的行为暂时没有意识或者失去控制造成他人损害有过错的，应当承担侵权责任；没有过错的，根据行为人的经济状况对受害人适当补偿', 750, '{\"level\": null, \"title\": null, \"chunk_index\": 135}', 'bge-large-zh-v1.5', '2026-09-25 17:05:01');
INSERT INTO `chunk` VALUES ('5192890f-fb7f-4f37-9197-ff68f19464a6', 'd9d7dc15-8041-43b8-9f75-f112fe3ae003', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 7, '建设单位应当委托具备国家规定的资质条件的机构对危险化学品建设项目进行安全评价，并将安全评价情况报建设项目所在地设区的市级以上人民政府应急管理部门；应急管理部门应当自收到报告之日起二十个工作日内作出安全条件审查决定，并书面通知建设单位。具体办法由国务院应急管理部门制定。\n新建、改建、扩建储存、装卸危险化学品的港口建设项目（以下统称危险化学品港口建设项目），由港口行政管理部门按照国务院交通运输主管部门的规定进行安全条件审查。\n承担安全评价等职责的机构的资质条件由国务院应急管理部门会同有关部门规定。\n第二十四条　危险化学品建设项目和危险化学品港口建设项目的安全设施，必须与主体工程同时设计、同时施工、同时投入生产和使用。安全设施投资应当纳入建设项目概算。\n第二十五条　危险化学品建设项目和危险化学品港口建设项目安全设施的设计人、设计单位应当对安全设施设计负责。在安全设施设计中应当提出保障安全的措施建议。\n第二十六条　危险化学品建设项目的安全设施设计应当报所在地设区的市级以上人民政府应急管理部门审查。具体办法由国务院应急管理部门制定。\n危险化学品港口建设项目的安全设施设计，由港口行政管理部门按照国家有关规定进行审查。\n第二十七条　施工单位必须按照批准的安全设施设计施工，并对安全设施的工程质量和施工安全负责。实行工程监理的危险化学品建设项目，建设单位应当对安全设施施工一并委托监理。\n建设单位应当组织对安全设施进行验收，验收合格方可投入生产和使用。\n对危险化学品建设项目和危险化学品港口建设项目负有安全生产监督管理职责的部门应当加强对建设单位验收活动和验收结果的监督核查。\n第二十八条　生产、储存危险化学品的单位在公共区域埋地、地面和架空的危险化学品输送管道及其附属设施的安全管理，应当符合法律、行政法规的规定和国家标准、行业标准的要求', 770, '{\"level\": null, \"title\": null, \"chunk_index\": 7}', 'bge-large-zh-v1.5', '2026-09-25 17:04:46');
INSERT INTO `chunk` VALUES ('51b811f2-819c-403a-8888-81d1665a061a', '821ce1fd-178d-4a7e-ab92-3deff1488ce2', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 44, '第六节　危害税收征管罪\n第二百零一条　纳税人采取欺骗、隐瞒手段进行虚假纳税申报或者不申报，逃避缴纳税款数额较大并且占应纳税额百分之十以上的，处三年以下有期徒刑或者拘役，并处罚金；数额巨大并且占应纳税额百分之三十以上的，处三年以上七年以下有期徒刑，并处罚金。\n扣缴义务人采取前款所列手段，不缴或者少缴已扣、已收税款，数额较大的，依照前款的规定处罚。\n对多次实施前两款行为，未经处理的，按照累计数额计算。\n有第一款行为，经税务机关依法下达追缴通知后，补缴应纳税款，缴纳滞纳金，已受行政处罚的，不予追究刑事责任；但是，五年内因逃避缴纳税款受过刑事处罚或者被税务机关给予二次以上行政处罚的除外。\n第二百零二条　以暴力、威胁方法拒不缴纳税款的，处三年以下有期徒刑或者拘役，并处拒缴税款一倍以上五倍以下罚金；情节严重的，处三年以上七年以下有期徒刑，并处拒缴税款一倍以上五倍以下罚金。\n第二百零三条　纳税人欠缴应纳税款，采取转移或者隐匿财产的手段，致使税务机关无法追缴欠缴的税款，数额在一万元以上不满十万元的，处三年以下有期徒刑或者拘役，并处或者单处欠缴税款一倍以上五倍以下罚金；数额在十万元以上的，处三年以上七年以下有期徒刑，并处欠缴税款一倍以上五倍以下罚金。\n第二百零四条　以假报出口或者其他欺骗手段，骗取国家出口退税款，数额较大的，处五年以下有期徒刑或者拘役，并处骗取税款一倍以上五倍以下罚金；数额巨大或者有其他严重情节的，处五年以上十年以下有期徒刑，并处骗取税款一倍以上五倍以下罚金；数额特别巨大或者有其他特别严重情节的，处十年以上有期徒刑或者无期徒刑，并处骗取税款一倍以上五倍以下罚金或者没收财产。\n纳税人缴纳税款后，采取前款规定的欺骗方法，骗取所缴纳的税款的，依照本法第二百零一条的规定定罪处罚；骗取税款超过所缴纳的税款部分，依照前款的规定处罚', 771, '{\"level\": null, \"title\": null, \"chunk_index\": 44}', 'bge-large-zh-v1.5', '2026-09-25 17:04:56');
INSERT INTO `chunk` VALUES ('51ca4d21-ebe8-408e-9716-0e99450393dd', '16cbea7e-7e36-4f31-afb5-63892345d29c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 3, '第十六条　监察机关应当坚决维护宪法确立的国家指导思想，加强对公职人员特别是领导人员坚持党的领导、坚持中国特色社会主义制度，贯彻落实党和国家路线方针政策、重大决策部署，履行从严管理监督职责，依法行使公权力等情况的监督。\n第十七条　监察机关应当加强对公职人员理想信念教育、为人民服务教育、宪法法律法规教育和社会主义先进文化、革命文化、中华优秀传统文化教育，弘扬社会主义核心价值观，深入开展警示教育，教育引导公职人员树立正确的权力观、政绩观、事业观，保持为民务实清廉本色。\n第十八条　监察机关应当结合公职人员的职责加强日常监督，通过收集群众反映、座谈走访、查阅资料、召集或者列席会议、听取工作汇报和述责述廉、开展监督检查等方式，促进公职人员依法用权、公正用权、为民用权、廉洁用权。\n第十九条　监察机关可以与公职人员进行谈心谈话，发现政治品行、行使公权力和道德操守方面有苗头性、倾向性问题的，及时进行教育提醒。\n第二十条　监察机关对于发现的行业性、系统性、区域性的突出问题，以及群众反映强烈的问题，可以通过专项监督进行深入了解，督促有关机关、单位强化治理，促进公职人员履职尽责。\n第二十一条　监察机关应当加强基层监督工作，促进基层监督资源和力量整合，有效衔接村（居）务监督等各类基层监督，畅通群众监督渠道，及时发现、处理侵害群众利益的不正之风和腐败问题。\n第二十二条　监察机关应当以办案促进整改、以监督促进治理，在查清问题、依法处置的同时，剖析问题发生的原因，发现制度建设、权力配置、监督机制等方面存在的问题，向有关机关、单位提出改进工作的意见或者监察建议，促进完善制度，提高治理效能。\n对同一行业、系统、区域相关职务违法或者职务犯罪案件，监察机关应当加强类案分析，深入挖掘存在的共性问题，提出综合性改进工作的意见或者监察建议', 759, '{\"level\": null, \"title\": null, \"chunk_index\": 3}', 'bge-large-zh-v1.5', '2026-09-25 17:04:49');
INSERT INTO `chunk` VALUES ('52155845-800f-4d6d-86f2-0662a8e0680e', '16cbea7e-7e36-4f31-afb5-63892345d29c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 67, '口头答复的，由监察机关主要负责人或者委派相关负责人到会答复。书面答复的，由监察机关主要负责人签署。\n第二百八十六条　各级监察机关应当通过互联网政务媒体、报刊、广播、电视等途径，向社会及时准确公开下列监察工作信息：\n（一）监察法规；\n（二）依法应当向社会公开的案件调查信息；\n（三）检举控告地址、电话、网站等信息；\n（四）其他依法应当公开的信息。\n第二百八十七条　各级监察机关可以根据工作需要，按程序选聘特约监察员履行监督、咨询等职责。特约监察员名单应当向社会公布。\n监察机关应当为特约监察员依法开展工作提供必要条件和便利。特约监察员对监察机关提出的意见、建议和批评，监察机关应当及时办理和反馈。\n第二百八十八条　监察机关实行严格的人员准入制度，严把政治关、品行关、能力关、作风关、廉洁关。监察人员必须忠诚坚定、担当尽责、遵纪守法、清正廉洁。\n第二百八十九条　监察机关应当建立信访举报、监督检查、调查、案件监督管理、案件审理等部门相互协调制约的工作机制。\n监督检查和调查部门实行分工协作、相互制约。监督检查部门主要负责联系地区、部门、单位的日常监督检查和对涉嫌一般违法问题线索处置。调查部门主要负责对涉嫌严重职务违法和职务犯罪问题线索进行初步核实和立案调查。\n案件监督管理部门负责对监督检查、调查工作全过程进行监督管理，做好线索管理、组织协调、监督检查、督促办理、统计分析等工作。案件监督管理部门发现监察人员在监督检查、调查中有违规办案行为的，及时督促整改；涉嫌违纪违法的，根据管理权限移交相关部门处理。\n第二百九十条　监察机关应当部署使用覆盖信访举报、线索处置、监督检查、调查、案件审理等监察执法主要流程和关键要素的监察一体化工作平台，推动数字技术融入监察工作，通过信息化手段加强对监督、调查、处置工作的全过程监督管理', 759, '{\"level\": null, \"title\": null, \"chunk_index\": 67}', 'bge-large-zh-v1.5', '2026-09-25 17:04:49');
INSERT INTO `chunk` VALUES ('53a2b6ea-5319-43f9-b9fc-aa278d1b08ac', '821ce1fd-178d-4a7e-ab92-3deff1488ce2', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 79, '第三百四十四条　违反国家规定，非法采伐、毁坏珍贵树木或者国家重点保护的其他植物的，或者非法收购、运输、加工、出售珍贵树木或者国家重点保护的其他植物及其制品的，处三年以下有期徒刑、拘役或者管制，并处罚金；情节严重的，处三年以上七年以下有期徒刑，并处罚金。\n第三百四十四条之一　违反国家规定，非法引进、释放或者丢弃外来入侵物种，情节严重的，处三年以下有期徒刑或者拘役，并处或者单处罚金。\n第三百四十五条　盗伐森林或者其他林木，数量较大的，处三年以下有期徒刑、拘役或者管制，并处或者单处罚金；数量巨大的，处三年以上七年以下有期徒刑，并处罚金；数量特别巨大的，处七年以上有期徒刑，并处罚金。\n违反森林法的规定，滥伐森林或者其他林木，数量较大的，处三年以下有期徒刑、拘役或者管制，并处或者单处罚金；数量巨大的，处三年以上七年以下有期徒刑，并处罚金。\n非法收购、运输明知是盗伐、滥伐的林木，情节严重的，处三年以下有期徒刑、拘役或者管制，并处或者单处罚金；情节特别严重的，处三年以上七年以下有期徒刑，并处罚金。\n盗伐、滥伐国家级自然保护区内的森林或者其他林木的，从重处罚。\n第三百四十六条　单位犯本节第三百三十八条至第三百四十五条规定之罪的，对单位判处罚金，并对其直接负责的主管人员和其他直接责任人员，依照本节各该条的规定处罚。\n第七节　走私、贩卖、运输、制造毒品罪\n第三百四十七条　走私、贩卖、运输、制造毒品，无论数量多少，都应当追究刑事责任，予以刑事处罚', 622, '{\"level\": null, \"title\": null, \"chunk_index\": 79}', 'bge-large-zh-v1.5', '2026-09-25 17:04:56');
INSERT INTO `chunk` VALUES ('54150b83-0d76-4400-95a0-ff71c503ba4d', '821ce1fd-178d-4a7e-ab92-3deff1488ce2', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 30, '第一百六十三条　公司、企业或者其他单位的工作人员，利用职务上的便利，索取他人财物或者非法收受他人财物，为他人谋取利益，数额较大的，处三年以下有期徒刑或者拘役，并处罚金；数额巨大或者有其他严重情节的，处三年以上十年以下有期徒刑，并处罚金；数额特别巨大或者有其他特别严重情节的，处十年以上有期徒刑或者无期徒刑，并处罚金。\n公司、企业或者其他单位的工作人员在经济往来中，利用职务上的便利，违反国家规定，收受各种名义的回扣、手续费，归个人所有的，依照前款的规定处罚。\n国有公司、企业或者其他国有单位中从事公务的人员和国有公司、企业或者其他国有单位委派到非国有公司、企业以及其他单位从事公务的人员有前两款行为的，依照本法第三百八十五条、第三百八十六条的规定定罪处罚。\n第一百六十四条　为谋取不正当利益，给予公司、企业或者其他单位的工作人员以财物，数额较大的，处三年以下有期徒刑或者拘役，并处罚金；数额巨大的，处三年以上十年以下有期徒刑，并处罚金。\n为谋取不正当商业利益，给予外国公职人员或者国际公共组织官员以财物的，依照前款的规定处罚。\n单位犯前两款罪的，对单位判处罚金，并对其直接负责的主管人员和其他直接责任人员，依照第一款的规定处罚。\n行贿人在被追诉前主动交待行贿行为的，可以减轻处罚或者免除处罚。\n第一百六十五条　国有公司、企业的董事、经理利用职务便利，自己经营或者为他人经营与其所任职公司、企业同类的营业，获取非法利益，数额巨大的，处三年以下有期徒刑或者拘役，并处或者单处罚金；数额特别巨大的，处三年以上七年以下有期徒刑，并处罚金', 664, '{\"level\": null, \"title\": null, \"chunk_index\": 30}', 'bge-large-zh-v1.5', '2026-09-25 17:04:56');
INSERT INTO `chunk` VALUES ('556ad73f-172c-4c98-8ce9-37185525969a', 'b25ce095-dfba-4403-acf8-c58eb456ca4c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 88, '第七百七十八条　承揽工作需要定作人协助的，定作人有协助的义务。定作人不履行协助义务致使承揽工作不能完成的，承揽人可以催告定作人在合理期限内履行义务，并可以顺延履行期限；定作人逾期不履行的，承揽人可以解除合同。\n第七百七十九条　承揽人在工作期间，应当接受定作人必要的监督检验。定作人不得因监督检验妨碍承揽人的正常工作。\n第七百八十条　承揽人完成工作的，应当向定作人交付工作成果，并提交必要的技术资料和有关质量证明。定作人应当验收该工作成果。\n第七百八十一条　承揽人交付的工作成果不符合质量要求的，定作人可以合理选择请求承揽人承担修理、重作、减少报酬、赔偿损失等违约责任。\n第七百八十二条　定作人应当按照约定的期限支付报酬。对支付报酬的期限没有约定或者约定不明确，依据本法第五百一十条的规定仍不能确定的，定作人应当在承揽人交付工作成果时支付；工作成果部分交付的，定作人应当相应支付。\n第七百八十三条　定作人未向承揽人支付报酬或者材料费等价款的，承揽人对完成的工作成果享有留置权或者有权拒绝交付，但是当事人另有约定的除外。\n第七百八十四条　承揽人应当妥善保管定作人提供的材料以及完成的工作成果，因保管不善造成毁损、灭失的，应当承担赔偿责任。\n第七百八十五条　承揽人应当按照定作人的要求保守秘密，未经定作人许可，不得留存复制品或者技术资料。\n第七百八十六条　共同承揽人对定作人承担连带责任，但是当事人另有约定的除外。\n第七百八十七条　定作人在承揽人完成工作前可以随时解除合同，造成承揽人损失的，应当赔偿损失。\n第十八章　建设工程合同\n第七百八十八条　建设工程合同是承包人进行工程建设，发包人支付价款的合同。\n建设工程合同包括工程勘察、设计、施工合同。\n第七百八十九条　建设工程合同应当采用书面形式。\n第七百九十条　建设工程的招标投标活动，应当依照有关法律的规定公开、公平、公正进行', 786, '{\"level\": null, \"title\": null, \"chunk_index\": 88}', 'bge-large-zh-v1.5', '2026-09-25 17:05:01');
INSERT INTO `chunk` VALUES ('5606b693-dc20-41d8-bdaa-998f1d833896', '16cbea7e-7e36-4f31-afb5-63892345d29c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 1, '第七条　监察机关应当尊重和保障人权，在适用法律上一律平等，充分保障监察对象以及相关人员的人身权、知情权、财产权、申辩权、申诉权以及申请复审复核权等合法权益。\n第八条　监察机关办理职务犯罪案件，应当与人民法院、人民检察院互相配合、互相制约，在案件管辖、证据审查、案件移送、涉案财物处置等方面加强沟通协调，对于人民法院、人民检察院提出的退回补充调查、排除非法证据、调取同步录音录像、要求调查人员出庭等意见依法办理。\n第九条　监察机关开展监察工作，可以依法提请组织人事、公安、国家安全、移民管理、审计、统计、市场监管、金融监管、财政、税务、自然资源、银行、证券、保险等有关部门、单位予以协助配合。\n有关部门、单位应当根据监察机关的要求，依法协助采取有关措施、共享相关信息、提供相关资料和专业技术支持，配合开展监察工作。\n第二章　监察机关及其职责\n第一节　领导体制\n第十条　国家监察委员会在党中央领导下开展工作。地方各级监察委员会在同级党委和上级监察委员会双重领导下工作，监督执法调查工作以上级监察委员会领导为主，线索处置和案件查办在向同级党委报告的同时应当一并向上一级监察委员会报告。\n上级监察委员会应当加强对下级监察委员会的领导。下级监察委员会对上级监察委员会的决定必须执行，认为决定不当的，应当在执行的同时向上级监察委员会反映。上级监察委员会对下级监察委员会作出的错误决定，应当按程序予以纠正，或者要求下级监察委员会予以纠正。\n第十一条　上级监察委员会可以依法统一调用所辖各级监察机关的监察人员办理监察事项。调用决定应当以书面形式作出。\n监察机关办理监察事项应当加强互相协作和配合，对于重要、复杂事项可以提请上级监察机关予以协调', 713, '{\"level\": null, \"title\": null, \"chunk_index\": 1}', 'bge-large-zh-v1.5', '2026-09-25 17:04:49');
INSERT INTO `chunk` VALUES ('59f1874a-637b-4339-9b2b-45612516864d', '821ce1fd-178d-4a7e-ab92-3deff1488ce2', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 96, '第四百三十一条　以窃取、刺探、收买方法，非法获取军事秘密的，处五年以下有期徒刑；情节严重的，处五年以上十年以下有期徒刑；情节特别严重的，处十年以上有期徒刑。\n为境外的机构、组织、人员窃取、刺探、收买、非法提供军事秘密的，处五年以上十年以下有期徒刑；情节严重的，处十年以上有期徒刑、无期徒刑或者死刑。\n第四百三十二条　违反保守国家秘密法规，故意或者过失泄露军事秘密，情节严重的，处五年以下有期徒刑或者拘役；情节特别严重的，处五年以上十年以下有期徒刑。\n战时犯前款罪的，处五年以上十年以下有期徒刑；情节特别严重的，处十年以上有期徒刑或者无期徒刑。\n第四百三十三条　战时造谣惑众，动摇军心的，处三年以下有期徒刑；情节严重的，处三年以上十年以下有期徒刑；情节特别严重的，处十年以上有期徒刑或者无期徒刑。\n第四百三十四条　战时自伤身体，逃避军事义务的，处三年以下有期徒刑；情节严重的，处三年以上七年以下有期徒刑。\n第四百三十五条　违反兵役法规，逃离部队，情节严重的，处三年以下有期徒刑或者拘役。\n战时犯前款罪的，处三年以上七年以下有期徒刑。\n第四百三十六条　违反武器装备使用规定，情节严重，因而发生责任事故，致人重伤、死亡或者造成其他严重后果的，处三年以下有期徒刑或者拘役；后果特别严重的，处三年以上七年以下有期徒刑。\n第四百三十七条　违反武器装备管理规定，擅自改变武器装备的编配用途，造成严重后果的，处三年以下有期徒刑或者拘役；造成特别严重后果的，处三年以上七年以下有期徒刑。\n第四百三十八条　盗窃、抢夺武器装备或者军用物资的，处五年以下有期徒刑或者拘役；情节严重的，处五年以上十年以下有期徒刑；情节特别严重的，处十年以上有期徒刑、无期徒刑或者死刑。\n盗窃、抢夺枪支、弹药、爆炸物的，依照本法第一百二十七条的规定处罚', 754, '{\"level\": null, \"title\": null, \"chunk_index\": 96}', 'bge-large-zh-v1.5', '2026-09-25 17:04:56');
INSERT INTO `chunk` VALUES ('5a8b0131-2dd0-4d15-baf5-d970b0441037', 'b25ce095-dfba-4403-acf8-c58eb456ca4c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 81, '第七百一十四条　承租人应当妥善保管租赁物，因保管不善造成租赁物毁损、灭失的，应当承担赔偿责任。\n第七百一十五条　承租人经出租人同意，可以对租赁物进行改善或者增设他物。\n承租人未经出租人同意，对租赁物进行改善或者增设他物的，出租人可以请求承租人恢复原状或者赔偿损失。\n第七百一十六条　承租人经出租人同意，可以将租赁物转租给第三人。承租人转租的，承租人与出租人之间的租赁合同继续有效；第三人造成租赁物损失的，承租人应当赔偿损失。\n承租人未经出租人同意转租的，出租人可以解除合同。\n第七百一十七条　承租人经出租人同意将租赁物转租给第三人，转租期限超过承租人剩余租赁期限的，超过部分的约定对出租人不具有法律约束力，但是出租人与承租人另有约定的除外。\n第七百一十八条　出租人知道或者应当知道承租人转租，但是在六个月内未提出异议的，视为出租人同意转租。\n第七百一十九条　承租人拖欠租金的，次承租人可以代承租人支付其欠付的租金和违约金，但是转租合同对出租人不具有法律约束力的除外。\n次承租人代为支付的租金和违约金，可以充抵次承租人应当向承租人支付的租金；超出其应付的租金数额的，可以向承租人追偿。\n第七百二十条　在租赁期限内因占有、使用租赁物获得的收益，归承租人所有，但是当事人另有约定的除外。\n第七百二十一条　承租人应当按照约定的期限支付租金。对支付租金的期限没有约定或者约定不明确，依据本法第五百一十条的规定仍不能确定，租赁期限不满一年的，应当在租赁期限届满时支付；租赁期限一年以上的，应当在每届满一年时支付，剩余期限不满一年的，应当在租赁期限届满时支付。\n第七百二十二条　承租人无正当理由未支付或者迟延支付租金的，出租人可以请求承租人在合理期限内支付；承租人逾期不支付的，出租人可以解除合同。\n第七百二十三条　因第三人主张权利，致使承租人不能对租赁物使用、收益的，承租人可以请求减少租金或者不支付租金', 796, '{\"level\": null, \"title\": null, \"chunk_index\": 81}', 'bge-large-zh-v1.5', '2026-09-25 17:05:01');
INSERT INTO `chunk` VALUES ('5a973b34-cc49-47eb-9b0a-bd2cca62298b', 'b25ce095-dfba-4403-acf8-c58eb456ca4c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 60, '第五百二十六条　当事人互负债务，有先后履行顺序，应当先履行债务一方未履行的，后履行一方有权拒绝其履行请求。先履行一方履行债务不符合约定的，后履行一方有权拒绝其相应的履行请求。\n第五百二十七条　应当先履行债务的当事人，有确切证据证明对方有下列情形之一的，可以中止履行：\n（一）经营状况严重恶化；\n（二）转移财产、抽逃资金，以逃避债务；\n（三）丧失商业信誉；\n（四）有丧失或者可能丧失履行债务能力的其他情形。\n当事人没有确切证据中止履行的，应当承担违约责任。\n第五百二十八条　当事人依据前条规定中止履行的，应当及时通知对方。对方提供适当担保的，应当恢复履行。中止履行后，对方在合理期限内未恢复履行能力且未提供适当担保的，视为以自己的行为表明不履行主要债务，中止履行的一方可以解除合同并可以请求对方承担违约责任。\n第五百二十九条　债权人分立、合并或者变更住所没有通知债务人，致使履行债务发生困难的，债务人可以中止履行或者将标的物提存。\n第五百三十条　债权人可以拒绝债务人提前履行债务，但是提前履行不损害债权人利益的除外。\n债务人提前履行债务给债权人增加的费用，由债务人负担。\n第五百三十一条　债权人可以拒绝债务人部分履行债务，但是部分履行不损害债权人利益的除外。\n债务人部分履行债务给债权人增加的费用，由债务人负担。\n第五百三十二条　合同生效后，当事人不得因姓名、名称的变更或者法定代表人、负责人、承办人的变动而不履行合同义务。\n第五百三十三条　合同成立后，合同的基础条件发生了当事人在订立合同时无法预见的、不属于商业风险的重大变化，继续履行合同对于当事人一方明显不公平的，受不利影响的当事人可以与对方重新协商；在合理期限内协商不成的，当事人可以请求人民法院或者仲裁机构变更或者解除合同。\n人民法院或者仲裁机构应当结合案件的实际情况，根据公平原则变更或者解除合同', 778, '{\"level\": null, \"title\": null, \"chunk_index\": 60}', 'bge-large-zh-v1.5', '2026-09-25 17:05:01');
INSERT INTO `chunk` VALUES ('5c9650f6-74eb-4415-a7e8-1c7bd8307baa', '16cbea7e-7e36-4f31-afb5-63892345d29c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 20, '证人未被限制人身自由的，应当在首次询问时向其出具《询问通知书》。\n询问时，应当核实证人身份，问明证人的基本情况，告知证人应当如实提供证据、证言，以及作伪证或者隐匿证据应当承担的法律责任。不得向证人泄露案情，不得采用非法方法获取证言。\n询问重大或者有社会影响案件的重要证人，应当对询问过程全程同步录音录像，并告知证人。告知情况应当在录音录像中予以反映，并在笔录中记明。\n第九十五条　询问未成年人，应当通知其法定代理人到场。无法通知或者法定代理人不能到场的，应当通知未成年人的其他成年亲属或者所在学校、居住地基层组织的代表等有关人员到场。询问结束后，由法定代理人或者有关人员在笔录中签名。调查人员应当将到场情况记录在案。\n询问聋、哑人，应当有通晓聋、哑手势的人员参加。调查人员应当在笔录中记明证人的聋、哑情况，以及翻译人员的姓名、工作单位和职业。询问不通晓当地通用语言、文字的证人，应当有翻译人员。询问结束后，由翻译人员在笔录中签名。\n第九十六条　凡是知道案件情况的人，都有如实作证的义务。对故意提供虚假证言的证人，应当依法追究法律责任。\n证人或者其他任何人不得帮助被调查人伪造、隐匿、毁灭证据或者串供，不得实施其他干扰调查活动的行为。\n第九十七条　证人、鉴定人、被害人因作证，本人或者近亲属人身安全面临危险，向监察机关请求保护的，监察机关应当受理并及时进行审查；对于确实存在人身安全危险的，监察机关应当采取必要的保护措施。监察机关发现存在上述情形的，应当主动采取保护措施。\n监察机关可以采取下列一项或者多项保护措施：\n（一）不公开真实姓名、住址和工作单位等个人信息；\n（二）禁止特定的人员接触证人、鉴定人、被害人及其近亲属；\n（三）对人身和住宅采取专门性保护措施；\n（四）其他必要的保护措施', 744, '{\"level\": null, \"title\": null, \"chunk_index\": 20}', 'bge-large-zh-v1.5', '2026-09-25 17:04:49');
INSERT INTO `chunk` VALUES ('5cc9338e-b4af-4480-a3eb-a9af1e262699', 'd9d7dc15-8041-43b8-9f75-f112fe3ae003', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 19, '第七十一条　通过道路运输剧毒化学品，托运人应当向运输始发地或者目的地县级人民政府公安机关申请剧毒化学品道路运输通行证。\n申请剧毒化学品道路运输通行证，托运人应当向县级人民政府公安机关提交下列材料：\n（一）拟运输的剧毒化学品品种、数量的说明；\n（二）运输始发地、目的地、运输时间和运输路线的说明；\n（三）承运人取得相应危险货物道路运输许可、运输车辆取得相应营运证以及驾驶人员、押运人员取得相应上岗资格的证明文件；\n（四）本法第五十八条第一款、第二款规定的购买剧毒化学品的相关许可证件，或者海关出具的进出口证明文件。\n县级人民政府公安机关应当自收到前款规定的材料之日起七个工作日内，作出批准或者不予批准的决定。予以批准的，颁发剧毒化学品道路运输通行证；不予批准的，书面通知申请人并说明理由。\n剧毒化学品道路运输通行证管理按照国务院公安部门的规定执行。\n第七十二条　剧毒化学品、易制爆危险化学品在道路运输途中丢失、被盗、被抢或者出现流散、泄漏等情况的，驾驶人员、押运人员应当立即采取相应的警示措施和安全措施，并向当地公安机关报告。公安机关接到报告后，应当根据实际情况立即向交通运输、应急管理、生态环境、卫生健康部门通报。有关部门应当采取必要的应急处置措施。\n第七十三条　海事管理机构应当根据危险化学品的种类和危险特性，确定船舶运输危险化学品的安全运输条件。\n拟交付船舶运输的化学品的安全运输条件不明确的，货物所有人或者代理人应当委托相关技术机构进行评估，明确相关安全运输条件并经海事管理机构确认后，方可交付船舶运输。\n第七十四条　禁止通过内河封闭水域运输剧毒化学品。\n禁止通过内河水域运输国家规定禁止通过内河运输的危险化学品', 709, '{\"level\": null, \"title\": null, \"chunk_index\": 19}', 'bge-large-zh-v1.5', '2026-09-25 17:04:46');
INSERT INTO `chunk` VALUES ('5d74584c-a961-403b-a595-33dc09bef158', 'd9d7dc15-8041-43b8-9f75-f112fe3ae003', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 15, '法律、行政法规或者国务院规定经营危险化学品还需要经其他有关部门许可的，申请人向市场监督管理部门办理登记手续时应当持相应的许可证件。\n第五十六条　危险化学品经营企业储存危险化学品的，应当遵守本法第三章关于储存危险化学品的规定。危险化学品商店内只能存放民用小包装的危险化学品。\n第五十七条　危险化学品生产企业、经营企业在销售危险化学品时，应当向购买单位或者个人提供符合法律、行政法规规定和国家标准、行业标准要求的化学品安全技术说明书，不得经营没有化学品安全技术说明书或者化学品安全标签的危险化学品，不得擅自更改化学品安全技术说明书或者化学品安全标签。\n任何单位和个人购买危险化学品时，有权向危险化学品生产企业、经营企业索取有关危险化学品的安全技术说明书，了解其危险特性、防护措施和使用方法。\n第五十八条　依法取得危险化学品安全生产许可证、危险化学品安全使用许可证或者危险化学品经营许可证的企业，凭相应的许可证件购买剧毒化学品、易制爆危险化学品。民用爆炸物品、烟花爆竹、武器装备科研生产企业凭相应许可证购买易制爆危险化学品。\n前款规定以外的单位购买剧毒化学品的，应当向所在地县级人民政府公安机关申请取得剧毒化学品购买许可证；购买易制爆危险化学品的，应当持本单位出具的合法用途说明。\n个人不得购买剧毒化学品（属于剧毒化学品的农药除外）和易制爆危险化学品（含有易制爆危险化学品的食品添加剂、药品、兽药、消毒剂等生活用品除外）。\n第五十九条　申请取得剧毒化学品购买许可证，申请人应当向所在地县级人民政府公安机关提交下列材料：\n（一）营业执照或者法人证书（登记证书）的复印件；\n（二）拟购买的剧毒化学品品种、数量的说明；\n（三）购买剧毒化学品用途的说明；\n（四）经办人的身份证明。\n县级人民政府公安机关应当自收到前款规定的材料之日起三个工作日内，作出批准或者不予批准的决定', 779, '{\"level\": null, \"title\": null, \"chunk_index\": 15}', 'bge-large-zh-v1.5', '2026-09-25 17:04:46');
INSERT INTO `chunk` VALUES ('5d99df2a-3a39-40d0-a516-7ba4249eb67a', '821ce1fd-178d-4a7e-ab92-3deff1488ce2', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 25, '第一百四十六条　生产不符合保障人身、财产安全的国家标准、行业标准的电器、压力容器、易燃易爆产品或者其他不符合保障人身、财产安全的国家标准、行业标准的产品，或者销售明知是以上不符合保障人身、财产安全的国家标准、行业标准的产品，造成严重后果的，处五年以下有期徒刑，并处销售金额百分之五十以上二倍以下罚金；后果特别严重的，处五年以上有期徒刑，并处销售金额百分之五十以上二倍以下罚金。\n第一百四十七条　生产假农药、假兽药、假化肥，销售明知是假的或者失去使用效能的农药、兽药、化肥、种子，或者生产者、销售者以不合格的农药、兽药、化肥、种子冒充合格的农药、兽药、化肥、种子，使生产遭受较大损失的，处三年以下有期徒刑或者拘役，并处或者单处销售金额百分之五十以上二倍以下罚金；使生产遭受重大损失的，处三年以上七年以下有期徒刑，并处销售金额百分之五十以上二倍以下罚金；使生产遭受特别重大损失的，处七年以上有期徒刑或者无期徒刑，并处销售金额百分之五十以上二倍以下罚金或者没收财产。\n第一百四十八条　生产不符合卫生标准的化妆品，或者销售明知是不符合卫生标准的化妆品，造成严重后果的，处三年以下有期徒刑或者拘役，并处或者单处销售金额百分之五十以上二倍以下罚金。\n第一百四十九条　生产、销售本节第一百四十一条至第一百四十八条所列产品，不构成各该条规定的犯罪，但是销售金额在五万元以上的，依照本节第一百四十条的规定定罪处罚。\n生产、销售本节第一百四十一条至第一百四十八条所列产品，构成各该条规定的犯罪，同时又构成本节第一百四十条规定之罪的，依照处罚较重的规定定罪处罚。\n第一百五十条　单位犯本节第一百四十条至第一百四十八条规定之罪的，对单位判处罚金，并对其直接负责的主管人员和其他直接责任人员，依照各该条的规定处罚', 743, '{\"level\": null, \"title\": null, \"chunk_index\": 25}', 'bge-large-zh-v1.5', '2026-09-25 17:04:56');
INSERT INTO `chunk` VALUES ('5dc82a00-0144-490e-84a1-3c0ecc06b0e9', 'b25ce095-dfba-4403-acf8-c58eb456ca4c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 98, '第三节　技术转让合同和技术许可合同\n第八百六十二条　技术转让合同是合法拥有技术的权利人，将现有特定的专利、专利申请、技术秘密的相关权利让与他人所订立的合同。\n技术许可合同是合法拥有技术的权利人，将现有特定的专利、技术秘密的相关权利许可他人实施、使用所订立的合同。\n技术转让合同和技术许可合同中关于提供实施技术的专用设备、原材料或者提供有关的技术咨询、技术服务的约定，属于合同的组成部分。\n第八百六十三条　技术转让合同包括专利权转让、专利申请权转让、技术秘密转让等合同。\n技术许可合同包括专利实施许可、技术秘密使用许可等合同。\n技术转让合同和技术许可合同应当采用书面形式。\n第八百六十四条　技术转让合同和技术许可合同可以约定实施专利或者使用技术秘密的范围，但是不得限制技术竞争和技术发展。\n第八百六十五条　专利实施许可合同仅在该专利权的存续期限内有效。专利权有效期限届满或者专利权被宣告无效的，专利权人不得就该专利与他人订立专利实施许可合同。\n第八百六十六条　专利实施许可合同的许可人应当按照约定许可被许可人实施专利，交付实施专利有关的技术资料，提供必要的技术指导。\n第八百六十七条　专利实施许可合同的被许可人应当按照约定实施专利，不得许可约定以外的第三人实施该专利，并按照约定支付使用费。\n第八百六十八条　技术秘密转让合同的让与人和技术秘密使用许可合同的许可人应当按照约定提供技术资料，进行技术指导，保证技术的实用性、可靠性，承担保密义务。\n前款规定的保密义务，不限制许可人申请专利，但是当事人另有约定的除外。\n第八百六十九条　技术秘密转让合同的受让人和技术秘密使用许可合同的被许可人应当按照约定使用技术，支付转让费、使用费，承担保密义务。\n第八百七十条　技术转让合同的让与人和技术许可合同的许可人应当保证自己是所提供的技术的合法拥有者，并保证所提供的技术完整、无误、有效，能够达到约定的目标', 796, '{\"level\": null, \"title\": null, \"chunk_index\": 98}', 'bge-large-zh-v1.5', '2026-09-25 17:05:01');
INSERT INTO `chunk` VALUES ('5e9d3c54-d014-4de4-9944-dfd01ddf33b8', 'b25ce095-dfba-4403-acf8-c58eb456ca4c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 87, '第七百六十八条　应收账款债权人就同一应收账款订立多个保理合同，致使多个保理人主张权利的，已经登记的先于未登记的取得应收账款；均已经登记的，按照登记时间的先后顺序取得应收账款；均未登记的，由最先到达应收账款债务人的转让通知中载明的保理人取得应收账款；既未登记也未通知的，按照保理融资款或者服务报酬的比例取得应收账款。\n第七百六十九条　本章没有规定的，适用本编第六章债权转让的有关规定。\n第十七章　承揽合同\n第七百七十条　承揽合同是承揽人按照定作人的要求完成工作，交付工作成果，定作人支付报酬的合同。\n承揽包括加工、定作、修理、复制、测试、检验等工作。\n第七百七十一条　承揽合同的内容一般包括承揽的标的、数量、质量、报酬，承揽方式，材料的提供，履行期限，验收标准和方法等条款。\n第七百七十二条　承揽人应当以自己的设备、技术和劳力，完成主要工作，但是当事人另有约定的除外。\n承揽人将其承揽的主要工作交由第三人完成的，应当就该第三人完成的工作成果向定作人负责；未经定作人同意的，定作人也可以解除合同。\n第七百七十三条　承揽人可以将其承揽的辅助工作交由第三人完成。承揽人将其承揽的辅助工作交由第三人完成的，应当就该第三人完成的工作成果向定作人负责。\n第七百七十四条　承揽人提供材料的，应当按照约定选用材料，并接受定作人检验。\n第七百七十五条　定作人提供材料的，应当按照约定提供材料。承揽人对定作人提供的材料应当及时检验，发现不符合约定时，应当及时通知定作人更换、补齐或者采取其他补救措施。\n承揽人不得擅自更换定作人提供的材料，不得更换不需要修理的零部件。\n第七百七十六条　承揽人发现定作人提供的图纸或者技术要求不合理的，应当及时通知定作人。因定作人怠于答复等原因造成承揽人损失的，应当赔偿损失。\n第七百七十七条　定作人中途变更承揽工作的要求，造成承揽人损失的，应当赔偿损失', 781, '{\"level\": null, \"title\": null, \"chunk_index\": 87}', 'bge-large-zh-v1.5', '2026-09-25 17:05:01');
INSERT INTO `chunk` VALUES ('5edeef78-6aca-469c-88da-4c175bc34415', '821ce1fd-178d-4a7e-ab92-3deff1488ce2', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 49, '第二百一十九条之一　为境外的机构、组织、人员窃取、刺探、收买、非法提供商业秘密的，处五年以下有期徒刑，并处或者单处罚金；情节严重的，处五年以上有期徒刑，并处罚金。\n第二百二十条　单位犯本节第二百一十三条至第二百一十九条之一规定之罪的，对单位判处罚金，并对其直接负责的主管人员和其他直接责任人员，依照本节各该条的规定处罚。\n第八节　扰乱市场秩序罪\n第二百二十一条　捏造并散布虚伪事实，损害他人的商业信誉、商品声誉，给他人造成重大损失或者有其他严重情节的，处二年以下有期徒刑或者拘役，并处或者单处罚金。\n第二百二十二条　广告主、广告经营者、广告发布者违反国家规定，利用广告对商品或者服务作虚假宣传，情节严重的，处二年以下有期徒刑或者拘役，并处或者单处罚金。\n第二百二十三条　投标人相互串通投标报价，损害招标人或者其他投标人利益，情节严重的，处三年以下有期徒刑或者拘役，并处或者单处罚金。\n投标人与招标人串通投标，损害国家、集体、公民的合法利益的，依照前款的规定处罚。\n第二百二十四条　有下列情形之一，以非法占有为目的，在签订、履行合同过程中，骗取对方当事人财物，数额较大的，处三年以下有期徒刑或者拘役，并处或者单处罚金；数额巨大或者有其他严重情节的，处三年以上十年以下有期徒刑，并处罚金；数额特别巨大或者有其他特别严重情节的，处十年以上有期徒刑或者无期徒刑，并处罚金或者没收财产：\n（一）以虚构的单位或者冒用他人名义签订合同的；\n（二）以伪造、变造、作废的票据或者其他虚假的产权证明作担保的；\n（三）没有实际履行能力，以先履行小额合同或者部分履行合同的方法，诱骗对方当事人继续签订和履行合同的；\n（四）收受对方当事人给付的货物、货款、预付款或者担保财产后逃匿的；\n（五）以其他方法骗取对方当事人财物的', 748, '{\"level\": null, \"title\": null, \"chunk_index\": 49}', 'bge-large-zh-v1.5', '2026-09-25 17:04:56');
INSERT INTO `chunk` VALUES ('5f2d4ea2-edd0-40e1-8981-32483602ee8c', '0497a5e7-7044-4b18-8fed-af3fb7bc7890', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 2, '第十四条　纳税人按照简易计税方法计算缴纳增值税的，因销售折让、中止或者退回而退还给购买方的销售额，应当从当期销售额中扣减。扣减当期销售额后仍有多缴税款的，可以从以后的应纳税额中扣减或者按规定申请退还。\n第十五条　增值税法第十七条所称全部价款，不包括纳税人代为收取的下列税费或者款项：\n（一）政府性基金或者行政事业性收费；\n（二）受托加工应征消费税的消费品所产生的消费税；\n（三）车辆购置税、车船税；\n（四）以委托方名义开具发票代委托方收取的款项。\n第十六条　纳税人采用销售额和增值税税额合并定价方法的，按照下列公式计算销售额：\n一般计税方法的销售额＝含税销售额÷（1+税率）\n简易计税方法的销售额＝含税销售额÷（1＋征收率）\n第十七条　纳税人以人民币以外的货币结算销售额的，在折合成人民币计算时，折合率可以选择销售额发生的当日或者当月1日有效的人民币汇率中间价。纳税人确定折合率后，12个月内不得变更。\n第十八条　纳税人发生增值税法第二十条规定情形的，税务机关可以按顺序依照下列方法核定销售额：\n（一）按照纳税人最近时期销售同类货物、服务、无形资产或者不动产的平均价格确定；\n（二）按照其他纳税人最近时期销售同类货物、服务、无形资产或者不动产的平均价格确定；\n（三）按照组成计税价格确定。组成计税价格的公式为：\n组成计税价格=成本×（1+成本利润率）+消费税税额\n公式中成本利润率为10%，国务院税务主管部门可以根据行业成本利润实际情况调整成本利润率。\n第十九条　增值税法第二十二条第三项所称非正常损失，是指因管理不善造成货物被盗、丢失、霉烂变质，以及因违反法律法规造成货物或者不动产被依法没收、销毁、拆除等情形', 706, '{\"level\": null, \"title\": null, \"chunk_index\": 2}', 'bge-large-zh-v1.5', '2026-09-25 17:04:28');
INSERT INTO `chunk` VALUES ('602cce32-7e79-43b7-8c4b-709db721b93b', '16cbea7e-7e36-4f31-afb5-63892345d29c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 12, '人民检察院在办理直接受理侦查的案件中，发现犯罪嫌疑人同时涉嫌监察机关管辖的其他职务犯罪，经沟通全案移送监察机关管辖的，监察机关应当依法进行调查。\n第五十六条　监察机关对于退休公职人员在退休前或者退休后，或者离职、死亡的公职人员在履职期间实施的涉嫌职务违法或者职务犯罪行为，可以依法进行调查。\n对前款规定人员，按照其原任职务的管辖规定确定管辖的监察机关；由其他监察机关管辖更为适宜的，可以依法指定或者交由其他监察机关管辖。\n第四章　监察权限\n第一节　一般要求\n第五十七条　监察机关应当加强监督执法调查工作规范化建设，严格按规定对监察措施进行审批和监管，依照法定的范围、程序和期限采取相关措施，出具、送达法律文书。\n第五十八条　监察机关应当根据开展监督执法调查工作的需要、涉嫌职务违法或者职务犯罪行为的严重程度、监察措施适用对象与案件的关联程度，以及采取监察措施的紧急程度等情况，合理确定采取监察措施的对象、种类和期限，不得超过必要限度。禁止违反规定滥用监察措施。\n第五十九条　监察机关在初步核实中，可以依法采取谈话、询问、查询、调取、勘验检查、调查实验、鉴定措施；立案后可以采取讯问、强制到案、责令候查、管护、留置、禁闭、冻结、搜查、查封、扣押、通缉措施。发现存在逃跑、自杀等重大安全风险，在立案前依法对监察法第二十五条第一款第一项、第二项规定的人员采取管护措施的，符合立案条件的应当及时立案。需要采取技术调查、限制出境措施的，应当按照规定交有关机关依法执行。设区的市级以下监察机关在初步核实中不得采取技术调查措施。监察机关采取谈话、函询方式处置问题线索的，适用监察法和本条例关于采取该两项措施的相关规定。\n开展问责调查，根据具体情况可以依法采取相关监察措施。\n第六十条　开展讯问、搜查、查封、扣押以及重要的谈话、询问等调查取证工作，应当全程同步录音录像，并保持录音录像资料的完整性', 790, '{\"level\": null, \"title\": null, \"chunk_index\": 12}', 'bge-large-zh-v1.5', '2026-09-25 17:04:49');
INSERT INTO `chunk` VALUES ('610c1692-4f04-4a30-a476-9cf1f56ec03b', 'b25ce095-dfba-4403-acf8-c58eb456ca4c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 85, '第七百五十三条　承租人未经出租人同意，将租赁物转让、抵押、质押、投资入股或者以其他方式处分的，出租人可以解除融资租赁合同。\n第七百五十四条　有下列情形之一的，出租人或者承租人可以解除融资租赁合同：\n（一）出租人与出卖人订立的买卖合同解除、被确认无效或者被撤销，且未能重新订立买卖合同；\n（二）租赁物因不可归责于当事人的原因毁损、灭失，且不能修复或者确定替代物；\n（三）因出卖人的原因致使融资租赁合同的目的不能实现。\n第七百五十五条　融资租赁合同因买卖合同解除、被确认无效或者被撤销而解除，出卖人、租赁物系由承租人选择的，出租人有权请求承租人赔偿相应损失；但是，因出租人原因致使买卖合同解除、被确认无效或者被撤销的除外。\n出租人的损失已经在买卖合同解除、被确认无效或者被撤销时获得赔偿的，承租人不再承担相应的赔偿责任。\n第七百五十六条　融资租赁合同因租赁物交付承租人后意外毁损、灭失等不可归责于当事人的原因解除的，出租人可以请求承租人按照租赁物折旧情况给予补偿。\n第七百五十七条　出租人和承租人可以约定租赁期限届满租赁物的归属；对租赁物的归属没有约定或者约定不明确，依据本法第五百一十条的规定仍不能确定的，租赁物的所有权归出租人。\n第七百五十八条　当事人约定租赁期限届满租赁物归承租人所有，承租人已经支付大部分租金，但是无力支付剩余租金，出租人因此解除合同收回租赁物，收回的租赁物的价值超过承租人欠付的租金以及其他费用的，承租人可以请求相应返还。\n当事人约定租赁期限届满租赁物归出租人所有，因租赁物毁损、灭失或者附合、混合于他物致使承租人不能返还的，出租人有权请求承租人给予合理补偿。\n第七百五十九条　当事人约定租赁期限届满，承租人仅需向出租人支付象征性价款的，视为约定的租金义务履行完毕后租赁物的所有权归承租人', 755, '{\"level\": null, \"title\": null, \"chunk_index\": 85}', 'bge-large-zh-v1.5', '2026-09-25 17:05:01');
INSERT INTO `chunk` VALUES ('613593c4-f7fd-487d-8c3b-5f6ba9b11f45', '821ce1fd-178d-4a7e-ab92-3deff1488ce2', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 46, '第二百零七条　非法出售增值税专用发票的，处三年以下有期徒刑、拘役或者管制，并处二万元以上二十万元以下罚金；数量较大的，处三年以上十年以下有期徒刑，并处五万元以上五十万元以下罚金；数量巨大的，处十年以上有期徒刑或者无期徒刑，并处五万元以上五十万元以下罚金或者没收财产。\n第二百零八条　非法购买增值税专用发票或者购买伪造的增值税专用发票的，处五年以下有期徒刑或者拘役，并处或者单处二万元以上二十万元以下罚金。\n非法购买增值税专用发票或者购买伪造的增值税专用发票又虚开或者出售的，分别依照本法第二百零五条、第二百零六条、第二百零七条的规定定罪处罚。\n第二百零九条　伪造、擅自制造或者出售伪造、擅自制造的可以用于骗取出口退税、抵扣税款的其他发票的，处三年以下有期徒刑、拘役或者管制，并处二万元以上二十万元以下罚金；数量巨大的，处三年以上七年以下有期徒刑，并处五万元以上五十万元以下罚金；数量特别巨大的，处七年以上有期徒刑，并处五万元以上五十万元以下罚金或者没收财产。\n伪造、擅自制造或者出售伪造、擅自制造的前款规定以外的其他发票的，处二年以下有期徒刑、拘役或者管制，并处或者单处一万元以上五万元以下罚金；情节严重的，处二年以上七年以下有期徒刑，并处五万元以上五十万元以下罚金。\n非法出售可以用于骗取出口退税、抵扣税款的其他发票的，依照第一款的规定处罚。\n非法出售第三款规定以外的其他发票的，依照第二款的规定处罚。\n第二百一十条　盗窃增值税专用发票或者可以用于骗取出口退税、抵扣税款的其他发票的，依照本法第二百六十四条的规定定罪处罚。\n使用欺骗手段骗取增值税专用发票或者可以用于骗取出口退税、抵扣税款的其他发票的，依照本法第二百六十六条的规定定罪处罚。\n第二百一十条之一　明知是伪造的发票而持有，数量较大的，处二年以下有期徒刑、拘役或者管制，并处罚金；数量巨大的，处二年以上七年以下有期徒刑，并处罚金', 795, '{\"level\": null, \"title\": null, \"chunk_index\": 46}', 'bge-large-zh-v1.5', '2026-09-25 17:04:56');
INSERT INTO `chunk` VALUES ('61be1642-678b-4972-a49b-96ba4eb43e29', '16cbea7e-7e36-4f31-afb5-63892345d29c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 65, '国家监察委员会收到外国提出的刑事司法协助请求书及所附材料，经审查认为符合有关规定的，作出决定并交由省级监察机关执行，或者转交其他有关主管机关。省级监察机关应当立即执行，或者交由下级监察机关执行，并将执行结果或者妨碍执行的情形及时报送国家监察委员会。在执行过程中，需要依法采取查询、调取、查封、扣押、冻结等措施或者需要返还涉案财物的，根据我国法律规定和国家监察委员会的执行决定办理有关法律手续。\n第二百七十九条　地方各级监察机关通过执法合作方式办理相关涉外案件的，应当将合作事项及相关材料逐级报送国家监察委员会审核。由国家监察委员会依法直接或者协调有关单位，向有关国家（地区）相关机构提交并开展合作。\n第二百八十条　地方各级监察机关通过境外追诉方式办理相关涉外案件的，应当提供外逃人员相关违法线索和证据，逐级报送国家监察委员会审核。由国家监察委员会按照国际刑事司法协助法等规定直接或者协调有关单位向有关国家（地区）相关机构提交，请其依法对外逃人员调查、起诉、审判，移管被判刑人或者遣返外逃人员。\n第二百八十一条　监察机关对依法应当追缴的境外违法所得及其他涉案财产，应当责令涉案人员以合法方式退赔。涉案人员拒不退赔的，可以依法通过下列方式追缴：\n（一）在开展引渡等追逃合作时，随附请求有关国家（地区）移交相关违法所得及其他涉案财产；\n（二）依法启动违法所得没收程序，申请由人民法院对相关违法所得及其他涉案财产作出没收裁定，请有关国家（地区）承认和执行，并予以返还；\n（三）请有关国家（地区）依法追缴相关违法所得及其他涉案财产，并予以返还；\n（四）通过其他合法方式追缴', 681, '{\"level\": null, \"title\": null, \"chunk_index\": 65}', 'bge-large-zh-v1.5', '2026-09-25 17:04:49');
INSERT INTO `chunk` VALUES ('62570969-27a7-4020-b694-01b7a1a3b92d', 'b25ce095-dfba-4403-acf8-c58eb456ca4c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 6, '第三十四条　监护人的职责是代理被监护人实施民事法律行为，保护被监护人的人身权利、财产权利以及其他合法权益等。\n监护人依法履行监护职责产生的权利，受法律保护。\n监护人不履行监护职责或者侵害被监护人合法权益的，应当承担法律责任。\n因发生突发事件等紧急情况，监护人暂时无法履行监护职责，被监护人的生活处于无人照料状态的，被监护人住所地的居民委员会、村民委员会或者民政部门应当为被监护人安排必要的临时生活照料措施。\n第三十五条　监护人应当按照最有利于被监护人的原则履行监护职责。监护人除为维护被监护人利益外，不得处分被监护人的财产。\n未成年人的监护人履行监护职责，在作出与被监护人利益有关的决定时，应当根据被监护人的年龄和智力状况，尊重被监护人的真实意愿。\n成年人的监护人履行监护职责，应当最大程度地尊重被监护人的真实意愿，保障并协助被监护人实施与其智力、精神健康状况相适应的民事法律行为。对被监护人有能力独立处理的事务，监护人不得干涉。\n第三十六条　监护人有下列情形之一的，人民法院根据有关个人或者组织的申请，撤销其监护人资格，安排必要的临时监护措施，并按照最有利于被监护人的原则依法指定监护人：\n（一）实施严重损害被监护人身心健康的行为；\n（二）怠于履行监护职责，或者无法履行监护职责且拒绝将监护职责部分或者全部委托给他人，导致被监护人处于危困状态；\n（三）实施严重侵害被监护人合法权益的其他行为。\n本条规定的有关个人、组织包括：其他依法具有监护资格的人，居民委员会、村民委员会、学校、医疗机构、妇女联合会、残疾人联合会、未成年人保护组织、依法设立的老年人组织、民政部门等。\n前款规定的个人和民政部门以外的组织未及时向人民法院申请撤销监护人资格的，民政部门应当向人民法院申请。\n第三十七条　依法负担被监护人抚养费、赡养费、扶养费的父母、子女、配偶等，被人民法院撤销监护人资格后，应当继续履行负担的义务', 798, '{\"level\": null, \"title\": null, \"chunk_index\": 6}', 'bge-large-zh-v1.5', '2026-09-25 17:05:01');
INSERT INTO `chunk` VALUES ('62939301-583c-4133-bce4-7b72683f2add', 'b25ce095-dfba-4403-acf8-c58eb456ca4c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 126, '第一千零九十八条　收养人应当同时具备下列条件：\n（一）无子女或者只有一名子女；\n（二）有抚养、教育和保护被收养人的能力；\n（三）未患有在医学上认为不应当收养子女的疾病；\n（四）无不利于被收养人健康成长的违法犯罪记录；\n（五）年满三十周岁。\n第一千零九十九条　收养三代以内旁系同辈血亲的子女，可以不受本法第一千零九十三条第三项、第一千零九十四条第三项和第一千一百零二条规定的限制。\n华侨收养三代以内旁系同辈血亲的子女，还可以不受本法第一千零九十八条第一项规定的限制。\n第一千一百条　无子女的收养人可以收养两名子女；有子女的收养人只能收养一名子女。\n收养孤儿、残疾未成年人或者儿童福利机构抚养的查找不到生父母的未成年人，可以不受前款和本法第一千零九十八条第一项规定的限制。\n第一千一百零一条　有配偶者收养子女，应当夫妻共同收养。\n第一千一百零二条　无配偶者收养异性子女的，收养人与被收养人的年龄应当相差四十周岁以上。\n第一千一百零三条　继父或者继母经继子女的生父母同意，可以收养继子女，并可以不受本法第一千零九十三条第三项、第一千零九十四条第三项、第一千零九十八条和第一千一百条第一款规定的限制。\n第一千一百零四条　收养人收养与送养人送养，应当双方自愿。收养八周岁以上未成年人的，应当征得被收养人的同意。\n第一千一百零五条　收养应当向县级以上人民政府民政部门登记。收养关系自登记之日起成立。\n收养查找不到生父母的未成年人的，办理登记的民政部门应当在登记前予以公告。\n收养关系当事人愿意签订收养协议的，可以签订收养协议。\n收养关系当事人各方或者一方要求办理收养公证的，应当办理收养公证。\n县级以上人民政府民政部门应当依法进行收养评估。\n第一千一百零六条　收养关系成立后，公安机关应当按照国家有关规定为被收养人办理户口登记', 757, '{\"level\": null, \"title\": null, \"chunk_index\": 126}', 'bge-large-zh-v1.5', '2026-09-25 17:05:01');
INSERT INTO `chunk` VALUES ('639a3c78-9943-4273-b5d3-832bf26fd8c5', '16cbea7e-7e36-4f31-afb5-63892345d29c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 8, '第四十三条　监察法第十五条第三项所称国有企业管理人员，是指国家出资企业中的下列人员：\n（一）在国有独资、全资公司、企业中履行组织、领导、管理、监督等职责的人员；\n（二）经党组织或者国家机关，国有独资、全资公司、企业，事业单位提名、推荐、任命、批准等，在国有控股、参股公司及其分支机构中履行组织、领导、管理、监督等职责的人员；\n（三）经国家出资企业中负有管理、监督国有资产职责的组织批准或者研究决定，代表其在国有控股、参股公司及其分支机构中从事组织、领导、管理、监督等工作的人员。\n第四十四条　监察法第十五条第四项所称公办的教育、科研、文化、医疗卫生、体育等单位中从事管理的人员，是指国家为了社会公益目的，由国家机关举办或者其他组织利用国有资产举办的教育、科研、文化、医疗卫生、体育等事业单位中，从事组织、领导、管理、监督等工作的人员。\n第四十五条　监察法第十五条第五项所称基层群众性自治组织中从事管理的人员，是指该组织中的下列人员：\n（一）从事集体事务和公益事业管理的人员；\n（二）从事集体资金、资产、资源管理的人员；\n（三）协助人民政府从事行政管理工作的人员，包括从事救灾、防疫、抢险、防汛、优抚、帮扶、移民、救济款物的管理，社会捐助公益事业款物的管理，国有土地的经营和管理，土地征收、征用补偿费用的管理，代征、代缴税款，有关计划生育、户籍、征兵工作，协助人民政府等国家机关在基层群众性自治组织中从事的其他管理工作', 608, '{\"level\": null, \"title\": null, \"chunk_index\": 8}', 'bge-large-zh-v1.5', '2026-09-25 17:04:49');
INSERT INTO `chunk` VALUES ('644b4b18-02b2-483b-a4a5-55f08f9c66ad', 'b25ce095-dfba-4403-acf8-c58eb456ca4c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 57, '第五百一十条　合同生效后，当事人就质量、价款或者报酬、履行地点等内容没有约定或者约定不明确的，可以协议补充；不能达成补充协议的，按照合同相关条款或者交易习惯确定。\n第五百一十一条　当事人就有关合同内容约定不明确，依据前条规定仍不能确定的，适用下列规定：\n（一）质量要求不明确的，按照强制性国家标准履行；没有强制性国家标准的，按照推荐性国家标准履行；没有推荐性国家标准的，按照行业标准履行；没有国家标准、行业标准的，按照通常标准或者符合合同目的的特定标准履行。\n（二）价款或者报酬不明确的，按照订立合同时履行地的市场价格履行；依法应当执行政府定价或者政府指导价的，依照规定履行。\n（三）履行地点不明确，给付货币的，在接受货币一方所在地履行；交付不动产的，在不动产所在地履行；其他标的，在履行义务一方所在地履行。\n（四）履行期限不明确的，债务人可以随时履行，债权人也可以随时请求履行，但是应当给对方必要的准备时间。\n（五）履行方式不明确的，按照有利于实现合同目的的方式履行。\n（六）履行费用的负担不明确的，由履行义务一方负担；因债权人原因增加的履行费用，由债权人负担。\n第五百一十二条　通过互联网等信息网络订立的电子合同的标的为交付商品并采用快递物流方式交付的，收货人的签收时间为交付时间。电子合同的标的为提供服务的，生成的电子凭证或者实物凭证中载明的时间为提供服务时间；前述凭证没有载明时间或者载明时间与实际提供服务时间不一致的，以实际提供服务的时间为准。\n电子合同的标的物为采用在线传输方式交付的，合同标的物进入对方当事人指定的特定系统且能够检索识别的时间为交付时间。\n电子合同当事人对交付商品或者提供服务的方式、时间另有约定的，按照其约定。\n第五百一十三条　执行政府定价或者政府指导价的，在合同约定的交付期限内政府价格调整时，按照交付时的价格计价', 774, '{\"level\": null, \"title\": null, \"chunk_index\": 57}', 'bge-large-zh-v1.5', '2026-09-25 17:05:01');
INSERT INTO `chunk` VALUES ('65af1c6a-e610-4e8e-8b67-d50b5d8260b5', 'b25ce095-dfba-4403-acf8-c58eb456ca4c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 29, '第二百五十九条　履行国有财产管理、监督职责的机构及其工作人员，应当依法加强对国有财产的管理、监督，促进国有财产保值增值，防止国有财产损失；滥用职权，玩忽职守，造成国有财产损失的，应当依法承担法律责任。\n违反国有财产管理规定，在企业改制、合并分立、关联交易等过程中，低价转让、合谋私分、擅自担保或者以其他方式造成国有财产损失的，应当依法承担法律责任。\n第二百六十条　集体所有的不动产和动产包括：\n（一）法律规定属于集体所有的土地和森林、山岭、草原、荒地、滩涂；\n（二）集体所有的建筑物、生产设施、农田水利设施；\n（三）集体所有的教育、科学、文化、卫生、体育等设施；\n（四）集体所有的其他不动产和动产。\n第二百六十一条　农民集体所有的不动产和动产，属于本集体成员集体所有。\n下列事项应当依照法定程序经本集体成员决定：\n（一）土地承包方案以及将土地发包给本集体以外的组织或者个人承包；\n（二）个别土地承包经营权人之间承包地的调整；\n（三）土地补偿费等费用的使用、分配办法；\n（四）集体出资的企业的所有权变动等事项；\n（五）法律规定的其他事项。\n第二百六十二条　对于集体所有的土地和森林、山岭、草原、荒地、滩涂等，依照下列规定行使所有权：\n（一）属于村农民集体所有的，由村集体经济组织或者村民委员会依法代表集体行使所有权；\n（二）分别属于村内两个以上农民集体所有的，由村内各该集体经济组织或者村民小组依法代表集体行使所有权；\n（三）属于乡镇农民集体所有的，由乡镇集体经济组织代表集体行使所有权。\n第二百六十三条　城镇集体所有的不动产和动产，依照法律、行政法规的规定由本集体享有占有、使用、收益和处分的权利。\n第二百六十四条　农村集体经济组织或者村民委员会、村民小组应当依照法律、行政法规以及章程、村规民约向本集体成员公布集体财产的状况。集体成员有权查阅、复制相关资料', 779, '{\"level\": null, \"title\": null, \"chunk_index\": 29}', 'bge-large-zh-v1.5', '2026-09-25 17:05:01');
INSERT INTO `chunk` VALUES ('66089fcf-0441-4e3d-96c3-18962c01b66d', '821ce1fd-178d-4a7e-ab92-3deff1488ce2', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 8, '对被判处死刑缓期执行的累犯以及因故意杀人、强奸、抢劫、绑架、放火、爆炸、投放危险物质或者有组织的暴力性犯罪被判处死刑缓期执行的犯罪分子，人民法院根据犯罪情节等情况可以同时决定对其限制减刑。\n第五十一条　死刑缓期执行的期间，从判决确定之日起计算。死刑缓期执行减为有期徒刑的刑期，从死刑缓期执行期满之日起计算。\n第六节　罚　　金\n第五十二条　判处罚金，应当根据犯罪情节决定罚金数额。\n第五十三条　罚金在判决指定的期限内一次或者分期缴纳。期满不缴纳的，强制缴纳。对于不能全部缴纳罚金的，人民法院在任何时候发现被执行人有可以执行的财产，应当随时追缴。\n由于遭遇不能抗拒的灾祸等原因缴纳确实有困难的，经人民法院裁定，可以延期缴纳、酌情减少或者免除。\n第七节　剥夺政治权利\n第五十四条　剥夺政治权利是剥夺下列权利：\n（一）选举权和被选举权；\n（二）言论、出版、集会、结社、游行、示威自由的权利；\n（三）担任国家机关职务的权利；\n（四）担任国有公司、企业、事业单位和人民团体领导职务的权利。\n第五十五条　剥夺政治权利的期限，除本法第五十七条规定外，为一年以上五年以下。\n判处管制附加剥夺政治权利的，剥夺政治权利的期限与管制的期限相等，同时执行。\n第五十六条　对于危害国家安全的犯罪分子应当附加剥夺政治权利；对于故意杀人、强奸、放火、爆炸、投毒、抢劫等严重破坏社会秩序的犯罪分子，可以附加剥夺政治权利。\n独立适用剥夺政治权利的，依照本法分则的规定。\n第五十七条　对于被判处死刑、无期徒刑的犯罪分子，应当剥夺政治权利终身。\n在死刑缓期执行减为有期徒刑或者无期徒刑减为有期徒刑的时候，应当把附加剥夺政治权利的期限改为三年以上十年以下。\n第五十八条　附加剥夺政治权利的刑期，从徒刑、拘役执行完毕之日或者从假释之日起计算；剥夺政治权利的效力当然施用于主刑执行期间', 769, '{\"level\": null, \"title\": null, \"chunk_index\": 8}', 'bge-large-zh-v1.5', '2026-09-25 17:04:56');
INSERT INTO `chunk` VALUES ('66df36e7-480e-4ae4-84eb-14bbe7f26c4c', 'b25ce095-dfba-4403-acf8-c58eb456ca4c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 47, '第四百二十二条　最高额抵押担保的债权确定前，抵押权人与抵押人可以通过协议变更债权确定的期间、债权范围以及最高债权额。但是，变更的内容不得对其他抵押权人产生不利影响。\n第四百二十三条　有下列情形之一的，抵押权人的债权确定：\n（一）约定的债权确定期间届满；\n（二）没有约定债权确定期间或者约定不明确，抵押权人或者抵押人自最高额抵押权设立之日起满二年后请求确定债权；\n（三）新的债权不可能发生；\n（四）抵押权人知道或者应当知道抵押财产被查封、扣押；\n（五）债务人、抵押人被宣告破产或者解散；\n（六）法律规定债权确定的其他情形。\n第四百二十四条　最高额抵押权除适用本节规定外，适用本章第一节的有关规定。\n第十八章　质　　权\n第一节　动产质权\n第四百二十五条　为担保债务的履行，债务人或者第三人将其动产出质给债权人占有的，债务人不履行到期债务或者发生当事人约定的实现质权的情形，债权人有权就该动产优先受偿。\n前款规定的债务人或者第三人为出质人，债权人为质权人，交付的动产为质押财产。\n第四百二十六条　法律、行政法规禁止转让的动产不得出质。\n第四百二十七条　设立质权，当事人应当采用书面形式订立质押合同。\n质押合同一般包括下列条款：\n（一）被担保债权的种类和数额；\n（二）债务人履行债务的期限；\n（三）质押财产的名称、数量等情况；\n（四）担保的范围；\n（五）质押财产交付的时间、方式。\n第四百二十八条　质权人在债务履行期限届满前，与出质人约定债务人不履行到期债务时质押财产归债权人所有的，只能依法就质押财产优先受偿。\n第四百二十九条　质权自出质人交付质押财产时设立。\n第四百三十条　质权人有权收取质押财产的孳息，但是合同另有约定的除外。\n前款规定的孳息应当先充抵收取孳息的费用。\n第四百三十一条　质权人在质权存续期间，未经出质人同意，擅自使用、处分质押财产，造成出质人损害的，应当承担赔偿责任', 790, '{\"level\": null, \"title\": null, \"chunk_index\": 47}', 'bge-large-zh-v1.5', '2026-09-25 17:05:01');
INSERT INTO `chunk` VALUES ('6707a0c4-089b-4baa-b2b5-918113c2a692', '821ce1fd-178d-4a7e-ab92-3deff1488ce2', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 17, '第一百一十三条　本章上述危害国家安全罪行中，除第一百零三条第二款、第一百零五条、第一百零七条、第一百零九条外，对国家和人民危害特别严重、情节特别恶劣的，可以判处死刑。\n犯本章之罪的，可以并处没收财产。\n第二章　危害公共安全罪\n第一百一十四条　放火、决水、爆炸以及投放毒害性、放射性、传染病病原体等物质或者以其他危险方法危害公共安全，尚未造成严重后果的，处三年以上十年以下有期徒刑。\n第一百一十五条　放火、决水、爆炸以及投放毒害性、放射性、传染病病原体等物质或者以其他危险方法致人重伤、死亡或者使公私财产遭受重大损失的，处十年以上有期徒刑、无期徒刑或者死刑。\n过失犯前款罪的，处三年以上七年以下有期徒刑；情节较轻的，处三年以下有期徒刑或者拘役。\n第一百一十六条　破坏火车、汽车、电车、船只、航空器，足以使火车、汽车、电车、船只、航空器发生倾覆、毁坏危险，尚未造成严重后果的，处三年以上十年以下有期徒刑。\n第一百一十七条　破坏轨道、桥梁、隧道、公路、机场、航道、灯塔、标志或者进行其他破坏活动，足以使火车、汽车、电车、船只、航空器发生倾覆、毁坏危险，尚未造成严重后果的，处三年以上十年以下有期徒刑。\n第一百一十八条　破坏电力、燃气或者其他易燃易爆设备，危害公共安全，尚未造成严重后果的，处三年以上十年以下有期徒刑。\n第一百一十九条　破坏交通工具、交通设施、电力设备、燃气设备、易燃易爆设备，造成严重后果的，处十年以上有期徒刑、无期徒刑或者死刑。\n过失犯前款罪的，处三年以上七年以下有期徒刑；情节较轻的，处三年以下有期徒刑或者拘役。\n第一百二十条　组织、领导恐怖活动组织的，处十年以上有期徒刑或者无期徒刑，并处没收财产；积极参加的，处三年以上十年以下有期徒刑，并处罚金；其他参加的，处三年以下有期徒刑、拘役、管制或者剥夺政治权利，可以并处罚金', 768, '{\"level\": null, \"title\": null, \"chunk_index\": 17}', 'bge-large-zh-v1.5', '2026-09-25 17:04:56');
INSERT INTO `chunk` VALUES ('67354df8-2b90-41eb-b6ba-d4e9f4a845e9', '16cbea7e-7e36-4f31-afb5-63892345d29c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 60, '第二百五十七条　监察机关对于人民检察院依法退回补充调查的案件，应当向主要负责人报告，并积极开展补充调查工作。\n第二百五十八条　对人民检察院退回补充调查的案件，经审批分别作出下列处理：\n（一）认定犯罪事实的证据不够充分的，应当在补充证据后，制作补充调查报告书，连同相关材料一并移送人民检察院审查，对无法补充完善的证据，应当作出书面情况说明并加盖监察机关或者承办部门公章；\n（二）在补充调查中发现新的同案犯或者增加、变更犯罪事实，需要追究刑事责任的，应当重新提出处理意见，移送人民检察院审查；\n（三）犯罪事实的认定出现重大变化，认为不应当追究被调查人刑事责任的，应当在补充调查期限内重新提出处理意见，将处理结果书面通知人民检察院并说明理由；\n（四）认为移送起诉的犯罪事实清楚，证据确实、充分的，应当说明理由，移送人民检察院依法审查。\n第二百五十九条　人民检察院在审查起诉过程中发现新的职务违法或者职务犯罪问题线索并移送监察机关的，监察机关应当依法处置。\n第二百六十条　在案件审判过程中，人民检察院书面要求监察机关补充提供证据，对证据进行补正、解释，或者协助人民检察院补充侦查的，监察机关应当予以配合。监察机关不能提供有关证据材料的，应当书面说明情况。\n人民法院在审判过程中就证据收集合法性问题要求有关调查人员出庭说明情况时，监察机关应当依法予以配合。\n第二百六十一条　监察机关认为人民检察院不起诉决定有错误的，应当在收到不起诉决定书后三十日以内，依法向其上一级人民检察院提请复议。监察机关应当将上述情况及时向上一级监察机关书面报告。\n第二百六十二条　对于监察机关移送起诉的案件，人民检察院作出不起诉决定，人民法院作出无罪判决，或者监察机关经人民检察院退回补充调查后不再移送起诉，涉及对被调查人已生效政务处分事实认定的，监察机关应当依法对政务处分决定进行审核', 776, '{\"level\": null, \"title\": null, \"chunk_index\": 60}', 'bge-large-zh-v1.5', '2026-09-25 17:04:49');
INSERT INTO `chunk` VALUES ('675dd345-e172-4c7d-b12e-2f497831f716', '16cbea7e-7e36-4f31-afb5-63892345d29c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 2, '第十二条　各级监察委员会依法向本级中国共产党机关、国家机关、中国人民政治协商会议委员会机关、法律法规授权或者受委托管理公共事务的组织和单位以及所管辖的国有企业、事业单位等派驻或者派出监察机构、监察专员。\n省级和设区的市级监察委员会依法向地区、盟、开发区等不设置人民代表大会的区域派出监察机构或者监察专员。县级监察委员会和直辖市所辖区（县）监察委员会可以向街道、乡镇等区域派出监察机构或者监察专员。\n监察机构、监察专员开展监察工作，受派出机关领导。\n第十三条　各级监察委员会派驻或者派出的监察机构、监察专员根据派出机关授权，按照管理权限依法对派驻或者派出监督单位、区域等的公职人员开展监督，对职务违法和职务犯罪进行调查、处置。监察机构、监察专员可以按规定与地方监察委员会联合调查严重职务违法、职务犯罪，或者移交地方监察委员会调查。\n前款规定的监察机构、监察专员未被授予职务犯罪调查权的，其发现监察对象涉嫌职务犯罪线索，应当及时向派出机关报告，由派出机关调查或者依法移交有关地方监察委员会调查。\n第十四条　经国家监察委员会批准，国家监察委员会有关派驻监察机构、监察专员可以按照监察法第十二条第二款、第三款规定再派出。\n再派出监察机构、监察专员开展监察工作，受派出它的监察机构、监察专员领导。\n再派出监察机构、监察专员根据授权，按照管理权限依法对再派出监督单位的公职人员开展监督，对职务违法进行调查、处置。职务犯罪的调查、处置，按照本条例第五十二条第二款规定办理。\n第二节　监察监督\n第十五条　监察机关依法履行监察监督职责，对公职人员政治品行、行使公权力和道德操守情况进行监督检查，督促有关机关、单位加强对所属公职人员的教育、管理、监督', 715, '{\"level\": null, \"title\": null, \"chunk_index\": 2}', 'bge-large-zh-v1.5', '2026-09-25 17:04:49');
INSERT INTO `chunk` VALUES ('68657cae-616c-4044-a1b4-df44fc47ffd6', 'b25ce095-dfba-4403-acf8-c58eb456ca4c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 10, '法人终止，法律、行政法规规定须经有关机关批准的，依照其规定。\n第六十九条　有下列情形之一的，法人解散：\n（一）法人章程规定的存续期间届满或者法人章程规定的其他解散事由出现；\n（二）法人的权力机构决议解散；\n（三）因法人合并或者分立需要解散；\n（四）法人依法被吊销营业执照、登记证书，被责令关闭或者被撤销；\n（五）法律规定的其他情形。\n第七十条　法人解散的，除合并或者分立的情形外，清算义务人应当及时组成清算组进行清算。\n法人的董事、理事等执行机构或者决策机构的成员为清算义务人。法律、行政法规另有规定的，依照其规定。\n清算义务人未及时履行清算义务，造成损害的，应当承担民事责任；主管机关或者利害关系人可以申请人民法院指定有关人员组成清算组进行清算。\n第七十一条　法人的清算程序和清算组职权，依照有关法律的规定；没有规定的，参照适用公司法律的有关规定。\n第七十二条　清算期间法人存续，但是不得从事与清算无关的活动。\n法人清算后的剩余财产，按照法人章程的规定或者法人权力机构的决议处理。法律另有规定的，依照其规定。\n清算结束并完成法人注销登记时，法人终止；依法不需要办理法人登记的，清算结束时，法人终止。\n第七十三条　法人被宣告破产的，依法进行破产清算并完成法人注销登记时，法人终止。\n第七十四条　法人可以依法设立分支机构。法律、行政法规规定分支机构应当登记的，依照其规定。\n分支机构以自己的名义从事民事活动，产生的民事责任由法人承担；也可以先以该分支机构管理的财产承担，不足以承担的，由法人承担。\n第七十五条　设立人为设立法人从事的民事活动，其法律后果由法人承受；法人未成立的，其法律后果由设立人承受，设立人为二人以上的，享有连带债权，承担连带债务。\n设立人为设立法人以自己的名义从事民事活动产生的民事责任，第三人有权选择请求法人或者设立人承担', 771, '{\"level\": null, \"title\": null, \"chunk_index\": 10}', 'bge-large-zh-v1.5', '2026-09-25 17:05:01');
INSERT INTO `chunk` VALUES ('68f02981-6507-4d5a-8b61-3be79c2ad941', '821ce1fd-178d-4a7e-ab92-3deff1488ce2', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 5, '对于未遂犯，可以比照既遂犯从轻或者减轻处罚。\n第二十四条　在犯罪过程中，自动放弃犯罪或者自动有效地防止犯罪结果发生的，是犯罪中止。\n对于中止犯，没有造成损害的，应当免除处罚；造成损害的，应当减轻处罚。\n第三节　共同犯罪\n第二十五条　共同犯罪是指二人以上共同故意犯罪。\n二人以上共同过失犯罪，不以共同犯罪论处；应当负刑事责任的，按照他们所犯的罪分别处罚。\n第二十六条　组织、领导犯罪集团进行犯罪活动的或者在共同犯罪中起主要作用的，是主犯。\n三人以上为共同实施犯罪而组成的较为固定的犯罪组织，是犯罪集团。\n对组织、领导犯罪集团的首要分子，按照集团所犯的全部罪行处罚。\n对于第三款规定以外的主犯，应当按照其所参与的或者组织、指挥的全部犯罪处罚。\n第二十七条　在共同犯罪中起次要或者辅助作用的，是从犯。\n对于从犯，应当从轻、减轻处罚或者免除处罚。\n第二十八条　对于被胁迫参加犯罪的，应当按照他的犯罪情节减轻处罚或者免除处罚。\n第二十九条　教唆他人犯罪的，应当按照他在共同犯罪中所起的作用处罚。教唆不满十八周岁的人犯罪的，应当从重处罚。\n如果被教唆的人没有犯被教唆的罪，对于教唆犯，可以从轻或者减轻处罚。\n第四节　单位犯罪\n第三十条　公司、企业、事业单位、机关、团体实施的危害社会的行为，法律规定为单位犯罪的，应当负刑事责任。\n第三十一条　单位犯罪的，对单位判处罚金，并对其直接负责的主管人员和其他直接责任人员判处刑罚。本法分则和其他法律另有规定的，依照规定。\n第三章　刑　　罚\n第一节　刑罚的种类\n第三十二条　刑罚分为主刑和附加刑。\n第三十三条　主刑的种类如下：\n（一）管制；\n（二）拘役；\n（三）有期徒刑；\n（四）无期徒刑；\n（五）死刑。\n第三十四条　附加刑的种类如下：\n（一）罚金；\n（二）剥夺政治权利；\n（三）没收财产。\n附加刑也可以独立适用', 770, '{\"level\": null, \"title\": null, \"chunk_index\": 5}', 'bge-large-zh-v1.5', '2026-09-25 17:04:56');
INSERT INTO `chunk` VALUES ('69952378-86c3-4013-bcaa-9a524c731789', 'b25ce095-dfba-4403-acf8-c58eb456ca4c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 2, '心价值观，根据宪法，制定本法', 14, '{\"level\": null, \"title\": null, \"chunk_index\": 2}', 'bge-large-zh-v1.5', '2026-09-25 17:05:01');
INSERT INTO `chunk` VALUES ('69a29901-6f08-4027-9516-3cd48cf62262', 'b25ce095-dfba-4403-acf8-c58eb456ca4c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 49, '第二节　权利质权\n第四百四十条　债务人或者第三人有权处分的下列权利可以出质：\n（一）汇票、本票、支票；\n（二）债券、存款单；\n（三）仓单、提单；\n（四）可以转让的基金份额、股权；\n（五）可以转让的注册商标专用权、专利权、著作权等知识产权中的财产权；\n（六）现有的以及将有的应收账款；\n（七）法律、行政法规规定可以出质的其他财产权利。\n第四百四十一条　以汇票、本票、支票、债券、存款单、仓单、提单出质的，质权自权利凭证交付质权人时设立；没有权利凭证的，质权自办理出质登记时设立。法律另有规定的，依照其规定。\n第四百四十二条　汇票、本票、支票、债券、存款单、仓单、提单的兑现日期或者提货日期先于主债权到期的，质权人可以兑现或者提货，并与出质人协议将兑现的价款或者提取的货物提前清偿债务或者提存。\n第四百四十三条　以基金份额、股权出质的，质权自办理出质登记时设立。\n基金份额、股权出质后，不得转让，但是出质人与质权人协商同意的除外。出质人转让基金份额、股权所得的价款，应当向质权人提前清偿债务或者提存。\n第四百四十四条　以注册商标专用权、专利权、著作权等知识产权中的财产权出质的，质权自办理出质登记时设立。\n知识产权中的财产权出质后，出质人不得转让或者许可他人使用，但是出质人与质权人协商同意的除外。出质人转让或者许可他人使用出质的知识产权中的财产权所得的价款，应当向质权人提前清偿债务或者提存。\n第四百四十五条　以应收账款出质的，质权自办理出质登记时设立。\n应收账款出质后，不得转让，但是出质人与质权人协商同意的除外。出质人转让应收账款所得的价款，应当向质权人提前清偿债务或者提存。\n第四百四十六条　权利质权除适用本节规定外，适用本章第一节的有关规定。\n第十九章　留置权\n第四百四十七条　债务人不履行到期债务，债权人可以留置已经合法占有的债务人的动产，并有权就该动产优先受偿', 785, '{\"level\": null, \"title\": null, \"chunk_index\": 49}', 'bge-large-zh-v1.5', '2026-09-25 17:05:01');
INSERT INTO `chunk` VALUES ('6a15a801-8c82-4810-801e-d861783636f8', '16cbea7e-7e36-4f31-afb5-63892345d29c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 13, '对谈话、讯问、询问进行同步录音录像的，谈话笔录、讯问笔录、询问笔录记载的起止时间应当与录音录像资料反映的起止时间一致。谈话笔录、讯问笔录、询问笔录内容应当与录音录像资料内容相符。\n同步录音录像资料应当妥善保管、及时归档，留存备查。监察机关案件监督管理部门应当开展常态化检查。人民检察院、人民法院需要调取同步录音录像的，监察机关应当依法予以提供。\n第六十一条　需要商请其他监察机关协助收集证据材料的，应当依法出具《委托调查函》；商请其他监察机关对采取措施提供一般性协助的，应当依法出具《商请协助采取措施函》。商请协助事项涉及协助地监察机关管辖的监察对象的，应当由协助地监察机关按照所涉人员的管理权限报批。协助地监察机关对于协助请求，应当依法予以协助配合。\n第六十二条　采取、解除或者变更监察措施需要告知、通知相关人员的，应当依法办理。告知包括口头、书面两种方式，除本条例另有规定外，通知应当采取书面方式。采取口头方式告知、通知的，应当将相关情况制作工作记录；采取书面方式告知、通知的，可以通过直接送交、邮寄、转交等途径送达，将有关回执或者凭证附卷。\n无法告知、通知，或者相关人员拒绝接收的，调查人员应当在工作记录或者有关文书上记明。\n第六十三条　监察机关采取监察措施，依法需要见证人在场的，应当邀请合适的见证人在场。下列人员不得担任见证人：\n（一）生理上、精神上有缺陷或者未成年，不具有相应辨别能力或者不能正确表达的人；\n（二）与案件有利害关系，可能影响案件公正处理的人；\n（三）监察机关的工作人员或者其聘用的人员；\n（四）依法协助监察机关采取监察措施的工作人员。\n第六十四条　监察机关依法变更强制到案、责令候查、管护、留置以及禁闭等监察强制措施的，原监察强制措施自监察机关采取新的监察强制措施之时自动解除', 752, '{\"level\": null, \"title\": null, \"chunk_index\": 13}', 'bge-large-zh-v1.5', '2026-09-25 17:04:49');
INSERT INTO `chunk` VALUES ('6ac870a5-f087-429b-908f-c02e7cda0505', 'b25ce095-dfba-4403-acf8-c58eb456ca4c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 141, '第一千二百二十五条　医疗机构及其医务人员应当按照规定填写并妥善保管住院志、医嘱单、检验报告、手术及麻醉记录、病理资料、护理记录等病历资料。\n患者要求查阅、复制前款规定的病历资料的，医疗机构应当及时提供。\n第一千二百二十六条　医疗机构及其医务人员应当对患者的隐私和个人信息保密。泄露患者的隐私和个人信息，或者未经患者同意公开其病历资料的，应当承担侵权责任。\n第一千二百二十七条　医疗机构及其医务人员不得违反诊疗规范实施不必要的检查。\n第一千二百二十八条　医疗机构及其医务人员的合法权益受法律保护。\n干扰医疗秩序，妨碍医务人员工作、生活，侵害医务人员合法权益的，应当依法承担法律责任。\n第七章　环境污染和生态破坏责任\n第一千二百二十九条　因污染环境、破坏生态造成他人损害的，侵权人应当承担侵权责任。\n第一千二百三十条　因污染环境、破坏生态发生纠纷，行为人应当就法律规定的不承担责任或者减轻责任的情形及其行为与损害之间不存在因果关系承担举证责任。\n第一千二百三十一条　两个以上侵权人污染环境、破坏生态的，承担责任的大小，根据污染物的种类、浓度、排放量，破坏生态的方式、范围、程度，以及行为对损害后果所起的作用等因素确定。\n第一千二百三十二条　侵权人违反法律规定故意污染环境、破坏生态造成严重后果的，被侵权人有权请求相应的惩罚性赔偿。\n第一千二百三十三条　因第三人的过错污染环境、破坏生态的，被侵权人可以向侵权人请求赔偿，也可以向第三人请求赔偿。侵权人赔偿后，有权向第三人追偿。\n第一千二百三十四条　违反国家规定造成生态环境损害，生态环境能够修复的，国家规定的机关或者法律规定的组织有权请求侵权人在合理期限内承担修复责任。侵权人在期限内未修复的，国家规定的机关或者法律规定的组织可以自行或者委托他人进行修复，所需费用由侵权人负担', 760, '{\"level\": null, \"title\": null, \"chunk_index\": 141}', 'bge-large-zh-v1.5', '2026-09-25 17:05:01');
INSERT INTO `chunk` VALUES ('6b08f126-34ea-406e-9c4e-68839d65dc88', '821ce1fd-178d-4a7e-ab92-3deff1488ce2', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 65, '有前两款行为，同时构成其他犯罪的，依照处罚较重的规定定罪处罚。\n第二百八十七条之二　明知他人利用信息网络实施犯罪，为其犯罪提供互联网接入、服务器托管、网络存储、通讯传输等技术支持，或者提供广告推广、支付结算等帮助，情节严重的，处三年以下有期徒刑或者拘役，并处或者单处罚金。\n单位犯前款罪的，对单位判处罚金，并对其直接负责的主管人员和其他直接责任人员，依照第一款的规定处罚。\n有前两款行为，同时构成其他犯罪的，依照处罚较重的规定定罪处罚。\n第二百八十八条　违反国家规定，擅自设置、使用无线电台（站），或者擅自使用无线电频率，干扰无线电通讯秩序，情节严重的，处三年以下有期徒刑、拘役或者管制，并处或者单处罚金；情节特别严重的，处三年以上七年以下有期徒刑，并处罚金。\n单位犯前款罪的，对单位判处罚金，并对其直接负责的主管人员和其他直接责任人员，依照前款的规定处罚。\n第二百八十九条　聚众“打砸抢”，致人伤残、死亡的，依照本法第二百三十四条、第二百三十二条的规定定罪处罚。毁坏或者抢走公私财物的，除判令退赔外，对首要分子，依照本法第二百六十三条的规定定罪处罚。\n第二百九十条　聚众扰乱社会秩序，情节严重，致使工作、生产、营业和教学、科研、医疗无法进行，造成严重损失的，对首要分子，处三年以上七年以下有期徒刑；对其他积极参加的，处三年以下有期徒刑、拘役、管制或者剥夺政治权利。\n聚众冲击国家机关，致使国家机关工作无法进行，造成严重损失的，对首要分子，处五年以上十年以下有期徒刑；对其他积极参加的，处五年以下有期徒刑、拘役、管制或者剥夺政治权利。\n多次扰乱国家机关工作秩序，经行政处罚后仍不改正，造成严重后果的，处三年以下有期徒刑、拘役或者管制。\n多次组织、资助他人非法聚集，扰乱社会秩序，情节严重的，依照前款的规定处罚', 754, '{\"level\": null, \"title\": null, \"chunk_index\": 65}', 'bge-large-zh-v1.5', '2026-09-25 17:04:56');
INSERT INTO `chunk` VALUES ('6bc7a559-e2e6-4214-913d-a47dde93b87d', '821ce1fd-178d-4a7e-ab92-3deff1488ce2', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 77, '第六节　破坏环境资源保护罪\n第三百三十八条　违反国家规定，排放、倾倒或者处置有放射性的废物、含传染病病原体的废物、有毒物质或者其他有害物质，严重污染环境的，处三年以下有期徒刑或者拘役，并处或者单处罚金；情节严重的，处三年以上七年以下有期徒刑，并处罚金；有下列情形之一的，处七年以上有期徒刑，并处罚金：\n（一）在饮用水水源保护区、自然保护地核心保护区等依法确定的重点保护区域排放、倾倒、处置有放射性的废物、含传染病病原体的废物、有毒物质，情节特别严重的；\n（二）向国家确定的重要江河、湖泊水域排放、倾倒、处置有放射性的废物、含传染病病原体的废物、有毒物质，情节特别严重的；\n（三）致使大量永久基本农田基本功能丧失或者遭受永久性破坏的；\n（四）致使多人重伤、严重疾病，或者致人严重残疾、死亡的。\n有前款行为，同时构成其他犯罪的，依照处罚较重的规定定罪处罚。\n第三百三十九条　违反国家规定，将境外的固体废物进境倾倒、堆放、处置的，处五年以下有期徒刑或者拘役，并处罚金；造成重大环境污染事故，致使公私财产遭受重大损失或者严重危害人体健康的，处五年以上十年以下有期徒刑，并处罚金；后果特别严重的，处十年以上有期徒刑，并处罚金。\n未经国务院有关主管部门许可，擅自进口固体废物用作原料，造成重大环境污染事故，致使公私财产遭受重大损失或者严重危害人体健康的，处五年以下有期徒刑或者拘役，并处罚金；后果特别严重的，处五年以上十年以下有期徒刑，并处罚金。\n以原料利用为名，进口不能用作原料的固体废物、液态废物和气态废物的，依照本法第一百五十二条第二款、第三款的规定定罪处罚。\n第三百四十条　违反保护水产资源法规，在禁渔区、禁渔期或者使用禁用的工具、方法捕捞水产品，情节严重的，处三年以下有期徒刑、拘役、管制或者罚金', 747, '{\"level\": null, \"title\": null, \"chunk_index\": 77}', 'bge-large-zh-v1.5', '2026-09-25 17:04:56');
INSERT INTO `chunk` VALUES ('6ccb375c-fb48-4794-9f8e-2bacca2dcc71', '16cbea7e-7e36-4f31-afb5-63892345d29c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 29, '第一百三十二条　省级以上监察机关在调查期间，发现涉嫌职务犯罪的被调查人另有与留置时的罪行不同种的重大职务犯罪或者同种的影响罪名认定、量刑档次的重大职务犯罪，经审批可以依照监察法第四十八条第三款的规定重新计算留置时间。留置时间重新计算以一次为限。\n依照前款规定重新计算留置时间的，国家监察委员会调查部门应当自发现之日起五日以内履行报批程序，省级监察机关应当自发现之日起五日以内报请国家监察委员会批准。\n重新计算留置时间的，应当自作出决定之日起五日以内向被留置人员宣布，要求其在《重新计算留置时间决定书》上签名、捺指印，并及时通知被留置人员所在单位和家属。被留置人员拒绝签名、捺指印的，调查人员应当在文书上记明。\n第一百三十三条　重新计算留置时间的，留置时间不得超过三个月。新发现的罪行具有本条例第一百二十九条、第一百三十条规定情形的，可以依法延长和再延长留置时间。但是，此前已经根据本条例第一百三十条规定再延长留置时间的，不得再次适用该规定再延长留置时间。\n第一百三十四条　对被留置人员不需要继续采取留置措施的，应当按规定报批后解除留置或者变更为责令候查措施。留置期满的，应当按规定报批后予以解除。\n解除留置措施的，调查人员应当向被留置人员宣布解除留置措施的决定，由其在《解除留置决定书》上签名、捺指印；变更为责令候查措施的，应当向被留置人员宣布变更为责令候查措施的决定，由其在《变更留置决定书》上签名、捺指印。被留置人员拒绝签名、捺指印的，调查人员应当在文书上记明。\n解除留置措施或者变更为责令候查措施的，应当及时通知被留置人员所在单位和家属、申请人。调查人员应当与交接人办理交接手续，并由其在《解除留置通知书》或者《变更留置通知书》上签名。无法通知或者有关人员拒绝签名的，调查人员应当在文书上记明。不得因办理交接手续延迟解除或者变更留置措施', 771, '{\"level\": null, \"title\": null, \"chunk_index\": 29}', 'bge-large-zh-v1.5', '2026-09-25 17:04:49');
INSERT INTO `chunk` VALUES ('6d0b7bf1-f2a0-48bb-90bf-323b591bd546', '22a2c356-7a68-4455-b657-333e3dba1e1a', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 25, '在少数民族聚居或者多民族共同居住的地区，应当用当地通用的语言进行审理；起诉书、判决书、布告和其他文书应当根据实际需要使用当地通用的一种或者几种文字。\n第一百四十条　人民法院、人民检察院和公安机关办理刑事案件，应当分工负责，互相配合，互相制约，以保证准确有效地执行法律。\n第四章　国旗、国歌、国徽、首都\n第一百四十一条　中华人民共和国国旗是五星红旗。\n中华人民共和国国歌是《义勇军进行曲》。\n第一百四十二条　中华人民共和国国徽，中间是五星照耀下的天安门，周围是谷穗和齿轮。\n第一百四十三条　中华人民共和国首都是北京。', 257, '{\"level\": null, \"title\": null, \"chunk_index\": 25}', 'bge-large-zh-v1.5', '2026-09-25 17:04:29');
INSERT INTO `chunk` VALUES ('6d68533a-536a-443d-9183-3a61405016f3', '821ce1fd-178d-4a7e-ab92-3deff1488ce2', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 1, '正）\n目　　录\n第一编　总　　则\n第一章　刑法的任务、基本原则和适用范围\n第二章　犯　　罪\n第一节　犯罪和刑事责任\n第二节　犯罪的预备、未遂和中止\n第三节　共同犯罪\n第四节　单位犯罪\n第三章　刑　　罚\n第一节　刑罚的种类\n第二节　管　　制\n第三节　拘　　役\n第四节　有期徒刑、无期徒刑\n第五节　死　　刑\n第六节　罚　　金\n第七节　剥夺政治权利\n第八节　没收财产\n第四章　刑罚的具体运用\n第一节　量　　刑\n第二节　累　　犯\n第三节　自首和立功\n第四节　数罪并罚\n第五节　缓　　刑\n第六节　减　　刑\n第七节　假　　释\n第八节　时　　效\n第五章　其他规定\n第二编　分　　则\n第一章　危害国家安全罪\n第二章　危害公共安全罪\n第三章　破坏社会主义市场经济秩序罪\n第一节　生产、销售伪劣商品罪\n第二节　走私罪\n第三节　妨害对公司、企业的管理秩序罪\n第四节　破坏金融管理秩序罪\n第五节　金融诈骗罪\n第六节　危害税收征管罪\n第七节　侵犯知识产权罪\n第八节　扰乱市场秩序罪\n第四章　侵犯公民人身权利、民主权利罪\n第五章　侵犯财产罪\n第六章　妨害社会管理秩序罪\n第一节　扰乱公共秩序罪\n第二节　妨害司法罪\n第三节　妨害国（边）境管理罪\n第四节　妨害文物管理罪\n第五节　危害公共卫生罪\n第六节　破坏环境资源保护罪\n第七节　走私、贩卖、运输、制造毒品罪\n第八节　组织、强迫、引诱、容留、介绍卖淫罪\n第九节　制作、贩卖、传播淫秽物品罪\n第七章　危害国防利益罪\n第八章　贪污贿赂罪\n第九章　渎职罪\n第十章　军人违反职责罪\n附　　则\n第一编　总　　则\n第一章　刑法的任务、基本原则和适用范围\n第一条　为了惩罚犯罪，保护人民，根据宪法，结合我国同犯罪作斗争的具体经验及实际情况，制定本法', 727, '{\"level\": null, \"title\": null, \"chunk_index\": 1}', 'bge-large-zh-v1.5', '2026-09-25 17:04:56');
INSERT INTO `chunk` VALUES ('6da258ab-3e88-4ed4-8f93-cf8fe86508e4', 'b25ce095-dfba-4403-acf8-c58eb456ca4c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 14, '第一百零三条　非法人组织应当依照法律的规定登记。\n设立非法人组织，法律、行政法规规定须经有关机关批准的，依照其规定。\n第一百零四条　非法人组织的财产不足以清偿债务的，其出资人或者设立人承担无限责任。法律另有规定的，依照其规定。\n第一百零五条　非法人组织可以确定一人或者数人代表该组织从事民事活动。\n第一百零六条　有下列情形之一的，非法人组织解散：\n（一）章程规定的存续期间届满或者章程规定的其他解散事由出现；\n（二）出资人或者设立人决定解散；\n（三）法律规定的其他情形。\n第一百零七条　非法人组织解散的，应当依法进行清算。\n第一百零八条　非法人组织除适用本章规定外，参照适用本编第三章第一节的有关规定。\n第五章　民事权利\n第一百零九条　自然人的人身自由、人格尊严受法律保护。\n第一百一十条　自然人享有生命权、身体权、健康权、姓名权、肖像权、名誉权、荣誉权、隐私权、婚姻自主权等权利。\n法人、非法人组织享有名称权、名誉权和荣誉权。\n第一百一十一条　自然人的个人信息受法律保护。任何组织或者个人需要获取他人个人信息的，应当依法取得并确保信息安全，不得非法收集、使用、加工、传输他人个人信息，不得非法买卖、提供或者公开他人个人信息。\n第一百一十二条　自然人因婚姻家庭关系等产生的人身权利受法律保护。\n第一百一十三条　民事主体的财产权利受法律平等保护。\n第一百一十四条　民事主体依法享有物权。\n物权是权利人依法对特定的物享有直接支配和排他的权利，包括所有权、用益物权和担保物权。\n第一百一十五条　物包括不动产和动产。法律规定权利作为物权客体的，依照其规定。\n第一百一十六条　物权的种类和内容，由法律规定。\n第一百一十七条　为了公共利益的需要，依照法律规定的权限和程序征收、征用不动产或者动产的，应当给予公平、合理的补偿。\n第一百一十八条　民事主体依法享有债权', 775, '{\"level\": null, \"title\": null, \"chunk_index\": 14}', 'bge-large-zh-v1.5', '2026-09-25 17:05:01');
INSERT INTO `chunk` VALUES ('6dd5044b-e626-4657-b26b-01abc4f5bd71', '16cbea7e-7e36-4f31-afb5-63892345d29c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 43, '第一百九十五条　监察机关接到口岸移民管理机构查获被决定采取留置措施的边控对象的通知后，应当于二十四小时以内到达口岸办理移交手续。无法及时到达的，应当委托当地监察机关及时前往口岸办理移交手续。当地监察机关应当予以协助。\n第一百九十六条　对于不需要继续采取限制出境措施的，应当按规定报批，及时予以解除。承办部门应当出具有关函件，与《解除限制出境措施决定书》一并送交移民管理机构执行。\n第一百九十七条　县级以上监察机关在重要紧急情况下，经审批可以依法直接向口岸所在地口岸移民管理机构提请办理临时限制出境措施，期限不超过七日，不能延期。\n第五章　监察程序\n第一节　线索处置\n第一百九十八条　监察机关应当对问题线索归口受理、集中管理、分类处置、定期清理。\n第一百九十九条　监察机关对于报案或者举报应当依法接受。属于本级监察机关管辖的，依法予以受理；属于其他监察机关管辖的，应当在五个工作日以内予以转送。\n监察机关可以向下级监察机关发函交办检举控告，并进行督办，下级监察机关应当按期回复办理结果。\n第二百条　对于涉嫌职务违法或者职务犯罪的公职人员自动投案的，应当依法接待和办理。\n第二百零一条　监察机关对于执法机关、司法机关等其他机关移送的问题线索，应当及时审核，并按照下列方式办理：\n（一）本单位有管辖权的，及时研究提出处置意见；\n（二）本单位没有管辖权但其他监察机关有管辖权的，在五个工作日以内转送有管辖权的监察机关；\n（三）本单位对部分问题线索有管辖权的，对有管辖权的部分提出处置意见，并及时将其他问题线索转送有管辖权的机关；\n（四）监察机关没有管辖权的，及时退回移送机关。\n第二百零二条　信访举报部门归口受理本机关管辖监察对象涉嫌职务违法和职务犯罪问题的检举控告，统一接收有关监察机关以及其他单位移送的相关检举控告，移交本机关监督检查部门或者相关部门，并将移交情况通报案件监督管理部门', 790, '{\"level\": null, \"title\": null, \"chunk_index\": 43}', 'bge-large-zh-v1.5', '2026-09-25 17:04:49');
INSERT INTO `chunk` VALUES ('6e1803bb-c00e-4888-8aa3-2c0759a4ef2f', 'b25ce095-dfba-4403-acf8-c58eb456ca4c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 48, '第四百三十二条　质权人负有妥善保管质押财产的义务；因保管不善致使质押财产毁损、灭失的，应当承担赔偿责任。\n质权人的行为可能使质押财产毁损、灭失的，出质人可以请求质权人将质押财产提存，或者请求提前清偿债务并返还质押财产。\n第四百三十三条　因不可归责于质权人的事由可能使质押财产毁损或者价值明显减少，足以危害质权人权利的，质权人有权请求出质人提供相应的担保；出质人不提供的，质权人可以拍卖、变卖质押财产，并与出质人协议将拍卖、变卖所得的价款提前清偿债务或者提存。\n第四百三十四条　质权人在质权存续期间，未经出质人同意转质，造成质押财产毁损、灭失的，应当承担赔偿责任。\n第四百三十五条　质权人可以放弃质权。债务人以自己的财产出质，质权人放弃该质权的，其他担保人在质权人丧失优先受偿权益的范围内免除担保责任，但是其他担保人承诺仍然提供担保的除外。\n第四百三十六条　债务人履行债务或者出质人提前清偿所担保的债权的，质权人应当返还质押财产。\n债务人不履行到期债务或者发生当事人约定的实现质权的情形，质权人可以与出质人协议以质押财产折价，也可以就拍卖、变卖质押财产所得的价款优先受偿。\n质押财产折价或者变卖的，应当参照市场价格。\n第四百三十七条　出质人可以请求质权人在债务履行期限届满后及时行使质权；质权人不行使的，出质人可以请求人民法院拍卖、变卖质押财产。\n出质人请求质权人及时行使质权，因质权人怠于行使权利造成出质人损害的，由质权人承担赔偿责任。\n第四百三十八条　质押财产折价或者拍卖、变卖后，其价款超过债权数额的部分归出质人所有，不足部分由债务人清偿。\n第四百三十九条　出质人与质权人可以协议设立最高额质权。\n最高额质权除适用本节有关规定外，参照适用本编第十七章第二节的有关规定', 735, '{\"level\": null, \"title\": null, \"chunk_index\": 48}', 'bge-large-zh-v1.5', '2026-09-25 17:05:01');
INSERT INTO `chunk` VALUES ('6eff8710-39dd-4ee0-966a-a0e9ab85ab9c', '22a2c356-7a68-4455-b657-333e3dba1e1a', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 23, '国家在民族自治地方开发资源、建设企业的时候，应当照顾民族自治地方的利益。\n第一百一十九条　民族自治地方的自治机关自主地管理本地方的教育、科学、文化、卫生、体育事业，保护和整理民族的文化遗产，发展和繁荣民族文化。\n第一百二十条　民族自治地方的自治机关依照国家的军事制度和当地的实际需要，经国务院批准，可以组织本地方维护社会治安的公安部队。\n第一百二十一条　民族自治地方的自治机关在执行职务的时候，依照本民族自治地方自治条例的规定，使用当地通用的一种或者几种语言文字。\n第一百二十二条　国家从财政、物资、技术等方面帮助各少数民族加速发展经济建设和文化建设事业。\n国家帮助民族自治地方从当地民族中大量培养各级干部、各种专业人才和技术工人。\n第七节　监察委员会\n第一百二十三条　中华人民共和国各级监察委员会是国家的监察机关。\n第一百二十四条　中华人民共和国设立国家监察委员会和地方各级监察委员会。\n监察委员会由下列人员组成：\n主任，\n副主任若干人，\n委员若干人。\n监察委员会主任每届任期同本级人民代表大会每届任期相同。国家监察委员会主任连续任职不得超过两届。\n监察委员会的组织和职权由法律规定。\n第一百二十五条　中华人民共和国国家监察委员会是最高监察机关。\n国家监察委员会领导地方各级监察委员会的工作，上级监察委员会领导下级监察委员会的工作。\n第一百二十六条　国家监察委员会对全国人民代表大会和全国人民代表大会常务委员会负责。地方各级监察委员会对产生它的国家权力机关和上一级监察委员会负责。\n第一百二十七条　监察委员会依照法律规定独立行使监察权，不受行政机关、社会团体和个人的干涉。\n监察机关办理职务违法和职务犯罪案件，应当与审判机关、检察机关、执法部门互相配合，互相制约。\n第八节　人民法院和人民检察院\n第一百二十八条　中华人民共和国人民法院是国家的审判机关', 776, '{\"level\": null, \"title\": null, \"chunk_index\": 23}', 'bge-large-zh-v1.5', '2026-09-25 17:04:29');
INSERT INTO `chunk` VALUES ('6fcf5a03-4e75-465e-bac1-58e96b3583df', '22a2c356-7a68-4455-b657-333e3dba1e1a', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 9, '第四十二条　中华人民共和国公民有劳动的权利和义务。\n国家通过各种途径，创造劳动就业条件，加强劳动保护，改善劳动条件，并在发展生产的基础上，提高劳动报酬和福利待遇。\n劳动是一切有劳动能力的公民的光荣职责。国有企业和城乡集体经济组织的劳动者都应当以国家主人翁的态度对待自己的劳动。国家提倡社会主义劳动竞赛，奖励劳动模范和先进工作者。国家提倡公民从事义务劳动。\n国家对就业前的公民进行必要的劳动就业训练。\n第四十三条　中华人民共和国劳动者有休息的权利。\n国家发展劳动者休息和休养的设施，规定职工的工作时间和休假制度。\n第四十四条　国家依照法律规定实行企业事业组织的职工和国家机关工作人员的退休制度。退休人员的生活受到国家和社会的保障。\n第四十五条　中华人民共和国公民在年老、疾病或者丧失劳动能力的情况下，有从国家和社会获得物质帮助的权利。国家发展为公民享受这些权利所需要的社会保险、社会救济和医疗卫生事业。\n国家和社会保障残废军人的生活，抚恤烈士家属，优待军人家属。\n国家和社会帮助安排盲、聋、哑和其他有残疾的公民的劳动、生活和教育。\n第四十六条　中华人民共和国公民有受教育的权利和义务。\n国家培养青年、少年、儿童在品德、智力、体质等方面全面发展。\n第四十七条　中华人民共和国公民有进行科学研究、文学艺术创作和其他文化活动的自由。国家对于从事教育、科学、技术、文学、艺术和其他文化事业的公民的有益于人民的创造性工作，给以鼓励和帮助。\n第四十八条　中华人民共和国妇女在政治的、经济的、文化的、社会的和家庭的生活等各方面享有同男子平等的权利。\n国家保护妇女的权利和利益，实行男女同工同酬，培养和选拔妇女干部。\n第四十九条　婚姻、家庭、母亲和儿童受国家的保护。\n夫妻双方有实行计划生育的义务。\n父母有抚养教育未成年子女的义务，成年子女有赡养扶助父母的义务。\n禁止破坏婚姻自由，禁止虐待老人、妇女和儿童', 794, '{\"level\": null, \"title\": null, \"chunk_index\": 9}', 'bge-large-zh-v1.5', '2026-09-25 17:04:28');
INSERT INTO `chunk` VALUES ('718750a8-419b-4044-8ca6-6bd3c47a25cf', '821ce1fd-178d-4a7e-ab92-3deff1488ce2', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 34, '第一百七十五条　以转贷牟利为目的，套取金融机构信贷资金高利转贷他人，违法所得数额较大的，处三年以下有期徒刑或者拘役，并处违法所得一倍以上五倍以下罚金；数额巨大的，处三年以上七年以下有期徒刑，并处违法所得一倍以上五倍以下罚金。\n单位犯前款罪的，对单位判处罚金，并对其直接负责的主管人员和其他直接责任人员，处三年以下有期徒刑或者拘役。\n第一百七十五条之一　以欺骗手段取得银行或者其他金融机构贷款、票据承兑、信用证、保函等，给银行或者其他金融机构造成重大损失的，处三年以下有期徒刑或者拘役，并处或者单处罚金；给银行或者其他金融机构造成特别重大损失或者有其他特别严重情节的，处三年以上七年以下有期徒刑，并处罚金。\n单位犯前款罪的，对单位判处罚金，并对其直接负责的主管人员和其他直接责任人员，依照前款的规定处罚。\n第一百七十六条　非法吸收公众存款或者变相吸收公众存款，扰乱金融秩序的，处三年以下有期徒刑或者拘役，并处或者单处罚金；数额巨大或者有其他严重情节的，处三年以上十年以下有期徒刑，并处罚金；数额特别巨大或者有其他特别严重情节的，处十年以上有期徒刑，并处罚金。\n单位犯前款罪的，对单位判处罚金，并对其直接负责的主管人员和其他直接责任人员，依照前款的规定处罚。\n有前两款行为，在提起公诉前积极退赃退赔，减少损害结果发生的，可以从轻或者减轻处罚', 568, '{\"level\": null, \"title\": null, \"chunk_index\": 34}', 'bge-large-zh-v1.5', '2026-09-25 17:04:56');
INSERT INTO `chunk` VALUES ('728ae016-f904-4696-acd4-f03f79495b9c', 'b25ce095-dfba-4403-acf8-c58eb456ca4c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 28, '第二百四十五条　因抢险救灾、疫情防控等紧急需要，依照法律规定的权限和程序可以征用组织、个人的不动产或者动产。被征用的不动产或者动产使用后，应当返还被征用人。组织、个人的不动产或者动产被征用或者征用后毁损、灭失的，应当给予补偿。\n第五章　国家所有权和集体所有权、私人所有权\n第二百四十六条　法律规定属于国家所有的财产，属于国家所有即全民所有。\n国有财产由国务院代表国家行使所有权。法律另有规定的，依照其规定。\n第二百四十七条　矿藏、水流、海域属于国家所有。\n第二百四十八条　无居民海岛属于国家所有，国务院代表国家行使无居民海岛所有权。\n第二百四十九条　城市的土地，属于国家所有。法律规定属于国家所有的农村和城市郊区的土地，属于国家所有。\n第二百五十条　森林、山岭、草原、荒地、滩涂等自然资源，属于国家所有，但是法律规定属于集体所有的除外。\n第二百五十一条　法律规定属于国家所有的野生动植物资源，属于国家所有。\n第二百五十二条　无线电频谱资源属于国家所有。\n第二百五十三条　法律规定属于国家所有的文物，属于国家所有。\n第二百五十四条　国防资产属于国家所有。\n铁路、公路、电力设施、电信设施和油气管道等基础设施，依照法律规定为国家所有的，属于国家所有。\n第二百五十五条　国家机关对其直接支配的不动产和动产，享有占有、使用以及依照法律和国务院的有关规定处分的权利。\n第二百五十六条　国家举办的事业单位对其直接支配的不动产和动产，享有占有、使用以及依照法律和国务院的有关规定收益、处分的权利。\n第二百五十七条　国家出资的企业，由国务院、地方人民政府依照法律、行政法规规定分别代表国家履行出资人职责，享有出资人权益。\n第二百五十八条　国家所有的财产受法律保护，禁止任何组织或者个人侵占、哄抢、私分、截留、破坏', 748, '{\"level\": null, \"title\": null, \"chunk_index\": 28}', 'bge-large-zh-v1.5', '2026-09-25 17:05:01');
INSERT INTO `chunk` VALUES ('733f1e3d-2079-4783-a961-3e0088c01ba4', 'd9d7dc15-8041-43b8-9f75-f112fe3ae003', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 16, '予以批准的，颁发剧毒化学品购买许可证；不予批准的，书面通知申请人并说明理由。\n剧毒化学品购买许可管理按照国务院公安部门的规定执行。\n第六十条　危险化学品生产企业、经营企业销售剧毒化学品、易制爆危险化学品，应当查验本法第五十八条第一款、第二款规定的相关许可证件或者证明文件，不得向不具有相关许可证件或者证明文件的单位销售剧毒化学品、易制爆危险化学品。对持剧毒化学品购买许可证购买剧毒化学品的，应当按照许可证载明的品种、数量销售。\n禁止向个人销售剧毒化学品（属于剧毒化学品的农药除外）和易制爆危险化学品（含有易制爆危险化学品的食品添加剂、药品、兽药、消毒剂等生活用品除外）。\n第六十一条　危险化学品生产企业、经营企业销售剧毒化学品、易制爆危险化学品，应当如实记录购买单位的名称、地址，经办人的姓名、身份证号码以及所购买的剧毒化学品、易制爆危险化学品的品种、数量、用途。销售记录以及经办人的身份证明复印件、相关许可证件复印件或者证明文件的保存期限不得少于三年。\n剧毒化学品、易制爆危险化学品的销售企业、购买单位应当在销售、购买后三日内，将所销售、购买的剧毒化学品、易制爆危险化学品的品种、数量以及流向信息报所在地县级人民政府公安机关备案，并录入计算机系统。\n第六十二条　使用剧毒化学品、易制爆危险化学品的单位不得出借、转让其购买的剧毒化学品、易制爆危险化学品；因转产、停产、搬迁、关闭等确需转让的，应当向具有本法第五十八条第一款、第二款规定的相关许可证件或者证明文件的单位转让，并在转让后三日内将所转让的剧毒化学品、易制爆危险化学品品种、数量以及流向信息报所在地县级人民政府公安机关备案。\n第六十三条　禁止在互联网上销售、购买剧毒化学品、易制爆危险化学品', 724, '{\"level\": null, \"title\": null, \"chunk_index\": 16}', 'bge-large-zh-v1.5', '2026-09-25 17:04:46');
INSERT INTO `chunk` VALUES ('7388d9fe-e087-4c34-8147-9531db1fe7d1', '821ce1fd-178d-4a7e-ab92-3deff1488ce2', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 67, '纠集他人多次实施前款行为，严重破坏社会秩序的，处五年以上十年以下有期徒刑，可以并处罚金。\n第二百九十三条之一　有下列情形之一，催收高利放贷等产生的非法债务，情节严重的，处三年以下有期徒刑、拘役或者管制，并处或者单处罚金：\n（一）使用暴力、胁迫方法的；\n（二）限制他人人身自由或者侵入他人住宅的；\n（三）恐吓、跟踪、骚扰他人的。\n第二百九十四条　组织、领导黑社会性质的组织的，处七年以上有期徒刑，并处没收财产；积极参加的，处三年以上七年以下有期徒刑，可以并处罚金或者没收财产；其他参加的，处三年以下有期徒刑、拘役、管制或者剥夺政治权利，可以并处罚金。\n境外的黑社会组织的人员到中华人民共和国境内发展组织成员的，处三年以上十年以下有期徒刑。\n国家机关工作人员包庇黑社会性质的组织，或者纵容黑社会性质的组织进行违法犯罪活动的，处五年以下有期徒刑；情节严重的，处五年以上有期徒刑。\n犯前三款罪又有其他犯罪行为的，依照数罪并罚的规定处罚。\n黑社会性质的组织应当同时具备以下特征：\n（一）形成较稳定的犯罪组织，人数较多，有明确的组织者、领导者，骨干成员基本固定；\n（二）有组织地通过违法犯罪活动或者其他手段获取经济利益，具有一定的经济实力，以支持该组织的活动；\n（三）以暴力、威胁或者其他手段，有组织地多次进行违法犯罪活动，为非作恶，欺压、残害群众；\n（四）通过实施违法犯罪活动，或者利用国家工作人员的包庇或者纵容，称霸一方，在一定区域或者行业内，形成非法控制或者重大影响，严重破坏经济、社会生活秩序。\n第二百九十五条　传授犯罪方法的，处五年以下有期徒刑、拘役或者管制；情节严重的，处五年以上十年以下有期徒刑；情节特别严重的，处十年以上有期徒刑或者无期徒刑', 722, '{\"level\": null, \"title\": null, \"chunk_index\": 67}', 'bge-large-zh-v1.5', '2026-09-25 17:04:56');
INSERT INTO `chunk` VALUES ('74e7272f-b301-4bf7-9a5c-b00769aad5a1', 'b25ce095-dfba-4403-acf8-c58eb456ca4c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 82, '第三人主张权利的，承租人应当及时通知出租人。\n第七百二十四条　有下列情形之一，非因承租人原因致使租赁物无法使用的，承租人可以解除合同：\n（一）租赁物被司法机关或者行政机关依法查封、扣押；\n（二）租赁物权属有争议；\n（三）租赁物具有违反法律、行政法规关于使用条件的强制性规定情形。\n第七百二十五条　租赁物在承租人按照租赁合同占有期限内发生所有权变动的，不影响租赁合同的效力。\n第七百二十六条　出租人出卖租赁房屋的，应当在出卖之前的合理期限内通知承租人，承租人享有以同等条件优先购买的权利；但是，房屋按份共有人行使优先购买权或者出租人将房屋出卖给近亲属的除外。\n出租人履行通知义务后，承租人在十五日内未明确表示购买的，视为承租人放弃优先购买权。\n第七百二十七条　出租人委托拍卖人拍卖租赁房屋的，应当在拍卖五日前通知承租人。承租人未参加拍卖的，视为放弃优先购买权。\n第七百二十八条　出租人未通知承租人或者有其他妨害承租人行使优先购买权情形的，承租人可以请求出租人承担赔偿责任。但是，出租人与第三人订立的房屋买卖合同的效力不受影响。\n第七百二十九条　因不可归责于承租人的事由，致使租赁物部分或者全部毁损、灭失的，承租人可以请求减少租金或者不支付租金；因租赁物部分或者全部毁损、灭失，致使不能实现合同目的的，承租人可以解除合同。\n第七百三十条　当事人对租赁期限没有约定或者约定不明确，依据本法第五百一十条的规定仍不能确定的，视为不定期租赁；当事人可以随时解除合同，但是应当在合理期限之前通知对方。\n第七百三十一条　租赁物危及承租人的安全或者健康的，即使承租人订立合同时明知该租赁物质量不合格，承租人仍然可以随时解除合同。\n第七百三十二条　承租人在房屋租赁期限内死亡的，与其生前共同居住的人或者共同经营人可以按照原租赁合同租赁该房屋。\n第七百三十三条　租赁期限届满，承租人应当返还租赁物', 787, '{\"level\": null, \"title\": null, \"chunk_index\": 82}', 'bge-large-zh-v1.5', '2026-09-25 17:05:01');
INSERT INTO `chunk` VALUES ('766b1bec-6927-4065-9696-4d2968fec057', '821ce1fd-178d-4a7e-ab92-3deff1488ce2', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 21, '第一百三十三条　违反交通运输管理法规，因而发生重大事故，致人重伤、死亡或者使公私财产遭受重大损失的，处三年以下有期徒刑或者拘役；交通运输肇事后逃逸或者有其他特别恶劣情节的，处三年以上七年以下有期徒刑；因逃逸致人死亡的，处七年以上有期徒刑。\n第一百三十三条之一　在道路上驾驶机动车，有下列情形之一的，处拘役，并处罚金：\n（一）追逐竞驶，情节恶劣的；\n（二）醉酒驾驶机动车的；\n（三）从事校车业务或者旅客运输，严重超过额定乘员载客，或者严重超过规定时速行驶的；\n（四）违反危险化学品安全管理规定运输危险化学品，危及公共安全的。\n机动车所有人、管理人对前款第三项、第四项行为负有直接责任的，依照前款的规定处罚。\n有前两款行为，同时构成其他犯罪的，依照处罚较重的规定定罪处罚。\n第一百三十三条之二　对行驶中的公共交通工具的驾驶人员使用暴力或者抢控驾驶操纵装置，干扰公共交通工具正常行驶，危及公共安全的，处一年以下有期徒刑、拘役或者管制，并处或者单处罚金。\n前款规定的驾驶人员在行驶的公共交通工具上擅离职守，与他人互殴或者殴打他人，危及公共安全的，依照前款的规定处罚。\n有前两款行为，同时构成其他犯罪的，依照处罚较重的规定定罪处罚。\n第一百三十四条　在生产、作业中违反有关安全管理的规定，因而发生重大伤亡事故或者造成其他严重后果的，处三年以下有期徒刑或者拘役；情节特别恶劣的，处三年以上七年以下有期徒刑。\n强令他人违章冒险作业，或者明知存在重大事故隐患而不排除，仍冒险组织作业，因而发生重大伤亡事故或者造成其他严重后果的，处五年以下有期徒刑或者拘役；情节特别恶劣的，处五年以上有期徒刑', 687, '{\"level\": null, \"title\": null, \"chunk_index\": 21}', 'bge-large-zh-v1.5', '2026-09-25 17:04:56');
INSERT INTO `chunk` VALUES ('775c7e39-eef7-480f-a964-9db462a867b5', '16cbea7e-7e36-4f31-afb5-63892345d29c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 56, '第二百四十五条　涉嫌职务犯罪的被调查人具有下列情形之一，如实交代自己主要犯罪事实的，可以认定为监察法第三十四条第一项规定的自动投案，真诚悔罪悔过：\n（一）职务犯罪问题未被监察机关掌握或者监察机关正在就有关问题线索进行适当了解时，向监察机关投案的；\n（二）在监察机关谈话、函询过程中，如实交代监察机关未掌握的涉嫌职务犯罪问题的；\n（三）在初步核实阶段，尚未受到监察机关谈话时投案的；\n（四）职务犯罪问题虽被监察机关立案，但尚未受到讯问或者采取监察强制措施，向监察机关投案的；\n（五）因伤病等客观原因无法前往投案，先委托他人代为表达投案意愿，或者以书信、网络、电话、传真等方式表达投案意愿，后到监察机关接受处理的；\n（六）涉嫌职务犯罪潜逃后又投案，包括在被通缉、抓捕过程中投案的；\n（七）经查实确已准备去投案，或者正在投案途中被有关机关抓获的；\n（八）经他人规劝或者在他人陪同下投案的；\n（九）虽未向监察机关投案，但向其所在党组织、单位或者有关负责人员投案，向有关巡视巡察机构投案，以及向公安机关、人民检察院、人民法院投案的；\n（十）具有其他应当视为自动投案的情形的。\n被调查人自动投案后不能如实交代自己的主要犯罪事实，或者自动投案并如实供述自己的罪行后又翻供的，不能适用前款规定。\n第二百四十六条　涉嫌职务犯罪的被调查人具有下列情形之一的，可以认定为监察法第三十四条第二项规定的积极配合调查工作，如实供述监察机关还未掌握的违法犯罪行为：\n（一）监察机关所掌握线索针对的犯罪事实不成立，在此范围外被调查人主动交代其他罪行的；\n（二）主动交代监察机关尚未掌握的犯罪事实，与监察机关已掌握的犯罪事实属不同种罪行的；\n（三）主动交代监察机关尚未掌握的犯罪事实，与监察机关已掌握的犯罪事实属同种罪行的；\n（四）监察机关掌握的证据不充分，被调查人如实交代有助于收集定案证据的', 780, '{\"level\": null, \"title\": null, \"chunk_index\": 56}', 'bge-large-zh-v1.5', '2026-09-25 17:04:49');
INSERT INTO `chunk` VALUES ('777ca012-00ba-4253-ad32-a88e074d8744', '22a2c356-7a68-4455-b657-333e3dba1e1a', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 5, '国家保护个体经济、私营经济等非公有制经济的合法的权利和利益。国家鼓励、支持和引导非公有制经济的发展，并对非公有制经济依法实行监督和管理。\n第十二条　社会主义的公共财产神圣不可侵犯。\n国家保护社会主义的公共财产。禁止任何组织或者个人用任何手段侵占或者破坏国家的和集体的财产。\n第十三条　公民的合法的私有财产不受侵犯。\n国家依照法律规定保护公民的私有财产权和继承权。\n国家为了公共利益的需要，可以依照法律规定对公民的私有财产实行征收或者征用并给予补偿。\n第十四条　国家通过提高劳动者的积极性和技术水平，推广先进的科学技术，完善经济管理体制和企业经营管理制度，实行各种形式的社会主义责任制，改进劳动组织，以不断提高劳动生产率和经济效益，发展社会生产力。\n国家厉行节约，反对浪费。\n国家合理安排积累和消费，兼顾国家、集体和个人的利益，在发展生产的基础上，逐步改善人民的物质生活和文化生活。\n国家建立健全同经济发展水平相适应的社会保障制度。\n第十五条　国家实行社会主义市场经济。\n国家加强经济立法，完善宏观调控。\n国家依法禁止任何组织或者个人扰乱社会经济秩序。\n第十六条　国有企业在法律规定的范围内有权自主经营。\n国有企业依照法律规定，通过职工代表大会和其他形式，实行民主管理。\n第十七条　集体经济组织在遵守有关法律的前提下，有独立进行经济活动的自主权。\n集体经济组织实行民主管理，依照法律规定选举和罢免管理人员，决定经营管理的重大问题。\n第十八条　中华人民共和国允许外国的企业和其他经济组织或者个人依照中华人民共和国法律的规定在中国投资，同中国的企业或者其他经济组织进行各种形式的经济合作。\n在中国境内的外国企业和其他外国经济组织以及中外合资经营的企业，都必须遵守中华人民共和国的法律。它们的合法的权利和利益受中华人民共和国法律的保护。\n第十九条　国家发展社会主义的教育事业，提高全国人民的科学文化水平', 797, '{\"level\": null, \"title\": null, \"chunk_index\": 5}', 'bge-large-zh-v1.5', '2026-09-25 17:04:28');
INSERT INTO `chunk` VALUES ('780c50f6-a084-4d31-a325-4d049b44cc23', '16cbea7e-7e36-4f31-afb5-63892345d29c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 49, '案件审理部门对于受理的案件，应当以监察法、政务处分法、刑法、《中华人民共和国刑事诉讼法》等法律法规为准绳，对案件事实和证据、性质认定、程序手续、涉案财物等进行全面审理。\n案件审理部门应当强化监督制约职能，对案件严格审核把关，坚持实事求是、独立审理，依法提出审理意见。坚持调查与审理相分离的原则，案件调查人员不得参与审理。\n第二百二十三条　审理工作应当坚持民主集中制原则，经集体审议形成审理意见。\n第二百二十四条　审理工作应当在受理之日起一个月以内完成，重大、复杂案件经批准可以适当延长。\n第二百二十五条　案件审理部门根据案件审理情况，经审批可以与被调查人谈话，告知其在审理阶段的权利义务，核对涉嫌违法犯罪事实，听取其辩解意见，了解有关情况。与被调查人谈话应当在具备安全保障条件的场所进行，被调查人为在押的犯罪嫌疑人、被告人或者在看守所、监狱服刑人员的，按照本条例第八十三条规定办理。谈话时，案件审理人员不得少于二人。\n具有下列情形之一的，一般应当与被调查人谈话：\n（一）对被调查人采取留置措施，拟移送起诉的；\n（二）可能存在以非法方法收集证据情形的；\n（三）被调查人对涉嫌违法犯罪事实材料签署不同意见或者拒不签署意见的；\n（四）被调查人要求向案件审理人员当面陈述的；\n（五）其他有必要与被调查人进行谈话的情形。\n第二百二十六条　经审理认为主要违法犯罪事实不清、证据不足的，应当经审批将案件退回承办部门重新调查。\n具有下列情形之一，需要补充完善证据的，经审批可以退回补充调查：\n（一）部分事实不清、证据不足的；\n（二）遗漏违法犯罪事实的；\n（三）其他需要进一步查清案件事实的情形。\n案件审理部门将案件退回重新调查或者补充调查的，应当出具审核意见，写明调查事项、理由、调查方向、需要补充收集的证据及其证明作用等，连同案卷材料一并送交承办部门', 768, '{\"level\": null, \"title\": null, \"chunk_index\": 49}', 'bge-large-zh-v1.5', '2026-09-25 17:04:49');
INSERT INTO `chunk` VALUES ('78451563-3afe-430d-932c-c1ce9208ed61', 'b25ce095-dfba-4403-acf8-c58eb456ca4c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 128, '第一千一百一十五条　养父母与成年养子女关系恶化、无法共同生活的，可以协议解除收养关系。不能达成协议的，可以向人民法院提起诉讼。\n第一千一百一十六条　当事人协议解除收养关系的，应当到民政部门办理解除收养关系登记。\n第一千一百一十七条　收养关系解除后，养子女与养父母以及其他近亲属间的权利义务关系即行消除，与生父母以及其他近亲属间的权利义务关系自行恢复。但是，成年养子女与生父母以及其他近亲属间的权利义务关系是否恢复，可以协商确定。\n第一千一百一十八条　收养关系解除后，经养父母抚养的成年养子女，对缺乏劳动能力又缺乏生活来源的养父母，应当给付生活费。因养子女成年后虐待、遗弃养父母而解除收养关系的，养父母可以要求养子女补偿收养期间支出的抚养费。\n生父母要求解除收养关系的，养父母可以要求生父母适当补偿收养期间支出的抚养费；但是，因养父母虐待、遗弃养子女而解除收养关系的除外。\n第六编　继　　承\n第一章　一般规定\n第一千一百一十九条　本编调整因继承产生的民事关系。\n第一千一百二十条　国家保护自然人的继承权。\n第一千一百二十一条　继承从被继承人死亡时开始。\n相互有继承关系的数人在同一事件中死亡，难以确定死亡时间的，推定没有其他继承人的人先死亡。都有其他继承人，辈份不同的，推定长辈先死亡；辈份相同的，推定同时死亡，相互不发生继承。\n第一千一百二十二条　遗产是自然人死亡时遗留的个人合法财产。\n依照法律规定或者根据其性质不得继承的遗产，不得继承。\n第一千一百二十三条　继承开始后，按照法定继承办理；有遗嘱的，按照遗嘱继承或者遗赠办理；有遗赠扶养协议的，按照协议办理。\n第一千一百二十四条　继承开始后，继承人放弃继承的，应当在遗产处理前，以书面形式作出放弃继承的表示；没有表示的，视为接受继承。\n受遗赠人应当在知道受遗赠后六十日内，作出接受或者放弃受遗赠的表示；到期没有表示的，视为放弃受遗赠', 792, '{\"level\": null, \"title\": null, \"chunk_index\": 128}', 'bge-large-zh-v1.5', '2026-09-25 17:05:01');
INSERT INTO `chunk` VALUES ('787cda40-add9-4f59-8ada-9b397488f01c', '16cbea7e-7e36-4f31-afb5-63892345d29c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 63, '国家监察委员会派驻或者派出的监察机构、监察专员和地方各级监察机关办理涉外案件中有关执法司法国际合作事项，应当逐级报送国家监察委员会审批。由国家监察委员会依法直接或者协调有关单位与有关国家（地区）相关机构沟通，以双方认可的方式实施。\n第二百六十八条　监察机关应当建立追逃追赃和防逃工作内部联络机制。承办部门在调查过程中，发现被调查人或者重要涉案人员外逃、违法所得及其他涉案财产被转移到境外的，可以请追逃追赃部门提供工作协助。监察机关将案件移送人民检察院审查起诉后，仍有重要涉案人员外逃或者未追缴的违法所得及其他涉案财产的，应当由追逃追赃部门继续办理，或者由追逃追赃部门指定协调有关单位办理。\n第二节　国（境）内工作\n第二百六十九条　监察机关应当将防逃工作纳入日常监督内容，督促相关机关、单位建立健全防逃责任机制。\n监察机关在监督、调查工作中，应当根据情况制定对监察对象、重要涉案人员的防逃方案，防范人员外逃和资金外流风险。监察机关应当会同同级组织人事、外事、公安、移民管理等单位健全防逃预警机制，对存在外逃风险的监察对象早发现、早报告、早处置。\n第二百七十条　监察机关应当加强与同级人民银行、公安等单位的沟通协作，推动预防、打击利用离岸公司和地下钱庄等向境外转移违法所得及其他涉案财产，对涉及职务违法和职务犯罪的行为依法进行调查。\n第二百七十一条　国家监察委员会派驻或者派出的监察机构、监察专员和地方各级监察委员会发现监察对象出逃、失踪、出走，或者违法所得及其他涉案财产被转移至境外的，应当在二十四小时以内将有关信息逐级报送至国家监察委员会国际合作局，并迅速开展相关工作。\n第二百七十二条　监察机关追逃追赃部门统一接收巡视巡察机构、审计机关、执法机关、司法机关等单位移交的外逃信息。\n监察机关对涉嫌职务违法和职务犯罪的外逃人员，应当明确承办部门，建立案件档案', 778, '{\"level\": null, \"title\": null, \"chunk_index\": 63}', 'bge-large-zh-v1.5', '2026-09-25 17:04:49');
INSERT INTO `chunk` VALUES ('7947696f-0542-4cb2-a008-a736b6734e47', 'b25ce095-dfba-4403-acf8-c58eb456ca4c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 127, '第一千一百零七条　孤儿或者生父母无力抚养的子女，可以由生父母的亲属、朋友抚养；抚养人与被抚养人的关系不适用本章规定。\n第一千一百零八条　配偶一方死亡，另一方送养未成年子女的，死亡一方的父母有优先抚养的权利。\n第一千一百零九条　外国人依法可以在中华人民共和国收养子女。\n外国人在中华人民共和国收养子女，应当经其所在国主管机关依照该国法律审查同意。收养人应当提供由其所在国有权机构出具的有关其年龄、婚姻、职业、财产、健康、有无受过刑事处罚等状况的证明材料，并与送养人签订书面协议，亲自向省、自治区、直辖市人民政府民政部门登记。\n前款规定的证明材料应当经收养人所在国外交机关或者外交机关授权的机构认证，并经中华人民共和国驻该国使领馆认证，但是国家另有规定的除外。\n第一千一百一十条　收养人、送养人要求保守收养秘密的，其他人应当尊重其意愿，不得泄露。\n第二节　收养的效力\n第一千一百一十一条　自收养关系成立之日起，养父母与养子女间的权利义务关系，适用本法关于父母子女关系的规定；养子女与养父母的近亲属间的权利义务关系，适用本法关于子女与父母的近亲属关系的规定。\n养子女与生父母以及其他近亲属间的权利义务关系，因收养关系的成立而消除。\n第一千一百一十二条　养子女可以随养父或者养母的姓氏，经当事人协商一致，也可以保留原姓氏。\n第一千一百一十三条　有本法第一编关于民事法律行为无效规定情形或者违反本编规定的收养行为无效。\n无效的收养行为自始没有法律约束力。\n第三节　收养关系的解除\n第一千一百一十四条　收养人在被收养人成年以前，不得解除收养关系，但是收养人、送养人双方协议解除的除外。养子女八周岁以上的，应当征得本人同意。\n收养人不履行抚养义务，有虐待、遗弃等侵害未成年养子女合法权益行为的，送养人有权要求解除养父母与养子女间的收养关系。送养人、收养人不能达成解除收养关系协议的，可以向人民法院提起诉讼', 795, '{\"level\": null, \"title\": null, \"chunk_index\": 127}', 'bge-large-zh-v1.5', '2026-09-25 17:05:01');
INSERT INTO `chunk` VALUES ('79572d35-1562-4675-b001-b0459e85c35f', '16cbea7e-7e36-4f31-afb5-63892345d29c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 73, '第三百一十七条　监察机关应当建立健全办案安全责任制。承办部门主要负责人和调查组组长是调查安全第一责任人。调查组应当指定专人担任安全员。\n地方各级监察机关履行管理、监督职责不力发生严重办案安全事故、事件的，或者办案中存在严重违规违纪违法行为的，省级监察机关主要负责人应当按规定向国家监察委员会作出检讨，并予以通报、严肃追责问责。\n案件监督管理部门应当对办案安全责任制落实情况组织经常性检查和不定期抽查，发现问题及时报告并督促整改。\n第三百一十八条　监察人员在履行职责中有下列行为之一的，依法严肃处理；构成犯罪的，依法追究刑事责任：\n（一）贪污贿赂、徇私舞弊的；\n（二）不履行或者不正确履行监督职责，应当发现的问题没有发现，或者发现问题不报告、不处置，造成严重影响的；\n（三）未经批准、授权处置问题线索，发现重大案情隐瞒不报，或者私自留存、处理涉案材料的；\n（四）利用职权或者职务上的影响干预调查工作的；\n（五）违法窃取、泄露调查工作信息，或者泄露举报事项、举报受理情况以及举报人信息的；\n（六）对被调查人或者涉案人员等逼供、诱供，或者侮辱、打骂、虐待、体罚或者变相体罚的；\n（七）违反规定处置查封、扣押、冻结的财物的；\n（八）违反规定导致发生办案安全事故、事件，或者发生安全事故、事件后隐瞒不报、报告失实、处置不当的；\n（九）违反规定采取强制到案、责令候查、管护、留置或者禁闭措施，或者法定期限届满，不予以解除或者变更的；\n（十）违反规定采取技术调查、限制出境措施，或者不按规定解除技术调查、限制出境措施的；\n（十一）利用职权非法干扰企业生产经营或者侵害企业经营者人身权利、财产权利和其他合法权益的；\n（十二）其他职务违法和职务犯罪行为。\n第三百一十九条　对监察人员在履行职责中存在违法行为的，可以根据情节轻重，依法进行谈话提醒、批评教育、责令检查、诫勉，或者给予政务处分。构成犯罪的，依法追究刑事责任', 800, '{\"level\": null, \"title\": null, \"chunk_index\": 73}', 'bge-large-zh-v1.5', '2026-09-25 17:04:49');
INSERT INTO `chunk` VALUES ('798edcc4-23a0-4550-94c4-6fb0e636bfd2', '821ce1fd-178d-4a7e-ab92-3deff1488ce2', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 89, '第三百九十条之一　为谋取不正当利益，向国家工作人员的近亲属或者其他与该国家工作人员关系密切的人，或者向离职的国家工作人员或者其近亲属以及其他与其关系密切的人行贿的，处三年以下有期徒刑或者拘役，并处罚金；情节严重的，或者使国家利益遭受重大损失的，处三年以上七年以下有期徒刑，并处罚金；情节特别严重的，或者使国家利益遭受特别重大损失的，处七年以上十年以下有期徒刑，并处罚金。\n单位犯前款罪的，对单位判处罚金，并对其直接负责的主管人员和其他直接责任人员，处三年以下有期徒刑或者拘役，并处罚金。\n第三百九十一条　为谋取不正当利益，给予国家机关、国有公司、企业、事业单位、人民团体以财物的，或者在经济往来中，违反国家规定，给予各种名义的回扣、手续费的，处三年以下有期徒刑或者拘役，并处罚金。\n单位犯前款罪的，对单位判处罚金，并对其直接负责的主管人员和其他直接责任人员，依照前款的规定处罚。\n第三百九十二条　向国家工作人员介绍贿赂，情节严重的，处三年以下有期徒刑或者拘役，并处罚金。\n介绍贿赂人在被追诉前主动交待介绍贿赂行为的，可以减轻处罚或者免除处罚。\n第三百九十三条　单位为谋取不正当利益而行贿，或者违反国家规定，给予国家工作人员以回扣、手续费，情节严重的，对单位判处罚金，并对其直接负责的主管人员和其他直接责任人员，处五年以下有期徒刑或者拘役，并处罚金。因行贿取得的违法所得归个人所有的，依照本法第三百八十九条、第三百九十条的规定定罪处罚。\n第三百九十四条　国家工作人员在国内公务活动或者对外交往中接受礼物，依照国家规定应当交公而不交公，数额较大的，依照本法第三百八十二条、第三百八十三条的规定定罪处罚', 698, '{\"level\": null, \"title\": null, \"chunk_index\": 89}', 'bge-large-zh-v1.5', '2026-09-25 17:04:56');
INSERT INTO `chunk` VALUES ('799941c0-2619-482a-9828-c0b66658dc1b', '0497a5e7-7044-4b18-8fed-af3fb7bc7890', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 4, '第二十三条　一般纳税人购进货物（不含固定资产）、服务，用于简易计税方法计税项目、免征增值税项目和不得抵扣非应税交易而无法划分不得抵扣的进项税额的，应当按照销售额或者收入占比逐期计算当期不得抵扣的进项税额，并于次年1月的纳税申报期内进行全年汇总清算。\n第二十四条　已抵扣进项税额的购进货物（不含固定资产）、服务，发生增值税法第二十二条第三项至第五项规定情形的，应当将对应的进项税额从当期进项税额中扣减；无法确定对应的进项税额的，按照当期实际成本计算应扣减的进项税额。\n第二十五条　一般纳税人取得的固定资产、无形资产或者不动产（以下统称长期资产），既用于一般计税方法计税项目，又用于简易计税方法计税项目、免征增值税项目、不得抵扣非应税交易、集体福利或者个人消费（以下统称五类不允许抵扣项目）的，属于用作混合用途的长期资产，对应的进项税额依照增值税法和下列规定处理：\n（一）原值不超过500万元的单项长期资产，对应的进项税额可以全额从销项税额中抵扣；\n（二）原值超过500万元的单项长期资产，购进时先全额抵扣进项税额，此后在用于混合用途期间，根据调整年限计算五类不允许抵扣项目对应的不得从销项税额中抵扣的进项税额，逐年调整。\n长期资产进项税额抵扣的具体操作办法，由国务院财政、税务主管部门制定。\n第四章　税收优惠\n第二十六条　增值税法第二十四条第一款第一项所称农业生产者，是指从事农业生产的单位和个人；农产品，是指初级农产品。\n第二十七条　增值税法第二十四条第一款第二项所称医疗机构，是指依据有关规定设立的具有医疗机构执业资格的机构，包括军队、武警部队各级各类医疗机构，不包括营利性美容医疗机构。\n第二十八条　增值税法第二十四条第一款第三项所称古旧图书，是指向社会收购的古书和旧书', 737, '{\"level\": null, \"title\": null, \"chunk_index\": 4}', 'bge-large-zh-v1.5', '2026-09-25 17:04:28');
INSERT INTO `chunk` VALUES ('79a43b2e-899d-4c64-b52e-36e3bc0b6775', '821ce1fd-178d-4a7e-ab92-3deff1488ce2', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 29, '第一百六十一条　依法负有信息披露义务的公司、企业向股东和社会公众提供虚假的或者隐瞒重要事实的财务会计报告，或者对依法应当披露的其他重要信息不按照规定披露，严重损害股东或者其他人利益，或者有其他严重情节的，对其直接负责的主管人员和其他直接责任人员，处五年以下有期徒刑或者拘役，并处或者单处罚金；情节特别严重的，处五年以上十年以下有期徒刑，并处罚金。\n前款规定的公司、企业的控股股东、实际控制人实施或者组织、指使实施前款行为的，或者隐瞒相关事项导致前款规定的情形发生的，依照前款的规定处罚。\n犯前款罪的控股股东、实际控制人是单位的，对单位判处罚金，并对其直接负责的主管人员和其他直接责任人员，依照第一款的规定处罚。\n第一百六十二条　公司、企业进行清算时，隐匿财产，对资产负债表或者财产清单作虚伪记载或者在未清偿债务前分配公司、企业财产，严重损害债权人或者其他人利益的，对其直接负责的主管人员和其他直接责任人员，处五年以下有期徒刑或者拘役，并处或者单处二万元以上二十万元以下罚金。\n第一百六十二条之一　隐匿或者故意销毁依法应当保存的会计凭证、会计帐簿、财务会计报告，情节严重的，处五年以下有期徒刑或者拘役，并处或者单处二万元以上二十万元以下罚金。\n单位犯前款罪的，对单位判处罚金，并对其直接负责的主管人员和其他直接责任人员，依照前款的规定处罚。\n第一百六十二条之二　公司、企业通过隐匿财产、承担虚构的债务或者以其他方法转移、处分财产，实施虚假破产，严重损害债权人或者其他人利益的，对其直接负责的主管人员和其他直接责任人员，处五年以下有期徒刑或者拘役，并处或者单处二万元以上二十万元以下罚金', 691, '{\"level\": null, \"title\": null, \"chunk_index\": 29}', 'bge-large-zh-v1.5', '2026-09-25 17:04:56');
INSERT INTO `chunk` VALUES ('7a32a7a6-42b5-4fe9-ad25-7368d32f1523', 'b25ce095-dfba-4403-acf8-c58eb456ca4c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 46, '第四百一十三条　抵押财产折价或者拍卖、变卖后，其价款超过债权数额的部分归抵押人所有，不足部分由债务人清偿。\n第四百一十四条　同一财产向两个以上债权人抵押的，拍卖、变卖抵押财产所得的价款依照下列规定清偿：\n（一）抵押权已经登记的，按照登记的时间先后确定清偿顺序；\n（二）抵押权已经登记的先于未登记的受偿；\n（三）抵押权未登记的，按照债权比例清偿。\n其他可以登记的担保物权，清偿顺序参照适用前款规定。\n第四百一十五条　同一财产既设立抵押权又设立质权的，拍卖、变卖该财产所得的价款按照登记、交付的时间先后确定清偿顺序。\n第四百一十六条　动产抵押担保的主债权是抵押物的价款，标的物交付后十日内办理抵押登记的，该抵押权人优先于抵押物买受人的其他担保物权人受偿，但是留置权人除外。\n第四百一十七条　建设用地使用权抵押后，该土地上新增的建筑物不属于抵押财产。该建设用地使用权实现抵押权时，应当将该土地上新增的建筑物与建设用地使用权一并处分。但是，新增建筑物所得的价款，抵押权人无权优先受偿。\n第四百一十八条　以集体所有土地的使用权依法抵押的，实现抵押权后，未经法定程序，不得改变土地所有权的性质和土地用途。\n第四百一十九条　抵押权人应当在主债权诉讼时效期间行使抵押权；未行使的，人民法院不予保护。\n第二节　最高额抵押权\n第四百二十条　为担保债务的履行，债务人或者第三人对一定期间内将要连续发生的债权提供担保财产的，债务人不履行到期债务或者发生当事人约定的实现抵押权的情形，抵押权人有权在最高债权额限度内就该担保财产优先受偿。\n最高额抵押权设立前已经存在的债权，经当事人同意，可以转入最高额抵押担保的债权范围。\n第四百二十一条　最高额抵押担保的债权确定前，部分债权转让的，最高额抵押权不得转让，但是当事人另有约定的除外', 751, '{\"level\": null, \"title\": null, \"chunk_index\": 46}', 'bge-large-zh-v1.5', '2026-09-25 17:05:01');
INSERT INTO `chunk` VALUES ('7b306146-979f-4753-be28-e412a1ff2185', 'd9d7dc15-8041-43b8-9f75-f112fe3ae003', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 12, '第四十四条　研制开发单位进行危险化学品新工艺、新技术、新产品开发，应当加强研制开发过程的安全管理，确保研制开发过程安全，不得将未经小试、中试、工业化试验的新工艺、新技术直接用于工业化生产。\n研制开发单位转让危险化学品新工艺、新技术时，应当提供新工艺、新技术的安全论证报告及相关资料，并进行技术指导。\n第四十五条　生产、储存危险化学品的单位整体或者部分转产、停产、停业、解散的，应当采取有效措施，及时、妥善处置其危险化学品生产装置、储存设施以及库存的危险化学品，不得丢弃危险化学品；处置方案应当报所在地县级人民政府应急管理、工业和信息化、生态环境部门和公安机关、消防救援机构备案。应急管理部门应当会同生态环境主管部门和公安机关、消防救援机构对处置情况进行监督检查，发现未按照规定处置的，应当责令其立即处置。\n第四章　使用安全\n第四十六条　县级以上人民政府有关部门应当依照职责分工，加强对企业、学校、科研机构、医疗机构、检测机构、检验机构等单位使用危险化学品的监督管理。\n第四十七条　使用危险化学品的单位的使用条件（包括工艺）应当符合法律、行政法规的规定和国家标准、行业标准的要求，并根据所使用的危险化学品的种类、危险特性以及使用量和使用方式，建立健全使用危险化学品的安全管理规章制度和安全操作规程，保证危险化学品的安全使用。\n第四十八条　使用国家规定种类的危险化学品从事生产并且使用量达到规定数量的化工企业（属于危险化学品生产企业的除外，下同），应当依照本法的规定取得危险化学品安全使用许可证。\n前款规定的危险化学品种类及其使用量的数量标准，由国务院应急管理部门会同公安、农业农村部门确定并公布', 696, '{\"level\": null, \"title\": null, \"chunk_index\": 12}', 'bge-large-zh-v1.5', '2026-09-25 17:04:46');
INSERT INTO `chunk` VALUES ('7b94c995-3be3-4ffe-b6fa-a46464ec219e', '16cbea7e-7e36-4f31-afb5-63892345d29c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 74, '第三百二十条　监察机关及其工作人员在行使职权时，具有下列情形之一的，受害人可以申请国家赔偿：\n（一）违法采取管护、禁闭措施，或者依照法定条件和程序采取管护、禁闭措施，但是管护时间、禁闭时间超过法定时限，其后决定撤销案件的；\n（二）采取留置措施后，决定撤销案件的；\n（三）违法没收、追缴或者违法查封、扣押、冻结财物造成损害的；\n（四）违法行使职权，造成被调查人、涉案人员或者证人身体伤害或者死亡的；\n（五）其他侵犯公民、法人和其他组织合法权益造成损害的。\n受害人死亡的，其继承人和其他有扶养关系的亲属有权要求赔偿；受害的法人或者其他组织终止的，其权利承受人有权要求赔偿。\n第三百二十一条　监察机关及其工作人员违法行使职权侵犯公民、法人和其他组织的合法权益造成损害的，该机关为赔偿义务机关。申请赔偿应当向赔偿义务机关提出，由该机关负责复审复核工作的部门受理。\n赔偿以支付赔偿金为主要方式。能够返还财产或者恢复原状的，予以返还财产或者恢复原状。\n第九章　附　　则\n第三百二十二条　本条例所称监察机关，包括各级监察委员会及其派驻或者派出监察机构、监察专员，以及再派出的监察机构、监察专员。\n第三百二十三条　本条例所称严重职务违法，是指根据监察机关已经掌握的事实及证据，被调查人涉嫌的职务违法行为情节严重，可能被给予撤职以上政务处分。\n本条例所称重大职务犯罪、重大贪污贿赂等职务犯罪，是指具有下列情形之一的职务犯罪：\n（一）案情重大、复杂，涉及国家利益、重大公共利益或者犯罪行为致使公共财产、国家和人民利益遭受特别重大损失的；\n（二）被调查人可能被判处十年有期徒刑以上刑罚的；\n（三）案件在全国或者本省、自治区、直辖市范围内有较大影响的。\n第三百二十四条　本条例所称同种罪行和不同种罪行，应当以罪名区分，但属选择性罪名或者在法律、事实上密切关联的犯罪，应当认定为同种罪行', 780, '{\"level\": null, \"title\": null, \"chunk_index\": 74}', 'bge-large-zh-v1.5', '2026-09-25 17:04:49');
INSERT INTO `chunk` VALUES ('7d312e51-a9fc-42b4-a43c-9f900875b801', '821ce1fd-178d-4a7e-ab92-3deff1488ce2', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 26, '第二节　走私罪\n第一百五十一条　走私武器、弹药、核材料或者伪造的货币的，处七年以上有期徒刑，并处罚金或者没收财产；情节特别严重的，处无期徒刑，并处没收财产；情节较轻的，处三年以上七年以下有期徒刑，并处罚金。\n走私国家禁止出口的文物、黄金、白银和其他贵重金属或者国家禁止进出口的珍贵动物及其制品的，处五年以上十年以下有期徒刑，并处罚金；情节特别严重的，处十年以上有期徒刑或者无期徒刑，并处没收财产；情节较轻的，处五年以下有期徒刑，并处罚金。\n走私珍稀植物及其制品等国家禁止进出口的其他货物、物品的，处五年以下有期徒刑或者拘役，并处或者单处罚金；情节严重的，处五年以上有期徒刑，并处罚金。\n单位犯本条规定之罪的，对单位判处罚金，并对其直接负责的主管人员和其他直接责任人员，依照本条各款的规定处罚。\n第一百五十二条　以牟利或者传播为目的，走私淫秽的影片、录像带、录音带、图片、书刊或者其他淫秽物品的，处三年以上十年以下有期徒刑，并处罚金；情节严重的，处十年以上有期徒刑或者无期徒刑，并处罚金或者没收财产；情节较轻的，处三年以下有期徒刑、拘役或者管制，并处罚金。\n逃避海关监管将境外固体废物、液态废物和气态废物运输进境，情节严重的，处五年以下有期徒刑，并处或者单处罚金；情节特别严重的，处五年以上有期徒刑，并处罚金。\n单位犯前两款罪的，对单位判处罚金，并对其直接负责的主管人员和其他直接责任人员，依照前两款的规定处罚。\n第一百五十三条　走私本法第一百五十一条、第一百五十二条、第三百四十七条规定以外的货物、物品的，根据情节轻重，分别依照下列规定处罚：\n（一）走私货物、物品偷逃应缴税额较大或者一年内曾因走私被给予二次行政处罚后又走私的，处三年以下有期徒刑或者拘役，并处偷逃应缴税额一倍以上五倍以下罚金', 746, '{\"level\": null, \"title\": null, \"chunk_index\": 26}', 'bge-large-zh-v1.5', '2026-09-25 17:04:56');
INSERT INTO `chunk` VALUES ('7dc61161-352f-49ec-9713-ed3779745022', 'b25ce095-dfba-4403-acf8-c58eb456ca4c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 104, '因仓储物本身的自然性质、包装不符合约定或者超过有效储存期造成仓储物变质、损坏的，保管人不承担赔偿责任。\n第九百一十八条　本章没有规定的，适用保管合同的有关规定。\n第二十三章　委托合同\n第九百一十九条　委托合同是委托人和受托人约定，由受托人处理委托人事务的合同。\n第九百二十条　委托人可以特别委托受托人处理一项或者数项事务，也可以概括委托受托人处理一切事务。\n第九百二十一条　委托人应当预付处理委托事务的费用。受托人为处理委托事务垫付的必要费用，委托人应当偿还该费用并支付利息。\n第九百二十二条　受托人应当按照委托人的指示处理委托事务。需要变更委托人指示的，应当经委托人同意；因情况紧急，难以和委托人取得联系的，受托人应当妥善处理委托事务，但是事后应当将该情况及时报告委托人。\n第九百二十三条　受托人应当亲自处理委托事务。经委托人同意，受托人可以转委托。转委托经同意或者追认的，委托人可以就委托事务直接指示转委托的第三人，受托人仅就第三人的选任及其对第三人的指示承担责任。转委托未经同意或者追认的，受托人应当对转委托的第三人的行为承担责任；但是，在紧急情况下受托人为了维护委托人的利益需要转委托第三人的除外。\n第九百二十四条　受托人应当按照委托人的要求，报告委托事务的处理情况。委托合同终止时，受托人应当报告委托事务的结果。\n第九百二十五条　受托人以自己的名义，在委托人的授权范围内与第三人订立的合同，第三人在订立合同时知道受托人与委托人之间的代理关系的，该合同直接约束委托人和第三人；但是，有确切证据证明该合同只约束受托人和第三人的除外。\n第九百二十六条　受托人以自己的名义与第三人订立合同时，第三人不知道受托人与委托人之间的代理关系的，受托人因第三人的原因对委托人不履行义务，受托人应当向委托人披露第三人，委托人因此可以行使受托人对第三人的权利', 773, '{\"level\": null, \"title\": null, \"chunk_index\": 104}', 'bge-large-zh-v1.5', '2026-09-25 17:05:01');
INSERT INTO `chunk` VALUES ('7e0b4bf1-2f8e-462c-ac87-c190ec1c9386', 'b25ce095-dfba-4403-acf8-c58eb456ca4c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 70, '第六百一十二条　出卖人就交付的标的物，负有保证第三人对该标的物不享有任何权利的义务，但是法律另有规定的除外。\n第六百一十三条　买受人订立合同时知道或者应当知道第三人对买卖的标的物享有权利的，出卖人不承担前条规定的义务。\n第六百一十四条　买受人有确切证据证明第三人对标的物享有权利的，可以中止支付相应的价款，但是出卖人提供适当担保的除外。\n第六百一十五条　出卖人应当按照约定的质量要求交付标的物。出卖人提供有关标的物质量说明的，交付的标的物应当符合该说明的质量要求。\n第六百一十六条　当事人对标的物的质量要求没有约定或者约定不明确，依据本法第五百一十条的规定仍不能确定的，适用本法第五百一十一条第一项的规定。\n第六百一十七条　出卖人交付的标的物不符合质量要求的，买受人可以依据本法第五百八十二条至第五百八十四条的规定请求承担违约责任。\n第六百一十八条　当事人约定减轻或者免除出卖人对标的物瑕疵承担的责任，因出卖人故意或者重大过失不告知买受人标的物瑕疵的，出卖人无权主张减轻或者免除责任。\n第六百一十九条　出卖人应当按照约定的包装方式交付标的物。对包装方式没有约定或者约定不明确，依据本法第五百一十条的规定仍不能确定的，应当按照通用的方式包装；没有通用方式的，应当采取足以保护标的物且有利于节约资源、保护生态环境的包装方式。\n第六百二十条　买受人收到标的物时应当在约定的检验期限内检验。没有约定检验期限的，应当及时检验。\n第六百二十一条　当事人约定检验期限的，买受人应当在检验期限内将标的物的数量或者质量不符合约定的情形通知出卖人。买受人怠于通知的，视为标的物的数量或者质量符合约定。\n当事人没有约定检验期限的，买受人应当在发现或者应当发现标的物的数量或者质量不符合约定的合理期限内通知出卖人', 744, '{\"level\": null, \"title\": null, \"chunk_index\": 70}', 'bge-large-zh-v1.5', '2026-09-25 17:05:01');
INSERT INTO `chunk` VALUES ('7e81330c-cddc-4d53-a6ae-3ffdce7d22eb', 'd9d7dc15-8041-43b8-9f75-f112fe3ae003', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 30, '第一百零四条　有下列情形之一的，由公安机关责令限期改正，可以处二万元以上十万元以下的罚款；逾期不改正的，处十万元以上二十万元以下的罚款，对直接负责的主管人员和其他直接责任人员处一万元以上五万元以下的罚款：\n（一）生产、储存、使用剧毒化学品、易制爆危险化学品的单位不如实记录其生产、储存、使用的剧毒化学品、易制爆危险化学品的品种、数量、流向；\n（二）生产、储存、使用剧毒化学品、易制爆危险化学品的单位发现剧毒化学品、易制爆危险化学品丢失或者被盗，不立即向公安机关报告；\n（三）储存剧毒化学品的单位未将剧毒化学品的储存数量、储存地点以及管理人员的情况报所在地县级人民政府公安机关备案；\n（四）危险化学品生产企业、经营企业不如实记录剧毒化学品、易制爆危险化学品购买单位的名称、地址，经办人的姓名、身份证号码以及所购买的剧毒化学品、易制爆危险化学品的品种、数量、用途，或者保存销售记录和相关材料的时间少于三年；\n（五）剧毒化学品、易制爆危险化学品的销售企业、购买单位未在规定的时限内将所销售、购买的剧毒化学品、易制爆危险化学品的品种、数量以及流向信息报所在地县级人民政府公安机关备案；\n（六）使用剧毒化学品、易制爆危险化学品的单位依照本法规定转让其购买的剧毒化学品、易制爆危险化学品，未将有关情况在转让后三日内向所在地县级人民政府公安机关备案。\n生产、储存危险化学品的企业，使用危险化学品从事生产的企业，或者在港区内储存、装卸危险化学品的企业未依照本法规定将安全评价报告以及整改方案的落实情况报所在地县级人民政府应急管理部门或者港口行政管理部门备案的，分别由应急管理部门或者港口行政管理部门依照前款规定予以处理、处罚', 704, '{\"level\": null, \"title\": null, \"chunk_index\": 30}', 'bge-large-zh-v1.5', '2026-09-25 17:04:46');
INSERT INTO `chunk` VALUES ('81c9b840-be1c-45a3-8f33-0f697a5de1a0', '821ce1fd-178d-4a7e-ab92-3deff1488ce2', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 7, '第四十条　被判处管制的犯罪分子，管制期满，执行机关应即向本人和其所在单位或者居住地的群众宣布解除管制。\n第四十一条　管制的刑期，从判决执行之日起计算；判决执行以前先行羁押的，羁押一日折抵刑期二日。\n第三节　拘　　役\n第四十二条　拘役的期限，为一个月以上六个月以下。\n第四十三条　被判处拘役的犯罪分子，由公安机关就近执行。\n在执行期间，被判处拘役的犯罪分子每月可以回家一天至两天；参加劳动的，可以酌量发给报酬。\n第四十四条　拘役的刑期，从判决执行之日起计算；判决执行以前先行羁押的，羁押一日折抵刑期一日。\n第四节　有期徒刑、无期徒刑\n第四十五条　有期徒刑的期限，除本法第五十条、第六十九条规定外，为六个月以上十五年以下。\n第四十六条　被判处有期徒刑、无期徒刑的犯罪分子，在监狱或者其他执行场所执行；凡有劳动能力的，都应当参加劳动，接受教育和改造。\n第四十七条　有期徒刑的刑期，从判决执行之日起计算；判决执行以前先行羁押的，羁押一日折抵刑期一日。\n第五节　死　　刑\n第四十八条　死刑只适用于罪行极其严重的犯罪分子。对于应当判处死刑的犯罪分子，如果不是必须立即执行的，可以判处死刑同时宣告缓期二年执行。\n死刑除依法由最高人民法院判决的以外，都应当报请最高人民法院核准。死刑缓期执行的，可以由高级人民法院判决或者核准。\n第四十九条　犯罪的时候不满十八周岁的人和审判的时候怀孕的妇女，不适用死刑。\n审判的时候已满七十五周岁的人，不适用死刑，但以特别残忍手段致人死亡的除外。\n第五十条　判处死刑缓期执行的，在死刑缓期执行期间，如果没有故意犯罪，二年期满以后，减为无期徒刑；如果确有重大立功表现，二年期满以后，减为二十五年有期徒刑；如果故意犯罪，情节恶劣的，报请最高人民法院核准后执行死刑；对于故意犯罪未执行死刑的，死刑缓期执行的期间重新计算，并报最高人民法院备案', 775, '{\"level\": null, \"title\": null, \"chunk_index\": 7}', 'bge-large-zh-v1.5', '2026-09-25 17:04:56');
INSERT INTO `chunk` VALUES ('820a336c-f047-453f-8f25-de04c4807109', '821ce1fd-178d-4a7e-ab92-3deff1488ce2', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 35, '第一百七十七条　有下列情形之一，伪造、变造金融票证的，处五年以下有期徒刑或者拘役，并处或者单处二万元以上二十万元以下罚金；情节严重的，处五年以上十年以下有期徒刑，并处五万元以上五十万元以下罚金；情节特别严重的，处十年以上有期徒刑或者无期徒刑，并处五万元以上五十万元以下罚金或者没收财产：\n（一）伪造、变造汇票、本票、支票的；\n（二）伪造、变造委托收款凭证、汇款凭证、银行存单等其他银行结算凭证的；\n（三）伪造、变造信用证或者附随的单据、文件的；\n（四）伪造信用卡的。\n单位犯前款罪的，对单位判处罚金，并对其直接负责的主管人员和其他直接责任人员，依照前款的规定处罚。\n第一百七十七条之一　有下列情形之一，妨害信用卡管理的，处三年以下有期徒刑或者拘役，并处或者单处一万元以上十万元以下罚金；数量巨大或者有其他严重情节的，处三年以上十年以下有期徒刑，并处二万元以上二十万元以下罚金：\n（一）明知是伪造的信用卡而持有、运输的，或者明知是伪造的空白信用卡而持有、运输，数量较大的；\n（二）非法持有他人信用卡，数量较大的；\n（三）使用虚假的身份证明骗领信用卡的；\n（四）出售、购买、为他人提供伪造的信用卡或者以虚假的身份证明骗领的信用卡的。\n窃取、收买或者非法提供他人信用卡信息资料的，依照前款规定处罚。\n银行或者其他金融机构的工作人员利用职务上的便利，犯第二款罪的，从重处罚。\n第一百七十八条　伪造、变造国库券或者国家发行的其他有价证券，数额较大的，处三年以下有期徒刑或者拘役，并处或者单处二万元以上二十万元以下罚金；数额巨大的，处三年以上十年以下有期徒刑，并处五万元以上五十万元以下罚金；数额特别巨大的，处十年以上有期徒刑或者无期徒刑，并处五万元以上五十万元以下罚金或者没收财产', 735, '{\"level\": null, \"title\": null, \"chunk_index\": 35}', 'bge-large-zh-v1.5', '2026-09-25 17:04:56');
INSERT INTO `chunk` VALUES ('825f417d-052b-4192-9f2b-7ed9c407a348', '16cbea7e-7e36-4f31-afb5-63892345d29c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 19, '讯问一般按照下列顺序进行：\n（一）核实被讯问人的基本情况，包括姓名、曾用名、出生年月日、户籍地、身份证件号码、民族、职业、政治面貌、文化程度、工作单位及职务、住所、家庭情况、社会经历，是否属于党代表大会代表、人大代表、政协委员，是否受到过党纪政务处分，是否受到过刑事处罚等；\n（二）告知被讯问人如实供述自己罪行可以依法从宽处理和认罪认罚的法律规定；\n（三）讯问被讯问人是否有犯罪行为，让其陈述有罪的事实或者无罪的辩解，应当允许其连贯陈述。\n调查人员的提问应当与调查的案件相关。被讯问人对调查人员的提问应当如实回答。调查人员对被讯问人的辩解，应当如实记录，认真查核。\n发现涉嫌职务犯罪的被调查人自动投案、如实供述监察机关还未掌握的违法犯罪行为、揭发他人犯罪行为或者提供重要线索等，可能具有自首、立功等法定情节的，应当依法及时讯问。对某一具体涉嫌职务犯罪事实初步查清后，应当在全面梳理分析在案证据的基础上进行讯问。\n讯问时，应当告知被讯问人将进行全程同步录音录像。告知情况应当在录音录像中予以反映，并在笔录中记明。\n第九十一条　本条例第八十二条至第八十六条的要求，也适用于讯问。\n第五节　询　　问\n第九十二条　监察机关按规定报批后，可以依法对证人、被害人等人员进行询问，了解核实有关问题或者案件情况。\n第九十三条　证人未被限制人身自由的，可以在其工作地点、住所或者其提出的地点进行询问，也可以通知其到指定地点接受询问。到证人提出的地点或者调查人员指定的地点进行询问的，应当在笔录中记明。\n调查人员认为有必要或者证人提出需要由所在单位派员或者其家属陪同到询问地点的，应当办理交接手续并填写《陪送交接单》。\n第九十四条　询问应当个别进行。负责询问的调查人员不得少于二人。\n首次询问时，应当向证人出示《证人权利义务告知书》，由其签名、捺指印。证人拒绝签名、捺指印的，调查人员应当在文书上记明', 790, '{\"level\": null, \"title\": null, \"chunk_index\": 19}', 'bge-large-zh-v1.5', '2026-09-25 17:04:49');
INSERT INTO `chunk` VALUES ('8324d80e-9ad2-48a1-bf00-6d5f447b1872', '16cbea7e-7e36-4f31-afb5-63892345d29c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 52, '处分决定应当在作出之日起一个月以内执行完毕，特殊情况下经监察机关批准可以适当延长办理期限，最迟不得超过六个月。\n第二百三十四条　监察机关对不履行或者不正确履行职责造成严重后果或者恶劣影响的领导人员，可以按照管理权限采取通报、诫勉、政务处分等方式进行问责；提出组织处理的建议。\n第二百三十五条　监察机关依法向监察对象所在单位提出监察建议的，应当经审批制作监察建议书。\n监察建议书一般应当包括下列内容：\n（一）监督调查情况；\n（二）发现的主要问题及其产生的原因；\n（三）整改建议内容和要求；\n（四）整改期限和反馈整改情况的要求；\n（五）提出异议的期限和方式。\n第二百三十六条　监察机关在研究提出监察建议过程中，应当坚持问题导向、系统观念，加强分析研判，保证监察建议质量。\n监察机关可以采取专题调研、部门会商、征求特约监察员等有关人员意见，以及与被建议单位或者其他有关方面沟通等方式，提高监察建议的针对性、可行性。\n第二百三十七条　监察机关经调查，对没有证据证明或者现有证据不足以证明被调查人存在违法犯罪行为的，应当依法撤销案件。省级以下监察机关撤销案件后，应当在七个工作日以内向上一级监察机关报送备案报告。上一级监察机关监督检查部门负责备案工作。\n省级以下监察机关拟撤销上级监察机关指定管辖或者交办案件的，应当将《撤销案件意见书》连同案卷材料，在法定调查期限到期七个工作日前报指定管辖或者交办案件的监察机关审查。对于重大、复杂案件，在法定调查期限到期十个工作日前报指定管辖或者交办案件的监察机关审查。\n指定管辖或者交办案件的监察机关由监督检查部门负责审查工作。指定管辖或者交办案件的监察机关同意撤销案件的，下级监察机关应当作出撤销案件决定，制作《撤销案件决定书》；指定管辖或者交办案件的监察机关不同意撤销案件的，下级监察机关应当执行该决定', 767, '{\"level\": null, \"title\": null, \"chunk_index\": 52}', 'bge-large-zh-v1.5', '2026-09-25 17:04:49');
INSERT INTO `chunk` VALUES ('8386650b-9f01-4045-93ee-8a5a2145b628', 'b25ce095-dfba-4403-acf8-c58eb456ca4c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 143, '所有人、管理人不能证明对防止非法占有尽到高度注意义务的，与非法占有人承担连带责任。\n第一千二百四十三条　未经许可进入高度危险活动区域或者高度危险物存放区域受到损害，管理人能够证明已经采取足够安全措施并尽到充分警示义务的，可以减轻或者不承担责任。\n第一千二百四十四条　承担高度危险责任，法律规定赔偿限额的，依照其规定，但是行为人有故意或者重大过失的除外。\n第九章　饲养动物损害责任\n第一千二百四十五条　饲养的动物造成他人损害的，动物饲养人或者管理人应当承担侵权责任；但是，能够证明损害是因被侵权人故意或者重大过失造成的，可以不承担或者减轻责任。\n第一千二百四十六条　违反管理规定，未对动物采取安全措施造成他人损害的，动物饲养人或者管理人应当承担侵权责任；但是，能够证明损害是因被侵权人故意造成的，可以减轻责任。\n第一千二百四十七条　禁止饲养的烈性犬等危险动物造成他人损害的，动物饲养人或者管理人应当承担侵权责任。\n第一千二百四十八条　动物园的动物造成他人损害的，动物园应当承担侵权责任；但是，能够证明尽到管理职责的，不承担侵权责任。\n第一千二百四十九条　遗弃、逃逸的动物在遗弃、逃逸期间造成他人损害的，由动物原饲养人或者管理人承担侵权责任。\n第一千二百五十条　因第三人的过错致使动物造成他人损害的，被侵权人可以向动物饲养人或者管理人请求赔偿，也可以向第三人请求赔偿。动物饲养人或者管理人赔偿后，有权向第三人追偿。\n第一千二百五十一条　饲养动物应当遵守法律法规，尊重社会公德，不得妨碍他人生活。\n第十章　建筑物和物件损害责任\n第一千二百五十二条　建筑物、构筑物或者其他设施倒塌、塌陷造成他人损害的，由建设单位与施工单位承担连带责任，但是建设单位与施工单位能够证明不存在质量缺陷的除外。建设单位、施工单位赔偿后，有其他责任人的，有权向其他责任人追偿', 771, '{\"level\": null, \"title\": null, \"chunk_index\": 143}', 'bge-large-zh-v1.5', '2026-09-25 17:05:01');
INSERT INTO `chunk` VALUES ('83debf89-6051-4b6d-a2b5-728c2472318c', '821ce1fd-178d-4a7e-ab92-3deff1488ce2', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 85, '第三百七十一条　聚众冲击军事禁区，严重扰乱军事禁区秩序的，对首要分子，处五年以上十年以下有期徒刑；对其他积极参加的，处五年以下有期徒刑、拘役、管制或者剥夺政治权利。\n聚众扰乱军事管理区秩序，情节严重，致使军事管理区工作无法进行，造成严重损失的，对首要分子，处三年以上七年以下有期徒刑；对其他积极参加的，处三年以下有期徒刑、拘役、管制或者剥夺政治权利。\n第三百七十二条　冒充军人招摇撞骗的，处三年以下有期徒刑、拘役、管制或者剥夺政治权利；情节严重的，处三年以上十年以下有期徒刑。\n第三百七十三条　煽动军人逃离部队或者明知是逃离部队的军人而雇用，情节严重的，处三年以下有期徒刑、拘役或者管制。\n第三百七十四条　在征兵工作中徇私舞弊，接送不合格兵员，情节严重的，处三年以下有期徒刑或者拘役；造成特别严重后果的，处三年以上七年以下有期徒刑。\n第三百七十五条　伪造、变造、买卖或者盗窃、抢夺武装部队公文、证件、印章的，处三年以下有期徒刑、拘役、管制或者剥夺政治权利；情节严重的，处三年以上十年以下有期徒刑。\n非法生产、买卖武装部队制式服装，情节严重的，处三年以下有期徒刑、拘役或者管制，并处或者单处罚金。\n伪造、盗窃、买卖或者非法提供、使用武装部队车辆号牌等专用标志，情节严重的，处三年以下有期徒刑、拘役或者管制，并处或者单处罚金；情节特别严重的，处三年以上七年以下有期徒刑，并处罚金。\n单位犯第二款、第三款罪的，对单位判处罚金，并对其直接负责的主管人员和其他直接责任人员，依照各该款的规定处罚。\n第三百七十六条　预备役人员战时拒绝、逃避征召或者军事训练，情节严重的，处三年以下有期徒刑或者拘役。\n公民战时拒绝、逃避服役，情节严重的，处二年以下有期徒刑或者拘役。\n第三百七十七条　战时故意向武装部队提供虚假敌情，造成严重后果的，处三年以上十年以下有期徒刑；造成特别严重后果的，处十年以上有期徒刑或者无期徒刑', 798, '{\"level\": null, \"title\": null, \"chunk_index\": 85}', 'bge-large-zh-v1.5', '2026-09-25 17:04:56');
INSERT INTO `chunk` VALUES ('841fb0db-4e2b-4c20-95a9-8bfbc3485439', '22a2c356-7a68-4455-b657-333e3dba1e1a', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 17, '第三节　国务院\n第八十五条　中华人民共和国国务院，即中央人民政府，是最高国家权力机关的执行机关，是最高国家行政机关。\n第八十六条　国务院由下列人员组成：\n总理，\n副总理若干人，\n国务委员若干人，\n各部部长，\n各委员会主任，\n审计长，\n秘书长。\n国务院实行总理负责制。各部、各委员会实行部长、主任负责制。\n国务院的组织由法律规定。\n第八十七条　国务院每届任期同全国人民代表大会每届任期相同。\n总理、副总理、国务委员连续任职不得超过两届。\n第八十八条　总理领导国务院的工作。副总理、国务委员协助总理工作。\n总理、副总理、国务委员、秘书长组成国务院常务会议。\n总理召集和主持国务院常务会议和国务院全体会议', 299, '{\"level\": null, \"title\": null, \"chunk_index\": 17}', 'bge-large-zh-v1.5', '2026-09-25 17:04:29');
INSERT INTO `chunk` VALUES ('84fe132c-f6aa-407e-a5d1-4c3acbe70116', 'b25ce095-dfba-4403-acf8-c58eb456ca4c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 12, '但是，营利法人依据该决议与善意相对人形成的民事法律关系不受影响。\n第八十六条　营利法人从事经营活动，应当遵守商业道德，维护交易安全，接受政府和社会的监督，承担社会责任。\n第三节　非营利法人\n第八十七条　为公益目的或者其他非营利目的成立，不向出资人、设立人或者会员分配所取得利润的法人，为非营利法人。\n非营利法人包括事业单位、社会团体、基金会、社会服务机构等。\n第八十八条　具备法人条件，为适应经济社会发展需要，提供公益服务设立的事业单位，经依法登记成立，取得事业单位法人资格；依法不需要办理法人登记的，从成立之日起，具有事业单位法人资格。\n第八十九条　事业单位法人设理事会的，除法律另有规定外，理事会为其决策机构。事业单位法人的法定代表人依照法律、行政法规或者法人章程的规定产生。\n第九十条　具备法人条件，基于会员共同意愿，为公益目的或者会员共同利益等非营利目的设立的社会团体，经依法登记成立，取得社会团体法人资格；依法不需要办理法人登记的，从成立之日起，具有社会团体法人资格。\n第九十一条　设立社会团体法人应当依法制定法人章程。\n社会团体法人应当设会员大会或者会员代表大会等权力机构。\n社会团体法人应当设理事会等执行机构。理事长或者会长等负责人按照法人章程的规定担任法定代表人。\n第九十二条　具备法人条件，为公益目的以捐助财产设立的基金会、社会服务机构等，经依法登记成立，取得捐助法人资格。\n依法设立的宗教活动场所，具备法人条件的，可以申请法人登记，取得捐助法人资格。法律、行政法规对宗教活动场所有规定的，依照其规定。\n第九十三条　设立捐助法人应当依法制定法人章程。\n捐助法人应当设理事会、民主管理组织等决策机构，并设执行机构。理事长等负责人按照法人章程的规定担任法定代表人。\n捐助法人应当设监事会等监督机构', 755, '{\"level\": null, \"title\": null, \"chunk_index\": 12}', 'bge-large-zh-v1.5', '2026-09-25 17:05:01');
INSERT INTO `chunk` VALUES ('85dc93b2-5643-49ce-b290-24ac4dd1cb43', '16cbea7e-7e36-4f31-afb5-63892345d29c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 55, '坚持复审复核与调查审理分离，原案调查、审理人员不得参与复审复核。\n第六节　移送审查起诉\n第二百四十三条　监察机关决定对涉嫌职务犯罪的被调查人移送起诉的，应当出具《起诉意见书》，连同案卷材料、证据及到案经过材料等，一并移送同级人民检察院。\n监察机关案件审理部门负责与人民检察院审查起诉的衔接工作，调查、案件监督管理等部门应当予以协助。\n国家监察委员会派驻或者派出的监察机构、监察专员调查的职务犯罪案件，应当依法移送省级人民检察院审查起诉。\n第二百四十四条　涉嫌职务犯罪的被调查人和涉案人员符合监察法第三十四条、第三十五条规定情形的，结合其案发前的一贯表现、违法犯罪行为的情节、后果和影响等因素，监察机关经综合研判和集体审议，报请上一级监察机关批准，可以在移送人民检察院时依法提出从轻、减轻或者免除处罚等从宽处罚建议。报请批准时，应当一并提供主要证据材料、忏悔反思材料。\n上级监察机关相关监督检查部门负责审查工作，重点审核拟认定的从宽处罚情形、提出的从宽处罚建议，经审批在十五个工作日以内作出批复', 446, '{\"level\": null, \"title\": null, \"chunk_index\": 55}', 'bge-large-zh-v1.5', '2026-09-25 17:04:49');
INSERT INTO `chunk` VALUES ('876d95b2-cf89-4219-af94-bf422191d852', '16cbea7e-7e36-4f31-afb5-63892345d29c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 38, '第一百七十一条　调查人员在必要时，可以依法让被害人、证人和被调查人对与违法犯罪有关的物品、文件、尸体或者场所进行辨认；也可以让被害人、证人对被调查人进行辨认，或者让被调查人对涉案人员进行辨认。\n辨认工作应当由二名以上调查人员主持进行。在辨认前，应当向辨认人详细询问辨认对象的具体特征，避免辨认人见到辨认对象，并告知辨认人作虚假辨认应当承担的法律责任。几名辨认人对同一辨认对象进行辨认时，应当由辨认人个别进行。辨认应当形成笔录，并由调查人员、辨认人签名或者盖章。\n第一百七十二条　辨认人员时，被辨认的人数不得少于七人，照片不得少于十张。\n辨认人不愿公开进行辨认时，应当在不暴露辨认人的情况下进行辨认，并为其保守秘密。\n第一百七十三条　组织辨认物品时一般应当辨认实物。被辨认的物品系名贵字画等贵重物品或者存在不便搬运等情况的，可以对实物照片进行辨认。辨认人进行辨认时，应当在辨认出的实物照片与附纸骑缝上捺指印予以确认，在附纸上写明该实物涉案情况并签名、捺指印。\n辨认物品时，同类物品不得少于五件，照片不得少于五张。\n对于难以找到相似物品的特定物，可以将该物品照片交由辨认人进行确认后，在照片与附纸骑缝上捺指印，在附纸上写明该物品涉案情况并签名、捺指印。在辨认人确认前，应当向其详细询问物品的具体特征，并对确认过程和结果形成笔录。\n第一百七十四条　辨认笔录具有下列情形之一的，不得作为认定案件的依据：\n（一）辨认开始前使辨认人见到辨认对象的；\n（二）辨认活动没有个别进行的；\n（三）辨认对象没有混杂在具有类似特征的其他对象中，或者供辨认的对象数量不符合规定的，但特定辨认对象除外；\n（四）辨认中给辨认人明显暗示或者明显有指认嫌疑的；\n（五）辨认不是在调查人员主持下进行的；\n（六）违反有关规定，不能确定辨认笔录真实性的其他情形。\n辨认笔录存在其他瑕疵的，应当结合全案证据审查其真实性和关联性，作出综合判断', 799, '{\"level\": null, \"title\": null, \"chunk_index\": 38}', 'bge-large-zh-v1.5', '2026-09-25 17:04:49');
INSERT INTO `chunk` VALUES ('88033f48-9436-44a7-b887-690bfb02a4f7', '821ce1fd-178d-4a7e-ab92-3deff1488ce2', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 31, '第一百六十六条　国有公司、企业、事业单位的工作人员，利用职务便利，有下列情形之一，使国家利益遭受重大损失的，处三年以下有期徒刑或者拘役，并处或者单处罚金；致使国家利益遭受特别重大损失的，处三年以上七年以下有期徒刑，并处罚金：\n（一）将本单位的盈利业务交由自己的亲友进行经营的；\n（二）以明显高于市场的价格向自己的亲友经营管理的单位采购商品或者以明显低于市场的价格向自己的亲友经营管理的单位销售商品的；\n（三）向自己的亲友经营管理的单位采购不合格商品的。\n第一百六十七条　国有公司、企业、事业单位直接负责的主管人员，在签订、履行合同过程中，因严重不负责任被诈骗，致使国家利益遭受重大损失的，处三年以下有期徒刑或者拘役；致使国家利益遭受特别重大损失的，处三年以上七年以下有期徒刑。\n第一百六十八条　国有公司、企业的工作人员，由于严重不负责任或者滥用职权，造成国有公司、企业破产或者严重损失，致使国家利益遭受重大损失的，处三年以下有期徒刑或者拘役；致使国家利益遭受特别重大损失的，处三年以上七年以下有期徒刑。\n国有事业单位的工作人员有前款行为，致使国家利益遭受重大损失的，依照前款的规定处罚。\n国有公司、企业、事业单位的工作人员，徇私舞弊，犯前两款罪的，依照第一款的规定从重处罚。\n第一百六十九条　国有公司、企业或者其上级主管部门直接负责的主管人员，徇私舞弊，将国有资产低价折股或者低价出售，致使国家利益遭受重大损失的，处三年以下有期徒刑或者拘役；致使国家利益遭受特别重大损失的，处三年以上七年以下有期徒刑', 650, '{\"level\": null, \"title\": null, \"chunk_index\": 31}', 'bge-large-zh-v1.5', '2026-09-25 17:04:56');
INSERT INTO `chunk` VALUES ('883e6c5f-e0d7-4655-8359-0d54f8fe84be', '16cbea7e-7e36-4f31-afb5-63892345d29c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 24, '依照监察法第二十三条第一款第三项规定被责令候查的人员，违反责令候查规定，情节严重，依法应予留置的，省级监察机关应当报请国家监察委员会批准，设区的市级以下监察机关应当逐级报送省级监察机关批准。\n第一百一十条　被管护人员、被留置人员、被禁闭人员及其近亲属向监察机关申请变更为责令候查措施的，应当以书面方式提出。监察机关收到申请后，应当在三日以内作出决定。经审查，符合责令候查条件的，可以将管护、留置或者禁闭措施依法变更为责令候查措施；不符合责令候查条件的，应当告知申请人，并说明不同意的理由。\n第一百一十一条　对被责令候查人员不需要继续采取责令候查措施或者责令候查期满的，应当按规定报批后解除责令候查措施。调查人员应当向被责令候查人员宣布《解除责令候查决定书》，由其签名、捺指印。被责令候查人员拒绝签名、捺指印的，调查人员应当在文书上记明。\n解除责令候查措施的，应当及时通知被责令候查人员所在单位和家属。当面通知的，由有关人员在《解除责令候查通知书》上签名。无法当面通知的，可以先以电话等方式通知，并通过邮寄、转交等方式送达《解除责令候查通知书》，要求有关人员在《解除责令候查通知书》上签名。有关人员拒绝签名的，调查人员应当在文书上记明。\n第一百一十二条　案件依法移送人民检察院审查起诉的，责令候查措施自移送之日自动解除，不再办理解除法律手续。\n第八节　管　　护\n第一百一十三条　监察机关对于符合监察法第二十五条第一款规定的未被留置人员，经依法审批，可以对其采取管护措施。\n第一百一十四条　采取管护措施时，调查人员不得少于二人，应当向被管护人员宣布《管护决定书》，告知被管护人员权利义务，要求其在《管护决定书》上签名、捺指印。被管护人员拒绝签名、捺指印的，调查人员应当在文书上记明。\n第一百一十五条　采取管护措施后，应当立即将被管护人员送留置场所，至迟不得超过二十四小时', 783, '{\"level\": null, \"title\": null, \"chunk_index\": 24}', 'bge-large-zh-v1.5', '2026-09-25 17:04:49');
INSERT INTO `chunk` VALUES ('89e9091d-9472-4f27-8b24-f3401a9d9eeb', '821ce1fd-178d-4a7e-ab92-3deff1488ce2', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 14, '在追诉期限以内又犯罪的，前罪追诉的期限从犯后罪之日起计算。\n第五章　其他规定\n第九十条　民族自治地方不能全部适用本法规定的，可以由自治区或者省的人民代表大会根据当地民族的政治、经济、文化的特点和本法规定的基本原则，制定变通或者补充的规定，报请全国人民代表大会常务委员会批准施行。\n第九十一条　本法所称公共财产，是指下列财产：\n（一）国有财产；\n（二）劳动群众集体所有的财产；\n（三）用于扶贫和其他公益事业的社会捐助或者专项基金的财产。\n在国家机关、国有公司、企业、集体企业和人民团体管理、使用或者运输中的私人财产，以公共财产论。\n第九十二条　本法所称公民私人所有的财产，是指下列财产：\n（一）公民的合法收入、储蓄、房屋和其他生活资料；\n（二）依法归个人、家庭所有的生产资料；\n（三）个体户和私营企业的合法财产；\n（四）依法归个人所有的股份、股票、债券和其他财产。\n第九十三条　本法所称国家工作人员，是指国家机关中从事公务的人员。\n国有公司、企业、事业单位、人民团体中从事公务的人员和国家机关、国有公司、企业、事业单位委派到非国有公司、企业、事业单位、社会团体从事公务的人员，以及其他依照法律从事公务的人员，以国家工作人员论。\n第九十四条　本法所称司法工作人员，是指有侦查、检察、审判、监管职责的工作人员。\n第九十五条　本法所称重伤，是指有下列情形之一的伤害：\n（一）使人肢体残废或者毁人容貌的；\n（二）使人丧失听觉、视觉或者其他器官机能的；\n（三）其他对于人身健康有重大伤害的。\n第九十六条　本法所称违反国家规定，是指违反全国人民代表大会及其常务委员会制定的法律和决定，国务院制定的行政法规、规定的行政措施、发布的决定和命令。\n第九十七条　本法所称首要分子，是指在犯罪集团或者聚众犯罪中起组织、策划、指挥作用的犯罪分子。\n第九十八条　本法所称告诉才处理，是指被害人告诉才处理', 787, '{\"level\": null, \"title\": null, \"chunk_index\": 14}', 'bge-large-zh-v1.5', '2026-09-25 17:04:56');
INSERT INTO `chunk` VALUES ('8b2e2d8f-5257-4d03-94a1-0775edaf4d72', '22a2c356-7a68-4455-b657-333e3dba1e1a', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 2, '社会主义的建设事业必须依靠工人、农民和知识分子，团结一切可以团结的力量。在长期的革命、建设、改革过程中，已经结成由中国共产党领导的，有各民主党派和各人民团体参加的，包括全体社会主义劳动者、社会主义事业的建设者、拥护社会主义的爱国者、拥护祖国统一和致力于中华民族伟大复兴的爱国者的广泛的爱国统一战线，这个统一战线将继续巩固和发展。中国人民政治协商会议是有广泛代表性的统一战线组织，过去发挥了重要的历史作用，今后在国家政治生活、社会生活和对外友好活动中，在进行社会主义现代化建设、维护国家的统一和团结的斗争中，将进一步发挥它的重要作用。中国共产党领导的多党合作和政治协商制度将长期存在和发展。\n中华人民共和国是全国各族人民共同缔造的统一的多民族国家。平等团结互助和谐的社会主义民族关系已经确立，并将继续加强。在维护民族团结的斗争中，要反对大民族主义，主要是大汉族主义，也要反对地方民族主义。国家尽一切努力，促进全国各民族的共同繁荣。\n中国革命、建设、改革的成就是同世界人民的支持分不开的。中国的前途是同世界的前途紧密地联系在一起的。中国坚持独立自主的对外政策，坚持互相尊重主权和领土完整、互不侵犯、互不干涉内政、平等互利、和平共处的五项原则，坚持和平发展道路，坚持互利共赢开放战略，发展同各国的外交关系和经济、文化交流，推动构建人类命运共同体；坚持反对帝国主义、霸权主义、殖民主义，加强同世界各国人民的团结，支持被压迫民族和发展中国家争取和维护民族独立、发展民族经济的正义斗争，为维护世界和平和促进人类进步事业而努力。\n本宪法以法律的形式确认了中国各族人民奋斗的成果，规定了国家的根本制度和根本任务，是国家的根本法，具有最高的法律效力。全国各族人民、一切国家机关和武装力量、各政党和各社会团体、各企业事业组织，都必须以宪法为根本的活动准则，并且负有维护宪法尊严、保证宪法实施的职责', 788, '{\"level\": null, \"title\": null, \"chunk_index\": 2}', 'bge-large-zh-v1.5', '2026-09-25 17:04:28');
INSERT INTO `chunk` VALUES ('8bb67f1a-5c71-4600-be83-7792a97a86e8', 'b25ce095-dfba-4403-acf8-c58eb456ca4c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 140, '第六章　医疗损害责任\n第一千二百一十八条　患者在诊疗活动中受到损害，医疗机构或者其医务人员有过错的，由医疗机构承担赔偿责任。\n第一千二百一十九条　医务人员在诊疗活动中应当向患者说明病情和医疗措施。需要实施手术、特殊检查、特殊治疗的，医务人员应当及时向患者具体说明医疗风险、替代医疗方案等情况，并取得其明确同意；不能或者不宜向患者说明的，应当向患者的近亲属说明，并取得其明确同意。\n医务人员未尽到前款义务，造成患者损害的，医疗机构应当承担赔偿责任。\n第一千二百二十条　因抢救生命垂危的患者等紧急情况，不能取得患者或者其近亲属意见的，经医疗机构负责人或者授权的负责人批准，可以立即实施相应的医疗措施。\n第一千二百二十一条　医务人员在诊疗活动中未尽到与当时的医疗水平相应的诊疗义务，造成患者损害的，医疗机构应当承担赔偿责任。\n第一千二百二十二条　患者在诊疗活动中受到损害，有下列情形之一的，推定医疗机构有过错：\n（一）违反法律、行政法规、规章以及其他有关诊疗规范的规定；\n（二）隐匿或者拒绝提供与纠纷有关的病历资料；\n（三）遗失、伪造、篡改或者违法销毁病历资料。\n第一千二百二十三条　因药品、消毒产品、医疗器械的缺陷，或者输入不合格的血液造成患者损害的，患者可以向药品上市许可持有人、生产者、血液提供机构请求赔偿，也可以向医疗机构请求赔偿。患者向医疗机构请求赔偿的，医疗机构赔偿后，有权向负有责任的药品上市许可持有人、生产者、血液提供机构追偿。\n第一千二百二十四条　患者在诊疗活动中受到损害，有下列情形之一的，医疗机构不承担赔偿责任：\n（一）患者或者其近亲属不配合医疗机构进行符合诊疗规范的诊疗；\n（二）医务人员在抢救生命垂危的患者等紧急情况下已经尽到合理诊疗义务；\n（三）限于当时的医疗水平难以诊疗。\n前款第一项情形中，医疗机构或者其医务人员也有过错的，应当承担相应的赔偿责任', 786, '{\"level\": null, \"title\": null, \"chunk_index\": 140}', 'bge-large-zh-v1.5', '2026-09-25 17:05:01');
INSERT INTO `chunk` VALUES ('8beb4be6-4995-412d-a293-5d57a3a1a49f', '16cbea7e-7e36-4f31-afb5-63892345d29c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 61, '认为原政务处分决定认定事实清楚、适用法律正确的，不再改变；认为原政务处分决定确有错误或者不当的，依法予以撤销或者变更。\n第二百六十三条　对于贪污贿赂、失职渎职等职务犯罪案件，被调查人逃匿，在通缉一年后不能到案，或者被调查人死亡，依法应当追缴其违法所得及其他涉案财产的，承办部门在调查终结后应当依法移送审理。\n监察机关应当经集体审议，出具《没收违法所得意见书》，连同案卷材料、证据等，一并移送人民检察院依法提出没收违法所得的申请。\n监察机关将《没收违法所得意见书》移送人民检察院后，在逃的被调查人自动投案或者被抓获的，监察机关应当及时通知人民检察院。\n第二百六十四条　监察机关立案调查拟适用缺席审判程序的贪污贿赂犯罪案件，应当逐级报送国家监察委员会同意。\n监察机关承办部门认为在境外的被调查人犯罪事实已经查清，证据确实、充分，依法应当追究刑事责任的，应当依法移送审理。\n监察机关应当经集体审议，出具《起诉意见书》，连同案卷材料、证据等，一并移送人民检察院审查起诉。\n在审查起诉或者缺席审判过程中，犯罪嫌疑人、被告人向监察机关自动投案或者被抓获的，监察机关应当立即通知人民检察院、人民法院。\n第六章　反腐败国际合作\n第一节　工作职责和领导体制\n第二百六十五条　国家监察委员会统筹协调与其他国家、地区、国际组织开展反腐败国际交流、合作。\n国家监察委员会组织《联合国反腐败公约》等反腐败国际条约的实施以及履约审议等工作，承担《联合国反腐败公约》司法协助中央机关有关工作', 630, '{\"level\": null, \"title\": null, \"chunk_index\": 61}', 'bge-large-zh-v1.5', '2026-09-25 17:04:49');
INSERT INTO `chunk` VALUES ('8f7a2557-f053-46c0-8710-d7f552836acf', '16cbea7e-7e36-4f31-afb5-63892345d29c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 54, '第二百四十条　监察机关经调查，对违法取得的财物及孳息决定追缴或者责令退赔的，可以依法要求公安、自然资源、住房城乡建设、市场监管、金融监管等部门以及银行等机构、单位予以协助。\n追缴涉案财物以追缴原物为原则，原物已经转化为其他财物的，应当追缴转化后的财物。涉案财物已被用于清偿合法债务、转让或者设置其他权利负担，善意第三人通过正常市场交易、支付合理对价，并实际取得相应权利的，不得对善意取得的财物进行追缴。\n有证据证明依法应当追缴、没收的涉案财物无法找到、被他人善意取得、价值灭失减损或者与其他合法财产混合且不可分割的，可以依法追缴、没收被调查人的其他等值财产。\n追缴或者责令退赔应当自处置决定作出之日起一个月以内执行完毕。因被调查人的原因逾期执行的除外。\n人民检察院、人民法院依法将不认定为犯罪所得的相关涉案财物退回监察机关的，监察机关应当依法处理。\n第二百四十一条　监察对象对监察机关作出的涉及本人的处理决定不服的，可以在收到处理决定之日起一个月以内，向作出决定的监察机关申请复审。复审机关应当依法受理，并在受理后一个月以内作出复审决定。监察对象对复审决定仍不服的，可以在收到复审决定之日起一个月以内，向上一级监察机关申请复核。复核机关应当依法受理，并在受理后二个月以内作出复核决定。\n上一级监察机关的复核决定和国家监察委员会的复审、复核决定为最终决定。\n第二百四十二条　复审、复核机关承办部门应当成立工作组，调阅原案卷宗，必要时可以进行调查取证。承办部门应当集体研究，提出办理意见，经审批作出复审、复核决定。决定应当送达申请人，抄送相关单位，并在一定范围内宣布。\n复审、复核期间，不停止原处理决定的执行。复审、复核机关经审查认定处理决定有错误或者不当的，应当依法撤销、变更原处理决定，或者责令原处理机关及时予以纠正。复审、复核机关经审查认定处理决定事实清楚、适用法律正确的，应当予以维持', 794, '{\"level\": null, \"title\": null, \"chunk_index\": 54}', 'bge-large-zh-v1.5', '2026-09-25 17:04:49');
INSERT INTO `chunk` VALUES ('90119f00-0b0e-449a-b424-df2efe1576db', '16cbea7e-7e36-4f31-afb5-63892345d29c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 33, '调取物证的照片、录像和书证、视听资料的副本、复制件的，应当书面记明不能调取原物、原件的原因，原物、原件存放地点，制作过程，是否与原物、原件相符，并由调查人员和物证、书证、视听资料原持有人签名或者盖章。持有人无法签名、盖章或者拒绝签名、盖章的，应当在笔录中记明，由见证人签名。\n第一百五十二条　调取外文材料作为证据使用的，应当交由具有资质的机构和人员出具中文译本。中文译本应当加盖翻译机构公章。\n第一百五十三条　收集、提取电子数据，能够扣押原始存储介质的，应当予以扣押、封存并在笔录中记录封存状态。无法扣押原始存储介质的，可以采取调取、勘验检查措施，通过现场或者网络远程收集、提取电子数据，但应当在笔录中记明不能扣押的原因、原始存储介质的存放地点或者电子数据的来源等情况。\n由于客观原因无法或者不宜采取前款规定方式收集、提取电子数据的，可以采取打印、拍照或者录像等方式固定相关证据，并在笔录中说明原因。\n收集、提取的电子数据，足以保证完整性，无删除、修改、增加等情形的，可以作为证据使用。\n收集、提取电子数据，应当制作笔录，记录案由、对象、内容，收集、提取电子数据的时间、地点、方法、过程，并附电子数据清单，注明类别、文件格式、完整性校验值等，由调查人员、电子数据持有人（提供人）签名或者盖章；电子数据持有人（提供人）无法签名或者拒绝签名的，应当在笔录中记明，由见证人签名或者盖章。有条件的，应当对相关活动进行录像。\n第一百五十四条　调取的物证、书证、视听资料等原件，经查明与案件无关的，经审批，应当在查明后三日以内退还，并办理交接手续。\n第十三节　查封、扣押\n第一百五十五条　监察机关按规定报批后，可以依法查封、扣押用以证明被调查人涉嫌违法犯罪以及情节轻重的财物、文件、电子数据等证据材料', 744, '{\"level\": null, \"title\": null, \"chunk_index\": 33}', 'bge-large-zh-v1.5', '2026-09-25 17:04:49');
INSERT INTO `chunk` VALUES ('9013c183-467d-4c9b-8706-ddc8beeb0f1b', 'b25ce095-dfba-4403-acf8-c58eb456ca4c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 76, '第六百六十六条　赠与人的经济状况显著恶化，严重影响其生产经营或者家庭生活的，可以不再履行赠与义务。\n第十二章　借款合同\n第六百六十七条　借款合同是借款人向贷款人借款，到期返还借款并支付利息的合同。\n第六百六十八条　借款合同应当采用书面形式，但是自然人之间借款另有约定的除外。\n借款合同的内容一般包括借款种类、币种、用途、数额、利率、期限和还款方式等条款。\n第六百六十九条　订立借款合同，借款人应当按照贷款人的要求提供与借款有关的业务活动和财务状况的真实情况。\n第六百七十条　借款的利息不得预先在本金中扣除。利息预先在本金中扣除的，应当按照实际借款数额返还借款并计算利息。\n第六百七十一条　贷款人未按照约定的日期、数额提供借款，造成借款人损失的，应当赔偿损失。\n借款人未按照约定的日期、数额收取借款的，应当按照约定的日期、数额支付利息。\n第六百七十二条　贷款人按照约定可以检查、监督借款的使用情况。借款人应当按照约定向贷款人定期提供有关财务会计报表或者其他资料。\n第六百七十三条　借款人未按照约定的借款用途使用借款的，贷款人可以停止发放借款、提前收回借款或者解除合同。\n第六百七十四条　借款人应当按照约定的期限支付利息。对支付利息的期限没有约定或者约定不明确，依据本法第五百一十条的规定仍不能确定，借款期间不满一年的，应当在返还借款时一并支付；借款期间一年以上的，应当在每届满一年时支付，剩余期间不满一年的，应当在返还借款时一并支付。\n第六百七十五条　借款人应当按照约定的期限返还借款。对借款期限没有约定或者约定不明确，依据本法第五百一十条的规定仍不能确定的，借款人可以随时返还；贷款人可以催告借款人在合理期限内返还。\n第六百七十六条　借款人未按照约定的期限返还借款的，应当按照约定或者国家有关规定支付逾期利息。\n第六百七十七条　借款人提前返还借款的，除当事人另有约定外，应当按照实际借款的期间计算利息', 800, '{\"level\": null, \"title\": null, \"chunk_index\": 76}', 'bge-large-zh-v1.5', '2026-09-25 17:05:01');
INSERT INTO `chunk` VALUES ('9025580b-a0f1-4479-b4cf-93174054b778', '0497a5e7-7044-4b18-8fed-af3fb7bc7890', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 9, '第六章　附　　则\n第五十四条　本条例自2026年1月1日起施行。', 32, '{\"level\": null, \"title\": null, \"chunk_index\": 9}', 'bge-large-zh-v1.5', '2026-09-25 17:04:28');
INSERT INTO `chunk` VALUES ('918e77a1-c94b-44e9-9943-5a2177c99580', 'b25ce095-dfba-4403-acf8-c58eb456ca4c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 56, '第五百零一条　当事人在订立合同过程中知悉的商业秘密或者其他应当保密的信息，无论合同是否成立，不得泄露或者不正当地使用；泄露、不正当地使用该商业秘密或者信息，造成对方损失的，应当承担赔偿责任。\n第三章　合同的效力\n第五百零二条　依法成立的合同，自成立时生效，但是法律另有规定或者当事人另有约定的除外。\n依照法律、行政法规的规定，合同应当办理批准等手续的，依照其规定。未办理批准等手续影响合同生效的，不影响合同中履行报批等义务条款以及相关条款的效力。应当办理申请批准等手续的当事人未履行义务的，对方可以请求其承担违反该义务的责任。\n依照法律、行政法规的规定，合同的变更、转让、解除等情形应当办理批准等手续的，适用前款规定。\n第五百零三条　无权代理人以被代理人的名义订立合同，被代理人已经开始履行合同义务或者接受相对人履行的，视为对合同的追认。\n第五百零四条　法人的法定代表人或者非法人组织的负责人超越权限订立的合同，除相对人知道或者应当知道其超越权限外，该代表行为有效，订立的合同对法人或者非法人组织发生效力。\n第五百零五条　当事人超越经营范围订立的合同的效力，应当依照本法第一编第六章第三节和本编的有关规定确定，不得仅以超越经营范围确认合同无效。\n第五百零六条　合同中的下列免责条款无效：\n（一）造成对方人身损害的；\n（二）因故意或者重大过失造成对方财产损失的。\n第五百零七条　合同不生效、无效、被撤销或者终止的，不影响合同中有关解决争议方法的条款的效力。\n第五百零八条　本编对合同的效力没有规定的，适用本法第一编第六章的有关规定。\n第四章　合同的履行\n第五百零九条　当事人应当按照约定全面履行自己的义务。\n当事人应当遵循诚信原则，根据合同的性质、目的和交易习惯履行通知、协助、保密等义务。\n当事人在履行合同过程中，应当避免浪费资源、污染环境和破坏生态', 775, '{\"level\": null, \"title\": null, \"chunk_index\": 56}', 'bge-large-zh-v1.5', '2026-09-25 17:05:01');
INSERT INTO `chunk` VALUES ('919db404-ddfe-4ba9-8364-1faf0b7ddb6f', 'b25ce095-dfba-4403-acf8-c58eb456ca4c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 94, '收货人在约定的期限或者合理期限内对货物的数量、毁损等未提出异议的，视为承运人已经按照运输单证的记载交付的初步证据。\n第八百三十二条　承运人对运输过程中货物的毁损、灭失承担赔偿责任。但是，承运人证明货物的毁损、灭失是因不可抗力、货物本身的自然性质或者合理损耗以及托运人、收货人的过错造成的，不承担赔偿责任。\n第八百三十三条　货物的毁损、灭失的赔偿额，当事人有约定的，按照其约定；没有约定或者约定不明确，依据本法第五百一十条的规定仍不能确定的，按照交付或者应当交付时货物到达地的市场价格计算。法律、行政法规对赔偿额的计算方法和赔偿限额另有规定的，依照其规定。\n第八百三十四条　两个以上承运人以同一运输方式联运的，与托运人订立合同的承运人应当对全程运输承担责任；损失发生在某一运输区段的，与托运人订立合同的承运人和该区段的承运人承担连带责任。\n第八百三十五条　货物在运输过程中因不可抗力灭失，未收取运费的，承运人不得请求支付运费；已经收取运费的，托运人可以请求返还。法律另有规定的，依照其规定。\n第八百三十六条　托运人或者收货人不支付运费、保管费或者其他费用的，承运人对相应的运输货物享有留置权，但是当事人另有约定的除外。\n第八百三十七条　收货人不明或者收货人无正当理由拒绝受领货物的，承运人依法可以提存货物。\n第四节　多式联运合同\n第八百三十八条　多式联运经营人负责履行或者组织履行多式联运合同，对全程运输享有承运人的权利，承担承运人的义务。\n第八百三十九条　多式联运经营人可以与参加多式联运的各区段承运人就多式联运合同的各区段运输约定相互之间的责任；但是，该约定不影响多式联运经营人对全程运输承担的义务。\n第八百四十条　多式联运经营人收到托运人交付的货物时，应当签发多式联运单据。按照托运人的要求，多式联运单据可以是可转让单据，也可以是不可转让单据', 773, '{\"level\": null, \"title\": null, \"chunk_index\": 94}', 'bge-large-zh-v1.5', '2026-09-25 17:05:01');
INSERT INTO `chunk` VALUES ('91b7a457-13b3-4a72-8c6c-0ba0abe2a6c2', '821ce1fd-178d-4a7e-ab92-3deff1488ce2', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 94, '第四百一十四条　对生产、销售伪劣商品犯罪行为负有追究责任的国家机关工作人员，徇私舞弊，不履行法律规定的追究职责，情节严重的，处五年以下有期徒刑或者拘役。\n第四百一十五条　负责办理护照、签证以及其他出入境证件的国家机关工作人员，对明知是企图偷越国（边）境的人员，予以办理出入境证件的，或者边防、海关等国家机关工作人员，对明知是偷越国（边）境的人员，予以放行的，处三年以下有期徒刑或者拘役；情节严重的，处三年以上七年以下有期徒刑。\n第四百一十六条　对被拐卖、绑架的妇女、儿童负有解救职责的国家机关工作人员，接到被拐卖、绑架的妇女、儿童及其家属的解救要求或者接到其他人的举报，而对被拐卖、绑架的妇女、儿童不进行解救，造成严重后果的，处五年以下有期徒刑或者拘役。\n负有解救职责的国家机关工作人员利用职务阻碍解救的，处二年以上七年以下有期徒刑；情节较轻的，处二年以下有期徒刑或者拘役。\n第四百一十七条　有查禁犯罪活动职责的国家机关工作人员，向犯罪分子通风报信、提供便利，帮助犯罪分子逃避处罚的，处三年以下有期徒刑或者拘役；情节严重的，处三年以上十年以下有期徒刑。\n第四百一十八条　国家机关工作人员在招收公务员、学生工作中徇私舞弊，情节严重的，处三年以下有期徒刑或者拘役。\n第四百一十九条　国家机关工作人员严重不负责任，造成珍贵文物损毁或者流失，后果严重的，处三年以下有期徒刑或者拘役。\n第十章　军人违反职责罪\n第四百二十条　军人违反职责，危害国家军事利益，依照法律应当受刑罚处罚的行为，是军人违反职责罪。\n第四百二十一条　战时违抗命令，对作战造成危害的，处三年以上十年以下有期徒刑；致使战斗、战役遭受重大损失的，处十年以上有期徒刑、无期徒刑或者死刑', 719, '{\"level\": null, \"title\": null, \"chunk_index\": 94}', 'bge-large-zh-v1.5', '2026-09-25 17:04:56');
INSERT INTO `chunk` VALUES ('92a97cdb-f980-4382-a5f5-dfb59beede43', 'd9d7dc15-8041-43b8-9f75-f112fe3ae003', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 31, '未依照本法规定将剧毒化学品以及危险化学品重大危险源的情况报应急管理部门、港口行政管理部门或者消防救援机构备案的，分别由应急管理部门、港口行政管理部门或者消防救援机构依照本条第一款的规定予以处理、处罚。\n第一百零五条　生产、储存、使用危险化学品的单位转产、停产、停业或者解散，未采取有效措施及时、妥善处置其危险化学品生产装置、储存设施以及库存的危险化学品，或者丢弃危险化学品的，由应急管理部门责令限期改正，处十万元以上五十万元以下的罚款。\n生产、储存、使用危险化学品的单位转产、停产、停业或者解散，未依照本法规定将其危险化学品生产装置、储存设施以及库存危险化学品的处置方案报有关部门备案的，分别由有关部门责令限期改正，可以处二万元以上十万元以下的罚款；逾期不改正的，处十万元以上二十万元以下的罚款。\n第一百零六条　危险化学品经营企业向未经许可违法从事危险化学品生产、经营活动的企业采购危险化学品的，由应急管理部门责令限期改正，处二十万元以上五十万元以下的罚款；逾期不改正的，责令停业整顿直至由原发证机关吊销其危险化学品经营许可证，对其直接负责的主管人员和其他直接责任人员处五万元以上十万元以下的罚款；相关许可证件被吊销的，由市场监督管理部门责令其办理经营范围变更登记或者吊销其营业执照', 541, '{\"level\": null, \"title\": null, \"chunk_index\": 31}', 'bge-large-zh-v1.5', '2026-09-25 17:04:46');
INSERT INTO `chunk` VALUES ('93c1594e-f63b-4f75-a86b-2958dacb858d', '22a2c356-7a68-4455-b657-333e3dba1e1a', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 12, '第六十五条　全国人民代表大会常务委员会由下列人员组成：\n委员长，\n副委员长若干人，\n秘书长，\n委员若干人。\n全国人民代表大会常务委员会组成人员中，应当有适当名额的少数民族代表。\n全国人民代表大会选举并有权罢免全国人民代表大会常务委员会的组成人员。\n全国人民代表大会常务委员会的组成人员不得担任国家行政机关、监察机关、审判机关和检察机关的职务。\n第六十六条　全国人民代表大会常务委员会每届任期同全国人民代表大会每届任期相同，它行使职权到下届全国人民代表大会选出新的常务委员会为止。\n委员长、副委员长连续任职不得超过两届', 258, '{\"level\": null, \"title\": null, \"chunk_index\": 12}', 'bge-large-zh-v1.5', '2026-09-25 17:04:28');
INSERT INTO `chunk` VALUES ('93c16640-c490-4e44-a1ac-db5a11bb1bf6', '16cbea7e-7e36-4f31-afb5-63892345d29c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 41, '第一百八十六条　对于采取技术调查措施收集的信息和材料，依法需要作为刑事诉讼证据使用的，监察机关应当按规定报批，出具《调取技术调查证据材料通知书》向有关执行机关调取。\n对于采取技术调查措施收集的物证、书证及其他证据材料，监察机关应当制作书面说明，写明获取证据的时间、地点、数量、特征以及采取技术调查措施的批准机关、种类等。调查人员应当在书面说明上签名。\n对于采取技术调查措施获取的证据材料，如果使用该证据材料可能危及有关人员的人身安全，或者可能产生其他严重后果的，应当采取不暴露有关人员身份、技术方法等保护措施。必要时，可以建议由审判人员在庭外进行核实。\n第一百八十七条　调查人员对采取技术调查措施过程中知悉的国家秘密、工作秘密、商业秘密、个人隐私和个人信息，应当严格保密。\n采取技术调查措施获取的证据、线索及其他有关材料，只能用于对违法犯罪的调查、起诉和审判，不得用于其他用途。\n对采取技术调查措施获取的与案件无关的材料，应当经审批及时销毁。对销毁情况应当制作记录，由调查人员签名。\n第十七节　通　　缉\n第一百八十八条　县级以上监察机关对在逃的应当被留置人员，依法决定在本行政区域内通缉的，应当按规定报批，送交同级公安机关执行。送交执行时，应当出具《通缉决定书》，附《留置决定书》等法律文书和被通缉人员信息，以及承办单位、承办人员等有关情况。\n通缉范围超出本行政区域的，应当报有决定权的上级监察机关出具《通缉决定书》，并附《留置决定书》及相关材料，送交同级公安机关执行。\n第一百八十九条　国家监察委员会依法需要提请公安部对在逃人员发布公安部通缉令的，应当先提请公安部采取网上追逃措施。如情况紧急，可以向公安部同时出具《通缉决定书》和《提请采取网上追逃措施函》。\n省级以下监察机关报请国家监察委员会提请公安部发布公安部通缉令的，应当先提请本地公安机关采取网上追逃措施', 782, '{\"level\": null, \"title\": null, \"chunk_index\": 41}', 'bge-large-zh-v1.5', '2026-09-25 17:04:49');
INSERT INTO `chunk` VALUES ('9482aa18-eb3a-45ec-9ab5-d80e64ca8d85', '821ce1fd-178d-4a7e-ab92-3deff1488ce2', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 3, '第十二条　中华人民共和国成立以后本法施行以前的行为，如果当时的法律不认为是犯罪的，适用当时的法律；如果当时的法律认为是犯罪的，依照本法总则第四章第八节的规定应当追诉的，按照当时的法律追究刑事责任，但是如果本法不认为是犯罪或者处刑较轻的，适用本法。\n本法施行以前，依照当时的法律已经作出的生效判决，继续有效。\n第二章　犯　　罪\n第一节　犯罪和刑事责任\n第十三条　一切危害国家主权、领土完整和安全，分裂国家、颠覆人民民主专政的政权和推翻社会主义制度，破坏社会秩序和经济秩序，侵犯国有财产或者劳动群众集体所有的财产，侵犯公民私人所有的财产，侵犯公民的人身权利、民主权利和其他权利，以及其他危害社会的行为，依照法律应当受刑罚处罚的，都是犯罪，但是情节显著轻微危害不大的，不认为是犯罪。\n第十四条　明知自己的行为会发生危害社会的结果，并且希望或者放任这种结果发生，因而构成犯罪的，是故意犯罪。\n故意犯罪，应当负刑事责任。\n第十五条　应当预见自己的行为可能发生危害社会的结果，因为疏忽大意而没有预见，或者已经预见而轻信能够避免，以致发生这种结果的，是过失犯罪。\n过失犯罪，法律有规定的才负刑事责任。\n第十六条　行为在客观上虽然造成了损害结果，但是不是出于故意或者过失，而是由于不能抗拒或者不能预见的原因所引起的，不是犯罪。\n第十七条　已满十六周岁的人犯罪，应当负刑事责任。\n已满十四周岁不满十六周岁的人，犯故意杀人、故意伤害致人重伤或者死亡、强奸、抢劫、贩卖毒品、放火、爆炸、投放危险物质罪的，应当负刑事责任。\n已满十二周岁不满十四周岁的人，犯故意杀人、故意伤害罪，致人死亡或者以特别残忍手段致人重伤造成严重残疾，情节恶劣，经最高人民检察院核准追诉的，应当负刑事责任。\n对依照前三款规定追究刑事责任的不满十八周岁的人，应当从轻或者减轻处罚', 763, '{\"level\": null, \"title\": null, \"chunk_index\": 3}', 'bge-large-zh-v1.5', '2026-09-25 17:04:56');
INSERT INTO `chunk` VALUES ('94d315da-2277-4c7f-b291-83b830f68455', '16cbea7e-7e36-4f31-afb5-63892345d29c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 26, '不得因办理交接手续延迟解除或者变更管护措施。\n第一百二十条　在管护期满前，将管护措施变更为留置措施的，按照本条例关于采取留置措施的规定执行。\n第九节　留　　置\n第一百二十一条　监察机关调查严重职务违法或者职务犯罪，对于符合监察法第二十四条第一款规定的，经依法审批，可以对被调查人采取留置措施。\n监察法第二十四条第一款规定的已经掌握其部分违法犯罪事实及证据，是指同时具备下列情形：\n（一）有证据证明发生了违法犯罪事实；\n（二）有证据证明该违法犯罪事实是被调查人实施；\n（三）证明被调查人实施违法犯罪行为的证据已经查证属实。\n部分违法犯罪事实，既可以是单一违法犯罪行为的事实，也可以是数个违法犯罪行为中任何一个违法犯罪行为的事实。\n监察法第二十四条第一款规定的重要问题，是指对被调查人涉嫌的严重职务违法或者职务犯罪，在定性处置、定罪量刑等方面有重要影响的事实、情节及证据。\n第一百二十二条　被调查人具有下列情形之一的，可以认定为监察法第二十四条第一款第二项所规定的可能逃跑、自杀：\n（一）着手准备自杀、自残或者逃跑的；\n（二）曾经有自杀、自残或者逃跑行为的；\n（三）有自杀、自残或者逃跑意图的；\n（四）其他可能逃跑、自杀的情形。\n第一百二十三条　被调查人具有下列情形之一的，可以认定为监察法第二十四条第一款第三项所规定的可能串供或者伪造、隐匿、毁灭证据：\n（一）曾经或者企图串供，伪造、隐匿、毁灭、转移证据的；\n（二）曾经或者企图威逼、恐吓、利诱、收买证人，干扰证人作证的；\n（三）有同案人或者与被调查人存在密切关联违法犯罪的涉案人员在逃，重要证据尚未收集完成的；\n（四）其他可能串供或者伪造、隐匿、毁灭证据的情形', 705, '{\"level\": null, \"title\": null, \"chunk_index\": 26}', 'bge-large-zh-v1.5', '2026-09-25 17:04:49');
INSERT INTO `chunk` VALUES ('94d609e3-2477-430a-8701-04bec9919fc6', '22a2c356-7a68-4455-b657-333e3dba1e1a', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 14, '（二十一）决定全国或者个别省、自治区、直辖市进入紧急状态；\n（二十二）全国人民代表大会授予的其他职权', 50, '{\"level\": null, \"title\": null, \"chunk_index\": 14}', 'bge-large-zh-v1.5', '2026-09-25 17:04:29');
INSERT INTO `chunk` VALUES ('95438354-9825-4bdd-83cf-810abc9b58c4', 'b25ce095-dfba-4403-acf8-c58eb456ca4c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 33, '第二百八十七条　业主对建设单位、物业服务企业或者其他管理人以及其他业主侵害自己合法权益的行为，有权请求其承担民事责任。\n第七章　相邻关系\n第二百八十八条　不动产的相邻权利人应当按照有利生产、方便生活、团结互助、公平合理的原则，正确处理相邻关系。\n第二百八十九条　法律、法规对处理相邻关系有规定的，依照其规定；法律、法规没有规定的，可以按照当地习惯。\n第二百九十条　不动产权利人应当为相邻权利人用水、排水提供必要的便利。\n对自然流水的利用，应当在不动产的相邻权利人之间合理分配。对自然流水的排放，应当尊重自然流向。\n第二百九十一条　不动产权利人对相邻权利人因通行等必须利用其土地的，应当提供必要的便利。\n第二百九十二条　不动产权利人因建造、修缮建筑物以及铺设电线、电缆、水管、暖气和燃气管线等必须利用相邻土地、建筑物的，该土地、建筑物的权利人应当提供必要的便利。\n第二百九十三条　建造建筑物，不得违反国家有关工程建设标准，不得妨碍相邻建筑物的通风、采光和日照。\n第二百九十四条　不动产权利人不得违反国家规定弃置固体废物，排放大气污染物、水污染物、土壤污染物、噪声、光辐射、电磁辐射等有害物质。\n第二百九十五条　不动产权利人挖掘土地、建造建筑物、铺设管线以及安装设备等，不得危及相邻不动产的安全。\n第二百九十六条　不动产权利人因用水、排水、通行、铺设管线等利用相邻不动产的，应当尽量避免对相邻的不动产权利人造成损害。\n第八章　共　　有\n第二百九十七条　不动产或者动产可以由两个以上组织、个人共有。共有包括按份共有和共同共有。\n第二百九十八条　按份共有人对共有的不动产或者动产按照其份额享有所有权。\n第二百九十九条　共同共有人对共有的不动产或者动产共同享有所有权。\n第三百条　共有人按照约定管理共有的不动产或者动产；没有约定或者约定不明确的，各共有人都有管理的权利和义务', 782, '{\"level\": null, \"title\": null, \"chunk_index\": 33}', 'bge-large-zh-v1.5', '2026-09-25 17:05:01');
INSERT INTO `chunk` VALUES ('960b10ec-3cbc-4473-ad98-3e6507446a69', 'b25ce095-dfba-4403-acf8-c58eb456ca4c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 90, '发包人与监理人的权利和义务以及法律责任，应当依照本编委托合同以及其他有关法律、行政法规的规定。\n第七百九十七条　发包人在不妨碍承包人正常作业的情况下，可以随时对作业进度、质量进行检查。\n第七百九十八条　隐蔽工程在隐蔽以前，承包人应当通知发包人检查。发包人没有及时检查的，承包人可以顺延工程日期，并有权请求赔偿停工、窝工等损失。\n第七百九十九条　建设工程竣工后，发包人应当根据施工图纸及说明书、国家颁发的施工验收规范和质量检验标准及时进行验收。验收合格的，发包人应当按照约定支付价款，并接收该建设工程。\n建设工程竣工经验收合格后，方可交付使用；未经验收或者验收不合格的，不得交付使用。\n第八百条　勘察、设计的质量不符合要求或者未按照期限提交勘察、设计文件拖延工期，造成发包人损失的，勘察人、设计人应当继续完善勘察、设计，减收或者免收勘察、设计费并赔偿损失。\n第八百零一条　因施工人的原因致使建设工程质量不符合约定的，发包人有权请求施工人在合理期限内无偿修理或者返工、改建。经过修理或者返工、改建后，造成逾期交付的，施工人应当承担违约责任。\n第八百零二条　因承包人的原因致使建设工程在合理使用期限内造成人身损害和财产损失的，承包人应当承担赔偿责任。\n第八百零三条　发包人未按照约定的时间和要求提供原材料、设备、场地、资金、技术资料的，承包人可以顺延工程日期，并有权请求赔偿停工、窝工等损失。\n第八百零四条　因发包人的原因致使工程中途停建、缓建的，发包人应当采取措施弥补或者减少损失，赔偿承包人因此造成的停工、窝工、倒运、机械设备调迁、材料和构件积压等损失和实际费用。\n第八百零五条　因发包人变更计划，提供的资料不准确，或者未按照期限提供必需的勘察、设计工作条件而造成勘察、设计的返工、停工或者修改设计，发包人应当按照勘察人、设计人实际消耗的工作量增付费用', 775, '{\"level\": null, \"title\": null, \"chunk_index\": 90}', 'bge-large-zh-v1.5', '2026-09-25 17:05:01');
INSERT INTO `chunk` VALUES ('9665df9d-5700-4902-82aa-0fcdff9ce080', '821ce1fd-178d-4a7e-ab92-3deff1488ce2', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 53, '第二百三十六条之一　对已满十四周岁不满十六周岁的未成年女性负有监护、收养、看护、教育、医疗等特殊职责的人员，与该未成年女性发生性关系的，处三年以下有期徒刑；情节恶劣的，处三年以上十年以下有期徒刑。\n有前款行为，同时又构成本法第二百三十六条规定之罪的，依照处罚较重的规定定罪处罚。\n第二百三十七条　以暴力、胁迫或者其他方法强制猥亵他人或者侮辱妇女的，处五年以下有期徒刑或者拘役。\n聚众或者在公共场所当众犯前款罪的，或者有其他恶劣情节的，处五年以上有期徒刑。\n猥亵儿童的，处五年以下有期徒刑；有下列情形之一的，处五年以上有期徒刑：\n（一）猥亵儿童多人或者多次的；\n（二）聚众猥亵儿童的，或者在公共场所当众猥亵儿童，情节恶劣的；\n（三）造成儿童伤害或者其他严重后果的；\n（四）猥亵手段恶劣或者有其他恶劣情节的。\n第二百三十八条　非法拘禁他人或者以其他方法非法剥夺他人人身自由的，处三年以下有期徒刑、拘役、管制或者剥夺政治权利。具有殴打、侮辱情节的，从重处罚。\n犯前款罪，致人重伤的，处三年以上十年以下有期徒刑；致人死亡的，处十年以上有期徒刑。使用暴力致人伤残、死亡的，依照本法第二百三十四条、第二百三十二条的规定定罪处罚。\n为索取债务非法扣押、拘禁他人的，依照前两款的规定处罚。\n国家机关工作人员利用职权犯前三款罪的，依照前三款的规定从重处罚。\n第二百三十九条　以勒索财物为目的绑架他人的，或者绑架他人作为人质的，处十年以上有期徒刑或者无期徒刑，并处罚金或者没收财产；情节较轻的，处五年以上十年以下有期徒刑，并处罚金。\n犯前款罪，杀害被绑架人的，或者故意伤害被绑架人，致人重伤、死亡的，处无期徒刑或者死刑，并处没收财产。\n以勒索财物为目的偷盗婴幼儿的，依照前两款的规定处罚', 733, '{\"level\": null, \"title\": null, \"chunk_index\": 53}', 'bge-large-zh-v1.5', '2026-09-25 17:04:56');
INSERT INTO `chunk` VALUES ('972b8d6d-794b-494a-871e-8b49e21fff94', 'b25ce095-dfba-4403-acf8-c58eb456ca4c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 138, '第四章　产品责任\n第一千二百零二条　因产品存在缺陷造成他人损害的，生产者应当承担侵权责任。\n第一千二百零三条　因产品存在缺陷造成他人损害的，被侵权人可以向产品的生产者请求赔偿，也可以向产品的销售者请求赔偿。\n产品缺陷由生产者造成的，销售者赔偿后，有权向生产者追偿。因销售者的过错使产品存在缺陷的，生产者赔偿后，有权向销售者追偿。\n第一千二百零四条　因运输者、仓储者等第三人的过错使产品存在缺陷，造成他人损害的，产品的生产者、销售者赔偿后，有权向第三人追偿。\n第一千二百零五条　因产品缺陷危及他人人身、财产安全的，被侵权人有权请求生产者、销售者承担停止侵害、排除妨碍、消除危险等侵权责任。\n第一千二百零六条　产品投入流通后发现存在缺陷的，生产者、销售者应当及时采取停止销售、警示、召回等补救措施；未及时采取补救措施或者补救措施不力造成损害扩大的，对扩大的损害也应当承担侵权责任。\n依据前款规定采取召回措施的，生产者、销售者应当负担被侵权人因此支出的必要费用。\n第一千二百零七条　明知产品存在缺陷仍然生产、销售，或者没有依据前条规定采取有效补救措施，造成他人死亡或者健康严重损害的，被侵权人有权请求相应的惩罚性赔偿。\n第五章　机动车交通事故责任\n第一千二百零八条　机动车发生交通事故造成损害的，依照道路交通安全法律和本法的有关规定承担赔偿责任。\n第一千二百零九条　因租赁、借用等情形机动车所有人、管理人与使用人不是同一人时，发生交通事故造成损害，属于该机动车一方责任的，由机动车使用人承担赔偿责任；机动车所有人、管理人对损害的发生有过错的，承担相应的赔偿责任。\n第一千二百一十条　当事人之间已经以买卖或者其他方式转让并交付机动车但是未办理登记，发生交通事故造成损害，属于该机动车一方责任的，由受让人承担赔偿责任', 753, '{\"level\": null, \"title\": null, \"chunk_index\": 138}', 'bge-large-zh-v1.5', '2026-09-25 17:05:01');
INSERT INTO `chunk` VALUES ('98296dda-ad22-4543-9f61-309110855a6f', 'b25ce095-dfba-4403-acf8-c58eb456ca4c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 132, '第一千一百五十一条　存有遗产的人，应当妥善保管遗产，任何组织或者个人不得侵吞或者争抢。\n第一千一百五十二条　继承开始后，继承人于遗产分割前死亡，并没有放弃继承的，该继承人应当继承的遗产转给其继承人，但是遗嘱另有安排的除外。\n第一千一百五十三条　夫妻共同所有的财产，除有约定的外，遗产分割时，应当先将共同所有的财产的一半分出为配偶所有，其余的为被继承人的遗产。\n遗产在家庭共有财产之中的，遗产分割时，应当先分出他人的财产。\n第一千一百五十四条　有下列情形之一的，遗产中的有关部分按照法定继承办理：\n（一）遗嘱继承人放弃继承或者受遗赠人放弃受遗赠；\n（二）遗嘱继承人丧失继承权或者受遗赠人丧失受遗赠权；\n（三）遗嘱继承人、受遗赠人先于遗嘱人死亡或者终止；\n（四）遗嘱无效部分所涉及的遗产；\n（五）遗嘱未处分的遗产。\n第一千一百五十五条　遗产分割时，应当保留胎儿的继承份额。胎儿娩出时是死体的，保留的份额按照法定继承办理。\n第一千一百五十六条　遗产分割应当有利于生产和生活需要，不损害遗产的效用。\n不宜分割的遗产，可以采取折价、适当补偿或者共有等方法处理。\n第一千一百五十七条　夫妻一方死亡后另一方再婚的，有权处分所继承的财产，任何组织或者个人不得干涉。\n第一千一百五十八条　自然人可以与继承人以外的组织或者个人签订遗赠扶养协议。按照协议，该组织或者个人承担该自然人生养死葬的义务，享有受遗赠的权利。\n第一千一百五十九条　分割遗产，应当清偿被继承人依法应当缴纳的税款和债务；但是，应当为缺乏劳动能力又没有生活来源的继承人保留必要的遗产。\n第一千一百六十条　无人继承又无人受遗赠的遗产，归国家所有，用于公益事业；死者生前是集体所有制组织成员的，归所在集体所有制组织所有。\n第一千一百六十一条　继承人以所得遗产实际价值为限清偿被继承人依法应当缴纳的税款和债务。超过遗产实际价值部分，继承人自愿偿还的不在此限', 798, '{\"level\": null, \"title\": null, \"chunk_index\": 132}', 'bge-large-zh-v1.5', '2026-09-25 17:05:01');
INSERT INTO `chunk` VALUES ('989d3db1-5b72-4a27-907a-e2bb94b27798', 'd9d7dc15-8041-43b8-9f75-f112fe3ae003', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 1, '第五条　生产、储存、使用、经营、运输危险化学品的企业、学校、科研机构、医疗机构、检测机构、检验机构等单位（以下统称危险化学品单位）应当实行全员安全生产责任制，构建安全风险分级管控和隐患排查治理双重预防机制，加强安全生产标准化、信息化建设，其主要负责人对本单位的危险化学品安全生产工作全面负责。\n危险化学品单位应当具备法律、行政法规规定和国家标准、行业标准要求的安全条件，建立健全安全管理规章制度和岗位安全责任制度，对从业人员进行安全生产教育和培训，为从业人员提供符合国家标准或者行业标准的劳动防护用品，依法参加工伤保险。从业人员应当接受教育和培训，考核合格后上岗作业；对有资格要求的岗位，应当配备依法取得相应资格的人员。\n第六条　任何单位和个人不得生产、使用、经营国家禁止生产、使用、经营的危险化学品。\n国家对危险化学品的使用有限制性规定的，任何单位和个人不得违反限制性规定使用危险化学品。\n第七条　对危险化学品的生产、储存、使用、经营、运输实施安全监督管理的有关部门（以下统称负有危险化学品安全监督管理职责的部门），依照下列规定履行职责：\n（一）应急管理部门负责危险化学品安全生产监督管理工作和危险化学品安全监督管理综合工作，组织确定、公布、调整危险化学品目录，依法对新建、改建、扩建生产、储存危险化学品（包括使用长输管道输送危险化学品，下同）的建设项目（以下统称危险化学品建设项目）进行安全条件审查和安全设施设计审查，核发危险化学品安全生产许可证、危险化学品安全使用许可证和危险化学品经营许可证，并负责危险化学品登记工作，组织危险化学品事故应急处置。\n（二）公安机关负责危险化学品的公共安全管理，核发剧毒化学品购买许可证、剧毒化学品道路运输通行证，负责运输危险化学品的车辆进入危险化学品运输车辆限制通行区域的许可，并负责危险化学品运输车辆的道路交通安全管理', 780, '{\"level\": null, \"title\": null, \"chunk_index\": 1}', 'bge-large-zh-v1.5', '2026-09-25 17:04:46');
INSERT INTO `chunk` VALUES ('99a98b50-bec5-4e7e-9fad-590cdef96445', 'b25ce095-dfba-4403-acf8-c58eb456ca4c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 34, '第三百零一条　处分共有的不动产或者动产以及对共有的不动产或者动产作重大修缮、变更性质或者用途的，应当经占份额三分之二以上的按份共有人或者全体共同共有人同意，但是共有人之间另有约定的除外。\n第三百零二条　共有人对共有物的管理费用以及其他负担，有约定的，按照其约定；没有约定或者约定不明确的，按份共有人按照其份额负担，共同共有人共同负担。\n第三百零三条　共有人约定不得分割共有的不动产或者动产，以维持共有关系的，应当按照约定，但是共有人有重大理由需要分割的，可以请求分割；没有约定或者约定不明确的，按份共有人可以随时请求分割，共同共有人在共有的基础丧失或者有重大理由需要分割时可以请求分割。因分割造成其他共有人损害的，应当给予赔偿。\n第三百零四条　共有人可以协商确定分割方式。达不成协议，共有的不动产或者动产可以分割且不会因分割减损价值的，应当对实物予以分割；难以分割或者因分割会减损价值的，应当对折价或者拍卖、变卖取得的价款予以分割。\n共有人分割所得的不动产或者动产有瑕疵的，其他共有人应当分担损失。\n第三百零五条　按份共有人可以转让其享有的共有的不动产或者动产份额。其他共有人在同等条件下享有优先购买的权利。\n第三百零六条　按份共有人转让其享有的共有的不动产或者动产份额的，应当将转让条件及时通知其他共有人。其他共有人应当在合理期限内行使优先购买权。\n两个以上其他共有人主张行使优先购买权的，协商确定各自的购买比例；协商不成的，按照转让时各自的共有份额比例行使优先购买权。\n第三百零七条　因共有的不动产或者动产产生的债权债务，在对外关系上，共有人享有连带债权、承担连带债务，但是法律另有规定或者第三人知道共有人不具有连带债权债务关系的除外；在共有人内部关系上，除共有人另有约定外，按份共有人按照份额享有债权、承担债务，共同共有人共同享有债权、承担债务', 775, '{\"level\": null, \"title\": null, \"chunk_index\": 34}', 'bge-large-zh-v1.5', '2026-09-25 17:05:01');
INSERT INTO `chunk` VALUES ('99b2bf41-bf6d-4a32-9c29-eb4e03d391b4', '821ce1fd-178d-4a7e-ab92-3deff1488ce2', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 80, '走私、贩卖、运输、制造毒品，有下列情形之一的，处十五年有期徒刑、无期徒刑或者死刑，并处没收财产：\n（一）走私、贩卖、运输、制造鸦片一千克以上、海洛因或者甲基苯丙胺五十克以上或者其他毒品数量大的；\n（二）走私、贩卖、运输、制造毒品集团的首要分子；\n（三）武装掩护走私、贩卖、运输、制造毒品的；\n（四）以暴力抗拒检查、拘留、逮捕，情节严重的；\n（五）参与有组织的国际贩毒活动的。\n走私、贩卖、运输、制造鸦片二百克以上不满一千克、海洛因或者甲基苯丙胺十克以上不满五十克或者其他毒品数量较大的，处七年以上有期徒刑，并处罚金。\n走私、贩卖、运输、制造鸦片不满二百克、海洛因或者甲基苯丙胺不满十克或者其他少量毒品的，处三年以下有期徒刑、拘役或者管制，并处罚金；情节严重的，处三年以上七年以下有期徒刑，并处罚金。\n单位犯第二款、第三款、第四款罪的，对单位判处罚金，并对其直接负责的主管人员和其他直接责任人员，依照各该款的规定处罚。\n利用、教唆未成年人走私、贩卖、运输、制造毒品，或者向未成年人出售毒品的，从重处罚。\n对多次走私、贩卖、运输、制造毒品，未经处理的，毒品数量累计计算。\n第三百四十八条　非法持有鸦片一千克以上、海洛因或者甲基苯丙胺五十克以上或者其他毒品数量大的，处七年以上有期徒刑或者无期徒刑，并处罚金；非法持有鸦片二百克以上不满一千克、海洛因或者甲基苯丙胺十克以上不满五十克或者其他毒品数量较大的，处三年以下有期徒刑、拘役或者管制，并处罚金；情节严重的，处三年以上七年以下有期徒刑，并处罚金。\n第三百四十九条　包庇走私、贩卖、运输、制造毒品的犯罪分子的，为犯罪分子窝藏、转移、隐瞒毒品或者犯罪所得的财物的，处三年以下有期徒刑、拘役或者管制；情节严重的，处三年以上十年以下有期徒刑。\n缉毒人员或者其他国家机关工作人员掩护、包庇走私、贩卖、运输、制造毒品的犯罪分子的，依照前款的规定从重处罚', 793, '{\"level\": null, \"title\": null, \"chunk_index\": 80}', 'bge-large-zh-v1.5', '2026-09-25 17:04:56');
INSERT INTO `chunk` VALUES ('99dbeb45-bc0d-4e16-b35e-e4865040fb82', 'b25ce095-dfba-4403-acf8-c58eb456ca4c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 65, '第五百六十八条　当事人互负债务，该债务的标的物种类、品质相同的，任何一方可以将自己的债务与对方的到期债务抵销；但是，根据债务性质、按照当事人约定或者依照法律规定不得抵销的除外。\n当事人主张抵销的，应当通知对方。通知自到达对方时生效。抵销不得附条件或者附期限。\n第五百六十九条　当事人互负债务，标的物种类、品质不相同的，经协商一致，也可以抵销。\n第五百七十条　有下列情形之一，难以履行债务的，债务人可以将标的物提存：\n（一）债权人无正当理由拒绝受领；\n（二）债权人下落不明；\n（三）债权人死亡未确定继承人、遗产管理人，或者丧失民事行为能力未确定监护人；\n（四）法律规定的其他情形。\n标的物不适于提存或者提存费用过高的，债务人依法可以拍卖或者变卖标的物，提存所得的价款。\n第五百七十一条　债务人将标的物或者将标的物依法拍卖、变卖所得价款交付提存部门时，提存成立。\n提存成立的，视为债务人在其提存范围内已经交付标的物。\n第五百七十二条　标的物提存后，债务人应当及时通知债权人或者债权人的继承人、遗产管理人、监护人、财产代管人。\n第五百七十三条　标的物提存后，毁损、灭失的风险由债权人承担。提存期间，标的物的孳息归债权人所有。提存费用由债权人负担。\n第五百七十四条　债权人可以随时领取提存物。但是，债权人对债务人负有到期债务的，在债权人未履行债务或者提供担保之前，提存部门根据债务人的要求应当拒绝其领取提存物。\n债权人领取提存物的权利，自提存之日起五年内不行使而消灭，提存物扣除提存费用后归国家所有。但是，债权人未履行对债务人的到期债务，或者债权人向提存部门书面表示放弃领取提存物权利的，债务人负担提存费用后有权取回提存物。\n第五百七十五条　债权人免除债务人部分或者全部债务的，债权债务部分或者全部终止，但是债务人在合理期限内拒绝的除外', 764, '{\"level\": null, \"title\": null, \"chunk_index\": 65}', 'bge-large-zh-v1.5', '2026-09-25 17:05:01');
INSERT INTO `chunk` VALUES ('9a5f21be-26a8-4dc3-a641-b86c2dc6bd3b', 'b25ce095-dfba-4403-acf8-c58eb456ca4c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 50, '前款规定的债权人为留置权人，占有的动产为留置财产。\n第四百四十八条　债权人留置的动产，应当与债权属于同一法律关系，但是企业之间留置的除外。\n第四百四十九条　法律规定或者当事人约定不得留置的动产，不得留置。\n第四百五十条　留置财产为可分物的，留置财产的价值应当相当于债务的金额。\n第四百五十一条　留置权人负有妥善保管留置财产的义务；因保管不善致使留置财产毁损、灭失的，应当承担赔偿责任。\n第四百五十二条　留置权人有权收取留置财产的孳息。\n前款规定的孳息应当先充抵收取孳息的费用。\n第四百五十三条　留置权人与债务人应当约定留置财产后的债务履行期限；没有约定或者约定不明确的，留置权人应当给债务人六十日以上履行债务的期限，但是鲜活易腐等不易保管的动产除外。债务人逾期未履行的，留置权人可以与债务人协议以留置财产折价，也可以就拍卖、变卖留置财产所得的价款优先受偿。\n留置财产折价或者变卖的，应当参照市场价格。\n第四百五十四条　债务人可以请求留置权人在债务履行期限届满后行使留置权；留置权人不行使的，债务人可以请求人民法院拍卖、变卖留置财产。\n第四百五十五条　留置财产折价或者拍卖、变卖后，其价款超过债权数额的部分归债务人所有，不足部分由债务人清偿。\n第四百五十六条　同一动产上已经设立抵押权或者质权，该动产又被留置的，留置权人优先受偿。\n第四百五十七条　留置权人对留置财产丧失占有或者留置权人接受债务人另行提供担保的，留置权消灭。\n第五分编　占　　有\n第二十章　占　　有\n第四百五十八条　基于合同关系等产生的占有，有关不动产或者动产的使用、收益、违约责任等，按照合同约定；合同没有约定或者约定不明确的，依照有关法律规定。\n第四百五十九条　占有人因使用占有的不动产或者动产，致使该不动产或者动产受到损害的，恶意占有人应当承担赔偿责任', 761, '{\"level\": null, \"title\": null, \"chunk_index\": 50}', 'bge-large-zh-v1.5', '2026-09-25 17:05:01');
INSERT INTO `chunk` VALUES ('9b0c97da-fc0f-45ed-8af8-abdfb9a27fae', 'd9d7dc15-8041-43b8-9f75-f112fe3ae003', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 6, '化工园区所在地设区的市级和县级人民政府自然资源主管部门应当严格控制化工园区周边规划安全控制线内的土地开发利用，规划安全控制线范围内的建设项目应当满足安全风险控制要求。\n第二十一条　县级以上地方人民政府应当加强危险化学品运输安全保障，对涉及危险化学品储存、装卸、运输的物流园区、集中停车区域，以及高速公路服务区的加油站、加气站等进行规划。\n第二十二条　危险化学品生产装置或者储存数量构成重大危险源的危险化学品储存设施，与下列场所、设施、区域的安全距离应当符合国家有关规定：\n（一）居住区以及商业中心、公园等人员密集场所；\n（二）学校、医院、影剧院、体育场馆等公共设施；\n（三）饮用水水源、水厂以及饮用水水源保护区；\n（四）车站、码头（依法经许可从事危险化学品装卸作业的除外）、机场以及通信干线、通信枢纽、铁路线路、道路交通干线、水路交通干线、地铁风亭以及地铁站出入口；\n（五）生态保护红线、自然保护地、永久基本农田、基本草原、种质资源库（场、区、圃）、畜禽规模化养殖场、渔业水域以及种子、种畜禽、水产苗种生产基地；\n（六）河流、湖泊、水库、海洋、重要调水输水线路、蓄滞洪区；\n（七）军事禁区、军事管理区以及有关军事设施；\n（八）核设施；\n（九）法律、行政法规规定的其他场所、设施、区域。\n已建的危险化学品生产装置或者储存数量构成重大危险源的危险化学品储存设施不符合前款规定的，由所在地设区的市级人民政府应急管理部门会同有关部门监督其所属单位在规定期限内进行整改；需要转产、停产、搬迁、关闭的，由本级人民政府决定并组织实施。\n储存数量构成重大危险源的危险化学品储存设施的选址，应当避开地震活动断层和容易发生洪灾、地质灾害、森林草原火灾的区域。\n第三章　生产和储存安全\n第二十三条　危险化学品建设项目应当由应急管理部门进行安全条件审查', 764, '{\"level\": null, \"title\": null, \"chunk_index\": 6}', 'bge-large-zh-v1.5', '2026-09-25 17:04:46');
INSERT INTO `chunk` VALUES ('9b4ca205-2278-4772-a990-a2878fabed76', '16cbea7e-7e36-4f31-afb5-63892345d29c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 51, '有管理权限的监察机关应当进行审理，审理意见与被指定管辖的监察机关意见不一致的，双方应当进行沟通；经沟通不能取得一致意见的，报请有权决定的上级监察机关决定。经协商，有管理权限的监察机关在被指定管辖的监察机关审理阶段可以提前阅卷，沟通了解情况。\n对于前款规定的重大、复杂案件，被指定管辖的监察机关经集体审议后将处理意见报有权决定的上级监察机关审核同意的，有管理权限的监察机关可以经集体审议后依法处置。\n第五节　处　　置\n第二百三十条　监察机关根据监督、调查结果，依据监察法、政务处分法等规定进行处置。\n第二百三十一条　监察机关对于公职人员有职务违法行为但情节较轻的，可以依法进行谈话提醒、批评教育、责令检查，或者予以诫勉。上述方式可以单独使用，也可以依据规定合并使用。\n谈话提醒、批评教育应当由监察机关相关负责人或者承办部门负责人进行，可以由被谈话提醒、批评教育人所在单位有关负责人陪同；经批准也可以委托其所在单位主要负责人进行。对谈话提醒、批评教育情况应当制作记录。\n被责令检查的公职人员应当作出书面检查并进行整改。整改情况在一定范围内通报。\n诫勉由监察机关以谈话或者书面方式进行。采取谈话方式予以诫勉的，应当由监察机关相关负责人或者承办部门负责人进行；经批准也可以委托诫勉对象所在单位主要负责人进行。对谈话情况应当制作记录。\n第二百三十二条　对违法的公职人员依法需要给予政务处分的，应当根据情节轻重作出警告、记过、记大过、降级、撤职、开除的政务处分决定，制作政务处分决定书。\n第二百三十三条　监察机关应当将政务处分决定书在作出后一个月以内送达被处分人和被处分人所在机关、单位，并依法履行宣布、书面告知程序。\n政务处分决定自作出之日起生效。有关机关、单位、组织应当依法及时执行处分决定，并将执行情况向监察机关报告', 755, '{\"level\": null, \"title\": null, \"chunk_index\": 51}', 'bge-large-zh-v1.5', '2026-09-25 17:04:49');
INSERT INTO `chunk` VALUES ('9b50a573-6364-4bd8-a072-d9d25ab9342f', '821ce1fd-178d-4a7e-ab92-3deff1488ce2', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 42, '第一百九十五条　有下列情形之一，进行信用证诈骗活动的，处五年以下有期徒刑或者拘役，并处二万元以上二十万元以下罚金；数额巨大或者有其他严重情节的，处五年以上十年以下有期徒刑，并处五万元以上五十万元以下罚金；数额特别巨大或者有其他特别严重情节的，处十年以上有期徒刑或者无期徒刑，并处五万元以上五十万元以下罚金或者没收财产：\n（一）使用伪造、变造的信用证或者附随的单据、文件的；\n（二）使用作废的信用证的；\n（三）骗取信用证的；\n（四）以其他方法进行信用证诈骗活动的。\n第一百九十六条　有下列情形之一，进行信用卡诈骗活动，数额较大的，处五年以下有期徒刑或者拘役，并处二万元以上二十万元以下罚金；数额巨大或者有其他严重情节的，处五年以上十年以下有期徒刑，并处五万元以上五十万元以下罚金；数额特别巨大或者有其他特别严重情节的，处十年以上有期徒刑或者无期徒刑，并处五万元以上五十万元以下罚金或者没收财产：\n（一）使用伪造的信用卡，或者使用以虚假的身份证明骗领的信用卡的；\n（二）使用作废的信用卡的；\n（三）冒用他人信用卡的；\n（四）恶意透支的。\n前款所称恶意透支，是指持卡人以非法占有为目的，超过规定限额或者规定期限透支，并且经发卡银行催收后仍不归还的行为。\n盗窃信用卡并使用的，依照本法第二百六十四条的规定定罪处罚。\n第一百九十七条　使用伪造、变造的国库券或者国家发行的其他有价证券，进行诈骗活动，数额较大的，处五年以下有期徒刑或者拘役，并处二万元以上二十万元以下罚金；数额巨大或者有其他严重情节的，处五年以上十年以下有期徒刑，并处五万元以上五十万元以下罚金；数额特别巨大或者有其他特别严重情节的，处十年以上有期徒刑或者无期徒刑，并处五万元以上五十万元以下罚金或者没收财产', 731, '{\"level\": null, \"title\": null, \"chunk_index\": 42}', 'bge-large-zh-v1.5', '2026-09-25 17:04:56');
INSERT INTO `chunk` VALUES ('9bc9707a-d4a5-455b-a391-fb1991d1a5a7', 'b25ce095-dfba-4403-acf8-c58eb456ca4c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 43, '第三百九十二条　被担保的债权既有物的担保又有人的担保的，债务人不履行到期债务或者发生当事人约定的实现担保物权的情形，债权人应当按照约定实现债权；没有约定或者约定不明确，债务人自己提供物的担保的，债权人应当先就该物的担保实现债权；第三人提供物的担保的，债权人可以就物的担保实现债权，也可以请求保证人承担保证责任。提供担保的第三人承担担保责任后，有权向债务人追偿。\n第三百九十三条　有下列情形之一的，担保物权消灭：\n（一）主债权消灭；\n（二）担保物权实现；\n（三）债权人放弃担保物权；\n（四）法律规定担保物权消灭的其他情形。\n第十七章　抵押权\n第一节　一般抵押权\n第三百九十四条　为担保债务的履行，债务人或者第三人不转移财产的占有，将该财产抵押给债权人的，债务人不履行到期债务或者发生当事人约定的实现抵押权的情形，债权人有权就该财产优先受偿。\n前款规定的债务人或者第三人为抵押人，债权人为抵押权人，提供担保的财产为抵押财产。\n第三百九十五条　债务人或者第三人有权处分的下列财产可以抵押：\n（一）建筑物和其他土地附着物；\n（二）建设用地使用权；\n（三）海域使用权；\n（四）生产设备、原材料、半成品、产品；\n（五）正在建造的建筑物、船舶、航空器；\n（六）交通运输工具；\n（七）法律、行政法规未禁止抵押的其他财产。\n抵押人可以将前款所列财产一并抵押。\n第三百九十六条　企业、个体工商户、农业生产经营者可以将现有的以及将有的生产设备、原材料、半成品、产品抵押，债务人不履行到期债务或者发生当事人约定的实现抵押权的情形，债权人有权就抵押财产确定时的动产优先受偿。\n第三百九十七条　以建筑物抵押的，该建筑物占用范围内的建设用地使用权一并抵押。以建设用地使用权抵押的，该土地上的建筑物一并抵押。\n抵押人未依据前款规定一并抵押的，未抵押的财产视为一并抵押。\n第三百九十八条　乡镇、村企业的建设用地使用权不得单独抵押', 797, '{\"level\": null, \"title\": null, \"chunk_index\": 43}', 'bge-large-zh-v1.5', '2026-09-25 17:05:01');
INSERT INTO `chunk` VALUES ('9be7668b-ff75-4c8c-968f-bbc411f52e08', 'b25ce095-dfba-4403-acf8-c58eb456ca4c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 122, '约定应当采用书面形式。没有约定或者约定不明确的，适用本法第一千零六十二条、第一千零六十三条的规定。\n夫妻对婚姻关系存续期间所得的财产以及婚前财产的约定，对双方具有法律约束力。\n夫妻对婚姻关系存续期间所得的财产约定归各自所有，夫或者妻一方对外所负的债务，相对人知道该约定的，以夫或者妻一方的个人财产清偿。\n第一千零六十六条　婚姻关系存续期间，有下列情形之一的，夫妻一方可以向人民法院请求分割共同财产：\n（一）一方有隐藏、转移、变卖、毁损、挥霍夫妻共同财产或者伪造夫妻共同债务等严重损害夫妻共同财产利益的行为；\n（二）一方负有法定扶养义务的人患重大疾病需要医治，另一方不同意支付相关医疗费用。\n第二节　父母子女关系和其他近亲属关系\n第一千零六十七条　父母不履行抚养义务的，未成年子女或者不能独立生活的成年子女，有要求父母给付抚养费的权利。\n成年子女不履行赡养义务的，缺乏劳动能力或者生活困难的父母，有要求成年子女给付赡养费的权利。\n第一千零六十八条　父母有教育、保护未成年子女的权利和义务。未成年子女造成他人损害的，父母应当依法承担民事责任。\n第一千零六十九条　子女应当尊重父母的婚姻权利，不得干涉父母离婚、再婚以及婚后的生活。子女对父母的赡养义务，不因父母的婚姻关系变化而终止。\n第一千零七十条　父母和子女有相互继承遗产的权利。\n第一千零七十一条　非婚生子女享有与婚生子女同等的权利，任何组织或者个人不得加以危害和歧视。\n不直接抚养非婚生子女的生父或者生母，应当负担未成年子女或者不能独立生活的成年子女的抚养费。\n第一千零七十二条　继父母与继子女间，不得虐待或者歧视。\n继父或者继母和受其抚养教育的继子女间的权利义务关系，适用本法关于父母子女关系的规定。\n第一千零七十三条　对亲子关系有异议且有正当理由的，父或者母可以向人民法院提起诉讼，请求确认或者否认亲子关系', 780, '{\"level\": null, \"title\": null, \"chunk_index\": 122}', 'bge-large-zh-v1.5', '2026-09-25 17:05:01');
INSERT INTO `chunk` VALUES ('9c997b44-22b9-4433-88c6-021113a2a3c7', '821ce1fd-178d-4a7e-ab92-3deff1488ce2', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 27, '（二）走私货物、物品偷逃应缴税额巨大或者有其他严重情节的，处三年以上十年以下有期徒刑，并处偷逃应缴税额一倍以上五倍以下罚金。\n（三）走私货物、物品偷逃应缴税额特别巨大或者有其他特别严重情节的，处十年以上有期徒刑或者无期徒刑，并处偷逃应缴税额一倍以上五倍以下罚金或者没收财产。\n单位犯前款罪的，对单位判处罚金，并对其直接负责的主管人员和其他直接责任人员，处三年以下有期徒刑或者拘役；情节严重的，处三年以上十年以下有期徒刑；情节特别严重的，处十年以上有期徒刑。\n对多次走私未经处理的，按照累计走私货物、物品的偷逃应缴税额处罚。\n第一百五十四条　下列走私行为，根据本节规定构成犯罪的，依照本法第一百五十三条的规定定罪处罚：\n（一）未经海关许可并且未补缴应缴税额，擅自将批准进口的来料加工、来件装配、补偿贸易的原材料、零件、制成品、设备等保税货物，在境内销售牟利的；\n（二）未经海关许可并且未补缴应缴税额，擅自将特定减税、免税进口的货物、物品，在境内销售牟利的。\n第一百五十五条　下列行为，以走私罪论处，依照本节的有关规定处罚：\n（一）直接向走私人非法收购国家禁止进口物品的，或者直接向走私人非法收购走私进口的其他货物、物品，数额较大的；\n（二）在内海、领海、界河、界湖运输、收购、贩卖国家禁止进出口物品的，或者运输、收购、贩卖国家限制进出口货物、物品，数额较大，没有合法证明的。\n第一百五十六条　与走私罪犯通谋，为其提供贷款、资金、帐号、发票、证明，或者为其提供运输、保管、邮寄或者其他方便的，以走私罪的共犯论处。\n第一百五十七条　武装掩护走私的，依照本法第一百五十一条第一款的规定从重处罚。\n以暴力、威胁方法抗拒缉私的，以走私罪和本法第二百七十七条规定的阻碍国家机关工作人员依法执行职务罪，依照数罪并罚的规定处罚', 754, '{\"level\": null, \"title\": null, \"chunk_index\": 27}', 'bge-large-zh-v1.5', '2026-09-25 17:04:56');
INSERT INTO `chunk` VALUES ('9caa4a24-abfb-43b5-a83e-1c9263120a49', '16cbea7e-7e36-4f31-afb5-63892345d29c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 5, '第二十九条　监察机关依法调查涉嫌贪污贿赂犯罪，包括贪污罪，挪用公款罪，受贿罪，单位受贿罪，利用影响力受贿罪，行贿罪，对有影响力的人行贿罪，对单位行贿罪，介绍贿赂罪，单位行贿罪，巨额财产来源不明罪，隐瞒境外存款罪，私分国有资产罪，私分罚没财物罪，以及公职人员在行使公权力过程中实施的职务侵占罪，挪用资金罪，对外国公职人员、国际公共组织官员行贿罪，非国家工作人员受贿罪和相关联的对非国家工作人员行贿罪。\n第三十条　监察机关依法调查公职人员涉嫌滥用职权犯罪，包括滥用职权罪，国有公司、企业、事业单位人员滥用职权罪，滥用管理公司、证券职权罪，食品、药品监管渎职罪，故意泄露国家秘密罪，报复陷害罪，阻碍解救被拐卖、绑架妇女、儿童罪，帮助犯罪分子逃避处罚罪，违法发放林木采伐许可证罪，办理偷越国（边）境人员出入境证件罪，放行偷越国（边）境人员罪，挪用特定款物罪，非法剥夺公民宗教信仰自由罪，侵犯少数民族风俗习惯罪，打击报复会计、统计人员罪，以及司法工作人员以外的公职人员利用职权实施的非法拘禁罪、虐待被监管人罪、非法搜查罪。\n第三十一条　监察机关依法调查公职人员涉嫌玩忽职守犯罪，包括玩忽职守罪，国有公司、企业、事业单位人员失职罪，签订、履行合同失职被骗罪，国家机关工作人员签订、履行合同失职被骗罪，环境监管失职罪，传染病防治失职罪，商检失职罪，动植物检疫失职罪，不解救被拐卖、绑架妇女、儿童罪，失职造成珍贵文物损毁、流失罪，过失泄露国家秘密罪', 616, '{\"level\": null, \"title\": null, \"chunk_index\": 5}', 'bge-large-zh-v1.5', '2026-09-25 17:04:49');
INSERT INTO `chunk` VALUES ('9cf3825c-4080-4367-8023-49eb7dcf687d', '22a2c356-7a68-4455-b657-333e3dba1e1a', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 11, '如果全国人民代表大会常务委员会认为必要，或者有五分之一以上的全国人民代表大会代表提议，可以临时召集全国人民代表大会会议。\n全国人民代表大会举行会议的时候，选举主席团主持会议。\n第六十二条　全国人民代表大会行使下列职权：\n（一）修改宪法；\n（二）监督宪法的实施；\n（三）制定和修改刑事、民事、国家机构的和其他的基本法律；\n（四）选举中华人民共和国主席、副主席；\n（五）根据中华人民共和国主席的提名，决定国务院总理的人选；根据国务院总理的提名，决定国务院副总理、国务委员、各部部长、各委员会主任、审计长、秘书长的人选；\n（六）选举中央军事委员会主席；根据中央军事委员会主席的提名，决定中央军事委员会其他组成人员的人选；\n（七）选举国家监察委员会主任；\n（八）选举最高人民法院院长；\n（九）选举最高人民检察院检察长；\n（十）审查和批准国民经济和社会发展计划和计划执行情况的报告；\n（十一）审查和批准国家的预算和预算执行情况的报告；\n（十二）改变或者撤销全国人民代表大会常务委员会不适当的决定；\n（十三）批准省、自治区和直辖市的建置；\n（十四）决定特别行政区的设立及其制度；\n（十五）决定战争和和平的问题；\n（十六）应当由最高国家权力机关行使的其他职权。\n第六十三条　全国人民代表大会有权罢免下列人员：\n（一）中华人民共和国主席、副主席；\n（二）国务院总理、副总理、国务委员、各部部长、各委员会主任、审计长、秘书长；\n（三）中央军事委员会主席和中央军事委员会其他组成人员；\n（四）国家监察委员会主任；\n（五）最高人民法院院长；\n（六）最高人民检察院检察长。\n第六十四条　宪法的修改，由全国人民代表大会常务委员会或者五分之一以上的全国人民代表大会代表提议，并由全国人民代表大会以全体代表的三分之二以上的多数通过。\n法律和其他议案由全国人民代表大会以全体代表的过半数通过', 779, '{\"level\": null, \"title\": null, \"chunk_index\": 11}', 'bge-large-zh-v1.5', '2026-09-25 17:04:28');
INSERT INTO `chunk` VALUES ('9e0a58ca-4099-45a9-8190-48acf0c8657f', 'b25ce095-dfba-4403-acf8-c58eb456ca4c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 114, '第一千零五条　自然人的生命权、身体权、健康权受到侵害或者处于其他危难情形的，负有法定救助义务的组织或者个人应当及时施救。\n第一千零六条　完全民事行为能力人有权依法自主决定无偿捐献其人体细胞、人体组织、人体器官、遗体。任何组织或者个人不得强迫、欺骗、利诱其捐献。\n完全民事行为能力人依据前款规定同意捐献的，应当采用书面形式，也可以订立遗嘱。\n自然人生前未表示不同意捐献的，该自然人死亡后，其配偶、成年子女、父母可以共同决定捐献，决定捐献应当采用书面形式。\n第一千零七条　禁止以任何形式买卖人体细胞、人体组织、人体器官、遗体。\n违反前款规定的买卖行为无效。\n第一千零八条　为研制新药、医疗器械或者发展新的预防和治疗方法，需要进行临床试验的，应当依法经相关主管部门批准并经伦理委员会审查同意，向受试者或者受试者的监护人告知试验目的、用途和可能产生的风险等详细情况，并经其书面同意。\n进行临床试验的，不得向受试者收取试验费用。\n第一千零九条　从事与人体基因、人体胚胎等有关的医学和科研活动，应当遵守法律、行政法规和国家有关规定，不得危害人体健康，不得违背伦理道德，不得损害公共利益。\n第一千零一十条　违背他人意愿，以言语、文字、图像、肢体行为等方式对他人实施性骚扰的，受害人有权依法请求行为人承担民事责任。\n机关、企业、学校等单位应当采取合理的预防、受理投诉、调查处置等措施，防止和制止利用职权、从属关系等实施性骚扰。\n第一千零一十一条　以非法拘禁等方式剥夺、限制他人的行动自由，或者非法搜查他人身体的，受害人有权依法请求行为人承担民事责任。\n第三章　姓名权和名称权\n第一千零一十二条　自然人享有姓名权，有权依法决定、使用、变更或者许可他人使用自己的姓名，但是不得违背公序良俗。\n第一千零一十三条　法人、非法人组织享有名称权，有权依法决定、使用、变更、转让或者许可他人使用自己的名称', 787, '{\"level\": null, \"title\": null, \"chunk_index\": 114}', 'bge-large-zh-v1.5', '2026-09-25 17:05:01');
INSERT INTO `chunk` VALUES ('a0685e42-b0dd-4339-9899-9b98ac12885a', 'b25ce095-dfba-4403-acf8-c58eb456ca4c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 144, '因所有人、管理人、使用人或者第三人的原因，建筑物、构筑物或者其他设施倒塌、塌陷造成他人损害的，由所有人、管理人、使用人或者第三人承担侵权责任。\n第一千二百五十三条　建筑物、构筑物或者其他设施及其搁置物、悬挂物发生脱落、坠落造成他人损害，所有人、管理人或者使用人不能证明自己没有过错的，应当承担侵权责任。所有人、管理人或者使用人赔偿后，有其他责任人的，有权向其他责任人追偿。\n第一千二百五十四条　禁止从建筑物中抛掷物品。从建筑物中抛掷物品或者从建筑物上坠落的物品造成他人损害的，由侵权人依法承担侵权责任；经调查难以确定具体侵权人的，除能够证明自己不是侵权人的外，由可能加害的建筑物使用人给予补偿。可能加害的建筑物使用人补偿后，有权向侵权人追偿。\n物业服务企业等建筑物管理人应当采取必要的安全保障措施防止前款规定情形的发生；未采取必要的安全保障措施的，应当依法承担未履行安全保障义务的侵权责任。\n发生本条第一款规定的情形的，公安等机关应当依法及时调查，查清责任人。\n第一千二百五十五条　堆放物倒塌、滚落或者滑落造成他人损害，堆放人不能证明自己没有过错的，应当承担侵权责任。\n第一千二百五十六条　在公共道路上堆放、倾倒、遗撒妨碍通行的物品造成他人损害的，由行为人承担侵权责任。公共道路管理人不能证明已经尽到清理、防护、警示等义务的，应当承担相应的责任。\n第一千二百五十七条　因林木折断、倾倒或者果实坠落等造成他人损害，林木的所有人或者管理人不能证明自己没有过错的，应当承担侵权责任。\n第一千二百五十八条　在公共场所或者道路上挖掘、修缮安装地下设施等造成他人损害，施工人不能证明已经设置明显标志和采取安全措施的，应当承担侵权责任。\n窨井等地下设施造成他人损害，管理人不能证明尽到管理职责的，应当承担侵权责任', 749, '{\"level\": null, \"title\": null, \"chunk_index\": 144}', 'bge-large-zh-v1.5', '2026-09-25 17:05:01');
INSERT INTO `chunk` VALUES ('a1d084f2-e133-45ae-b044-d50af9cfbb96', '22a2c356-7a68-4455-b657-333e3dba1e1a', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 22, '第一百一十一条　城市和农村按居民居住地区设立的居民委员会或者村民委员会是基层群众性自治组织。居民委员会、村民委员会的主任、副主任和委员由居民选举。居民委员会、村民委员会同基层政权的相互关系由法律规定。\n居民委员会、村民委员会设人民调解、治安保卫、公共卫生等委员会，办理本居住地区的公共事务和公益事业，调解民间纠纷，协助维护社会治安，并且向人民政府反映群众的意见、要求和提出建议。\n第六节　民族自治地方的自治机关\n第一百一十二条　民族自治地方的自治机关是自治区、自治州、自治县的人民代表大会和人民政府。\n第一百一十三条　自治区、自治州、自治县的人民代表大会中，除实行区域自治的民族的代表外，其他居住在本行政区域内的民族也应当有适当名额的代表。\n自治区、自治州、自治县的人民代表大会常务委员会中应当有实行区域自治的民族的公民担任主任或者副主任。\n第一百一十四条　自治区主席、自治州州长、自治县县长由实行区域自治的民族的公民担任。\n第一百一十五条　自治区、自治州、自治县的自治机关行使宪法第三章第五节规定的地方国家机关的职权，同时依照宪法、民族区域自治法和其他法律规定的权限行使自治权，根据本地方实际情况贯彻执行国家的法律、政策。\n第一百一十六条　民族自治地方的人民代表大会有权依照当地民族的政治、经济和文化的特点，制定自治条例和单行条例。自治区的自治条例和单行条例，报全国人民代表大会常务委员会批准后生效。自治州、自治县的自治条例和单行条例，报省或者自治区的人民代表大会常务委员会批准后生效，并报全国人民代表大会常务委员会备案。\n第一百一十七条　民族自治地方的自治机关有管理地方财政的自治权。凡是依照国家财政体制属于民族自治地方的财政收入，都应当由民族自治地方的自治机关自主地安排使用。\n第一百一十八条　民族自治地方的自治机关在国家计划的指导下，自主地安排和管理地方性的经济建设事业', 789, '{\"level\": null, \"title\": null, \"chunk_index\": 22}', 'bge-large-zh-v1.5', '2026-09-25 17:04:29');
INSERT INTO `chunk` VALUES ('a2606359-14e9-4e4f-a7dd-bd4b87c7b6a4', '16cbea7e-7e36-4f31-afb5-63892345d29c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 21, '依法决定不公开证人、鉴定人、被害人的真实姓名、住址和工作单位等个人信息的，可以在询问笔录等法律文书、证据材料中使用化名。但是应当另行书面说明使用化名的情况并标明密级，单独成卷。\n监察机关采取保护措施需要协助的，可以提请公安机关等有关单位和要求有关个人依法予以协助。\n第九十八条　本条例第八十三条至第八十六条的要求，也适用于询问。询问重要涉案人员，根据情况适用本条例第八十二条的规定。\n询问被害人，适用询问证人的规定。\n第六节　强制到案\n第九十九条　监察机关调查严重职务违法或者职务犯罪，对于经通知无正当理由不到案的被调查人，经依法审批，可以强制其到监察机关谈话场所或者留置场所接受调查。\n首次通知到案一般应当以书面方式，确因情况紧急无法书面通知的，可以通过电话等方式通知，并将相关情况制作工作记录。\n采取强制到案措施时，调查人员不得少于二人，应当向被强制到案人员出具《强制到案决定书》。\n第一百条　监察机关应当立即将被强制到案人员送至监察机关谈话场所或者留置场所。强制到案的时间自被强制到案人员到达相关场所时起算。\n被强制到案人员到案后，应当要求其在《强制到案决定书》上填写到案时间，并签名、捺指印；强制到案结束后，应当要求被强制到案人员在《强制到案决定书》上填写结束时间，并签名、捺指印。被强制到案人员拒绝填写或者签名、捺指印的，调查人员应当在文书上记明。\n一次强制到案持续的时间不得超过十二小时；依法需要采取管护或者留置措施的，按规定报批后，强制到案持续的时间不得超过二十四小时。两次强制到案间隔的时间不得少于二十四小时，不得以连续强制到案的方式变相拘禁被调查人。两次强制到案的间隔时间从第一次强制到案结束时起算。\n第一百零一条　监察机关强制被调查人到案后，应当对涉嫌职务违法的被调查人及时谈话，对涉嫌职务犯罪的被调查人及时讯问', 766, '{\"level\": null, \"title\": null, \"chunk_index\": 21}', 'bge-large-zh-v1.5', '2026-09-25 17:04:49');
INSERT INTO `chunk` VALUES ('a286a556-b00e-4b4f-99b2-3f60fd5856e2', '16cbea7e-7e36-4f31-afb5-63892345d29c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 57, '第二百四十七条　涉嫌职务犯罪的被调查人具有下列情形之一的，可以认定为监察法第三十四条第三项规定的积极退赃，减少损失：\n（一）全额退赃的；\n（二）退赃能力不足，但被调查人及其亲友在监察机关追缴赃款赃物过程中积极配合，且大部分已追缴到位的；\n（三）犯罪后主动采取措施避免损失发生，或者积极采取有效措施减少、挽回大部分损失的。\n第二百四十八条　涉嫌职务犯罪的被调查人具有下列情形之一的，可以认定为监察法第三十四条第四项规定的具有重大立功表现：\n（一）检举揭发他人重大犯罪行为且经查证属实的；\n（二）提供其他重大案件的重要线索且经查证属实的；\n（三）阻止他人重大犯罪活动的；\n（四）协助抓捕其他重大职务犯罪案件被调查人、重大犯罪嫌疑人（包括同案犯）的；\n（五）为国家挽回重大损失等对国家和社会有其他重大贡献的。\n前款所称重大犯罪一般是指依法可能被判处无期徒刑以上刑罚的犯罪行为；重大案件一般是指在本省、自治区、直辖市或者全国范围内有较大影响的案件；查证属实一般是指有关案件已被监察机关或者司法机关立案调查、侦查，被调查人、犯罪嫌疑人被监察机关采取监察强制措施或者被司法机关采取刑事强制措施，或者被告人被人民法院作出有罪判决，并结合案件事实、证据进行判断。\n监察法第三十四条第四项规定的案件涉及国家重大利益，是指案件涉及国家主权和领土完整、国家安全、外交、社会稳定、经济发展等情形', 585, '{\"level\": null, \"title\": null, \"chunk_index\": 57}', 'bge-large-zh-v1.5', '2026-09-25 17:04:49');
INSERT INTO `chunk` VALUES ('a32bf5ae-fdeb-41ad-9481-6e0cf0ef9da8', '16cbea7e-7e36-4f31-afb5-63892345d29c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 35, '第一百五十八条　查封、扣押下列物品，应当依法进行相应的处理：\n（一）查封、扣押外币、金银珠宝、文物、名贵字画以及其他不易辨别真伪的贵重物品，具备当场密封条件的，应当当场密封，由二名以上调查人员在密封材料上签名并记明密封时间。不具备当场密封条件的，应当在笔录中记明，以拍照、录像等方法加以保全后进行封存。查封、扣押的贵重物品需要鉴定的，应当及时鉴定。\n（二）查封、扣押存折、银行卡、有价证券等支付凭证和具有一定特征能够证明案情的现金，应当记明特征、编号、种类、面值、张数、金额等，当场密封，由二名以上调查人员在密封材料上签名并记明密封时间。\n（三）查封、扣押易损毁、灭失、变质等不宜长期保存的物品以及有消费期限的卡、券，应当在笔录中记明，以拍照、录像等方法加以保全后进行封存，或者经审批委托有关机构变卖、拍卖。变卖、拍卖的价款存入专用账户保管，待调查终结后一并处理。\n（四）对于可以作为证据使用的录音录像、电子数据存储介质，应当记明案由、对象、内容，录制、复制的时间、地点、规格、类别、应用长度、文件格式及长度等，制作清单。具备查封、扣押条件的电子设备、存储介质应当密封保存。必要时，可以请有关机关协助。\n（五）对被调查人使用违法犯罪所得与合法收入共同购置的不可分割的财产，可以先行查封、扣押。对无法分割退还的财产，涉及违法的，可以经被调查人申请并经监察机关批准，由被调查人亲属或者被调查人委托的其他人员在监察机关监督下自行变现后上缴违法所得及孳息，也可以由监察机关在结案后委托有关单位拍卖、变卖，退还不属于违法所得的部分及孳息；涉及职务犯罪的，依法移送司法机关处置，并说明涉嫌犯罪所得及孳息数额。\n（六）查封、扣押危险品、违禁品，应当及时送交有关部门，或者根据工作需要严格封存保管。\n第一百五十九条　对于需要启封的财物和文件，应当由二名以上调查人员共同办理', 778, '{\"level\": null, \"title\": null, \"chunk_index\": 35}', 'bge-large-zh-v1.5', '2026-09-25 17:04:49');
INSERT INTO `chunk` VALUES ('a3ad588a-3bb6-443d-980f-eff3a5142e6c', 'd9d7dc15-8041-43b8-9f75-f112fe3ae003', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 13, '第四十九条　申请危险化学品安全使用许可证的化工企业，除应当符合本法第四十七条的规定外，还应当具备下列条件：\n（一）有与所使用的危险化学品相适应的专业技术人员，从业人员经考核合格；\n（二）有安全生产管理机构和专职安全生产管理人员；\n（三）有符合国家规定的危险化学品事故应急预案和必要的应急救援器材、装备、设备和物资；\n（四）依法进行了安全评价；\n（五）法律、法规规定的其他条件。\n第五十条　申请危险化学品安全使用许可证的化工企业，应当向所在地设区的市级人民政府应急管理部门提出申请，并提交其符合本法第四十九条规定条件的证明材料。设区的市级人民政府应急管理部门应当依法进行审查，自收到证明材料之日起二十个工作日内作出批准或者不予批准的决定。予以批准的，颁发危险化学品安全使用许可证；不予批准的，书面通知申请人并说明理由。\n设区的市级人民政府应急管理部门应当将其颁发危险化学品安全使用许可证的情况依照有关法律、行政法规的规定及时向社会公开。\n第五十一条　使用危险化学品的单位应当将其作业场所使用的化学品安全技术说明书和化学品安全标签提供给从业人员，并加强培训教育，告知从业人员正确使用的方法和在紧急情况下应当采取的措施。\n使用危险化学品的个人，应当了解危险化学品的危险特性、正确使用方法和防护措施，不得违法使用、储存、处置危险化学品。\n第五十二条　本法第三十七条、第三十八条、第四十条第一款、第四十五条关于生产、储存危险化学品的单位的规定，适用于使用危险化学品的单位；第三十四条、第三十五条、第三十六条、第三十九条关于生产、储存危险化学品的企业的规定，适用于使用危险化学品从事生产的企业。\n第五章　经营安全\n第五十三条　国家对危险化学品经营（包括仓储经营，下同）实行许可制度。未经许可，任何单位和个人不得经营危险化学品。危险化学品经营企业不得向未经许可从事危险化学品生产、经营活动的企业采购危险化学品', 797, '{\"level\": null, \"title\": null, \"chunk_index\": 13}', 'bge-large-zh-v1.5', '2026-09-25 17:04:46');
INSERT INTO `chunk` VALUES ('a466c3a7-3213-4e01-8526-0b0899cb7eee', '22a2c356-7a68-4455-b657-333e3dba1e1a', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 19, '第九十一条　国务院设立审计机关，对国务院各部门和地方各级政府的财政收支，对国家的财政金融机构和企业事业组织的财务收支，进行审计监督。\n审计机关在国务院总理领导下，依照法律规定独立行使审计监督权，不受其他行政机关、社会团体和个人的干涉。\n第九十二条　国务院对全国人民代表大会负责并报告工作；在全国人民代表大会闭会期间，对全国人民代表大会常务委员会负责并报告工作。\n第四节　中央军事委员会\n第九十三条　中华人民共和国中央军事委员会领导全国武装力量。\n中央军事委员会由下列人员组成：\n主席，\n副主席若干人，\n委员若干人。\n中央军事委员会实行主席负责制。\n中央军事委员会每届任期同全国人民代表大会每届任期相同。\n第九十四条　中央军事委员会主席对全国人民代表大会和全国人民代表大会常务委员会负责。\n第五节　地方各级人民代表大会和地方各级人民政府\n第九十五条　省、直辖市、县、市、市辖区、乡、民族乡、镇设立人民代表大会和人民政府。\n地方各级人民代表大会和地方各级人民政府的组织由法律规定。\n自治区、自治州、自治县设立自治机关。自治机关的组织和工作根据宪法第三章第五节、第六节规定的基本原则由法律规定。\n第九十六条　地方各级人民代表大会是地方国家权力机关。\n县级以上的地方各级人民代表大会设立常务委员会。\n第九十七条　省、直辖市、设区的市的人民代表大会代表由下一级的人民代表大会选举；县、不设区的市、市辖区、乡、民族乡、镇的人民代表大会代表由选民直接选举。\n地方各级人民代表大会代表名额和代表产生办法由法律规定。\n第九十八条　地方各级人民代表大会每届任期五年。\n第九十九条　地方各级人民代表大会在本行政区域内，保证宪法、法律、行政法规的遵守和执行；依照法律规定的权限，通过和发布决议，审查和决定地方的经济建设、文化建设和公共事业建设的计划', 762, '{\"level\": null, \"title\": null, \"chunk_index\": 19}', 'bge-large-zh-v1.5', '2026-09-25 17:04:29');
INSERT INTO `chunk` VALUES ('a473708b-3282-4c7a-a797-fab96a9787b1', 'b25ce095-dfba-4403-acf8-c58eb456ca4c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 96, '第八百四十七条　职务技术成果的使用权、转让权属于法人或者非法人组织的，法人或者非法人组织可以就该项职务技术成果订立技术合同。法人或者非法人组织订立技术合同转让职务技术成果时，职务技术成果的完成人享有以同等条件优先受让的权利。\n职务技术成果是执行法人或者非法人组织的工作任务，或者主要是利用法人或者非法人组织的物质技术条件所完成的技术成果。\n第八百四十八条　非职务技术成果的使用权、转让权属于完成技术成果的个人，完成技术成果的个人可以就该项非职务技术成果订立技术合同。\n第八百四十九条　完成技术成果的个人享有在有关技术成果文件上写明自己是技术成果完成者的权利和取得荣誉证书、奖励的权利。\n第八百五十条　非法垄断技术或者侵害他人技术成果的技术合同无效。\n第二节　技术开发合同\n第八百五十一条　技术开发合同是当事人之间就新技术、新产品、新工艺、新品种或者新材料及其系统的研究开发所订立的合同。\n技术开发合同包括委托开发合同和合作开发合同。\n技术开发合同应当采用书面形式。\n当事人之间就具有实用价值的科技成果实施转化订立的合同，参照适用技术开发合同的有关规定。\n第八百五十二条　委托开发合同的委托人应当按照约定支付研究开发经费和报酬，提供技术资料，提出研究开发要求，完成协作事项，接受研究开发成果。\n第八百五十三条　委托开发合同的研究开发人应当按照约定制定和实施研究开发计划，合理使用研究开发经费，按期完成研究开发工作，交付研究开发成果，提供有关的技术资料和必要的技术指导，帮助委托人掌握研究开发成果。\n第八百五十四条　委托开发合同的当事人违反约定造成研究开发工作停滞、延误或者失败的，应当承担违约责任。\n第八百五十五条　合作开发合同的当事人应当按照约定进行投资，包括以技术进行投资，分工参与研究开发工作，协作配合研究开发工作', 759, '{\"level\": null, \"title\": null, \"chunk_index\": 96}', 'bge-large-zh-v1.5', '2026-09-25 17:05:01');
INSERT INTO `chunk` VALUES ('a4d66602-70d0-42ed-be8d-721b85ea752e', '16cbea7e-7e36-4f31-afb5-63892345d29c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 64, '第二百七十三条　监察机关应当依法全面收集外逃人员涉嫌职务违法和职务犯罪证据。\n第二百七十四条　开展反腐败国际追逃追赃等涉外案件办理工作，应当把思想教育贯穿始终，落实宽严相济刑事政策，依法适用认罪认罚从宽制度，促使外逃人员回国投案或者配合调查、主动退赃。开展相关工作，应当尊重所在国家（地区）的法律规定。\n第二百七十五条　外逃人员归案、违法所得及其他涉案财产被追缴后，承办案件的监察机关应当将情况逐级报送国家监察委员会国际合作局。监察机关应当依法对涉案人员和违法所得及其他涉案财产作出处置，或者请有关单位依法处置。对不需要继续采取相关措施的，应当及时解除或者撤销。\n第三节　对外合作\n第二百七十六条　监察机关对依法应当留置或者已经决定留置的外逃人员，需要申请发布国际刑警组织红色通报的，应当逐级报送国家监察委员会审核。国家监察委员会审核后，依法通过公安部向国际刑警组织提出申请。\n需要延期、暂停、撤销红色通报的，申请发布红色通报的监察机关应当逐级报送国家监察委员会审核，由国家监察委员会依法通过公安部联系国际刑警组织办理。\n第二百七十七条　地方各级监察机关通过引渡方式办理相关涉外案件的，应当按照《中华人民共和国引渡法》、相关双边及多边国际条约等规定准备引渡请求书及相关材料，逐级报送国家监察委员会审核。由国家监察委员会依法通过外交途径向外国提出引渡请求。\n第二百七十八条　地方各级监察机关通过刑事司法协助方式办理相关涉外案件的，应当按照《中华人民共和国国际刑事司法协助法》（以下简称国际刑事司法协助法）、相关双边及多边国际条约等规定准备刑事司法协助请求书及相关材料，逐级报送国家监察委员会审核。由国家监察委员会依法直接或者通过对外联系机关等渠道，向外国提出刑事司法协助请求', 736, '{\"level\": null, \"title\": null, \"chunk_index\": 64}', 'bge-large-zh-v1.5', '2026-09-25 17:04:49');
INSERT INTO `chunk` VALUES ('a5c41926-85b1-48ff-9831-56a83bc1a4e6', '16cbea7e-7e36-4f31-afb5-63892345d29c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 40, '第一百八十条　经审查具有下列情形之一的，应当补充鉴定：\n（一）鉴定内容有明显遗漏的；\n（二）发现新的有鉴定意义的证物的；\n（三）对鉴定证物有新的鉴定要求的；\n（四）鉴定意见不完整，委托事项无法确定的；\n（五）其他需要补充鉴定的情形。\n第一百八十一条　经审查具有下列情形之一的，应当重新鉴定：\n（一）鉴定程序违法或者违反相关专业技术要求的；\n（二）鉴定机构、鉴定人不具备鉴定资质和条件的；\n（三）鉴定人故意作出虚假鉴定或者违反回避规定的；\n（四）鉴定意见依据明显不足的；\n（五）检材虚假或者被损坏的；\n（六）其他应当重新鉴定的情形。\n决定重新鉴定的，应当另行确定鉴定机构和鉴定人。\n第一百八十二条　因无鉴定机构，或者根据法律法规等规定，监察机关可以指派、聘请具有专门知识的人就案件的专门性问题出具报告。\n第十六节　技术调查\n第一百八十三条　监察机关根据调查涉嫌重大贪污贿赂等职务犯罪需要，依照规定的权限和程序报经批准，可以依法采取技术调查措施，按照规定交公安机关或者国家有关执法机关依法执行。\n第一百八十四条　依法采取技术调查措施的，监察机关应当出具《采取技术调查措施委托函》《采取技术调查措施决定书》和《采取技术调查措施适用对象情况表》，送交有关机关执行。其中，设区的市级以下监察机关委托有关执行机关采取技术调查措施，还应当提供《立案决定书》。\n第一百八十五条　技术调查措施的期限按照监察法的规定执行，期限届满前未办理延期手续的，到期自动解除。\n对于不需要继续采取技术调查措施的，监察机关应当按规定及时报批，将《解除技术调查措施决定书》送交有关机关执行。\n需要依法变更技术调查措施种类或者增加适用对象的，监察机关应当重新办理报批和委托手续，依法送交有关机关执行', 730, '{\"level\": null, \"title\": null, \"chunk_index\": 40}', 'bge-large-zh-v1.5', '2026-09-25 17:04:49');
INSERT INTO `chunk` VALUES ('a8d9a0d0-5736-49b9-9fb9-1dbe29385513', 'b25ce095-dfba-4403-acf8-c58eb456ca4c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 4, '第十九条　八周岁以上的未成年人为限制民事行为能力人，实施民事法律行为由其法定代理人代理或者经其法定代理人同意、追认；但是，可以独立实施纯获利益的民事法律行为或者与其年龄、智力相适应的民事法律行为。\n第二十条　不满八周岁的未成年人为无民事行为能力人，由其法定代理人代理实施民事法律行为。\n第二十一条　不能辨认自己行为的成年人为无民事行为能力人，由其法定代理人代理实施民事法律行为。\n八周岁以上的未成年人不能辨认自己行为的，适用前款规定。\n第二十二条　不能完全辨认自己行为的成年人为限制民事行为能力人，实施民事法律行为由其法定代理人代理或者经其法定代理人同意、追认；但是，可以独立实施纯获利益的民事法律行为或者与其智力、精神健康状况相适应的民事法律行为。\n第二十三条　无民事行为能力人、限制民事行为能力人的监护人是其法定代理人。\n第二十四条　不能辨认或者不能完全辨认自己行为的成年人，其利害关系人或者有关组织，可以向人民法院申请认定该成年人为无民事行为能力人或者限制民事行为能力人。\n被人民法院认定为无民事行为能力人或者限制民事行为能力人的，经本人、利害关系人或者有关组织申请，人民法院可以根据其智力、精神健康恢复的状况，认定该成年人恢复为限制民事行为能力人或者完全民事行为能力人。\n本条规定的有关组织包括：居民委员会、村民委员会、学校、医疗机构、妇女联合会、残疾人联合会、依法设立的老年人组织、民政部门等。\n第二十五条　自然人以户籍登记或者其他有效身份登记记载的居所为住所；经常居所与住所不一致的，经常居所视为住所。\n第二节　监　　护\n第二十六条　父母对未成年子女负有抚养、教育和保护的义务。\n成年子女对父母负有赡养、扶助和保护的义务。\n第二十七条　父母是未成年子女的监护人', 736, '{\"level\": null, \"title\": null, \"chunk_index\": 4}', 'bge-large-zh-v1.5', '2026-09-25 17:05:01');
INSERT INTO `chunk` VALUES ('a91aa3f9-82f5-41fc-b340-0468f2f075b9', 'b25ce095-dfba-4403-acf8-c58eb456ca4c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 105, '但是，第三人与受托人订立合同时如果知道该委托人就不会订立合同的除外。\n受托人因委托人的原因对第三人不履行义务，受托人应当向第三人披露委托人，第三人因此可以选择受托人或者委托人作为相对人主张其权利，但是第三人不得变更选定的相对人。\n委托人行使受托人对第三人的权利的，第三人可以向委托人主张其对受托人的抗辩。第三人选定委托人作为其相对人的，委托人可以向第三人主张其对受托人的抗辩以及受托人对第三人的抗辩。\n第九百二十七条　受托人处理委托事务取得的财产，应当转交给委托人。\n第九百二十八条　受托人完成委托事务的，委托人应当按照约定向其支付报酬。\n因不可归责于受托人的事由，委托合同解除或者委托事务不能完成的，委托人应当向受托人支付相应的报酬。当事人另有约定的，按照其约定。\n第九百二十九条　有偿的委托合同，因受托人的过错造成委托人损失的，委托人可以请求赔偿损失。无偿的委托合同，因受托人的故意或者重大过失造成委托人损失的，委托人可以请求赔偿损失。\n受托人超越权限造成委托人损失的，应当赔偿损失。\n第九百三十条　受托人处理委托事务时，因不可归责于自己的事由受到损失的，可以向委托人请求赔偿损失。\n第九百三十一条　委托人经受托人同意，可以在受托人之外委托第三人处理委托事务。因此造成受托人损失的，受托人可以向委托人请求赔偿损失。\n第九百三十二条　两个以上的受托人共同处理委托事务的，对委托人承担连带责任。\n第九百三十三条　委托人或者受托人可以随时解除委托合同。因解除合同造成对方损失的，除不可归责于该当事人的事由外，无偿委托合同的解除方应当赔偿因解除时间不当造成的直接损失，有偿委托合同的解除方应当赔偿对方的直接损失和合同履行后可以获得的利益。\n第九百三十四条　委托人死亡、终止或者受托人死亡、丧失民事行为能力、终止的，委托合同终止；但是，当事人另有约定或者根据委托事务的性质不宜终止的除外', 790, '{\"level\": null, \"title\": null, \"chunk_index\": 105}', 'bge-large-zh-v1.5', '2026-09-25 17:05:01');
INSERT INTO `chunk` VALUES ('a95453b1-e83c-43e1-adb7-8074adb26940', '821ce1fd-178d-4a7e-ab92-3deff1488ce2', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 36, '伪造、变造股票或者公司、企业债券，数额较大的，处三年以下有期徒刑或者拘役，并处或者单处一万元以上十万元以下罚金；数额巨大的，处三年以上十年以下有期徒刑，并处二万元以上二十万元以下罚金。\n单位犯前两款罪的，对单位判处罚金，并对其直接负责的主管人员和其他直接责任人员，依照前两款的规定处罚。\n第一百七十九条　未经国家有关主管部门批准，擅自发行股票或者公司、企业债券，数额巨大、后果严重或者有其他严重情节的，处五年以下有期徒刑或者拘役，并处或者单处非法募集资金金额百分之一以上百分之五以下罚金。\n单位犯前款罪的，对单位判处罚金，并对其直接负责的主管人员和其他直接责任人员，处五年以下有期徒刑或者拘役。\n第一百八十条　证券、期货交易内幕信息的知情人员或者非法获取证券、期货交易内幕信息的人员，在涉及证券的发行，证券、期货交易或者其他对证券、期货交易价格有重大影响的信息尚未公开前，买入或者卖出该证券，或者从事与该内幕信息有关的期货交易，或者泄露该信息，或者明示、暗示他人从事上述交易活动，情节严重的，处五年以下有期徒刑或者拘役，并处或者单处违法所得一倍以上五倍以下罚金；情节特别严重的，处五年以上十年以下有期徒刑，并处违法所得一倍以上五倍以下罚金。\n单位犯前款罪的，对单位判处罚金，并对其直接负责的主管人员和其他直接责任人员，处五年以下有期徒刑或者拘役。\n内幕信息、知情人员的范围，依照法律、行政法规的规定确定。\n证券交易所、期货交易所、证券公司、期货经纪公司、基金管理公司、商业银行、保险公司等金融机构的从业人员以及有关监管部门或者行业协会的工作人员，利用因职务便利获取的内幕信息以外的其他未公开的信息，违反规定，从事与该信息相关的证券、期货交易活动，或者明示、暗示他人从事相关交易活动，情节严重的，依照第一款的规定处罚', 757, '{\"level\": null, \"title\": null, \"chunk_index\": 36}', 'bge-large-zh-v1.5', '2026-09-25 17:04:56');
INSERT INTO `chunk` VALUES ('aa3710aa-a44f-4f64-a00a-2a9cca6b899d', 'b25ce095-dfba-4403-acf8-c58eb456ca4c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 95, '第八百四十一条　因托运人托运货物时的过错造成多式联运经营人损失的，即使托运人已经转让多式联运单据，托运人仍然应当承担赔偿责任。\n第八百四十二条　货物的毁损、灭失发生于多式联运的某一运输区段的，多式联运经营人的赔偿责任和责任限额，适用调整该区段运输方式的有关法律规定；货物毁损、灭失发生的运输区段不能确定的，依照本章规定承担赔偿责任。\n第二十章　技术合同\n第一节　一般规定\n第八百四十三条　技术合同是当事人就技术开发、转让、许可、咨询或者服务订立的确立相互之间权利和义务的合同。\n第八百四十四条　订立技术合同，应当有利于知识产权的保护和科学技术的进步，促进科学技术成果的研发、转化、应用和推广。\n第八百四十五条　技术合同的内容一般包括项目的名称，标的的内容、范围和要求，履行的计划、地点和方式，技术信息和资料的保密，技术成果的归属和收益的分配办法，验收标准和方法，名词和术语的解释等条款。\n与履行合同有关的技术背景资料、可行性论证和技术评价报告、项目任务书和计划书、技术标准、技术规范、原始设计和工艺文件，以及其他技术文档，按照当事人的约定可以作为合同的组成部分。\n技术合同涉及专利的，应当注明发明创造的名称、专利申请人和专利权人、申请日期、申请号、专利号以及专利权的有效期限。\n第八百四十六条　技术合同价款、报酬或者使用费的支付方式由当事人约定，可以采取一次总算、一次总付或者一次总算、分期支付，也可以采取提成支付或者提成支付附加预付入门费的方式。\n约定提成支付的，可以按照产品价格、实施专利和使用技术秘密后新增的产值、利润或者产品销售额的一定比例提成，也可以按照约定的其他方式计算。提成支付的比例可以采取固定比例、逐年递增比例或者逐年递减比例。\n约定提成支付的，当事人可以约定查阅有关会计账目的办法', 750, '{\"level\": null, \"title\": null, \"chunk_index\": 95}', 'bge-large-zh-v1.5', '2026-09-25 17:05:01');
INSERT INTO `chunk` VALUES ('aca8debb-d625-4659-a166-776ca44cb76c', 'b25ce095-dfba-4403-acf8-c58eb456ca4c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 108, '物业服务期限届满前，物业服务人不同意续聘的，应当在合同期限届满前九十日书面通知业主或者业主委员会，但是合同对通知期限另有约定的除外。\n第九百四十八条　物业服务期限届满后，业主没有依法作出续聘或者另聘物业服务人的决定，物业服务人继续提供物业服务的，原物业服务合同继续有效，但是服务期限为不定期。\n当事人可以随时解除不定期物业服务合同，但是应当提前六十日书面通知对方。\n第九百四十九条　物业服务合同终止的，原物业服务人应当在约定期限或者合理期限内退出物业服务区域，将物业服务用房、相关设施、物业服务所必需的相关资料等交还给业主委员会、决定自行管理的业主或者其指定的人，配合新物业服务人做好交接工作，并如实告知物业的使用和管理状况。\n原物业服务人违反前款规定的，不得请求业主支付物业服务合同终止后的物业费；造成业主损失的，应当赔偿损失。\n第九百五十条　物业服务合同终止后，在业主或者业主大会选聘的新物业服务人或者决定自行管理的业主接管之前，原物业服务人应当继续处理物业服务事项，并可以请求业主支付该期间的物业费。\n第二十五章　行纪合同\n第九百五十一条　行纪合同是行纪人以自己的名义为委托人从事贸易活动，委托人支付报酬的合同。\n第九百五十二条　行纪人处理委托事务支出的费用，由行纪人负担，但是当事人另有约定的除外。\n第九百五十三条　行纪人占有委托物的，应当妥善保管委托物。\n第九百五十四条　委托物交付给行纪人时有瑕疵或者容易腐烂、变质的，经委托人同意，行纪人可以处分该物；不能与委托人及时取得联系的，行纪人可以合理处分。\n第九百五十五条　行纪人低于委托人指定的价格卖出或者高于委托人指定的价格买入的，应当经委托人同意；未经委托人同意，行纪人补偿其差额的，该买卖对委托人发生效力', 734, '{\"level\": null, \"title\": null, \"chunk_index\": 108}', 'bge-large-zh-v1.5', '2026-09-25 17:05:01');
INSERT INTO `chunk` VALUES ('b0139449-778c-421c-91df-762d1382a65e', 'd9d7dc15-8041-43b8-9f75-f112fe3ae003', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 2, '（三）市场监督管理部门负责对纳入工业产品生产许可证管理目录的危险化学品及其包装物、容器（包括罐体，不包括储存危险化学品的固定式大型储罐，下同）实施工业产品生产许可证管理和产品质量监督，签发危险化学品生产、储存、经营、运输企业营业执照。\n（四）生态环境主管部门负责废弃危险化学品处置的监督管理，组织危险化学品的生态环境危害性鉴定和生态环境风险程度评估，负责新化学物质环境管理登记，依照职责分工调查相关危险化学品环境污染事故和生态破坏事件，负责危险化学品事故现场的生态环境应急监测。\n（五）交通运输主管部门负责危险化学品道路、水路运输活动安全监督管理，负责危险化学品道路运输、水路运输的许可或者备案，以及运输工具的安全监督管理，负责危险化学品道路运输企业、水路运输企业驾驶人员、船员、装卸管理人员、押运人员、申报人员、集装箱装箱现场检查员的资格认定。铁路监管部门负责危险化学品铁路运输及其运输工具的安全监督管理。民用航空主管部门负责危险化学品航空运输以及航空运输企业及其运输工具的安全监督管理。邮政管理部门负责依法查处寄递危险化学品的行为。\n（六）卫生健康主管部门负责危险化学品毒性鉴定的管理，负责危险化学品单位职业健康的监督管理，负责组织、协调危险化学品事故受伤人员的医疗卫生救援工作。\n（七）自然资源主管部门负责在编制国土空间规划时，将危险化学品建设项目及化工园区、储存危险化学品的专门区域和周边安全控制距离等有关内容按照程序纳入当地国土空间规划，并做好规划监督实施。\n（八）工业和信息化主管部门依照职责负责危险化学品生产、储存的相关行业规划和布局，组织制定化工园区的建设标准和认定管理办法，并推动落后工艺、产能退出。\n（九）海关负责依法对进出口危险化学品及其包装实施检验。\n（十）其他部门依照各自职责履行危险化学品安全监督管理职责', 766, '{\"level\": null, \"title\": null, \"chunk_index\": 2}', 'bge-large-zh-v1.5', '2026-09-25 17:04:46');
INSERT INTO `chunk` VALUES ('b3194e88-403e-418e-b153-139f59fd7ef0', '821ce1fd-178d-4a7e-ab92-3deff1488ce2', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 64, '第二百八十六条　违反国家规定，对计算机信息系统功能进行删除、修改、增加、干扰，造成计算机信息系统不能正常运行，后果严重的，处五年以下有期徒刑或者拘役；后果特别严重的，处五年以上有期徒刑。\n违反国家规定，对计算机信息系统中存储、处理或者传输的数据和应用程序进行删除、修改、增加的操作，后果严重的，依照前款的规定处罚。\n故意制作、传播计算机病毒等破坏性程序，影响计算机系统正常运行，后果严重的，依照第一款的规定处罚。\n单位犯前三款罪的，对单位判处罚金，并对其直接负责的主管人员和其他直接责任人员，依照第一款的规定处罚。\n第二百八十六条之一　网络服务提供者不履行法律、行政法规规定的信息网络安全管理义务，经监管部门责令采取改正措施而拒不改正，有下列情形之一的，处三年以下有期徒刑、拘役或者管制，并处或者单处罚金：\n（一）致使违法信息大量传播的；\n（二）致使用户信息泄露，造成严重后果的；\n（三）致使刑事案件证据灭失，情节严重的；\n（四）有其他严重情节的。\n单位犯前款罪的，对单位判处罚金，并对其直接负责的主管人员和其他直接责任人员，依照前款的规定处罚。\n有前两款行为，同时构成其他犯罪的，依照处罚较重的规定定罪处罚。\n第二百八十七条　利用计算机实施金融诈骗、盗窃、贪污、挪用公款、窃取国家秘密或者其他犯罪的，依照本法有关规定定罪处罚。\n第二百八十七条之一　利用信息网络实施下列行为之一，情节严重的，处三年以下有期徒刑或者拘役，并处或者单处罚金：\n（一）设立用于实施诈骗、传授犯罪方法、制作或者销售违禁物品、管制物品等违法犯罪活动的网站、通讯群组的；\n（二）发布有关制作或者销售毒品、枪支、淫秽物品等违禁物品、管制物品或者其他违法犯罪信息的；\n（三）为实施诈骗等违法犯罪活动发布信息的。\n单位犯前款罪的，对单位判处罚金，并对其直接负责的主管人员和其他直接责任人员，依照第一款的规定处罚', 788, '{\"level\": null, \"title\": null, \"chunk_index\": 64}', 'bge-large-zh-v1.5', '2026-09-25 17:04:56');
INSERT INTO `chunk` VALUES ('b48bb907-689d-418f-8f29-de6598780dc7', 'b25ce095-dfba-4403-acf8-c58eb456ca4c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 101, '第八百八十七条　法律、行政法规对技术中介合同、技术培训合同另有规定的，依照其规定。\n第二十一章　保管合同\n第八百八十八条　保管合同是保管人保管寄存人交付的保管物，并返还该物的合同。\n寄存人到保管人处从事购物、就餐、住宿等活动，将物品存放在指定场所的，视为保管，但是当事人另有约定或者另有交易习惯的除外。\n第八百八十九条　寄存人应当按照约定向保管人支付保管费。\n当事人对保管费没有约定或者约定不明确，依据本法第五百一十条的规定仍不能确定的，视为无偿保管。\n第八百九十条　保管合同自保管物交付时成立，但是当事人另有约定的除外。\n第八百九十一条　寄存人向保管人交付保管物的，保管人应当出具保管凭证，但是另有交易习惯的除外。\n第八百九十二条　保管人应当妥善保管保管物。\n当事人可以约定保管场所或者方法。除紧急情况或者为维护寄存人利益外，不得擅自改变保管场所或者方法。\n第八百九十三条　寄存人交付的保管物有瑕疵或者根据保管物的性质需要采取特殊保管措施的，寄存人应当将有关情况告知保管人。寄存人未告知，致使保管物受损失的，保管人不承担赔偿责任；保管人因此受损失的，除保管人知道或者应当知道且未采取补救措施外，寄存人应当承担赔偿责任。\n第八百九十四条　保管人不得将保管物转交第三人保管，但是当事人另有约定的除外。\n保管人违反前款规定，将保管物转交第三人保管，造成保管物损失的，应当承担赔偿责任。\n第八百九十五条　保管人不得使用或者许可第三人使用保管物，但是当事人另有约定的除外。\n第八百九十六条　第三人对保管物主张权利的，除依法对保管物采取保全或者执行措施外，保管人应当履行向寄存人返还保管物的义务。\n第三人对保管人提起诉讼或者对保管物申请扣押的，保管人应当及时通知寄存人。\n第八百九十七条　保管期内，因保管人保管不善造成保管物毁损、灭失的，保管人应当承担赔偿责任', 775, '{\"level\": null, \"title\": null, \"chunk_index\": 101}', 'bge-large-zh-v1.5', '2026-09-25 17:05:01');
INSERT INTO `chunk` VALUES ('b5f508f5-91fe-4cae-ae72-fa981b41f1ca', '821ce1fd-178d-4a7e-ab92-3deff1488ce2', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 13, '第八十三条　有期徒刑的假释考验期限，为没有执行完毕的刑期；无期徒刑的假释考验期限为十年。\n假释考验期限，从假释之日起计算。\n第八十四条　被宣告假释的犯罪分子，应当遵守下列规定：\n（一）遵守法律、行政法规，服从监督；\n（二）按照监督机关的规定报告自己的活动情况；\n（三）遵守监督机关关于会客的规定；\n（四）离开所居住的市、县或者迁居，应当报经监督机关批准。\n第八十五条　对假释的犯罪分子，在假释考验期限内，依法实行社区矫正，如果没有本法第八十六条规定的情形，假释考验期满，就认为原判刑罚已经执行完毕，并公开予以宣告。\n第八十六条　被假释的犯罪分子，在假释考验期限内犯新罪，应当撤销假释，依照本法第七十一条的规定实行数罪并罚。\n在假释考验期限内，发现被假释的犯罪分子在判决宣告以前还有其他罪没有判决的，应当撤销假释，依照本法第七十条的规定实行数罪并罚。\n被假释的犯罪分子，在假释考验期限内，有违反法律、行政法规或者国务院有关部门关于假释的监督管理规定的行为，尚未构成新的犯罪的，应当依照法定程序撤销假释，收监执行未执行完毕的刑罚。\n第八节　时　　效\n第八十七条　犯罪经过下列期限不再追诉：\n（一）法定最高刑为不满五年有期徒刑的，经过五年；\n（二）法定最高刑为五年以上不满十年有期徒刑的，经过十年；\n（三）法定最高刑为十年以上有期徒刑的，经过十五年；\n（四）法定最高刑为无期徒刑、死刑的，经过二十年。如果二十年以后认为必须追诉的，须报请最高人民检察院核准。\n第八十八条　在人民检察院、公安机关、国家安全机关立案侦查或者在人民法院受理案件以后，逃避侦查或者审判的，不受追诉期限的限制。\n被害人在追诉期限内提出控告，人民法院、人民检察院、公安机关应当立案而不予立案的，不受追诉期限的限制。\n第八十九条　追诉期限从犯罪之日起计算；犯罪行为有连续或者继续状态的，从犯罪行为终了之日起计算', 786, '{\"level\": null, \"title\": null, \"chunk_index\": 13}', 'bge-large-zh-v1.5', '2026-09-25 17:04:56');
INSERT INTO `chunk` VALUES ('b83deaa5-baa9-47ed-8d69-cf918942c71d', '821ce1fd-178d-4a7e-ab92-3deff1488ce2', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 18, '犯前款罪并实施杀人、爆炸、绑架等犯罪的，依照数罪并罚的规定处罚。\n第一百二十条之一　资助恐怖活动组织、实施恐怖活动的个人的，或者资助恐怖活动培训的，处五年以下有期徒刑、拘役、管制或者剥夺政治权利，并处罚金；情节严重的，处五年以上有期徒刑，并处罚金或者没收财产。\n为恐怖活动组织、实施恐怖活动或者恐怖活动培训招募、运送人员的，依照前款的规定处罚。\n单位犯前两款罪的，对单位判处罚金，并对其直接负责的主管人员和其他直接责任人员，依照第一款的规定处罚。\n第一百二十条之二　有下列情形之一的，处五年以下有期徒刑、拘役、管制或者剥夺政治权利，并处罚金；情节严重的，处五年以上有期徒刑，并处罚金或者没收财产：\n（一）为实施恐怖活动准备凶器、危险物品或者其他工具的；\n（二）组织恐怖活动培训或者积极参加恐怖活动培训的；\n（三）为实施恐怖活动与境外恐怖活动组织或者人员联络的；\n（四）为实施恐怖活动进行策划或者其他准备的。\n有前款行为，同时构成其他犯罪的，依照处罚较重的规定定罪处罚。\n第一百二十条之三　以制作、散发宣扬恐怖主义、极端主义的图书、音频视频资料或者其他物品，或者通过讲授、发布信息等方式宣扬恐怖主义、极端主义的，或者煽动实施恐怖活动的，处五年以下有期徒刑、拘役、管制或者剥夺政治权利，并处罚金；情节严重的，处五年以上有期徒刑，并处罚金或者没收财产。\n第一百二十条之四　利用极端主义煽动、胁迫群众破坏国家法律确立的婚姻、司法、教育、社会管理等制度实施的，处三年以下有期徒刑、拘役或者管制，并处罚金；情节严重的，处三年以上七年以下有期徒刑，并处罚金；情节特别严重的，处七年以上有期徒刑，并处罚金或者没收财产。\n第一百二十条之五　以暴力、胁迫等方式强制他人在公共场所穿着、佩戴宣扬恐怖主义、极端主义服饰、标志的，处三年以下有期徒刑、拘役或者管制，并处罚金', 773, '{\"level\": null, \"title\": null, \"chunk_index\": 18}', 'bge-large-zh-v1.5', '2026-09-25 17:04:56');
INSERT INTO `chunk` VALUES ('b975e8bc-6981-4c26-8314-cd337bc89d39', 'b25ce095-dfba-4403-acf8-c58eb456ca4c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 77, '第六百七十八条　借款人可以在还款期限届满前向贷款人申请展期；贷款人同意的，可以展期。\n第六百七十九条　自然人之间的借款合同，自贷款人提供借款时成立。\n第六百八十条　禁止高利放贷，借款的利率不得违反国家有关规定。\n借款合同对支付利息没有约定的，视为没有利息。\n借款合同对支付利息约定不明确，当事人不能达成补充协议的，按照当地或者当事人的交易方式、交易习惯、市场利率等因素确定利息；自然人之间借款的，视为没有利息。\n第十三章　保证合同\n第一节　一般规定\n第六百八十一条　保证合同是为保障债权的实现，保证人和债权人约定，当债务人不履行到期债务或者发生当事人约定的情形时，保证人履行债务或者承担责任的合同。\n第六百八十二条　保证合同是主债权债务合同的从合同。主债权债务合同无效的，保证合同无效，但是法律另有规定的除外。\n保证合同被确认无效后，债务人、保证人、债权人有过错的，应当根据其过错各自承担相应的民事责任。\n第六百八十三条　机关法人不得为保证人，但是经国务院批准为使用外国政府或者国际经济组织贷款进行转贷的除外。\n以公益为目的的非营利法人、非法人组织不得为保证人。\n第六百八十四条　保证合同的内容一般包括被保证的主债权的种类、数额，债务人履行债务的期限，保证的方式、范围和期间等条款。\n第六百八十五条　保证合同可以是单独订立的书面合同，也可以是主债权债务合同中的保证条款。\n第三人单方以书面形式向债权人作出保证，债权人接收且未提出异议的，保证合同成立。\n第六百八十六条　保证的方式包括一般保证和连带责任保证。\n当事人在保证合同中对保证方式没有约定或者约定不明确的，按照一般保证承担保证责任。\n第六百八十七条　当事人在保证合同中约定，债务人不能履行债务时，由保证人承担保证责任的，为一般保证', 743, '{\"level\": null, \"title\": null, \"chunk_index\": 77}', 'bge-large-zh-v1.5', '2026-09-25 17:05:01');
INSERT INTO `chunk` VALUES ('b9a5ca92-cf71-4fe8-8d1a-990257ea33e4', 'b25ce095-dfba-4403-acf8-c58eb456ca4c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 42, '第三百八十四条　地役权人有下列情形之一的，供役地权利人有权解除地役权合同，地役权消灭：\n（一）违反法律规定或者合同约定，滥用地役权；\n（二）有偿利用供役地，约定的付款期限届满后在合理期限内经两次催告未支付费用。\n第三百八十五条　已经登记的地役权变更、转让或者消灭的，应当及时办理变更登记或者注销登记。\n第四分编　担保物权\n第十六章　一般规定\n第三百八十六条　担保物权人在债务人不履行到期债务或者发生当事人约定的实现担保物权的情形，依法享有就担保财产优先受偿的权利，但是法律另有规定的除外。\n第三百八十七条　债权人在借贷、买卖等民事活动中，为保障实现其债权，需要担保的，可以依照本法和其他法律的规定设立担保物权。\n第三人为债务人向债权人提供担保的，可以要求债务人提供反担保。反担保适用本法和其他法律的规定。\n第三百八十八条　设立担保物权，应当依照本法和其他法律的规定订立担保合同。担保合同包括抵押合同、质押合同和其他具有担保功能的合同。担保合同是主债权债务合同的从合同。主债权债务合同无效的，担保合同无效，但是法律另有规定的除外。\n担保合同被确认无效后，债务人、担保人、债权人有过错的，应当根据其过错各自承担相应的民事责任。\n第三百八十九条　担保物权的担保范围包括主债权及其利息、违约金、损害赔偿金、保管担保财产和实现担保物权的费用。当事人另有约定的，按照其约定。\n第三百九十条　担保期间，担保财产毁损、灭失或者被征收等，担保物权人可以就获得的保险金、赔偿金或者补偿金等优先受偿。被担保债权的履行期限未届满的，也可以提存该保险金、赔偿金或者补偿金等。\n第三百九十一条　第三人提供担保，未经其书面同意，债权人允许债务人转移全部或者部分债务的，担保人不再承担相应的担保责任', 733, '{\"level\": null, \"title\": null, \"chunk_index\": 42}', 'bge-large-zh-v1.5', '2026-09-25 17:05:01');
INSERT INTO `chunk` VALUES ('b9fbc623-732d-4f2f-a37e-4a213618f445', 'b25ce095-dfba-4403-acf8-c58eb456ca4c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 23, '第一百九十四条　在诉讼时效期间的最后六个月内，因下列障碍，不能行使请求权的，诉讼时效中止：\n（一）不可抗力；\n（二）无民事行为能力人或者限制民事行为能力人没有法定代理人，或者法定代理人死亡、丧失民事行为能力、丧失代理权；\n（三）继承开始后未确定继承人或者遗产管理人；\n（四）权利人被义务人或者其他人控制；\n（五）其他导致权利人不能行使请求权的障碍。\n自中止时效的原因消除之日起满六个月，诉讼时效期间届满。\n第一百九十五条　有下列情形之一的，诉讼时效中断，从中断、有关程序终结时起，诉讼时效期间重新计算：\n（一）权利人向义务人提出履行请求；\n（二）义务人同意履行义务；\n（三）权利人提起诉讼或者申请仲裁；\n（四）与提起诉讼或者申请仲裁具有同等效力的其他情形。\n第一百九十六条　下列请求权不适用诉讼时效的规定：\n（一）请求停止侵害、排除妨碍、消除危险；\n（二）不动产物权和登记的动产物权的权利人请求返还财产；\n（三）请求支付抚养费、赡养费或者扶养费；\n（四）依法不适用诉讼时效的其他请求权。\n第一百九十七条　诉讼时效的期间、计算方法以及中止、中断的事由由法律规定，当事人约定无效。\n当事人对诉讼时效利益的预先放弃无效。\n第一百九十八条　法律对仲裁时效有规定的，依照其规定；没有规定的，适用诉讼时效的规定。\n第一百九十九条　法律规定或者当事人约定的撤销权、解除权等权利的存续期间，除法律另有规定外，自权利人知道或者应当知道权利产生之日起计算，不适用有关诉讼时效中止、中断和延长的规定。存续期间届满，撤销权、解除权等权利消灭。\n第十章　期间计算\n第二百条　民法所称的期间按照公历年、月、日、小时计算。\n第二百零一条　按照年、月、日计算期间的，开始的当日不计入，自下一日开始计算。\n按照小时计算期间的，自法律规定或者当事人约定的时间开始计算', 765, '{\"level\": null, \"title\": null, \"chunk_index\": 23}', 'bge-large-zh-v1.5', '2026-09-25 17:05:01');
INSERT INTO `chunk` VALUES ('ba13791c-e544-46aa-9598-7188fb3c94e0', '16cbea7e-7e36-4f31-afb5-63892345d29c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 53, '监察机关对于撤销案件的决定应当向被调查人宣布，由其在《撤销案件决定书》上签名、捺指印，立即解除监察强制措施，并通知其所在单位。\n撤销案件后又发现重要事实或者有充分证据，认为被调查人有违法犯罪事实需要追究法律责任的，应当重新立案调查。\n第二百三十八条　对于涉嫌行贿等犯罪的非监察对象，案件调查终结后依法移送起诉。综合考虑行为性质、手段、后果、时间节点、认罪悔罪态度等具体情况，对于情节较轻，经审批不予移送起诉的，应当采取批评教育、责令具结悔过等方式处置；应当给予行政处罚的，依法移送有关行政执法部门。\n对于有行贿行为的涉案单位和人员，按规定记入相关信息记录，可以作为信用评价的依据。\n对于涉案单位和人员通过行贿等非法手段取得的财物及孳息，应当依法予以没收、追缴或者责令退赔，不得没收、追缴与案件无关的财物。对于涉案单位和人员主动上交的涉案财物，应当严格核查，确系违法所得及孳息的，依法予以没收、追缴。对于违法取得的经营资格、资质、荣誉、奖励、学历学位、职称或者职务职级等其他不正当利益，应当建议有关机关、单位、组织依照法律法规及有关规定予以纠正处理。\n第二百三十九条　对查封、扣押、冻结的涉嫌职务犯罪所得财物及孳息应当妥善保管，并制作《移送司法机关涉案财物清单》随案移送人民检察院。对作为证据使用的实物应当随案移送；对不宜移送的，应当将清单、照片和其他证明文件随案移送。\n对于移送人民检察院的涉案财物，价值不明的，应当在移送起诉前委托进行价格认定。在价格认定过程中，需要对涉案财物先行作出真伪鉴定或者出具技术、质量检测报告的，应当委托有关鉴定机构或者检测机构进行真伪鉴定或者技术、质量检测。\n对不属于犯罪所得但属于违法取得的财物及孳息，应当依法予以没收、追缴或者责令退赔，并出具有关法律文书。\n对经认定不属于违法所得的财物及孳息，应当及时予以返还，并办理签收手续', 780, '{\"level\": null, \"title\": null, \"chunk_index\": 53}', 'bge-large-zh-v1.5', '2026-09-25 17:04:49');
INSERT INTO `chunk` VALUES ('ba6cdfeb-c243-4dee-aa5f-78df6142b873', 'b25ce095-dfba-4403-acf8-c58eb456ca4c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 71, '买受人在合理期限内未通知或者自收到标的物之日起二年内未通知出卖人的，视为标的物的数量或者质量符合约定；但是，对标的物有质量保证期的，适用质量保证期，不适用该二年的规定。\n出卖人知道或者应当知道提供的标的物不符合约定的，买受人不受前两款规定的通知时间的限制。\n第六百二十二条　当事人约定的检验期限过短，根据标的物的性质和交易习惯，买受人在检验期限内难以完成全面检验的，该期限仅视为买受人对标的物的外观瑕疵提出异议的期限。\n约定的检验期限或者质量保证期短于法律、行政法规规定期限的，应当以法律、行政法规规定的期限为准。\n第六百二十三条　当事人对检验期限未作约定，买受人签收的送货单、确认单等载明标的物数量、型号、规格的，推定买受人已经对数量和外观瑕疵进行检验，但是有相关证据足以推翻的除外。\n第六百二十四条　出卖人依照买受人的指示向第三人交付标的物，出卖人和买受人约定的检验标准与买受人和第三人约定的检验标准不一致的，以出卖人和买受人约定的检验标准为准。\n第六百二十五条　依照法律、行政法规的规定或者按照当事人的约定，标的物在有效使用年限届满后应予回收的，出卖人负有自行或者委托第三人对标的物予以回收的义务。\n第六百二十六条　买受人应当按照约定的数额和支付方式支付价款。对价款的数额和支付方式没有约定或者约定不明确的，适用本法第五百一十条、第五百一十一条第二项和第五项的规定。\n第六百二十七条　买受人应当按照约定的地点支付价款。对支付地点没有约定或者约定不明确，依据本法第五百一十条的规定仍不能确定的，买受人应当在出卖人的营业地支付；但是，约定支付价款以交付标的物或者交付提取标的物单证为条件的，在交付标的物或者交付提取标的物单证的所在地支付。\n第六百二十八条　买受人应当按照约定的时间支付价款', 745, '{\"level\": null, \"title\": null, \"chunk_index\": 71}', 'bge-large-zh-v1.5', '2026-09-25 17:05:01');
INSERT INTO `chunk` VALUES ('bb45aaf1-b410-4216-8ed2-449e2c2f01df', 'b25ce095-dfba-4403-acf8-c58eb456ca4c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 5, '未成年人的父母已经死亡或者没有监护能力的，由下列有监护能力的人按顺序担任监护人：\n（一）祖父母、外祖父母；\n（二）兄、姐；\n（三）其他愿意担任监护人的个人或者组织，但是须经未成年人住所地的居民委员会、村民委员会或者民政部门同意。\n第二十八条　无民事行为能力或者限制民事行为能力的成年人，由下列有监护能力的人按顺序担任监护人：\n（一）配偶；\n（二）父母、子女；\n（三）其他近亲属；\n（四）其他愿意担任监护人的个人或者组织，但是须经被监护人住所地的居民委员会、村民委员会或者民政部门同意。\n第二十九条　被监护人的父母担任监护人的，可以通过遗嘱指定监护人。\n第三十条　依法具有监护资格的人之间可以协议确定监护人。协议确定监护人应当尊重被监护人的真实意愿。\n第三十一条　对监护人的确定有争议的，由被监护人住所地的居民委员会、村民委员会或者民政部门指定监护人，有关当事人对指定不服的，可以向人民法院申请指定监护人；有关当事人也可以直接向人民法院申请指定监护人。\n居民委员会、村民委员会、民政部门或者人民法院应当尊重被监护人的真实意愿，按照最有利于被监护人的原则在依法具有监护资格的人中指定监护人。\n依据本条第一款规定指定监护人前，被监护人的人身权利、财产权利以及其他合法权益处于无人保护状态的，由被监护人住所地的居民委员会、村民委员会、法律规定的有关组织或者民政部门担任临时监护人。\n监护人被指定后，不得擅自变更；擅自变更的，不免除被指定的监护人的责任。\n第三十二条　没有依法具有监护资格的人的，监护人由民政部门担任，也可以由具备履行监护职责条件的被监护人住所地的居民委员会、村民委员会担任。\n第三十三条　具有完全民事行为能力的成年人，可以与其近亲属、其他愿意担任监护人的个人或者组织事先协商，以书面形式确定自己的监护人，在自己丧失或者部分丧失民事行为能力时，由该监护人履行监护职责', 786, '{\"level\": null, \"title\": null, \"chunk_index\": 5}', 'bge-large-zh-v1.5', '2026-09-25 17:05:01');
INSERT INTO `chunk` VALUES ('bb705889-9db9-47ee-9115-6f26ccc9375d', 'b25ce095-dfba-4403-acf8-c58eb456ca4c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 11, '第二节　营利法人\n第七十六条　以取得利润并分配给股东等出资人为目的成立的法人，为营利法人。\n营利法人包括有限责任公司、股份有限公司和其他企业法人等。\n第七十七条　营利法人经依法登记成立。\n第七十八条　依法设立的营利法人，由登记机关发给营利法人营业执照。营业执照签发日期为营利法人的成立日期。\n第七十九条　设立营利法人应当依法制定法人章程。\n第八十条　营利法人应当设权力机构。\n权力机构行使修改法人章程，选举或者更换执行机构、监督机构成员，以及法人章程规定的其他职权。\n第八十一条　营利法人应当设执行机构。\n执行机构行使召集权力机构会议，决定法人的经营计划和投资方案，决定法人内部管理机构的设置，以及法人章程规定的其他职权。\n执行机构为董事会或者执行董事的，董事长、执行董事或者经理按照法人章程的规定担任法定代表人；未设董事会或者执行董事的，法人章程规定的主要负责人为其执行机构和法定代表人。\n第八十二条　营利法人设监事会或者监事等监督机构的，监督机构依法行使检查法人财务，监督执行机构成员、高级管理人员执行法人职务的行为，以及法人章程规定的其他职权。\n第八十三条　营利法人的出资人不得滥用出资人权利损害法人或者其他出资人的利益；滥用出资人权利造成法人或者其他出资人损失的，应当依法承担民事责任。\n营利法人的出资人不得滥用法人独立地位和出资人有限责任损害法人债权人的利益；滥用法人独立地位和出资人有限责任，逃避债务，严重损害法人债权人的利益的，应当对法人债务承担连带责任。\n第八十四条　营利法人的控股出资人、实际控制人、董事、监事、高级管理人员不得利用其关联关系损害法人的利益；利用关联关系造成法人损失的，应当承担赔偿责任。\n第八十五条　营利法人的权力机构、执行机构作出决议的会议召集程序、表决方式违反法律、行政法规、法人章程，或者决议内容违反法人章程的，营利法人的出资人可以请求人民法院撤销该决议', 798, '{\"level\": null, \"title\": null, \"chunk_index\": 11}', 'bge-large-zh-v1.5', '2026-09-25 17:05:01');
INSERT INTO `chunk` VALUES ('bb82b736-32b0-4e5e-ac5e-d278417c73f8', 'd9d7dc15-8041-43b8-9f75-f112fe3ae003', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 10, '第三十七条　生产、储存危险化学品的单位，应当根据其生产、储存的危险化学品的种类和危险特性，在作业场所设置相应的监测、监控、通风、防晒、调温、防火、灭火、防爆、泄压、防毒、中和、防潮、防雷、防静电、防腐、防泄漏以及防护围堤或者隔离操作等安全设施、设备，并按照国家标准、行业标准或者国家有关规定对安全设施、设备进行经常性维护、保养，保证安全设施、设备的正常使用。\n生产、储存危险化学品的单位，应当在其作业场所和安全设施、设备上设置明显的安全警示标志。\n第三十八条　生产、储存危险化学品的单位，应当在其作业场所设置通信、报警装置，并保证处于适用状态。\n生产、储存危险化学品的单位，不得关闭、破坏直接关系生产安全的监控、报警、防护、救生设施、设备，或者以其他任何方式影响其正常使用，不得篡改、隐瞒、销毁其相关数据、信息。\n第三十九条　生产、储存危险化学品的企业，应当委托具备国家规定的资质条件的机构，对本企业的安全生产条件每三年进行一次安全评价，提出安全评价报告。安全评价报告的内容应当包括对安全生产条件存在的问题进行整改的方案和整改完成后的结论性意见。安全评价报告应当按照规定向社会公开。\n生产、储存危险化学品的企业，应当将安全评价报告以及整改方案的落实情况报所在地县级人民政府应急管理部门备案。\n在港区内储存、装卸危险化学品的企业，应当依照本条第一款要求进行安全评价，安全评价报告以及整改方案的落实情况按照规定报港口行政管理部门或者所在地县级人民政府应急管理部门备案', 631, '{\"level\": null, \"title\": null, \"chunk_index\": 10}', 'bge-large-zh-v1.5', '2026-09-25 17:04:46');
INSERT INTO `chunk` VALUES ('bbd42300-ead0-4e67-b5c1-6b999c08d511', 'b25ce095-dfba-4403-acf8-c58eb456ca4c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 22, '第一百八十三条　因保护他人民事权益使自己受到损害的，由侵权人承担民事责任，受益人可以给予适当补偿。没有侵权人、侵权人逃逸或者无力承担民事责任，受害人请求补偿的，受益人应当给予适当补偿。\n第一百八十四条　因自愿实施紧急救助行为造成受助人损害的，救助人不承担民事责任。\n第一百八十五条　侵害英雄烈士等的姓名、肖像、名誉、荣誉，损害社会公共利益的，应当承担民事责任。\n第一百八十六条　因当事人一方的违约行为，损害对方人身权益、财产权益的，受损害方有权选择请求其承担违约责任或者侵权责任。\n第一百八十七条　民事主体因同一行为应当承担民事责任、行政责任和刑事责任的，承担行政责任或者刑事责任不影响承担民事责任；民事主体的财产不足以支付的，优先用于承担民事责任。\n第九章　诉讼时效\n第一百八十八条　向人民法院请求保护民事权利的诉讼时效期间为三年。法律另有规定的，依照其规定。\n诉讼时效期间自权利人知道或者应当知道权利受到损害以及义务人之日起计算。法律另有规定的，依照其规定。但是，自权利受到损害之日起超过二十年的，人民法院不予保护，有特殊情况的，人民法院可以根据权利人的申请决定延长。\n第一百八十九条　当事人约定同一债务分期履行的，诉讼时效期间自最后一期履行期限届满之日起计算。\n第一百九十条　无民事行为能力人或者限制民事行为能力人对其法定代理人的请求权的诉讼时效期间，自该法定代理终止之日起计算。\n第一百九十一条　未成年人遭受性侵害的损害赔偿请求权的诉讼时效期间，自受害人年满十八周岁之日起计算。\n第一百九十二条　诉讼时效期间届满的，义务人可以提出不履行义务的抗辩。\n诉讼时效期间届满后，义务人同意履行的，不得以诉讼时效期间届满为由抗辩；义务人已经自愿履行的，不得请求返还。\n第一百九十三条　人民法院不得主动适用诉讼时效的规定', 758, '{\"level\": null, \"title\": null, \"chunk_index\": 22}', 'bge-large-zh-v1.5', '2026-09-25 17:05:01');
INSERT INTO `chunk` VALUES ('bc30f217-8a66-4e41-8035-8cb49339ca62', 'b25ce095-dfba-4403-acf8-c58eb456ca4c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 107, '第九百四十二条　物业服务人应当按照约定和物业的使用性质，妥善维修、养护、清洁、绿化和经营管理物业服务区域内的业主共有部分，维护物业服务区域内的基本秩序，采取合理措施保护业主的人身、财产安全。\n对物业服务区域内违反有关治安、环保、消防等法律法规的行为，物业服务人应当及时采取合理措施制止、向有关行政主管部门报告并协助处理。\n第九百四十三条　物业服务人应当定期将服务的事项、负责人员、质量要求、收费项目、收费标准、履行情况，以及维修资金使用情况、业主共有部分的经营与收益情况等以合理方式向业主公开并向业主大会、业主委员会报告。\n第九百四十四条　业主应当按照约定向物业服务人支付物业费。物业服务人已经按照约定和有关规定提供服务的，业主不得以未接受或者无需接受相关物业服务为由拒绝支付物业费。\n业主违反约定逾期不支付物业费的，物业服务人可以催告其在合理期限内支付；合理期限届满仍不支付的，物业服务人可以提起诉讼或者申请仲裁。\n物业服务人不得采取停止供电、供水、供热、供燃气等方式催交物业费。\n第九百四十五条　业主装饰装修房屋的，应当事先告知物业服务人，遵守物业服务人提示的合理注意事项，并配合其进行必要的现场检查。\n业主转让、出租物业专有部分、设立居住权或者依法改变共有部分用途的，应当及时将相关情况告知物业服务人。\n第九百四十六条　业主依照法定程序共同决定解聘物业服务人的，可以解除物业服务合同。决定解聘的，应当提前六十日书面通知物业服务人，但是合同对通知期限另有约定的除外。\n依据前款规定解除合同造成物业服务人损失的，除不可归责于业主的事由外，业主应当赔偿损失。\n第九百四十七条　物业服务期限届满前，业主依法共同决定续聘的，应当与原物业服务人在合同期限届满前续订物业服务合同', 735, '{\"level\": null, \"title\": null, \"chunk_index\": 107}', 'bge-large-zh-v1.5', '2026-09-25 17:05:01');
INSERT INTO `chunk` VALUES ('bcc5f88d-893e-4eaa-8554-dacecd521eea', 'd9d7dc15-8041-43b8-9f75-f112fe3ae003', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 29, '第一百零三条　有下列情形之一的，由负有危险化学品安全监督管理职责的部门按照职责分工责令限期改正，处五万元以上十万元以下的罚款；逾期不改正的，责令停产停业整顿直至由原发证机关吊销其相关许可证件，并处十万元以上二十万元以下的罚款，对其直接负责的主管人员和其他直接责任人员处二万元以上五万元以下的罚款；相关许可证件被吊销的，由市场监督管理部门责令其办理经营范围变更登记或者吊销其营业执照：\n（一）未按照国家有关规定对危险化学品重大危险源登记建档，未进行定期检测、评估、监控，未制定应急预案，或者未建立重大危险源安全责任制；\n（二）对重复使用的危险化学品包装物、容器，在重复使用前不进行检查，或者使用存在安全隐患的危险化学品包装物、容器；\n（三）未根据其生产、储存的危险化学品的种类和危险特性，在作业场所设置相关安全设施、设备，或者未按照国家标准、行业标准或者国家有关规定对安全设施、设备进行经常性维护、保养；\n（四）未依照本法规定对其安全生产条件定期进行安全评价；\n（五）未将危险化学品储存在专用储存场所内，或者未将剧毒化学品以及储存数量构成重大危险源的其他危险化学品在专用储存场所内单独存放；\n（六）危险化学品的储存方式、方法或者储存数量不符合国家标准或者国家有关规定；\n（七）危险化学品专用储存场所不符合国家标准、行业标准的要求；\n（八）未对危险化学品专用储存场所的安全设施、设备定期进行检测、检验，或者经检测、检验不合格，没有停止使用并按照规定予以维修或者更换；\n（九）生产、储存危险化学品的企业以及使用危险化学品从事生产的企业未建立安全风险分级管控制度，未开展安全风险辨识评估，未按照安全风险分级采取相应安全管控措施，或者工艺、设施、设备、原料等发生变更时未重新进行安全风险辨识评估。\n从事危险化学品仓储经营的港口经营人有前款规定情形的，由港口行政管理部门依照前款规定予以处理、处罚', 792, '{\"level\": null, \"title\": null, \"chunk_index\": 29}', 'bge-large-zh-v1.5', '2026-09-25 17:04:46');
INSERT INTO `chunk` VALUES ('bda16d75-5b47-449c-ac74-9ad65b7fe5aa', 'b25ce095-dfba-4403-acf8-c58eb456ca4c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 26, '第二百二十一条　当事人签订买卖房屋的协议或者签订其他不动产物权的协议，为保障将来实现物权，按照约定可以向登记机构申请预告登记。预告登记后，未经预告登记的权利人同意，处分该不动产的，不发生物权效力。\n预告登记后，债权消灭或者自能够进行不动产登记之日起九十日内未申请登记的，预告登记失效。\n第二百二十二条　当事人提供虚假材料申请登记，造成他人损害的，应当承担赔偿责任。\n因登记错误，造成他人损害的，登记机构应当承担赔偿责任。登记机构赔偿后，可以向造成登记错误的人追偿。\n第二百二十三条　不动产登记费按件收取，不得按照不动产的面积、体积或者价款的比例收取。\n第二节　动产交付\n第二百二十四条　动产物权的设立和转让，自交付时发生效力，但是法律另有规定的除外。\n第二百二十五条　船舶、航空器和机动车等的物权的设立、变更、转让和消灭，未经登记，不得对抗善意第三人。\n第二百二十六条　动产物权设立和转让前，权利人已经占有该动产的，物权自民事法律行为生效时发生效力。\n第二百二十七条　动产物权设立和转让前，第三人占有该动产的，负有交付义务的人可以通过转让请求第三人返还原物的权利代替交付。\n第二百二十八条　动产物权转让时，当事人又约定由出让人继续占有该动产的，物权自该约定生效时发生效力。\n第三节　其他规定\n第二百二十九条　因人民法院、仲裁机构的法律文书或者人民政府的征收决定等，导致物权设立、变更、转让或者消灭的，自法律文书或者征收决定等生效时发生效力。\n第二百三十条　因继承取得物权的，自继承开始时发生效力。\n第二百三十一条　因合法建造、拆除房屋等事实行为设立或者消灭物权的，自事实行为成就时发生效力。\n第二百三十二条　处分依照本节规定享有的不动产物权，依照法律规定需要办理登记的，未经登记，不发生物权效力。\n第三章　物权的保护\n第二百三十三条　物权受到侵害的，权利人可以通过和解、调解、仲裁、诉讼等途径解决', 798, '{\"level\": null, \"title\": null, \"chunk_index\": 26}', 'bge-large-zh-v1.5', '2026-09-25 17:05:01');
INSERT INTO `chunk` VALUES ('bdcad84c-5a84-4c33-aca7-7bb7c0ac43b5', 'b25ce095-dfba-4403-acf8-c58eb456ca4c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 130, '继承人协商同意的，也可以不均等。\n第一千一百三十一条　对继承人以外的依靠被继承人扶养的人，或者继承人以外的对被继承人扶养较多的人，可以分给适当的遗产。\n第一千一百三十二条　继承人应当本着互谅互让、和睦团结的精神，协商处理继承问题。遗产分割的时间、办法和份额，由继承人协商确定；协商不成的，可以由人民调解委员会调解或者向人民法院提起诉讼。\n第三章　遗嘱继承和遗赠\n第一千一百三十三条　自然人可以依照本法规定立遗嘱处分个人财产，并可以指定遗嘱执行人。\n自然人可以立遗嘱将个人财产指定由法定继承人中的一人或者数人继承。\n自然人可以立遗嘱将个人财产赠与国家、集体或者法定继承人以外的组织、个人。\n自然人可以依法设立遗嘱信托。\n第一千一百三十四条　自书遗嘱由遗嘱人亲笔书写，签名，注明年、月、日。\n第一千一百三十五条　代书遗嘱应当有两个以上见证人在场见证，由其中一人代书，并由遗嘱人、代书人和其他见证人签名，注明年、月、日。\n第一千一百三十六条　打印遗嘱应当有两个以上见证人在场见证。遗嘱人和见证人应当在遗嘱每一页签名，注明年、月、日。\n第一千一百三十七条　以录音录像形式立的遗嘱，应当有两个以上见证人在场见证。遗嘱人和见证人应当在录音录像中记录其姓名或者肖像，以及年、月、日。\n第一千一百三十八条　遗嘱人在危急情况下，可以立口头遗嘱。口头遗嘱应当有两个以上见证人在场见证。危急情况消除后，遗嘱人能够以书面或者录音录像形式立遗嘱的，所立的口头遗嘱无效。\n第一千一百三十九条　公证遗嘱由遗嘱人经公证机构办理。\n第一千一百四十条　下列人员不能作为遗嘱见证人：\n（一）无民事行为能力人、限制民事行为能力人以及其他不具有见证能力的人；\n（二）继承人、受遗赠人；\n（三）与继承人、受遗赠人有利害关系的人。\n第一千一百四十一条　遗嘱应当为缺乏劳动能力又没有生活来源的继承人保留必要的遗产份额', 784, '{\"level\": null, \"title\": null, \"chunk_index\": 130}', 'bge-large-zh-v1.5', '2026-09-25 17:05:01');
INSERT INTO `chunk` VALUES ('be50900e-6b5c-4e3d-a8f6-37d9f433e95f', 'b25ce095-dfba-4403-acf8-c58eb456ca4c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 24, '第二百零二条　按照年、月计算期间的，到期月的对应日为期间的最后一日；没有对应日的，月末日为期间的最后一日。\n第二百零三条　期间的最后一日是法定休假日的，以法定休假日结束的次日为期间的最后一日。\n期间的最后一日的截止时间为二十四时；有业务时间的，停止业务活动的时间为截止时间。\n第二百零四条　期间的计算方法依照本法的规定，但是法律另有规定或者当事人另有约定的除外。\n第二编　物　　权\n第一分编　通　　则\n第一章　一般规定\n第二百零五条　本编调整因物的归属和利用产生的民事关系。\n第二百零六条　国家坚持和完善公有制为主体、多种所有制经济共同发展，按劳分配为主体、多种分配方式并存，社会主义市场经济体制等社会主义基本经济制度。\n国家巩固和发展公有制经济，鼓励、支持和引导非公有制经济的发展。\n国家实行社会主义市场经济，保障一切市场主体的平等法律地位和发展权利。\n第二百零七条　国家、集体、私人的物权和其他权利人的物权受法律平等保护，任何组织或者个人不得侵犯。\n第二百零八条　不动产物权的设立、变更、转让和消灭，应当依照法律规定登记。动产物权的设立和转让，应当依照法律规定交付。\n第二章　物权的设立、变更、转让和消灭\n第一节　不动产登记\n第二百零九条　不动产物权的设立、变更、转让和消灭，经依法登记，发生效力；未经登记，不发生效力，但是法律另有规定的除外。\n依法属于国家所有的自然资源，所有权可以不登记。\n第二百一十条　不动产登记，由不动产所在地的登记机构办理。\n国家对不动产实行统一登记制度。统一登记的范围、登记机构和登记办法，由法律、行政法规规定。\n第二百一十一条　当事人申请登记，应当根据不同登记事项提供权属证明和不动产界址、面积等必要材料', 719, '{\"level\": null, \"title\": null, \"chunk_index\": 24}', 'bge-large-zh-v1.5', '2026-09-25 17:05:01');
INSERT INTO `chunk` VALUES ('be645cc0-d4b7-4601-879c-9fddc1ae14b4', '821ce1fd-178d-4a7e-ab92-3deff1488ce2', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 33, '银行或者其他金融机构的工作人员购买伪造的货币或者利用职务上的便利，以伪造的货币换取货币的，处三年以上十年以下有期徒刑，并处二万元以上二十万元以下罚金；数额巨大或者有其他严重情节的，处十年以上有期徒刑或者无期徒刑，并处二万元以上二十万元以下罚金或者没收财产；情节较轻的，处三年以下有期徒刑或者拘役，并处或者单处一万元以上十万元以下罚金。\n伪造货币并出售或者运输伪造的货币的，依照本法第一百七十条的规定定罪从重处罚。\n第一百七十二条　明知是伪造的货币而持有、使用，数额较大的，处三年以下有期徒刑或者拘役，并处或者单处一万元以上十万元以下罚金；数额巨大的，处三年以上十年以下有期徒刑，并处二万元以上二十万元以下罚金；数额特别巨大的，处十年以上有期徒刑，并处五万元以上五十万元以下罚金或者没收财产。\n第一百七十三条　变造货币，数额较大的，处三年以下有期徒刑或者拘役，并处或者单处一万元以上十万元以下罚金；数额巨大的，处三年以上十年以下有期徒刑，并处二万元以上二十万元以下罚金。\n第一百七十四条　未经国家有关主管部门批准，擅自设立商业银行、证券交易所、期货交易所、证券公司、期货经纪公司、保险公司或者其他金融机构的，处三年以下有期徒刑或者拘役，并处或者单处二万元以上二十万元以下罚金；情节严重的，处三年以上十年以下有期徒刑，并处五万元以上五十万元以下罚金。\n伪造、变造、转让商业银行、证券交易所、期货交易所、证券公司、期货经纪公司、保险公司或者其他金融机构的经营许可证或者批准文件的，依照前款的规定处罚。\n单位犯前两款罪的，对单位判处罚金，并对其直接负责的主管人员和其他直接责任人员，依照第一款的规定处罚', 697, '{\"level\": null, \"title\": null, \"chunk_index\": 33}', 'bge-large-zh-v1.5', '2026-09-25 17:04:56');
INSERT INTO `chunk` VALUES ('bebf4c1d-0332-40a5-a902-170ab0a741a7', '16cbea7e-7e36-4f31-afb5-63892345d29c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 66, '第七章　对监察机关和监察人员的监督\n第二百八十二条　监察机关和监察人员必须自觉坚持党的领导，在党组织的管理、监督下开展工作，依法接受本级人民代表大会及其常务委员会的监督，接受民主监督、司法监督、社会监督、舆论监督，加强内部监督制约机制建设，确保权力受到严格的约束和监督。\n第二百八十三条　各级监察委员会应当按照监察法第六十条第二款规定，由主要负责人在本级人民代表大会常务委员会全体会议上报告专项工作。\n在报告专项工作前，应当与本级人民代表大会有关专门委员会、常务委员会有关工作机构沟通协商，并配合开展专题调查研究等工作。各级人民代表大会常务委员会审议专项工作报告时，本级监察委员会应当根据要求派出负责人列席相关会议，听取意见。\n各级监察委员会应当认真研究处理本级人民代表大会常务委员会反馈的审议意见，并按照要求书面报告研究处理情况。本级人民代表大会常务委员会对专项工作报告作出决议的，监察委员会应当在决议规定的期限内，将执行决议的情况向其报告。\n第二百八十四条　各级监察委员会应当积极接受、配合本级人民代表大会常务委员会组织的执法检查。对本级人民代表大会常务委员会的执法检查报告，应当认真研究处理，并向其报告研究处理情况。本级人民代表大会常务委员会对执法检查报告作出决议的，监察委员会应当在决议规定的期限内，将执行决议的情况向其报告。\n第二百八十五条　各级监察委员会在本级人民代表大会常务委员会会议审议与监察工作有关的议案和报告时，应当派相关负责人到会听取意见，回答询问。\n本级人民代表大会常务委员会就与监察工作有关的重大问题，召开全体会议、联组会议或者分组会议进行专题询问的，监察委员会负责人应当到会，听取意见，回答询问。各级监察委员会应当及时向本级人民代表大会常务委员会提交专题询问中提出意见的研究处理情况报告。\n监察机关对依法交由监察机关答复的质询案应当按照要求进行答复', 788, '{\"level\": null, \"title\": null, \"chunk_index\": 66}', 'bge-large-zh-v1.5', '2026-09-25 17:04:49');
INSERT INTO `chunk` VALUES ('bec399b0-7a33-435e-9743-cf53817cea3e', '821ce1fd-178d-4a7e-ab92-3deff1488ce2', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 90, '第三百九十五条　国家工作人员的财产、支出明显超过合法收入，差额巨大的，可以责令该国家工作人员说明来源，不能说明来源的，差额部分以非法所得论，处五年以下有期徒刑或者拘役；差额特别巨大的，处五年以上十年以下有期徒刑。财产的差额部分予以追缴。\n国家工作人员在境外的存款，应当依照国家规定申报。数额较大、隐瞒不报的，处二年以下有期徒刑或者拘役；情节较轻的，由其所在单位或者上级主管机关酌情给予行政处分。\n第三百九十六条　国家机关、国有公司、企业、事业单位、人民团体，违反国家规定，以单位名义将国有资产集体私分给个人，数额较大的，对其直接负责的主管人员和其他直接责任人员，处三年以下有期徒刑或者拘役，并处或者单处罚金；数额巨大的，处三年以上七年以下有期徒刑，并处罚金。\n司法机关、行政执法机关违反国家规定，将应当上缴国家的罚没财物，以单位名义集体私分给个人的，依照前款的规定处罚。\n第九章　渎职罪\n第三百九十七条　国家机关工作人员滥用职权或者玩忽职守，致使公共财产、国家和人民利益遭受重大损失的，处三年以下有期徒刑或者拘役；情节特别严重的，处三年以上七年以下有期徒刑。本法另有规定的，依照规定。\n国家机关工作人员徇私舞弊，犯前款罪的，处五年以下有期徒刑或者拘役；情节特别严重的，处五年以上十年以下有期徒刑。本法另有规定的，依照规定。\n第三百九十八条　国家机关工作人员违反保守国家秘密法的规定，故意或者过失泄露国家秘密，情节严重的，处三年以下有期徒刑或者拘役；情节特别严重的，处三年以上七年以下有期徒刑。\n非国家机关工作人员犯前款罪的，依照前款的规定酌情处罚', 673, '{\"level\": null, \"title\": null, \"chunk_index\": 90}', 'bge-large-zh-v1.5', '2026-09-25 17:04:56');
INSERT INTO `chunk` VALUES ('bf367502-e2ab-44df-9db7-e018434e1c4e', 'b25ce095-dfba-4403-acf8-c58eb456ca4c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 18, '第一百五十二条　有下列情形之一的，撤销权消灭：\n（一）当事人自知道或者应当知道撤销事由之日起一年内、重大误解的当事人自知道或者应当知道撤销事由之日起九十日内没有行使撤销权；\n（二）当事人受胁迫，自胁迫行为终止之日起一年内没有行使撤销权；\n（三）当事人知道撤销事由后明确表示或者以自己的行为表明放弃撤销权。\n当事人自民事法律行为发生之日起五年内没有行使撤销权的，撤销权消灭。\n第一百五十三条　违反法律、行政法规的强制性规定的民事法律行为无效。但是，该强制性规定不导致该民事法律行为无效的除外。\n违背公序良俗的民事法律行为无效。\n第一百五十四条　行为人与相对人恶意串通，损害他人合法权益的民事法律行为无效。\n第一百五十五条　无效的或者被撤销的民事法律行为自始没有法律约束力。\n第一百五十六条　民事法律行为部分无效，不影响其他部分效力的，其他部分仍然有效。\n第一百五十七条　民事法律行为无效、被撤销或者确定不发生效力后，行为人因该行为取得的财产，应当予以返还；不能返还或者没有必要返还的，应当折价补偿。有过错的一方应当赔偿对方由此所受到的损失；各方都有过错的，应当各自承担相应的责任。法律另有规定的，依照其规定。\n第四节　民事法律行为的附条件和附期限\n第一百五十八条　民事法律行为可以附条件，但是根据其性质不得附条件的除外。附生效条件的民事法律行为，自条件成就时生效。附解除条件的民事法律行为，自条件成就时失效。\n第一百五十九条　附条件的民事法律行为，当事人为自己的利益不正当地阻止条件成就的，视为条件已经成就；不正当地促成条件成就的，视为条件不成就。\n第一百六十条　民事法律行为可以附期限，但是根据其性质不得附期限的除外。附生效期限的民事法律行为，自期限届至时生效。附终止期限的民事法律行为，自期限届满时失效。\n第七章　代　　理\n第一节　一般规定\n第一百六十一条　民事主体可以通过代理人实施民事法律行为', 799, '{\"level\": null, \"title\": null, \"chunk_index\": 18}', 'bge-large-zh-v1.5', '2026-09-25 17:05:01');
INSERT INTO `chunk` VALUES ('bfb13ed7-f60f-4a3a-972c-4ba701686cbf', 'b25ce095-dfba-4403-acf8-c58eb456ca4c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 91, '第八百零六条　承包人将建设工程转包、违法分包的，发包人可以解除合同。\n发包人提供的主要建筑材料、建筑构配件和设备不符合强制性标准或者不履行协助义务，致使承包人无法施工，经催告后在合理期限内仍未履行相应义务的，承包人可以解除合同。\n合同解除后，已经完成的建设工程质量合格的，发包人应当按照约定支付相应的工程价款；已经完成的建设工程质量不合格的，参照本法第七百九十三条的规定处理。\n第八百零七条　发包人未按照约定支付价款的，承包人可以催告发包人在合理期限内支付价款。发包人逾期不支付的，除根据建设工程的性质不宜折价、拍卖外，承包人可以与发包人协议将该工程折价，也可以请求人民法院将该工程依法拍卖。建设工程的价款就该工程折价或者拍卖的价款优先受偿。\n第八百零八条　本章没有规定的，适用承揽合同的有关规定。\n第十九章　运输合同\n第一节　一般规定\n第八百零九条　运输合同是承运人将旅客或者货物从起运地点运输到约定地点，旅客、托运人或者收货人支付票款或者运输费用的合同。\n第八百一十条　从事公共运输的承运人不得拒绝旅客、托运人通常、合理的运输要求。\n第八百一十一条　承运人应当在约定期限或者合理期限内将旅客、货物安全运输到约定地点。\n第八百一十二条　承运人应当按照约定的或者通常的运输路线将旅客、货物运输到约定地点。\n第八百一十三条　旅客、托运人或者收货人应当支付票款或者运输费用。承运人未按照约定路线或者通常路线运输增加票款或者运输费用的，旅客、托运人或者收货人可以拒绝支付增加部分的票款或者运输费用。\n第二节　客运合同\n第八百一十四条　客运合同自承运人向旅客出具客票时成立，但是当事人另有约定或者另有交易习惯的除外。\n第八百一十五条　旅客应当按照有效客票记载的时间、班次和座位号乘坐', 737, '{\"level\": null, \"title\": null, \"chunk_index\": 91}', 'bge-large-zh-v1.5', '2026-09-25 17:05:01');
INSERT INTO `chunk` VALUES ('c036b4cb-9cf0-4485-ad46-bf11e83fa8dd', 'b25ce095-dfba-4403-acf8-c58eb456ca4c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 61, '第五百三十四条　对当事人利用合同实施危害国家利益、社会公共利益行为的，市场监督管理和其他有关行政主管部门依照法律、行政法规的规定负责监督处理。\n第五章　合同的保全\n第五百三十五条　因债务人怠于行使其债权或者与该债权有关的从权利，影响债权人的到期债权实现的，债权人可以向人民法院请求以自己的名义代位行使债务人对相对人的权利，但是该权利专属于债务人自身的除外。\n代位权的行使范围以债权人的到期债权为限。债权人行使代位权的必要费用，由债务人负担。\n相对人对债务人的抗辩，可以向债权人主张。\n第五百三十六条　债权人的债权到期前，债务人的债权或者与该债权有关的从权利存在诉讼时效期间即将届满或者未及时申报破产债权等情形，影响债权人的债权实现的，债权人可以代位向债务人的相对人请求其向债务人履行、向破产管理人申报或者作出其他必要的行为。\n第五百三十七条　人民法院认定代位权成立的，由债务人的相对人向债权人履行义务，债权人接受履行后，债权人与债务人、债务人与相对人之间相应的权利义务终止。债务人对相对人的债权或者与该债权有关的从权利被采取保全、执行措施，或者债务人破产的，依照相关法律的规定处理。\n第五百三十八条　债务人以放弃其债权、放弃债权担保、无偿转让财产等方式无偿处分财产权益，或者恶意延长其到期债权的履行期限，影响债权人的债权实现的，债权人可以请求人民法院撤销债务人的行为。\n第五百三十九条　债务人以明显不合理的低价转让财产、以明显不合理的高价受让他人财产或者为他人的债务提供担保，影响债权人的债权实现，债务人的相对人知道或者应当知道该情形的，债权人可以请求人民法院撤销债务人的行为。\n第五百四十条　撤销权的行使范围以债权人的债权为限。债权人行使撤销权的必要费用，由债务人负担。\n第五百四十一条　撤销权自债权人知道或者应当知道撤销事由之日起一年内行使', 772, '{\"level\": null, \"title\": null, \"chunk_index\": 61}', 'bge-large-zh-v1.5', '2026-09-25 17:05:01');
INSERT INTO `chunk` VALUES ('c07cbe01-6c34-4dce-9ecc-f7e5c033b616', '821ce1fd-178d-4a7e-ab92-3deff1488ce2', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 86, '第三百七十八条　战时造谣惑众，扰乱军心的，处三年以下有期徒刑、拘役或者管制；情节严重的，处三年以上十年以下有期徒刑。\n第三百七十九条　战时明知是逃离部队的军人而为其提供隐蔽处所、财物，情节严重的，处三年以下有期徒刑或者拘役。\n第三百八十条　战时拒绝或者故意延误军事订货，情节严重的，对单位判处罚金，并对其直接负责的主管人员和其他直接责任人员，处五年以下有期徒刑或者拘役；造成严重后果的，处五年以上有期徒刑。\n第三百八十一条　战时拒绝军事征收、征用，情节严重的，处三年以下有期徒刑或者拘役。\n第八章　贪污贿赂罪\n第三百八十二条　国家工作人员利用职务上的便利，侵吞、窃取、骗取或者以其他手段非法占有公共财物的，是贪污罪。\n受国家机关、国有公司、企业、事业单位、人民团体委托管理、经营国有财产的人员，利用职务上的便利，侵吞、窃取、骗取或者以其他手段非法占有国有财物的，以贪污论。\n与前两款所列人员勾结，伙同贪污的，以共犯论处。\n第三百八十三条　对犯贪污罪的，根据情节轻重，分别依照下列规定处罚：\n（一）贪污数额较大或者有其他较重情节的，处三年以下有期徒刑或者拘役，并处罚金。\n（二）贪污数额巨大或者有其他严重情节的，处三年以上十年以下有期徒刑，并处罚金或者没收财产。\n（三）贪污数额特别巨大或者有其他特别严重情节的，处十年以上有期徒刑或者无期徒刑，并处罚金或者没收财产；数额特别巨大，并使国家和人民利益遭受特别重大损失的，处无期徒刑或者死刑，并处没收财产。\n对多次贪污未经处理的，按照累计贪污数额处罚。\n犯第一款罪，在提起公诉前如实供述自己罪行、真诚悔罪、积极退赃，避免、减少损害结果的发生，有第一项规定情形的，可以从轻、减轻或者免除处罚；有第二项、第三项规定情形的，可以从轻处罚', 737, '{\"level\": null, \"title\": null, \"chunk_index\": 86}', 'bge-large-zh-v1.5', '2026-09-25 17:04:56');
INSERT INTO `chunk` VALUES ('c134b6f5-15bf-4180-97c5-bcb62b238947', 'b25ce095-dfba-4403-acf8-c58eb456ca4c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 116, '第一千零二十条　合理实施下列行为的，可以不经肖像权人同意：\n（一）为个人学习、艺术欣赏、课堂教学或者科学研究，在必要范围内使用肖像权人已经公开的肖像；\n（二）为实施新闻报道，不可避免地制作、使用、公开肖像权人的肖像；\n（三）为依法履行职责，国家机关在必要范围内制作、使用、公开肖像权人的肖像；\n（四）为展示特定公共环境，不可避免地制作、使用、公开肖像权人的肖像；\n（五）为维护公共利益或者肖像权人合法权益，制作、使用、公开肖像权人的肖像的其他行为。\n第一千零二十一条　当事人对肖像许可使用合同中关于肖像使用条款的理解有争议的，应当作出有利于肖像权人的解释。\n第一千零二十二条　当事人对肖像许可使用期限没有约定或者约定不明确的，任何一方当事人可以随时解除肖像许可使用合同，但是应当在合理期限之前通知对方。\n当事人对肖像许可使用期限有明确约定，肖像权人有正当理由的，可以解除肖像许可使用合同，但是应当在合理期限之前通知对方。因解除合同造成对方损失的，除不可归责于肖像权人的事由外，应当赔偿损失。\n第一千零二十三条　对姓名等的许可使用，参照适用肖像许可使用的有关规定。\n对自然人声音的保护，参照适用肖像权保护的有关规定。\n第五章　名誉权和荣誉权\n第一千零二十四条　民事主体享有名誉权。任何组织或者个人不得以侮辱、诽谤等方式侵害他人的名誉权。\n名誉是对民事主体的品德、声望、才能、信用等的社会评价。\n第一千零二十五条　行为人为公共利益实施新闻报道、舆论监督等行为，影响他人名誉的，不承担民事责任，但是有下列情形之一的除外：\n（一）捏造、歪曲事实；\n（二）对他人提供的严重失实内容未尽到合理核实义务；\n（三）使用侮辱性言辞等贬损他人名誉', 713, '{\"level\": null, \"title\": null, \"chunk_index\": 116}', 'bge-large-zh-v1.5', '2026-09-25 17:05:01');
INSERT INTO `chunk` VALUES ('c13604e7-5de0-48b6-b8e7-e245570b73c5', '16cbea7e-7e36-4f31-afb5-63892345d29c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 68, '第二百九十一条　监察机关应当对监察权运行关键环节进行经常性监督检查，适时开展专项督查。案件监督管理、案件审理等部门应当按照各自职责，对问题线索处置、调查措施使用、涉案财物管理等进行监督检查，建立常态化、全覆盖的案件质量评查机制。\n第二百九十二条　监察机关应当加强对监察人员执行职务和遵纪守法情况的监督，按照管理权限依法对监察人员涉嫌违法犯罪问题进行调查处置。\n第二百九十三条　监察机关及其监督检查、调查部门负责人应当定期检查调查期间的录音录像、谈话笔录、讯问笔录、询问笔录、涉案财物登记资料，加强对调查全过程的监督，发现问题及时纠正并报告。\n对谈话、讯问和询问的同步录音录像，应当重点检查是否存在以下情形：\n（一）以暴力、威胁等非法方法收集证据；\n（二）未保证被调查人的饮食和必要的休息时间；\n（三）谈话笔录、讯问笔录、询问笔录记载的起止时间与谈话、讯问、询问录音录像资料反映的起止时间不一致；\n（四）谈话笔录、讯问笔录、询问笔录与谈话、讯问、询问录音录像资料内容存在实质性差异。\n第二百九十四条　对监察人员打听案情、过问案件、说情干预的，办理监察事项的监察人员应当及时向上级负责人报告。有关情况应当登记备案。\n发现办理监察事项的监察人员未经批准接触被调查人、涉案人员及其特定关系人，或者存在交往情形的，知情的监察人员应当及时向上级负责人报告。有关情况应当登记备案。\n第二百九十五条　办理监察事项的监察人员有监察法第六十七条所列情形之一的，应当自行提出回避；没有自行提出回避的，监察机关应当依法决定其回避，监察对象、检举人及其他有关人员也有权要求其回避。\n选用借调人员、看护人员、调查场所，应当严格执行回避制度。\n第二百九十六条　监察人员自行提出回避，或者监察对象、检举人及其他有关人员要求监察人员回避的，应当书面或者口头提出，并说明理由。口头提出的，应当形成记录', 782, '{\"level\": null, \"title\": null, \"chunk_index\": 68}', 'bge-large-zh-v1.5', '2026-09-25 17:04:49');
INSERT INTO `chunk` VALUES ('c1cc7d4b-5872-4428-bdc0-75778bd13373', 'b25ce095-dfba-4403-acf8-c58eb456ca4c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 123, '对亲子关系有异议且有正当理由的，成年子女可以向人民法院提起诉讼，请求确认亲子关系。\n第一千零七十四条　有负担能力的祖父母、外祖父母，对于父母已经死亡或者父母无力抚养的未成年孙子女、外孙子女，有抚养的义务。\n有负担能力的孙子女、外孙子女，对于子女已经死亡或者子女无力赡养的祖父母、外祖父母，有赡养的义务。\n第一千零七十五条　有负担能力的兄、姐，对于父母已经死亡或者父母无力抚养的未成年弟、妹，有扶养的义务。\n由兄、姐扶养长大的有负担能力的弟、妹，对于缺乏劳动能力又缺乏生活来源的兄、姐，有扶养的义务。\n第四章　离　　婚\n第一千零七十六条　夫妻双方自愿离婚的，应当签订书面离婚协议，并亲自到婚姻登记机关申请离婚登记。\n离婚协议应当载明双方自愿离婚的意思表示和对子女抚养、财产以及债务处理等事项协商一致的意见。\n第一千零七十七条　自婚姻登记机关收到离婚登记申请之日起三十日内，任何一方不愿意离婚的，可以向婚姻登记机关撤回离婚登记申请。\n前款规定期限届满后三十日内，双方应当亲自到婚姻登记机关申请发给离婚证；未申请的，视为撤回离婚登记申请。\n第一千零七十八条　婚姻登记机关查明双方确实是自愿离婚，并已经对子女抚养、财产以及债务处理等事项协商一致的，予以登记，发给离婚证。\n第一千零七十九条　夫妻一方要求离婚的，可以由有关组织进行调解或者直接向人民法院提起离婚诉讼。\n人民法院审理离婚案件，应当进行调解；如果感情确已破裂，调解无效的，应当准予离婚。\n有下列情形之一，调解无效的，应当准予离婚：\n（一）重婚或者与他人同居；\n（二）实施家庭暴力或者虐待、遗弃家庭成员；\n（三）有赌博、吸毒等恶习屡教不改；\n（四）因感情不和分居满二年；\n（五）其他导致夫妻感情破裂的情形。\n一方被宣告失踪，另一方提起离婚诉讼的，应当准予离婚。\n经人民法院判决不准离婚后，双方又分居满一年，一方再次提起离婚诉讼的，应当准予离婚', 796, '{\"level\": null, \"title\": null, \"chunk_index\": 123}', 'bge-large-zh-v1.5', '2026-09-25 17:05:01');
INSERT INTO `chunk` VALUES ('c2229967-aa81-4e23-bdbf-949a4fda3cb0', 'd9d7dc15-8041-43b8-9f75-f112fe3ae003', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 3, '对因涉及新兴行业、领域，危险化学品安全监督管理职责不明确的，由县级以上人民政府按照业务相近的原则及时确定监督管理部门。\n第八条　负有危险化学品安全监督管理职责的部门依法进行监督检查，可以采取下列措施：\n（一）进入危险化学品作业场所实施现场检查，向有关单位和人员了解情况，查阅、复制有关文件、资料，必要时可以对危险化学品实施抽样检测；\n（二）运用信息化手段对危险化学品单位的重大危险源开展在线巡查抽查；\n（三）发现危险化学品事故隐患，责令立即消除或者限期消除；\n（四）对不符合法律、行政法规、规章规定或者国家标准、行业标准要求的设施、设备、装置、器材、运输工具等，责令立即停止使用；\n（五）经本部门主要负责人批准，查封违法生产、储存、使用、经营危险化学品的场所，扣押违法生产、储存、使用、经营、运输的危险化学品以及用于违法生产、使用、运输危险化学品的原材料、设备、运输工具；\n（六）发现影响危险化学品安全的违法行为，当场予以纠正或者责令限期改正。\n负有危险化学品安全监督管理职责的部门依法进行监督检查，监督检查人员不得少于二人，并应当出示执法证件；有关单位和个人对依法进行的监督检查应当予以配合，不得拒绝、阻挠。\n第九条　县级以上人民政府应当建立危险化学品安全监督管理工作协调机制，支持、督促负有危险化学品安全监督管理职责的部门依法履行职责，协调、解决危险化学品安全监督管理工作中的重大问题。\n负有危险化学品安全监督管理职责的部门应当加强监管协作和联合执法，密切协调配合，实现信息及时、充分、有效共享，依法加强对危险化学品的安全监督管理。发现依法应当由其他部门处理的违法行为，及时移交其他部门处理。\n第十条　任何单位和个人对违反本法规定的行为或者事故隐患，有权向负有危险化学品安全监督管理职责的部门举报或者报告', 754, '{\"level\": null, \"title\": null, \"chunk_index\": 3}', 'bge-large-zh-v1.5', '2026-09-25 17:04:46');
INSERT INTO `chunk` VALUES ('c3271f99-80b1-4311-8557-21a604547e6e', 'b25ce095-dfba-4403-acf8-c58eb456ca4c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 62, '自债务人的行为发生之日起五年内没有行使撤销权的，该撤销权消灭。\n第五百四十二条　债务人影响债权人的债权实现的行为被撤销的，自始没有法律约束力。\n第六章　合同的变更和转让\n第五百四十三条　当事人协商一致，可以变更合同。\n第五百四十四条　当事人对合同变更的内容约定不明确的，推定为未变更。\n第五百四十五条　债权人可以将债权的全部或者部分转让给第三人，但是有下列情形之一的除外：\n（一）根据债权性质不得转让；\n（二）按照当事人约定不得转让；\n（三）依照法律规定不得转让。\n当事人约定非金钱债权不得转让的，不得对抗善意第三人。当事人约定金钱债权不得转让的，不得对抗第三人。\n第五百四十六条　债权人转让债权，未通知债务人的，该转让对债务人不发生效力。\n债权转让的通知不得撤销，但是经受让人同意的除外。\n第五百四十七条　债权人转让债权的，受让人取得与债权有关的从权利，但是该从权利专属于债权人自身的除外。\n受让人取得从权利不因该从权利未办理转移登记手续或者未转移占有而受到影响。\n第五百四十八条　债务人接到债权转让通知后，债务人对让与人的抗辩，可以向受让人主张。\n第五百四十九条　有下列情形之一的，债务人可以向受让人主张抵销：\n（一）债务人接到债权转让通知时，债务人对让与人享有债权，且债务人的债权先于转让的债权到期或者同时到期；\n（二）债务人的债权与转让的债权是基于同一合同产生。\n第五百五十条　因债权转让增加的履行费用，由让与人负担。\n第五百五十一条　债务人将债务的全部或者部分转移给第三人的，应当经债权人同意。\n债务人或者第三人可以催告债权人在合理期限内予以同意，债权人未作表示的，视为不同意。\n第五百五十二条　第三人与债务人约定加入债务并通知债权人，或者第三人向债权人表示愿意加入债务，债权人未在合理期限内明确拒绝的，债权人可以请求第三人在其愿意承担的债务范围内和债务人承担连带债务', 789, '{\"level\": null, \"title\": null, \"chunk_index\": 62}', 'bge-large-zh-v1.5', '2026-09-25 17:05:01');
INSERT INTO `chunk` VALUES ('c3c2864b-f3f6-47e8-9b7d-3fbb5f87d67e', '821ce1fd-178d-4a7e-ab92-3deff1488ce2', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 6, '第三十五条　对于犯罪的外国人，可以独立适用或者附加适用驱逐出境。\n第三十六条　由于犯罪行为而使被害人遭受经济损失的，对犯罪分子除依法给予刑事处罚外，并应根据情况判处赔偿经济损失。\n承担民事赔偿责任的犯罪分子，同时被判处罚金，其财产不足以全部支付的，或者被判处没收财产的，应当先承担对被害人的民事赔偿责任。\n第三十七条　对于犯罪情节轻微不需要判处刑罚的，可以免予刑事处罚，但是可以根据案件的不同情况，予以训诫或者责令具结悔过、赔礼道歉、赔偿损失，或者由主管部门予以行政处罚或者行政处分。\n第三十七条之一　因利用职业便利实施犯罪，或者实施违背职业要求的特定义务的犯罪被判处刑罚的，人民法院可以根据犯罪情况和预防再犯罪的需要，禁止其自刑罚执行完毕之日或者假释之日起从事相关职业，期限为三年至五年。\n被禁止从事相关职业的人违反人民法院依照前款规定作出的决定的，由公安机关依法给予处罚；情节严重的，依照本法第三百一十三条的规定定罪处罚。\n其他法律、行政法规对其从事相关职业另有禁止或者限制性规定的，从其规定。\n第二节　管　　制\n第三十八条　管制的期限，为三个月以上二年以下。\n判处管制，可以根据犯罪情况，同时禁止犯罪分子在执行期间从事特定活动，进入特定区域、场所，接触特定的人。\n对判处管制的犯罪分子，依法实行社区矫正。\n违反第二款规定的禁止令的，由公安机关依照《中华人民共和国治安管理处罚法》的规定处罚。\n第三十九条　被判处管制的犯罪分子，在执行期间，应当遵守下列规定：\n（一）遵守法律、行政法规，服从监督；\n（二）未经执行机关批准，不得行使言论、出版、集会、结社、游行、示威自由的权利；\n（三）按照执行机关规定报告自己的活动情况；\n（四）遵守执行机关关于会客的规定；\n（五）离开所居住的市、县或者迁居，应当报经执行机关批准。\n对于被判处管制的犯罪分子，在劳动中应当同工同酬', 783, '{\"level\": null, \"title\": null, \"chunk_index\": 6}', 'bge-large-zh-v1.5', '2026-09-25 17:04:56');
INSERT INTO `chunk` VALUES ('c3f61233-2408-40d6-9140-59904677bd6d', '821ce1fd-178d-4a7e-ab92-3deff1488ce2', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 0, '中华人民共和国刑法\n（1979年7月1日第五届全国人民代表大会第二次会议通过　1997年3月14日第八届全国人民代表大会第五次会议修订　根据1998年12月29日第九届全国人民代表大会常务委员会第六次会议通过的《全国人民代表大会常务委员会关于惩治骗购外汇、逃汇和非法买卖外汇犯罪的决定》、1999年12月25日第九届全国人民代表大会常务委员会第十三次会议通过的《中华人民共和国刑法修正案》、2001年8月31日第九届全国人民代表大会常务委员会第二十三次会议通过的《中华人民共和国刑法修正案（二）》、2001年12月29日第九届全国人民代表大会常务委员会第二十五次会议通过的《中华人民共和国刑法修正案（三）》、2002年12月28日第九届全国人民代表大会常务委员会第三十一次会议通过的《中华人民共和国刑法修正案（四）》、2005年2月28日第十届全国人民代表大会常务委员会第十四次会议通过的《中华人民共和国刑法修正案（五）》、2006年6月29日第十届全国人民代表大会常务委员会第二十二次会议通过的《中华人民共和国刑法修正案（六）》、2009年2月28日第十一届全国人民代表大会常务委员会第七次会议通过的《中华人民共和国刑法修正案（七）》、2009年8月27日第十一届全国人民代表大会常务委员会第十次会议通过的《全国人民代表大会常务委员会关于修改部分法律的决定》、2011年2月25日第十一届全国人民代表大会常务委员会第十九次会议通过的《中华人民共和国刑法修正案（八）》、2015年8月29日第十二届全国人民代表大会常务委员会第十六次会议通过的《中华人民共和国刑法修正案（九）》、2017年11月4日第十二届全国人民代表大会常务委员会第三十次会议通过的《中华人民共和国刑法修正案（十）》和2020年12月26日第十三届全国人民代表大会常务委员会第二十四次会议通过的《中华人民共和国刑法修正案（十一）》修', 800, '{\"level\": null, \"title\": null, \"chunk_index\": 0}', 'bge-large-zh-v1.5', '2026-09-25 17:04:56');
INSERT INTO `chunk` VALUES ('c4f568cd-4d93-44cf-93d0-5fb5f8277dab', 'b25ce095-dfba-4403-acf8-c58eb456ca4c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 13, '第九十四条　捐助人有权向捐助法人查询捐助财产的使用、管理情况，并提出意见和建议，捐助法人应当及时、如实答复。\n捐助法人的决策机构、执行机构或者法定代表人作出决定的程序违反法律、行政法规、法人章程，或者决定内容违反法人章程的，捐助人等利害关系人或者主管机关可以请求人民法院撤销该决定。但是，捐助法人依据该决定与善意相对人形成的民事法律关系不受影响。\n第九十五条　为公益目的成立的非营利法人终止时，不得向出资人、设立人或者会员分配剩余财产。剩余财产应当按照法人章程的规定或者权力机构的决议用于公益目的；无法按照法人章程的规定或者权力机构的决议处理的，由主管机关主持转给宗旨相同或者相近的法人，并向社会公告。\n第四节　特别法人\n第九十六条　本节规定的机关法人、农村集体经济组织法人、城镇农村的合作经济组织法人、基层群众性自治组织法人，为特别法人。\n第九十七条　有独立经费的机关和承担行政职能的法定机构从成立之日起，具有机关法人资格，可以从事为履行职能所需要的民事活动。\n第九十八条　机关法人被撤销的，法人终止，其民事权利和义务由继任的机关法人享有和承担；没有继任的机关法人的，由作出撤销决定的机关法人享有和承担。\n第九十九条　农村集体经济组织依法取得法人资格。\n法律、行政法规对农村集体经济组织有规定的，依照其规定。\n第一百条　城镇农村的合作经济组织依法取得法人资格。\n法律、行政法规对城镇农村的合作经济组织有规定的，依照其规定。\n第一百零一条　居民委员会、村民委员会具有基层群众性自治组织法人资格，可以从事为履行职能所需要的民事活动。\n未设立村集体经济组织的，村民委员会可以依法代行村集体经济组织的职能。\n第四章　非法人组织\n第一百零二条　非法人组织是不具有法人资格，但是能够依法以自己的名义从事民事活动的组织。\n非法人组织包括个人独资企业、合伙企业、不具有法人资格的专业服务机构等', 789, '{\"level\": null, \"title\": null, \"chunk_index\": 13}', 'bge-large-zh-v1.5', '2026-09-25 17:05:01');
INSERT INTO `chunk` VALUES ('c54c07f0-3415-4e73-9915-455707383028', '821ce1fd-178d-4a7e-ab92-3deff1488ce2', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 37, '第一百八十一条　编造并且传播影响证券、期货交易的虚假信息，扰乱证券、期货交易市场，造成严重后果的，处五年以下有期徒刑或者拘役，并处或者单处一万元以上十万元以下罚金。\n证券交易所、期货交易所、证券公司、期货经纪公司的从业人员，证券业协会、期货业协会或者证券期货监督管理部门的工作人员，故意提供虚假信息或者伪造、变造、销毁交易记录，诱骗投资者买卖证券、期货合约，造成严重后果的，处五年以下有期徒刑或者拘役，并处或者单处一万元以上十万元以下罚金；情节特别恶劣的，处五年以上十年以下有期徒刑，并处二万元以上二十万元以下罚金。\n单位犯前两款罪的，对单位判处罚金，并对其直接负责的主管人员和其他直接责任人员，处五年以下有期徒刑或者拘役。\n第一百八十二条　有下列情形之一，操纵证券、期货市场，影响证券、期货交易价格或者证券、期货交易量，情节严重的，处五年以下有期徒刑或者拘役，并处或者单处罚金；情节特别严重的，处五年以上十年以下有期徒刑，并处罚金：\n（一）单独或者合谋，集中资金优势、持股或者持仓优势或者利用信息优势联合或者连续买卖的；\n（二）与他人串通，以事先约定的时间、价格和方式相互进行证券、期货交易的；\n（三）在自己实际控制的帐户之间进行证券交易，或者以自己为交易对象，自买自卖期货合约的；\n（四）不以成交为目的，频繁或者大量申报买入、卖出证券、期货合约并撤销申报的；\n（五）利用虚假或者不确定的重大信息，诱导投资者进行证券、期货交易的；\n（六）对证券、证券发行人、期货交易标的公开作出评价、预测或者投资建议，同时进行反向证券交易或者相关期货交易的；\n（七）以其他方法操纵证券、期货市场的。\n单位犯前款罪的，对单位判处罚金，并对其直接负责的主管人员和其他直接责任人员，依照前款的规定处罚', 740, '{\"level\": null, \"title\": null, \"chunk_index\": 37}', 'bge-large-zh-v1.5', '2026-09-25 17:04:56');
INSERT INTO `chunk` VALUES ('c608fb64-e575-4b6f-bb4e-3b02ad135309', 'b25ce095-dfba-4403-acf8-c58eb456ca4c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 52, '第四百六十八条　非因合同产生的债权债务关系，适用有关该债权债务关系的法律规定；没有规定的，适用本编通则的有关规定，但是根据其性质不能适用的除外。\n第二章　合同的订立\n第四百六十九条　当事人订立合同，可以采用书面形式、口头形式或者其他形式。\n书面形式是合同书、信件、电报、电传、传真等可以有形地表现所载内容的形式。\n以电子数据交换、电子邮件等方式能够有形地表现所载内容，并可以随时调取查用的数据电文，视为书面形式。\n第四百七十条　合同的内容由当事人约定，一般包括下列条款：\n（一）当事人的姓名或者名称和住所；\n（二）标的；\n（三）数量；\n（四）质量；\n（五）价款或者报酬；\n（六）履行期限、地点和方式；\n（七）违约责任；\n（八）解决争议的方法。\n当事人可以参照各类合同的示范文本订立合同。\n第四百七十一条　当事人订立合同，可以采取要约、承诺方式或者其他方式。\n第四百七十二条　要约是希望与他人订立合同的意思表示，该意思表示应当符合下列条件：\n（一）内容具体确定；\n（二）表明经受要约人承诺，要约人即受该意思表示约束。\n第四百七十三条　要约邀请是希望他人向自己发出要约的表示。拍卖公告、招标公告、招股说明书、债券募集办法、基金招募说明书、商业广告和宣传、寄送的价目表等为要约邀请。\n商业广告和宣传的内容符合要约条件的，构成要约。\n第四百七十四条　要约生效的时间适用本法第一百三十七条的规定。\n第四百七十五条　要约可以撤回。要约的撤回适用本法第一百四十一条的规定。\n第四百七十六条　要约可以撤销，但是有下列情形之一的除外：\n（一）要约人以确定承诺期限或者其他形式明示要约不可撤销；\n（二）受要约人有理由认为要约是不可撤销的，并已经为履行合同做了合理准备工作', 725, '{\"level\": null, \"title\": null, \"chunk_index\": 52}', 'bge-large-zh-v1.5', '2026-09-25 17:05:01');
INSERT INTO `chunk` VALUES ('c60e0771-38a5-459f-82ed-3b54059f489a', '821ce1fd-178d-4a7e-ab92-3deff1488ce2', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 78, '第三百四十一条　非法猎捕、杀害国家重点保护的珍贵、濒危野生动物的，或者非法收购、运输、出售国家重点保护的珍贵、濒危野生动物及其制品的，处五年以下有期徒刑或者拘役，并处罚金；情节严重的，处五年以上十年以下有期徒刑，并处罚金；情节特别严重的，处十年以上有期徒刑，并处罚金或者没收财产。\n违反狩猎法规，在禁猎区、禁猎期或者使用禁用的工具、方法进行狩猎，破坏野生动物资源，情节严重的，处三年以下有期徒刑、拘役、管制或者罚金。\n违反野生动物保护管理法规，以食用为目的非法猎捕、收购、运输、出售第一款规定以外的在野外环境自然生长繁殖的陆生野生动物，情节严重的，依照前款的规定处罚。\n第三百四十二条　违反土地管理法规，非法占用耕地、林地等农用地，改变被占用土地用途，数量较大，造成耕地、林地等农用地大量毁坏的，处五年以下有期徒刑或者拘役，并处或者单处罚金。\n第三百四十二条之一　违反自然保护地管理法规，在国家公园、国家级自然保护区进行开垦、开发活动或者修建建筑物，造成严重后果或者有其他恶劣情节的，处五年以下有期徒刑或者拘役，并处或者单处罚金。\n有前款行为，同时构成其他犯罪的，依照处罚较重的规定定罪处罚。\n第三百四十三条　违反矿产资源法的规定，未取得采矿许可证擅自采矿，擅自进入国家规划矿区、对国民经济具有重要价值的矿区和他人矿区范围采矿，或者擅自开采国家规定实行保护性开采的特定矿种，情节严重的，处三年以下有期徒刑、拘役或者管制，并处或者单处罚金；情节特别严重的，处三年以上七年以下有期徒刑，并处罚金。\n违反矿产资源法的规定，采取破坏性的开采方法开采矿产资源，造成矿产资源严重破坏的，处五年以下有期徒刑或者拘役，并处罚金', 705, '{\"level\": null, \"title\": null, \"chunk_index\": 78}', 'bge-large-zh-v1.5', '2026-09-25 17:04:56');
INSERT INTO `chunk` VALUES ('c6b1c480-bdc6-40a7-aace-4ba19cdf78f7', 'b25ce095-dfba-4403-acf8-c58eb456ca4c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 67, '第五百八十五条　当事人可以约定一方违约时应当根据违约情况向对方支付一定数额的违约金，也可以约定因违约产生的损失赔偿额的计算方法。\n约定的违约金低于造成的损失的，人民法院或者仲裁机构可以根据当事人的请求予以增加；约定的违约金过分高于造成的损失的，人民法院或者仲裁机构可以根据当事人的请求予以适当减少。\n当事人就迟延履行约定违约金的，违约方支付违约金后，还应当履行债务。\n第五百八十六条　当事人可以约定一方向对方给付定金作为债权的担保。定金合同自实际交付定金时成立。\n定金的数额由当事人约定；但是，不得超过主合同标的额的百分之二十，超过部分不产生定金的效力。实际交付的定金数额多于或者少于约定数额的，视为变更约定的定金数额。\n第五百八十七条　债务人履行债务的，定金应当抵作价款或者收回。给付定金的一方不履行债务或者履行债务不符合约定，致使不能实现合同目的的，无权请求返还定金；收受定金的一方不履行债务或者履行债务不符合约定，致使不能实现合同目的的，应当双倍返还定金。\n第五百八十八条　当事人既约定违约金，又约定定金的，一方违约时，对方可以选择适用违约金或者定金条款。\n定金不足以弥补一方违约造成的损失的，对方可以请求赔偿超过定金数额的损失。\n第五百八十九条　债务人按照约定履行债务，债权人无正当理由拒绝受领的，债务人可以请求债权人赔偿增加的费用。\n在债权人受领迟延期间，债务人无须支付利息。\n第五百九十条　当事人一方因不可抗力不能履行合同的，根据不可抗力的影响，部分或者全部免除责任，但是法律另有规定的除外。因不可抗力不能履行合同的，应当及时通知对方，以减轻可能给对方造成的损失，并应当在合理期限内提供证明。\n当事人迟延履行后发生不可抗力的，不免除其违约责任。\n第五百九十一条　当事人一方违约后，对方应当采取适当措施防止损失的扩大；没有采取适当措施致使损失扩大的，不得就扩大的损失请求赔偿', 792, '{\"level\": null, \"title\": null, \"chunk_index\": 67}', 'bge-large-zh-v1.5', '2026-09-25 17:05:01');
INSERT INTO `chunk` VALUES ('c6befcee-008d-40de-a6f9-ffddcaac2ba1', 'd9d7dc15-8041-43b8-9f75-f112fe3ae003', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 36, '第一百一十二条　有下列情形之一的，由公安机关责令限期改正，处五万元以上十万元以下的罚款：\n（一）危险化学品运输车辆未悬挂、喷涂或者遮挡、拆除警示标志，或者警示标志不符合国家标准要求；\n（二）通过道路运输危险化学品，不按照要求配备押运人员；\n（三）运输剧毒化学品或者易制爆危险化学品途中需要较长时间停车，驾驶人员、押运人员不向当地公安机关报告；\n（四）剧毒化学品、易制爆危险化学品在道路运输途中丢失、被盗、被抢或者出现流散、泄漏等情况，驾驶人员、押运人员不采取相应的警示措施和安全措施，或者不向当地公安机关报告。\n第一百一十三条　对发生交通事故负有全部责任或者主要责任的危险化学品道路运输企业，由公安机关责令消除安全隐患，未消除安全隐患的危险化学品运输车辆，禁止上道路行驶。\n第一百一十四条　有下列情形之一的，由交通运输主管部门责令限期改正，可以处五万元以下的罚款；逾期不改正的，处五万元以上十万元以下的罚款：\n（一）危险化学品道路运输企业、水路运输企业未配备专职安全生产管理人员；\n（二）用于危险化学品运输作业的内河码头、泊位的管理单位未制定码头、泊位危险化学品事故应急预案，或者未为码头、泊位配备充足、有效的应急救援器材、装备、设备和物资', 520, '{\"level\": null, \"title\": null, \"chunk_index\": 36}', 'bge-large-zh-v1.5', '2026-09-25 17:04:46');
INSERT INTO `chunk` VALUES ('c73391ab-0021-449a-9a5c-e9c46c57c926', '821ce1fd-178d-4a7e-ab92-3deff1488ce2', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 88, '第三百八十八条之一　国家工作人员的近亲属或者其他与该国家工作人员关系密切的人，通过该国家工作人员职务上的行为，或者利用该国家工作人员职权或者地位形成的便利条件，通过其他国家工作人员职务上的行为，为请托人谋取不正当利益，索取请托人财物或者收受请托人财物，数额较大或者有其他较重情节的，处三年以下有期徒刑或者拘役，并处罚金；数额巨大或者有其他严重情节的，处三年以上七年以下有期徒刑，并处罚金；数额特别巨大或者有其他特别严重情节的，处七年以上有期徒刑，并处罚金或者没收财产。\n离职的国家工作人员或者其近亲属以及其他与其关系密切的人，利用该离职的国家工作人员原职权或者地位形成的便利条件实施前款行为的，依照前款的规定定罪处罚。\n第三百八十九条　为谋取不正当利益，给予国家工作人员以财物的，是行贿罪。\n在经济往来中，违反国家规定，给予国家工作人员以财物，数额较大的，或者违反国家规定，给予国家工作人员以各种名义的回扣、手续费的，以行贿论处。\n因被勒索给予国家工作人员以财物，没有获得不正当利益的，不是行贿。\n第三百九十条　对犯行贿罪的，处五年以下有期徒刑或者拘役，并处罚金；因行贿谋取不正当利益，情节严重的，或者使国家利益遭受重大损失的，处五年以上十年以下有期徒刑，并处罚金；情节特别严重的，或者使国家利益遭受特别重大损失的，处十年以上有期徒刑或者无期徒刑，并处罚金或者没收财产。\n行贿人在被追诉前主动交待行贿行为的，可以从轻或者减轻处罚。其中，犯罪较轻的，对侦破重大案件起关键作用的，或者有重大立功表现的，可以减轻或者免除处罚', 659, '{\"level\": null, \"title\": null, \"chunk_index\": 88}', 'bge-large-zh-v1.5', '2026-09-25 17:04:56');
INSERT INTO `chunk` VALUES ('c77da714-2e8a-46d3-9737-b647b1655fe5', '16cbea7e-7e36-4f31-afb5-63892345d29c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 15, '证据确凿，应当符合下列条件：\n（一）定性处置的事实都有证据证实；\n（二）定案证据真实、合法；\n（三）据以定案的证据之间不存在无法排除的矛盾；\n（四）综合全案证据，所认定事实清晰且令人信服。\n第七十条　监察机关调查终结的职务犯罪案件，应当事实清楚，证据确实、充分。证据确实、充分，应当符合下列条件：\n（一）定罪量刑的事实都有证据证明；\n（二）据以定案的证据均经法定程序查证属实；\n（三）综合全案证据，对所认定事实已排除合理怀疑。\n证据不足的，不得移送人民检察院审查起诉。\n第七十一条　调查人员应当依法文明规范开展调查工作。严禁以暴力、威胁、引诱、欺骗以及非法限制人身自由等非法方法收集证据，严禁侮辱、打骂、虐待、体罚或者变相体罚被调查人、涉案人员和证人。\n监察机关应当保障被强制到案人员、被管护人员、被留置人员以及被禁闭人员的合法权益，尊重其人格和民族习俗，保障饮食、休息和安全，提供医疗服务。\n第七十二条　对于调查人员采用暴力、威胁以及非法限制人身自由等非法方法收集的被调查人供述、证人证言、被害人陈述，应当依法予以排除。\n前款所称暴力的方法，是指采用殴打、违法使用戒具等方法或者变相肉刑的恶劣手段，使人遭受难以忍受的痛苦而违背意愿作出供述、证言、陈述；威胁的方法，是指采用以暴力或者严重损害本人及其近亲属合法权益等进行威胁的方法，使人遭受难以忍受的痛苦而违背意愿作出供述、证言、陈述。\n收集物证、书证不符合法定程序，可能严重影响案件公正处理的，应当予以补正或者作出合理解释；不能补正或者作出合理解释的，对该证据应当予以排除。\n第七十三条　监察机关监督检查、调查、案件审理、案件监督管理等部门发现监察人员在办理案件中，可能存在以非法方法收集证据情形的，应当依据职责进行调查核实', 738, '{\"level\": null, \"title\": null, \"chunk_index\": 15}', 'bge-large-zh-v1.5', '2026-09-25 17:04:49');
INSERT INTO `chunk` VALUES ('c7a06ca6-4614-496c-a463-65288930eafd', 'b25ce095-dfba-4403-acf8-c58eb456ca4c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 8, '第四十六条　自然人有下列情形之一的，利害关系人可以向人民法院申请宣告该自然人死亡：\n（一）下落不明满四年；\n（二）因意外事件，下落不明满二年。\n因意外事件下落不明，经有关机关证明该自然人不可能生存的，申请宣告死亡不受二年时间的限制。\n第四十七条　对同一自然人，有的利害关系人申请宣告死亡，有的利害关系人申请宣告失踪，符合本法规定的宣告死亡条件的，人民法院应当宣告死亡。\n第四十八条　被宣告死亡的人，人民法院宣告死亡的判决作出之日视为其死亡的日期；因意外事件下落不明宣告死亡的，意外事件发生之日视为其死亡的日期。\n第四十九条　自然人被宣告死亡但是并未死亡的，不影响该自然人在被宣告死亡期间实施的民事法律行为的效力。\n第五十条　被宣告死亡的人重新出现，经本人或者利害关系人申请，人民法院应当撤销死亡宣告。\n第五十一条　被宣告死亡的人的婚姻关系，自死亡宣告之日起消除。死亡宣告被撤销的，婚姻关系自撤销死亡宣告之日起自行恢复。但是，其配偶再婚或者向婚姻登记机关书面声明不愿意恢复的除外。\n第五十二条　被宣告死亡的人在被宣告死亡期间，其子女被他人依法收养的，在死亡宣告被撤销后，不得以未经本人同意为由主张收养行为无效。\n第五十三条　被撤销死亡宣告的人有权请求依照本法第六编取得其财产的民事主体返还财产；无法返还的，应当给予适当补偿。\n利害关系人隐瞒真实情况，致使他人被宣告死亡而取得其财产的，除应当返还财产外，还应当对由此造成的损失承担赔偿责任。\n第四节　个体工商户和农村承包经营户\n第五十四条　自然人从事工商业经营，经依法登记，为个体工商户。个体工商户可以起字号。\n第五十五条　农村集体经济组织的成员，依法取得农村土地承包经营权，从事家庭承包经营的，为农村承包经营户。\n第五十六条　个体工商户的债务，个人经营的，以个人财产承担；家庭经营的，以家庭财产承担；无法区分的，以家庭财产承担', 787, '{\"level\": null, \"title\": null, \"chunk_index\": 8}', 'bge-large-zh-v1.5', '2026-09-25 17:05:01');
INSERT INTO `chunk` VALUES ('c7d9ac48-278a-41a6-8206-2d4f3f90fa84', '16cbea7e-7e36-4f31-afb5-63892345d29c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 27, '第一百二十四条　被调查人具有下列情形之一的，可以认定为监察法第二十四条第一款第四项所规定的可能有其他妨碍调查行为：\n（一）可能继续实施违法犯罪行为的；\n（二）有危害国家安全、公共安全等现实危险的；\n（三）可能对举报人、控告人、被害人、证人、鉴定人等相关人员实施打击报复的；\n（四）无正当理由拒不到案，严重影响调查的；\n（五）其他可能妨碍调查的行为。\n第一百二十五条　对下列人员不得采取留置措施：\n（一）患有严重疾病、生活不能自理的；\n（二）怀孕或者正在哺乳自己婴儿的妇女；\n（三）生活不能自理的人的唯一扶养人。\n上述情形消失后，根据调查需要可以对相关人员采取留置措施。\n第一百二十六条　采取留置措施时，调查人员不得少于二人，应当向被留置人员宣布《留置决定书》，告知被留置人员权利义务，要求其在《留置决定书》上签名、捺指印。被留置人员拒绝签名、捺指印的，调查人员应当在文书上记明。\n第一百二十七条　采取留置措施后，应当在二十四小时以内通知被留置人员所在单位和家属。当面通知的，由有关人员在《留置通知书》上签名。无法当面通知的，可以先以电话等方式通知，并通过邮寄、转交等方式送达《留置通知书》，要求有关人员在《留置通知书》上签名。有关人员拒绝签名的，调查人员应当在文书上记明。\n因可能伪造、隐匿、毁灭证据，干扰证人作证或者串供等有碍调查情形而不宜通知的，应当按规定报批，记录在案。有碍调查的情形消失后，应当立即通知被留置人员所在单位和家属。\n第一百二十八条　监察机关采取留置措施后，应当在二十四小时以内对涉嫌职务违法的被调查人进行谈话，对涉嫌职务犯罪的被调查人进行讯问。\n第一百二十九条　留置时间不得超过三个月，自向被留置人员宣布之日起算', 717, '{\"level\": null, \"title\": null, \"chunk_index\": 27}', 'bge-large-zh-v1.5', '2026-09-25 17:04:49');
INSERT INTO `chunk` VALUES ('c83462dc-6dd3-497e-abf3-0792953b5416', '821ce1fd-178d-4a7e-ab92-3deff1488ce2', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 95, '第四百二十二条　故意隐瞒、谎报军情或者拒传、假传军令，对作战造成危害的，处三年以上十年以下有期徒刑；致使战斗、战役遭受重大损失的，处十年以上有期徒刑、无期徒刑或者死刑。\n第四百二十三条　在战场上贪生怕死，自动放下武器投降敌人的，处三年以上十年以下有期徒刑；情节严重的，处十年以上有期徒刑或者无期徒刑。\n投降后为敌人效劳的，处十年以上有期徒刑、无期徒刑或者死刑。\n第四百二十四条　战时临阵脱逃的，处三年以下有期徒刑；情节严重的，处三年以上十年以下有期徒刑；致使战斗、战役遭受重大损失的，处十年以上有期徒刑、无期徒刑或者死刑。\n第四百二十五条　指挥人员和值班、值勤人员擅离职守或者玩忽职守，造成严重后果的，处三年以下有期徒刑或者拘役；造成特别严重后果的，处三年以上七年以下有期徒刑。\n战时犯前款罪的，处五年以上有期徒刑。\n第四百二十六条　以暴力、威胁方法，阻碍指挥人员或者值班、值勤人员执行职务的，处五年以下有期徒刑或者拘役；情节严重的，处五年以上十年以下有期徒刑；情节特别严重的，处十年以上有期徒刑或者无期徒刑。战时从重处罚。\n第四百二十七条　滥用职权，指使部属进行违反职责的活动，造成严重后果的，处五年以下有期徒刑或者拘役；情节特别严重的，处五年以上十年以下有期徒刑。\n第四百二十八条　指挥人员违抗命令，临阵畏缩，作战消极，造成严重后果的，处五年以下有期徒刑；致使战斗、战役遭受重大损失或者有其他特别严重情节的，处五年以上有期徒刑。\n第四百二十九条　在战场上明知友邻部队处境危急请求救援，能救援而不救援，致使友邻部队遭受重大损失的，对指挥人员，处五年以下有期徒刑。\n第四百三十条　在履行公务期间，擅离岗位，叛逃境外或者在境外叛逃，危害国家军事利益的，处五年以下有期徒刑或者拘役；情节严重的，处五年以上有期徒刑。\n驾驶航空器、舰船叛逃的，或者有其他特别严重情节的，处十年以上有期徒刑、无期徒刑或者死刑', 799, '{\"level\": null, \"title\": null, \"chunk_index\": 95}', 'bge-large-zh-v1.5', '2026-09-25 17:04:56');
INSERT INTO `chunk` VALUES ('c9df9512-214b-451e-8ffc-42eac2b6365f', '821ce1fd-178d-4a7e-ab92-3deff1488ce2', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 54, '第二百四十条　拐卖妇女、儿童的，处五年以上十年以下有期徒刑，并处罚金；有下列情形之一的，处十年以上有期徒刑或者无期徒刑，并处罚金或者没收财产；情节特别严重的，处死刑，并处没收财产：\n（一）拐卖妇女、儿童集团的首要分子；\n（二）拐卖妇女、儿童三人以上的；\n（三）奸淫被拐卖的妇女的；\n（四）诱骗、强迫被拐卖的妇女卖淫或者将被拐卖的妇女卖给他人迫使其卖淫的；\n（五）以出卖为目的，使用暴力、胁迫或者麻醉方法绑架妇女、儿童的；\n（六）以出卖为目的，偷盗婴幼儿的；\n（七）造成被拐卖的妇女、儿童或者其亲属重伤、死亡或者其他严重后果的；\n（八）将妇女、儿童卖往境外的。\n拐卖妇女、儿童是指以出卖为目的，有拐骗、绑架、收买、贩卖、接送、中转妇女、儿童的行为之一的。\n第二百四十一条　收买被拐卖的妇女、儿童的，处三年以下有期徒刑、拘役或者管制。\n收买被拐卖的妇女，强行与其发生性关系的，依照本法第二百三十六条的规定定罪处罚。\n收买被拐卖的妇女、儿童，非法剥夺、限制其人身自由或者有伤害、侮辱等犯罪行为的，依照本法的有关规定定罪处罚。\n收买被拐卖的妇女、儿童，并有第二款、第三款规定的犯罪行为的，依照数罪并罚的规定处罚。\n收买被拐卖的妇女、儿童又出卖的，依照本法第二百四十条的规定定罪处罚。\n收买被拐卖的妇女、儿童，对被买儿童没有虐待行为，不阻碍对其进行解救的，可以从轻处罚；按照被买妇女的意愿，不阻碍其返回原居住地的，可以从轻或者减轻处罚。\n第二百四十二条　以暴力、威胁方法阻碍国家机关工作人员解救被收买的妇女、儿童的，依照本法第二百七十七条的规定定罪处罚。\n聚众阻碍国家机关工作人员解救被收买的妇女、儿童的首要分子，处五年以下有期徒刑或者拘役；其他参与者使用暴力、威胁方法的，依照前款的规定处罚', 741, '{\"level\": null, \"title\": null, \"chunk_index\": 54}', 'bge-large-zh-v1.5', '2026-09-25 17:04:56');
INSERT INTO `chunk` VALUES ('ca7c39ff-db3b-4a0b-b284-346720f7aa8c', 'd9d7dc15-8041-43b8-9f75-f112fe3ae003', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 11, '第四十条　生产、储存剧毒化学品或者国务院公安部门规定的可用于制造爆炸物品的危险化学品（以下简称易制爆危险化学品）的单位，应当如实记录其生产、储存的剧毒化学品、易制爆危险化学品的品种、数量、流向，并采取必要的安全防范措施，防止剧毒化学品、易制爆危险化学品丢失或者被盗；发现剧毒化学品、易制爆危险化学品丢失或者被盗的，应当立即向当地公安机关报告；公安机关应当根据实际情况及时通报应急管理等有关部门。\n生产、储存剧毒化学品、易制爆危险化学品的单位，应当设置治安保卫机构，配备专职治安保卫人员，并依法报公安机关备案。\n第四十一条　危险化学品应当储存在专用仓库、专用场地或者专用储存室、储存专柜（以下统称专用储存场所）内，并由专人负责管理；剧毒化学品以及储存数量构成重大危险源的其他危险化学品，应当在专用储存场所内单独存放，实行双人收发、双人保管制度，收发记录的保存期限不得少于三年。\n危险化学品的储存方式、方法以及储存数量应当符合国家标准或者国家有关规定。\n第四十二条　储存危险化学品的单位应当建立危险化学品出入库核查、登记制度。\n剧毒化学品储存单位应当将剧毒化学品的储存数量、储存地点以及管理人员的情况，报所在地县级人民政府应急管理部门、消防救援机构和公安机关备案；在港区内储存的，报港口行政管理部门、消防救援机构和公安机关备案。\n第四十三条　危险化学品专用储存场所应当符合国家标准、行业标准的要求，并设置明显的标志。储存剧毒化学品、易制爆危险化学品的专用储存场所，应当按照国家有关规定设置相应的实体防范、技术防范设施。\n储存危险化学品的单位应当对其危险化学品专用储存场所的安全设施、设备定期进行检测、检验；检测、检验不合格的，应当停止使用，并按照规定予以维修或者更换', 731, '{\"level\": null, \"title\": null, \"chunk_index\": 11}', 'bge-large-zh-v1.5', '2026-09-25 17:04:46');
INSERT INTO `chunk` VALUES ('caebe09c-84e4-4102-b8ad-9ac52d475a36', '821ce1fd-178d-4a7e-ab92-3deff1488ce2', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 24, '第一百四十二条之一　违反药品管理法规，有下列情形之一，足以严重危害人体健康的，处三年以下有期徒刑或者拘役，并处或者单处罚金；对人体健康造成严重危害或者有其他严重情节的，处三年以上七年以下有期徒刑，并处罚金：\n（一）生产、销售国务院药品监督管理部门禁止使用的药品的；\n（二）未取得药品相关批准证明文件生产、进口药品或者明知是上述药品而销售的；\n（三）药品申请注册中提供虚假的证明、数据、资料、样品或者采取其他欺骗手段的；\n（四）编造生产、检验记录的。\n有前款行为，同时又构成本法第一百四十一条、第一百四十二条规定之罪或者其他犯罪的，依照处罚较重的规定定罪处罚。\n第一百四十三条　生产、销售不符合食品安全标准的食品，足以造成严重食物中毒事故或者其他严重食源性疾病的，处三年以下有期徒刑或者拘役，并处罚金；对人体健康造成严重危害或者有其他严重情节的，处三年以上七年以下有期徒刑，并处罚金；后果特别严重的，处七年以上有期徒刑或者无期徒刑，并处罚金或者没收财产。\n第一百四十四条　在生产、销售的食品中掺入有毒、有害的非食品原料的，或者销售明知掺有有毒、有害的非食品原料的食品的，处五年以下有期徒刑，并处罚金；对人体健康造成严重危害或者有其他严重情节的，处五年以上十年以下有期徒刑，并处罚金；致人死亡或者有其他特别严重情节的，依照本法第一百四十一条的规定处罚。\n第一百四十五条　生产不符合保障人体健康的国家标准、行业标准的医疗器械、医用卫生材料，或者销售明知是不符合保障人体健康的国家标准、行业标准的医疗器械、医用卫生材料，足以严重危害人体健康的，处三年以下有期徒刑或者拘役，并处销售金额百分之五十以上二倍以下罚金；对人体健康造成严重危害的，处三年以上十年以下有期徒刑，并处销售金额百分之五十以上二倍以下罚金；后果特别严重的，处十年以上有期徒刑或者无期徒刑，并处销售金额百分之五十以上二倍以下罚金或者没收财产', 798, '{\"level\": null, \"title\": null, \"chunk_index\": 24}', 'bge-large-zh-v1.5', '2026-09-25 17:04:56');
INSERT INTO `chunk` VALUES ('cb1f93fc-d3d6-4a18-9890-4087a36f4cb3', 'b25ce095-dfba-4403-acf8-c58eb456ca4c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 137, '第一千一百九十六条　网络用户接到转送的通知后，可以向网络服务提供者提交不存在侵权行为的声明。声明应当包括不存在侵权行为的初步证据及网络用户的真实身份信息。\n网络服务提供者接到声明后，应当将该声明转送发出通知的权利人，并告知其可以向有关部门投诉或者向人民法院提起诉讼。网络服务提供者在转送声明到达权利人后的合理期限内，未收到权利人已经投诉或者提起诉讼通知的，应当及时终止所采取的措施。\n第一千一百九十七条　网络服务提供者知道或者应当知道网络用户利用其网络服务侵害他人民事权益，未采取必要措施的，与该网络用户承担连带责任。\n第一千一百九十八条　宾馆、商场、银行、车站、机场、体育场馆、娱乐场所等经营场所、公共场所的经营者、管理者或者群众性活动的组织者，未尽到安全保障义务，造成他人损害的，应当承担侵权责任。\n因第三人的行为造成他人损害的，由第三人承担侵权责任；经营者、管理者或者组织者未尽到安全保障义务的，承担相应的补充责任。经营者、管理者或者组织者承担补充责任后，可以向第三人追偿。\n第一千一百九十九条　无民事行为能力人在幼儿园、学校或者其他教育机构学习、生活期间受到人身损害的，幼儿园、学校或者其他教育机构应当承担侵权责任；但是，能够证明尽到教育、管理职责的，不承担侵权责任。\n第一千二百条　限制民事行为能力人在学校或者其他教育机构学习、生活期间受到人身损害，学校或者其他教育机构未尽到教育、管理职责的，应当承担侵权责任。\n第一千二百零一条　无民事行为能力人或者限制民事行为能力人在幼儿园、学校或者其他教育机构学习、生活期间，受到幼儿园、学校或者其他教育机构以外的第三人人身损害的，由第三人承担侵权责任；幼儿园、学校或者其他教育机构未尽到管理职责的，承担相应的补充责任。幼儿园、学校或者其他教育机构承担补充责任后，可以向第三人追偿', 765, '{\"level\": null, \"title\": null, \"chunk_index\": 137}', 'bge-large-zh-v1.5', '2026-09-25 17:05:01');
INSERT INTO `chunk` VALUES ('cb61a498-4ab3-4b1d-b952-31289139010f', 'b25ce095-dfba-4403-acf8-c58eb456ca4c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 103, '保管人验收后，发生仓储物的品种、数量、质量不符合约定的，保管人应当承担赔偿责任。\n第九百零八条　存货人交付仓储物的，保管人应当出具仓单、入库单等凭证。\n第九百零九条　保管人应当在仓单上签名或者盖章。仓单包括下列事项：\n（一）存货人的姓名或者名称和住所；\n（二）仓储物的品种、数量、质量、包装及其件数和标记；\n（三）仓储物的损耗标准；\n（四）储存场所；\n（五）储存期限；\n（六）仓储费；\n（七）仓储物已经办理保险的，其保险金额、期间以及保险人的名称；\n（八）填发人、填发地和填发日期。\n第九百一十条　仓单是提取仓储物的凭证。存货人或者仓单持有人在仓单上背书并经保管人签名或者盖章的，可以转让提取仓储物的权利。\n第九百一十一条　保管人根据存货人或者仓单持有人的要求，应当同意其检查仓储物或者提取样品。\n第九百一十二条　保管人发现入库仓储物有变质或者其他损坏的，应当及时通知存货人或者仓单持有人。\n第九百一十三条　保管人发现入库仓储物有变质或者其他损坏，危及其他仓储物的安全和正常保管的，应当催告存货人或者仓单持有人作出必要的处置。因情况紧急，保管人可以作出必要的处置；但是，事后应当将该情况及时通知存货人或者仓单持有人。\n第九百一十四条　当事人对储存期限没有约定或者约定不明确的，存货人或者仓单持有人可以随时提取仓储物，保管人也可以随时请求存货人或者仓单持有人提取仓储物，但是应当给予必要的准备时间。\n第九百一十五条　储存期限届满，存货人或者仓单持有人应当凭仓单、入库单等提取仓储物。存货人或者仓单持有人逾期提取的，应当加收仓储费；提前提取的，不减收仓储费。\n第九百一十六条　储存期限届满，存货人或者仓单持有人不提取仓储物的，保管人可以催告其在合理期限内提取；逾期不提取的，保管人可以提存仓储物。\n第九百一十七条　储存期内，因保管不善造成仓储物毁损、灭失的，保管人应当承担赔偿责任', 788, '{\"level\": null, \"title\": null, \"chunk_index\": 103}', 'bge-large-zh-v1.5', '2026-09-25 17:05:01');
INSERT INTO `chunk` VALUES ('cb8885ee-6f7d-4def-b983-68b469ddad37', 'b25ce095-dfba-4403-acf8-c58eb456ca4c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 17, '第三节　民事法律行为的效力\n第一百四十三条　具备下列条件的民事法律行为有效：\n（一）行为人具有相应的民事行为能力；\n（二）意思表示真实；\n（三）不违反法律、行政法规的强制性规定，不违背公序良俗。\n第一百四十四条　无民事行为能力人实施的民事法律行为无效。\n第一百四十五条　限制民事行为能力人实施的纯获利益的民事法律行为或者与其年龄、智力、精神健康状况相适应的民事法律行为有效；实施的其他民事法律行为经法定代理人同意或者追认后有效。\n相对人可以催告法定代理人自收到通知之日起三十日内予以追认。法定代理人未作表示的，视为拒绝追认。民事法律行为被追认前，善意相对人有撤销的权利。撤销应当以通知的方式作出。\n第一百四十六条　行为人与相对人以虚假的意思表示实施的民事法律行为无效。\n以虚假的意思表示隐藏的民事法律行为的效力，依照有关法律规定处理。\n第一百四十七条　基于重大误解实施的民事法律行为，行为人有权请求人民法院或者仲裁机构予以撤销。\n第一百四十八条　一方以欺诈手段，使对方在违背真实意思的情况下实施的民事法律行为，受欺诈方有权请求人民法院或者仲裁机构予以撤销。\n第一百四十九条　第三人实施欺诈行为，使一方在违背真实意思的情况下实施的民事法律行为，对方知道或者应当知道该欺诈行为的，受欺诈方有权请求人民法院或者仲裁机构予以撤销。\n第一百五十条　一方或者第三人以胁迫手段，使对方在违背真实意思的情况下实施的民事法律行为，受胁迫方有权请求人民法院或者仲裁机构予以撤销。\n第一百五十一条　一方利用对方处于危困状态、缺乏判断能力等情形，致使民事法律行为成立时显失公平的，受损害方有权请求人民法院或者仲裁机构予以撤销', 700, '{\"level\": null, \"title\": null, \"chunk_index\": 17}', 'bge-large-zh-v1.5', '2026-09-25 17:05:01');
INSERT INTO `chunk` VALUES ('cbe4dcca-f8a3-46eb-b90f-9cadb2253815', '821ce1fd-178d-4a7e-ab92-3deff1488ce2', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 68, '第二百九十六条　举行集会、游行、示威，未依照法律规定申请或者申请未获许可，或者未按照主管机关许可的起止时间、地点、路线进行，又拒不服从解散命令，严重破坏社会秩序的，对集会、游行、示威的负责人和直接责任人员，处五年以下有期徒刑、拘役、管制或者剥夺政治权利。\n第二百九十七条　违反法律规定，携带武器、管制刀具或者爆炸物参加集会、游行、示威的，处三年以下有期徒刑、拘役、管制或者剥夺政治权利。\n第二百九十八条　扰乱、冲击或者以其他方法破坏依法举行的集会、游行、示威，造成公共秩序混乱的，处五年以下有期徒刑、拘役、管制或者剥夺政治权利。\n第二百九十九条　在公共场合，故意以焚烧、毁损、涂划、玷污、践踏等方式侮辱中华人民共和国国旗、国徽的，处三年以下有期徒刑、拘役、管制或者剥夺政治权利。\n在公共场合，故意篡改中华人民共和国国歌歌词、曲谱，以歪曲、贬损方式奏唱国歌，或者以其他方式侮辱国歌，情节严重的，依照前款的规定处罚。\n第二百九十九条之一　侮辱、诽谤或者以其他方式侵害英雄烈士的名誉、荣誉，损害社会公共利益，情节严重的，处三年以下有期徒刑、拘役、管制或者剥夺政治权利。\n第三百条　组织、利用会道门、邪教组织或者利用迷信破坏国家法律、行政法规实施的，处三年以上七年以下有期徒刑，并处罚金；情节特别严重的，处七年以上有期徒刑或者无期徒刑，并处罚金或者没收财产；情节较轻的，处三年以下有期徒刑、拘役、管制或者剥夺政治权利，并处或者单处罚金。\n组织、利用会道门、邪教组织或者利用迷信蒙骗他人，致人重伤、死亡的，依照前款的规定处罚。\n犯第一款罪又有奸淫妇女、诈骗财物等犯罪行为的，依照数罪并罚的规定处罚。\n第三百零一条　聚众进行淫乱活动的，对首要分子或者多次参加的，处五年以下有期徒刑、拘役或者管制。\n引诱未成年人参加聚众淫乱活动的，依照前款的规定从重处罚', 770, '{\"level\": null, \"title\": null, \"chunk_index\": 68}', 'bge-large-zh-v1.5', '2026-09-25 17:04:56');
INSERT INTO `chunk` VALUES ('cc3c50ee-1ebb-402f-ba1a-ebd12488c28d', '821ce1fd-178d-4a7e-ab92-3deff1488ce2', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 22, '第一百三十四条之一　在生产、作业中违反有关安全管理的规定，有下列情形之一，具有发生重大伤亡事故或者其他严重后果的现实危险的，处一年以下有期徒刑、拘役或者管制：\n（一）关闭、破坏直接关系生产安全的监控、报警、防护、救生设备、设施，或者篡改、隐瞒、销毁其相关数据、信息的；\n（二）因存在重大事故隐患被依法责令停产停业、停止施工、停止使用有关设备、设施、场所或者立即采取排除危险的整改措施，而拒不执行的；\n（三）涉及安全生产的事项未经依法批准或者许可，擅自从事矿山开采、金属冶炼、建筑施工，以及危险物品生产、经营、储存等高度危险的生产作业活动的。\n第一百三十五条　安全生产设施或者安全生产条件不符合国家规定，因而发生重大伤亡事故或者造成其他严重后果的，对直接负责的主管人员和其他直接责任人员，处三年以下有期徒刑或者拘役；情节特别恶劣的，处三年以上七年以下有期徒刑。\n第一百三十五条之一　举办大型群众性活动违反安全管理规定，因而发生重大伤亡事故或者造成其他严重后果的，对直接负责的主管人员和其他直接责任人员，处三年以下有期徒刑或者拘役；情节特别恶劣的，处三年以上七年以下有期徒刑。\n第一百三十六条　违反爆炸性、易燃性、放射性、毒害性、腐蚀性物品的管理规定，在生产、储存、运输、使用中发生重大事故，造成严重后果的，处三年以下有期徒刑或者拘役；后果特别严重的，处三年以上七年以下有期徒刑。\n第一百三十七条　建设单位、设计单位、施工单位、工程监理单位违反国家规定，降低工程质量标准，造成重大安全事故的，对直接责任人员，处五年以下有期徒刑或者拘役，并处罚金；后果特别严重的，处五年以上十年以下有期徒刑，并处罚金。\n第一百三十八条　明知校舍或者教育教学设施有危险，而不采取措施或者不及时报告，致使发生重大伤亡事故的，对直接责任人员，处三年以下有期徒刑或者拘役；后果特别严重的，处三年以上七年以下有期徒刑', 792, '{\"level\": null, \"title\": null, \"chunk_index\": 22}', 'bge-large-zh-v1.5', '2026-09-25 17:04:56');
INSERT INTO `chunk` VALUES ('cc583dbf-b652-4d80-8a40-c7085b0dd9d5', '16cbea7e-7e36-4f31-afb5-63892345d29c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 70, '查封经营性涉案财物，企业继续使用对该涉案财物价值无重大影响的，可以允许其使用。对于按规定不应交由企业保管使用的涉案财物，监察机关应当采取合理的保管保值措施。对于正在运营或者正在用于科技创新、产品研发的设备和技术资料等，一般不予查封、扣押，确需调取违法犯罪证据的，可以采取拍照、复制等方式。\n第三百零四条　监察机关根据已经掌握的事实及证据，发现涉嫌严重职务违法或者职务犯罪的监察人员可能实施下列行为之一的，经依法审批，可以在具备安全保障条件的场所对其采取禁闭措施：\n（一）继续实施违法犯罪行为的；\n（二）为被调查人或者涉案人员通风报信等泄露监察工作秘密的；\n（三）威胁、恐吓、蓄意报复举报人、控告人、被害人、证人、鉴定人等相关人员的；\n（四）其他可能造成更为严重的后果或者恶劣影响的行为。\n第三百零五条　采取禁闭措施时，调查人员不得少于二人，应当向被禁闭人员宣布《禁闭决定书》，告知被禁闭人员权利义务，要求其在《禁闭决定书》上签名、捺指印。被禁闭人员拒绝签名、捺指印的，调查人员应当在文书上记明。\n禁闭的期限不得超过七日，自向被禁闭人员宣布之日起算。\n第三百零六条　采取禁闭措施后，应当在二十四小时以内通知被禁闭人员所在单位和家属。当面通知的，由有关人员在《禁闭通知书》上签名。无法当面通知的，可以先以电话等方式通知，并通过邮寄、转交等方式送达《禁闭通知书》，要求有关人员在《禁闭通知书》上签名。有关人员拒绝签名的，调查人员应当在文书上记明。\n因可能伪造、隐匿、毁灭证据，干扰证人作证或者串供等有碍调查情形而不宜通知的，应当按规定报批，记录在案。有碍调查的情形消失后，应当立即通知被禁闭人员所在单位和家属。\n第三百零七条　对被禁闭人员不需要继续采取禁闭措施的，应当按规定报批后解除禁闭或者变更为责令候查措施。禁闭期满的，应当按规定报批后予以解除', 771, '{\"level\": null, \"title\": null, \"chunk_index\": 70}', 'bge-large-zh-v1.5', '2026-09-25 17:04:49');
INSERT INTO `chunk` VALUES ('cc773216-ed00-4c6e-b720-790a69bb510b', 'b25ce095-dfba-4403-acf8-c58eb456ca4c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 30, '第二百六十五条　集体所有的财产受法律保护，禁止任何组织或者个人侵占、哄抢、私分、破坏。\n农村集体经济组织、村民委员会或者其负责人作出的决定侵害集体成员合法权益的，受侵害的集体成员可以请求人民法院予以撤销。\n第二百六十六条　私人对其合法的收入、房屋、生活用品、生产工具、原材料等不动产和动产享有所有权。\n第二百六十七条　私人的合法财产受法律保护，禁止任何组织或者个人侵占、哄抢、破坏。\n第二百六十八条　国家、集体和私人依法可以出资设立有限责任公司、股份有限公司或者其他企业。国家、集体和私人所有的不动产或者动产投到企业的，由出资人按照约定或者出资比例享有资产收益、重大决策以及选择经营管理者等权利并履行义务。\n第二百六十九条　营利法人对其不动产和动产依照法律、行政法规以及章程享有占有、使用、收益和处分的权利。\n营利法人以外的法人，对其不动产和动产的权利，适用有关法律、行政法规以及章程的规定。\n第二百七十条　社会团体法人、捐助法人依法所有的不动产和动产，受法律保护。\n第六章　业主的建筑物区分所有权\n第二百七十一条　业主对建筑物内的住宅、经营性用房等专有部分享有所有权，对专有部分以外的共有部分享有共有和共同管理的权利。\n第二百七十二条　业主对其建筑物专有部分享有占有、使用、收益和处分的权利。业主行使权利不得危及建筑物的安全，不得损害其他业主的合法权益。\n第二百七十三条　业主对建筑物专有部分以外的共有部分，享有权利，承担义务；不得以放弃权利为由不履行义务。\n业主转让建筑物内的住宅、经营性用房，其对共有部分享有的共有和共同管理的权利一并转让。\n第二百七十四条　建筑区划内的道路，属于业主共有，但是属于城镇公共道路的除外。建筑区划内的绿地，属于业主共有，但是属于城镇公共绿地或者明示属于个人的除外。建筑区划内的其他公共场所、公用设施和物业服务用房，属于业主共有', 781, '{\"level\": null, \"title\": null, \"chunk_index\": 30}', 'bge-large-zh-v1.5', '2026-09-25 17:05:01');
INSERT INTO `chunk` VALUES ('ccefc867-69fd-41e7-a278-5f4b73edffb8', '16cbea7e-7e36-4f31-afb5-63892345d29c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 23, '确有正当理由需要离开的，应当经决定采取责令候查措施的监察机关批准。\n在同一直辖市、设区的市内跨区活动的，不属于离开所居住的市、县。\n本条第一款所称正当理由，是指就医、就学、参与诉讼、往返居住地与工作地、处理重要家庭事务或者参加重要公务、商务活动等。\n第一百零八条　被责令候查人员需要离开所居住的市、县的，应当向监察机关提出书面申请，并注明事由、目的地、路线、交通方式、往返日期、联系方式等。监察机关应当自收到书面申请之日起三日以内作出决定。被责令候查人员有紧急事由，无法及时提出书面申请的，可以先行通过电话等方式提出申请，并及时补办书面申请手续。\n监察机关批准被责令候查人员离开所居住的市、县的申请后，应当告知其遵守下列要求：\n（一）保持联系方式畅通，并在接到通知后及时到案接受调查；\n（二）严格按照批准的地点、路线、往返日期出行；\n（三）不得从事妨碍调查的活动；\n（四）返回居住地后及时向执行机关报告。\n对于被责令候查人员因正常工作或者生活需要经常性离开所居住的市、县的，可以根据情况简化批准程序，一次性审批其在特定期间内按照批准的地点、路线出行。\n第一百零九条　被责令候查人员具有下列情形之一的，可以认定为监察法第二十三条第三款所规定的违反责令候查规定，情节严重：\n（一）企图逃跑、自杀的；\n（二）实施伪造、隐匿、毁灭证据或者串供、干扰证人作证行为，严重影响调查工作正常进行的；\n（三）对举报人、控告人、被害人、证人、鉴定人等相关人员实施打击报复的；\n（四）未经批准，擅自离开所居住的市、县，严重影响调查工作正常进行，或者两次未经批准，擅自离开所居住的市、县的；\n（五）经通知无正当理由不到案，严重影响调查工作正常进行，或者两次经通知无正当理由不到案的；\n（六）住址、工作单位和联系方式等发生变动，未按规定向监察机关报告，导致无法通知到案，严重影响调查工作正常进行的', 785, '{\"level\": null, \"title\": null, \"chunk_index\": 23}', 'bge-large-zh-v1.5', '2026-09-25 17:04:49');
INSERT INTO `chunk` VALUES ('ccf74886-45fc-40d4-a734-063c4ce59f90', '821ce1fd-178d-4a7e-ab92-3deff1488ce2', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 92, '第四百零二条　行政执法人员徇私舞弊，对依法应当移交司法机关追究刑事责任的不移交，情节严重的，处三年以下有期徒刑或者拘役；造成严重后果的，处三年以上七年以下有期徒刑。\n第四百零三条　国家有关主管部门的国家机关工作人员，徇私舞弊，滥用职权，对不符合法律规定条件的公司设立、登记申请或者股票、债券发行、上市申请，予以批准或者登记，致使公共财产、国家和人民利益遭受重大损失的，处五年以下有期徒刑或者拘役。\n上级部门强令登记机关及其工作人员实施前款行为的，对其直接负责的主管人员，依照前款的规定处罚。\n第四百零四条　税务机关的工作人员徇私舞弊，不征或者少征应征税款，致使国家税收遭受重大损失的，处五年以下有期徒刑或者拘役；造成特别重大损失的，处五年以上有期徒刑。\n第四百零五条　税务机关的工作人员违反法律、行政法规的规定，在办理发售发票、抵扣税款、出口退税工作中，徇私舞弊，致使国家利益遭受重大损失的，处五年以下有期徒刑或者拘役；致使国家利益遭受特别重大损失的，处五年以上有期徒刑。\n其他国家机关工作人员违反国家规定，在提供出口货物报关单、出口收汇核销单等出口退税凭证的工作中，徇私舞弊，致使国家利益遭受重大损失的，依照前款的规定处罚。\n第四百零六条　国家机关工作人员在签订、履行合同过程中，因严重不负责任被诈骗，致使国家利益遭受重大损失的，处三年以下有期徒刑或者拘役；致使国家利益遭受特别重大损失的，处三年以上七年以下有期徒刑。\n第四百零七条　林业主管部门的工作人员违反森林法的规定，超过批准的年采伐限额发放林木采伐许可证或者违反规定滥发林木采伐许可证，情节严重，致使森林遭受严重破坏的，处三年以下有期徒刑或者拘役。\n第四百零八条　负有环境保护监督管理职责的国家机关工作人员严重不负责任，导致发生重大环境污染事故，致使公私财产遭受重大损失或者造成人身伤亡的严重后果的，处三年以下有期徒刑或者拘役', 793, '{\"level\": null, \"title\": null, \"chunk_index\": 92}', 'bge-large-zh-v1.5', '2026-09-25 17:04:56');
INSERT INTO `chunk` VALUES ('ce4d2dd8-3c57-4177-bbf4-19ddf96b795e', '821ce1fd-178d-4a7e-ab92-3deff1488ce2', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 74, '第三百二十八条　盗掘具有历史、艺术、科学价值的古文化遗址、古墓葬的，处三年以上十年以下有期徒刑，并处罚金；情节较轻的，处三年以下有期徒刑、拘役或者管制，并处罚金；有下列情形之一的，处十年以上有期徒刑或者无期徒刑，并处罚金或者没收财产：\n（一）盗掘确定为全国重点文物保护单位和省级文物保护单位的古文化遗址、古墓葬的；\n（二）盗掘古文化遗址、古墓葬集团的首要分子；\n（三）多次盗掘古文化遗址、古墓葬的；\n（四）盗掘古文化遗址、古墓葬，并盗窃珍贵文物或者造成珍贵文物严重破坏的。\n盗掘国家保护的具有科学价值的古人类化石和古脊椎动物化石的，依照前款的规定处罚。\n第三百二十九条　抢夺、窃取国家所有的档案的，处五年以下有期徒刑或者拘役。\n违反档案法的规定，擅自出卖、转让国家所有的档案，情节严重的，处三年以下有期徒刑或者拘役。\n有前两款行为，同时又构成本法规定的其他犯罪的，依照处罚较重的规定定罪处罚。\n第五节　危害公共卫生罪\n第三百三十条　违反传染病防治法的规定，有下列情形之一，引起甲类传染病以及依法确定采取甲类传染病预防、控制措施的传染病传播或者有传播严重危险的，处三年以下有期徒刑或者拘役；后果特别严重的，处三年以上七年以下有期徒刑：\n（一）供水单位供应的饮用水不符合国家规定的卫生标准的；\n（二）拒绝按照疾病预防控制机构提出的卫生要求，对传染病病原体污染的污水、污物、场所和物品进行消毒处理的；\n（三）准许或者纵容传染病病人、病原携带者和疑似传染病病人从事国务院卫生行政部门规定禁止从事的易使该传染病扩散的工作的；\n（四）出售、运输疫区中被传染病病原体污染或者可能被传染病病原体污染的物品，未进行消毒处理的；\n（五）拒绝执行县级以上人民政府、疾病预防控制机构依照传染病防治法提出的预防、控制措施的。\n单位犯前款罪的，对单位判处罚金，并对其直接负责的主管人员和其他直接责任人员，依照前款的规定处罚', 797, '{\"level\": null, \"title\": null, \"chunk_index\": 74}', 'bge-large-zh-v1.5', '2026-09-25 17:04:56');
INSERT INTO `chunk` VALUES ('ceb7e575-91c6-4ffd-8bff-9107e427990f', 'd9d7dc15-8041-43b8-9f75-f112fe3ae003', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 38, '第一百一十八条　发生危险化学品事故，有关地方人民政府及其有关部门不立即组织实施救援，或者不采取必要的应急处置措施减少事故损失，防止事故蔓延、扩大的，对负有责任的领导人员和直接责任人员依法给予处分。\n第一百一十九条　负有危险化学品安全监督管理职责的部门的工作人员，在危险化学品安全监督管理工作中滥用职权、玩忽职守、徇私舞弊的，依法给予处分。\n第一百二十条　违反本法规定，构成违反治安管理行为的，依法给予治安管理处罚；构成犯罪的，依法追究刑事责任。\n第十章　附　　则\n第一百二十一条　监控化学品、属于危险化学品的药品和农药的安全管理，依照本法的规定执行；法律、行政法规另有规定的，依照其规定。\n民用爆炸物品、烟花爆竹、放射性物品、核能物质以及用于国防科研生产的危险化学品的安全管理，不适用本法。\n法律、行政法规对燃气的安全管理另有规定的，依照其规定。\n危险化学品容器属于特种设备的，其安全管理依照有关特种设备安全的法律、行政法规的规定执行。\n第一百二十二条　危险化学品的进出口管理，依照有关对外贸易的法律、行政法规、规章的规定执行；出口危险化学品涉及《中华人民共和国出口管制法》规定的管制物项的，依照有关出口管制的法律、行政法规、规章的规定执行；进口的危险化学品的储存、使用、经营、运输的安全管理，依照本法的规定执行。\n第一百二十三条　公众发现、捡拾的无主危险化学品，由公安机关或者应急管理部门接收。有关部门接收或者依法没收的危险化学品，需要进行处置的，交由生态环境主管部门组织其认定的专业单位进行处置，或者交由有关危险化学品生产企业进行处置。处置所需费用由政府负担。\n第一百二十四条　化学品的危险特性尚未确定的，由国务院应急管理、生态环境、卫生健康部门分别负责组织对该化学品的物理危险性、生态环境危害性、毒理特性进行鉴定。根据鉴定结果需要调整危险化学品目录的，依照本法第三条第二款的规定办理', 794, '{\"level\": null, \"title\": null, \"chunk_index\": 38}', 'bge-large-zh-v1.5', '2026-09-25 17:04:46');
INSERT INTO `chunk` VALUES ('cee248f9-c702-4278-8612-dfdffd721743', '821ce1fd-178d-4a7e-ab92-3deff1488ce2', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 60, '国有公司、企业或者其他国有单位中从事公务的人员和国有公司、企业或者其他国有单位委派到非国有公司、企业以及其他单位从事公务的人员有前款行为的，依照本法第三百八十二条、第三百八十三条的规定定罪处罚。\n第二百七十二条　公司、企业或者其他单位的工作人员，利用职务上的便利，挪用本单位资金归个人使用或者借贷给他人，数额较大、超过三个月未还的，或者虽未超过三个月，但数额较大、进行营利活动的，或者进行非法活动的，处三年以下有期徒刑或者拘役；挪用本单位资金数额巨大的，处三年以上七年以下有期徒刑；数额特别巨大的，处七年以上有期徒刑。\n国有公司、企业或者其他国有单位中从事公务的人员和国有公司、企业或者其他国有单位委派到非国有公司、企业以及其他单位从事公务的人员有前款行为的，依照本法第三百八十四条的规定定罪处罚。\n有第一款行为，在提起公诉前将挪用的资金退还的，可以从轻或者减轻处罚。其中，犯罪较轻的，可以减轻或者免除处罚。\n第二百七十三条　挪用用于救灾、抢险、防汛、优抚、扶贫、移民、救济款物，情节严重，致使国家和人民群众利益遭受重大损害的，对直接责任人员，处三年以下有期徒刑或者拘役；情节特别严重的，处三年以上七年以下有期徒刑。\n第二百七十四条　敲诈勒索公私财物，数额较大或者多次敲诈勒索的，处三年以下有期徒刑、拘役或者管制，并处或者单处罚金；数额巨大或者有其他严重情节的，处三年以上十年以下有期徒刑，并处罚金；数额特别巨大或者有其他特别严重情节的，处十年以上有期徒刑，并处罚金。\n第二百七十五条　故意毁坏公私财物，数额较大或者有其他严重情节的，处三年以下有期徒刑、拘役或者罚金；数额巨大或者有其他特别严重情节的，处三年以上七年以下有期徒刑', 714, '{\"level\": null, \"title\": null, \"chunk_index\": 60}', 'bge-large-zh-v1.5', '2026-09-25 17:04:56');
INSERT INTO `chunk` VALUES ('cf01036e-c482-4c10-9884-c1b168fa7b4f', '821ce1fd-178d-4a7e-ab92-3deff1488ce2', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 16, '以造谣、诽谤或者其他方式煽动颠覆国家政权、推翻社会主义制度的，处五年以下有期徒刑、拘役、管制或者剥夺政治权利；首要分子或者罪行重大的，处五年以上有期徒刑。\n第一百零六条　与境外机构、组织、个人相勾结，实施本章第一百零三条、第一百零四条、第一百零五条规定之罪的，依照各该条的规定从重处罚。\n第一百零七条　境内外机构、组织或者个人资助实施本章第一百零二条、第一百零三条、第一百零四条、第一百零五条规定之罪的，对直接责任人员，处五年以下有期徒刑、拘役、管制或者剥夺政治权利；情节严重的，处五年以上有期徒刑。\n第一百零八条　投敌叛变的，处三年以上十年以下有期徒刑；情节严重或者带领武装部队人员、人民警察、民兵投敌叛变的，处十年以上有期徒刑或者无期徒刑。\n第一百零九条　国家机关工作人员在履行公务期间，擅离岗位，叛逃境外或者在境外叛逃的，处五年以下有期徒刑、拘役、管制或者剥夺政治权利；情节严重的，处五年以上十年以下有期徒刑。\n掌握国家秘密的国家工作人员叛逃境外或者在境外叛逃的，依照前款的规定从重处罚。\n第一百一十条　有下列间谍行为之一，危害国家安全的，处十年以上有期徒刑或者无期徒刑；情节较轻的，处三年以上十年以下有期徒刑：\n（一）参加间谍组织或者接受间谍组织及其代理人的任务的；\n（二）为敌人指示轰击目标的。\n第一百一十一条　为境外的机构、组织、人员窃取、刺探、收买、非法提供国家秘密或者情报的，处五年以上十年以下有期徒刑；情节特别严重的，处十年以上有期徒刑或者无期徒刑；情节较轻的，处五年以下有期徒刑、拘役、管制或者剥夺政治权利。\n第一百一十二条　战时供给敌人武器装备、军用物资资敌的，处十年以上有期徒刑或者无期徒刑；情节较轻的，处三年以上十年以下有期徒刑', 727, '{\"level\": null, \"title\": null, \"chunk_index\": 16}', 'bge-large-zh-v1.5', '2026-09-25 17:04:56');
INSERT INTO `chunk` VALUES ('cf09ffa2-66b3-4cd3-9405-169527294381', 'b25ce095-dfba-4403-acf8-c58eb456ca4c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 125, '第一千零八十八条　夫妻一方因抚育子女、照料老年人、协助另一方工作等负担较多义务的，离婚时有权向另一方请求补偿，另一方应当给予补偿。具体办法由双方协议；协议不成的，由人民法院判决。\n第一千零八十九条　离婚时，夫妻共同债务应当共同偿还。共同财产不足清偿或者财产归各自所有的，由双方协议清偿；协议不成的，由人民法院判决。\n第一千零九十条　离婚时，如果一方生活困难，有负担能力的另一方应当给予适当帮助。具体办法由双方协议；协议不成的，由人民法院判决。\n第一千零九十一条　有下列情形之一，导致离婚的，无过错方有权请求损害赔偿：\n（一）重婚；\n（二）与他人同居；\n（三）实施家庭暴力；\n（四）虐待、遗弃家庭成员；\n（五）有其他重大过错。\n第一千零九十二条　夫妻一方隐藏、转移、变卖、毁损、挥霍夫妻共同财产，或者伪造夫妻共同债务企图侵占另一方财产的，在离婚分割夫妻共同财产时，对该方可以少分或者不分。离婚后，另一方发现有上述行为的，可以向人民法院提起诉讼，请求再次分割夫妻共同财产。\n第五章　收　　养\n第一节　收养关系的成立\n第一千零九十三条　下列未成年人，可以被收养：\n（一）丧失父母的孤儿；\n（二）查找不到生父母的未成年人；\n（三）生父母有特殊困难无力抚养的子女。\n第一千零九十四条　下列个人、组织可以作送养人：\n（一）孤儿的监护人；\n（二）儿童福利机构；\n（三）有特殊困难无力抚养子女的生父母。\n第一千零九十五条　未成年人的父母均不具备完全民事行为能力且可能严重危害该未成年人的，该未成年人的监护人可以将其送养。\n第一千零九十六条　监护人送养孤儿的，应当征得有抚养义务的人同意。有抚养义务的人不同意送养、监护人不愿意继续履行监护职责的，应当依照本法第一编的规定另行确定监护人。\n第一千零九十七条　生父母送养子女，应当双方共同送养。生父母一方不明或者查找不到的，可以单方送养', 782, '{\"level\": null, \"title\": null, \"chunk_index\": 125}', 'bge-large-zh-v1.5', '2026-09-25 17:05:01');
INSERT INTO `chunk` VALUES ('cfc8b076-48d0-470a-a175-99d0a07080b4', 'b25ce095-dfba-4403-acf8-c58eb456ca4c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 92, '旅客无票乘坐、超程乘坐、越级乘坐或者持不符合减价条件的优惠客票乘坐的，应当补交票款，承运人可以按照规定加收票款；旅客不支付票款的，承运人可以拒绝运输。\n实名制客运合同的旅客丢失客票的，可以请求承运人挂失补办，承运人不得再次收取票款和其他不合理费用。\n第八百一十六条　旅客因自己的原因不能按照客票记载的时间乘坐的，应当在约定的期限内办理退票或者变更手续；逾期办理的，承运人可以不退票款，并不再承担运输义务。\n第八百一十七条　旅客随身携带行李应当符合约定的限量和品类要求；超过限量或者违反品类要求携带行李的，应当办理托运手续。\n第八百一十八条　旅客不得随身携带或者在行李中夹带易燃、易爆、有毒、有腐蚀性、有放射性以及可能危及运输工具上人身和财产安全的危险物品或者违禁物品。\n旅客违反前款规定的，承运人可以将危险物品或者违禁物品卸下、销毁或者送交有关部门。旅客坚持携带或者夹带危险物品或者违禁物品的，承运人应当拒绝运输。\n第八百一十九条　承运人应当严格履行安全运输义务，及时告知旅客安全运输应当注意的事项。旅客对承运人为安全运输所作的合理安排应当积极协助和配合。\n第八百二十条　承运人应当按照有效客票记载的时间、班次和座位号运输旅客。承运人迟延运输或者有其他不能正常运输情形的，应当及时告知和提醒旅客，采取必要的安置措施，并根据旅客的要求安排改乘其他班次或者退票；由此造成旅客损失的，承运人应当承担赔偿责任，但是不可归责于承运人的除外。\n第八百二十一条　承运人擅自降低服务标准的，应当根据旅客的请求退票或者减收票款；提高服务标准的，不得加收票款。\n第八百二十二条　承运人在运输过程中，应当尽力救助患有急病、分娩、遇险的旅客。\n第八百二十三条　承运人应当对运输过程中旅客的伤亡承担赔偿责任；但是，伤亡是旅客自身健康原因造成的或者承运人证明伤亡是旅客故意、重大过失造成的除外', 782, '{\"level\": null, \"title\": null, \"chunk_index\": 92}', 'bge-large-zh-v1.5', '2026-09-25 17:05:01');
INSERT INTO `chunk` VALUES ('d0216f05-4ba3-4fae-965b-d1c9b5ccc355', '16cbea7e-7e36-4f31-afb5-63892345d29c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 16, '对于被调查人控告、举报调查人员采用非法方法收集证据，并提供涉嫌非法取证的人员、时间、地点、方式和内容等材料或者线索的，应当受理并进行审核。根据现有材料无法证明证据收集合法性的，应当进行调查核实。\n经调查核实，确认或者不能排除以非法方法收集证据的，对有关证据依法予以排除，不得作为案件定性处置、移送审查起诉的依据。认定调查人员非法取证的，应当依法处理，另行指派调查人员重新调查取证。\n监察机关接到对下级监察机关调查人员采用非法方法收集证据的控告、举报，可以直接进行调查核实，也可以交由下级监察机关调查核实。交由下级监察机关调查核实的，下级监察机关应当及时将调查结果报告上级监察机关。\n第七十四条　对收集的证据材料及扣押的财物应当妥善保管，严格履行交接、调用手续，定期对账核实，不得违规使用、调换、损毁或者自行处理。\n第七十五条　监察机关对行政机关在行政执法和查办案件中收集的物证、书证、视听资料、电子数据，勘验、检查等笔录，以及鉴定意见等证据材料，经审查符合法定要求的，可以作为证据使用。\n根据法律、行政法规规定行使国家行政管理职权的组织在行政执法和查办案件中收集的证据材料，视为行政机关收集的证据材料。\n第七十六条　监察机关对人民法院、人民检察院、公安机关、国家安全机关等在刑事诉讼中收集的物证、书证、视听资料、电子数据，勘验、检查、辨认、侦查实验等笔录，以及鉴定意见等证据材料，经审查符合法定要求的，可以作为证据使用。\n监察机关办理职务违法案件，对于人民法院生效刑事判决、裁定和人民检察院不起诉决定采信的证据材料，可以直接作为证据使用。\n第三节　谈　　话\n第七十七条　监察机关对涉嫌职务违法的监察对象，可以依法进行谈话，要求其如实说明情况或者作出陈述。\n谈话应当个别进行。负责谈话的人员不得少于二人。\n第七十八条　对一般性问题线索的处置，可以采取谈话方式进行，对监察对象给予警示、批评、教育', 796, '{\"level\": null, \"title\": null, \"chunk_index\": 16}', 'bge-large-zh-v1.5', '2026-09-25 17:04:49');
INSERT INTO `chunk` VALUES ('d1964886-4e0e-45e2-850d-eac634467dc0', 'b25ce095-dfba-4403-acf8-c58eb456ca4c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 100, '技术服务合同是当事人一方以技术知识为对方解决特定技术问题所订立的合同，不包括承揽合同和建设工程合同。\n第八百七十九条　技术咨询合同的委托人应当按照约定阐明咨询的问题，提供技术背景材料及有关技术资料，接受受托人的工作成果，支付报酬。\n第八百八十条　技术咨询合同的受托人应当按照约定的期限完成咨询报告或者解答问题，提出的咨询报告应当达到约定的要求。\n第八百八十一条　技术咨询合同的委托人未按照约定提供必要的资料，影响工作进度和质量，不接受或者逾期接受工作成果的，支付的报酬不得追回，未支付的报酬应当支付。\n技术咨询合同的受托人未按期提出咨询报告或者提出的咨询报告不符合约定的，应当承担减收或者免收报酬等违约责任。\n技术咨询合同的委托人按照受托人符合约定要求的咨询报告和意见作出决策所造成的损失，由委托人承担，但是当事人另有约定的除外。\n第八百八十二条　技术服务合同的委托人应当按照约定提供工作条件，完成配合事项，接受工作成果并支付报酬。\n第八百八十三条　技术服务合同的受托人应当按照约定完成服务项目，解决技术问题，保证工作质量，并传授解决技术问题的知识。\n第八百八十四条　技术服务合同的委托人不履行合同义务或者履行合同义务不符合约定，影响工作进度和质量，不接受或者逾期接受工作成果的，支付的报酬不得追回，未支付的报酬应当支付。\n技术服务合同的受托人未按照约定完成服务工作的，应当承担免收报酬等违约责任。\n第八百八十五条　技术咨询合同、技术服务合同履行过程中，受托人利用委托人提供的技术资料和工作条件完成的新的技术成果，属于受托人。委托人利用受托人的工作成果完成的新的技术成果，属于委托人。当事人另有约定的，按照其约定。\n第八百八十六条　技术咨询合同和技术服务合同对受托人正常开展工作所需费用的负担没有约定或者约定不明确的，由受托人负担', 765, '{\"level\": null, \"title\": null, \"chunk_index\": 100}', 'bge-large-zh-v1.5', '2026-09-25 17:05:01');
INSERT INTO `chunk` VALUES ('d238ae9c-3b6a-4b47-ab5c-7b078dbb085d', '821ce1fd-178d-4a7e-ab92-3deff1488ce2', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 62, '冒充人民警察招摇撞骗的，依照前款的规定从重处罚。\n第二百八十条　伪造、变造、买卖或者盗窃、抢夺、毁灭国家机关的公文、证件、印章的，处三年以下有期徒刑、拘役、管制或者剥夺政治权利，并处罚金；情节严重的，处三年以上十年以下有期徒刑，并处罚金。\n伪造公司、企业、事业单位、人民团体的印章的，处三年以下有期徒刑、拘役、管制或者剥夺政治权利，并处罚金。\n伪造、变造、买卖居民身份证、护照、社会保障卡、驾驶证等依法可以用于证明身份的证件的，处三年以下有期徒刑、拘役、管制或者剥夺政治权利，并处罚金；情节严重的，处三年以上七年以下有期徒刑，并处罚金。\n第二百八十条之一　在依照国家规定应当提供身份证明的活动中，使用伪造、变造的或者盗用他人的居民身份证、护照、社会保障卡、驾驶证等依法可以用于证明身份的证件，情节严重的，处拘役或者管制，并处或者单处罚金。\n有前款行为，同时构成其他犯罪的，依照处罚较重的规定定罪处罚。\n第二百八十条之二　盗用、冒用他人身份，顶替他人取得的高等学历教育入学资格、公务员录用资格、就业安置待遇的，处三年以下有期徒刑、拘役或者管制，并处罚金。\n组织、指使他人实施前款行为的，依照前款的规定从重处罚。\n国家工作人员有前两款行为，又构成其他犯罪的，依照数罪并罚的规定处罚。\n第二百八十一条　非法生产、买卖人民警察制式服装、车辆号牌等专用标志、警械，情节严重的，处三年以下有期徒刑、拘役或者管制，并处或者单处罚金。\n单位犯前款罪的，对单位判处罚金，并对其直接负责的主管人员和其他直接责任人员，依照前款的规定处罚。\n第二百八十二条　以窃取、刺探、收买方法，非法获取国家秘密的，处三年以下有期徒刑、拘役、管制或者剥夺政治权利；情节严重的，处三年以上七年以下有期徒刑。\n非法持有属于国家绝密、机密的文件、资料或者其他物品，拒不说明来源与用途的，处三年以下有期徒刑、拘役或者管制', 787, '{\"level\": null, \"title\": null, \"chunk_index\": 62}', 'bge-large-zh-v1.5', '2026-09-25 17:04:56');
INSERT INTO `chunk` VALUES ('d27bcd20-d102-44fa-bcd0-bfbdb427f5a4', '821ce1fd-178d-4a7e-ab92-3deff1488ce2', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 99, '\n附件一\n全国人民代表大会常务委员会制定的下列条例、补充规定和决定，已纳入本法或者已不适用，自本法施行之日起，予以废止：\n1.中华人民共和国惩治军人违反职责罪暂行条例\n2.关于严惩严重破坏经济的罪犯的决定\n3.关于严惩严重危害社会治安的犯罪分子的决定\n4.关于惩治走私罪的补充规定\n5.关于惩治贪污罪贿赂罪的补充规定\n6.关于惩治泄露国家秘密犯罪的补充规定\n7.关于惩治捕杀国家重点保护的珍贵、濒危野生动物犯罪的补充规定\n8.关于惩治侮辱中华人民共和国国旗国徽罪的决定\n9.关于惩治盗掘古文化遗址古墓葬犯罪的补充规定\n10.关于惩治劫持航空器犯罪分子的决定\n11.关于惩治假冒注册商标犯罪的补充规定\n12.关于惩治生产、销售伪劣商品犯罪的决定\n13.关于惩治侵犯著作权的犯罪的决定\n14.关于惩治违反公司法的犯罪的决定\n15.关于处理逃跑或者重新犯罪的劳改犯和劳教人员的决定\n附件二\n全国人民代表大会常务委员会制定的下列补充规定和决定予以保留，其中，有关行政处罚和行政措施的规定继续有效；有关刑事责任的规定已纳入本法，自本法施行之日起，适用本法规定：\n1.关于禁毒的决定\n2.关于惩治走私、制作、贩卖、传播淫秽物品的犯罪分子的决定\n3.关于严禁卖淫嫖娼的决定\n4.关于严惩拐卖、绑架妇女、儿童的犯罪分子的决定\n5.关于惩治偷税、抗税犯罪的补充规定\n6.关于严惩组织、运送他人偷越国（边）境犯罪的补充规定\n7.关于惩治破坏金融秩序犯罪的决定\n8.关于惩治虚开、伪造和非法出售增值税专用发票犯罪的决定', 648, '{\"level\": null, \"title\": null, \"chunk_index\": 99}', 'bge-large-zh-v1.5', '2026-09-25 17:04:56');
INSERT INTO `chunk` VALUES ('d2b7096b-1a35-48e5-99a2-7a895e1d63d2', 'b25ce095-dfba-4403-acf8-c58eb456ca4c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 37, '第三百二十七条　因不动产或者动产被征收、征用致使用益物权消灭或者影响用益物权行使的，用益物权人有权依据本法第二百四十三条、第二百四十五条的规定获得相应补偿。\n第三百二十八条　依法取得的海域使用权受法律保护。\n第三百二十九条　依法取得的探矿权、采矿权、取水权和使用水域、滩涂从事养殖、捕捞的权利受法律保护。\n第十一章　土地承包经营权\n第三百三十条　农村集体经济组织实行家庭承包经营为基础、统分结合的双层经营体制。\n农民集体所有和国家所有由农民集体使用的耕地、林地、草地以及其他用于农业的土地，依法实行土地承包经营制度。\n第三百三十一条　土地承包经营权人依法对其承包经营的耕地、林地、草地等享有占有、使用和收益的权利，有权从事种植业、林业、畜牧业等农业生产。\n第三百三十二条　耕地的承包期为三十年。草地的承包期为三十年至五十年。林地的承包期为三十年至七十年。\n前款规定的承包期限届满，由土地承包经营权人依照农村土地承包的法律规定继续承包。\n第三百三十三条　土地承包经营权自土地承包经营权合同生效时设立。\n登记机构应当向土地承包经营权人发放土地承包经营权证、林权证等证书，并登记造册，确认土地承包经营权。\n第三百三十四条　土地承包经营权人依照法律规定，有权将土地承包经营权互换、转让。未经依法批准，不得将承包地用于非农建设。\n第三百三十五条　土地承包经营权互换、转让的，当事人可以向登记机构申请登记；未经登记，不得对抗善意第三人。\n第三百三十六条　承包期内发包人不得调整承包地。\n因自然灾害严重毁损承包地等特殊情形，需要适当调整承包的耕地和草地的，应当依照农村土地承包的法律规定办理。\n第三百三十七条　承包期内发包人不得收回承包地。法律另有规定的，依照其规定。\n第三百三十八条　承包地被征收的，土地承包经营权人有权依据本法第二百四十三条的规定获得相应补偿', 774, '{\"level\": null, \"title\": null, \"chunk_index\": 37}', 'bge-large-zh-v1.5', '2026-09-25 17:05:01');
INSERT INTO `chunk` VALUES ('d317189b-3446-4c47-9c6d-feaa7e01f12f', '22a2c356-7a68-4455-b657-333e3dba1e1a', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 4, '第六条　中华人民共和国的社会主义经济制度的基础是生产资料的社会主义公有制，即全民所有制和劳动群众集体所有制。社会主义公有制消灭人剥削人的制度，实行各尽所能、按劳分配的原则。\n国家在社会主义初级阶段，坚持公有制为主体、多种所有制经济共同发展的基本经济制度，坚持按劳分配为主体、多种分配方式并存的分配制度。\n第七条　国有经济，即社会主义全民所有制经济，是国民经济中的主导力量。国家保障国有经济的巩固和发展。\n第八条　农村集体经济组织实行家庭承包经营为基础、统分结合的双层经营体制。农村中的生产、供销、信用、消费等各种形式的合作经济，是社会主义劳动群众集体所有制经济。参加农村集体经济组织的劳动者，有权在法律规定的范围内经营自留地、自留山、家庭副业和饲养自留畜。\n城镇中的手工业、工业、建筑业、运输业、商业、服务业等行业的各种形式的合作经济，都是社会主义劳动群众集体所有制经济。\n国家保护城乡集体经济组织的合法的权利和利益，鼓励、指导和帮助集体经济的发展。\n第九条　矿藏、水流、森林、山岭、草原、荒地、滩涂等自然资源，都属于国家所有，即全民所有；由法律规定属于集体所有的森林和山岭、草原、荒地、滩涂除外。\n国家保障自然资源的合理利用，保护珍贵的动物和植物。禁止任何组织或者个人用任何手段侵占或者破坏自然资源。\n第十条　城市的土地属于国家所有。\n农村和城市郊区的土地，除由法律规定属于国家所有的以外，属于集体所有；宅基地和自留地、自留山，也属于集体所有。\n国家为了公共利益的需要，可以依照法律规定对土地实行征收或者征用并给予补偿。\n任何组织或者个人不得侵占、买卖或者以其他形式非法转让土地。土地的使用权可以依照法律的规定转让。\n一切使用土地的组织和个人必须合理地利用土地。\n第十一条　在法律规定范围内的个体经济、私营经济等非公有制经济，是社会主义市场经济的重要组成部分', 780, '{\"level\": null, \"title\": null, \"chunk_index\": 4}', 'bge-large-zh-v1.5', '2026-09-25 17:04:28');
INSERT INTO `chunk` VALUES ('d3fec250-102d-42f1-a2af-0791db757e22', '821ce1fd-178d-4a7e-ab92-3deff1488ce2', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 71, '第三百一十二条　明知是犯罪所得及其产生的收益而予以窝藏、转移、收购、代为销售或者以其他方法掩饰、隐瞒的，处三年以下有期徒刑、拘役或者管制，并处或者单处罚金；情节严重的，处三年以上七年以下有期徒刑，并处罚金。\n单位犯前款罪的，对单位判处罚金，并对其直接负责的主管人员和其他直接责任人员，依照前款的规定处罚。\n第三百一十三条　对人民法院的判决、裁定有能力执行而拒不执行，情节严重的，处三年以下有期徒刑、拘役或者罚金；情节特别严重的，处三年以上七年以下有期徒刑，并处罚金。\n单位犯前款罪的，对单位判处罚金，并对其直接负责的主管人员和其他直接责任人员，依照前款的规定处罚。\n第三百一十四条　隐藏、转移、变卖、故意毁损已被司法机关查封、扣押、冻结的财产，情节严重的，处三年以下有期徒刑、拘役或者罚金。\n第三百一十五条　依法被关押的罪犯，有下列破坏监管秩序行为之一，情节严重的，处三年以下有期徒刑：\n（一）殴打监管人员的；\n（二）组织其他被监管人破坏监管秩序的；\n（三）聚众闹事，扰乱正常监管秩序的；\n（四）殴打、体罚或者指使他人殴打、体罚其他被监管人的。\n第三百一十六条　依法被关押的罪犯、被告人、犯罪嫌疑人脱逃的，处五年以下有期徒刑或者拘役。\n劫夺押解途中的罪犯、被告人、犯罪嫌疑人的，处三年以上七年以下有期徒刑；情节严重的，处七年以上有期徒刑。\n第三百一十七条　组织越狱的首要分子和积极参加的，处五年以上有期徒刑；其他参加的，处五年以下有期徒刑或者拘役。\n暴动越狱或者聚众持械劫狱的首要分子和积极参加的，处十年以上有期徒刑或者无期徒刑；情节特别严重的，处死刑；其他参加的，处三年以上十年以下有期徒刑', 696, '{\"level\": null, \"title\": null, \"chunk_index\": 71}', 'bge-large-zh-v1.5', '2026-09-25 17:04:56');
INSERT INTO `chunk` VALUES ('d424e578-7459-4336-81da-299218b8d1e4', 'd9d7dc15-8041-43b8-9f75-f112fe3ae003', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 32, '第一百零七条　危险化学品生产企业、经营企业有下列情形之一的，由应急管理部门责令限期改正，没收违法所得，并处二十万元以上五十万元以下的罚款；逾期不改正的，责令停产停业整顿直至由原发证机关吊销其危险化学品安全生产许可证、危险化学品经营许可证，对其直接负责的主管人员和其他直接责任人员处五万元以上十万元以下的罚款；相关许可证件被吊销的，由市场监督管理部门责令其办理经营范围变更登记或者吊销其营业执照：\n（一）向不具有本法第五十八条第一款、第二款规定的相关许可证件或者证明文件的单位销售剧毒化学品、易制爆危险化学品；\n（二）不按照剧毒化学品购买许可证载明的品种、数量销售剧毒化学品；\n（三）向个人销售剧毒化学品（属于剧毒化学品的农药除外）、易制爆危险化学品（含有易制爆危险化学品的食品添加剂、药品、兽药、消毒剂等生活用品除外）。\n不具有本法第五十八条第一款、第二款规定的相关许可证件或者证明文件的单位购买剧毒化学品、易制爆危险化学品，或者个人购买剧毒化学品（属于剧毒化学品的农药除外）、易制爆危险化学品（含有易制爆危险化学品的食品添加剂、药品、兽药、消毒剂等生活用品除外）的，由公安机关没收所购买的剧毒化学品、易制爆危险化学品，可以并处二万元以上五万元以下的罚款。\n使用剧毒化学品、易制爆危险化学品的单位出借或者向不具有本法第五十八条第一款、第二款规定的相关许可证件或者证明文件的单位转让其购买的剧毒化学品、易制爆危险化学品，或者向个人转让其购买的剧毒化学品（属于剧毒化学品的农药除外）、易制爆危险化学品（含有易制爆危险化学品的食品添加剂、药品、兽药、消毒剂等生活用品除外）的，由公安机关责令限期改正，没收违法所得，并处十万元以上五十万元以下的罚款；逾期不改正的，责令停产停业整顿', 736, '{\"level\": null, \"title\": null, \"chunk_index\": 32}', 'bge-large-zh-v1.5', '2026-09-25 17:04:46');
INSERT INTO `chunk` VALUES ('d445fe68-774d-4a2a-8ac9-74bd1c5d81af', 'b25ce095-dfba-4403-acf8-c58eb456ca4c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 93, '前款规定适用于按照规定免票、持优待票或者经承运人许可搭乘的无票旅客。\n第八百二十四条　在运输过程中旅客随身携带物品毁损、灭失，承运人有过错的，应当承担赔偿责任。\n旅客托运的行李毁损、灭失的，适用货物运输的有关规定。\n第三节　货运合同\n第八百二十五条　托运人办理货物运输，应当向承运人准确表明收货人的姓名、名称或者凭指示的收货人，货物的名称、性质、重量、数量，收货地点等有关货物运输的必要情况。\n因托运人申报不实或者遗漏重要情况，造成承运人损失的，托运人应当承担赔偿责任。\n第八百二十六条　货物运输需要办理审批、检验等手续的，托运人应当将办理完有关手续的文件提交承运人。\n第八百二十七条　托运人应当按照约定的方式包装货物。对包装方式没有约定或者约定不明确的，适用本法第六百一十九条的规定。\n托运人违反前款规定的，承运人可以拒绝运输。\n第八百二十八条　托运人托运易燃、易爆、有毒、有腐蚀性、有放射性等危险物品的，应当按照国家有关危险物品运输的规定对危险物品妥善包装，做出危险物品标志和标签，并将有关危险物品的名称、性质和防范措施的书面材料提交承运人。\n托运人违反前款规定的，承运人可以拒绝运输，也可以采取相应措施以避免损失的发生，因此产生的费用由托运人负担。\n第八百二十九条　在承运人将货物交付收货人之前，托运人可以要求承运人中止运输、返还货物、变更到达地或者将货物交给其他收货人，但是应当赔偿承运人因此受到的损失。\n第八百三十条　货物运输到达后，承运人知道收货人的，应当及时通知收货人，收货人应当及时提货。收货人逾期提货的，应当向承运人支付保管费等费用。\n第八百三十一条　收货人提货时应当按照约定的期限检验货物。对检验货物的期限没有约定或者约定不明确，依据本法第五百一十条的规定仍不能确定的，应当在合理期限内检验货物', 757, '{\"level\": null, \"title\": null, \"chunk_index\": 93}', 'bge-large-zh-v1.5', '2026-09-25 17:05:01');
INSERT INTO `chunk` VALUES ('d49f809d-767d-430d-94ef-2e858f601655', '22a2c356-7a68-4455-b657-333e3dba1e1a', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 13, '第六十七条　全国人民代表大会常务委员会行使下列职权：\n（一）解释宪法，监督宪法的实施；\n（二）制定和修改除应当由全国人民代表大会制定的法律以外的其他法律；\n（三）在全国人民代表大会闭会期间，对全国人民代表大会制定的法律进行部分补充和修改，但是不得同该法律的基本原则相抵触；\n（四）解释法律；\n（五）在全国人民代表大会闭会期间，审查和批准国民经济和社会发展计划、国家预算在执行过程中所必须作的部分调整方案；\n（六）监督国务院、中央军事委员会、国家监察委员会、最高人民法院和最高人民检察院的工作；\n（七）撤销国务院制定的同宪法、法律相抵触的行政法规、决定和命令；\n（八）撤销省、自治区、直辖市国家权力机关制定的同宪法、法律和行政法规相抵触的地方性法规和决议；\n（九）在全国人民代表大会闭会期间，根据国务院总理的提名，决定部长、委员会主任、审计长、秘书长的人选；\n（十）在全国人民代表大会闭会期间，根据中央军事委员会主席的提名，决定中央军事委员会其他组成人员的人选；\n（十一）根据国家监察委员会主任的提请，任免国家监察委员会副主任、委员；\n（十二）根据最高人民法院院长的提请，任免最高人民法院副院长、审判员、审判委员会委员和军事法院院长；\n（十三）根据最高人民检察院检察长的提请，任免最高人民检察院副检察长、检察员、检察委员会委员和军事检察院检察长，并且批准省、自治区、直辖市的人民检察院检察长的任免；\n（十四）决定驻外全权代表的任免；\n（十五）决定同外国缔结的条约和重要协定的批准和废除；\n（十六）规定军人和外交人员的衔级制度和其他专门衔级制度；\n（十七）规定和决定授予国家的勋章和荣誉称号；\n（十八）决定特赦；\n（十九）在全国人民代表大会闭会期间，如果遇到国家遭受武装侵犯或者必须履行国际间共同防止侵略的条约的情况，决定战争状态的宣布；\n（二十）决定全国总动员或者局部动员', 785, '{\"level\": null, \"title\": null, \"chunk_index\": 13}', 'bge-large-zh-v1.5', '2026-09-25 17:04:28');
INSERT INTO `chunk` VALUES ('d518429d-7989-4414-989f-2bde8d09751d', '821ce1fd-178d-4a7e-ab92-3deff1488ce2', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 57, '第二百五十四条　国家机关工作人员滥用职权、假公济私，对控告人、申诉人、批评人、举报人实行报复陷害的，处二年以下有期徒刑或者拘役；情节严重的，处二年以上七年以下有期徒刑。\n第二百五十五条　公司、企业、事业单位、机关、团体的领导人，对依法履行职责、抵制违反会计法、统计法行为的会计、统计人员实行打击报复，情节恶劣的，处三年以下有期徒刑或者拘役。\n第二百五十六条　在选举各级人民代表大会代表和国家机关领导人员时，以暴力、威胁、欺骗、贿赂、伪造选举文件、虚报选举票数等手段破坏选举或者妨害选民和代表自由行使选举权和被选举权，情节严重的，处三年以下有期徒刑、拘役或者剥夺政治权利。\n第二百五十七条　以暴力干涉他人婚姻自由的，处二年以下有期徒刑或者拘役。\n犯前款罪，致使被害人死亡的，处二年以上七年以下有期徒刑。\n第一款罪，告诉的才处理。\n第二百五十八条　有配偶而重婚的，或者明知他人有配偶而与之结婚的，处二年以下有期徒刑或者拘役。\n第二百五十九条　明知是现役军人的配偶而与之同居或者结婚的，处三年以下有期徒刑或者拘役。\n利用职权、从属关系，以胁迫手段奸淫现役军人的妻子的，依照本法第二百三十六条的规定定罪处罚。\n第二百六十条　虐待家庭成员，情节恶劣的，处二年以下有期徒刑、拘役或者管制。\n犯前款罪，致使被害人重伤、死亡的，处二年以上七年以下有期徒刑。\n第一款罪，告诉的才处理，但被害人没有能力告诉，或者因受到强制、威吓无法告诉的除外。\n第二百六十条之一　对未成年人、老年人、患病的人、残疾人等负有监护、看护职责的人虐待被监护、看护的人，情节恶劣的，处三年以下有期徒刑或者拘役。\n单位犯前款罪的，对单位判处罚金，并对其直接负责的主管人员和其他直接责任人员，依照前款的规定处罚。\n有第一款行为，同时构成其他犯罪的，依照处罚较重的规定定罪处罚', 763, '{\"level\": null, \"title\": null, \"chunk_index\": 57}', 'bge-large-zh-v1.5', '2026-09-25 17:04:56');
INSERT INTO `chunk` VALUES ('d5567baf-ec7f-4604-bf20-bc242b80adf5', 'b25ce095-dfba-4403-acf8-c58eb456ca4c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 64, '解除合同的事由发生时，解除权人可以解除合同。\n第五百六十三条　有下列情形之一的，当事人可以解除合同：\n（一）因不可抗力致使不能实现合同目的；\n（二）在履行期限届满前，当事人一方明确表示或者以自己的行为表明不履行主要债务；\n（三）当事人一方迟延履行主要债务，经催告后在合理期限内仍未履行；\n（四）当事人一方迟延履行债务或者有其他违约行为致使不能实现合同目的；\n（五）法律规定的其他情形。\n以持续履行的债务为内容的不定期合同，当事人可以随时解除合同，但是应当在合理期限之前通知对方。\n第五百六十四条　法律规定或者当事人约定解除权行使期限，期限届满当事人不行使的，该权利消灭。\n法律没有规定或者当事人没有约定解除权行使期限，自解除权人知道或者应当知道解除事由之日起一年内不行使，或者经对方催告后在合理期限内不行使的，该权利消灭。\n第五百六十五条　当事人一方依法主张解除合同的，应当通知对方。合同自通知到达对方时解除；通知载明债务人在一定期限内不履行债务则合同自动解除，债务人在该期限内未履行债务的，合同自通知载明的期限届满时解除。对方对解除合同有异议的，任何一方当事人均可以请求人民法院或者仲裁机构确认解除行为的效力。\n当事人一方未通知对方，直接以提起诉讼或者申请仲裁的方式依法主张解除合同，人民法院或者仲裁机构确认该主张的，合同自起诉状副本或者仲裁申请书副本送达对方时解除。\n第五百六十六条　合同解除后，尚未履行的，终止履行；已经履行的，根据履行情况和合同性质，当事人可以请求恢复原状或者采取其他补救措施，并有权请求赔偿损失。\n合同因违约解除的，解除权人可以请求违约方承担违约责任，但是当事人另有约定的除外。\n主合同解除后，担保人对债务人应当承担的民事责任仍应当承担担保责任，但是担保合同另有约定的除外。\n第五百六十七条　合同的权利义务关系终止，不影响合同中结算和清理条款的效力', 787, '{\"level\": null, \"title\": null, \"chunk_index\": 64}', 'bge-large-zh-v1.5', '2026-09-25 17:05:01');
INSERT INTO `chunk` VALUES ('d594320d-47a9-4594-aaac-3aa1b87afa91', '16cbea7e-7e36-4f31-afb5-63892345d29c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 45, '监察机关根据工作需要，经审批可以对谈话、函询情况进行抽查核实。\n承办部门应当根据谈话、函询的情况，提出初步核实、拟立案调查、予以了结、暂存待查，或者移送有关部门、机关处理等建议，按程序报批后办理。\n第二百零七条　监察机关对具有可查性的职务违法和职务犯罪问题线索，应当按规定报批后，依法开展初步核实工作。采取初步核实方式处置问题线索，应当确定初步核实对象，制定工作方案，明确需要核实的问题和采取的措施，成立核查组。\n在初步核实中应当注重收集客观性证据，确保真实性和准确性。在初步核实中发现或者受理被核查人新的具有可查性的问题线索的，应当经审批纳入原初核方案开展核查。\n核查组在初步核实工作结束后应当撰写初步核实情况报告，列明被核查人基本情况、反映的主要问题、办理依据、初步核实结果、存在疑点、处理建议，由全体人员签名。\n承办部门应当综合分析初步核实情况，提出拟立案调查、予以了结、暂存待查，或者移送有关部门、机关处理等建议，按照批准初步核实的程序报批。\n第二百零八条　监察机关根据适当了解、谈话、函询或者初步核实情况，发现公职人员有职务违法行为但情节较轻的，可以按照本条例第二百三十一条规定处理，予以了结。\n第二百零九条　检举控告人使用本人真实姓名或者本单位名称，有电话等具体联系方式的，属于实名检举控告。监察机关对实名检举控告应当优先办理、优先处置，依法给予答复。虽有署名但不是检举控告人真实姓名（单位名称）或者无法验证的检举控告，按照匿名检举控告处理。\n信访举报部门对属于本机关受理的实名检举控告，应当在收到检举控告之日起十五个工作日以内按规定告知实名检举控告人受理情况，并做好记录。\n调查人员应当将实名检举控告的处理结果在办结之日起十五个工作日以内向检举控告人反馈，并记录反馈情况。对检举控告人提出异议的应当如实记录，并向其进行说明；对提供新证据材料的，应当依法核查处理', 787, '{\"level\": null, \"title\": null, \"chunk_index\": 45}', 'bge-large-zh-v1.5', '2026-09-25 17:04:49');
INSERT INTO `chunk` VALUES ('d6b9badf-4d5d-4802-9eb0-b2df08346c33', '16cbea7e-7e36-4f31-afb5-63892345d29c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 18, '第八十四条　与被调查人进行谈话，应当合理安排时间、控制时长，保证其饮食和必要的休息时间。\n第八十五条　谈话笔录应当在谈话现场制作。笔录应当详细具体，如实反映谈话情况。笔录制作完成后，应当交给被调查人核对。被调查人没有阅读能力的，应当向其宣读。\n笔录记载有遗漏或者差错的，应当补充或者更正，由被调查人在补充或者更正处捺指印。被调查人核对无误后，应当在笔录中逐页签名、捺指印。被调查人拒绝签名、捺指印的，调查人员应当在笔录中记明。调查人员也应当在笔录中签名。\n第八十六条　被调查人请求自行书写说明材料的，应当准许。必要时，调查人员可以要求被调查人自行书写说明材料。\n被调查人应当在说明材料上逐页签名、捺指印，在末页写明日期。对说明材料有修改的，在修改之处应当捺指印。说明材料应当由二名调查人员接收，在首页记明接收的日期并签名。\n第八十七条　本条例第八十一条至第八十六条的规定，也适用于在初步核实中开展的谈话。\n第四节　讯　　问\n第八十八条　监察机关对涉嫌职务犯罪的被调查人，可以依法进行讯问，要求其如实供述涉嫌犯罪的情况。\n第八十九条　讯问被管护人员、被留置人员，应当在留置场所进行。\n第九十条　讯问应当个别进行，调查人员不得少于二人。\n首次讯问时，应当向被讯问人出示《被调查人权利义务告知书》，由其签名、捺指印。被讯问人拒绝签名、捺指印的，调查人员应当在文书上记明。被讯问人未被限制人身自由的，应当在首次讯问时向其出具《讯问通知书》', 615, '{\"level\": null, \"title\": null, \"chunk_index\": 18}', 'bge-large-zh-v1.5', '2026-09-25 17:04:49');
INSERT INTO `chunk` VALUES ('d75c9fd4-fcbd-47f2-a9ac-9aae08af1f25', '16cbea7e-7e36-4f31-afb5-63892345d29c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 4, '第二十三条　监察机关应当依法运用大数据、人工智能等信息化手段，整合各类监督信息资源，强化数据综合分析研判，促进及时预警风险、精准发现问题。\n第二十四条　监察机关开展监察监督，应当与纪律监督、派驻监督、巡视监督统筹衔接，与人大监督、民主监督、行政监督、司法监督、审计监督、财会监督、统计监督、群众监督和舆论监督等贯通协调，健全信息、资源、成果共享等机制，形成监督合力。\n第三节　监察调查\n第二十五条　监察机关依法履行监察调查职责，依据监察法、《中华人民共和国公职人员政务处分法》（以下简称政务处分法）和《中华人民共和国刑法》（以下简称刑法）等规定对职务违法和职务犯罪进行调查。\n第二十六条　监察机关负责调查的职务违法是指公职人员实施的与其职务相关联，虽不构成犯罪但依法应当承担法律责任的下列违法行为：\n（一）利用职权实施的违法行为；\n（二）利用职务上的影响实施的违法行为；\n（三）履行职责不力、失职失责的违法行为；\n（四）其他违反与公职人员职务相关的特定义务的违法行为。\n第二十七条　监察机关发现公职人员存在其他违法行为，具有下列情形之一的，可以依法进行调查、处置：\n（一）超过行政违法追究时效，或者超过犯罪追诉时效、未追究刑事责任，但需要依法给予政务处分的；\n（二）被追究行政法律责任，需要依法给予政务处分的；\n（三）监察机关调查职务违法或者职务犯罪时，对被调查人实施的事实简单、清楚，需要依法给予政务处分的其他违法行为一并查核的。\n监察机关发现公职人员成为监察对象前有前款规定的违法行为的，依照前款规定办理。\n第二十八条　监察机关依法对监察法第十一条第二项规定的职务犯罪进行调查', 690, '{\"level\": null, \"title\": null, \"chunk_index\": 4}', 'bge-large-zh-v1.5', '2026-09-25 17:04:49');
INSERT INTO `chunk` VALUES ('d75f0e73-f04a-4270-bf44-c1f18ecd1b29', '821ce1fd-178d-4a7e-ab92-3deff1488ce2', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 41, '第一百九十三条　有下列情形之一，以非法占有为目的，诈骗银行或者其他金融机构的贷款，数额较大的，处五年以下有期徒刑或者拘役，并处二万元以上二十万元以下罚金；数额巨大或者有其他严重情节的，处五年以上十年以下有期徒刑，并处五万元以上五十万元以下罚金；数额特别巨大或者有其他特别严重情节的，处十年以上有期徒刑或者无期徒刑，并处五万元以上五十万元以下罚金或者没收财产：\n（一）编造引进资金、项目等虚假理由的；\n（二）使用虚假的经济合同的；\n（三）使用虚假的证明文件的；\n（四）使用虚假的产权证明作担保或者超出抵押物价值重复担保的；\n（五）以其他方法诈骗贷款的。\n第一百九十四条　有下列情形之一，进行金融票据诈骗活动，数额较大的，处五年以下有期徒刑或者拘役，并处二万元以上二十万元以下罚金；数额巨大或者有其他严重情节的，处五年以上十年以下有期徒刑，并处五万元以上五十万元以下罚金；数额特别巨大或者有其他特别严重情节的，处十年以上有期徒刑或者无期徒刑，并处五万元以上五十万元以下罚金或者没收财产：\n（一）明知是伪造、变造的汇票、本票、支票而使用的；\n（二）明知是作废的汇票、本票、支票而使用的；\n（三）冒用他人的汇票、本票、支票的；\n（四）签发空头支票或者与其预留印鉴不符的支票，骗取财物的；\n（五）汇票、本票的出票人签发无资金保证的汇票、本票或者在出票时作虚假记载，骗取财物的。\n使用伪造、变造的委托收款凭证、汇款凭证、银行存单等其他银行结算凭证的，依照前款的规定处罚', 628, '{\"level\": null, \"title\": null, \"chunk_index\": 41}', 'bge-large-zh-v1.5', '2026-09-25 17:04:56');
INSERT INTO `chunk` VALUES ('d8981deb-369d-4faa-8154-d7c4fb509c3b', '821ce1fd-178d-4a7e-ab92-3deff1488ce2', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 2, '第二条　中华人民共和国刑法的任务，是用刑罚同一切犯罪行为作斗争，以保卫国家安全，保卫人民民主专政的政权和社会主义制度，保护国有财产和劳动群众集体所有的财产，保护公民私人所有的财产，保护公民的人身权利、民主权利和其他权利，维护社会秩序、经济秩序，保障社会主义建设事业的顺利进行。\n第三条　法律明文规定为犯罪行为的，依照法律定罪处刑；法律没有明文规定为犯罪行为的，不得定罪处刑。\n第四条　对任何人犯罪，在适用法律上一律平等。不允许任何人有超越法律的特权。\n第五条　刑罚的轻重，应当与犯罪分子所犯罪行和承担的刑事责任相适应。\n第六条　凡在中华人民共和国领域内犯罪的，除法律有特别规定的以外，都适用本法。\n凡在中华人民共和国船舶或者航空器内犯罪的，也适用本法。\n犯罪的行为或者结果有一项发生在中华人民共和国领域内的，就认为是在中华人民共和国领域内犯罪。\n第七条　中华人民共和国公民在中华人民共和国领域外犯本法规定之罪的，适用本法，但是按本法规定的最高刑为三年以下有期徒刑的，可以不予追究。\n中华人民共和国国家工作人员和军人在中华人民共和国领域外犯本法规定之罪的，适用本法。\n第八条　外国人在中华人民共和国领域外对中华人民共和国国家或者公民犯罪，而按本法规定的最低刑为三年以上有期徒刑的，可以适用本法，但是按照犯罪地的法律不受处罚的除外。\n第九条　对于中华人民共和国缔结或者参加的国际条约所规定的罪行，中华人民共和国在所承担条约义务的范围内行使刑事管辖权的，适用本法。\n第十条　凡在中华人民共和国领域外犯罪，依照本法应当负刑事责任的，虽然经过外国审判，仍然可以依照本法追究，但是在外国已经受过刑罚处罚的，可以免除或者减轻处罚。\n第十一条　享有外交特权和豁免权的外国人的刑事责任，通过外交途径解决', 742, '{\"level\": null, \"title\": null, \"chunk_index\": 2}', 'bge-large-zh-v1.5', '2026-09-25 17:04:56');
INSERT INTO `chunk` VALUES ('d91049ad-aa77-49ed-b930-3a6e4722753b', 'b25ce095-dfba-4403-acf8-c58eb456ca4c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 19, '依照法律规定、当事人约定或者民事法律行为的性质，应当由本人亲自实施的民事法律行为，不得代理。\n第一百六十二条　代理人在代理权限内，以被代理人名义实施的民事法律行为，对被代理人发生效力。\n第一百六十三条　代理包括委托代理和法定代理。\n委托代理人按照被代理人的委托行使代理权。法定代理人依照法律的规定行使代理权。\n第一百六十四条　代理人不履行或者不完全履行职责，造成被代理人损害的，应当承担民事责任。\n代理人和相对人恶意串通，损害被代理人合法权益的，代理人和相对人应当承担连带责任。\n第二节　委托代理\n第一百六十五条　委托代理授权采用书面形式的，授权委托书应当载明代理人的姓名或者名称、代理事项、权限和期限，并由被代理人签名或者盖章。\n第一百六十六条　数人为同一代理事项的代理人的，应当共同行使代理权，但是当事人另有约定的除外。\n第一百六十七条　代理人知道或者应当知道代理事项违法仍然实施代理行为，或者被代理人知道或者应当知道代理人的代理行为违法未作反对表示的，被代理人和代理人应当承担连带责任。\n第一百六十八条　代理人不得以被代理人的名义与自己实施民事法律行为，但是被代理人同意或者追认的除外。\n代理人不得以被代理人的名义与自己同时代理的其他人实施民事法律行为，但是被代理的双方同意或者追认的除外。\n第一百六十九条　代理人需要转委托第三人代理的，应当取得被代理人的同意或者追认。\n转委托代理经被代理人同意或者追认的，被代理人可以就代理事务直接指示转委托的第三人，代理人仅就第三人的选任以及对第三人的指示承担责任。\n转委托代理未经被代理人同意或者追认的，代理人应当对转委托的第三人的行为承担责任；但是，在紧急情况下代理人为了维护被代理人的利益需要转委托第三人代理的除外', 732, '{\"level\": null, \"title\": null, \"chunk_index\": 19}', 'bge-large-zh-v1.5', '2026-09-25 17:05:01');
INSERT INTO `chunk` VALUES ('d9b2ba64-0acf-4da6-9dd8-be91c428a22c', 'b25ce095-dfba-4403-acf8-c58eb456ca4c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 134, '第一千一百七十三条　被侵权人对同一损害的发生或者扩大有过错的，可以减轻侵权人的责任。\n第一千一百七十四条　损害是因受害人故意造成的，行为人不承担责任。\n第一千一百七十五条　损害是因第三人造成的，第三人应当承担侵权责任。\n第一千一百七十六条　自愿参加具有一定风险的文体活动，因其他参加者的行为受到损害的，受害人不得请求其他参加者承担侵权责任；但是，其他参加者对损害的发生有故意或者重大过失的除外。\n活动组织者的责任适用本法第一千一百九十八条至第一千二百零一条的规定。\n第一千一百七十七条　合法权益受到侵害，情况紧迫且不能及时获得国家机关保护，不立即采取措施将使其合法权益受到难以弥补的损害的，受害人可以在保护自己合法权益的必要范围内采取扣留侵权人的财物等合理措施；但是，应当立即请求有关国家机关处理。\n受害人采取的措施不当造成他人损害的，应当承担侵权责任。\n第一千一百七十八条　本法和其他法律对不承担责任或者减轻责任的情形另有规定的，依照其规定。\n第二章　损害赔偿\n第一千一百七十九条　侵害他人造成人身损害的，应当赔偿医疗费、护理费、交通费、营养费、住院伙食补助费等为治疗和康复支出的合理费用，以及因误工减少的收入。造成残疾的，还应当赔偿辅助器具费和残疾赔偿金；造成死亡的，还应当赔偿丧葬费和死亡赔偿金。\n第一千一百八十条　因同一侵权行为造成多人死亡的，可以以相同数额确定死亡赔偿金。\n第一千一百八十一条　被侵权人死亡的，其近亲属有权请求侵权人承担侵权责任。被侵权人为组织，该组织分立、合并的，承继权利的组织有权请求侵权人承担侵权责任。\n被侵权人死亡的，支付被侵权人医疗费、丧葬费等合理费用的人有权请求侵权人赔偿费用，但是侵权人已经支付该费用的除外', 723, '{\"level\": null, \"title\": null, \"chunk_index\": 134}', 'bge-large-zh-v1.5', '2026-09-25 17:05:01');
INSERT INTO `chunk` VALUES ('da2d3e6a-a703-4c83-9476-043ead0b7668', 'b25ce095-dfba-4403-acf8-c58eb456ca4c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 115, '第一千零一十四条　任何组织或者个人不得以干涉、盗用、假冒等方式侵害他人的姓名权或者名称权。\n第一千零一十五条　自然人应当随父姓或者母姓，但是有下列情形之一的，可以在父姓和母姓之外选取姓氏：\n（一）选取其他直系长辈血亲的姓氏；\n（二）因由法定扶养人以外的人扶养而选取扶养人姓氏；\n（三）有不违背公序良俗的其他正当理由。\n少数民族自然人的姓氏可以遵从本民族的文化传统和风俗习惯。\n第一千零一十六条　自然人决定、变更姓名，或者法人、非法人组织决定、变更、转让名称的，应当依法向有关机关办理登记手续，但是法律另有规定的除外。\n民事主体变更姓名、名称的，变更前实施的民事法律行为对其具有法律约束力。\n第一千零一十七条　具有一定社会知名度，被他人使用足以造成公众混淆的笔名、艺名、网名、译名、字号、姓名和名称的简称等，参照适用姓名权和名称权保护的有关规定。\n第四章　肖像权\n第一千零一十八条　自然人享有肖像权，有权依法制作、使用、公开或者许可他人使用自己的肖像。\n肖像是通过影像、雕塑、绘画等方式在一定载体上所反映的特定自然人可以被识别的外部形象。\n第一千零一十九条　任何组织或者个人不得以丑化、污损，或者利用信息技术手段伪造等方式侵害他人的肖像权。未经肖像权人同意，不得制作、使用、公开肖像权人的肖像，但是法律另有规定的除外。\n未经肖像权人同意，肖像作品权利人不得以发表、复制、发行、出租、展览等方式使用或者公开肖像权人的肖像', 608, '{\"level\": null, \"title\": null, \"chunk_index\": 115}', 'bge-large-zh-v1.5', '2026-09-25 17:05:01');
INSERT INTO `chunk` VALUES ('dac13c12-ac7f-405a-9995-37b9b7862378', 'b25ce095-dfba-4403-acf8-c58eb456ca4c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 145, '附　　则\n第一千二百五十九条　民法所称的“以上”、“以下”、“以内”、“届满”，包括本数；所称的“不满”、“超过”、“以外”，不包括本数。\n第一千二百六十条　本法自2021年1月1日起施行。《中华人民共和国婚姻法》、《中华人民共和国继承法》、《中华人民共和国民法通则》、《中华人民共和国收养法》、《中华人民共和国担保法》、《中华人民共和国合同法》、《中华人民共和国物权法》、《中华人民共和国侵权责任法》、《中华人民共和国民法总则》同时废止。', 220, '{\"level\": null, \"title\": null, \"chunk_index\": 145}', 'bge-large-zh-v1.5', '2026-09-25 17:05:01');
INSERT INTO `chunk` VALUES ('dae075e4-e4b8-44c0-b915-a63afcd06b6e', '821ce1fd-178d-4a7e-ab92-3deff1488ce2', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 47, '单位犯前款罪的，对单位判处罚金，并对其直接负责的主管人员和其他直接责任人员，依照前款的规定处罚。\n第二百一十一条　单位犯本节第二百零一条、第二百零三条、第二百零四条、第二百零七条、第二百零八条、第二百零九条规定之罪的，对单位判处罚金，并对其直接负责的主管人员和其他直接责任人员，依照各该条的规定处罚。\n第二百一十二条　犯本节第二百零一条至第二百零五条规定之罪，被判处罚金、没收财产的，在执行前，应当先由税务机关追缴税款和所骗取的出口退税款。\n第七节　侵犯知识产权罪\n第二百一十三条　未经注册商标所有人许可，在同一种商品、服务上使用与其注册商标相同的商标，情节严重的，处三年以下有期徒刑，并处或者单处罚金；情节特别严重的，处三年以上十年以下有期徒刑，并处罚金。\n第二百一十四条　销售明知是假冒注册商标的商品，违法所得数额较大或者有其他严重情节的，处三年以下有期徒刑，并处或者单处罚金；违法所得数额巨大或者有其他特别严重情节的，处三年以上十年以下有期徒刑，并处罚金。\n第二百一十五条　伪造、擅自制造他人注册商标标识或者销售伪造、擅自制造的注册商标标识，情节严重的，处三年以下有期徒刑，并处或者单处罚金；情节特别严重的，处三年以上十年以下有期徒刑，并处罚金。\n第二百一十六条　假冒他人专利，情节严重的，处三年以下有期徒刑或者拘役，并处或者单处罚金', 570, '{\"level\": null, \"title\": null, \"chunk_index\": 47}', 'bge-large-zh-v1.5', '2026-09-25 17:04:56');
INSERT INTO `chunk` VALUES ('daee70da-f118-42af-a9fe-a66c16dcdac1', '821ce1fd-178d-4a7e-ab92-3deff1488ce2', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 59, '第二百六十六条　诈骗公私财物，数额较大的，处三年以下有期徒刑、拘役或者管制，并处或者单处罚金；数额巨大或者有其他严重情节的，处三年以上十年以下有期徒刑，并处罚金；数额特别巨大或者有其他特别严重情节的，处十年以上有期徒刑或者无期徒刑，并处罚金或者没收财产。本法另有规定的，依照规定。\n第二百六十七条　抢夺公私财物，数额较大的，或者多次抢夺的，处三年以下有期徒刑、拘役或者管制，并处或者单处罚金；数额巨大或者有其他严重情节的，处三年以上十年以下有期徒刑，并处罚金；数额特别巨大或者有其他特别严重情节的，处十年以上有期徒刑或者无期徒刑，并处罚金或者没收财产。\n携带凶器抢夺的，依照本法第二百六十三条的规定定罪处罚。\n第二百六十八条　聚众哄抢公私财物，数额较大或者有其他严重情节的，对首要分子和积极参加的，处三年以下有期徒刑、拘役或者管制，并处罚金；数额巨大或者有其他特别严重情节的，处三年以上十年以下有期徒刑，并处罚金。\n第二百六十九条　犯盗窃、诈骗、抢夺罪，为窝藏赃物、抗拒抓捕或者毁灭罪证而当场使用暴力或者以暴力相威胁的，依照本法第二百六十三条的规定定罪处罚。\n第二百七十条　将代为保管的他人财物非法占为己有，数额较大，拒不退还的，处二年以下有期徒刑、拘役或者罚金；数额巨大或者有其他严重情节的，处二年以上五年以下有期徒刑，并处罚金。\n将他人的遗忘物或者埋藏物非法占为己有，数额较大，拒不交出的，依照前款的规定处罚。\n本条罪，告诉的才处理。\n第二百七十一条　公司、企业或者其他单位的工作人员，利用职务上的便利，将本单位财物非法占为己有，数额较大的，处三年以下有期徒刑或者拘役，并处罚金；数额巨大的，处三年以上十年以下有期徒刑，并处罚金；数额特别巨大的，处十年以上有期徒刑或者无期徒刑，并处罚金', 745, '{\"level\": null, \"title\": null, \"chunk_index\": 59}', 'bge-large-zh-v1.5', '2026-09-25 17:04:56');
INSERT INTO `chunk` VALUES ('db334ced-4e27-4863-8a25-2fbfa3e4cace', 'b25ce095-dfba-4403-acf8-c58eb456ca4c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 69, '当事人没有约定交付地点或者约定不明确，依据本法第五百一十条的规定仍不能确定的，适用下列规定：\n（一）标的物需要运输的，出卖人应当将标的物交付给第一承运人以运交给买受人；\n（二）标的物不需要运输，出卖人和买受人订立合同时知道标的物在某一地点的，出卖人应当在该地点交付标的物；不知道标的物在某一地点的，应当在出卖人订立合同时的营业地交付标的物。\n第六百零四条　标的物毁损、灭失的风险，在标的物交付之前由出卖人承担，交付之后由买受人承担，但是法律另有规定或者当事人另有约定的除外。\n第六百零五条　因买受人的原因致使标的物未按照约定的期限交付的，买受人应当自违反约定时起承担标的物毁损、灭失的风险。\n第六百零六条　出卖人出卖交由承运人运输的在途标的物，除当事人另有约定外，毁损、灭失的风险自合同成立时起由买受人承担。\n第六百零七条　出卖人按照约定将标的物运送至买受人指定地点并交付给承运人后，标的物毁损、灭失的风险由买受人承担。\n当事人没有约定交付地点或者约定不明确，依据本法第六百零三条第二款第一项的规定标的物需要运输的，出卖人将标的物交付给第一承运人后，标的物毁损、灭失的风险由买受人承担。\n第六百零八条　出卖人按照约定或者依据本法第六百零三条第二款第二项的规定将标的物置于交付地点，买受人违反约定没有收取的，标的物毁损、灭失的风险自违反约定时起由买受人承担。\n第六百零九条　出卖人按照约定未交付有关标的物的单证和资料的，不影响标的物毁损、灭失风险的转移。\n第六百一十条　因标的物不符合质量要求，致使不能实现合同目的的，买受人可以拒绝接受标的物或者解除合同。买受人拒绝接受标的物或者解除合同的，标的物毁损、灭失的风险由出卖人承担。\n第六百一十一条　标的物毁损、灭失的风险由买受人承担的，不影响因出卖人履行义务不符合约定，买受人请求其承担违约责任的权利', 773, '{\"level\": null, \"title\": null, \"chunk_index\": 69}', 'bge-large-zh-v1.5', '2026-09-25 17:05:01');
INSERT INTO `chunk` VALUES ('db9e9d61-f212-4f48-af8a-b80725a317c6', 'b25ce095-dfba-4403-acf8-c58eb456ca4c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 36, '第三百一十六条　拾得人在遗失物送交有关部门前，有关部门在遗失物被领取前，应当妥善保管遗失物。因故意或者重大过失致使遗失物毁损、灭失的，应当承担民事责任。\n第三百一十七条　权利人领取遗失物时，应当向拾得人或者有关部门支付保管遗失物等支出的必要费用。\n权利人悬赏寻找遗失物的，领取遗失物时应当按照承诺履行义务。\n拾得人侵占遗失物的，无权请求保管遗失物等支出的费用，也无权请求权利人按照承诺履行义务。\n第三百一十八条　遗失物自发布招领公告之日起一年内无人认领的，归国家所有。\n第三百一十九条　拾得漂流物、发现埋藏物或者隐藏物的，参照适用拾得遗失物的有关规定。法律另有规定的，依照其规定。\n第三百二十条　主物转让的，从物随主物转让，但是当事人另有约定的除外。\n第三百二十一条　天然孳息，由所有权人取得；既有所有权人又有用益物权人的，由用益物权人取得。当事人另有约定的，按照其约定。\n法定孳息，当事人有约定的，按照约定取得；没有约定或者约定不明确的，按照交易习惯取得。\n第三百二十二条　因加工、附合、混合而产生的物的归属，有约定的，按照约定；没有约定或者约定不明确的，依照法律规定；法律没有规定的，按照充分发挥物的效用以及保护无过错当事人的原则确定。因一方当事人的过错或者确定物的归属造成另一方当事人损害的，应当给予赔偿或者补偿。\n第三分编　用益物权\n第十章　一般规定\n第三百二十三条　用益物权人对他人所有的不动产或者动产，依法享有占有、使用和收益的权利。\n第三百二十四条　国家所有或者国家所有由集体使用以及法律规定属于集体所有的自然资源，组织、个人依法可以占有、使用和收益。\n第三百二十五条　国家实行自然资源有偿使用制度，但是法律另有规定的除外。\n第三百二十六条　用益物权人行使权利，应当遵守法律有关保护和合理开发利用资源、保护生态环境的规定。所有权人不得干涉用益物权人行使权利', 785, '{\"level\": null, \"title\": null, \"chunk_index\": 36}', 'bge-large-zh-v1.5', '2026-09-25 17:05:01');
INSERT INTO `chunk` VALUES ('dc6823cd-4d42-455f-8204-dcf23d33a6f2', '821ce1fd-178d-4a7e-ab92-3deff1488ce2', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 98, '第四百五十条　本章适用于中国人民解放军的现役军官、文职干部、士兵及具有军籍的学员和中国人民武装警察部队的现役警官、文职干部、士兵及具有军籍的学员以及文职人员、执行军事任务的预备役人员和其他人员。\n第四百五十一条　本章所称战时，是指国家宣布进入战争状态、部队受领作战任务或者遭敌突然袭击时。\n部队执行戒严任务或者处置突发性暴力事件时，以战时论。\n附　　则\n第四百五十二条　本法自1997年10月1日起施行。\n列于本法附件一的全国人民代表大会常务委员会制定的条例、补充规定和决定，已纳入本法或者已不适用，自本法施行之日起，予以废止。\n列于本法附件二的全国人民代表大会常务委员会制定的补充规定和决定予以保留。其中，有关行政处罚和行政措施的规定继续有效；有关刑事责任的规定已纳入本法，自本法施行之日起，适用本法规定', 353, '{\"level\": null, \"title\": null, \"chunk_index\": 98}', 'bge-large-zh-v1.5', '2026-09-25 17:04:56');
INSERT INTO `chunk` VALUES ('dc70591b-0f1c-44be-ba77-e5f14d57cd48', '821ce1fd-178d-4a7e-ab92-3deff1488ce2', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 23, '第一百三十九条　违反消防管理法规，经消防监督机构通知采取改正措施而拒绝执行，造成严重后果的，对直接责任人员，处三年以下有期徒刑或者拘役；后果特别严重的，处三年以上七年以下有期徒刑。\n第一百三十九条之一　在安全事故发生后，负有报告职责的人员不报或者谎报事故情况，贻误事故抢救，情节严重的，处三年以下有期徒刑或者拘役；情节特别严重的，处三年以上七年以下有期徒刑。\n第三章　破坏社会主义市场经济秩序罪\n第一节　生产、销售伪劣商品罪\n第一百四十条　生产者、销售者在产品中掺杂、掺假，以假充真，以次充好或者以不合格产品冒充合格产品，销售金额五万元以上不满二十万元的，处二年以下有期徒刑或者拘役，并处或者单处销售金额百分之五十以上二倍以下罚金；销售金额二十万元以上不满五十万元的，处二年以上七年以下有期徒刑，并处销售金额百分之五十以上二倍以下罚金；销售金额五十万元以上不满二百万元的，处七年以上有期徒刑，并处销售金额百分之五十以上二倍以下罚金；销售金额二百万元以上的，处十五年有期徒刑或者无期徒刑，并处销售金额百分之五十以上二倍以下罚金或者没收财产。\n第一百四十一条　生产、销售假药的，处三年以下有期徒刑或者拘役，并处罚金；对人体健康造成严重危害或者有其他严重情节的，处三年以上十年以下有期徒刑，并处罚金；致人死亡或者有其他特别严重情节的，处十年以上有期徒刑、无期徒刑或者死刑，并处罚金或者没收财产。\n药品使用单位的人员明知是假药而提供给他人使用的，依照前款的规定处罚。\n第一百四十二条　生产、销售劣药，对人体健康造成严重危害的，处三年以上十年以下有期徒刑，并处罚金；后果特别严重的，处十年以上有期徒刑或者无期徒刑，并处罚金或者没收财产。\n药品使用单位的人员明知是劣药而提供给他人使用的，依照前款的规定处罚', 747, '{\"level\": null, \"title\": null, \"chunk_index\": 23}', 'bge-large-zh-v1.5', '2026-09-25 17:04:56');
INSERT INTO `chunk` VALUES ('dc8f0885-cb2b-49c8-a9a8-2d5767f09db5', 'b25ce095-dfba-4403-acf8-c58eb456ca4c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 7, '第三十八条　被监护人的父母或者子女被人民法院撤销监护人资格后，除对被监护人实施故意犯罪的外，确有悔改表现的，经其申请，人民法院可以在尊重被监护人真实意愿的前提下，视情况恢复其监护人资格，人民法院指定的监护人与被监护人的监护关系同时终止。\n第三十九条　有下列情形之一的，监护关系终止：\n（一）被监护人取得或者恢复完全民事行为能力；\n（二）监护人丧失监护能力；\n（三）被监护人或者监护人死亡；\n（四）人民法院认定监护关系终止的其他情形。\n监护关系终止后，被监护人仍然需要监护的，应当依法另行确定监护人。\n第三节　宣告失踪和宣告死亡\n第四十条　自然人下落不明满二年的，利害关系人可以向人民法院申请宣告该自然人为失踪人。\n第四十一条　自然人下落不明的时间自其失去音讯之日起计算。战争期间下落不明的，下落不明的时间自战争结束之日或者有关机关确定的下落不明之日起计算。\n第四十二条　失踪人的财产由其配偶、成年子女、父母或者其他愿意担任财产代管人的人代管。\n代管有争议，没有前款规定的人，或者前款规定的人无代管能力的，由人民法院指定的人代管。\n第四十三条　财产代管人应当妥善管理失踪人的财产，维护其财产权益。\n失踪人所欠税款、债务和应付的其他费用，由财产代管人从失踪人的财产中支付。\n财产代管人因故意或者重大过失造成失踪人财产损失的，应当承担赔偿责任。\n第四十四条　财产代管人不履行代管职责、侵害失踪人财产权益或者丧失代管能力的，失踪人的利害关系人可以向人民法院申请变更财产代管人。\n财产代管人有正当理由的，可以向人民法院申请变更财产代管人。\n人民法院变更财产代管人的，变更后的财产代管人有权请求原财产代管人及时移交有关财产并报告财产代管情况。\n第四十五条　失踪人重新出现，经本人或者利害关系人申请，人民法院应当撤销失踪宣告。\n失踪人重新出现，有权请求财产代管人及时移交有关财产并报告财产代管情况', 791, '{\"level\": null, \"title\": null, \"chunk_index\": 7}', 'bge-large-zh-v1.5', '2026-09-25 17:05:01');
INSERT INTO `chunk` VALUES ('dda0af97-d47b-40ea-8cd4-369daf454129', '16cbea7e-7e36-4f31-afb5-63892345d29c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 39, '第十五节　鉴　　定\n第一百七十五条　监察机关为解决案件中的专门性问题，按规定报批后，可以依法进行鉴定。\n鉴定时应当出具《委托鉴定书》，由二名以上调查人员送交具有鉴定资格的鉴定机构、鉴定人进行鉴定。\n第一百七十六条　监察机关可以依法开展下列鉴定：\n（一）对笔迹、印刷文件、污损文件、制成时间不明的文件和以其他形式表现的文件等进行鉴定；\n（二）对案件中涉及的财务会计资料及相关财物进行会计鉴定；\n（三）对被调查人、证人的行为能力进行精神病鉴定；\n（四）对人体造成的损害或者死因进行人身伤亡医学鉴定；\n（五）对录音录像资料进行鉴定；\n（六）对因电子信息技术应用而出现的材料及其派生物进行电子数据鉴定；\n（七）其他可以依法进行的专业鉴定。\n第一百七十七条　监察机关应当为鉴定提供必要条件，向鉴定人送交有关检材和对比样本等原始材料，介绍与鉴定有关的情况。调查人员应当明确提出要求鉴定事项，但不得暗示或者强迫鉴定人作出某种鉴定意见。\n监察机关应当做好检材的保管和送检工作，记明检材送检环节的责任人，确保检材在流转环节的同一性和不被污染。\n第一百七十八条　鉴定人应当在出具的鉴定意见上签名，并附鉴定机构和鉴定人的资质证明或者其他证明文件。多个鉴定人的鉴定意见不一致的，应当在鉴定意见上记明分歧的内容和理由，并且分别签名。\n监察机关对于法庭审理中依法决定鉴定人出庭作证的，应当予以协调。\n鉴定人故意作虚假鉴定的，应当依法追究法律责任。\n第一百七十九条　调查人员应当对鉴定意见进行审查。对经审查作为证据使用的鉴定意见，应当告知被调查人及相关单位、人员，送达《鉴定意见告知书》。\n被调查人或者相关单位、人员提出补充鉴定或者重新鉴定申请，经审查符合法定要求的，应当按规定报批，进行补充鉴定或者重新鉴定。\n对鉴定意见告知情况可以制作笔录，载明告知内容和被告知人的意见等', 772, '{\"level\": null, \"title\": null, \"chunk_index\": 39}', 'bge-large-zh-v1.5', '2026-09-25 17:04:49');
INSERT INTO `chunk` VALUES ('df170419-7aac-499a-9d7c-6c87dd546164', 'b25ce095-dfba-4403-acf8-c58eb456ca4c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 75, '用电人未按照国家有关规定和当事人的约定用电，造成供电人损失的，应当承担赔偿责任。\n第六百五十六条　供用水、供用气、供用热力合同，参照适用供用电合同的有关规定。\n第十一章　赠与合同\n第六百五十七条　赠与合同是赠与人将自己的财产无偿给予受赠人，受赠人表示接受赠与的合同。\n第六百五十八条　赠与人在赠与财产的权利转移之前可以撤销赠与。\n经过公证的赠与合同或者依法不得撤销的具有救灾、扶贫、助残等公益、道德义务性质的赠与合同，不适用前款规定。\n第六百五十九条　赠与的财产依法需要办理登记或者其他手续的，应当办理有关手续。\n第六百六十条　经过公证的赠与合同或者依法不得撤销的具有救灾、扶贫、助残等公益、道德义务性质的赠与合同，赠与人不交付赠与财产的，受赠人可以请求交付。\n依据前款规定应当交付的赠与财产因赠与人故意或者重大过失致使毁损、灭失的，赠与人应当承担赔偿责任。\n第六百六十一条　赠与可以附义务。\n赠与附义务的，受赠人应当按照约定履行义务。\n第六百六十二条　赠与的财产有瑕疵的，赠与人不承担责任。附义务的赠与，赠与的财产有瑕疵的，赠与人在附义务的限度内承担与出卖人相同的责任。\n赠与人故意不告知瑕疵或者保证无瑕疵，造成受赠人损失的，应当承担赔偿责任。\n第六百六十三条　受赠人有下列情形之一的，赠与人可以撤销赠与：\n（一）严重侵害赠与人或者赠与人近亲属的合法权益；\n（二）对赠与人有扶养义务而不履行；\n（三）不履行赠与合同约定的义务。\n赠与人的撤销权，自知道或者应当知道撤销事由之日起一年内行使。\n第六百六十四条　因受赠人的违法行为致使赠与人死亡或者丧失民事行为能力的，赠与人的继承人或者法定代理人可以撤销赠与。\n赠与人的继承人或者法定代理人的撤销权，自知道或者应当知道撤销事由之日起六个月内行使。\n第六百六十五条　撤销权人撤销赠与的，可以向受赠人请求返还赠与的财产', 780, '{\"level\": null, \"title\": null, \"chunk_index\": 75}', 'bge-large-zh-v1.5', '2026-09-25 17:05:01');
INSERT INTO `chunk` VALUES ('df28fd9a-86be-4e0e-973c-77109989da14', '16cbea7e-7e36-4f31-afb5-63892345d29c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 75, '第三百二十五条　本条例所称近亲属，是指夫、妻、父、母、子、女、同胞兄弟姊妹。\n第三百二十六条　本条例所称以上、以下、以内，包括本级、本数。\n第三百二十七条　期间以时、日、月、年计算，期间开始的时和日不算在期间以内。本条例另有规定的除外。\n按照年、月计算期间的，到期月的对应日为期间的最后一日；没有对应日的，月末日为期间的最后一日。\n期间的最后一日是节假日的，以节假日结束的次日为期间的最后一日。但被调查人被采取责令候查、管护、留置或者禁闭措施的期间应当至期满之日为止，不得因节假日而延长。\n第三百二十八条　本条例由国家监察委员会负责解释。\n第三百二十九条　本条例自发布之日起施行。', 290, '{\"level\": null, \"title\": null, \"chunk_index\": 75}', 'bge-large-zh-v1.5', '2026-09-25 17:04:49');
INSERT INTO `chunk` VALUES ('e0557aa3-9dd7-4d27-ac09-0371119d6402', '821ce1fd-178d-4a7e-ab92-3deff1488ce2', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 55, '第二百四十三条　捏造事实诬告陷害他人，意图使他人受刑事追究，情节严重的，处三年以下有期徒刑、拘役或者管制；造成严重后果的，处三年以上十年以下有期徒刑。\n国家机关工作人员犯前款罪的，从重处罚。\n不是有意诬陷，而是错告，或者检举失实的，不适用前两款的规定。\n第二百四十四条　以暴力、威胁或者限制人身自由的方法强迫他人劳动的，处三年以下有期徒刑或者拘役，并处罚金；情节严重的，处三年以上十年以下有期徒刑，并处罚金。\n明知他人实施前款行为，为其招募、运送人员或者有其他协助强迫他人劳动行为的，依照前款的规定处罚。\n单位犯前两款罪的，对单位判处罚金，并对其直接负责的主管人员和其他直接责任人员，依照第一款的规定处罚。\n第二百四十四条之一　违反劳动管理法规，雇用未满十六周岁的未成年人从事超强度体力劳动的，或者从事高空、井下作业的，或者在爆炸性、易燃性、放射性、毒害性等危险环境下从事劳动，情节严重的，对直接责任人员，处三年以下有期徒刑或者拘役，并处罚金；情节特别严重的，处三年以上七年以下有期徒刑，并处罚金。\n有前款行为，造成事故，又构成其他犯罪的，依照数罪并罚的规定处罚。\n第二百四十五条　非法搜查他人身体、住宅，或者非法侵入他人住宅的，处三年以下有期徒刑或者拘役。\n司法工作人员滥用职权，犯前款罪的，从重处罚。\n第二百四十六条　以暴力或者其他方法公然侮辱他人或者捏造事实诽谤他人，情节严重的，处三年以下有期徒刑、拘役、管制或者剥夺政治权利。\n前款罪，告诉的才处理，但是严重危害社会秩序和国家利益的除外。\n通过信息网络实施第一款规定的行为，被害人向人民法院告诉，但提供证据确有困难的，人民法院可以要求公安机关提供协助。\n第二百四十七条　司法工作人员对犯罪嫌疑人、被告人实行刑讯逼供或者使用暴力逼取证人证言的，处三年以下有期徒刑或者拘役', 763, '{\"level\": null, \"title\": null, \"chunk_index\": 55}', 'bge-large-zh-v1.5', '2026-09-25 17:04:56');
INSERT INTO `chunk` VALUES ('e0731ed9-11b2-4de9-a86a-4bdcf6399b38', '22a2c356-7a68-4455-b657-333e3dba1e1a', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 15, '第六十八条　全国人民代表大会常务委员会委员长主持全国人民代表大会常务委员会的工作，召集全国人民代表大会常务委员会会议。副委员长、秘书长协助委员长工作。\n委员长、副委员长、秘书长组成委员长会议，处理全国人民代表大会常务委员会的重要日常工作。\n第六十九条　全国人民代表大会常务委员会对全国人民代表大会负责并报告工作。\n第七十条　全国人民代表大会设立民族委员会、宪法和法律委员会、财政经济委员会、教育科学文化卫生委员会、外事委员会、华侨委员会和其他需要设立的专门委员会。在全国人民代表大会闭会期间，各专门委员会受全国人民代表大会常务委员会的领导。\n各专门委员会在全国人民代表大会和全国人民代表大会常务委员会领导下，研究、审议和拟订有关议案。\n第七十一条　全国人民代表大会和全国人民代表大会常务委员会认为必要的时候，可以组织关于特定问题的调查委员会，并且根据调查委员会的报告，作出相应的决议。\n调查委员会进行调查的时候，一切有关的国家机关、社会团体和公民都有义务向它提供必要的材料。\n第七十二条　全国人民代表大会代表和全国人民代表大会常务委员会组成人员，有权依照法律规定的程序分别提出属于全国人民代表大会和全国人民代表大会常务委员会职权范围内的议案。\n第七十三条　全国人民代表大会代表在全国人民代表大会开会期间，全国人民代表大会常务委员会组成人员在常务委员会开会期间，有权依照法律规定的程序提出对国务院或者国务院各部、各委员会的质询案。受质询的机关必须负责答复。\n第七十四条　全国人民代表大会代表，非经全国人民代表大会会议主席团许可，在全国人民代表大会闭会期间非经全国人民代表大会常务委员会许可，不受逮捕或者刑事审判。\n第七十五条　全国人民代表大会代表在全国人民代表大会各种会议上的发言和表决，不受法律追究', 749, '{\"level\": null, \"title\": null, \"chunk_index\": 15}', 'bge-large-zh-v1.5', '2026-09-25 17:04:29');
INSERT INTO `chunk` VALUES ('e13e739e-5eef-411a-bef4-1d5de1362275', '16cbea7e-7e36-4f31-afb5-63892345d29c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 6, '第三十二条　监察机关依法调查公职人员涉嫌徇私舞弊犯罪，包括徇私舞弊低价折股、出售公司、企业资产罪，非法批准征收、征用、占用土地罪，非法低价出让国有土地使用权罪，非法经营同类营业罪，为亲友非法牟利罪，枉法仲裁罪，徇私舞弊发售发票、抵扣税款、出口退税罪，商检徇私舞弊罪，动植物检疫徇私舞弊罪，放纵走私罪，放纵制售伪劣商品犯罪行为罪，招收公务员、学生徇私舞弊罪，徇私舞弊不移交刑事案件罪，违法提供出口退税凭证罪，徇私舞弊不征、少征税款罪。\n第三十三条　监察机关依法调查公职人员在行使公权力过程中涉及的重大责任事故犯罪，包括重大责任事故罪，教育设施重大安全事故罪，消防责任事故罪，重大劳动安全事故罪，强令、组织他人违章冒险作业罪，危险作业罪，不报、谎报安全事故罪，铁路运营安全事故罪，重大飞行事故罪，大型群众性活动重大安全事故罪，危险物品肇事罪，工程重大安全事故罪。\n第三十四条　监察机关依法调查公职人员在行使公权力过程中涉及的其他犯罪，包括破坏选举罪，背信损害上市公司利益罪，金融工作人员购买假币、以假币换取货币罪，利用未公开信息交易罪，诱骗投资者买卖证券、期货合约罪，背信运用受托财产罪，违法运用资金罪，违法发放贷款罪，吸收客户资金不入账罪，违规出具金融票证罪，对违法票据承兑、付款、保证罪，非法转让、倒卖土地使用权罪，私自开拆、隐匿、毁弃邮件、电报罪，故意延误投递邮件罪，泄露不应公开的案件信息罪，披露、报道不应公开的案件信息罪，接送不合格兵员罪。\n第三十五条　监察机关发现依法由其他机关管辖的违法犯罪线索，应当及时移送有管辖权的机关。\n监察机关调查结束后，对于应当给予被调查人或者涉案人员行政处罚等其他处理的，依法移送有关机关。\n第四节　监察处置\n第三十六条　监察机关对违法的公职人员，依据监察法、政务处分法等规定作出政务处分决定', 765, '{\"level\": null, \"title\": null, \"chunk_index\": 6}', 'bge-large-zh-v1.5', '2026-09-25 17:04:49');
INSERT INTO `chunk` VALUES ('e171954b-ff19-4a35-accb-39fb4a2be8ce', 'b25ce095-dfba-4403-acf8-c58eb456ca4c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 32, '经业主共同决定，可以用于电梯、屋顶、外墙、无障碍设施等共有部分的维修、更新和改造。建筑物及其附属设施的维修资金的筹集、使用情况应当定期公布。\n紧急情况下需要维修建筑物及其附属设施的，业主大会或者业主委员会可以依法申请使用建筑物及其附属设施的维修资金。\n第二百八十二条　建设单位、物业服务企业或者其他管理人等利用业主的共有部分产生的收入，在扣除合理成本之后，属于业主共有。\n第二百八十三条　建筑物及其附属设施的费用分摊、收益分配等事项，有约定的，按照约定；没有约定或者约定不明确的，按照业主专有部分面积所占比例确定。\n第二百八十四条　业主可以自行管理建筑物及其附属设施，也可以委托物业服务企业或者其他管理人管理。\n对建设单位聘请的物业服务企业或者其他管理人，业主有权依法更换。\n第二百八十五条　物业服务企业或者其他管理人根据业主的委托，依照本法第三编有关物业服务合同的规定管理建筑区划内的建筑物及其附属设施，接受业主的监督，并及时答复业主对物业服务情况提出的询问。\n物业服务企业或者其他管理人应当执行政府依法实施的应急处置措施和其他管理措施，积极配合开展相关工作。\n第二百八十六条　业主应当遵守法律、法规以及管理规约，相关行为应当符合节约资源、保护生态环境的要求。对于物业服务企业或者其他管理人执行政府依法实施的应急处置措施和其他管理措施，业主应当依法予以配合。\n业主大会或者业主委员会，对任意弃置垃圾、排放污染物或者噪声、违反规定饲养动物、违章搭建、侵占通道、拒付物业费等损害他人合法权益的行为，有权依照法律、法规以及管理规约，请求行为人停止侵害、排除妨碍、消除危险、恢复原状、赔偿损失。\n业主或者其他行为人拒不履行相关义务的，有关当事人可以向有关行政主管部门报告或者投诉，有关行政主管部门应当依法处理', 751, '{\"level\": null, \"title\": null, \"chunk_index\": 32}', 'bge-large-zh-v1.5', '2026-09-25 17:05:01');
INSERT INTO `chunk` VALUES ('e27f4ca1-f8bb-46a7-a3d4-7d9e6807936d', 'b25ce095-dfba-4403-acf8-c58eb456ca4c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 27, '第二百三十四条　因物权的归属、内容发生争议的，利害关系人可以请求确认权利。\n第二百三十五条　无权占有不动产或者动产的，权利人可以请求返还原物。\n第二百三十六条　妨害物权或者可能妨害物权的，权利人可以请求排除妨害或者消除危险。\n第二百三十七条　造成不动产或者动产毁损的，权利人可以依法请求修理、重作、更换或者恢复原状。\n第二百三十八条　侵害物权，造成权利人损害的，权利人可以依法请求损害赔偿，也可以依法请求承担其他民事责任。\n第二百三十九条　本章规定的物权保护方式，可以单独适用，也可以根据权利被侵害的情形合并适用。\n第二分编　所有权\n第四章　一般规定\n第二百四十条　所有权人对自己的不动产或者动产，依法享有占有、使用、收益和处分的权利。\n第二百四十一条　所有权人有权在自己的不动产或者动产上设立用益物权和担保物权。用益物权人、担保物权人行使权利，不得损害所有权人的权益。\n第二百四十二条　法律规定专属于国家所有的不动产和动产，任何组织或者个人不能取得所有权。\n第二百四十三条　为了公共利益的需要，依照法律规定的权限和程序可以征收集体所有的土地和组织、个人的房屋以及其他不动产。\n征收集体所有的土地，应当依法及时足额支付土地补偿费、安置补助费以及农村村民住宅、其他地上附着物和青苗等的补偿费用，并安排被征地农民的社会保障费用，保障被征地农民的生活，维护被征地农民的合法权益。\n征收组织、个人的房屋以及其他不动产，应当依法给予征收补偿，维护被征收人的合法权益；征收个人住宅的，还应当保障被征收人的居住条件。\n任何组织或者个人不得贪污、挪用、私分、截留、拖欠征收补偿费等费用。\n第二百四十四条　国家对耕地实行特殊保护，严格限制农用地转为建设用地，控制建设用地总量。不得违反法律规定的权限和程序征收集体所有的土地', 752, '{\"level\": null, \"title\": null, \"chunk_index\": 27}', 'bge-large-zh-v1.5', '2026-09-25 17:05:01');
INSERT INTO `chunk` VALUES ('e298f42f-5367-49c7-993c-621d79ca01c3', '16cbea7e-7e36-4f31-afb5-63892345d29c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 28, '具有下列情形之一的，经审批可以延长一次，延长时间不得超过三个月：\n（一）案情重大，严重危害国家利益或者公共利益的；\n（二）案情复杂，涉案人员多、金额巨大，涉及范围广的；\n（三）重要证据尚未收集完成，或者重要涉案人员尚未到案，导致违法犯罪的主要事实仍须继续调查的；\n（四）其他需要延长留置时间的情形。\n省级以下监察机关采取留置措施的，延长留置时间应当报请上一级监察机关批准。\n延长留置时间的，应当在留置期满前向被留置人员宣布延长留置时间的决定，要求其在《延长留置时间决定书》上签名、捺指印。被留置人员拒绝签名、捺指印的，调查人员应当在文书上记明。\n延长留置时间的，应当及时通知被留置人员所在单位和家属。\n第一百三十条　对涉嫌职务犯罪的被调查人可能判处十年有期徒刑以上刑罚，监察机关按照本条例第一百二十九条规定延长期限届满，仍不能调查终结的，经审批可以再延长，再延长时间不得超过二个月。\n省级以下监察机关需要再延长留置时间的，应当逐级报送国家监察委员会批准。\n再延长留置时间的，应当在留置期满前向被留置人员宣布再延长留置时间的决定，要求其在《再延长留置时间决定书》上签名、捺指印。被留置人员拒绝签名、捺指印的，调查人员应当在文书上记明。\n再延长留置时间的，应当及时通知被留置人员所在单位和家属。\n第一百三十一条　报请批准延长或者再延长留置时间，应当在报请材料中写明被留置人员基本情况、主要案情和留置后调查工作进展情况、下一步调查工作计划、延长或者再延长留置时间的具体理由及起止时间。\n报请批准延长或者再延长留置时间，应当根据案件具体情况和实际工作需要，提出合理、必要的时间建议。\n上级监察机关收到报请批准延长或者再延长留置时间的申请后，应当及时研究，在原留置期限届满前按程序作出决定', 739, '{\"level\": null, \"title\": null, \"chunk_index\": 28}', 'bge-large-zh-v1.5', '2026-09-25 17:04:49');
INSERT INTO `chunk` VALUES ('e3345ce0-82ed-4cac-ad9c-32099aa3a398', 'b25ce095-dfba-4403-acf8-c58eb456ca4c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 73, '第六百三十七条　试用买卖的当事人可以约定标的物的试用期限。对试用期限没有约定或者约定不明确，依据本法第五百一十条的规定仍不能确定的，由出卖人确定。\n第六百三十八条　试用买卖的买受人在试用期内可以购买标的物，也可以拒绝购买。试用期限届满，买受人对是否购买标的物未作表示的，视为购买。\n试用买卖的买受人在试用期内已经支付部分价款或者对标的物实施出卖、出租、设立担保物权等行为的，视为同意购买。\n第六百三十九条　试用买卖的当事人对标的物使用费没有约定或者约定不明确的，出卖人无权请求买受人支付。\n第六百四十条　标的物在试用期内毁损、灭失的风险由出卖人承担。\n第六百四十一条　当事人可以在买卖合同中约定买受人未履行支付价款或者其他义务的，标的物的所有权属于出卖人。\n出卖人对标的物保留的所有权，未经登记，不得对抗善意第三人。\n第六百四十二条　当事人约定出卖人保留合同标的物的所有权，在标的物所有权转移前，买受人有下列情形之一，造成出卖人损害的，除当事人另有约定外，出卖人有权取回标的物：\n（一）未按照约定支付价款，经催告后在合理期限内仍未支付；\n（二）未按照约定完成特定条件；\n（三）将标的物出卖、出质或者作出其他不当处分。\n出卖人可以与买受人协商取回标的物；协商不成的，可以参照适用担保物权的实现程序。\n第六百四十三条　出卖人依据前条第一款的规定取回标的物后，买受人在双方约定或者出卖人指定的合理回赎期限内，消除出卖人取回标的物的事由的，可以请求回赎标的物。\n买受人在回赎期限内没有回赎标的物，出卖人可以以合理价格将标的物出卖给第三人，出卖所得价款扣除买受人未支付的价款以及必要费用后仍有剩余的，应当返还买受人；不足部分由买受人清偿。\n第六百四十四条　招标投标买卖的当事人的权利和义务以及招标投标程序等，依照有关法律、行政法规的规定', 763, '{\"level\": null, \"title\": null, \"chunk_index\": 73}', 'bge-large-zh-v1.5', '2026-09-25 17:05:01');
INSERT INTO `chunk` VALUES ('e362472f-4f18-4c84-abe3-7e4183f02ef8', '22a2c356-7a68-4455-b657-333e3dba1e1a', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 20, '县级以上的地方各级人民代表大会审查和批准本行政区域内的国民经济和社会发展计划、预算以及它们的执行情况的报告；有权改变或者撤销本级人民代表大会常务委员会不适当的决定。\n民族乡的人民代表大会可以依照法律规定的权限采取适合民族特点的具体措施。\n第一百条　省、直辖市的人民代表大会和它们的常务委员会，在不同宪法、法律、行政法规相抵触的前提下，可以制定地方性法规，报全国人民代表大会常务委员会备案。\n设区的市的人民代表大会和它们的常务委员会，在不同宪法、法律、行政法规和本省、自治区的地方性法规相抵触的前提下，可以依照法律规定制定地方性法规，报本省、自治区人民代表大会常务委员会批准后施行。\n第一百零一条　地方各级人民代表大会分别选举并且有权罢免本级人民政府的省长和副省长、市长和副市长、县长和副县长、区长和副区长、乡长和副乡长、镇长和副镇长。\n县级以上的地方各级人民代表大会选举并且有权罢免本级监察委员会主任、本级人民法院院长和本级人民检察院检察长。选出或者罢免人民检察院检察长，须报上级人民检察院检察长提请该级人民代表大会常务委员会批准。\n第一百零二条　省、直辖市、设区的市的人民代表大会代表受原选举单位的监督；县、不设区的市、市辖区、乡、民族乡、镇的人民代表大会代表受选民的监督。\n地方各级人民代表大会代表的选举单位和选民有权依照法律规定的程序罢免由他们选出的代表。\n第一百零三条　县级以上的地方各级人民代表大会常务委员会由主任、副主任若干人和委员若干人组成，对本级人民代表大会负责并报告工作。\n县级以上的地方各级人民代表大会选举并有权罢免本级人民代表大会常务委员会的组成人员。\n县级以上的地方各级人民代表大会常务委员会的组成人员不得担任国家行政机关、监察机关、审判机关和检察机关的职务', 741, '{\"level\": null, \"title\": null, \"chunk_index\": 20}', 'bge-large-zh-v1.5', '2026-09-25 17:04:29');
INSERT INTO `chunk` VALUES ('e3eb7415-207b-4c4b-8848-2b5488a67999', '22a2c356-7a68-4455-b657-333e3dba1e1a', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 24, '第一百二十九条　中华人民共和国设立最高人民法院、地方各级人民法院和军事法院等专门人民法院。\n最高人民法院院长每届任期同全国人民代表大会每届任期相同，连续任职不得超过两届。\n人民法院的组织由法律规定。\n第一百三十条　人民法院审理案件，除法律规定的特别情况外，一律公开进行。被告人有权获得辩护。\n第一百三十一条　人民法院依照法律规定独立行使审判权，不受行政机关、社会团体和个人的干涉。\n第一百三十二条　最高人民法院是最高审判机关。\n最高人民法院监督地方各级人民法院和专门人民法院的审判工作，上级人民法院监督下级人民法院的审判工作。\n第一百三十三条　最高人民法院对全国人民代表大会和全国人民代表大会常务委员会负责。地方各级人民法院对产生它的国家权力机关负责。\n第一百三十四条　中华人民共和国人民检察院是国家的法律监督机关。\n第一百三十五条　中华人民共和国设立最高人民检察院、地方各级人民检察院和军事检察院等专门人民检察院。\n最高人民检察院检察长每届任期同全国人民代表大会每届任期相同，连续任职不得超过两届。\n人民检察院的组织由法律规定。\n第一百三十六条　人民检察院依照法律规定独立行使检察权，不受行政机关、社会团体和个人的干涉。\n第一百三十七条　最高人民检察院是最高检察机关。\n最高人民检察院领导地方各级人民检察院和专门人民检察院的工作，上级人民检察院领导下级人民检察院的工作。\n第一百三十八条　最高人民检察院对全国人民代表大会和全国人民代表大会常务委员会负责。地方各级人民检察院对产生它的国家权力机关和上级人民检察院负责。\n第一百三十九条　各民族公民都有用本民族语言文字进行诉讼的权利。人民法院和人民检察院对于不通晓当地通用的语言文字的诉讼参与人，应当为他们翻译', 729, '{\"level\": null, \"title\": null, \"chunk_index\": 24}', 'bge-large-zh-v1.5', '2026-09-25 17:04:29');
INSERT INTO `chunk` VALUES ('e4dee185-2ad4-4c18-a221-afc41d58160e', '16cbea7e-7e36-4f31-afb5-63892345d29c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 36, '重新密封时，由二名以上调查人员在密封材料上签名、记明时间。\n第一百六十条　查封、扣押涉案财物，应当按规定将涉案财物详细信息、《查封/扣押财物、文件清单》录入并上传监察机关涉案财物信息管理系统。\n对于涉案款项，应当在采取措施后十五日以内存入监察机关指定的专用账户。对于涉案物品，应当在采取措施后三十日以内移交涉案财物保管部门保管。因特殊原因不能按时存入专用账户或者移交保管的，应当按规定报批，将保管情况录入涉案财物信息管理系统，在原因消除后及时存入或者移交。\n第一百六十一条　对于已移交涉案财物保管部门保管的涉案财物，根据调查工作需要，经审批可以临时调用，并应当确保完好。调用结束后，应当及时归还。调用和归还时，调查人员、保管人员应当当面清点查验。保管部门应当对调用和归还情况进行登记，全程录像并上传涉案财物信息管理系统。\n第一百六十二条　对于被扣押的股票、债券、基金份额等财产，以及即将到期的汇票、本票、支票，依法需要出售或者变现的，按照本条例关于出售冻结财产的规定办理。\n第一百六十三条　监察机关接受司法机关、其他监察机关等国家机关移送的涉案财物后，该国家机关采取的查封、扣押期限届满，监察机关续行查封、扣押的顺位与该国家机关查封、扣押的顺位相同。\n第一百六十四条　对查封、扣押的财物和文件，应当及时进行核查。经查明与案件无关的，经审批，应当在查明后三日以内解除查封、扣押，予以退还。解除查封、扣押的，应当向有关单位、原持有人或者近亲属送达《解除查封/扣押通知书》，附《解除查封/扣押财物、文件清单》，要求其签名或者盖章。\n第一百六十五条　在立案调查之前，对监察对象及相关人员主动上交的涉案财物，经审批可以接收。\n接收时，应当由二名以上调查人员，会同持有人和见证人进行清点核对，当场填写《主动上交财物登记表》。调查人员、持有人和见证人应当在登记表上签名或者盖章', 781, '{\"level\": null, \"title\": null, \"chunk_index\": 36}', 'bge-large-zh-v1.5', '2026-09-25 17:04:49');
INSERT INTO `chunk` VALUES ('e4dfca11-3cde-46c4-9dad-9c5cd57cf80d', '821ce1fd-178d-4a7e-ab92-3deff1488ce2', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 20, '第一百二十七条　盗窃、抢夺枪支、弹药、爆炸物的，或者盗窃、抢夺毒害性、放射性、传染病病原体等物质，危害公共安全的，处三年以上十年以下有期徒刑；情节严重的，处十年以上有期徒刑、无期徒刑或者死刑。\n抢劫枪支、弹药、爆炸物的，或者抢劫毒害性、放射性、传染病病原体等物质，危害公共安全的，或者盗窃、抢夺国家机关、军警人员、民兵的枪支、弹药、爆炸物的，处十年以上有期徒刑、无期徒刑或者死刑。\n第一百二十八条　违反枪支管理规定，非法持有、私藏枪支、弹药的，处三年以下有期徒刑、拘役或者管制；情节严重的，处三年以上七年以下有期徒刑。\n依法配备公务用枪的人员，非法出租、出借枪支的，依照前款的规定处罚。\n依法配置枪支的人员，非法出租、出借枪支，造成严重后果的，依照第一款的规定处罚。\n单位犯第二款、第三款罪的，对单位判处罚金，并对其直接负责的主管人员和其他直接责任人员，依照第一款的规定处罚。\n第一百二十九条　依法配备公务用枪的人员，丢失枪支不及时报告，造成严重后果的，处三年以下有期徒刑或者拘役。\n第一百三十条　非法携带枪支、弹药、管制刀具或者爆炸性、易燃性、放射性、毒害性、腐蚀性物品，进入公共场所或者公共交通工具，危及公共安全，情节严重的，处三年以下有期徒刑、拘役或者管制。\n第一百三十一条　航空人员违反规章制度，致使发生重大飞行事故，造成严重后果的，处三年以下有期徒刑或者拘役；造成飞机坠毁或者人员死亡的，处三年以上七年以下有期徒刑。\n第一百三十二条　铁路职工违反规章制度，致使发生铁路运营安全事故，造成严重后果的，处三年以下有期徒刑或者拘役；造成特别严重后果的，处三年以上七年以下有期徒刑', 691, '{\"level\": null, \"title\": null, \"chunk_index\": 20}', 'bge-large-zh-v1.5', '2026-09-25 17:04:56');
INSERT INTO `chunk` VALUES ('e54042ac-ef1b-4547-8c3a-e0615a6490cf', 'b25ce095-dfba-4403-acf8-c58eb456ca4c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 74, '第六百四十五条　拍卖的当事人的权利和义务以及拍卖程序等，依照有关法律、行政法规的规定。\n第六百四十六条　法律对其他有偿合同有规定的，依照其规定；没有规定的，参照适用买卖合同的有关规定。\n第六百四十七条　当事人约定易货交易，转移标的物的所有权的，参照适用买卖合同的有关规定。\n第十章　供用电、水、气、热力合同\n第六百四十八条　供用电合同是供电人向用电人供电，用电人支付电费的合同。\n向社会公众供电的供电人，不得拒绝用电人合理的订立合同要求。\n第六百四十九条　供用电合同的内容一般包括供电的方式、质量、时间，用电容量、地址、性质，计量方式，电价、电费的结算方式，供用电设施的维护责任等条款。\n第六百五十条　供用电合同的履行地点，按照当事人约定；当事人没有约定或者约定不明确的，供电设施的产权分界处为履行地点。\n第六百五十一条　供电人应当按照国家规定的供电质量标准和约定安全供电。供电人未按照国家规定的供电质量标准和约定安全供电，造成用电人损失的，应当承担赔偿责任。\n第六百五十二条　供电人因供电设施计划检修、临时检修、依法限电或者用电人违法用电等原因，需要中断供电时，应当按照国家有关规定事先通知用电人；未事先通知用电人中断供电，造成用电人损失的，应当承担赔偿责任。\n第六百五十三条　因自然灾害等原因断电，供电人应当按照国家有关规定及时抢修；未及时抢修，造成用电人损失的，应当承担赔偿责任。\n第六百五十四条　用电人应当按照国家有关规定和当事人的约定及时支付电费。用电人逾期不支付电费的，应当按照约定支付违约金。经催告用电人在合理期限内仍不支付电费和违约金的，供电人可以按照国家规定的程序中止供电。\n供电人依据前款规定中止供电的，应当事先通知用电人。\n第六百五十五条　用电人应当按照国家有关规定和当事人的约定安全、节约和计划用电', 761, '{\"level\": null, \"title\": null, \"chunk_index\": 74}', 'bge-large-zh-v1.5', '2026-09-25 17:05:01');
INSERT INTO `chunk` VALUES ('e6088a5f-2d92-412d-b6f1-93fad2079f18', 'd9d7dc15-8041-43b8-9f75-f112fe3ae003', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 20, '禁止通过内河运输的危险化学品的范围，由国务院交通运输主管部门会同生态环境、应急管理、工业和信息化部门，根据危险化学品的危险特性、危险化学品对人体和水环境的危害程度以及消除危害后果的难易程度等因素规定并公布。\n第七十五条　国务院交通运输主管部门应当根据危险化学品的危险特性，对通过内河运输本法第七十四条规定以外的危险化学品（以下简称通过内河运输危险化学品）实行分类管理，对各类危险化学品的运输方式、包装规范和安全防护措施等分别作出规定并监督实施。\n第七十六条　通过内河运输危险化学品，应当使用依法取得危险货物适装证书的运输船舶。水路运输企业应当针对所运输的危险化学品的危险特性，制定运输船舶危险化学品事故应急救援预案，并为运输船舶配备充足、有效的应急救援器材、装备、设备和物资。\n通过内河运输危险化学品的船舶，其所有人或者经营人应当取得船舶污染损害责任保险证书或者财务担保证明。船舶污染损害责任保险证书或者财务担保证明的副本应当随船携带。\n第七十七条　通过内河运输危险化学品，危险化学品包装物的材质、型式、强度以及包装方法应当符合水路运输相关包装规范的要求。国务院交通运输主管部门对单船运输的危险化学品数量有限制性规定的，承运人应当按照规定安排运输数量。\n第七十八条　用于危险化学品运输作业的内河码头、泊位应当符合国家有关安全规范，与饮用水取水口保持国家规定的安全距离。有关管理单位应当制定码头、泊位危险化学品事故应急预案，并为码头、泊位配备充足、有效的应急救援器材、装备、设备和物资。\n用于危险化学品运输作业的内河码头、泊位，按照国家有关规定验收合格后方可投入使用。\n第七十九条　船舶载运危险化学品进出内河港口，应当依照法律、行政法规的规定向海事管理机构报告。海事管理机构接到报告后，应当在国务院交通运输主管部门规定的时间内作出是否同意的决定，通知报告人，同时通报港口行政管理部门', 790, '{\"level\": null, \"title\": null, \"chunk_index\": 20}', 'bge-large-zh-v1.5', '2026-09-25 17:04:46');
INSERT INTO `chunk` VALUES ('e67cba99-3de1-4e82-bef8-70bbe07c9868', '821ce1fd-178d-4a7e-ab92-3deff1488ce2', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 11, '第五节　缓　　刑\n第七十二条　对于被判处拘役、三年以下有期徒刑的犯罪分子，同时符合下列条件的，可以宣告缓刑，对其中不满十八周岁的人、怀孕的妇女和已满七十五周岁的人，应当宣告缓刑：\n（一）犯罪情节较轻；\n（二）有悔罪表现；\n（三）没有再犯罪的危险；\n（四）宣告缓刑对所居住社区没有重大不良影响。\n宣告缓刑，可以根据犯罪情况，同时禁止犯罪分子在缓刑考验期限内从事特定活动，进入特定区域、场所，接触特定的人。\n被宣告缓刑的犯罪分子，如果被判处附加刑，附加刑仍须执行。\n第七十三条　拘役的缓刑考验期限为原判刑期以上一年以下，但是不能少于二个月。\n有期徒刑的缓刑考验期限为原判刑期以上五年以下，但是不能少于一年。\n缓刑考验期限，从判决确定之日起计算。\n第七十四条　对于累犯和犯罪集团的首要分子，不适用缓刑。\n第七十五条　被宣告缓刑的犯罪分子，应当遵守下列规定：\n（一）遵守法律、行政法规，服从监督；\n（二）按照考察机关的规定报告自己的活动情况；\n（三）遵守考察机关关于会客的规定；\n（四）离开所居住的市、县或者迁居，应当报经考察机关批准。\n第七十六条　对宣告缓刑的犯罪分子，在缓刑考验期限内，依法实行社区矫正，如果没有本法第七十七条规定的情形，缓刑考验期满，原判的刑罚就不再执行，并公开予以宣告。\n第七十七条　被宣告缓刑的犯罪分子，在缓刑考验期限内犯新罪或者发现判决宣告以前还有其他罪没有判决的，应当撤销缓刑，对新犯的罪或者新发现的罪作出判决，把前罪和后罪所判处的刑罚，依照本法第六十九条的规定，决定执行的刑罚。\n被宣告缓刑的犯罪分子，在缓刑考验期限内，违反法律、行政法规或者国务院有关部门关于缓刑的监督管理规定，或者违反人民法院判决中的禁止令，情节严重的，应当撤销缓刑，执行原判刑罚', 737, '{\"level\": null, \"title\": null, \"chunk_index\": 11}', 'bge-large-zh-v1.5', '2026-09-25 17:04:56');
INSERT INTO `chunk` VALUES ('e6acfc41-e00f-42af-b644-fccac97ff350', 'd9d7dc15-8041-43b8-9f75-f112fe3ae003', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 4, '县级以上人民政府及其有关部门对举报违法行为或者报告重大事故隐患的有功人员依法给予奖励，并对举报人、报告人的信息进行严格保密。\n第十一条　县级以上人民政府负有危险化学品安全监督管理职责的部门应当加强危险化学品信息化监管，对危险化学品实行电子标识和全生命周期信息化管理和监控。\n化工园区应当明确负责安全生产监督管理的有关工作机构及其职责，加强危险化学品信息化建设，实现信息化安全监测、监控和预警，并与政府有关部门实现互联互通。\n第十二条　国家鼓励危险化学品单位采用有利于提高安全保障水平的先进技术、工艺、设备以及自动控制系统，鼓励对危险化学品实行专门储存、统一配送、集中销售。\n第十三条　生产、储存、使用、经营危险化学品的单位应当按照国家有关规定对危险化学品重大危险源登记建档，进行定期检测、评估、监控，制定应急预案，建立重大危险源安全责任制，并将重大危险源的储存数量、储存地点、管理人员的情况及有关安全措施、应急措施报所在地县级人民政府应急管理部门、消防救援机构和有关部门备案；在港区内储存的，报港口行政管理部门、消防救援机构和有关部门备案。\n负有危险化学品安全监督管理职责的部门应当分级分类定期对危险化学品重大危险源开展专项监督检查，督促危险化学品单位及时消除事故隐患，防范重特大事故发生。\n本法所称重大危险源，是指长期或者临时生产、储存、使用和经营危险化学品，且危险化学品的数量等于或者超过临界量的单元（包括场所和设施）。\n第十四条　各级人民政府及其有关部门应当采取多种形式，加强危险化学品安全法律法规和危险化学品安全知识宣传普及工作，促进全社会危险化学品安全意识的提升。\n化工园区、危险化学品单位应当对周边群众和其他生产经营单位进行危险化学品安全法律法规和危险化学品安全知识宣传。\n新闻媒体应当开展危险化学品安全法律法规和危险化学品安全知识公益宣传，对危险化学品安全违法行为进行舆论监督', 795, '{\"level\": null, \"title\": null, \"chunk_index\": 4}', 'bge-large-zh-v1.5', '2026-09-25 17:04:46');
INSERT INTO `chunk` VALUES ('e82e6332-c9c7-40e6-bcf7-936a66102303', '821ce1fd-178d-4a7e-ab92-3deff1488ce2', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 93, '第四百零八条之一　负有食品药品安全监督管理职责的国家机关工作人员，滥用职权或者玩忽职守，有下列情形之一，造成严重后果或者有其他严重情节的，处五年以下有期徒刑或者拘役；造成特别严重后果或者有其他特别严重情节的，处五年以上十年以下有期徒刑：\n（一）瞒报、谎报食品安全事故、药品安全事件的；\n（二）对发现的严重食品药品安全违法行为未按规定查处的；\n（三）在药品和特殊食品审批审评过程中，对不符合条件的申请准予许可的；\n（四）依法应当移交司法机关追究刑事责任不移交的；\n（五）有其他滥用职权或者玩忽职守行为的。\n徇私舞弊犯前款罪的，从重处罚。\n第四百零九条　从事传染病防治的政府卫生行政部门的工作人员严重不负责任，导致传染病传播或者流行，情节严重的，处三年以下有期徒刑或者拘役。\n第四百一十条　国家机关工作人员徇私舞弊，违反土地管理法规，滥用职权，非法批准征收、征用、占用土地，或者非法低价出让国有土地使用权，情节严重的，处三年以下有期徒刑或者拘役；致使国家或者集体利益遭受特别重大损失的，处三年以上七年以下有期徒刑。\n第四百一十一条　海关工作人员徇私舞弊，放纵走私，情节严重的，处五年以下有期徒刑或者拘役；情节特别严重的，处五年以上有期徒刑。\n第四百一十二条　国家商检部门、商检机构的工作人员徇私舞弊，伪造检验结果的，处五年以下有期徒刑或者拘役；造成严重后果的，处五年以上十年以下有期徒刑。\n前款所列人员严重不负责任，对应当检验的物品不检验，或者延误检验出证、错误出证，致使国家利益遭受重大损失的，处三年以下有期徒刑或者拘役。\n第四百一十三条　动植物检疫机关的检疫人员徇私舞弊，伪造检疫结果的，处五年以下有期徒刑或者拘役；造成严重后果的，处五年以上十年以下有期徒刑。\n前款所列人员严重不负责任，对应当检疫的检疫物不检疫，或者延误检疫出证、错误出证，致使国家利益遭受重大损失的，处三年以下有期徒刑或者拘役', 798, '{\"level\": null, \"title\": null, \"chunk_index\": 93}', 'bge-large-zh-v1.5', '2026-09-25 17:04:56');
INSERT INTO `chunk` VALUES ('e86f176f-4bd6-4e5c-b707-9476b748523b', 'b25ce095-dfba-4403-acf8-c58eb456ca4c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 84, '第七百四十三条　出租人有下列情形之一，致使承租人对出卖人行使索赔权利失败的，承租人有权请求出租人承担相应的责任：\n（一）明知租赁物有质量瑕疵而不告知承租人；\n（二）承租人行使索赔权利时，未及时提供必要协助。\n出租人怠于行使只能由其对出卖人行使的索赔权利，造成承租人损失的，承租人有权请求出租人承担赔偿责任。\n第七百四十四条　出租人根据承租人对出卖人、租赁物的选择订立的买卖合同，未经承租人同意，出租人不得变更与承租人有关的合同内容。\n第七百四十五条　出租人对租赁物享有的所有权，未经登记，不得对抗善意第三人。\n第七百四十六条　融资租赁合同的租金，除当事人另有约定外，应当根据购买租赁物的大部分或者全部成本以及出租人的合理利润确定。\n第七百四十七条　租赁物不符合约定或者不符合使用目的的，出租人不承担责任。但是，承租人依赖出租人的技能确定租赁物或者出租人干预选择租赁物的除外。\n第七百四十八条　出租人应当保证承租人对租赁物的占有和使用。\n出租人有下列情形之一的，承租人有权请求其赔偿损失：\n（一）无正当理由收回租赁物；\n（二）无正当理由妨碍、干扰承租人对租赁物的占有和使用；\n（三）因出租人的原因致使第三人对租赁物主张权利；\n（四）不当影响承租人对租赁物占有和使用的其他情形。\n第七百四十九条　承租人占有租赁物期间，租赁物造成第三人人身损害或者财产损失的，出租人不承担责任。\n第七百五十条　承租人应当妥善保管、使用租赁物。\n承租人应当履行占有租赁物期间的维修义务。\n第七百五十一条　承租人占有租赁物期间，租赁物毁损、灭失的，出租人有权请求承租人继续支付租金，但是法律另有规定或者当事人另有约定的除外。\n第七百五十二条　承租人应当按照约定支付租金。承租人经催告后在合理期限内仍不支付租金的，出租人可以请求支付全部租金；也可以解除合同，收回租赁物', 770, '{\"level\": null, \"title\": null, \"chunk_index\": 84}', 'bge-large-zh-v1.5', '2026-09-25 17:05:01');
INSERT INTO `chunk` VALUES ('e91fd915-51b9-43cf-9c3b-beda6d30a155', '16cbea7e-7e36-4f31-afb5-63892345d29c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 10, '第五十条　上级监察机关对于下一级监察机关管辖范围内的职务违法和职务犯罪案件，具有下列情形之一的，可以依法提级管辖：\n（一）在本辖区有重大影响的；\n（二）涉及多个下级监察机关管辖的监察对象，调查难度大的；\n（三）其他需要提级管辖的重大、复杂案件。\n上级监察机关对于所辖各级监察机关管辖范围内有重大影响的案件，必要时可以依法直接调查或者组织、指挥、参与调查。\n地方各级监察机关所管辖的职务违法和职务犯罪案件，具有第一款规定情形的，可以依法报请上一级监察机关管辖。\n第五十一条　上级监察机关可以依法将其所管辖的案件指定下级监察机关管辖。\n设区的市级监察委员会将同级党委管理的公职人员涉嫌职务违法或者职务犯罪案件指定下级监察委员会管辖的，应当报请省级监察委员会批准；省级监察委员会将同级党委管理的公职人员涉嫌职务违法或者职务犯罪案件指定下级监察委员会管辖的，应当报送国家监察委员会相关监督检查部门备案。\n上级监察机关对于下级监察机关管辖的职务违法和职务犯罪案件，具有下列情形之一，认为由其他下级监察机关管辖更为适宜的，可以依法指定给其他下级监察机关管辖：\n（一）管辖有争议的；\n（二）指定管辖有利于案件公正处理的；\n（三）下级监察机关报请指定管辖的；\n（四）其他有必要指定管辖的。\n被指定的下级监察机关未经指定管辖的监察机关批准，不得将案件再行指定管辖。发现新的职务违法或者职务犯罪线索，以及其他重要情况、重大问题，应当及时向指定管辖的监察机关请示报告。\n第五十二条　工作单位在地方、管理权限在主管部门的公职人员涉嫌职务违法和职务犯罪，一般由驻在主管部门、有管辖权的监察机构、监察专员管辖；经协商，监察机构、监察专员可以按规定移交公职人员工作单位所在地的地方监察委员会调查，或者与地方监察委员会联合调查', 747, '{\"level\": null, \"title\": null, \"chunk_index\": 10}', 'bge-large-zh-v1.5', '2026-09-25 17:04:49');
INSERT INTO `chunk` VALUES ('e9bc4d37-7440-4e70-9a3d-e4d878e92976', '16cbea7e-7e36-4f31-afb5-63892345d29c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 11, '地方监察委员会在工作中发现上述公职人员有关问题线索，应当向驻在主管部门、有管辖权的监察机构、监察专员通报，并协商确定管辖。\n前款规定单位的其他公职人员涉嫌职务违法的，可以由公职人员工作单位所在地的地方监察委员会管辖。涉嫌职务犯罪的，一般由公职人员工作单位所在地的地方监察委员会管辖；因涉及主管部门管理的公职人员等特殊情形，驻在主管部门的监察机构、监察专员认为由自己管辖或者其他地方监察委员会管辖更为适宜的，经与公职人员工作单位所在地的地方监察委员会协商，可以自行调查或者依法办理指定管辖。\n地方监察委员会调查前两款规定案件，应当按程序将立案、留置、移送审查起诉、撤销案件等重要情况通报相关监察机构、监察专员。\n第五十三条　监察机关办理案件中涉及无隶属关系的其他监察机关的监察对象，认为需要立案调查的，应当商请有管理权限的监察机关依法立案调查。商请立案时，应当提供涉案人员基本情况、已经查明的涉嫌违法犯罪事实以及相关证据材料。\n承办案件的监察机关认为由其一并调查更为适宜的，可以报请有权决定的上级监察机关指定管辖。\n第五十四条　公职人员既涉嫌贪污贿赂、失职渎职等严重职务违法和职务犯罪，又涉嫌公安机关、人民检察院等机关管辖的犯罪，依法由监察机关为主调查的，应当由监察机关和其他机关分别依职权立案，监察机关承担组织协调职责，协调调查和侦查工作进度、重要调查和侦查措施使用等重要事项。\n第五十五条　监察机关必要时可以依法调查司法工作人员利用职权实施的涉嫌非法拘禁、刑讯逼供、非法搜查等侵犯公民权利、损害司法公正的犯罪，并在立案后及时通报同级人民检察院。\n监察机关在调查司法工作人员涉嫌贪污贿赂等职务犯罪中，可以对其涉嫌的前款规定的犯罪一并调查，并及时通报同级人民检察院', 731, '{\"level\": null, \"title\": null, \"chunk_index\": 11}', 'bge-large-zh-v1.5', '2026-09-25 17:04:49');
INSERT INTO `chunk` VALUES ('e9c7961b-7119-4408-ab88-050f369e92be', 'b25ce095-dfba-4403-acf8-c58eb456ca4c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 21, '第一百七十五条　有下列情形之一的，法定代理终止：\n（一）被代理人取得或者恢复完全民事行为能力；\n（二）代理人丧失民事行为能力；\n（三）代理人或者被代理人死亡；\n（四）法律规定的其他情形。\n第八章　民事责任\n第一百七十六条　民事主体依照法律规定或者按照当事人约定，履行民事义务，承担民事责任。\n第一百七十七条　二人以上依法承担按份责任，能够确定责任大小的，各自承担相应的责任；难以确定责任大小的，平均承担责任。\n第一百七十八条　二人以上依法承担连带责任的，权利人有权请求部分或者全部连带责任人承担责任。\n连带责任人的责任份额根据各自责任大小确定；难以确定责任大小的，平均承担责任。实际承担责任超过自己责任份额的连带责任人，有权向其他连带责任人追偿。\n连带责任，由法律规定或者当事人约定。\n第一百七十九条　承担民事责任的方式主要有：\n（一）停止侵害；\n（二）排除妨碍；\n（三）消除危险；\n（四）返还财产；\n（五）恢复原状；\n（六）修理、重作、更换；\n（七）继续履行；\n（八）赔偿损失；\n（九）支付违约金；\n（十）消除影响、恢复名誉；\n（十一）赔礼道歉。\n法律规定惩罚性赔偿的，依照其规定。\n本条规定的承担民事责任的方式，可以单独适用，也可以合并适用。\n第一百八十条　因不可抗力不能履行民事义务的，不承担民事责任。法律另有规定的，依照其规定。\n不可抗力是不能预见、不能避免且不能克服的客观情况。\n第一百八十一条　因正当防卫造成损害的，不承担民事责任。\n正当防卫超过必要的限度，造成不应有的损害的，正当防卫人应当承担适当的民事责任。\n第一百八十二条　因紧急避险造成损害的，由引起险情发生的人承担民事责任。\n危险由自然原因引起的，紧急避险人不承担民事责任，可以给予适当补偿。\n紧急避险采取措施不当或者超过必要的限度，造成不应有的损害的，紧急避险人应当承担适当的民事责任', 779, '{\"level\": null, \"title\": null, \"chunk_index\": 21}', 'bge-large-zh-v1.5', '2026-09-25 17:05:01');
INSERT INTO `chunk` VALUES ('e9ee5798-81e0-4d94-8acb-bc792af3fdb9', 'b25ce095-dfba-4403-acf8-c58eb456ca4c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 129, '第一千一百二十五条　继承人有下列行为之一的，丧失继承权：\n（一）故意杀害被继承人；\n（二）为争夺遗产而杀害其他继承人；\n（三）遗弃被继承人，或者虐待被继承人情节严重；\n（四）伪造、篡改、隐匿或者销毁遗嘱，情节严重；\n（五）以欺诈、胁迫手段迫使或者妨碍被继承人设立、变更或者撤回遗嘱，情节严重。\n继承人有前款第三项至第五项行为，确有悔改表现，被继承人表示宽恕或者事后在遗嘱中将其列为继承人的，该继承人不丧失继承权。\n受遗赠人有本条第一款规定行为的，丧失受遗赠权。\n第二章　法定继承\n第一千一百二十六条　继承权男女平等。\n第一千一百二十七条　遗产按照下列顺序继承：\n（一）第一顺序：配偶、子女、父母；\n（二）第二顺序：兄弟姐妹、祖父母、外祖父母。\n继承开始后，由第一顺序继承人继承，第二顺序继承人不继承；没有第一顺序继承人继承的，由第二顺序继承人继承。\n本编所称子女，包括婚生子女、非婚生子女、养子女和有扶养关系的继子女。\n本编所称父母，包括生父母、养父母和有扶养关系的继父母。\n本编所称兄弟姐妹，包括同父母的兄弟姐妹、同父异母或者同母异父的兄弟姐妹、养兄弟姐妹、有扶养关系的继兄弟姐妹。\n第一千一百二十八条　被继承人的子女先于被继承人死亡的，由被继承人的子女的直系晚辈血亲代位继承。\n被继承人的兄弟姐妹先于被继承人死亡的，由被继承人的兄弟姐妹的子女代位继承。\n代位继承人一般只能继承被代位继承人有权继承的遗产份额。\n第一千一百二十九条　丧偶儿媳对公婆，丧偶女婿对岳父母，尽了主要赡养义务的，作为第一顺序继承人。\n第一千一百三十条　同一顺序继承人继承遗产的份额，一般应当均等。\n对生活有特殊困难又缺乏劳动能力的继承人，分配遗产时，应当予以照顾。\n对被继承人尽了主要扶养义务或者与被继承人共同生活的继承人，分配遗产时，可以多分。\n有扶养能力和有扶养条件的继承人，不尽扶养义务的，分配遗产时，应当不分或者少分', 800, '{\"level\": null, \"title\": null, \"chunk_index\": 129}', 'bge-large-zh-v1.5', '2026-09-25 17:05:01');
INSERT INTO `chunk` VALUES ('ea3edd6a-012a-4084-b065-daa3b429f89d', '16cbea7e-7e36-4f31-afb5-63892345d29c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 58, '第二百四十九条　涉嫌行贿等犯罪的涉案人员具有下列情形之一的，可以认定为监察法第三十五条规定的揭发有关被调查人职务违法犯罪行为，查证属实或者提供重要线索，有助于调查其他案件：\n（一）揭发所涉案件以外的被调查人职务犯罪行为，经查证属实的；\n（二）提供的重要线索指向具体的职务犯罪事实，对调查其他案件起到实质性推动作用的；\n（三）提供的重要线索有助于加快其他案件办理进度，或者对其他案件固定关键证据、挽回损失、追逃追赃等起到积极作用的。\n第二百五十条　从宽处罚建议一般应当在移送起诉时作为《起诉意见书》内容一并提出，特殊情况下也可以在案件移送后、人民检察院提起公诉前，单独形成从宽处罚建议书移送人民检察院。对于从宽处罚建议所依据的证据材料，应当一并移送人民检察院。\n监察机关对于被调查人在调查阶段认罪认罚，但不符合监察法规定的提出从宽处罚建议条件，在移送起诉时没有提出从宽处罚建议的，应当在《起诉意见书》中写明其自愿认罪认罚的情况。\n第二百五十一条　监察机关一般应当在正式移送起诉十日前，向拟移送的人民检察院采取书面通知等方式预告移送事宜。监察机关发现被调查人因身体等原因存在不适宜羁押等可能影响刑事强制措施执行情形的，应当通报人民检察院；被调查人已被采取留置措施的，可以在移送起诉前依法变更为责令候查措施。对于未采取监察强制措施的案件，可以根据案件具体情况，向人民检察院提出对被调查人采取刑事强制措施的建议。\n第二百五十二条　监察机关办理的职务犯罪案件移送起诉，需要指定起诉、审判管辖的，应当与同级人民检察院协商有关程序事宜。需要由同级人民检察院的上级人民检察院指定管辖的，应当商请同级人民检察院办理指定管辖事宜。\n监察机关一般应当在移送起诉二十日前，将商请指定管辖函送交同级人民检察院。商请指定管辖函应当附案件基本情况，对于被调查人已被其他机关立案侦查的犯罪认为需要并案审查起诉的，一并进行说明', 796, '{\"level\": null, \"title\": null, \"chunk_index\": 58}', 'bge-large-zh-v1.5', '2026-09-25 17:04:49');
INSERT INTO `chunk` VALUES ('eb4de4a6-26ad-44c1-8a1d-f49fa9ebedf6', 'b25ce095-dfba-4403-acf8-c58eb456ca4c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 111, '第九百七十四条　除合伙合同另有约定外，合伙人向合伙人以外的人转让其全部或者部分财产份额的，须经其他合伙人一致同意。\n第九百七十五条　合伙人的债权人不得代位行使合伙人依照本章规定和合伙合同享有的权利，但是合伙人享有的利益分配请求权除外。\n第九百七十六条　合伙人对合伙期限没有约定或者约定不明确，依据本法第五百一十条的规定仍不能确定的，视为不定期合伙。\n合伙期限届满，合伙人继续执行合伙事务，其他合伙人没有提出异议的，原合伙合同继续有效，但是合伙期限为不定期。\n合伙人可以随时解除不定期合伙合同，但是应当在合理期限之前通知其他合伙人。\n第九百七十七条　合伙人死亡、丧失民事行为能力或者终止的，合伙合同终止；但是，合伙合同另有约定或者根据合伙事务的性质不宜终止的除外。\n第九百七十八条　合伙合同终止后，合伙财产在支付因终止而产生的费用以及清偿合伙债务后有剩余的，依据本法第九百七十二条的规定进行分配。\n第三分编　准合同\n第二十八章　无因管理\n第九百七十九条　管理人没有法定的或者约定的义务，为避免他人利益受损失而管理他人事务的，可以请求受益人偿还因管理事务而支出的必要费用；管理人因管理事务受到损失的，可以请求受益人给予适当补偿。\n管理事务不符合受益人真实意思的，管理人不享有前款规定的权利；但是，受益人的真实意思违反法律或者违背公序良俗的除外。\n第九百八十条　管理人管理事务不属于前条规定的情形，但是受益人享有管理利益的，受益人应当在其获得的利益范围内向管理人承担前条第一款规定的义务。\n第九百八十一条　管理人管理他人事务，应当采取有利于受益人的方法。中断管理对受益人不利的，无正当理由不得中断。\n第九百八十二条　管理人管理他人事务，能够通知受益人的，应当及时通知受益人。管理的事务不需要紧急处理的，应当等待受益人的指示。\n第九百八十三条　管理结束后，管理人应当向受益人报告管理事务的情况', 792, '{\"level\": null, \"title\": null, \"chunk_index\": 111}', 'bge-large-zh-v1.5', '2026-09-25 17:05:01');
INSERT INTO `chunk` VALUES ('ec163428-485e-454b-9516-ae088ef7dc7b', 'd9d7dc15-8041-43b8-9f75-f112fe3ae003', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 8, '生产、储存危险化学品的单位，应当对其敷设的危险化学品管道设置明显标志，并对危险化学品管道定期检查、检测、巡护。\n进行可能危及危险化学品管道安全的施工作业，施工单位应当在开工的七日前将施工方案书面通知管道所属单位，并与管道所属单位共同制定应急预案，采取相应的安全防护措施。管道所属单位应当指派专门人员到现场进行管道安全保护指导。\n第二十九条　危险化学品生产企业主要负责人（包括法定代表人、实际控制人、实际负责人）和安全生产管理人员应当具备相应的安全生产知识和管理能力，并经应急管理部门考核合格。\n危险化学品生产企业从业人员应当满足国家规定的学历要求，接受安全生产教育和培训，考核合格后上岗作业。\n危险化学品生产企业应当建立健全安全培训管理制度，定期组织培训，提高从业人员安全意识和安全生产技能水平。\n第三十条　危险化学品生产企业进行生产前，应当依照有关安全生产许可法律、行政法规的规定，取得危险化学品安全生产许可证。\n生产列入国家实行生产许可证制度的工业产品目录的危险化学品的企业，还应当依照有关工业产品生产许可法律、行政法规的规定，取得工业产品生产许可证。试生产的危险化学品，在取得工业产品生产许可证后，经具有相应资质的检验机构检验合格可以销售。\n负责颁发危险化学品安全生产许可证、工业产品生产许可证的部门，应当将其颁发许可证的情况依照有关法律、行政法规的规定及时向社会公开。\n第三十一条　危险化学品生产企业、进口企业应当提供与其生产、进口的危险化学品相符的中文化学品安全技术说明书，并在危险化学品包装（包括外包装件，下同）上粘贴、印刷或者拴挂与包装内危险化学品相符的中文化学品安全标签。化学品安全技术说明书和化学品安全标签应当符合国家标准的要求。\n危险化学品生产企业、进口企业发现其生产或者进口的危险化学品有新的危险特性的，应当立即公告，及时修订其化学品安全技术说明书和化学品安全标签', 793, '{\"level\": null, \"title\": null, \"chunk_index\": 8}', 'bge-large-zh-v1.5', '2026-09-25 17:04:46');
INSERT INTO `chunk` VALUES ('ec2579fc-c283-4e0b-9baa-49257a7bae87', 'd9d7dc15-8041-43b8-9f75-f112fe3ae003', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 35, '水路运输企业的申报人员、集装箱装箱现场检查员违反法律、行政法规或者规章关于危险化学品安全管理规定的，由交通运输主管部门责令限期改正，给予警告；情节严重的，责令暂停从业活动直至吊销其从业资格。\n第一百一十条　有下列情形之一的，由交通运输主管部门责令限期改正，处二十万元以上三十万元以下的罚款，有违法所得的，没收违法所得；逾期不改正的，责令停产停业整顿，对其直接负责的主管人员和其他直接责任人员处一万元以上五万元以下的罚款：\n（一）委托未依法取得相应许可或者办理备案手续的单位或者个人承运危险化学品；\n（二）通过内河封闭水域运输剧毒化学品；\n（三）通过内河水域运输国家规定禁止通过内河运输的危险化学品；\n（四）载运危险化学品的船舶在内河航行时通过通航建筑物，未提前向通航建筑物运行单位报告，或者不服从交通运输主管部门管理；\n（五）在托运的普通货物中夹带危险化学品，或者将危险化学品匿报、谎报为普通货物托运。\n邮政企业、快递企业收寄危险化学品的，依照《中华人民共和国邮政法》的规定处理、处罚。\n第一百一十一条　有下列情形之一的，由公安机关责令限期改正，处十万元以上二十万元以下的罚款：\n（一）超过运输车辆的核定载质量装载危险化学品；\n（二）使用安全技术条件不符合国家标准要求的车辆运输危险化学品；\n（三）运输危险化学品的车辆未经公安机关批准进入危险化学品运输车辆限制通行的区域；\n（四）未取得剧毒化学品道路运输通行证，通过道路运输剧毒化学品', 617, '{\"level\": null, \"title\": null, \"chunk_index\": 35}', 'bge-large-zh-v1.5', '2026-09-25 17:04:46');
INSERT INTO `chunk` VALUES ('ed93605b-48b2-41e5-bd6e-85d2ec34c34d', '0497a5e7-7044-4b18-8fed-af3fb7bc7890', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 5, '第二十九条　增值税法第二十四条第一款第七项所称托儿所、幼儿园，是指依据有关规定设立的取得托育或者学前教育资格的机构，其免征增值税的收入是指有关收费标准规定以内的保育费、保育教育费；养老机构，是指依据有关规定设立的为老年人提供集中住宿和照料护理服务的各类养老机构；残疾人服务机构，是指依据有关规定设立的专门为残疾人提供相关服务的机构。\n第三十条　增值税法第二十四条第一款第八项所称学校，是指依据有关规定设立的提供学历教育的机构，以及技工学校、高级技工学校、技师学院。\n第三十一条　增值税法第二十四条第一款第九项所称门票收入，是指第一道门票收入。\n第三十二条　增值税优惠政策的适用范围、标准、条件等应当依法及时向社会公开。\n第三十三条　国务院财政、税务主管部门应当适时研究和评估增值税优惠政策执行效果，对不再适应国民经济和社会发展需要的优惠政策，及时报请国务院予以调整完善。\n第五章　征收管理\n第三十四条　单位以承包、承租、挂靠方式经营，承包人、承租人、挂靠人以发包人、出租人、被挂靠人名义对外经营并由发包人、出租人、被挂靠人承担相关法律责任的，发包人、出租人、被挂靠人为纳税人；其他情形下，承包人、承租人、挂靠人为纳税人。\n资管产品运营过程中发生的应税交易，资管产品管理人为纳税人。法律另有规定的，从其规定。\n第三十五条　自然人发生符合规定的应税交易，支付价款的境内单位为扣缴义务人。代扣代缴的具体操作办法，由国务院财政、税务主管部门制定。\n境外单位或者个人向自然人出租境内不动产，有境内代理人的，由境内代理人申报缴纳税款。\n第三十六条　除本条例另有规定外，单位和个体工商户年应征增值税销售额超过小规模纳税人标准的，应当向主管税务机关办理一般纳税人登记，并自超过小规模纳税人标准的当期起按照一般计税方法计算缴纳增值税', 757, '{\"level\": null, \"title\": null, \"chunk_index\": 5}', 'bge-large-zh-v1.5', '2026-09-25 17:04:28');
INSERT INTO `chunk` VALUES ('ed93ad8a-425d-4524-8d8e-0216bb4a3281', '821ce1fd-178d-4a7e-ab92-3deff1488ce2', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 81, '犯前两款罪，事先通谋的，以走私、贩卖、运输、制造毒品罪的共犯论处。\n第三百五十条　违反国家规定，非法生产、买卖、运输醋酸酐、乙醚、三氯甲烷或者其他用于制造毒品的原料、配剂，或者携带上述物品进出境，情节较重的，处三年以下有期徒刑、拘役或者管制，并处罚金；情节严重的，处三年以上七年以下有期徒刑，并处罚金；情节特别严重的，处七年以上有期徒刑，并处罚金或者没收财产。\n明知他人制造毒品而为其生产、买卖、运输前款规定的物品的，以制造毒品罪的共犯论处。\n单位犯前两款罪的，对单位判处罚金，并对其直接负责的主管人员和其他直接责任人员，依照前两款的规定处罚。\n第三百五十一条　非法种植罂粟、大麻等毒品原植物的，一律强制铲除。有下列情形之一的，处五年以下有期徒刑、拘役或者管制，并处罚金：\n（一）种植罂粟五百株以上不满三千株或者其他毒品原植物数量较大的；\n（二）经公安机关处理后又种植的；\n（三）抗拒铲除的。\n非法种植罂粟三千株以上或者其他毒品原植物数量大的，处五年以上有期徒刑，并处罚金或者没收财产。\n非法种植罂粟或者其他毒品原植物，在收获前自动铲除的，可以免除处罚。\n第三百五十二条　非法买卖、运输、携带、持有未经灭活的罂粟等毒品原植物种子或者幼苗，数量较大的，处三年以下有期徒刑、拘役或者管制，并处或者单处罚金。\n第三百五十三条　引诱、教唆、欺骗他人吸食、注射毒品的，处三年以下有期徒刑、拘役或者管制，并处罚金；情节严重的，处三年以上七年以下有期徒刑，并处罚金。\n强迫他人吸食、注射毒品的，处三年以上十年以下有期徒刑，并处罚金。\n引诱、教唆、欺骗或者强迫未成年人吸食、注射毒品的，从重处罚。\n第三百五十四条　容留他人吸食、注射毒品的，处三年以下有期徒刑、拘役或者管制，并处罚金', 733, '{\"level\": null, \"title\": null, \"chunk_index\": 81}', 'bge-large-zh-v1.5', '2026-09-25 17:04:56');
INSERT INTO `chunk` VALUES ('eda093f9-b67f-4612-982f-4a59d8f043bd', 'b25ce095-dfba-4403-acf8-c58eb456ca4c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 0, '中华人民共和国民法典\n（2020年5月28日第十三届全国人民代表大会第三次会议通过）\n目　　录\n第一编　总　　则\n第一章　基本规定\n第二章　自然人\n第一节　民事权利能力和民事行为能力\n第二节　监　　护\n第三节　宣告失踪和宣告死亡\n第四节　个体工商户和农村承包经营户\n第三章　法　　人\n第一节　一般规定\n第二节　营利法人\n第三节　非营利法人\n第四节　特别法人\n第四章　非法人组织\n第五章　民事权利\n第六章　民事法律行为\n第一节　一般规定\n第二节　意思表示\n第三节　民事法律行为的效力\n第四节　民事法律行为的附条件和附期限\n第七章　代　　理\n第一节　一般规定\n第二节　委托代理\n第三节　代理终止\n第八章　民事责任\n第九章　诉讼时效\n第十章　期间计算\n第二编　物　　权\n第一分编　通　　则\n第一章　一般规定\n第二章　物权的设立、变更、转让和消灭\n第一节　不动产登记\n第二节　动产交付\n第三节　其他规定\n第三章　物权的保护\n第二分编　所有权\n第四章　一般规定\n第五章　国家所有权和集体所有权、私人所有权\n第六章　业主的建筑物区分所有权\n第七章　相邻关系\n第八章　共　　有\n第九章　所有权取得的特别规定\n第三分编　用益物权\n第十章　一般规定\n第十一章　土地承包经营权\n第十二章　建设用地使用权\n第十三章　宅基地使用权\n第十四章　居住权\n第十五章　地役权\n第四分编　担保物权\n第十六章　一般规定\n第十七章　抵押权\n第一节　一般抵押权\n第二节　最高额抵押权\n第十八章　质　　权\n第一节　动产质权\n第二节　权利质权\n第十九章　留置权\n第五分编　占　　有\n第二十章　占　　有\n第三编　合　　同\n第一分编　通　　则\n第一章　一般规定\n第二章　合同的订立\n第三章　合同的效力\n第四章　合同的履行\n第五章　合同的保全\n第六章　合同的变更和转让\n第七章　合同的权利义务终止\n第八章　违约责任\n第二分编　典型合同\n第九章　买卖合', 800, '{\"level\": null, \"title\": null, \"chunk_index\": 0}', 'bge-large-zh-v1.5', '2026-09-25 17:05:01');
INSERT INTO `chunk` VALUES ('ee5bc911-242f-4906-8c36-ab5eebc20bb1', '22a2c356-7a68-4455-b657-333e3dba1e1a', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 10, '第五十条　中华人民共和国保护华侨的正当的权利和利益，保护归侨和侨眷的合法的权利和利益。\n第五十一条　中华人民共和国公民在行使自由和权利的时候，不得损害国家的、社会的、集体的利益和其他公民的合法的自由和权利。\n第五十二条　中华人民共和国公民有维护国家统一和全国各民族团结的义务。\n第五十三条　中华人民共和国公民必须遵守宪法和法律，保守国家秘密，爱护公共财产，遵守劳动纪律，遵守公共秩序，尊重社会公德。\n第五十四条　中华人民共和国公民有维护祖国的安全、荣誉和利益的义务，不得有危害祖国的安全、荣誉和利益的行为。\n第五十五条　保卫祖国、抵抗侵略是中华人民共和国每一个公民的神圣职责。\n依照法律服兵役和参加民兵组织是中华人民共和国公民的光荣义务。\n第五十六条　中华人民共和国公民有依照法律纳税的义务。\n第三章　国家机构\n第一节　全国人民代表大会\n第五十七条　中华人民共和国全国人民代表大会是最高国家权力机关。它的常设机关是全国人民代表大会常务委员会。\n第五十八条　全国人民代表大会和全国人民代表大会常务委员会行使国家立法权。\n第五十九条　全国人民代表大会由省、自治区、直辖市、特别行政区和军队选出的代表组成。各少数民族都应当有适当名额的代表。\n全国人民代表大会代表的选举由全国人民代表大会常务委员会主持。\n全国人民代表大会代表名额和代表产生办法由法律规定。\n第六十条　全国人民代表大会每届任期五年。\n全国人民代表大会任期届满的两个月以前，全国人民代表大会常务委员会必须完成下届全国人民代表大会代表的选举。如果遇到不能进行选举的非常情况，由全国人民代表大会常务委员会以全体组成人员的三分之二以上的多数通过，可以推迟选举，延长本届全国人民代表大会的任期。在非常情况结束后一年内，必须完成下届全国人民代表大会代表的选举。\n第六十一条　全国人民代表大会会议每年举行一次，由全国人民代表大会常务委员会召集', 793, '{\"level\": null, \"title\": null, \"chunk_index\": 10}', 'bge-large-zh-v1.5', '2026-09-25 17:04:28');
INSERT INTO `chunk` VALUES ('eea38ce9-2831-4060-b366-c7dc1111ecbf', 'd9d7dc15-8041-43b8-9f75-f112fe3ae003', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 37, '第一百一十五条　有下列情形之一的，依照有关内河交通安全管理法律、行政法规的规定处理、处罚：\n（一）通过内河运输危险化学品的水路运输企业未制定运输船舶危险化学品事故应急救援预案，或者未为运输船舶配备充足、有效的应急救援器材、装备、设备和物资；\n（二）通过内河运输危险化学品的船舶的所有人或者经营人未取得船舶污染损害责任保险证书或者财务担保证明；\n（三）船舶载运危险化学品进出内河港口，未依照法律、行政法规的规定报告海事管理机构并经其同意；\n（四）载运危险化学品的船舶在内河航行、装卸或者停泊，未悬挂专用的警示标志，未按照规定显示专用信号，或者未按照规定申请引航。\n未向港口行政管理部门报告并经其同意，在内河港口内进行危险化学品的装卸、过驳作业的，依照《中华人民共和国港口法》的规定处理、处罚。\n第一百一十六条　伪造、变造或者出租、出借、转让危险化学品安全生产许可证、工业产品生产许可证，或者使用伪造、变造的危险化学品安全生产许可证、工业产品生产许可证的，分别依照有关安全生产许可、工业产品生产许可法律、行政法规的规定处理、处罚。\n伪造、变造或者出租、出借、转让本法规定的其他许可证，或者使用伪造、变造的本法规定的其他许可证的，分别由相关许可证的颁发管理机关处二十万元以上三十万元以下的罚款，有违法所得的，没收违法所得。\n第一百一十七条　危险化学品单位发生危险化学品事故，其主要负责人不立即组织救援或者不立即向有关部门报告的，依照有关生产安全事故报告和调查处理法律、行政法规的规定处理、处罚。\n危险化学品单位的主要负责人未履行安全生产管理职责，导致发生生产安全事故的，依照《中华人民共和国安全生产法》的规定限制从业。\n危险化学品单位发生危险化学品事故，造成他人人身伤害或者财产损失的，依法承担赔偿责任', 748, '{\"level\": null, \"title\": null, \"chunk_index\": 37}', 'bge-large-zh-v1.5', '2026-09-25 17:04:46');
INSERT INTO `chunk` VALUES ('ef6add89-c973-488a-9cd3-af3f5d0799b0', 'd9d7dc15-8041-43b8-9f75-f112fe3ae003', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 28, '从事危险化学品仓储经营的港口经营人有前款规定情形的，由港口行政管理部门依照前款规定予以处理、处罚。储存剧毒化学品、易制爆危险化学品的专用储存场所未按照国家有关规定设置相应的实体防范、技术防范设施的，由公安机关依照前款规定予以处理、处罚。\n生产、储存剧毒化学品、易制爆危险化学品的单位未设置治安保卫机构、配备专职治安保卫人员的，依照有关企业事业单位内部治安保卫法律、行政法规的规定处理、处罚。\n第一百零二条　危险化学品包装物、容器生产企业销售未经检验或者经检验不合格的危险化学品包装物、容器的，由市场监督管理部门责令限期改正，处二十万元以上五十万元以下的罚款，有违法所得的，没收违法所得；逾期不改正的，责令停产停业整顿，对其直接负责的主管人员和其他直接责任人员处一万元以上五万元以下的罚款。\n将未经检验合格的运输危险化学品的船舶及其配载的容器投入使用的，由海事管理机构依照前款规定予以处理、处罚', 396, '{\"level\": null, \"title\": null, \"chunk_index\": 28}', 'bge-large-zh-v1.5', '2026-09-25 17:04:46');
INSERT INTO `chunk` VALUES ('ef71c54d-cff2-452f-9c6c-320d88207406', '16cbea7e-7e36-4f31-afb5-63892345d29c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 17, '谈话应当在监察机关谈话场所、具备安全保障条件的工作地点等场所进行，明确告知谈话事项，注重谈清问题、取得教育效果。\n第七十九条　采取谈话方式处置问题线索的，经审批可以由监察人员或者委托被谈话人所在单位主要负责人等进行谈话。\n监察机关谈话应当形成谈话笔录或者记录。谈话结束后，可以根据需要要求被谈话人在十五个工作日以内作出书面说明。被谈话人应当在书面说明每页签名，修改的地方也应当签名。\n委托谈话的，受委托人应当在收到委托函后的十五个工作日以内进行谈话。谈话结束后及时形成谈话情况材料报送监察机关，必要时附被谈话人的书面说明。\n第八十条　监察机关开展初步核实工作，一般不与被核查人接触；确有需要与被核查人谈话的，应当按规定报批。\n第八十一条　监察机关对涉嫌职务违法的被调查人立案后，可以依法进行谈话。\n与被调查人首次谈话时，应当出示《被调查人权利义务告知书》，由其签名、捺指印。被调查人拒绝签名、捺指印的，调查人员应当在文书上记明。对于被调查人未被限制人身自由的，应当在首次谈话时出具《谈话通知书》。\n与涉嫌严重职务违法的被调查人进行谈话的，应当全程同步录音录像，并告知被调查人。告知情况应当在录音录像中予以反映，并在笔录中记明。\n第八十二条　立案后，与被责令候查人员或者未被限制人身自由的被调查人谈话的，应当在具备安全保障条件的场所进行。\n调查人员按规定通知被调查人所在单位派员或者被调查人家属陪同被调查人到指定场所的，应当与陪同人员办理交接手续，填写《陪送交接单》。\n第八十三条　调查人员与被强制到案人员、被管护人员、被留置人员或者被禁闭人员谈话的，按照法定程序在执行相关监察强制措施的场所进行。\n与在押的犯罪嫌疑人、被告人谈话的，应当持以监察机关名义出具的介绍信、工作证件，商请有关案件主管机关依法协助办理。\n与在看守所、监狱服刑的人员谈话的，应当持以监察机关名义出具的介绍信、工作证件办理', 796, '{\"level\": null, \"title\": null, \"chunk_index\": 17}', 'bge-large-zh-v1.5', '2026-09-25 17:04:49');
INSERT INTO `chunk` VALUES ('f04f4ec5-476e-4f5e-a17e-15383528bbe5', '16cbea7e-7e36-4f31-afb5-63892345d29c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 25, '第一百一十六条　采取管护措施后，应当在二十四小时以内通知被管护人员所在单位和家属。当面通知的，由有关人员在《管护通知书》上签名。无法当面通知的，可以先以电话等方式通知，并通过邮寄、转交等方式送达《管护通知书》，要求有关人员在《管护通知书》上签名。有关人员拒绝签名的，调查人员应当在文书上记明。\n因可能伪造、隐匿、毁灭证据，干扰证人作证或者串供等有碍调查情形而不宜通知的，应当按规定报批，记录在案。有碍调查的情形消失后，应当立即通知被管护人员所在单位和家属。\n第一百一十七条　监察机关采取管护措施后，应当在二十四小时以内对被管护人员进行谈话、讯问。\n第一百一十八条　管护时间不得超过七日，自向被管护人员宣布之日起算。因案情复杂、疑难，在七日以内无法作出留置或者解除管护决定的，经审批可以延长一日至三日。\n延长管护时间的，应当在管护期满前向被管护人员宣布延长管护时间的决定，要求其在《延长管护时间决定书》上签名、捺指印。被管护人员拒绝签名、捺指印的，调查人员应当在文书上记明。\n延长管护时间的，应当及时通知被管护人员所在单位和家属。\n第一百一十九条　对被管护人员不需要继续采取管护措施的，应当按规定报批后解除管护或者变更为责令候查措施。管护期满的，应当按规定报批后予以解除。\n解除管护措施的，调查人员应当向被管护人员宣布解除管护措施的决定，由其在《解除管护决定书》上签名、捺指印；变更为责令候查措施的，应当向被管护人员宣布变更为责令候查措施的决定，由其在《变更管护决定书》上签名、捺指印。被管护人员拒绝签名、捺指印的，调查人员应当在文书上记明。\n解除管护措施或者变更为责令候查措施的，应当及时通知被管护人员所在单位和家属、申请人。调查人员应当与交接人办理交接手续，并由其在《解除管护通知书》或者《变更管护通知书》上签名。无法通知或者有关人员拒绝签名的，调查人员应当在文书上记明', 786, '{\"level\": null, \"title\": null, \"chunk_index\": 25}', 'bge-large-zh-v1.5', '2026-09-25 17:04:49');
INSERT INTO `chunk` VALUES ('f063f09b-8a3f-42b4-91cc-6ae55c34760d', 'd9d7dc15-8041-43b8-9f75-f112fe3ae003', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 5, '第十五条　对在危险化学品安全工作中做出突出贡献的单位和个人，按照国家有关规定给予表彰、奖励。\n第二章　规划布局\n第十六条　国家对危险化学品的生产、储存实行统筹规划、合理布局。\n国务院工业和信息化主管部门以及国务院其他有关部门依照各自职责，负责危险化学品生产、储存的行业规划和布局。\n地方人民政府组织编制国土空间规划时，应当根据本地区的实际情况，按照确保安全的原则，规划适当区域（包括化工园区）专门用于危险化学品的生产、储存。\n第十七条　化工园区应当由省、自治区、直辖市人民政府或者其授权的部门认定公布并定期复核。\n省、自治区、直辖市人民政府应当合理建设化工园区，组织开展化工园区的安全风险等级评估、论证，建立并落实管控措施。\n化工园区应当对进出园区的所有危险化学品实行动态监管，对园区内企业、重点场所、重大危险源、基础设施实施风险监测预警。\n第十八条　新建、扩建危险化学品生产建设项目应当进入化工园区，与其他行业生产装置配套建设的项目和符合国家规定的其他项目除外。\n除为化工企业提供配套服务的企业外，非化工企业禁止进入化工园区。\n第十九条　化工园区应当至少每三年开展一次整体性安全风险评估，提出消除、降低、管控安全风险的对策措施并有效实施。\n当化工园区及危险化学品品种、数量、布局等发生变化，按照国家有关规定需要调整化工园区风险控制条件时，应当及时组织重新开展化工园区整体性安全风险评估，并修订相关应急预案。\n第二十条　化工园区与城市建成区、人员密集场所、重要设施、敏感目标等应当保持符合相关法律、法规规定和国家标准要求的安全距离。\n化工园区应当依照相关法律、法规规定和国家标准要求，拟定化工园区周边规划安全控制线，并报送化工园区所在地设区的市级人民政府或者其授权的部门确定后，按照程序纳入当地国土空间规划', 753, '{\"level\": null, \"title\": null, \"chunk_index\": 5}', 'bge-large-zh-v1.5', '2026-09-25 17:04:46');
INSERT INTO `chunk` VALUES ('f0d7b988-44d2-4697-bde2-3ca282ff5a20', '16cbea7e-7e36-4f31-afb5-63892345d29c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 31, '轮候冻结的，监察机关应当要求有关银行或者其他金融机构等单位在解除冻结或者作出处理前予以通知。\n监察机关接受司法机关、其他监察机关等国家机关移送的涉案财物后，该国家机关采取的冻结期限届满，监察机关续行冻结的顺位与该国家机关冻结的顺位相同。\n第一百四十一条　冻结财产应当通知权利人或者其法定代理人、委托代理人，要求其在《冻结财产告知书》上签名。冻结股票、债券、基金份额等财产，应当告知权利人或者其法定代理人、委托代理人有权申请出售。\n对于被冻结的股票、债券、基金份额等财产，权利人或者其法定代理人、委托代理人申请出售，不损害国家利益、被害人利益，不影响调查正常进行的，经审批可以在案件办结前由相关机构依法出售或者变现。对于被冻结的汇票、本票、支票即将到期的，经审批可以在案件办结前由相关机构依法出售或者变现。出售上述财产的，应当出具《许可出售冻结财产通知书》。\n出售或者变现所得价款应当继续冻结在其对应的银行账户中；没有对应的银行账户的，应当存入监察机关指定的专用账户保管，并将存款凭证送监察机关登记。监察机关应当及时向权利人或者其法定代理人、委托代理人出具《出售冻结财产通知书》，并要求其签名。拒绝签名的，调查人员应当在文书上记明。\n第一百四十二条　对于冻结的财产，应当及时核查。经查明与案件无关的，经审批，应当在查明后三日以内将《解除冻结财产通知书》送交有关单位执行。解除情况应当告知被冻结财产的权利人或者其法定代理人、委托代理人。\n第十一节　搜　　查\n第一百四十三条　监察机关调查职务犯罪案件，为了收集犯罪证据、查获被调查人，按规定报批后，可以依法对被调查人以及可能隐藏被调查人或者犯罪证据的人的身体、物品、住处、工作地点和其他有关地方进行搜查。\n第一百四十四条　搜查应当在调查人员主持下进行，调查人员不得少于二人。搜查女性的身体，由女性工作人员进行', 776, '{\"level\": null, \"title\": null, \"chunk_index\": 31}', 'bge-large-zh-v1.5', '2026-09-25 17:04:49');
INSERT INTO `chunk` VALUES ('f14a8cb7-5167-42aa-995d-ca1e4a0b8832', 'b25ce095-dfba-4403-acf8-c58eb456ca4c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 131, '第一千一百四十二条　遗嘱人可以撤回、变更自己所立的遗嘱。\n立遗嘱后，遗嘱人实施与遗嘱内容相反的民事法律行为的，视为对遗嘱相关内容的撤回。\n立有数份遗嘱，内容相抵触的，以最后的遗嘱为准。\n第一千一百四十三条　无民事行为能力人或者限制民事行为能力人所立的遗嘱无效。\n遗嘱必须表示遗嘱人的真实意思，受欺诈、胁迫所立的遗嘱无效。\n伪造的遗嘱无效。\n遗嘱被篡改的，篡改的内容无效。\n第一千一百四十四条　遗嘱继承或者遗赠附有义务的，继承人或者受遗赠人应当履行义务。没有正当理由不履行义务的，经利害关系人或者有关组织请求，人民法院可以取消其接受附义务部分遗产的权利。\n第四章　遗产的处理\n第一千一百四十五条　继承开始后，遗嘱执行人为遗产管理人；没有遗嘱执行人的，继承人应当及时推选遗产管理人；继承人未推选的，由继承人共同担任遗产管理人；没有继承人或者继承人均放弃继承的，由被继承人生前住所地的民政部门或者村民委员会担任遗产管理人。\n第一千一百四十六条　对遗产管理人的确定有争议的，利害关系人可以向人民法院申请指定遗产管理人。\n第一千一百四十七条　遗产管理人应当履行下列职责：\n（一）清理遗产并制作遗产清单；\n（二）向继承人报告遗产情况；\n（三）采取必要措施防止遗产毁损、灭失；\n（四）处理被继承人的债权债务；\n（五）按照遗嘱或者依照法律规定分割遗产；\n（六）实施与管理遗产有关的其他必要行为。\n第一千一百四十八条　遗产管理人应当依法履行职责，因故意或者重大过失造成继承人、受遗赠人、债权人损害的，应当承担民事责任。\n第一千一百四十九条　遗产管理人可以依照法律规定或者按照约定获得报酬。\n第一千一百五十条　继承开始后，知道被继承人死亡的继承人应当及时通知其他继承人和遗嘱执行人。继承人中无人知道被继承人死亡或者知道被继承人死亡而不能通知的，由被继承人生前所在单位或者住所地的居民委员会、村民委员会负责通知', 794, '{\"level\": null, \"title\": null, \"chunk_index\": 131}', 'bge-large-zh-v1.5', '2026-09-25 17:05:01');
INSERT INTO `chunk` VALUES ('f1976e1e-53e5-4845-b816-e4572ba41f97', 'b25ce095-dfba-4403-acf8-c58eb456ca4c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 120, '第二章　结　　婚\n第一千零四十六条　结婚应当男女双方完全自愿，禁止任何一方对另一方加以强迫，禁止任何组织或者个人加以干涉。\n第一千零四十七条　结婚年龄，男不得早于二十二周岁，女不得早于二十周岁。\n第一千零四十八条　直系血亲或者三代以内的旁系血亲禁止结婚。\n第一千零四十九条　要求结婚的男女双方应当亲自到婚姻登记机关申请结婚登记。符合本法规定的，予以登记，发给结婚证。完成结婚登记，即确立婚姻关系。未办理结婚登记的，应当补办登记。\n第一千零五十条　登记结婚后，按照男女双方约定，女方可以成为男方家庭的成员，男方可以成为女方家庭的成员。\n第一千零五十一条　有下列情形之一的，婚姻无效：\n（一）重婚；\n（二）有禁止结婚的亲属关系；\n（三）未到法定婚龄。\n第一千零五十二条　因胁迫结婚的，受胁迫的一方可以向人民法院请求撤销婚姻。\n请求撤销婚姻的，应当自胁迫行为终止之日起一年内提出。\n被非法限制人身自由的当事人请求撤销婚姻的，应当自恢复人身自由之日起一年内提出。\n第一千零五十三条　一方患有重大疾病的，应当在结婚登记前如实告知另一方；不如实告知的，另一方可以向人民法院请求撤销婚姻。\n请求撤销婚姻的，应当自知道或者应当知道撤销事由之日起一年内提出。\n第一千零五十四条　无效的或者被撤销的婚姻自始没有法律约束力，当事人不具有夫妻的权利和义务。同居期间所得的财产，由当事人协议处理；协议不成的，由人民法院根据照顾无过错方的原则判决。对重婚导致的无效婚姻的财产处理，不得侵害合法婚姻当事人的财产权益。当事人所生的子女，适用本法关于父母子女的规定。\n婚姻无效或者被撤销的，无过错方有权请求损害赔偿。\n第三章　家庭关系\n第一节　夫妻关系\n第一千零五十五条　夫妻在婚姻家庭中地位平等。\n第一千零五十六条　夫妻双方都有各自使用自己姓名的权利', 759, '{\"level\": null, \"title\": null, \"chunk_index\": 120}', 'bge-large-zh-v1.5', '2026-09-25 17:05:01');
INSERT INTO `chunk` VALUES ('f336b5ed-6d66-41fb-95fd-cd294a045253', 'b25ce095-dfba-4403-acf8-c58eb456ca4c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 113, '受害人的停止侵害、排除妨碍、消除危险、消除影响、恢复名誉、赔礼道歉请求权，不适用诉讼时效的规定。\n第九百九十六条　因当事人一方的违约行为，损害对方人格权并造成严重精神损害，受损害方选择请求其承担违约责任的，不影响受损害方请求精神损害赔偿。\n第九百九十七条　民事主体有证据证明行为人正在实施或者即将实施侵害其人格权的违法行为，不及时制止将使其合法权益受到难以弥补的损害的，有权依法向人民法院申请采取责令行为人停止有关行为的措施。\n第九百九十八条　认定行为人承担侵害除生命权、身体权和健康权外的人格权的民事责任，应当考虑行为人和受害人的职业、影响范围、过错程度，以及行为的目的、方式、后果等因素。\n第九百九十九条　为公共利益实施新闻报道、舆论监督等行为的，可以合理使用民事主体的姓名、名称、肖像、个人信息等；使用不合理侵害民事主体人格权的，应当依法承担民事责任。\n第一千条　行为人因侵害人格权承担消除影响、恢复名誉、赔礼道歉等民事责任的，应当与行为的具体方式和造成的影响范围相当。\n行为人拒不承担前款规定的民事责任的，人民法院可以采取在报刊、网络等媒体上发布公告或者公布生效裁判文书等方式执行，产生的费用由行为人负担。\n第一千零一条　对自然人因婚姻家庭关系等产生的身份权利的保护，适用本法第一编、第五编和其他法律的相关规定；没有规定的，可以根据其性质参照适用本编人格权保护的有关规定。\n第二章　生命权、身体权和健康权\n第一千零二条　自然人享有生命权。自然人的生命安全和生命尊严受法律保护。任何组织或者个人不得侵害他人的生命权。\n第一千零三条　自然人享有身体权。自然人的身体完整和行动自由受法律保护。任何组织或者个人不得侵害他人的身体权。\n第一千零四条　自然人享有健康权。自然人的身心健康受法律保护。任何组织或者个人不得侵害他人的健康权', 765, '{\"level\": null, \"title\": null, \"chunk_index\": 113}', 'bge-large-zh-v1.5', '2026-09-25 17:05:01');
INSERT INTO `chunk` VALUES ('f3554c38-fcca-407f-a5f1-46cb3cbb3b93', 'b25ce095-dfba-4403-acf8-c58eb456ca4c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 66, '第五百七十六条　债权和债务同归于一人的，债权债务终止，但是损害第三人利益的除外。\n第八章　违约责任\n第五百七十七条　当事人一方不履行合同义务或者履行合同义务不符合约定的，应当承担继续履行、采取补救措施或者赔偿损失等违约责任。\n第五百七十八条　当事人一方明确表示或者以自己的行为表明不履行合同义务的，对方可以在履行期限届满前请求其承担违约责任。\n第五百七十九条　当事人一方未支付价款、报酬、租金、利息，或者不履行其他金钱债务的，对方可以请求其支付。\n第五百八十条　当事人一方不履行非金钱债务或者履行非金钱债务不符合约定的，对方可以请求履行，但是有下列情形之一的除外：\n（一）法律上或者事实上不能履行；\n（二）债务的标的不适于强制履行或者履行费用过高；\n（三）债权人在合理期限内未请求履行。\n有前款规定的除外情形之一，致使不能实现合同目的的，人民法院或者仲裁机构可以根据当事人的请求终止合同权利义务关系，但是不影响违约责任的承担。\n第五百八十一条　当事人一方不履行债务或者履行债务不符合约定，根据债务的性质不得强制履行的，对方可以请求其负担由第三人替代履行的费用。\n第五百八十二条　履行不符合约定的，应当按照当事人的约定承担违约责任。对违约责任没有约定或者约定不明确，依据本法第五百一十条的规定仍不能确定的，受损害方根据标的的性质以及损失的大小，可以合理选择请求对方承担修理、重作、更换、退货、减少价款或者报酬等违约责任。\n第五百八十三条　当事人一方不履行合同义务或者履行合同义务不符合约定的，在履行义务或者采取补救措施后，对方还有其他损失的，应当赔偿损失。\n第五百八十四条　当事人一方不履行合同义务或者履行合同义务不符合约定，造成对方损失的，损失赔偿额应当相当于因违约所造成的损失，包括合同履行后可以获得的利益；但是，不得超过违约一方订立合同时预见到或者应当预见到的因违约可能造成的损失', 792, '{\"level\": null, \"title\": null, \"chunk_index\": 66}', 'bge-large-zh-v1.5', '2026-09-25 17:05:01');
INSERT INTO `chunk` VALUES ('f37c6ff9-a3ea-4c9f-b62e-18ed573cbe67', 'b25ce095-dfba-4403-acf8-c58eb456ca4c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 20, '第一百七十条　执行法人或者非法人组织工作任务的人员，就其职权范围内的事项，以法人或者非法人组织的名义实施的民事法律行为，对法人或者非法人组织发生效力。\n法人或者非法人组织对执行其工作任务的人员职权范围的限制，不得对抗善意相对人。\n第一百七十一条　行为人没有代理权、超越代理权或者代理权终止后，仍然实施代理行为，未经被代理人追认的，对被代理人不发生效力。\n相对人可以催告被代理人自收到通知之日起三十日内予以追认。被代理人未作表示的，视为拒绝追认。行为人实施的行为被追认前，善意相对人有撤销的权利。撤销应当以通知的方式作出。\n行为人实施的行为未被追认的，善意相对人有权请求行为人履行债务或者就其受到的损害请求行为人赔偿。但是，赔偿的范围不得超过被代理人追认时相对人所能获得的利益。\n相对人知道或者应当知道行为人无权代理的，相对人和行为人按照各自的过错承担责任。\n第一百七十二条　行为人没有代理权、超越代理权或者代理权终止后，仍然实施代理行为，相对人有理由相信行为人有代理权的，代理行为有效。\n第三节　代理终止\n第一百七十三条　有下列情形之一的，委托代理终止：\n（一）代理期限届满或者代理事务完成；\n（二）被代理人取消委托或者代理人辞去委托；\n（三）代理人丧失民事行为能力；\n（四）代理人或者被代理人死亡；\n（五）作为代理人或者被代理人的法人、非法人组织终止。\n第一百七十四条　被代理人死亡后，有下列情形之一的，委托代理人实施的代理行为有效：\n（一）代理人不知道且不应当知道被代理人死亡；\n（二）被代理人的继承人予以承认；\n（三）授权中明确代理权在代理事务完成时终止；\n（四）被代理人死亡前已经实施，为了被代理人的继承人的利益继续代理。\n作为被代理人的法人、非法人组织终止的，参照适用前款规定', 743, '{\"level\": null, \"title\": null, \"chunk_index\": 20}', 'bge-large-zh-v1.5', '2026-09-25 17:05:01');
INSERT INTO `chunk` VALUES ('f4225050-2e6a-4033-9685-63b27b3d48de', 'b25ce095-dfba-4403-acf8-c58eb456ca4c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 45, '债权转让的，担保该债权的抵押权一并转让，但是法律另有规定或者当事人另有约定的除外。\n第四百零八条　抵押人的行为足以使抵押财产价值减少的，抵押权人有权请求抵押人停止其行为；抵押财产价值减少的，抵押权人有权请求恢复抵押财产的价值，或者提供与减少的价值相应的担保。抵押人不恢复抵押财产的价值，也不提供担保的，抵押权人有权请求债务人提前清偿债务。\n第四百零九条　抵押权人可以放弃抵押权或者抵押权的顺位。抵押权人与抵押人可以协议变更抵押权顺位以及被担保的债权数额等内容。但是，抵押权的变更未经其他抵押权人书面同意的，不得对其他抵押权人产生不利影响。\n债务人以自己的财产设定抵押，抵押权人放弃该抵押权、抵押权顺位或者变更抵押权的，其他担保人在抵押权人丧失优先受偿权益的范围内免除担保责任，但是其他担保人承诺仍然提供担保的除外。\n第四百一十条　债务人不履行到期债务或者发生当事人约定的实现抵押权的情形，抵押权人可以与抵押人协议以抵押财产折价或者以拍卖、变卖该抵押财产所得的价款优先受偿。协议损害其他债权人利益的，其他债权人可以请求人民法院撤销该协议。\n抵押权人与抵押人未就抵押权实现方式达成协议的，抵押权人可以请求人民法院拍卖、变卖抵押财产。\n抵押财产折价或者变卖的，应当参照市场价格。\n第四百一十一条　依据本法第三百九十六条规定设定抵押的，抵押财产自下列情形之一发生时确定：\n（一）债务履行期限届满，债权未实现；\n（二）抵押人被宣告破产或者解散；\n（三）当事人约定的实现抵押权的情形；\n（四）严重影响债权实现的其他情形。\n第四百一十二条　债务人不履行到期债务或者发生当事人约定的实现抵押权的情形，致使抵押财产被人民法院依法扣押的，自扣押之日起，抵押权人有权收取该抵押财产的天然孳息或者法定孳息，但是抵押权人未通知应当清偿法定孳息义务人的除外。\n前款规定的孳息应当先充抵收取孳息的费用', 785, '{\"level\": null, \"title\": null, \"chunk_index\": 45}', 'bge-large-zh-v1.5', '2026-09-25 17:05:01');
INSERT INTO `chunk` VALUES ('f4558a84-3374-4850-b518-7c7b1537cd4c', '821ce1fd-178d-4a7e-ab92-3deff1488ce2', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 40, '单位犯前款罪的，对单位判处罚金，并对其直接负责的主管人员和其他直接责任人员，依照前款的规定处罚。\n第一百九十条　公司、企业或者其他单位，违反国家规定，擅自将外汇存放境外，或者将境内的外汇非法转移到境外，数额较大的，对单位判处逃汇数额百分之五以上百分之三十以下罚金，并对其直接负责的主管人员和其他直接责任人员，处五年以下有期徒刑或者拘役；数额巨大或者有其他严重情节的，对单位判处逃汇数额百分之五以上百分之三十以下罚金，并对其直接负责的主管人员和其他直接责任人员，处五年以上有期徒刑。\n第一百九十一条　为掩饰、隐瞒毒品犯罪、黑社会性质的组织犯罪、恐怖活动犯罪、走私犯罪、贪污贿赂犯罪、破坏金融管理秩序犯罪、金融诈骗犯罪的所得及其产生的收益的来源和性质，有下列行为之一的，没收实施以上犯罪的所得及其产生的收益，处五年以下有期徒刑或者拘役，并处或者单处罚金；情节严重的，处五年以上十年以下有期徒刑，并处罚金：\n（一）提供资金帐户的；\n（二）将财产转换为现金、金融票据、有价证券的；\n（三）通过转帐或者其他支付结算方式转移资金的；\n（四）跨境转移资产的；\n（五）以其他方法掩饰、隐瞒犯罪所得及其收益的来源和性质的。\n单位犯前款罪的，对单位判处罚金，并对其直接负责的主管人员和其他直接责任人员，依照前款的规定处罚。\n第五节　金融诈骗罪\n第一百九十二条　以非法占有为目的，使用诈骗方法非法集资，数额较大的，处三年以上七年以下有期徒刑，并处罚金；数额巨大或者有其他严重情节的，处七年以上有期徒刑或者无期徒刑，并处罚金或者没收财产。\n单位犯前款罪的，对单位判处罚金，并对其直接负责的主管人员和其他直接责任人员，依照前款的规定处罚', 705, '{\"level\": null, \"title\": null, \"chunk_index\": 40}', 'bge-large-zh-v1.5', '2026-09-25 17:04:56');
INSERT INTO `chunk` VALUES ('f480b1d6-87cb-4b75-beb5-2958f46b5dd2', '821ce1fd-178d-4a7e-ab92-3deff1488ce2', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 73, '犯前两款罪，对被运送人有杀害、伤害、强奸、拐卖等犯罪行为，或者对检查人员有杀害、伤害等犯罪行为的，依照数罪并罚的规定处罚。\n第三百二十二条　违反国（边）境管理法规，偷越国（边）境，情节严重的，处一年以下有期徒刑、拘役或者管制，并处罚金；为参加恐怖活动组织、接受恐怖活动培训或者实施恐怖活动，偷越国（边）境的，处一年以上三年以下有期徒刑，并处罚金。\n第三百二十三条　故意破坏国家边境的界碑、界桩或者永久性测量标志的，处三年以下有期徒刑或者拘役。\n第四节　妨害文物管理罪\n第三百二十四条　故意损毁国家保护的珍贵文物或者被确定为全国重点文物保护单位、省级文物保护单位的文物的，处三年以下有期徒刑或者拘役，并处或者单处罚金；情节严重的，处三年以上十年以下有期徒刑，并处罚金。\n故意损毁国家保护的名胜古迹，情节严重的，处五年以下有期徒刑或者拘役，并处或者单处罚金。\n过失损毁国家保护的珍贵文物或者被确定为全国重点文物保护单位、省级文物保护单位的文物，造成严重后果的，处三年以下有期徒刑或者拘役。\n第三百二十五条　违反文物保护法规，将收藏的国家禁止出口的珍贵文物私自出售或者私自赠送给外国人的，处五年以下有期徒刑或者拘役，可以并处罚金。\n单位犯前款罪的，对单位判处罚金，并对其直接负责的主管人员和其他直接责任人员，依照前款的规定处罚。\n第三百二十六条　以牟利为目的，倒卖国家禁止经营的文物，情节严重的，处五年以下有期徒刑或者拘役，并处罚金；情节特别严重的，处五年以上十年以下有期徒刑，并处罚金。\n单位犯前款罪的，对单位判处罚金，并对其直接负责的主管人员和其他直接责任人员，依照前款的规定处罚。\n第三百二十七条　违反文物保护法规，国有博物馆、图书馆等单位将国家保护的文物藏品出售或者私自送给非国有单位或者个人的，对单位判处罚金，并对其直接负责的主管人员和其他直接责任人员，处三年以下有期徒刑或者拘役', 792, '{\"level\": null, \"title\": null, \"chunk_index\": 73}', 'bge-large-zh-v1.5', '2026-09-25 17:04:56');
INSERT INTO `chunk` VALUES ('f4a5717d-55c4-411a-93bb-de350e69aa2a', '821ce1fd-178d-4a7e-ab92-3deff1488ce2', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 75, '甲类传染病的范围，依照《中华人民共和国传染病防治法》和国务院有关规定确定。\n第三百三十一条　从事实验、保藏、携带、运输传染病菌种、毒种的人员，违反国务院卫生行政部门的有关规定，造成传染病菌种、毒种扩散，后果严重的，处三年以下有期徒刑或者拘役；后果特别严重的，处三年以上七年以下有期徒刑。\n第三百三十二条　违反国境卫生检疫规定，引起检疫传染病传播或者有传播严重危险的，处三年以下有期徒刑或者拘役，并处或者单处罚金。\n单位犯前款罪的，对单位判处罚金，并对其直接负责的主管人员和其他直接责任人员，依照前款的规定处罚。\n第三百三十三条　非法组织他人出卖血液的，处五年以下有期徒刑，并处罚金；以暴力、威胁方法强迫他人出卖血液的，处五年以上十年以下有期徒刑，并处罚金。\n有前款行为，对他人造成伤害的，依照本法第二百三十四条的规定定罪处罚。\n第三百三十四条　非法采集、供应血液或者制作、供应血液制品，不符合国家规定的标准，足以危害人体健康的，处五年以下有期徒刑或者拘役，并处罚金；对人体健康造成严重危害的，处五年以上十年以下有期徒刑，并处罚金；造成特别严重后果的，处十年以上有期徒刑或者无期徒刑，并处罚金或者没收财产。\n经国家主管部门批准采集、供应血液或者制作、供应血液制品的部门，不依照规定进行检测或者违背其他操作规定，造成危害他人身体健康后果的，对单位判处罚金，并对其直接负责的主管人员和其他直接责任人员，处五年以下有期徒刑或者拘役。\n第三百三十四条之一　违反国家有关规定，非法采集我国人类遗传资源或者非法运送、邮寄、携带我国人类遗传资源材料出境，危害公众健康或者社会公共利益，情节严重的，处三年以下有期徒刑、拘役或者管制，并处或者单处罚金；情节特别严重的，处三年以上七年以下有期徒刑，并处罚金。\n第三百三十五条　医务人员由于严重不负责任，造成就诊人死亡或者严重损害就诊人身体健康的，处三年以下有期徒刑或者拘役', 800, '{\"level\": null, \"title\": null, \"chunk_index\": 75}', 'bge-large-zh-v1.5', '2026-09-25 17:04:56');
INSERT INTO `chunk` VALUES ('f5abf309-9db4-47e8-88bf-3bc732833572', 'b25ce095-dfba-4403-acf8-c58eb456ca4c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 89, '第七百九十一条　发包人可以与总承包人订立建设工程合同，也可以分别与勘察人、设计人、施工人订立勘察、设计、施工承包合同。发包人不得将应当由一个承包人完成的建设工程支解成若干部分发包给数个承包人。\n总承包人或者勘察、设计、施工承包人经发包人同意，可以将自己承包的部分工作交由第三人完成。第三人就其完成的工作成果与总承包人或者勘察、设计、施工承包人向发包人承担连带责任。承包人不得将其承包的全部建设工程转包给第三人或者将其承包的全部建设工程支解以后以分包的名义分别转包给第三人。\n禁止承包人将工程分包给不具备相应资质条件的单位。禁止分包单位将其承包的工程再分包。建设工程主体结构的施工必须由承包人自行完成。\n第七百九十二条　国家重大建设工程合同，应当按照国家规定的程序和国家批准的投资计划、可行性研究报告等文件订立。\n第七百九十三条　建设工程施工合同无效，但是建设工程经验收合格的，可以参照合同关于工程价款的约定折价补偿承包人。\n建设工程施工合同无效，且建设工程经验收不合格的，按照以下情形处理：\n（一）修复后的建设工程经验收合格的，发包人可以请求承包人承担修复费用；\n（二）修复后的建设工程经验收不合格的，承包人无权请求参照合同关于工程价款的约定折价补偿。\n发包人对因建设工程不合格造成的损失有过错的，应当承担相应的责任。\n第七百九十四条　勘察、设计合同的内容一般包括提交有关基础资料和概预算等文件的期限、质量要求、费用以及其他协作条件等条款。\n第七百九十五条　施工合同的内容一般包括工程范围、建设工期、中间交工工程的开工和竣工时间、工程质量、工程造价、技术资料交付时间、材料和设备供应责任、拨款和结算、竣工验收、质量保修范围和质量保证期、相互协作等条款。\n第七百九十六条　建设工程实行监理的，发包人应当与监理人采用书面形式订立委托监理合同', 768, '{\"level\": null, \"title\": null, \"chunk_index\": 89}', 'bge-large-zh-v1.5', '2026-09-25 17:05:01');
INSERT INTO `chunk` VALUES ('f73cf3ee-0218-4074-884c-49912dbc8682', '22a2c356-7a68-4455-b657-333e3dba1e1a', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 3, '第一章　总　　纲\n第一条　中华人民共和国是工人阶级领导的、以工农联盟为基础的人民民主专政的社会主义国家。\n社会主义制度是中华人民共和国的根本制度。中国共产党领导是中国特色社会主义最本质的特征。禁止任何组织或者个人破坏社会主义制度。\n第二条　中华人民共和国的一切权力属于人民。\n人民行使国家权力的机关是全国人民代表大会和地方各级人民代表大会。\n人民依照法律规定，通过各种途径和形式，管理国家事务，管理经济和文化事业，管理社会事务。\n第三条　中华人民共和国的国家机构实行民主集中制的原则。\n全国人民代表大会和地方各级人民代表大会都由民主选举产生，对人民负责，受人民监督。\n国家行政机关、监察机关、审判机关、检察机关都由人民代表大会产生，对它负责，受它监督。\n中央和地方的国家机构职权的划分，遵循在中央的统一领导下，充分发挥地方的主动性、积极性的原则。\n第四条　中华人民共和国各民族一律平等。国家保障各少数民族的合法的权利和利益，维护和发展各民族的平等团结互助和谐关系。禁止对任何民族的歧视和压迫，禁止破坏民族团结和制造民族分裂的行为。\n国家根据各少数民族的特点和需要，帮助各少数民族地区加速经济和文化的发展。\n各少数民族聚居的地方实行区域自治，设立自治机关，行使自治权。各民族自治地方都是中华人民共和国不可分离的部分。\n各民族都有使用和发展自己的语言文字的自由，都有保持或者改革自己的风俗习惯的自由。\n第五条　中华人民共和国实行依法治国，建设社会主义法治国家。\n国家维护社会主义法制的统一和尊严。\n一切法律、行政法规和地方性法规都不得同宪法相抵触。\n一切国家机关和武装力量、各政党和各社会团体、各企业事业组织都必须遵守宪法和法律。一切违反宪法和法律的行为，必须予以追究。\n任何组织或者个人都不得有超越宪法和法律的特权', 756, '{\"level\": null, \"title\": null, \"chunk_index\": 3}', 'bge-large-zh-v1.5', '2026-09-25 17:04:28');
INSERT INTO `chunk` VALUES ('f7a4856a-52fd-434f-a522-dc83ede21cff', '22a2c356-7a68-4455-b657-333e3dba1e1a', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 21, '第一百零四条　县级以上的地方各级人民代表大会常务委员会讨论、决定本行政区域内各方面工作的重大事项；监督本级人民政府、监察委员会、人民法院和人民检察院的工作；撤销本级人民政府的不适当的决定和命令；撤销下一级人民代表大会的不适当的决议；依照法律规定的权限决定国家机关工作人员的任免；在本级人民代表大会闭会期间，罢免和补选上一级人民代表大会的个别代表。\n第一百零五条　地方各级人民政府是地方各级国家权力机关的执行机关，是地方各级国家行政机关。\n地方各级人民政府实行省长、市长、县长、区长、乡长、镇长负责制。\n第一百零六条　地方各级人民政府每届任期同本级人民代表大会每届任期相同。\n第一百零七条　县级以上地方各级人民政府依照法律规定的权限，管理本行政区域内的经济、教育、科学、文化、卫生、体育事业、城乡建设事业和财政、民政、公安、民族事务、司法行政、计划生育等行政工作，发布决定和命令，任免、培训、考核和奖惩行政工作人员。\n乡、民族乡、镇的人民政府执行本级人民代表大会的决议和上级国家行政机关的决定和命令，管理本行政区域内的行政工作。\n省、直辖市的人民政府决定乡、民族乡、镇的建置和区域划分。\n第一百零八条　县级以上的地方各级人民政府领导所属各工作部门和下级人民政府的工作，有权改变或者撤销所属各工作部门和下级人民政府的不适当的决定。\n第一百零九条　县级以上的地方各级人民政府设立审计机关。地方各级审计机关依照法律规定独立行使审计监督权，对本级人民政府和上一级审计机关负责。\n第一百一十条　地方各级人民政府对本级人民代表大会负责并报告工作。县级以上的地方各级人民政府在本级人民代表大会闭会期间，对本级人民代表大会常务委员会负责并报告工作。\n地方各级人民政府对上一级国家行政机关负责并报告工作。全国地方各级人民政府都是国务院统一领导下的国家行政机关，都服从国务院', 776, '{\"level\": null, \"title\": null, \"chunk_index\": 21}', 'bge-large-zh-v1.5', '2026-09-25 17:04:29');
INSERT INTO `chunk` VALUES ('f8238597-9e4f-43fe-95e6-728d06e0e836', 'b25ce095-dfba-4403-acf8-c58eb456ca4c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 139, '第一千二百一十一条　以挂靠形式从事道路运输经营活动的机动车，发生交通事故造成损害，属于该机动车一方责任的，由挂靠人和被挂靠人承担连带责任。\n第一千二百一十二条　未经允许驾驶他人机动车，发生交通事故造成损害，属于该机动车一方责任的，由机动车使用人承担赔偿责任；机动车所有人、管理人对损害的发生有过错的，承担相应的赔偿责任，但是本章另有规定的除外。\n第一千二百一十三条　机动车发生交通事故造成损害，属于该机动车一方责任的，先由承保机动车强制保险的保险人在强制保险责任限额范围内予以赔偿；不足部分，由承保机动车商业保险的保险人按照保险合同的约定予以赔偿；仍然不足或者没有投保机动车商业保险的，由侵权人赔偿。\n第一千二百一十四条　以买卖或者其他方式转让拼装或者已经达到报废标准的机动车，发生交通事故造成损害的，由转让人和受让人承担连带责任。\n第一千二百一十五条　盗窃、抢劫或者抢夺的机动车发生交通事故造成损害的，由盗窃人、抢劫人或者抢夺人承担赔偿责任。盗窃人、抢劫人或者抢夺人与机动车使用人不是同一人，发生交通事故造成损害，属于该机动车一方责任的，由盗窃人、抢劫人或者抢夺人与机动车使用人承担连带责任。\n保险人在机动车强制保险责任限额范围内垫付抢救费用的，有权向交通事故责任人追偿。\n第一千二百一十六条　机动车驾驶人发生交通事故后逃逸，该机动车参加强制保险的，由保险人在机动车强制保险责任限额范围内予以赔偿；机动车不明、该机动车未参加强制保险或者抢救费用超过机动车强制保险责任限额，需要支付被侵权人人身伤亡的抢救、丧葬等费用的，由道路交通事故社会救助基金垫付。道路交通事故社会救助基金垫付后，其管理机构有权向交通事故责任人追偿。\n第一千二百一十七条　非营运机动车发生交通事故造成无偿搭乘人损害，属于该机动车一方责任的，应当减轻其赔偿责任，但是机动车使用人有故意或者重大过失的除外', 785, '{\"level\": null, \"title\": null, \"chunk_index\": 139}', 'bge-large-zh-v1.5', '2026-09-25 17:05:01');
INSERT INTO `chunk` VALUES ('f84edcba-7da2-4ad0-a39c-e461144c9bfa', '16cbea7e-7e36-4f31-afb5-63892345d29c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 44, '案件监督管理部门统一接收巡视巡察机构和审计机关、执法机关、司法机关等其他机关移送的职务违法和职务犯罪问题线索，按程序移交本机关监督检查部门或者相关部门办理。\n监督检查部门、调查部门在工作中发现的相关问题线索，属于本部门受理范围的，应当报送案件监督管理部门备案；属于本机关其他部门受理范围的，经审批后移交案件监督管理部门分办。\n第二百零三条　案件监督管理部门应当对问题线索实行集中管理、动态更新，定期汇总、核对问题线索及处置情况，向监察机关主要负责人报告，并向相关部门通报。\n问题线索承办部门应当指定专人负责管理线索，逐件编号登记、建立管理台账。线索管理处置各环节应当由经手人员签名，全程登记备查，及时与案件监督管理部门核对。\n第二百零四条　监督检查部门应当结合问题线索所涉及地区、部门、单位总体情况进行综合分析，提出处置意见并制定处置方案，经审批按照适当了解、谈话、函询、初步核实、暂存待查、予以了结等方式进行处置，或者按照职责移送调查部门处置。\n第二百零五条　采取适当了解方式处置问题线索，应当按规定报批后，依法依规向有关单位和个人了解情况，验证问题的真实性，不得采取限制人身、财产权利的措施，不得与被反映人接触。\n承办部门应当根据适当了解的情况，提出谈话、函询、初步核实、拟立案调查、予以了结、暂存待查，或者移送有关部门、机关处理等建议，按程序报批后办理。\n第二百零六条　采取谈话方式处置问题线索的，按照本条例第七十八条、第七十九条规定办理。\n函询应当以监察机关办公厅（室）名义发函给被反映人，并抄送其所在单位和派驻监察机构主要负责人。被函询人应当在收到函件后十五个工作日以内写出说明材料，由其所在单位主要负责人签署意见后发函回复。被函询人为所在单位主要负责人的，或者被函询人所作说明涉及所在单位主要负责人的，应当直接发函回复监察机关。\n被函询人已经退休的，按照第二款规定程序办理', 792, '{\"level\": null, \"title\": null, \"chunk_index\": 44}', 'bge-large-zh-v1.5', '2026-09-25 17:04:49');
INSERT INTO `chunk` VALUES ('f9195af1-b4c1-4a7c-832a-4001ab8a7724', '16cbea7e-7e36-4f31-afb5-63892345d29c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 71, '解除禁闭措施的，调查人员应当向被禁闭人员宣布解除禁闭措施的决定，由其在《解除禁闭决定书》上签名、捺指印；变更为责令候查措施的，应当向被禁闭人员宣布变更为责令候查措施的决定，由其在《变更禁闭决定书》上签名、捺指印。被禁闭人员拒绝签名、捺指印的，调查人员应当在文书上记明。\n解除禁闭措施或者变更为责令候查措施的，应当及时通知被禁闭人员所在单位和家属、申请人。调查人员应当与交接人办理交接手续，并由其在《解除禁闭通知书》或者《变更禁闭通知书》上签名。无法通知或者有关人员拒绝签名的，调查人员应当在文书上记明。不得因办理交接手续延迟解除或者变更禁闭措施。\n在禁闭期满前，对被禁闭人员采取管护、留置措施的，按照本条例关于采取管护、留置措施的规定执行。\n第三百零八条　被调查人及其近亲属、利害关系人认为监察机关及其工作人员存在监察法第六十九条第一款规定的有关情形，向监察机关提出申诉的，由监察机关案件监督管理部门依法受理。监察机关应当自受理申诉之日起一个月以内作出处理决定。\n前款规定的利害关系人，是指与有关涉案财产存在利害关系的自然人、法人或者其他组织。\n第三百零九条　监察机关案件监督管理部门受理申诉后，应当组织成立核查组，对申诉反映的问题进行核实。根据工作需要，核查组可以调阅相关措施文书等材料，听取申诉人意见和承办部门工作人员的情况说明。案件监督管理部门应当集体研究，提出办理意见，经审批作出决定。\n第三百一十条　监察机关应当自申诉处理决定作出之日起七日以内，向申诉人送达申诉处理决定书，要求其在申诉处理决定书上签名。申诉人拒绝签名的，工作人员应当在文书上记明。\n第三百一十一条　申诉人对申诉处理决定不服的，可以自收到申诉处理决定书之日起一个月以内向上一级监察机关申请复查。上一级监察机关应当进行核实，并自收到复查申请之日起二个月以内作出处理决定', 771, '{\"level\": null, \"title\": null, \"chunk_index\": 71}', 'bge-large-zh-v1.5', '2026-09-25 17:04:49');
INSERT INTO `chunk` VALUES ('fbc5af5b-9187-4d6d-a8b9-28396edc5db0', 'b25ce095-dfba-4403-acf8-c58eb456ca4c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 51, '第四百六十条　不动产或者动产被占有人占有的，权利人可以请求返还原物及其孳息；但是，应当支付善意占有人因维护该不动产或者动产支出的必要费用。\n第四百六十一条　占有的不动产或者动产毁损、灭失，该不动产或者动产的权利人请求赔偿的，占有人应当将因毁损、灭失取得的保险金、赔偿金或者补偿金等返还给权利人；权利人的损害未得到足够弥补的，恶意占有人还应当赔偿损失。\n第四百六十二条　占有的不动产或者动产被侵占的，占有人有权请求返还原物；对妨害占有的行为，占有人有权请求排除妨害或者消除危险；因侵占或者妨害造成损害的，占有人有权依法请求损害赔偿。\n占有人返还原物的请求权，自侵占发生之日起一年内未行使的，该请求权消灭。\n第三编　合　　同\n第一分编　通　　则\n第一章　一般规定\n第四百六十三条　本编调整因合同产生的民事关系。\n第四百六十四条　合同是民事主体之间设立、变更、终止民事法律关系的协议。\n婚姻、收养、监护等有关身份关系的协议，适用有关该身份关系的法律规定；没有规定的，可以根据其性质参照适用本编规定。\n第四百六十五条　依法成立的合同，受法律保护。\n依法成立的合同，仅对当事人具有法律约束力，但是法律另有规定的除外。\n第四百六十六条　当事人对合同条款的理解有争议的，应当依据本法第一百四十二条第一款的规定，确定争议条款的含义。\n合同文本采用两种以上文字订立并约定具有同等效力的，对各文本使用的词句推定具有相同含义。各文本使用的词句不一致的，应当根据合同的相关条款、性质、目的以及诚信原则等予以解释。\n第四百六十七条　本法或者其他法律没有明文规定的合同，适用本编通则的规定，并可以参照适用本编或者其他法律最相类似合同的规定。\n在中华人民共和国境内履行的中外合资经营企业合同、中外合作经营企业合同、中外合作勘探开发自然资源合同，适用中华人民共和国法律', 768, '{\"level\": null, \"title\": null, \"chunk_index\": 51}', 'bge-large-zh-v1.5', '2026-09-25 17:05:01');
INSERT INTO `chunk` VALUES ('fc134d1b-172f-4061-ade4-2b9485b2dbee', 'b25ce095-dfba-4403-acf8-c58eb456ca4c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 59, '第五百二十条　部分连带债务人履行、抵销债务或者提存标的物的，其他债务人对债权人的债务在相应范围内消灭；该债务人可以依据前条规定向其他债务人追偿。\n部分连带债务人的债务被债权人免除的，在该连带债务人应当承担的份额范围内，其他债务人对债权人的债务消灭。\n部分连带债务人的债务与债权人的债权同归于一人的，在扣除该债务人应当承担的份额后，债权人对其他债务人的债权继续存在。\n债权人对部分连带债务人的给付受领迟延的，对其他连带债务人发生效力。\n第五百二十一条　连带债权人之间的份额难以确定的，视为份额相同。\n实际受领债权的连带债权人，应当按比例向其他连带债权人返还。\n连带债权参照适用本章连带债务的有关规定。\n第五百二十二条　当事人约定由债务人向第三人履行债务，债务人未向第三人履行债务或者履行债务不符合约定的，应当向债权人承担违约责任。\n法律规定或者当事人约定第三人可以直接请求债务人向其履行债务，第三人未在合理期限内明确拒绝，债务人未向第三人履行债务或者履行债务不符合约定的，第三人可以请求债务人承担违约责任；债务人对债权人的抗辩，可以向第三人主张。\n第五百二十三条　当事人约定由第三人向债权人履行债务，第三人不履行债务或者履行债务不符合约定的，债务人应当向债权人承担违约责任。\n第五百二十四条　债务人不履行债务，第三人对履行该债务具有合法利益的，第三人有权向债权人代为履行；但是，根据债务性质、按照当事人约定或者依照法律规定只能由债务人履行的除外。\n债权人接受第三人履行后，其对债务人的债权转让给第三人，但是债务人和第三人另有约定的除外。\n第五百二十五条　当事人互负债务，没有先后履行顺序的，应当同时履行。一方在对方履行之前有权拒绝其履行请求。一方在对方履行债务不符合约定时，有权拒绝其相应的履行请求', 748, '{\"level\": null, \"title\": null, \"chunk_index\": 59}', 'bge-large-zh-v1.5', '2026-09-25 17:05:01');
INSERT INTO `chunk` VALUES ('fc14bf66-e862-4670-a3ce-abfdab51e998', '821ce1fd-178d-4a7e-ab92-3deff1488ce2', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 82, '第三百五十五条　依法从事生产、运输、管理、使用国家管制的麻醉药品、精神药品的人员，违反国家规定，向吸食、注射毒品的人提供国家规定管制的能够使人形成瘾癖的麻醉药品、精神药品的，处三年以下有期徒刑或者拘役，并处罚金；情节严重的，处三年以上七年以下有期徒刑，并处罚金。向走私、贩卖毒品的犯罪分子或者以牟利为目的，向吸食、注射毒品的人提供国家规定管制的能够使人形成瘾癖的麻醉药品、精神药品的，依照本法第三百四十七条的规定定罪处罚。\n单位犯前款罪的，对单位判处罚金，并对其直接负责的主管人员和其他直接责任人员，依照前款的规定处罚。\n第三百五十五条之一　引诱、教唆、欺骗运动员使用兴奋剂参加国内、国际重大体育竞赛，或者明知运动员参加上述竞赛而向其提供兴奋剂，情节严重的，处三年以下有期徒刑或者拘役，并处罚金。\n组织、强迫运动员使用兴奋剂参加国内、国际重大体育竞赛的，依照前款的规定从重处罚。\n第三百五十六条　因走私、贩卖、运输、制造、非法持有毒品罪被判过刑，又犯本节规定之罪的，从重处罚。\n第三百五十七条　本法所称的毒品，是指鸦片、海洛因、甲基苯丙胺（冰毒）、吗啡、大麻、可卡因以及国家规定管制的其他能够使人形成瘾癖的麻醉药品和精神药品。\n毒品的数量以查证属实的走私、贩卖、运输、制造、非法持有毒品的数量计算，不以纯度折算。\n第八节　组织、强迫、引诱、容留、介绍卖淫罪\n第三百五十八条　组织、强迫他人卖淫的，处五年以上十年以下有期徒刑，并处罚金；情节严重的，处十年以上有期徒刑或者无期徒刑，并处罚金或者没收财产。\n组织、强迫未成年人卖淫的，依照前款的规定从重处罚。\n犯前两款罪，并有杀害、伤害、强奸、绑架等犯罪行为的，依照数罪并罚的规定处罚。\n为组织卖淫的人招募、运送人员或者有其他协助组织他人卖淫行为的，处五年以下有期徒刑，并处罚金；情节严重的，处五年以上十年以下有期徒刑，并处罚金', 786, '{\"level\": null, \"title\": null, \"chunk_index\": 82}', 'bge-large-zh-v1.5', '2026-09-25 17:04:56');
INSERT INTO `chunk` VALUES ('fd5d67bf-68f0-4fdc-b923-12bcfe7f728c', '821ce1fd-178d-4a7e-ab92-3deff1488ce2', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 15, '如果被害人因受强制、威吓无法告诉的，人民检察院和被害人的近亲属也可以告诉。\n第九十九条　本法所称以上、以下、以内，包括本数。\n第一百条　依法受过刑事处罚的人，在入伍、就业的时候，应当如实向有关单位报告自己曾受过刑事处罚，不得隐瞒。\n犯罪的时候不满十八周岁被判处五年有期徒刑以下刑罚的人，免除前款规定的报告义务。\n第一百零一条　本法总则适用于其他有刑罚规定的法律，但是其他法律有特别规定的除外。\n第二编　分　　则\n第一章　危害国家安全罪\n第一百零二条　勾结外国，危害中华人民共和国的主权、领土完整和安全的，处无期徒刑或者十年以上有期徒刑。\n与境外机构、组织、个人相勾结，犯前款罪的，依照前款的规定处罚。\n第一百零三条　组织、策划、实施分裂国家、破坏国家统一的，对首要分子或者罪行重大的，处无期徒刑或者十年以上有期徒刑；对积极参加的，处三年以上十年以下有期徒刑；对其他参加的，处三年以下有期徒刑、拘役、管制或者剥夺政治权利。\n煽动分裂国家、破坏国家统一的，处五年以下有期徒刑、拘役、管制或者剥夺政治权利；首要分子或者罪行重大的，处五年以上有期徒刑。\n第一百零四条　组织、策划、实施武装叛乱或者武装暴乱的，对首要分子或者罪行重大的，处无期徒刑或者十年以上有期徒刑；对积极参加的，处三年以上十年以下有期徒刑；对其他参加的，处三年以下有期徒刑、拘役、管制或者剥夺政治权利。\n策动、胁迫、勾引、收买国家机关工作人员、武装部队人员、人民警察、民兵进行武装叛乱或者武装暴乱的，依照前款的规定从重处罚。\n第一百零五条　组织、策划、实施颠覆国家政权、推翻社会主义制度的，对首要分子或者罪行重大的，处无期徒刑或者十年以上有期徒刑；对积极参加的，处三年以上十年以下有期徒刑；对其他参加的，处三年以下有期徒刑、拘役、管制或者剥夺政治权利', 755, '{\"level\": null, \"title\": null, \"chunk_index\": 15}', 'bge-large-zh-v1.5', '2026-09-25 17:04:56');
INSERT INTO `chunk` VALUES ('fda297d2-46a3-4e6c-a04e-b69786aa0ce7', '821ce1fd-178d-4a7e-ab92-3deff1488ce2', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 76, '第三百三十六条　未取得医生执业资格的人非法行医，情节严重的，处三年以下有期徒刑、拘役或者管制，并处或者单处罚金；严重损害就诊人身体健康的，处三年以上十年以下有期徒刑，并处罚金；造成就诊人死亡的，处十年以上有期徒刑，并处罚金。\n未取得医生执业资格的人擅自为他人进行节育复通手术、假节育手术、终止妊娠手术或者摘取宫内节育器，情节严重的，处三年以下有期徒刑、拘役或者管制，并处或者单处罚金；严重损害就诊人身体健康的，处三年以上十年以下有期徒刑，并处罚金；造成就诊人死亡的，处十年以上有期徒刑，并处罚金。\n第三百三十六条之一　将基因编辑、克隆的人类胚胎植入人体或者动物体内，或者将基因编辑、克隆的动物胚胎植入人体内，情节严重的，处三年以下有期徒刑或者拘役，并处罚金；情节特别严重的，处三年以上七年以下有期徒刑，并处罚金。\n第三百三十七条　违反有关动植物防疫、检疫的国家规定，引起重大动植物疫情的，或者有引起重大动植物疫情危险，情节严重的，处三年以下有期徒刑或者拘役，并处或者单处罚金。\n单位犯前款罪的，对单位判处罚金，并对其直接负责的主管人员和其他直接责任人员，依照前款的规定处罚', 486, '{\"level\": null, \"title\": null, \"chunk_index\": 76}', 'bge-large-zh-v1.5', '2026-09-25 17:04:56');
INSERT INTO `chunk` VALUES ('fda5e0a3-218d-4897-9267-6aabcd9107e6', '821ce1fd-178d-4a7e-ab92-3deff1488ce2', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 87, '犯第一款罪，有第三项规定情形被判处死刑缓期执行的，人民法院根据犯罪情节等情况可以同时决定在其死刑缓期执行二年期满依法减为无期徒刑后，终身监禁，不得减刑、假释。\n第三百八十四条　国家工作人员利用职务上的便利，挪用公款归个人使用，进行非法活动的，或者挪用公款数额较大、进行营利活动的，或者挪用公款数额较大、超过三个月未还的，是挪用公款罪，处五年以下有期徒刑或者拘役；情节严重的，处五年以上有期徒刑。挪用公款数额巨大不退还的，处十年以上有期徒刑或者无期徒刑。\n挪用用于救灾、抢险、防汛、优抚、扶贫、移民、救济款物归个人使用的，从重处罚。\n第三百八十五条　国家工作人员利用职务上的便利，索取他人财物的，或者非法收受他人财物，为他人谋取利益的，是受贿罪。\n国家工作人员在经济往来中，违反国家规定，收受各种名义的回扣、手续费，归个人所有的，以受贿论处。\n第三百八十六条　对犯受贿罪的，根据受贿所得数额及情节，依照本法第三百八十三条的规定处罚。索贿的从重处罚。\n第三百八十七条　国家机关、国有公司、企业、事业单位、人民团体，索取、非法收受他人财物，为他人谋取利益，情节严重的，对单位判处罚金，并对其直接负责的主管人员和其他直接责任人员，处五年以下有期徒刑或者拘役。\n前款所列单位，在经济往来中，在帐外暗中收受各种名义的回扣、手续费的，以受贿论，依照前款的规定处罚。\n第三百八十八条　国家工作人员利用本人职权或者地位形成的便利条件，通过其他国家工作人员职务上的行为，为请托人谋取不正当利益，索取请托人财物或者收受请托人财物的，以受贿论处', 660, '{\"level\": null, \"title\": null, \"chunk_index\": 87}', 'bge-large-zh-v1.5', '2026-09-25 17:04:56');
INSERT INTO `chunk` VALUES ('fdcec450-261e-48d9-ade1-dd6e93bf64c0', '821ce1fd-178d-4a7e-ab92-3deff1488ce2', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 39, '社会保障基金管理机构、住房公积金管理机构等公众资金管理机构，以及保险公司、保险资产管理公司、证券投资基金管理公司，违反国家规定运用资金的，对其直接负责的主管人员和其他直接责任人员，依照前款的规定处罚。\n第一百八十六条　银行或者其他金融机构的工作人员违反国家规定发放贷款，数额巨大或者造成重大损失的，处五年以下有期徒刑或者拘役，并处一万元以上十万元以下罚金；数额特别巨大或者造成特别重大损失的，处五年以上有期徒刑，并处二万元以上二十万元以下罚金。\n银行或者其他金融机构的工作人员违反国家规定，向关系人发放贷款的，依照前款的规定从重处罚。\n单位犯前两款罪的，对单位判处罚金，并对其直接负责的主管人员和其他直接责任人员，依照前两款的规定处罚。\n关系人的范围，依照《中华人民共和国商业银行法》和有关金融法规确定。\n第一百八十七条　银行或者其他金融机构的工作人员吸收客户资金不入帐，数额巨大或者造成重大损失的，处五年以下有期徒刑或者拘役，并处二万元以上二十万元以下罚金；数额特别巨大或者造成特别重大损失的，处五年以上有期徒刑，并处五万元以上五十万元以下罚金。\n单位犯前款罪的，对单位判处罚金，并对其直接负责的主管人员和其他直接责任人员，依照前款的规定处罚。\n第一百八十八条　银行或者其他金融机构的工作人员违反规定，为他人出具信用证或者其他保函、票据、存单、资信证明，情节严重的，处五年以下有期徒刑或者拘役；情节特别严重的，处五年以上有期徒刑。\n单位犯前款罪的，对单位判处罚金，并对其直接负责的主管人员和其他直接责任人员，依照前款的规定处罚。\n第一百八十九条　银行或者其他金融机构的工作人员在票据业务中，对违反票据法规定的票据予以承兑、付款或者保证，造成重大损失的，处五年以下有期徒刑或者拘役；造成特别重大损失的，处五年以上有期徒刑', 760, '{\"level\": null, \"title\": null, \"chunk_index\": 39}', 'bge-large-zh-v1.5', '2026-09-25 17:04:56');
INSERT INTO `chunk` VALUES ('fe0811f7-f0c8-4dae-8cec-fbae206be1da', '821ce1fd-178d-4a7e-ab92-3deff1488ce2', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 51, '倒卖车票、船票，情节严重的，处三年以下有期徒刑、拘役或者管制，并处或者单处票证价额一倍以上五倍以下罚金。\n第二百二十八条　以牟利为目的，违反土地管理法规，非法转让、倒卖土地使用权，情节严重的，处三年以下有期徒刑或者拘役，并处或者单处非法转让、倒卖土地使用权价额百分之五以上百分之二十以下罚金；情节特别严重的，处三年以上七年以下有期徒刑，并处非法转让、倒卖土地使用权价额百分之五以上百分之二十以下罚金。\n第二百二十九条　承担资产评估、验资、验证、会计、审计、法律服务、保荐、安全评价、环境影响评价、环境监测等职责的中介组织的人员故意提供虚假证明文件，情节严重的，处五年以下有期徒刑或者拘役，并处罚金；有下列情形之一的，处五年以上十年以下有期徒刑，并处罚金：\n（一）提供与证券发行相关的虚假的资产评估、会计、审计、法律服务、保荐等证明文件，情节特别严重的；\n（二）提供与重大资产交易相关的虚假的资产评估、会计、审计等证明文件，情节特别严重的；\n（三）在涉及公共安全的重大工程、项目中提供虚假的安全评价、环境影响评价等证明文件，致使公共财产、国家和人民利益遭受特别重大损失的。\n有前款行为，同时索取他人财物或者非法收受他人财物构成犯罪的，依照处罚较重的规定定罪处罚。\n第一款规定的人员，严重不负责任，出具的证明文件有重大失实，造成严重后果的，处三年以下有期徒刑或者拘役，并处或者单处罚金。\n第二百三十条　违反进出口商品检验法的规定，逃避商品检验，将必须经商检机构检验的进口商品未报经检验而擅自销售、使用，或者将必须经商检机构检验的出口商品未报经检验合格而擅自出口，情节严重的，处三年以下有期徒刑或者拘役，并处或者单处罚金。\n第二百三十一条　单位犯本节第二百二十一条至第二百三十条规定之罪的，对单位判处罚金，并对其直接负责的主管人员和其他直接责任人员，依照本节各该条的规定处罚', 784, '{\"level\": null, \"title\": null, \"chunk_index\": 51}', 'bge-large-zh-v1.5', '2026-09-25 17:04:56');
INSERT INTO `chunk` VALUES ('fff0d84a-d525-498c-bfb9-e46d6335119e', 'b25ce095-dfba-4403-acf8-c58eb456ca4c', 'a2bc8103-1010-4a5b-b187-f2e749cbcaee', 31, '第二百七十五条　建筑区划内，规划用于停放汽车的车位、车库的归属，由当事人通过出售、附赠或者出租等方式约定。\n占用业主共有的道路或者其他场地用于停放汽车的车位，属于业主共有。\n第二百七十六条　建筑区划内，规划用于停放汽车的车位、车库应当首先满足业主的需要。\n第二百七十七条　业主可以设立业主大会，选举业主委员会。业主大会、业主委员会成立的具体条件和程序，依照法律、法规的规定。\n地方人民政府有关部门、居民委员会应当对设立业主大会和选举业主委员会给予指导和协助。\n第二百七十八条　下列事项由业主共同决定：\n（一）制定和修改业主大会议事规则；\n（二）制定和修改管理规约；\n（三）选举业主委员会或者更换业主委员会成员；\n（四）选聘和解聘物业服务企业或者其他管理人；\n（五）使用建筑物及其附属设施的维修资金；\n（六）筹集建筑物及其附属设施的维修资金；\n（七）改建、重建建筑物及其附属设施；\n（八）改变共有部分的用途或者利用共有部分从事经营活动；\n（九）有关共有和共同管理权利的其他重大事项。\n业主共同决定事项，应当由专有部分面积占比三分之二以上的业主且人数占比三分之二以上的业主参与表决。决定前款第六项至第八项规定的事项，应当经参与表决专有部分面积四分之三以上的业主且参与表决人数四分之三以上的业主同意。决定前款其他事项，应当经参与表决专有部分面积过半数的业主且参与表决人数过半数的业主同意。\n第二百七十九条　业主不得违反法律、法规以及管理规约，将住宅改变为经营性用房。业主将住宅改变为经营性用房的，除遵守法律、法规以及管理规约外，应当经有利害关系的业主一致同意。\n第二百八十条　业主大会或者业主委员会的决定，对业主具有法律约束力。\n业主大会或者业主委员会作出的决定侵害业主合法权益的，受侵害的业主可以请求人民法院予以撤销。\n第二百八十一条　建筑物及其附属设施的维修资金，属于业主共有', 787, '{\"level\": null, \"title\": null, \"chunk_index\": 31}', 'bge-large-zh-v1.5', '2026-09-25 17:05:01');
