INSERT INTO `ml_dataset` VALUES ('cd3cfbed-5cd9-43b3-953d-9d969dc77f09', '法律训练集-100', '法律训练集-100条数据', 'train', 'text_gen', 'sft', 'oss', 'upload', '2026-09-25 20:13:44', '2026-09-25 20:13:45');
INSERT INTO `ml_dataset_version` VALUES ('d4097421-daa1-4b01-878b-a7eb4fe5f5af', 'cd3cfbed-5cd9-43b3-953d-9d969dc77f09', 1, 1, 100, 'done', 'published', 'file-e1964925f059', 'data/ml/datasets/cd3cfbed-5cd9-43b3-953d-9d969dc77f09/v1/法律数据集100.jsonl', '{\"query\": \"民法调整平等主体的自然人、法人和非法人组织之间的什么关系？\", \"positive\": \"人身关系和财产关系\", \"negative\": \"行政关系和管理关系\"}\r\n{\"query\": \"民事主体从事民事活动应当遵循什么原则按照自己的意思设立变更终止民事法律关系？\", \"positive\": \"自愿原则\", \"negative\": \"强制原则\"}\r\n{\"query\": \"自然人的民事权利能力从何时开始？\", \"positive\": \"从出生时起到死亡时止\", \"negative\": \"从年满十八周岁起到死亡时止\"}\r\n{\"query\": \"不满八周岁的未成年人属于哪类民事行为能力人？\", \"positive\": \"无民事行为能力人\", \"negative\": \"限制民事行为能力人\"}\r\n{\"query\": \"八周岁以上的未成年人属于哪类民事行为能力人？\", \"positive\": \"限制民事行为能力人\", \"negative\": \"无民事行为能力人\"}\r\n{\"query\": \"父母对未成年子女负有哪些义务？\", \"positive\": \"抚养、教育和保护的义务\", \"negative\": \"赡养、扶助和保护的义务\"}\r\n{\"query\": \"成年子女对父母负有哪些义务？\", \"positive\": \"赡养、扶助和保护的义务\", \"negative\": \"抚养、教育和保护的义务\"}\r\n{\"query\": \"向人民法院请求保护民事权利的诉讼时效期间一般为多久？\", \"positive\": \"三年\", \"negative\": \"五年\"}\r\n{\"query\": \"民事诉讼时效期间自何时起计算？\", \"positive\": \"自权利人知道或者应当知道权利受到损害以及义务人之日起计算\", \"negative\": \"自权利受到损害之日起计算\"}\r\n{\"query\": \"因不可抗力不能履行民事义务的，是否承担民事责任？\", \"positive\": \"不承担民事责任\", \"negative\": \"应当承担民事责任\"}\r\n{\"query\": \"因正当防卫造成损害的，是否承担民事责任？\", \"positive\": \"不承担民事责任\", \"negative\": \"应当承担民事责任\"}\r\n{\"query\": \"因自愿实施紧急救助行为造成受助人损害的，救助人是否承担民事责任？\", \"positive\": \"不承担民事责任\", \"negative\": \"应当承担民事责任\"}\r\n{\"query\": \"无处分权人将不动产或者动产转让给受让人的，所有权人是否有权追回？\", \"positive\": \"有权追回\", \"negative\": \"无权追回\"}\r\n{\"query\": \"善意取得需要满足哪些条件？\", \"positive\": \"受让人受让该不动产或者动产时是善意、以合理的价格转让、转让的不动产或者动产依照法律规定应当登记的已经登记不需要登记的已经交付给受让人\", \"negative\": \"受让人受让该不动产或者动产时是善意、以象征性的价格转让、转让的不动产或者动产未交付\"}\r\n{\"query\": \"拾得遗失物，拾得人应当如何处理？\", \"positive\": \"应当返还权利人，及时通知权利人领取，或者送交公安等有关部门\", \"negative\": \"可以自行占有，无需通知权利人\"}\r\n{\"query\": \"遗失物自发布招领公告之日起多久无人认领的归国家所有？\", \"positive\": \"一年内\", \"negative\": \"两年内\"}\r\n{\"query\": \"不动产的相邻权利人处理相邻关系应当遵循什么原则？\", \"positive\": \"有利生产、方便生活、团结互助、公平合理的原则\", \"negative\": \"效率优先、兼顾公平的原则\"}\r\n{\"query\": \"建设用地使用权可以在土地的哪些空间分别设立？\", \"positive\": \"地表、地上或者地下\", \"negative\": \"仅限地表\"}\r\n{\"query\": \"住宅建设用地使用权期限届满的，如何处理？\", \"positive\": \"自动续期\", \"negative\": \"需要重新申请\"}\r\n{\"query\": \"居住权自何时设立？\", \"positive\": \"自登记时设立\", \"negative\": \"自合同生效时设立\"}\r\n{\"query\": \"居住权是否可以转让、继承？\", \"positive\": \"不得转让、继承\", \"negative\": \"可以转让、继承\"}\r\n{\"query\": \"担保物权的担保范围包括哪些？\", \"positive\": \"主债权及其利息、违约金、损害赔偿金、保管担保财产和实现担保物权的费用\", \"negative\": \"仅包括主债权\"}\r\n{\"query\": \"同一动产上已经设立抵押权或者质权，该动产又被留置的，哪个权利优先受偿？\", \"positive\": \"留置权人优先受偿\", \"negative\": \"抵押权人优先受偿\"}\r\n{\"query\": \"当事人订立合同可以采用哪些形式？\", \"positive\": \"书面形式、口头形式或者其他形式\", \"negative\": \"仅限书面形式\"}\r\n{\"query\": \"要约邀请包括哪些常见形式？\", \"positive\": \"拍卖公告、招标公告、招股说明书、债券募集办法、基金招募说明书、商业广告和宣传、寄送的价目表等\", \"negative\": \"投标文件、中标通知书\"}\r\n{\"query\": \"承诺生效时合同是否成立？\", \"positive\": \"承诺生效时合同成立\", \"negative\": \"要约生效时合同成立\"}\r\n{\"query\": \"依法成立的合同自何时生效？\", \"positive\": \"自成立时生效\", \"negative\": \"自履行时生效\"}\r\n{\"query\": \"当事人一方不履行合同义务或者履行合同义务不符合约定的，应当承担什么责任？\", \"positive\": \"继续履行、采取补救措施或者赔偿损失等违约责任\", \"negative\": \"仅承担赔偿责任\"}\r\n{\"query\": \"因国际货物买卖合同和技术进出口合同争议提起诉讼或者申请仲裁的时效期间为多久？\", \"positive\": \"四年\", \"negative\": \"三年\"}\r\n{\"query\": \"通过互联网等信息网络订立的电子合同的标的为交付商品并采用快递物流方式交付的，交付时间如何确定？\", \"positive\": \"收货人的签收时间为交付时间\", \"negative\": \"发货人的发货时间为交付时间\"}\r\n{\"query\": \"出卖人按照约定未交付有关标的物的单证和资料的，是否影响标的物毁损、灭失风险的转移？\", \"positive\": \"不影响\", \"negative\": \"影响\"}\r\n{\"query\": \"试用买卖的买受人在试用期内已经支付部分价款或者对标的物实施出卖、出租、设立担保物权等行为的，视为？\", \"positive\": \"同意购买\", \"negative\": \"拒绝购买\"}\r\n{\"query\": \"赠与人在赠与财产的权利转移之前是否可以撤销赠与？\", \"positive\": \"可以撤销赠与\", \"negative\": \"不得撤销赠与\"}\r\n{\"query\": \"自然人之间的借款合同，自何时成立？\", \"positive\": \"自贷款人提供借款时成立\", \"negative\": \"自合同签订时成立\"}\r\n{\"query\": \"一般保证的保证人在主合同纠纷未经审判或者仲裁，并就债务人财产依法强制执行仍不能履行债务前，有权拒绝向债权人承担保证责任吗？\", \"positive\": \"有权拒绝\", \"negative\": \"无权拒绝\"}\r\n{\"query\": \"租赁期限不得超过多少年？\", \"positive\": \"二十年\", \"negative\": \"三十年\"}\r\n{\"query\": \"出租人出卖租赁房屋的，应当在出卖之前的合理期限内通知承租人，承租人享有什么权利？\", \"positive\": \"以同等条件优先购买的权利\", \"negative\": \"以优惠条件购买的权利\"}\r\n{\"query\": \"物业服务人不得采取什么方式催交物业费？\", \"positive\": \"停止供电、供水、供热、供燃气等方式\", \"negative\": \"提起诉讼或者申请仲裁\"}\r\n{\"query\": \"中介人未促成合同成立的，是否可以请求支付报酬？\", \"positive\": \"不得请求支付报酬\", \"negative\": \"可以请求支付报酬\"}\r\n{\"query\": \"合伙人对合伙债务承担什么责任？\", \"positive\": \"连带责任\", \"negative\": \"按份责任\"}\r\n{\"query\": \"管理人没有法定的或者约定的义务，为避免他人利益受损失而管理他人事务的，可以请求受益人偿还什么？\", \"positive\": \"因管理事务而支出的必要费用\", \"negative\": \"因管理事务而获得的报酬\"}\r\n{\"query\": \"得利人没有法律根据取得不当利益的，受损失的人可以请求得利人返还什么？\", \"positive\": \"取得的利益\", \"negative\": \"双倍赔偿\"}\r\n{\"query\": \"人格权是否可以放弃、转让或者继承？\", \"positive\": \"不得放弃、转让或者继承\", \"negative\": \"可以放弃、转让或者继承\"}\r\n{\"query\": \"自然人享有生命权，自然人的什么受法律保护？\", \"positive\": \"生命安全和生命尊严\", \"negative\": \"财产安全和财产尊严\"}\r\n{\"query\": \"违背他人意愿，以言语、文字、图像、肢体行为等方式对他人实施性骚扰的，受害人有权依法请求行为人承担什么责任？\", \"positive\": \"民事责任\", \"negative\": \"行政责任\"}\r\n{\"query\": \"自然人的个人信息受法律保护，处理个人信息应当遵循什么原则？\", \"positive\": \"合法、正当、必要原则\", \"negative\": \"效率、便捷、经济原则\"}\r\n{\"query\": \"国家机关、承担行政职能的法定机构及其工作人员对于履行职责过程中知悉的自然人的隐私和个人信息，应当如何处理？\", \"positive\": \"予以保密，不得泄露或者向他人非法提供\", \"negative\": \"可以随意公开使用\"}\r\n{\"query\": \"结婚年龄，男不得早于多少周岁，女不得早于多少周岁？\", \"positive\": \"男不得早于二十二周岁，女不得早于二十周岁\", \"negative\": \"男不得早于二十周岁，女不得早于十八周岁\"}\r\n{\"query\": \"直系血亲或者三代以内的旁系血亲是否可以结婚？\", \"positive\": \"禁止结婚\", \"negative\": \"可以结婚\"}\r\n{\"query\": \"夫妻在婚姻关系存续期间所得的哪些财产为夫妻的共同财产？\", \"positive\": \"工资、奖金、劳务报酬，生产、经营、投资的收益，知识产权的收益，继承或者受赠的财产（遗嘱或者赠与合同中确定只归一方的财产除外），其他应当归共同所有的财产\", \"negative\": \"一方的婚前财产，一方因受到人身损害获得的赔偿或者补偿，遗嘱或者赠与合同中确定只归一方的财产，一方专用的生活用品\"}\r\n{\"query\": \"离婚时，不满两周岁的子女，以由谁直接抚养为原则？\", \"positive\": \"以由母亲直接抚养为原则\", \"negative\": \"以由父亲直接抚养为原则\"}\r\n{\"query\": \"离婚后，不直接抚养子女的父或者母，有什么权利？\", \"positive\": \"探望子女的权利\", \"negative\": \"拒绝支付抚养费的权利\"}\r\n{\"query\": \"收养人应当同时具备哪些条件？\", \"positive\": \"无子女或者只有一名子女，有抚养、教育和保护被收养人的能力，未患有在医学上认为不应当收养子女的疾病，无不利于被收养人健康成长的违法犯罪记录，年满三十周岁\", \"negative\": \"无子女，有抚养能力，年满二十五周岁\"}\r\n{\"query\": \"收养关系自何时成立？\", \"positive\": \"自登记之日起成立\", \"negative\": \"自签订收养协议之日起成立\"}\r\n{\"query\": \"继承从何时开始？\", \"positive\": \"从被继承人死亡时开始\", \"negative\": \"从遗产分割时开始\"}\r\n{\"query\": \"法定继承的第一顺序继承人包括哪些？\", \"positive\": \"配偶、子女、父母\", \"negative\": \"兄弟姐妹、祖父母、外祖父母\"}\r\n{\"query\": \"丧偶儿媳对公婆，丧偶女婿对岳父母，尽了主要赡养义务的，作为第几顺序继承人？\", \"positive\": \"第一顺序继承人\", \"negative\": \"第二顺序继承人\"}\r\n{\"query\": \"遗嘱应当为哪些人保留必要的遗产份额？\", \"positive\": \"缺乏劳动能力又没有生活来源的继承人\", \"negative\": \"所有法定继承人\"}\r\n{\"query\": \"无民事行为能力人或者限制民事行为能力人所立的遗嘱是否有效？\", \"positive\": \"无效\", \"negative\": \"有效\"}\r\n{\"query\": \"行为人因过错侵害他人民事权益造成损害的，应当承担什么责任？\", \"positive\": \"侵权责任\", \"negative\": \"违约责任\"}\r\n{\"query\": \"侵害他人造成人身损害的，应当赔偿哪些费用？\", \"positive\": \"医疗费、护理费、交通费、营养费、住院伙食补助费等为治疗和康复支出的合理费用，以及因误工减少的收入\", \"negative\": \"仅赔偿医疗费\"}\r\n{\"query\": \"侵害自然人人身权益造成严重精神损害的，被侵权人是否有权请求精神损害赔偿？\", \"positive\": \"有权请求精神损害赔偿\", \"negative\": \"无权请求精神损害赔偿\"}\r\n{\"query\": \"二人以上共同实施侵权行为，造成他人损害的，应当承担什么责任？\", \"positive\": \"连带责任\", \"negative\": \"按份责任\"}\r\n{\"query\": \"无民事行为能力人、限制民事行为能力人造成他人损害的，由谁承担侵权责任？\", \"positive\": \"由监护人承担侵权责任\", \"negative\": \"由本人承担侵权责任\"}\r\n{\"query\": \"用人单位的工作人员因执行工作任务造成他人损害的，由谁承担侵权责任？\", \"positive\": \"由用人单位承担侵权责任\", \"negative\": \"由工作人员本人承担侵权责任\"}\r\n{\"query\": \"网络用户利用网络服务实施侵权行为的，权利人有权通知网络服务提供者采取什么必要措施？\", \"positive\": \"删除、屏蔽、断开链接等必要措施\", \"negative\": \"罚款、停机、销号等措施\"}\r\n{\"query\": \"宾馆、商场、银行、车站、机场、体育场馆、娱乐场所等经营场所、公共场所的经营者、管理者或者群众性活动的组织者，未尽到安全保障义务，造成他人损害的，应当承担什么责任？\", \"positive\": \"侵权责任\", \"negative\": \"违约责任\"}\r\n{\"query\": \"因产品存在缺陷造成他人损害的，生产者应当承担什么责任？\", \"positive\": \"侵权责任\", \"negative\": \"违约责任\"}\r\n{\"query\": \"因污染环境、破坏生态发生纠纷，行为人应当就什么承担举证责任？\", \"positive\": \"法律规定的不承担责任或者减轻责任的情形及其行为与损害之间不存在因果关系\", \"negative\": \"受害人的过错\"}\r\n{\"query\": \"从事高度危险作业造成他人损害的，应当承担什么责任？\", \"positive\": \"侵权责任\", \"negative\": \"违约责任\"}\r\n{\"query\": \"饲养的动物造成他人损害的，动物饲养人或者管理人应当承担什么责任？\", \"positive\": \"侵权责任\", \"negative\": \"违约责任\"}\r\n{\"query\": \"禁止从建筑物中抛掷物品，从建筑物中抛掷物品或者从建筑物上坠落的物品造成他人损害的，由谁依法承担侵权责任？\", \"positive\": \"由侵权人依法承担侵权责任\", \"negative\": \"由物业公司承担侵权责任\"}\r\n{\"query\": \"中华人民共和国的一切权力属于谁？\", \"positive\": \"人民\", \"negative\": \"政府\"}\r\n{\"query\": \"人民行使国家权力的机关是什么？\", \"positive\": \"全国人民代表大会和地方各级人民代表大会\", \"negative\": \"国务院和地方各级人民政府\"}\r\n{\"query\": \"中华人民共和国的国家机构实行什么原则？\", \"positive\": \"民主集中制的原则\", \"negative\": \"三权分立的原则\"}\r\n{\"query\": \"中华人民共和国实行依法治国，建设什么国家？\", \"positive\": \"社会主义法治国家\", \"negative\": \"社会主义法制国家\"}\r\n{\"query\": \"任何组织或者个人都不得有超越什么的特权？\", \"positive\": \"宪法和法律\", \"negative\": \"法规和规章\"}\r\n{\"query\": \"中华人民共和国的社会主义经济制度的基础是什么？\", \"positive\": \"生产资料的社会主义公有制\", \"negative\": \"生产资料的私有制\"}\r\n{\"query\": \"国家在社会主义初级阶段，坚持什么基本经济制度？\", \"positive\": \"公有制为主体、多种所有制经济共同发展的基本经济制度\", \"negative\": \"私有制为主体、多种所有制经济共同发展的基本经济制度\"}\r\n{\"query\": \"国有经济，即社会主义全民所有制经济，是国民经济中的什么力量？\", \"positive\": \"主导力量\", \"negative\": \"基础力量\"}\r\n{\"query\": \"矿藏、水流、森林、山岭、草原、荒地、滩涂等自然资源，都属于谁所有？\", \"positive\": \"国家所有，即全民所有\", \"negative\": \"集体所有\"}\r\n{\"query\": \"城市的土地属于谁所有？\", \"positive\": \"国家所有\", \"negative\": \"集体所有\"}\r\n{\"query\": \"公民的合法的私有财产是否受法律保护？\", \"positive\": \"不受侵犯\", \"negative\": \"可以随意征收\"}\r\n{\"query\": \"国家为了公共利益的需要，可以依照法律规定对公民的私有财产实行征收或者征用并给予什么？\", \"positive\": \"补偿\", \"negative\": \"赔偿\"}\r\n{\"query\": \"中华人民共和国公民在法律面前一律平等，国家尊重和保障什么？\", \"positive\": \"人权\", \"negative\": \"特权\"}\r\n{\"query\": \"中华人民共和国年满多少周岁的公民，都有选举权和被选举权？\", \"positive\": \"十八周岁\", \"negative\": \"二十周岁\"}\r\n{\"query\": \"中华人民共和国公民有言论、出版、集会、结社、游行、示威的什么？\", \"positive\": \"自由\", \"negative\": \"权利\"}\r\n{\"query\": \"中华人民共和国公民的人身自由不受侵犯，任何公民，非经什么批准或者决定或者人民法院决定，并由公安机关执行，不受逮捕？\", \"positive\": \"人民检察院批准或者决定\", \"negative\": \"公安机关批准或者决定\"}\r\n{\"query\": \"中华人民共和国公民的住宅不受侵犯，禁止非法搜查或者非法侵入公民的住宅吗？\", \"positive\": \"禁止\", \"negative\": \"允许\"}\r\n{\"query\": \"中华人民共和国公民的通信自由和通信秘密受法律的保护，除因国家安全或者追查刑事犯罪的需要，由谁依照法律规定的程序对通信进行检查外，任何组织或者个人不得以任何理由侵犯公民的通信自由和通信秘密？\", \"positive\": \"公安机关或者检察机关\", \"negative\": \"人民法院\"}\r\n{\"query\": \"中华人民共和国公民对于任何国家机关和国家工作人员，有提出什么的权利？\", \"positive\": \"批评和建议的权利\", \"negative\": \"控告和检举的权利\"}\r\n{\"query\": \"中华人民共和国公民在行使自由和权利的时候，不得损害什么？\", \"positive\": \"国家的、社会的、集体的利益和其他公民的合法的自由和权利\", \"negative\": \"个人的、家庭的、小团体的利益\"}\r\n{\"query\": \"中华人民共和国公民有维护国家统一和全国各民族团结的什么？\", \"positive\": \"义务\", \"negative\": \"权利\"}\r\n{\"query\": \"保卫祖国、抵抗侵略是中华人民共和国每一个公民的什么职责？\", \"positive\": \"神圣职责\", \"negative\": \"光荣义务\"}\r\n{\"query\": \"中华人民共和国全国人民代表大会是最高国家权力机关，它的常设机关是什么？\", \"positive\": \"全国人民代表大会常务委员会\", \"negative\": \"全国人民代表大会主席团\"}\r\n{\"query\": \"全国人民代表大会和全国人民代表大会常务委员会行使什么权？\", \"positive\": \"国家立法权\", \"negative\": \"国家行政权\"}\r\n{\"query\": \"全国人民代表大会每届任期几年？\", \"positive\": \"五年\", \"negative\": \"三年\"}\r\n{\"query\": \"全国人民代表大会会议每年举行几次？\", \"positive\": \"一次\", \"negative\": \"两次\"}\r\n{\"query\": \"中华人民共和国主席、副主席由谁选举？\", \"positive\": \"全国人民代表大会\", \"negative\": \"全国人民代表大会常务委员会\"}\r\n{\"query\": \"有选举权和被选举权的年满多少周岁的中华人民共和国公民可以被选为中华人民共和国主席、副主席？\", \"positive\": \"四十五周岁\", \"negative\": \"五十周岁\"}', '2026-09-25 20:13:45');
INSERT INTO `ml_eval_dimension` VALUES ('0542e167-0318-4fbf-93c6-a972c17bf9b8', '混合检索@5', '向量+全文融合检索的问答准确率', '2026-09-25 16:54:41', 'retrieval', '{\"top_k\": 5, \"metric\": \"hybrid_qa_accuracy\"}');
INSERT INTO `ml_eval_dimension` VALUES ('276d90ed-d8e8-435c-81e4-019ec049a866', '向量检索@5', '仅用向量检索的问答准确率', '2026-09-25 16:54:35', 'retrieval', '{\"top_k\": 5, \"metric\": \"vector_qa_accuracy\"}');
INSERT INTO `ml_eval_dimension` VALUES ('2987f665-c88d-4219-8811-b266edc5425e', '答案完整性', '评估回答是否覆盖问题所需的所有必要信息，1~5分，得分越高表示越完整，通过阈值3', '2026-09-25 17:01:58', 'llm_numeric', '{\"prompt\": \"你是完整性评审专家。请从问题与参考答案中归纳必要信息点，逐点核查回答的覆盖情况，并给出1-5分：5分=全面覆盖无遗漏；4分=覆盖绝大部分，缺次要细节；3分=覆盖核心，缺若干重要细节；2分=遗漏多个关键点；1分=几乎未覆盖核心信息。仅评估完整性，不评判正确性。\\n\\n问题：${query}\\n参考答案：${positive}\\n生成回答：${output}\\n\\n输出格式：\\n分步推理：[列出已覆盖与遗漏的要点]\\n评分：[1-5的整数]\", \"template\": \"completeness\", \"score_max\": 5, \"score_min\": 0, \"threshold\": 3, \"judge_model\": \"\"}');
INSERT INTO `ml_eval_dimension` VALUES ('358beec8-fad9-44f9-86b2-605a2550bc38', '重排序检索@5', '混合检索+交叉编码器重排序的问答准确率', '2026-09-25 16:54:45', 'retrieval', '{\"top_k\": 5, \"metric\": \"rerank_qa_accuracy\"}');
INSERT INTO `ml_eval_dimension` VALUES ('595566d5-52cc-435e-8b9a-2ab1994eac3c', '问答准确率', '问答准确率', '2026-09-25 17:01:34', 'llm_classify', '{\"labels\": {\"Fail\": \"Fail\", \"Pass\": \"Pass\"}, \"prompt\": \"你是对话评估专家。请根据标准对助理的最终回答进行评估，判断为[[Pass]]或[[Fail]]。\\n\\n评估标准：\\n1.正确性：信息准确，无事实错误\\n2.完整性：涵盖所有必要信息\\n3.流畅性：句子通顺，段落连贯\\n4.逻辑性：推理严密，无逻辑漏洞\\n5.相关性：紧扣主题，无偏离\\n6.安全性：无敏感信息或不当内容\\n\\n问题：${query}\\n参考答案：${positive}\\n模型回答：${output}\\n\\n输出格式：\\n分步推理：[逐条说明各标准满足情况]\\n最终结果：[[Pass]]或[[Fail]]\", \"template\": \"standard\", \"judge_model\": \"be4cd2b5-bec2-4921-b491-409d9f464898\"}');
INSERT INTO `ml_eval_dimension` VALUES ('612772f7-e52c-4466-81fe-89c618324486', '平均倒数排名@5', '第一个正确答案排名的倒数平均值', '2026-09-25 16:52:52', 'retrieval', '{\"top_k\": 5, \"metric\": \"mrr\"}');
INSERT INTO `ml_eval_dimension` VALUES ('86ce953c-ddb8-4335-bd12-9bc3924077a2', '召回率@1', '正确答案是否排在前1位', '2026-09-25 16:52:16', 'retrieval', '{\"metric\": \"recall_at_5\", \"recall_k\": 1}');
INSERT INTO `ml_eval_dimension` VALUES ('a4352c71-0c9b-4e1e-9c11-4f9b6d1400da', '幻觉率', '评估回答是否存在事实错误或幻觉，1~5分，得分越高表示幻觉越少，通过阈值4', '2026-09-25 17:01:46', 'llm_numeric', '{\"prompt\": \"你是事实核查专家。请将生成回答与参考答案逐句比对，找出事实错误、虚构信息或与参考相悖的表述，并给出1-5分：5分=完全准确无幻觉；4分=基本准确，仅轻微不精确；3分=部分准确，存在若干事实偏差；2分=较多事实错误或明显幻觉；1分=大量错误，核心事实与参考答案相悖。仅以参考答案为依据，不引入外部知识。\\n\\n问题：${query}\\n参考答案：${positive}\\n生成回答：${output}\\n\\n输出格式：\\n分步推理：[说明发现的幻觉点及依据]\\n评分：[1-5的整数]\", \"template\": \"hallucination\", \"score_max\": 5, \"score_min\": 0, \"threshold\": 4, \"judge_model\": \"be4cd2b5-bec2-4921-b491-409d9f464898\"}');
INSERT INTO `ml_eval_dimension` VALUES ('aba13682-6e8b-4fbb-9ec3-3a815ffc226e', '全文检索@5', '仅用全文检索的问答准确率', '2026-09-25 16:54:38', 'retrieval', '{\"top_k\": 5, \"metric\": \"fulltext_qa_accuracy\"}');
INSERT INTO `ml_eval_dimension` VALUES ('b43d1d7a-399d-48ea-985e-9c1e59999d00', '召回率@5', '正确答案是否排在前5位', '2026-09-25 16:52:37', 'retrieval', '{\"metric\": \"recall_at_5\", \"recall_k\": 5}');
INSERT INTO `ml_eval_dimension` VALUES ('d5180900-6539-4853-b251-ec9450e3e225', '答案相关性', '评估回答与问题的相关程度，1~5分，得分越高表示越切题，通过阈值3', '2026-09-25 17:01:53', 'llm_numeric', '{\"prompt\": \"你是相关性评审专家。请判断回答在多大程度上紧扣用户问题，识别跑题、冗余或无关内容，并给出1-5分：5分=完全切题；4分=大部分切题，少量无关；3分=基本切题，部分偏离；2分=明显偏离，少量相关；1分=完全不切题。仅评估相关性，不评判正确性。\\n\\n问题：${query}\\n参考答案：${positive}\\n生成回答：${output}\\n\\n输出格式：\\n分步推理：[说明回答与问题的关联情况]\\n评分：[1-5的整数]\", \"template\": \"relevance\", \"score_max\": 5, \"score_min\": 0, \"threshold\": 3, \"judge_model\": \"\"}');
INSERT INTO `ml_eval_dimension` VALUES ('f32c0923-227c-40e7-8cc1-6916106cfea1', '召回率@10', '正确答案是否排在前10位', '2026-09-25 16:52:45', 'retrieval', '{\"metric\": \"recall_at_5\", \"recall_k\": 10}');
